package gps;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;

/**
 * Microbenchmarks for the water-pin hot paths: the wet-endpoint flood a water target runs per
 * generation, and the sea-track builder the overlay schedules per sailing leg. Dev-only (jmh
 * source set, -Pjmh) — never ships, never counts toward the hub review surface.
 *
 * Each case CYCLES through several inputs so the production single-entry / LRU caches miss on
 * every call — these measure the compute, not the cache.
 *
 * Run:
 *   ./gradlew -Pjmh jmh --args='SailingSea -f 1 -wi 3 -i 5'
 * Allocation profile (B/op — the metric that caught the boxed-queue churn):
 *   ./gradlew -Pjmh jmh --args='SailingSea -f 1 -wi 3 -i 5 -prof gc'
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 2, time = 2)
@Measurement(iterations = 3, time = 2)
@Fork(1)
public class SailingSeaBenchmark
{
	/** Coastal pins: endpoints settle fast, small flood. */
	private static final int[][] COASTAL = {{2692, 3142}, {3051, 2645}, {2929, 3138}};
	/** Mid-ocean pins: the flood must reach 12 coastal endpoints — the worst case. */
	private static final int[][] MID_OCEAN = {{2894, 2637}, {2404, 2580}, {3200, 2700}};

	private final List<long[]> legs = new ArrayList<>();
	private int coastalAt;
	private int oceanAt;
	private int legAt;

	@Setup
	public void setup()
	{
		// Warm the resource load out of the measurement.
		SailingSea.isSailable(WorldPointUtil.packWorldPoint(2894, 2637, 0));
		// 16+ distinct static-row legs (> the 8-entry LRU) so every seaPath call computes.
		try (Scanner scanner = new Scanner(
			SailingSea.class.getResourceAsStream("/transports/sailing.tsv"), "UTF-8"))
		{
			while (scanner.hasNextLine() && legs.size() < 16)
			{
				String line = scanner.nextLine();
				if (line.startsWith("#") || line.isBlank())
				{
					continue;
				}
				String[] fields = line.split("\t");
				String[] origin = fields[0].split(" ");
				String[] destination = fields[1].split(" ");
				legs.add(new long[]{
					WorldPointUtil.packWorldPoint(
						Integer.parseInt(origin[0]), Integer.parseInt(origin[1]), 0),
					WorldPointUtil.packWorldPoint(
						Integer.parseInt(destination[0]), Integer.parseInt(destination[1]), 0)});
			}
		}
	}

	@Benchmark
	public int[] wetFloodCoastal()
	{
		int[] pin = COASTAL[coastalAt++ % COASTAL.length];
		return SailingSea.seaDistances(WorldPointUtil.packWorldPoint(pin[0], pin[1], 0));
	}

	@Benchmark
	public int[] wetFloodMidOcean()
	{
		int[] pin = MID_OCEAN[oceanAt++ % MID_OCEAN.length];
		return SailingSea.seaDistances(WorldPointUtil.packWorldPoint(pin[0], pin[1], 0));
	}

	@Benchmark
	public int[] seaTrackLeg()
	{
		long[] leg = legs.get(legAt++ % legs.size());
		return SailingSea.seaPathBlocking((int) leg[0], (int) leg[1]);
	}
}

package gps.pathfinder;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;
import gps.TeleportMethod;

/**
 * Microbenchmark for the method-availability computation: the work done once per generation on the
 * client thread ({@link PathfinderConfig#refresh}: snapshot game state into the full usable-transport
 * lists and method catalog) and once per search off-thread ({@link
 * PathfinderConfig#rebuildAvailabilityWithExclusions}: re-derive the usable lists for an exclusion
 * set from the base lists, no game-state reads).
 * <p>
 * The rebuild is measured WITH an exclusion, alternating between two catalog methods: with no
 * exclusions and no extras the rebuild hands back the base lists untouched (the first search's
 * fast path), which is a no-op worth nothing on a chart. Every chain iteration after the first
 * excludes something, so the filtered rebuild is the per-search cost.
 * <p>
 * Run: {@code ./gradlew -Pjmh jmh --args='AvailabilityBenchmark'}
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class AvailabilityBenchmark
{
	private PathfinderConfig config;
	private List<Set<TeleportMethod>> exclusions;
	private int next;

	@Setup(Level.Trial)
	public void setup()
	{
		config = BenchScenarios.everythingConfig();
		List<TeleportMethod> catalog = new ArrayList<>(config.getMethodCatalog());
		if (catalog.size() < 2)
		{
			throw new IllegalStateException("the catalog must offer two methods to exclude");
		}
		exclusions = List.of(Set.of(catalog.get(0)), Set.of(catalog.get(1)));
	}

	/** The per-generation client-thread refresh: rebuild the full availability from game state. */
	@Benchmark
	public int refresh()
	{
		config.refresh();
		return config.getUsableTeleports(false).length;
	}

	/** The per-search off-thread rebuild from the base lists, with one method excluded. */
	@Benchmark
	public int rebuildWithExclusion()
	{
		config.rebuildAvailabilityWithExclusions(exclusions.get(next++ & 1));
		return config.getUsableTeleports(false).length;
	}
}

package gps.pathfinder;

import java.lang.reflect.Proxy;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import gps.Destinations;
import gps.TestShortestPathConfig;
import gps.WorldPointUtil;

/**
 * Shared setup for the search-pipeline benchmarks (heuristic build, search, availability, generate).
 * Builds a planning config off the real collision map + transport data with the plugin's default
 * settings, and resolves representative start/target queries of increasing difficulty, each the
 * kind of click a player makes.
 */
final class BenchScenarios
{
	// Cross-country, largely walking with a few transports.
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);
	// Needs a real teleport/boat leg to another region.
	private static final int GRAND_EXCHANGE = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	private static final int SHILO_VILLAGE = WorldPointUtil.packWorldPoint(2852, 2954, 0);
	// The capture query: Lumbridge to the Varlamore Hunter Guild, a cross-continent multi-teleport.
	private static final int CAPTURE_START = WorldPointUtil.packWorldPoint(3219, 3219, 0);
	private static final Set<Integer> CAPTURE_TARGETS = Set.of(
		WorldPointUtil.packWorldPoint(1556, 3046, 0),
		WorldPointUtil.packWorldPoint(1555, 3045, 0),
		WorldPointUtil.packWorldPoint(1555, 3046, 0),
		WorldPointUtil.packWorldPoint(1554, 3046, 0));
	// Uncommon shapes (see UncommonPathShapesTest): boat-only island, deep wilderness both ways.
	private static final int ENTRANA = WorldPointUtil.packWorldPoint(2830, 3335, 0);
	private static final int DEEP_WILDERNESS = WorldPointUtil.packWorldPoint(3004, 3937, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	// A water pin off Dognose (see SailingGenerationTest): the sea legs are synthesized per
	// generation and the reverse field must see them.
	private static final int DOGNOSE_PIN = WorldPointUtil.packWorldPoint(3048, 2648, 0);
	// The Broken Raft deck: open tiles ringed by the river, never reachable. The provably
	// unreachable short circuit (plan step N7): one complete flood, three escape routes, and in
	// an owned mode the all-everything probe behind the "not with what you have" verdict.
	private static final int LUM_RAFT = WorldPointUtil.packWorldPoint(3253, 3180, 0);

	private BenchScenarios()
	{
	}

	/**
	 * A planning copy with the plugin's default settings. A real implementing config, so every
	 * unoverridden setting resolves to the interface's default (sailing on, as shipped); the
	 * stub mock this used to be returned false for every toggle. Everything-mode until a
	 * generation applies its own mode on the client-thread refresh.
	 */
	static PathfinderConfig everythingConfig()
	{
		TestShortestPathConfig cfg = new TestShortestPathConfig();
		cfg.setCalculationCutoffValue(120);
		PathfinderConfig config = new TestPathfinderConfig(realisticClient(), cfg).copyForPlanning();
		config.refresh();
		return config;
	}

	/**
	 * A real (non-Mockito) Client. refresh() makes thousands of getVarbitValue calls, and even a
	 * stubOnly Mockito mock allocates a transient invocation on every one; that alone made refresh
	 * measure ~15x slower and ~70x heavier than it is with a real client. A reflective Proxy returning
	 * game-state defaults is a far more representative (and still conservative) stand-in: empty
	 * containers, so an owned mode sees a player carrying nothing.
	 */
	private static Client realisticClient()
	{
		final Thread clientThread = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return defaultValue(method.getReturnType());
				}
			});
	}

	private static Object defaultValue(Class<?> type)
	{
		if (type == int.class || type == short.class || type == byte.class)
		{
			return 0;
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == double.class)
		{
			return 0.0;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == char.class)
		{
			return (char) 0;
		}
		return null;
	}

	static int start(String scenario)
	{
		switch (scenario)
		{
			case "lumbridge-barrows":
			case "island":
			case "deep-wild":
			case "nearest-bank":
			case "bank-and-back":
			case "water-pin":
			case "sealed":
				return LUMBRIDGE;
			case "ge-shilo":
				return GRAND_EXCHANGE;
			case "capture":
				return CAPTURE_START;
			case "wilderness-escape":
				return DEEP_WILDERNESS;
			default:
				throw new IllegalArgumentException("unknown scenario: " + scenario);
		}
	}

	/** The target set; the nearest-bank scenarios gather the bank tiles the way the panel does. */
	static Set<Integer> targets(String scenario, PathfinderConfig config)
	{
		switch (scenario)
		{
			case "lumbridge-barrows":
				return Set.of(BARROWS);
			case "ge-shilo":
				return Set.of(SHILO_VILLAGE);
			case "capture":
				return CAPTURE_TARGETS;
			case "island":
				return Set.of(ENTRANA);
			case "deep-wild":
				return Set.of(DEEP_WILDERNESS);
			case "wilderness-escape":
				return Set.of(VARROCK);
			case "nearest-bank":
			case "bank-and-back":
			{
				// The panel's "nearest bank": the amenity dump's bank tiles plus the engine's own
				// accessible-bank tiles (see DestinationSearchView.runNearestOption). A map-wide
				// set; it gets a distance field like any other (plan step N1).
				Set<Integer> banks = new HashSet<>(Destinations.tilesForCategory("bank", null));
				banks.addAll(config.getDestinations("bank"));
				return banks;
			}
			case "water-pin":
				return Set.of(DOGNOSE_PIN);
			case "sealed":
				return Set.of(LUM_RAFT);
			default:
				throw new IllegalArgumentException("unknown scenario: " + scenario);
		}
	}

	/** "Nearest bank and back" is the one round-trip destination the panel offers. */
	static boolean roundTrip(String scenario)
	{
		return "bank-and-back".equals(scenario);
	}
}

package gps.pathfinder;

import java.util.Set;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mockito;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * Microbenchmark for the per-generation distance-field build: one multi-source reverse flood plus
 * the reverse-transport index and the blocked-landing patch. Dev-only — it lives in the jmh source
 * set so it never ships and never counts toward the hub's review surface.
 * <p>
 * The heavy setup (loading the real collision map + transport data and refreshing the everything-mode
 * config) runs once per trial in {@link #setup()} and is NOT measured; only {@link DistanceField#build}
 * is timed. Returning the field lets JMH consume it so the JIT cannot elide the flood.
 * <p>
 * Run e.g.: {@code ./gradlew -Pjmh jmh --args='DistanceFieldBenchmark -f 1 -wi 3 -i 5'}
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class DistanceFieldBenchmark
{
	// Varrock, and a spread-out three-target set (Varrock / Falador / Draynor) whose wider initial
	// frontier makes the flood do more work — the two ends of what a real generation asks for.
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3380, 0);
	private static final int DRAYNOR = WorldPointUtil.packWorldPoint(3093, 3245, 0);

	@Param({"single", "multi"})
	public String scenario;

	// 0 = full-map flood; 3 = the production default cost multiple (floor-bounded flood).
	@Param({"0", "3"})
	public int costMultiple;

	private PathfinderConfig config;
	private Set<Integer> targets;

	@Setup(Level.Trial)
	public void setup()
	{
		Client client = Mockito.mock(Client.class);
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class);
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		Mockito.when(client.getClientThread()).thenReturn(Thread.currentThread());
		Mockito.when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);

		config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();

		switch (scenario)
		{
			case "single":
				targets = Set.of(VARROCK);
				break;
			case "multi":
				targets = Set.of(VARROCK, FALADOR, DRAYNOR);
				break;
			default:
				throw new IllegalArgumentException("unknown scenario: " + scenario);
		}
	}

	@Benchmark
	public DistanceField build()
	{
		return DistanceField.build(config, targets, costMultiple);
	}
}

package gps.pathfinder;

import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.client.callback.ClientThread;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mockito;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.TearDown;
import org.openjdk.jmh.annotations.Warmup;
import gps.AlternativeRoutesMode;
import gps.AlternativeRoutesService;
import gps.RouteOption;
import gps.TeleportMethod;

/**
 * Microbenchmark for the true end-to-end "find routes": one {@link AlternativeRoutesService}
 * generation, which builds the distance field once and runs the exclusion-chain + seed searches to
 * produce a page of alternative routes by method. This is the actual cost of a panel "find routes"
 * click, at the plugin's default page size and cost band (the route budget is the same with the
 * panel shown or hidden, see RouteController.routeLimitFor).
 * <p>
 * The generation is asynchronous (own executor + seed pool); the benchmark awaits the terminal
 * {@code done} update on a latch, so the measured wall time is the generation's. The client-thread
 * bounce is run inline via a mock. Output in ms.
 * <p>
 * {@code scenario}: the six single-target queries, then the panel's "nearest bank" (a map-wide
 * target set, guided by its field like any other), "nearest bank and back"
 * (round trips: a return search per route over a start-rooted field), a water pin (sea legs
 * synthesized per generation) and a sealed target (the provably-unreachable short circuit).
 * <p>
 * {@code mode}: {@code owned} is the plugin's default (inventory only, possession checked); the
 * bench client carries nothing, so this is the no-items player, whose flood has no cheap teleport
 * floor and runs widest. {@code everything} bypasses possession: every teleport usable, the widest
 * transport fan-out.
 * <p>
 * {@code cache}: the distance-field cache (plan step N4). A service reuses the field across
 * generations with the same target set and usable transports, so one long-lived service fed the
 * same query in a loop measures a WARM regeneration (the player walking toward a pinned target:
 * one guided search per route, single-digit milliseconds), not a first click. {@code cold} builds
 * a fresh service per invocation, so every generation floods its field (the first click on a new
 * target, where the flood dominates); {@code warm} keeps one service per trial. The shared
 * config's own caches stay warm in both, as they do in the plugin.
 * <p>
 * Run: {@code ./gradlew -Pjmh jmh --args='GenerateBenchmark'}; narrow with
 * {@code -p scenario=capture -p mode=owned -p cache=cold}.
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class GenerateBenchmark
{
	/** The plugin's defaults: routes per page (ShortestPathConfig.defaultRouteCount) ... */
	private static final int ROUTES_PER_PAGE = 10;
	/** ... and the cost band each search is capped at (RouteSession.DEFAULT_COST_MULTIPLE). */
	private static final int COST_MULTIPLE = 3;

	@Param({"lumbridge-barrows", "ge-shilo", "capture", "island", "deep-wild", "wilderness-escape",
		"nearest-bank", "bank-and-back", "water-pin", "sealed"})
	public String scenario;

	/** owned: the plugin's default mode (inventory, possession checked); everything: all bypassed. */
	@Param({"owned", "everything"})
	public String mode;

	/** cold: a fresh service (empty field cache) per invocation; warm: one service per trial. */
	@Param({"cold", "warm"})
	public String cache;

	private ClientThread clientThread;
	private PathfinderConfig config;
	private AlternativeRoutesService service;
	private int start;
	private Set<Integer> targets;
	private AlternativeRoutesMode routesMode;
	private boolean roundTrip;

	@Setup(Level.Trial)
	public void setup()
	{
		clientThread = Mockito.mock(ClientThread.class);
		Mockito.doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		config = BenchScenarios.everythingConfig();
		start = BenchScenarios.start(scenario);
		targets = BenchScenarios.targets(scenario, config);
		routesMode = "owned".equals(mode) ? AlternativeRoutesMode.OWNED_INVENTORY : AlternativeRoutesMode.ALL_EVERYTHING;
		roundTrip = BenchScenarios.roundTrip(scenario);
		if ("warm".equals(cache))
		{
			service = new AlternativeRoutesService(clientThread, config);
		}
	}

	/** Cold: every invocation starts from an empty field cache, the way a new target does. */
	@Setup(Level.Invocation)
	public void freshServiceWhenCold()
	{
		if ("cold".equals(cache))
		{
			service = new AlternativeRoutesService(clientThread, config);
		}
	}

	@TearDown(Level.Invocation)
	public void dropServiceWhenCold()
	{
		if ("cold".equals(cache))
		{
			service.shutdown();
			service = null;
		}
	}

	@TearDown(Level.Trial)
	public void tearDown()
	{
		if (service != null)
		{
			service.shutdown();
		}
	}

	@Benchmark
	public List<RouteOption> generate() throws InterruptedException
	{
		final CountDownLatch latch = new CountDownLatch(1);
		final AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(start, targets, Set.<TeleportMethod>of(), routesMode, ROUTES_PER_PAGE, COST_MULTIPLE,
			roundTrip,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		latch.await(60, TimeUnit.SECONDS);
		return out.get();
	}
}

package gps.pathfinder;

import java.util.Set;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;

/**
 * Microbenchmark for the third pipeline step: one {@link Pathfinder} search from start to targets.
 * The {@code mode} axis contrasts the production A* (with the distance-field heuristic) against the
 * uninformed search (heuristic = null), so the numbers show what the heuristic actually buys per
 * scenario.
 * <p>
 * The config, and the field + heuristic for the A* mode, are built once per trial in {@link #setup()}
 * and are NOT measured. Each invocation constructs a fresh Pathfinder (the search state is single-use)
 * and runs it — that construction is part of a real per-route cost, so it is measured too. Returning
 * the result lets JMH consume it.
 * <p>
 * Run: {@code ./gradlew -Pjmh jmh --args='PathfinderBenchmark'}
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class PathfinderBenchmark
{
	@Param({"lumbridge-barrows", "ge-shilo", "capture", "island", "deep-wild", "wilderness-escape"})
	public String scenario;

	@Param({"astar", "uninformed"})
	public String mode;

	private PathfinderConfig config;
	private int start;
	private Set<Integer> targets;
	private SearchHeuristic heuristic;

	@Setup(Level.Trial)
	public void setup()
	{
		config = BenchScenarios.everythingConfig();
		start = BenchScenarios.start(scenario);
		targets = BenchScenarios.targets(scenario, config);
		heuristic = "astar".equals(mode)
			? SearchHeuristic.buildWithField(config, DistanceField.build(config, targets))
			: null;
	}

	@Benchmark
	public PathfinderResult search()
	{
		Pathfinder pathfinder = new Pathfinder(config, start, targets, Integer.MAX_VALUE, heuristic);
		pathfinder.run();
		return pathfinder.getResult();
	}
}

