import static gps.WorldPointUtil.distanceBetween;

/**
 * Generates up to {@link #MAX_ROUTES} alternative shortest paths to a target, each using a different
 * set of teleport/transport methods.
 * <p>
 * Strategy: run the planning-mode pathfinder, record the methods the best path used, exclude that
 * path's primary method, and search again. Repeating this yields successively-different routes in
 * increasing cost order. The user's own exclusions (methods they switched off in the panel) are
 * applied on top of every search.
 * <p>
 * Searches run on a dedicated background thread. Each search needs the planning config's transport
 * availability rebuilt for the current exclusion set, and {@link PathfinderConfig#refresh()} must run
 * on the client thread (it reads live game state), so the worker bounces each refresh onto the client
 * thread and waits for it before running the search off-thread.
 */
@Slf4j
public class AlternativeRoutesService {
    public static final int MAX_ROUTES = 10;
    // Absolute safety backstop on how many routes one generation may enumerate. "Poll more" grows the
    // live limit toward this; it exists only so a runaway query can't enumerate without bound, not as a
    // user-facing ceiling — in practice the walk-cost cap ends enumeration long before this.
    public static final int MAX_ROUTES_CAP = 250;
    /** Closest-approach routes kept for a provably unreachable target (each is a full-world flood). */
    static final int UNREACHABLE_ESCAPE_ROUTES = 3;
    private static final long CLIENT_THREAD_TIMEOUT_SECONDS = 10;

    /**
     * Receives progressive updates for one generation: the catalog as soon as it's known, then the
     * routes-so-far after each one is found, and a final call with {@code done == true}. Invoked on
     * the worker thread; the caller marshals to the Swing EDT. Stale generations stop emitting.
     * {@code unavailable} maps each catalog method the player cannot use in the current mode to the
     * reason why (missing item, in the bank, missing level/quest, not unlocked), so the panel can mark
     * and explain them; it is populated in every mode.
     */
    public interface ResultListener {
        void onUpdate(List<RouteOption> routes, List<TeleportMethod> catalog,
            Map<TeleportMethod, MethodAvailability> unavailable, boolean done);
    }

    /**
     * Worker threads for the parallel seed searches (the exclusion loop itself is inherently
     * sequential). Small pool: searches are CPU-bound.
     */
    // Fixed pool size: the plugin hub disallows Runtime::availableProcessors. Four workers is the
    // measured sweet spot on the benchmark; on smaller machines surplus workers just idle.
    private static final int SEED_POOL_SIZE = 4;

    private final ClientThread clientThread;
    private final PathfinderConfig planningConfig;
    private final ExecutorService executor;
    private final ExecutorService seedExecutor;
    // Bumped on every generate()/cancel() so a stale in-flight generation discards its result.
    private final AtomicInteger generation = new AtomicInteger();

    public AlternativeRoutesService(ClientThread clientThread, PathfinderConfig planningConfig) {
        this.clientThread = clientThread;
        this.planningConfig = planningConfig;
        this.executor = Executors.newSingleThreadExecutor(
            new ThreadFactoryBuilder().setNameFormat("shortest-path-alts-%d").setDaemon(true).build());
        this.seedExecutor = Executors.newFixedThreadPool(SEED_POOL_SIZE,
            new ThreadFactoryBuilder().setNameFormat("shortest-path-alts-seed-%d").setDaemon(true).build());
    }

    /**
     * The specific missing-unlock reason per unavailable catalog method ("Requires 60 Mining"),
     * from the same client-thread refresh that produced the availability statuses.
     */
    public Map<TeleportMethod, String> getAvailabilityDetails() {
        return planningConfig.getMethodAvailabilityDetail();
    }

    /**
     * Asynchronously computes the alternative routes, streaming progressive updates to {@code listener}
     * (catalog first, then each route as it's found, then a final done update). Supersedes any in-flight
     * generation.
     */
    public void generate(int start, Set<Integer> targets, Set<TeleportMethod> userExclusions,
        AlternativeRoutesMode mode, int maxRoutes, ResultListener listener) {
        generate(start, targets, userExclusions, mode, maxRoutes, 0, false, listener);
    }

    /**
     * Round-trip variant: every produced route goes out to a target AND back to the start, ranked
     * by the combined cost — the best round-trip destination is not necessarily the nearest one-way
     * one (a marginally farther bank with a cheap way home, or bank-unlocked teleports for the
     * return, can win).
     * <p>
     * {@code costMultiple} caps each search at {@code best route cost * costMultiple} (in addition
     * to the walk-cost ceiling), so only routes up to that many times the cheapest are computed —
     * a cheap global teleport otherwise makes the A* heuristic flat and a search for a far-worse
     * alternative floods the map. 0 disables the cap (used by tests). The "show more" action raises
     * the multiple and regenerates; {@link #wasMoreLikely()} reports whether raising it further
     * could surface routes the cap held back.
     */
    public void generate(int start, Set<Integer> targets, Set<TeleportMethod> userExclusions,
        AlternativeRoutesMode mode, int maxRoutes, int costMultiple, boolean roundTrip, ResultListener listener) {
        final int gen = generation.incrementAndGet();
        final Set<Integer> targetsCopy = new HashSet<>(targets);
        final Set<TeleportMethod> userExclusionsCopy = new HashSet<>(userExclusions);
        executor.submit(() -> {
            try {
                computeRoutes(gen, start, targetsCopy, userExclusionsCopy, mode, maxRoutes, costMultiple,
                    roundTrip, listener);
            }
            catch (Exception e) {
                log.warn("Alternative route generation failed", e);
                // Without a terminal update the plugin keeps altGenerationInFlight forever and
                // the panel sits on "Finding the best route". emit() itself drops stale gens.
                emit(gen, listener, List.of(), List.of(), Map.of(), true);
            }
        });
    }

    public void cancel() {
        generation.incrementAndGet();
    }

    /** What the panel shows beside the catalog: the catalog and who can't use what. */
    public interface CatalogListener {
        void onCatalog(List<TeleportMethod> catalog, Map<TeleportMethod, MethodAvailability> unavailable);
    }

    /**
     * Re-snapshots the game state and re-classifies the method catalog WITHOUT generating routes
     * (issue #5: the "usable/total" count and the per-method reasons were a per-generation
     * snapshot — opening the bank, equipping runes or gaining a level changed nothing until the
     * next route computation). Serialized on the generation executor so it never overlaps a
     * generation; the listener runs there too.
     */
    public void refreshCatalog(AlternativeRoutesMode mode, CatalogListener listener) {
        executor.submit(() -> {
            try {
                if (!refreshOnClientThread(Collections.emptySet(), null, mode))
                    return;
                List<TeleportMethod> catalog = new ArrayList<>(planningConfig.getMethodCatalog());
                listener.onCatalog(catalog, notUsable(catalog));
            }
            catch (Exception e) {
                log.warn("Catalog refresh failed", e);
            }
        });
    }

    /**
     * The catalog is the full method universe in every mode; this maps each entry the player can't
     * use straight from the inventory to WHY (missing item/level/quest, in the bank, not unlocked),
     * mode-independently — the panel decides usability per mode (a banked item is usable in the
     * "Inventory + bank" mode, whose route walks to a bank) and filters by these reasons.
     */
    private Map<TeleportMethod, MethodAvailability> notUsable(List<TeleportMethod> catalog) {
        final Map<TeleportMethod, MethodAvailability> statuses = planningConfig.getMethodAvailability();
        final Map<TeleportMethod, MethodAvailability> notUsable = new HashMap<>();
        for (TeleportMethod method : catalog) {
            MethodAvailability status = statuses.getOrDefault(method, MethodAvailability.AVAILABLE);
            if (status != MethodAvailability.AVAILABLE)
                notUsable.put(method, status);
        }
        return Collections.unmodifiableMap(notUsable);
    }

    public void shutdown() {
        executor.shutdownNow();
        seedExecutor.shutdownNow();
        cachedField = null;
        cachedFieldKey = null;
    }

    private void computeRoutes(int gen, int start, Set<Integer> targets,
        Set<TeleportMethod> userExclusions, AlternativeRoutesMode mode, int maxRoutes, int costMultiple,
        boolean roundTrip, ResultListener listener) {
        // The generation as phases over one context (plan step L3): prepare the query (resume or
        // refresh, sea legs), build the field and its verdict, start the concurrent walk search,
        // run the exclusion chain, fill the page (seeds, tail diversity), append the baselines,
        // finish (round trips, timing, resume state, the unreachable cause, the terminal update).
        Generation g = prepare(gen, start, targets, userExclusions, mode, maxRoutes, costMultiple, roundTrip, listener);
        if (g == null)
            return;
        buildField(g);
        startWalkSearch(g);
        if (!runChain(g))
            return;
        fillPage(g);
        appendBaselines(g);
        finish(g);
    }

    /**
     * Resolves the query into a generation context: a widened re-request resumes the previous
     * chain state, anything else refreshes the planning snapshot on the client thread and builds
     * the catalog; both synthesize the sea legs. Null when the generation ended here (the refresh
     * timed out, or no target survived filtering); the terminal update has then been emitted.
     */
    private Generation prepare(int gen, int start, Set<Integer> targets,
        Set<TeleportMethod> userExclusions, AlternativeRoutesMode mode, int maxRoutes, int costMultiple,
        boolean roundTrip, ResultListener listener) {
        final int limit = Math.max(1, Math.min(maxRoutes, MAX_ROUTES_CAP));
        final Set<Integer> rawTargets = new HashSet<>(targets);
        final Set<Integer> ends = new HashSet<>(targets);
        final Map<String, Integer> chainTailCounts;
        final GenTimer timer = new GenTimer();
        final long wallStart = System.nanoTime();

        // A widened re-request for the SAME query ("+ more routes": limit/multiple grew, nothing else
        // changed) CONTINUES the previous generation instead of starting over: the exclusion chain's
        // state is resumable, and widening only ever appends costlier routes. The already-found routes
        // go out in the very first update, so the panel never blanks while the extra ones compute.
        final ResumeState prior = resumeState;
        final boolean resumed = !roundTrip && prior != null
            && prior.start == start && prior.rawTargets.equals(rawTargets)
            && prior.mode == mode && prior.userExclusions.equals(userExclusions)
            && limit >= prior.limit && costMultiple >= prior.costMultiple
            && (limit > prior.limit || costMultiple > prior.costMultiple);

        final Set<TeleportMethod> excluded;
        final List<TeleportMethod> catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable;
        final List<Transport> seedCandidates;
        final List<RouteOption> routes;
        final Set<String> seenSignatures;
        // Remaining distance to the target of the first route's endpoint; -1 until known. For an
        // unreachable exact target (e.g. an NPC tile) every route ends at the closest reachable area,
        // so later routes are only accepted while they get equally close (small tolerance).
        int bestRemaining;

        // Water targets: synthesize the final sea legs (board at a nearby mooring, sail
        // straight out) so a pin on the ocean is a real destination. Set for EVERY branch —
        // the resumed path reuses the prior snapshot and previously lost the legs entirely,
        // leaving water pins to detour via whatever static landing the search could reach.
        List<Transport> seaLegs = new ArrayList<>();
        // Wet = sailable terrain AND collision-blocked: stilt-deck tiles (the Pandemonium
        // dock) sit on water-family terrain but are walkable pier cells — functionally land.
        // Sea legs to those said "sail to the destination" where mooring + walking is the
        // real route (and the only physically sensible one). Which targets qualify is
        // SailingSea.waterPins, decided at synthesis time: whether the player is aboard comes
        // from the refreshed snapshot.
        // Synthesis must run against the CURRENT snapshot: the gated must-include berths
        // and the BOARDED varbit both come from planningConfig state that the client-thread
        // refresh rewrites, and synthesizing before it used the PREVIOUS generation's
        // toggles — flipping Summon Boat off then refreshing routed a Khazard water pin
        // toward Brimhaven as its "closest point" until a second refresh (capture 211433).
        // Resumed generations keep the prior snapshot ON PURPOSE (no refresh), so each
        // branch synthesizes at its own right moment.
        Runnable synthesizeSeaLegs = () -> {
            // A place's water tiles always; a category's only for a player already aboard.
            Set<Integer> wetTargets = SailingSea.waterPins(planningConfig.getMap(), ends,
                planningConfig.isOnSailingBoat());
            for (int target : wetTargets) {
                seaLegs.addAll(SailingSea.seaLegTransports(target, 6,
                    planningConfig.gatedBoatMoorings()));
            }
            // Player aboard: the start tile is sealed ocean with no walk edges — without legs
            // FROM it (disembark at nearby ports, or sail straight to a water pin), every search
            // dies on the start node and the whole generation reports unreachable. Gated on the
            // BOARDED varbit, not tile wateriness: stilt decks (the Pandemonium) are sailable
            // tiles a player stands on afoot, and offering "sail from here" there was wrong.
            if (planningConfig.isOnSailingBoat())
                seaLegs.addAll(SailingSea.aboardLegTransports(start, wetTargets));
            planningConfig.setExtraTransports(seaLegs);
        };

        if (resumed) {
            synthesizeSeaLegs.run();
            // No client-thread refresh: the cached routes were computed against the previous snapshot,
            // and mixing a fresh one into a continued chain would make the page inconsistent. A real
            // re-read happens on any non-widening regeneration (new target, Find routes, recompute).
            ends.clear();
            ends.addAll(prior.filteredEnds);
            excluded = new HashSet<>(prior.excluded);
            catalog = prior.catalog;
            unavailable = prior.unavailable;
            seedCandidates = prior.seedCandidates;
            routes = new ArrayList<>(prior.routes);
            seenSignatures = new HashSet<>(prior.seenSignatures);
            chainTailCounts = new java.util.HashMap<>(prior.chainTailCounts);
            bestRemaining = prior.bestRemaining;
            // First update: the routes the user is already looking at, unchanged.
            emit(gen, listener, new ArrayList<>(routes), catalog, unavailable, false);
            log.debug("[alt-routes] resuming: {} route(s), limit {} -> {}, multiple {} -> {}",
                routes.size(), prior.limit, limit, prior.costMultiple, costMultiple);
        }
        else {
            excluded = new HashSet<>(userExclusions);
            // Single client-thread pass per generation, with NO exclusions: snapshots the game state and
            // builds the full availability (the complete method catalog, and the base lists that per-search
            // availability is rebuilt from off-thread), and drops targets the avoid-wilderness setting forbids.
            long clientStart = System.nanoTime();
            boolean refreshed = refreshOnClientThread(Collections.emptySet(), ends, mode);
            timer.clientNanos += System.nanoTime() - clientStart;
            if (!refreshed) {
                emit(gen, listener, List.of(), List.of(), Map.of(), true);
                return null;
            }
            // Now the snapshot is current — the sea legs see THIS generation's toggles.
            synthesizeSeaLegs.run();
            // The hop filter's baseline is captured HERE, before the chain's own exclusion
            // rebuilds: the chain removes the direct teleport right before its hop variants
            // are generated (that removal is WHY they appear), so a live-availability check
            // found nothing (capture 20260823-215617, on the first cut of this filter).
            hopBaselineTeleports = teleportHopBaseline(planningConfig, userExclusions);
            catalog = new ArrayList<>(planningConfig.getMethodCatalog());
            unavailable = notUsable(catalog);
            if (ends.isEmpty()) {
                resumeState = null;
                emit(gen, listener, List.of(), catalog, unavailable, true);
                return null;
            }
            routes = new ArrayList<>();
            seenSignatures = new HashSet<>();
            chainTailCounts = new java.util.HashMap<>();
            bestRemaining = -1;
            // Show the catalog right away while the routes are still computing.
            emit(gen, listener, List.of(), catalog, unavailable, false);

            log.debug("[alt-routes] searching: start={}, target={}, mode={}, usableTeleports={}, catalog={}",
                WorldPointUtil.unpackWorldPoint(start),
                WorldPointUtil.unpackWorldPoint(ends.iterator().next()),
                mode, planningConfig.getUsableTeleports(false).length, catalog.size());

            // Snapshot the global-teleport candidates now, while availability reflects no exclusions; used
            // to seed extra routes if the exclusion loop dries up before the limit.
            seedCandidates = new ArrayList<>(Arrays.asList(
                planningConfig.getUsableTeleports(mode == AlternativeRoutesMode.OWNED_WITH_BANK)));
            // Abandonment forbidden: teleport-FIRST seeds would cast from the helm — the
            // search itself blocks that (teleportsBlockedAt), so the seeds are dead weight.
            if (planningConfig.teleportsBlockedAt(start))
                seedCandidates.clear();
        // Aboard: EVERY disembark port gets its own seeded search — nearest first. With
            // abandonment forbidden this is the whole diversity engine (teleport-first seeds
            // are barred, and one port seed + chains produced exactly one route in the
            // field); with abandonment allowed it still guarantees the "park the boat
            // properly" options ride alongside the teleport routes.
            if (planningConfig.isOnSailingBoat()) {
                List<Transport> ports = new ArrayList<>();
                for (Transport leg : seaLegs) {
                    if (leg.getOrigin() == start && leg.getDisplayInfo() != null
                        && leg.getDisplayInfo().startsWith("Disembark")) {
                        ports.add(leg);
                    }
                }
                ports.sort(Comparator.comparingInt(Transport::getDuration));
                for (int i = 0; i < ports.size(); i++)
                    seedCandidates.add(Math.min(i, seedCandidates.size()), ports.get(i));
            }
        }

        final Generation g = new Generation(gen, start, ends, userExclusions, mode, limit, costMultiple, roundTrip,
            listener, timer, catalog, unavailable, seedCandidates, routes, seenSignatures);
        g.excluded = excluded;
        g.chainTailCounts = chainTailCounts;
        g.bestRemaining = bestRemaining;
        g.seaLegs = seaLegs;
        g.rawTargets = rawTargets;
        g.resumed = resumed;
        g.wallStart = wallStart;
        return g;
    }

    /** Builds (or reuses) the generation's distance field and its unreachable verdict. */
    private void buildField(Generation g) {
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final int costMultiple = g.costMultiple;
        final GenTimer timer = g.timer;
        final List<Transport> seaLegs = g.seaLegs;
        final Set<TeleportMethod> excluded = g.excluded;
        // Per-generation preprocessing: one multi-source reverse flood from the target set builds a
        // walking+transport distance field — the near-exact A* heuristic every search of this
        // generation shares (chain, walk, seeds). Compact target sets only; a map-wide nearest-X
        // set would flood everything for searches that are already cheap.
        // The field's reverse-transport index must see the sea legs set above: availability
        // only absorbs extras on REBUILD, and the first in-loop rebuild happens after the field
        // is built. Water pins therefore got an EMPTY field — production diagnostics showed 0
        // guided / 19 blind searches and a 30s wall for a pin the direct probe (which rebuilt
        // first) served a healthy field for.
        // Over the USER exclusions only: a resumed generation's chain set already holds the
        // previous chain's exclusions, and a field flooded over that smaller availability is not
        // a lower bound for the seed and tail searches, which run with the user exclusions alone
        // (a reverse flood over fewer transports can only overestimate).
        planningConfig.rebuildAvailabilityWithExclusions(userExclusions);
        boolean availabilityCurrent = excluded.equals(userExclusions);
        long fieldStart = System.nanoTime();
        // The horizon matches the searches' sanity ceiling (2x the display band), so the fill region
        // past the band edge still gets exact heuristic guidance. Same inputs as the last
        // generation: the previous field is reused instead of flooded again (plan step N4).
        final FieldKey fieldKey = new FieldKey(planningConfig.getUsableFingerprint(), userExclusions,
            extrasFingerprint(seaLegs), ends, costMultiple);
        final boolean fieldReused = cachedField != null
            && fieldKey.sameInputs(cachedFieldKey, cachedField.horizon() == Integer.MAX_VALUE);
        final DistanceField field;
        if (fieldReused)
            field = cachedField;
        else {
            field = DistanceField.buildIfCompact(planningConfig, ends, 2 * costMultiple);
            cachedField = field;
            cachedFieldKey = field != null ? fieldKey : null;
        }
        lastFieldReused = fieldReused;
        g.field = field;
        timer.fieldNanos = System.nanoTime() - fieldStart;
        // A complete reverse field that never reached the start, with no usable teleport landing
        // inside its flooded pocket, proves the target unreachable for EVERY search of this
        // generation (exclusions only shrink availability) - exactly the condition under which
        // SearchHeuristic already discards the field. Capture 20260830-172137 then ran seven
        // full-world floods (~2M nodes, ~400 ms each) to rediscover that verdict seven times.
        // The chain then keeps a SHORT escape menu (UNREACHABLE_ESCAPE_ROUTES distinct closest-
        // approach routes - a sealed-cell capture wants several ways out, see HybridPageFillTest)
        // and skips the walk, seed and tail passes entirely. In every mode: the reverse flood
        // runs over BOTH bank states (reverse transport index, teleport landings, blocked-landing
        // patch), so a route that needs a banked item is part of the proof (plan step N7; the
        // former "+ Bank" exclusion predated that and left bank mode with a one-route page).
        final boolean targetProvablyUnreachable = field != null
            && field.horizon() == Integer.MAX_VALUE
            && field.distance(start) == DistanceField.UNREACHED
            && SearchHeuristic.buildWithField(planningConfig, field) != null
            && SearchHeuristic.buildWithField(planningConfig, field, start) == null;
        g.availabilityCurrent = availabilityCurrent;
        g.targetProvablyUnreachable = targetProvablyUnreachable;
    }

    /** Starts the concurrent walk-only search (none for single-route pages or a sealed target). */
    private void startWalkSearch(Generation g) {
        final boolean resumed = g.resumed;
        final List<RouteOption> routes = g.routes;
        final int costMultiple = g.costMultiple;
        final int limit = g.limit;
        final boolean targetProvablyUnreachable = g.targetProvablyUnreachable;
        // Walk-only search, run concurrently on the seed pool (its own config copy — the chain
        // mutates planningConfig per iteration): its cost is a rigorous expansion cap for every
        // search that starts after it finishes (routes costlier than walking are never shown, so a
        // node above walk cost is provably useless — this keeps a dead-end seed teleport from
        // flooding the map), and its path is the last-resort route appended when the chain doesn't
        // derive it. Polled non-blockingly so route 1's latency is unchanged. Skipped for
        // single-route generations (limit 1): one search, a cap can't pay for itself.
        // Live ceiling for the walk search: unbounded until the chain finds its (cheapest) route, then
        // dropped to that route's cost band so the walk stops flooding the map when walking is
        // uncompetitive — which is most queries, since a teleport route usually wins.
        final AtomicInteger walkCeiling = new AtomicInteger(Integer.MAX_VALUE);
        if (resumed && !routes.isEmpty() && costMultiple > 0) {
            // The best route is already known, so the walk search starts pre-capped at the (widened)
            // sanity ceiling instead of waiting for the chain's in-loop drop (which only fires on the
            // FIRST route — already found on a resume).
            walkCeiling.set((int) Math.min(Integer.MAX_VALUE,
                (long) routes.get(0).getTotalCost() * 2 * costMultiple));
        }
        final Future<WalkResult> walkFuture = limit > 1 && !targetProvablyUnreachable
            ? seedExecutor.submit(() -> runWalkSearch(g, walkCeiling))
            : null;
        g.walkCeiling = walkCeiling;
        g.walkFuture = walkFuture;
    }

    /**
     * The exclusion chain: each accepted route excludes its primary method for the next search,
     * so the page walks down the distinct ways in. False when a newer generation superseded this
     * one mid-chain (nothing more is emitted for it).
     */
    private boolean runChain(Generation g) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final int limit = g.limit;
        final int costMultiple = g.costMultiple;
        final boolean roundTrip = g.roundTrip;
        final ResultListener listener = g.listener;
        final List<TeleportMethod> catalog = g.catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable = g.unavailable;
        final List<RouteOption> routes = g.routes;
        final Set<String> seenSignatures = g.seenSignatures;
        final GenTimer timer = g.timer;
        final Set<TeleportMethod> excluded = g.excluded;
        final Map<String, Integer> chainTailCounts = g.chainTailCounts;
        final DistanceField field = g.field;
        final boolean targetProvablyUnreachable = g.targetProvablyUnreachable;
        final Future<WalkResult> walkFuture = g.walkFuture;
        final AtomicInteger walkCeiling = g.walkCeiling;
        boolean availabilityCurrent = g.availabilityCurrent;
        int bestRemaining = g.bestRemaining;
        // Whether the cost cap (best * costMultiple, below the walk ceiling) held a route back — a
        // search couldn't reach within the band. If so, "show more" (a higher multiple) can surface
        // it. Set only for cost-cap truncations, not method exhaustion or the walk ceiling.
        boolean cappedByCost = false;
        // Set when the chain stops on its own terms (methods exhausted, a duplicate signature, a
        // walk-only route, or the target drifting out of reach). If it stays false the loop simply ran
        // out of route-count budget — the count was binding, so a higher limit can surface more.
        boolean chainExhausted = false;

        for (int i = routes.size(); i < limit; i++) {
            if (gen != generation.get())
                return false;
            if (targetProvablyUnreachable && routes.size() >= UNREACHABLE_ESCAPE_ROUTES) {
                // The escape menu is full; every further search would flood the same world to
                // the same verdict.
                chainExhausted = true;
                break;
            }
            // Rebuild availability for the current exclusion set — pure computation over the base lists
            // captured by the client-thread pass above, so no client-thread round-trip per search.
            long rebuildStart = System.nanoTime();
            // The pre-field rebuild covered the first iteration's exclusion set; later
            // iterations rebuild because the chain grows the set between them.
            if (!availabilityCurrent)
                planningConfig.rebuildAvailabilityWithExclusions(excluded);
            availabilityCurrent = false;
            timer.rebuildNanos += System.nanoTime() - rebuildStart;

            long searchStart = System.nanoTime();
            int walkCap = capOf(walkFuture);
            // Searches run under the hard sanity ceiling (twice the display band): the band itself is
            // no longer a hard cut — past it the page keeps FILLING while each next route stays within
            // a modest gap of the acceptance region (see the accept check below), so the first page
            // never stops mid-cluster (e.g. 105 shown, 107 hidden) the way a bare best*multiple cut did.
            int chainCap = RouteAcceptance.cappedByBestCost(walkCap, routes, 2 * costMultiple);
            // The cost ceiling is the binding one (tighter than the walk ceiling) — a search failing now
            // was held back by cost, not by walking being cheaper or methods running out.
            boolean costLimited = chainCap < walkCap;
            // Heuristic rebuilt per iteration: the exclusion set changes the usable teleports and
            // with them the field floor — excluding the good teleports raises it, so the heuristic
            // gets stronger exactly when the searches get expensive. Null field (map-wide target
            // sets) means uninformed, which those cheap searches don't need anyway.
            SearchHeuristic heuristic = SearchHeuristic.buildWithField(planningConfig, field, start);
            Pathfinder pathfinder = new Pathfinder(planningConfig, start, ends, chainCap, heuristic);
            pathfinder.run();
            long searchNanos = System.nanoTime() - searchStart;
            timer.searchNanos += searchNanos;
            timer.searches++;
            record(timer, "chain#" + i, searchNanos, pathfinder, chainCap);
            PathfinderResult result = pathfinder.getResult();
            List<PathStep> path = (result != null) ? result.getPathSteps() : List.of();
            if (result == null || path.isEmpty()) {
                log.debug("[alt-routes] search #{} produced no path: result={}, reason={}",
                    i, result == null ? "null" : "empty",
                    result == null ? "n/a" : result.getTerminationReason());
                cappedByCost |= costLimited;
                chainExhausted = true;
                break;
            }

            boolean reached = result.isReached();
            // Closeness (RouteAcceptance.tooFar): with the best route reaching, an unreached result
            // is a cap truncation a few tiles short, not a route (a phantom "unreachable" quetzal
            // route at cost 28 under a 27 band was shown once); with an unreachable target, routes
            // are accepted while they end about as close as the best approach. Either way the
            // route is beyond the band, and "more routes" reveals it by widening.
            int remaining = reached ? 0 : remainingDistance(path, ends);
            if (RouteAcceptance.tooFar(reached, remaining, bestRemaining)) {
                log.debug("[alt-routes] search #{} ends {} tiles from target (best {}); stopping with {} route(s)",
                    i, remaining, bestRemaining, routes.size());
                cappedByCost |= costLimited;
                chainExhausted = true;
                break;
            }
            if (bestRemaining < 0)
                bestRemaining = remaining;

            // Hybrid band edge: routes inside the display band are always accepted; past it the page
            // keeps filling while the next cost stays within a modest gap of max(band, costliest
            // accepted) — so a cost cluster straddling the band edge is shown whole, but a genuine
            // cliff (the next route being far pricier than everything shown) still ends the page.
            // A minimum page overrides the cliff: one super-cheap route (a direct minigame teleport)
            // otherwise produced a single-entry page with no alternatives at all (user capture).
            final int totalCost = result.getTotalCost();
            if (RouteAcceptance.beyondBand(totalCost, routes, costMultiple, limit)) {
                // A route exists beyond what this page shows: "+" (a wider band) can reveal it.
                cappedByCost = true;
                chainExhausted = true;
                break;
            }

            MethodScan scan = scanMethods(planningConfig, path);
            List<TeleportMethod> methods = scan.methods;

            // A kept route nested inside this one (detour + same ending): skip it WITHOUT burning
            // its signature, and keep the chain moving by excluding its primary like any accepted
            // route — the next iteration can still find genuinely different endings.
            if (RouteAcceptance.nestsAKeptRoute(methods, !scan.bankGated.isEmpty(), routes)) {
                excluded.add(methods.get(0));
                continue;
            }

            // A whistle-hop variant of a direct teleport (see hasRedundantTeleportHop): skip it
            // WITHOUT burning its signature or a route slot (the loop is iteration-bounded, and
            // one filtered variant per whistle site would eat the whole budget - the probe run
            // came back with 2 routes of 10). Excluding its primary keeps the chain moving to
            // genuinely different methods; the growing exclusion set bounds the extra turns.
            if (RouteAcceptance.hasRedundantTeleportHop(hopBaselineTeleports, methods)) {
                excluded.add(methods.get(0));
                i--;
                continue;
            }
            // Prefix twin of a saturated tail: same treatment as a hop variant. Counted over
            // CHAIN acceptances only (resumable), so a widened resume replays the exact
            // saturation sequence of a from-scratch run.
            if (methods.size() >= 2
                && chainTailCounts.getOrDefault(tailSignature(methods), 0) >= TAIL_DOMINANCE) {
                excluded.add(methods.get(0));
                i--;
                continue;
            }

            // Distinct method-signature gate: if this route uses the same ordered methods as a previous
            // one, excluding more would only reshuffle, so stop.
            if (!seenSignatures.add(signature(methods))) {
                chainExhausted = true;
                break;
            }
            routes.add(new RouteOption(withoutIdleBankFlip(path, scan), methods, scan.methodEdges, scan.methodDurations,
                totalCost, scan.rawCost, reached, scan.bankGated, scan.bankGatedTransports, scan.walkBefore, scan.trailingWalk));
            if (methods.size() >= 2)
                chainTailCounts.merge(tailSignature(methods), 1, Integer::sum);
            // The chain's first route is the cheapest; drop the concurrent walk search's ceiling to the
            // search sanity ceiling (twice the display band). A walk costlier than that can never be
            // shown, so a walk to an unreachable/far target stops instead of flooding the map. Only when
            // route 0 actually reached — an unreachable-target run keeps the walk uncapped so it can be
            // the last resort.
            if (routes.size() == 1 && reached && costMultiple > 0)
                walkCeiling.set((int) Math.min(Integer.MAX_VALUE, (long) totalCost * 2 * costMultiple));
            // Stream the route we just found so the panel shows it immediately. Round-trip mode
            // streams only the merged results — one-way costs would reorder once returns are added.
            if (!roundTrip)
                emit(gen, listener, new ArrayList<>(routes), catalog, unavailable, false);

            // Unreached target: every extra route is another escape toward the same closest area,
            // and with the heuristic degenerate (sealed pocket) each iteration is an uninformed
            // sweep. Time-boxed rather than counted: the page holds whatever the search budget
            // affords, and "+" resumes with a fresh budget.
            if (!reached && searchBudgetExhausted(timer)) {
                cappedByCost = true;
                chainExhausted = true;
                break;
            }

            TeleportMethod primary = methods.isEmpty() ? null : methods.get(0);
            if (primary == null) {
                // Walk-only route: the exclusion strategy has nothing left to remove. Seeding below can
                // still surface teleport routes that lost to walking on cost.
                chainExhausted = true;
                break;
            }
            excluded.add(primary);
        }
        g.bestRemaining = bestRemaining;
        g.availabilityCurrent = availabilityCurrent;
        g.cappedByCost = cappedByCost;
        g.chainExhausted = chainExhausted;
        return true;
    }

    /** The seed and tail-diversity passes, and whether a wider request could show more. */
    private void fillPage(Generation g) {
        final int gen = g.gen;
        final List<RouteOption> routes = g.routes;
        final int costMultiple = g.costMultiple;
        final boolean targetProvablyUnreachable = g.targetProvablyUnreachable;
        final Future<WalkResult> walkFuture = g.walkFuture;
        final boolean cappedByCost = g.cappedByCost;
        final boolean chainExhausted = g.chainExhausted;
        // Stop at the pure-walk option: once walking there is on the list, anything more expensive than
        // just walking isn't worth showing. Seeding only ever surfaces teleports that lost to walking on
        // cost (i.e. routes MORE expensive than walk-only), so skip it entirely when a walk-only route was
        // already found. A FULL list does not skip seeding: a small floor of attempts always runs, and a
        // cheaper seed evicts the costliest route — the safety net for anything the chain missed must not
        // be silenced by a low route limit (the exact failure a user capture showed at limit 10).
        boolean hasWalkOnly = routes.stream().anyMatch(RouteOption::isWalkOnly);
        if (!hasWalkOnly && !routes.isEmpty() && !targetProvablyUnreachable)
            seedTeleportRoutes(g, RouteAcceptance.cappedByBestCost(capOf(walkFuture), routes, 2 * costMultiple));
        // Tail-diversity pass: when the page is dominated by one shared method TAIL, surface a
        // variant with a different middle. Runs after seeds so eviction sees the full page.
        if (gen == generation.get() && !targetProvablyUnreachable)
            diversifySharedTails(g, RouteAcceptance.cappedByBestCost(capOf(walkFuture), routes, 2 * costMultiple));

        // More routes are worth polling for when the count budget was the binding limit (the chain kept
        // finding distinct routes and simply ran out of slots), or the cost cap held routes back — the
        // latter only while it sat below the walk ceiling, since once it reaches walking there's nothing
        // cheaper-than-walk left to reveal.
        int moreWalkCap = capOf(walkFuture);
        boolean costHeldBack = cappedByCost
            && RouteAcceptance.cappedByBestCost(moreWalkCap, routes, costMultiple) < moreWalkCap;
        lastGenerationMoreLikely = !chainExhausted || costHeldBack;
    }

    /** The walk-only and keep-sailing baselines, the final ordering, and the cut at walking. */
    private void appendBaselines(Generation g) {
        final List<RouteOption> routes = g.routes;
        final int limit = g.limit;
        final Set<String> seenSignatures = g.seenSignatures;
        final int bestRemaining = g.bestRemaining;
        final Future<WalkResult> walkFuture = g.walkFuture;
        // The walk-only route from the concurrent search is the last resort: append it when the
        // chain didn't derive it (signature dedup skips it when it did), under the same closeness
        // guard as every other route. Blocking here is fine — the generation is finishing anyway.
        WalkResult walk = walkResult(walkFuture);
        // Ties lose to walking: a method route costing the same as (or more than) plain walking
        // isn't worth a slot. The searches race the concurrent walk search, and now that they're
        // heuristic-directed they can finish before its cap exists — under f-ordering an
        // equal-cost method route can then win the tie the FIFO search implicitly gave to walking.
        if (walk != null && walk.cap != Integer.MAX_VALUE) {
            final int walkCost = walk.cap;
            // When the baseline itself is the keep-sailing route (aboard), an equal-cost
            // pure-sail route IS that baseline - culling it here and letting the signature
            // dedupe block the re-add below would empty the page (close water pins: the
            // direct sail ties its own ceiling).
            final boolean sailWalk = walk.route.isPureSail();
            routes.removeIf(r -> !r.isWalkOnly() && r.getTotalCost() >= walkCost
                && !(sailWalk && r.isPureSail() && r.getTotalCost() == walkCost));
        }
        // Always surface walking as the baseline option (when the target is reachable on foot and the
        // chain didn't already derive it), even at the route limit — the player should always see
        // "…or just walk N tiles" as a complete-picture fallback, whatever teleports were found.
        if (walk != null && walk.cap != Integer.MAX_VALUE
            && (bestRemaining < 0 || walk.remaining <= bestRemaining + RouteAcceptance.CLOSEST_DISTANCE_TOLERANCE)
            && seenSignatures.add(signature(walk.route.getMethods()))) {
            routes.add(walk.route);
            // Keep it within the limit by dropping the costliest teleport route it displaces. Never
            // the baseline itself: at the helm it is a pure-sail route (not walk-only), and with a
            // full page of port-first routes it was the costliest unprotected entry, so the page
            // evicted the very route this block exists to surface (plan step N10).
            while (routes.size() > limit) {
                int drop = RouteAcceptance.evictionIndex(routes, -1, r -> r != walk.route && !r.isWalkOnly());
                if (drop < 0)
                    break;
                routes.remove(drop);
            }
        }

        // The keep-sailing baseline joins the page when aboard and no pure-sail route survived
        // the band: signature-deduped, evicting the costliest teleport chain when full - the
        // walk baseline's exact shape. The plugin ranks it first at the helm.
        RouteOption sailBaseline = g.bestSail.get();
        if (sailBaseline != null && routes.stream().noneMatch(RouteOption::isPureSail)
            && seenSignatures.add(signature(sailBaseline.getMethods()))) {
            routes.add(sailBaseline);
            while (routes.size() > limit) {
                int drop = RouteAcceptance.evictionIndex(routes, -1, r -> !r.isWalkOnly() && !r.isPureSail());
                if (drop < 0)
                    break;
                routes.remove(drop);
            }
        }

        routes.sort(Comparator.comparingInt(RouteOption::getTotalCost));
        // Drop anything after the pure-walk option (belt-and-braces alongside the skipped seeding above).
        for (int i = 0; i < routes.size(); i++) {
            if (routes.get(i).isWalkOnly()) {
                routes.subList(i + 1, routes.size()).clear();
                break;
            }
        }
    }

    /** Round trips, the timing summary, the resume state, the unreachable cause, the terminal update. */
    private void finish(Generation g) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final AlternativeRoutesMode mode = g.mode;
        final int limit = g.limit;
        final int costMultiple = g.costMultiple;
        final boolean roundTrip = g.roundTrip;
        final ResultListener listener = g.listener;
        final List<TeleportMethod> catalog = g.catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable = g.unavailable;
        final List<Transport> seedCandidates = g.seedCandidates;
        final List<RouteOption> routes = g.routes;
        final GenTimer timer = g.timer;
        final long wallStart = g.wallStart;
        final Set<Integer> rawTargets = g.rawTargets;
        final Set<TeleportMethod> excluded = g.excluded;
        final Map<String, Integer> chainTailCounts = g.chainTailCounts;
        final int bestRemaining = g.bestRemaining;
        // Round-trip mode: give every one-way route its return leg and re-rank by combined cost.
        if (roundTrip && !routes.isEmpty() && gen == generation.get()) {
            List<RouteOption> merged = buildRoundTrips(g, routes);
            routes.clear();
            routes.addAll(merged);
        }

        synchronized (timer) {
            // Retained for the GPS debug snapshot:
            // [wallMs, clientMs, rebuildMs, searchCpuMs, searches, fieldMs].
            lastTimingSummary = new long[]{
                (System.nanoTime() - wallStart) / 1_000_000,
                timer.clientNanos / 1_000_000,
                timer.rebuildNanos / 1_000_000,
                timer.searchNanos / 1_000_000,
                timer.searches,
                timer.fieldNanos / 1_000_000};
            List<SearchRecord> records = new ArrayList<>(timer.records);
            records.sort(Comparator.comparingLong((SearchRecord r) -> r.cpuMs).reversed());
            lastSearchRecords = Collections.unmodifiableList(records);
            log.debug("[alt-routes] generated {} route(s); timing: wall={}ms client={}ms rebuild={}ms searchCpu={}ms ({} searches)",
                routes.size(),
                lastTimingSummary[0], lastTimingSummary[1], lastTimingSummary[2],
                lastTimingSummary[3], lastTimingSummary[4]);
        }
        // Capture the chain state so a widened re-request ("+ more routes") can continue this
        // generation instead of starting over. Round trips merge return legs into the route list,
        // which the one-way chain state can't be rebuilt from — they always regenerate.
        if (gen == generation.get() && !roundTrip) {
            // Carry ONLY the shown routes' signatures forward — not the full seenSignatures, which
            // also holds combos the seed pass tried but couldn't fit (cost/slot). A resume that
            // inherited those burned signatures would reject them again when the wider limit COULD
            // show them: a panel-hidden limit-1 generation would poison the full limit-10 resume,
            // silently dropping cheap routes (user capture: Quest-Helper target lost the 164 route).
            Set<String> shownSignatures = new HashSet<>();
            for (RouteOption route : routes)
                shownSignatures.add(signature(route.getMethods()));
            resumeState = new ResumeState(start, rawTargets, Set.copyOf(ends), Set.copyOf(userExclusions),
                mode, limit, costMultiple, Set.copyOf(excluded), shownSignatures,
                List.copyOf(routes), bestRemaining, catalog, unavailable, seedCandidates,
                java.util.Map.copyOf(chainTailCounts));
        }
        if (gen == generation.get())
            lastUnreachableCause = unreachableCause(routes, start, ends, mode);
        // A superseded run leaves the previous state alone: the newer generation overwrites it when it
        // completes, and the eligibility check (start/targets/mode/exclusions) guards staleness anyway.
        emit(gen, listener, new ArrayList<>(routes), catalog, unavailable, true);
    }

    /**
     * A completed generation's chain state, kept so "+ more routes" (same query, wider
     * limit/multiple) resumes instead of recomputing: the found routes are emitted immediately and
     * the exclusion chain continues where it stopped. Only ever read and written on the generation
     * executor thread.
     */
    private static final class ResumeState {
        final int start;
        final Set<Integer> rawTargets;
        final Set<Integer> filteredEnds;
        final Set<TeleportMethod> userExclusions;
        final AlternativeRoutesMode mode;
        final int limit;
        final int costMultiple;
        final Set<TeleportMethod> excluded;
        final Set<String> seenSignatures;
        final List<RouteOption> routes;
        final int bestRemaining;
        final List<TeleportMethod> catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable;
        final List<Transport> seedCandidates;
        // Chain-only tail counts, so a widened resume saturates tails in the exact sequence the
        // from-scratch run would (seed routes must not shift the counts between the two paths).
        final Map<String, Integer> chainTailCounts;

        ResumeState(int start, Set<Integer> rawTargets, Set<Integer> filteredEnds,
            Set<TeleportMethod> userExclusions, AlternativeRoutesMode mode, int limit, int costMultiple,
            Set<TeleportMethod> excluded, Set<String> seenSignatures, List<RouteOption> routes,
            int bestRemaining, List<TeleportMethod> catalog,
            Map<TeleportMethod, MethodAvailability> unavailable, List<Transport> seedCandidates,
            Map<String, Integer> chainTailCounts) {
            this.chainTailCounts = chainTailCounts;
            this.start = start;
            this.rawTargets = rawTargets;
            this.filteredEnds = filteredEnds;
            this.userExclusions = userExclusions;
            this.mode = mode;
            this.limit = limit;
            this.costMultiple = costMultiple;
            this.excluded = excluded;
            this.seenSignatures = seenSignatures;
            this.routes = routes;
            this.bestRemaining = bestRemaining;
            this.catalog = catalog;
            this.unavailable = unavailable;
            this.seedCandidates = seedCandidates;
        }
    }

    private ResumeState resumeState;

    /**
     * The last completed generation's timing, for the GPS debug snapshot:
     * [wallMs, clientMs, rebuildMs, searchCpuMs, searches]. Null before the first generation.
     */
    private volatile long[] lastTimingSummary;

    long[] getLastTimingSummary() {
        long[] summary = lastTimingSummary;
        return summary == null ? null : summary.clone();
    }


    // Whether the last generation's cost cap held routes back — a higher cost multiple ("show more")
    // could surface them. False when walking is the binding ceiling (nothing cheaper-than-walk left).
    private volatile boolean lastGenerationMoreLikely = false;

    /**
     * The last built distance field and the inputs it was built from (plan step N4). A field is
     * immutable once built and a pure function of the target set, the usable transports (the
     * refresh fingerprint), the user exclusions, the synthesized sea legs and the flood horizon.
     * A player walking toward a pinned target regenerates every few tiles with all of those
     * unchanged, and used to flood the identical field each time (~200 ms per generation against
     * ~1 ms per guided search). Generation-thread only.
     */
    private DistanceField cachedField;
    private FieldKey cachedFieldKey;
    private volatile boolean lastFieldReused;

    /** Whether the last generation reused the previous generation's distance field. */
    boolean lastFieldReused() {
        return lastFieldReused;
    }

    private static final class FieldKey {
        private final long usableFingerprint;
        private final Set<TeleportMethod> userExclusions;
        private final long extrasFingerprint;
        private final Set<Integer> ends;
        private final int costMultiple;

        FieldKey(long usableFingerprint, Set<TeleportMethod> userExclusions, long extrasFingerprint,
            Set<Integer> ends, int costMultiple) {
            this.usableFingerprint = usableFingerprint;
            this.userExclusions = new HashSet<>(userExclusions);
            this.extrasFingerprint = extrasFingerprint;
            this.ends = new HashSet<>(ends);
            this.costMultiple = costMultiple;
        }

        /** Same inputs; a complete field (horizon at MAX) serves any cost multiple. */
        boolean sameInputs(FieldKey cached, boolean cachedComplete) {
            return cached != null
                && usableFingerprint == cached.usableFingerprint
                && extrasFingerprint == cached.extrasFingerprint
                && (costMultiple == cached.costMultiple || cachedComplete)
                && userExclusions.equals(cached.userExclusions)
                && ends.equals(cached.ends);
        }
    }

    /** Commutative content fingerprint of the synthesized sea legs (fresh objects every generation). */
    private static long extrasFingerprint(List<Transport> extras) {
        long fingerprint = 0;
        for (Transport extra : extras) {
            long key = ((long) extra.getOrigin() << 32) ^ (extra.getDestination() & 0xffffffffL);
            fingerprint += RoutingItemDependencies.mix64(key * 31 + extra.getDuration());
        }
        return fingerprint;
    }

    /** Whether raising the cost multiple and regenerating could surface more routes. */
    public boolean wasMoreLikely() {
        return lastGenerationMoreLikely;
    }

    /**
     * Per-generation timing breakdown: time blocked on the client thread, time rebuilding
     * availability off-thread, and time in the searches. Seed searches run in parallel, so their
     * rebuild/search nanos are CPU-summed across workers (can exceed wall time); accumulation from
     * worker threads synchronizes on this object.
     */
    private static final class GenTimer {
        private long clientNanos;
        private long rebuildNanos;
        private long searchNanos;
        private long fieldNanos;
        private int searches;
        private final List<SearchRecord> records = new ArrayList<>();
    }

    /**
     * One generation's shared state (plan step L2): the query, the page under construction and
     * the per-generation search inputs, handed to every pass instead of the ten-to-eighteen
     * parameter signatures that used to carry them, plus the one {@link #emit} that cannot forget
     * the staleness check. Mutable fields are written by the generation thread between passes.
     */
    private final class Generation {
        final int gen;
        final int start;
        final Set<Integer> ends;
        final Set<TeleportMethod> userExclusions;
        final AlternativeRoutesMode mode;
        final int limit;
        final int costMultiple;
        final boolean roundTrip;
        final ResultListener listener;
        final GenTimer timer;
        final List<TeleportMethod> catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable;
        final List<Transport> seedCandidates;
        final List<RouteOption> routes;
        final Set<String> seenSignatures;
        // State written by one phase and read by the next (generation thread only).
        /** The chain's exclusion set: the user's, grown by one primary per accepted route. */
        Set<TeleportMethod> excluded;
        /** Chain acceptances per shared tail, for the saturation filter (resumable). */
        Map<String, Integer> chainTailCounts;
        /** The synthesized sea legs of this generation (water pins, the helm). */
        List<Transport> seaLegs;
        /** The caller's targets before wilderness filtering (the resume key). */
        Set<Integer> rawTargets;
        /** Whether this generation continues a previous one ("+ more routes"). */
        boolean resumed;
        long wallStart;
        /** Whether the availability already matches {@link #excluded} for the chain's first search. */
        boolean availabilityCurrent;
        /** A complete field that never reached the start: every search would find nothing. */
        boolean targetProvablyUnreachable;
        AtomicInteger walkCeiling;
        Future<WalkResult> walkFuture;
        /** The cost cap held a route back (a wider band can reveal it). */
        boolean cappedByCost;
        /** The chain stopped on its own terms rather than on the route-count budget. */
        boolean chainExhausted;
        /** The generation's distance field, once built (null for an empty target set). */
        DistanceField field;
        /** Remaining distance of the first route's endpoint; -1 until the chain knows it. */
        int bestRemaining = -1;
        /** The cheapest pure-sail continuation seen at the helm (the keep-sailing baseline). */
        final java.util.concurrent.atomic.AtomicReference<RouteOption> bestSail =
            new java.util.concurrent.atomic.AtomicReference<>();

        Generation(int gen, int start, Set<Integer> ends, Set<TeleportMethod> userExclusions,
            AlternativeRoutesMode mode, int limit, int costMultiple, boolean roundTrip, ResultListener listener,
            GenTimer timer, List<TeleportMethod> catalog, Map<TeleportMethod, MethodAvailability> unavailable,
            List<Transport> seedCandidates, List<RouteOption> routes, Set<String> seenSignatures) {
            this.gen = gen;
            this.start = start;
            this.ends = ends;
            this.userExclusions = userExclusions;
            this.mode = mode;
            this.limit = limit;
            this.costMultiple = costMultiple;
            this.roundTrip = roundTrip;
            this.listener = listener;
            this.timer = timer;
            this.catalog = catalog;
            this.unavailable = unavailable;
            this.seedCandidates = seedCandidates;
            this.routes = routes;
            this.seenSignatures = seenSignatures;
        }

        /** Whether a newer generation has superseded this one. */
        boolean stale() {
            return gen != generation.get();
        }

        /**
         * The listener a one-way pass streams to: none in round-trip mode, which streams only
         * merged results (one-way costs would reorder once returns are added).
         */
        ResultListener oneWayListener() {
            return roundTrip ? null : listener;
        }
    }

    /**
     * One search's profile within a generation — which search ran, what it found, and how much it
     * explored — for the benchmark report and for pinpointing slow searches (the aggregate GenTimer
     * numbers can't tell a few expensive searches from many cheap ones).
     */
    static final class SearchRecord {
        final String label;
        final long cpuMs;
        /** Total cost of the found path, -1 when the search produced none. */
        final int resultCost;
        final boolean reached;
        final String termination;
        final int nodesChecked;
        final int transportsChecked;
        final boolean capped;
        final boolean astar;

        SearchRecord(String label, long cpuMs, int resultCost, boolean reached, String termination,
            int nodesChecked, int transportsChecked, boolean capped, boolean astar) {
            this.label = label;
            this.cpuMs = cpuMs;
            this.resultCost = resultCost;
            this.reached = reached;
            this.termination = termination;
            this.nodesChecked = nodesChecked;
            this.transportsChecked = transportsChecked;
            this.capped = capped;
            this.astar = astar;
        }
    }

    /** Appends one search's profile to the generation's records (seed workers call concurrently). */
    private static void record(GenTimer timer, String label, long searchNanos, Pathfinder pathfinder, int cap) {
        PathfinderResult result = pathfinder.getResult();
        Pathfinder.PathfinderStats stats = pathfinder.getStats();
        List<PathStep> path = result != null ? result.getPathSteps() : null;
        SearchRecord searchRecord = new SearchRecord(
            label,
            searchNanos / 1_000_000,
            (path != null && !path.isEmpty()) ? result.getTotalCost() : -1,
            result != null && result.isReached(),
            (result != null && result.getTerminationReason() != null) ? result.getTerminationReason().name() : "NONE",
            stats != null ? stats.getNodesChecked() : -1,
            stats != null ? stats.getTransportsChecked() : -1,
            cap != Integer.MAX_VALUE,
            pathfinder.isAstar());
        synchronized (timer) {
            timer.records.add(searchRecord);
        }
    }

    /**
     * The last completed generation's per-search profiles, slowest first. Empty before the first
     * generation. For the benchmark report.
     */
    List<SearchRecord> getLastSearchRecords() {
        List<SearchRecord> records = lastSearchRecords;
        return records == null ? List.of() : records;
    }

    private volatile List<SearchRecord> lastSearchRecords;

    /** Why the last generation's routes all stop short of the target (plan step N12). */
    public enum UnreachableCause {
        /** The page has a route that reaches the target (or there is no page). */
        NONE,
        /** Reachable with everything the game offers, not with this mode's items and unlocks. */
        MISSING_UNLOCKS,
        /** No known route in any mode: a sealed tile, or a gap in the map data. */
        NO_KNOWN_ROUTE
    }

    private volatile UnreachableCause lastUnreachableCause = UnreachableCause.NONE;

    public UnreachableCause lastUnreachableCause() {
        return lastUnreachableCause;
    }

    /**
     * Tells "not with what you have" from "no known route" for a page whose routes all stop
     * short: an all-everything planning copy is refreshed on the client thread and its distance
     * field flooded from the targets; the target is reachable with everything when that field
     * reaches the start or any teleport landing. Runs only for an unreached page in an owned
     * mode (the all mode already includes everything), so the probe costs nothing on a normal
     * generation.
     */
    private UnreachableCause unreachableCause(List<RouteOption> routes, int start, Set<Integer> ends,
        AlternativeRoutesMode mode) {
        if (routes.isEmpty() || ends.isEmpty())
            return UnreachableCause.NONE;
        for (RouteOption route : routes) {
            if (route.isReached())
                return UnreachableCause.NONE;
        }
        if (mode == AlternativeRoutesMode.ALL_EVERYTHING)
            return UnreachableCause.NO_KNOWN_ROUTE;
        PathfinderConfig probe = planningConfig.copyForPlanning();
        if (!refreshOnClientThread(probe, Collections.emptySet(), null, AlternativeRoutesMode.ALL_EVERYTHING))
            return UnreachableCause.NO_KNOWN_ROUTE;
        probe.rebuildAvailabilityWithExclusions(Collections.emptySet());
        DistanceField everything = DistanceField.buildIfCompact(probe, ends, 0);
        boolean reachableWithEverything = everything != null
            && SearchHeuristic.buildWithField(probe, everything, start) != null;
        return reachableWithEverything ? UnreachableCause.MISSING_UNLOCKS : UnreachableCause.NO_KNOWN_ROUTE;
    }

    /**
     * Seeds additional routes when the exclusion loop ended early: for each candidate global teleport
     * (best estimated arrival first), run one search with every OTHER global teleport excluded, so the
     * result is "the best route if you use this teleport". Routes with an already-seen method
     * signature, walk-only results, or endpoints meaningfully further than the best route are skipped.
     */
    private void seedTeleportRoutes(Generation g, int costCap) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final AlternativeRoutesMode mode = g.mode;
        final int limit = g.limit;
        final int costMultiple = g.costMultiple;
        final List<Transport> seedCandidates = g.seedCandidates;
        final List<RouteOption> routes = g.routes;
        final Set<String> seenSignatures = g.seenSignatures;
        final List<TeleportMethod> catalog = g.catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable = g.unavailable;
        final ResultListener listener = g.oneWayListener();
        final int bestRemaining = g.bestRemaining;
        final DistanceField field = g.field;
        final GenTimer timer = g.timer;
        final java.util.concurrent.atomic.AtomicReference<RouteOption> bestSail = g.bestSail;
        // Every global teleport is excluded from each seed search except the seed itself, so the
        // exclusion universe must span ALL candidates — including ones that don't get an attempt.
        final Set<TeleportMethod> allSeedMethods = new HashSet<>();
        for (Transport transport : seedCandidates)
            allSeedMethods.add(transport.method());

        // A floor of attempts even when the chain filled every slot: the best-ranked seeds are the
        // safety net against a missed-cheap-route bug, and cost nearly nothing when they lose.
        final int maxAttempts = Math.max(6, (limit - routes.size()) * 3);
        final List<Transport> attempts = rankSeedCandidates(seedCandidates, ends, userExclusions, maxAttempts);
        String nearestPortInfo = null;
        // Aboard, the closest-port disembark is ALWAYS attempted: cheap teleports outrank
        // every port seed and the ranking silently dropped them all (field capture 225140 —
        // ten teleport routes, zero "park the boat" options). One guaranteed attempt keeps
        // the promise that docking properly is always on the card.
        if (planningConfig.isOnSailingBoat()) {
            Transport nearestPort = null;
            for (Transport candidate : seedCandidates) {
                if (candidate.getDisplayInfo() != null
                    && candidate.getDisplayInfo().startsWith("Disembark")
                    && (nearestPort == null || candidate.getDuration() < nearestPort.getDuration())) {
                    nearestPort = candidate;
                }
            }
            if (nearestPort != null && !attempts.contains(nearestPort)) {
                if (attempts.size() >= maxAttempts && !attempts.isEmpty())
                    attempts.remove(attempts.size() - 1);
                attempts.add(nearestPort);
            }
            nearestPortInfo = nearestPort != null ? nearestPort.getDisplayInfo() : null;
        }
        if (attempts.isEmpty())
            return;

        // One config per concurrent worker (shares immutable data + the refreshed state); the seed
        // searches are independent, so they run in parallel on the seed pool. Results are collected
        // and accepted on this (generation) thread in completion order.
        final int workers = Math.min(SEED_POOL_SIZE, attempts.size());
        final Queue<PathfinderConfig> configPool = new ConcurrentLinkedQueue<>();
        for (int i = 0; i < workers; i++)
            configPool.add(planningConfig.copyForParallelSearch());
        final AtomicBoolean stop = new AtomicBoolean(false);
        final String nearestPortRetained = nearestPortInfo;
        final CompletionService<SeedResult> completion = new ExecutorCompletionService<>(seedExecutor);
        final List<Future<SeedResult>> futures = new ArrayList<>(attempts.size());
        for (Transport seed : attempts) {
            futures.add(completion.submit(() ->
                runSeedSearch(g, stop, allSeedMethods, seed,
                    nearestPortRetained != null && nearestPortRetained.equals(seed.getDisplayInfo()),
                    costCap, configPool)));
        }

        try {
            // Results are collected first and accepted in a DETERMINISTIC order (cost, then
            // signature), not completion order: the page-fill ceiling ratchets as routes are
            // accepted, so completion order (JIT warmth, load) decided which seeds made the page
            // and the same query produced different pages run to run (plan step N10; the seeds
            // take milliseconds each, so nothing is lost by waiting for all of them).
            List<SeedResult> results = new ArrayList<>(futures.size());
            for (int i = 0; i < futures.size() && gen == generation.get(); i++) {
                try {
                    SeedResult seedResult = completion.take().get();
                    if (seedResult != null)
                        results.add(seedResult);
                }
                catch (ExecutionException e) {
                    log.warn("Seed search failed", e);
                }
            }
            results.sort(Comparator.comparingInt((SeedResult r) -> r.totalCost)
                .thenComparing(r -> signature(r.scan.methods)));
            for (SeedResult seedResult : results) {
                if (gen != generation.get())
                    break;
                // Same hybrid acceptance as the chain: a seed beyond the page-fill ceiling isn't shown
                // (skip, not stop — seeds complete in parallel, a later one can be cheaper). Checked
                // BEFORE the signature is consumed: a cost-rejected seed must stay eligible for a
                // widened re-run ("+"), which resumes with this generation's seenSignatures.
                // The nearest-port disembark is the walk fallback's sea twin: docking properly
                // is ALWAYS on the card when aboard, however cheap the teleports are. It is
                // exempt from the cost band and, below, evicts the costliest teleport route
                // even when every shown route is cheaper (finding 4: the seed always ran but
                // its route died here, and the service test caught the gap the field saw).
                boolean portPromise = nearestPortRetained != null
                    && !seedResult.scan.methods.isEmpty()
                    && nearestPortRetained.equals(seedResult.scan.methods.get(0).getDisplayInfo())
                    && !RouteAcceptance.hasPortFirstRoute(routes);
                // At the helm the cheapest PURE-SAIL continuation is a protected baseline (the
                // walk route's sibling): the cost band otherwise culls every keep-sailing option
                // while cheap disembark-teleport chains fill the page (capture 20260829-204334),
                // leaving a sailor mid-task with no sea route at all.
                if (planningConfig.isOnSailingBoat() && seedResult.reached
                    && isPureSail(seedResult.scan.methods)) {
                    RouteOption prior = bestSail.get();
                    if (prior == null || seedResult.totalCost < prior.getTotalCost()) {
                        bestSail.set(new RouteOption(withoutIdleBankFlip(seedResult.path, seedResult.scan),
                            seedResult.scan.methods, seedResult.scan.methodEdges,
                            seedResult.scan.methodDurations, seedResult.totalCost, seedResult.scan.rawCost,
                            true, seedResult.scan.bankGated, seedResult.scan.walkBefore,
                            seedResult.scan.trailingWalk));
                    }
                }
                if (!portPromise && RouteAcceptance.beyondBand(seedResult.totalCost, routes, costMultiple))
                    continue;
                // The port promise IS a detour with the same ending (Disembark + the teleport
                // the bare route uses) — the nesting filter would always drop it.
                if (!portPromise && RouteAcceptance.nestsAKeptRoute(seedResult.scan.methods,
                    !seedResult.scan.bankGated.isEmpty(), routes)) {
                    continue;
                }
                if (RouteAcceptance.hasRedundantTeleportHop(hopBaselineTeleports, seedResult.scan.methods))
                    continue;
                if (!seenSignatures.add(signature(seedResult.scan.methods)))
                    continue;
                // A full list doesn't end the pass: a strictly cheaper seed evicts the costliest
                // teleport route — the seeds are the safety net for anything the chain missed.
                if (routes.size() >= limit) {
                    // The walk baseline is evict-proof only when there is a LIST to anchor: in
                    // overlay-only mode (panel closed, limit 1) the single route must be the best
                    // route, or a slow walk permanently shadows a cheap sea leg (field report:
                    // 7-minute walk shown while a 131-cost sail existed). The port promise may
                    // evict any cost; every other seed only a strictly costlier route.
                    int evict = RouteAcceptance.evictionIndex(routes, portPromise ? -1 : seedResult.totalCost,
                        r -> limit == 1 || !r.isWalkOnly());
                    if (evict < 0)
                        continue;
                    routes.remove(evict);
                }
                routes.add(new RouteOption(withoutIdleBankFlip(seedResult.path, seedResult.scan),
                    seedResult.scan.methods, seedResult.scan.methodEdges,
                    seedResult.scan.methodDurations, seedResult.totalCost, seedResult.scan.rawCost,
                    seedResult.reached, seedResult.scan.bankGated, seedResult.scan.walkBefore,
                    seedResult.scan.trailingWalk));
                emit(gen, listener, new ArrayList<>(routes), catalog, unavailable, false);
            }
        }
        catch (InterruptedException e) {
            // Interruption means shutdown/cancellation: just stop. (The plugin hub disallows
            // Thread::interrupt, so the flag is not restored; this generation thread is ours and
            // nothing downstream reads it.)
        }
        finally {
            stop.set(true);
            for (Future<SeedResult> future : futures)
                future.cancel(false);
        }
    }

    /**
     * Selects and orders the seed-teleport attempt list: user-excluded methods and duplicate landings
     * (e.g. tab vs spell to the same tile) are dropped, the rest are ranked by estimated arrival cost
     * — the teleport's cast/travel duration (in {@link CostUnits}) plus the straight-line distance
     * from its landing to the NEAREST target (a lower bound of the remaining run, in the same
     * currency) — and the list is capped at {@code maxAttempts}. Ranking against the whole target set
     * matters for multi-target queries ("nearest bank" has ~150): a teleport landing beside a distant
     * bank is an excellent seed, but measured against only the player's local bank it would rank last
     * and be cut by the cap.
     * <p>
     * Candidates landing farther than the start are deliberately KEPT: when an obstacle separates the
     * start from the target, the straight-line start distance understates the real walk, and a
     * teleport landing "farther" can be much closer by path (it also keeps cross-plane landings,
     * where the straight-line distance is unknowable). Ranking tries them last and the attempt cap
     * bounds the work, so this costs nothing when closer candidates exist. Each attempt is priced by
     * a full search afterwards — this pre-selection never decides a shown cost, only which candidates
     * get a search.
     */
    static List<Transport> rankSeedCandidates(List<Transport> seedCandidates, Set<Integer> targets,
        Set<TeleportMethod> userExclusions, int maxAttempts) {
        final List<Transport> ranked = new ArrayList<>(seedCandidates);
        // Long arithmetic: a cross-plane landing has straight-line distance Integer.MAX_VALUE, which
        // must rank last rather than overflow into ranking first.
        final int[] targetArray = new int[targets.size()];
        int t = 0;
        for (int target : targets)
            targetArray[t++] = target;
        ranked.sort(Comparator.comparingLong(
            candidate -> (long) CostUnits.fromTicks(candidate.getDuration())
                + distanceToNearest(candidate.getDestination(), targetArray)));
        final Map<Integer, Transport> byDestination = new LinkedHashMap<>();
        for (Transport transport : ranked) {
            if (userExclusions.contains(transport.method()))
                continue;
            byDestination.putIfAbsent(transport.getDestination(), transport);
        }
        final List<Transport> attempts = new ArrayList<>(Math.max(0, Math.min(maxAttempts, byDestination.size())));
        for (Transport seed : byDestination.values()) {
            if (attempts.size() >= maxAttempts)
                break;
            attempts.add(seed);
        }
        return attempts;
    }

    /** Straight-line distance from a landing to its nearest target (MAX_VALUE across planes). */
    private static int distanceToNearest(int packedPoint, int[] targets) {
        int best = Integer.MAX_VALUE;
        for (int target : targets)
            best = Math.min(best, distanceBetween(packedPoint, target));
        return best;
    }

    /** A tail shared by this many kept routes triggers the diversity pass. */

    private static final int TAIL_DOMINANCE = 3;
    /** At most this many extra searches per generation, one per shared-tail method. */
    private static final int TAIL_DIVERSITY_SEARCHES = 2;

    /** The signature of everything after the primary, or null when there is no tail. */
    private static String tailSignature(List<TeleportMethod> methods) {
        return methods.size() < 2 ? null : signature(methods.subList(1, methods.size()));
    }

    /**
     * Tail-diversity pass (captures 20260823-230534, 20260824-183101): the exclusion chain only
     * varies each route's PRIMARY method, and exclusions accumulate — so when every cheap route
     * shares a tail (bank teleport + "Salve graveyard tablet + fairy ring", with the staff banked),
     * the page fills with first-leg variants, and a route that shares a kept PRIMARY but differs in
     * the middle (Ardougne cloak to the monastery ring) can never be generated: its primary is
     * already spent. When one tail dominates the page, this pass runs a couple of fresh searches
     * with ONLY the user's exclusions plus one shared-tail method — primaries deliberately come
     * back — and feeds any distinct result through the exact acceptance the seeds use, evicting
     * the costliest member of the dominant family when the page is full.
     */
    private void diversifySharedTails(Generation g, int costCap) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final int limit = g.limit;
        final int costMultiple = g.costMultiple;
        final List<RouteOption> routes = g.routes;
        final Set<String> seenSignatures = g.seenSignatures;
        final List<TeleportMethod> catalog = g.catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable = g.unavailable;
        final ResultListener listener = g.oneWayListener();
        final int bestRemaining = g.bestRemaining;
        final DistanceField field = g.field;
        final GenTimer timer = g.timer;
        // The dominant tail among the kept routes.
        Map<String, List<RouteOption>> byTail = new LinkedHashMap<>();
        for (RouteOption route : routes) {
            String tail = tailSignature(route.getMethods());
            if (tail != null)
                byTail.computeIfAbsent(tail, k -> new ArrayList<>()).add(route);
        }
        String dominantTail = null;
        List<RouteOption> family = null;
        for (Map.Entry<String, List<RouteOption>> entry : byTail.entrySet()) {
            if (family == null || entry.getValue().size() > family.size()) {
                dominantTail = entry.getKey();
                family = entry.getValue();
            }
        }
        if (family == null || family.size() < TAIL_DOMINANCE)
            return;

        List<TeleportMethod> sharedTail = family.get(0).getMethods();
        sharedTail = sharedTail.subList(1, sharedTail.size());
        int searches = 0;
        for (TeleportMethod shared : sharedTail) {
            if (searches >= TAIL_DIVERSITY_SEARCHES || gen != generation.get())
                break;
            if (userExclusions.contains(shared))
                continue;
            searches++;
            PathfinderConfig config = planningConfig.copyForParallelSearch();
            Set<TeleportMethod> exclusions = new HashSet<>(userExclusions);
            exclusions.add(shared);
            long rebuildStart = System.nanoTime();
            config.rebuildAvailabilityWithExclusions(exclusions);
            long searchStart = System.nanoTime();
            SearchHeuristic heuristic = SearchHeuristic.buildWithField(config, field, start);
            Pathfinder pathfinder = new Pathfinder(config, start, ends, costCap, heuristic);
            pathfinder.run();
            long searchEnd = System.nanoTime();
            synchronized (timer) {
                timer.rebuildNanos += searchStart - rebuildStart;
                timer.searchNanos += searchEnd - searchStart;
                timer.searches++;
            }
            record(timer, "tail:" + shared.label(), searchEnd - searchStart, pathfinder, costCap);

            PathfinderResult result = pathfinder.getResult();
            List<PathStep> path = (result != null) ? result.getPathSteps() : List.of();
            if (result == null || path.isEmpty())
                continue;
            boolean reached = result.isReached();
            int remaining = reached ? 0 : remainingDistance(path, ends);
            if (RouteAcceptance.tooFar(reached, remaining, bestRemaining))
                continue;
            final int totalCost = result.getTotalCost();
            if (RouteAcceptance.beyondBand(totalCost, routes, costMultiple))
                continue;
            MethodScan scan = scanMethods(config, path);
            if (scan.methods.isEmpty()
                || RouteAcceptance.nestsAKeptRoute(scan.methods, !scan.bankGated.isEmpty(), routes)
                || RouteAcceptance.hasRedundantTeleportHop(hopBaselineTeleports, scan.methods)
                || !seenSignatures.add(signature(scan.methods))) {
                continue;
            }
            if (routes.size() >= limit) {
                // The whole point: the slot comes out of the over-represented family.
                final String familyTail = dominantTail;
                int evict = RouteAcceptance.evictionIndex(routes, -1,
                    kept -> !kept.isWalkOnly() && familyTail.equals(tailSignature(kept.getMethods())));
                if (evict < 0)
                    continue;
                routes.remove(evict);
            }
            routes.add(new RouteOption(withoutIdleBankFlip(path, scan), scan.methods, scan.methodEdges,
                scan.methodDurations, totalCost, scan.rawCost, reached, scan.bankGated,
                scan.bankGatedTransports, scan.walkBefore, scan.trailingWalk));
            emit(gen, listener, new ArrayList<>(routes), catalog, unavailable, false);
        }
    }

    private SeedResult runSeedSearch(Generation g, AtomicBoolean stop, Set<TeleportMethod> allSeedMethods,
        Transport seed, boolean portPromiseSeed, int costCap, Queue<PathfinderConfig> configPool) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final int bestRemaining = g.bestRemaining;
        final DistanceField field = g.field;
        final GenTimer timer = g.timer;
        if (gen != generation.get() || stop.get())
            return null;
        // Unreached-target seeds are uninformed sweeps too — same budget as the chain, checked as
        // each queued seed comes up so a long tail of pending seeds drains cheaply.
        if (bestRemaining > 0 && searchBudgetExhausted(timer))
            return null;
        PathfinderConfig config = configPool.poll();
        if (config == null)
            // Should not happen (pool size == max concurrency), but never block on it.
            config = planningConfig.copyForParallelSearch();
        try {
            // Exclude every other global teleport so the search is forced onto (at most) this one.
            Set<TeleportMethod> seedExclusions = new HashSet<>(allSeedMethods);
            seedExclusions.remove(seed.method());
            seedExclusions.addAll(userExclusions);
            // The port-promise seed forces its port by excluding only the OTHER sailing
            // seeds; teleports stay usable but position-gated off the water start, so the
            // route is 'Disembark at the nearest port, then the best of everything'.
            config.portPromiseSearch = portPromiseSeed;
            Set<TeleportMethod> effectiveExclusions = seedExclusions;
            if (portPromiseSeed) {
                effectiveExclusions = new HashSet<>();
                for (TeleportMethod method : seedExclusions) {
                    if (!method.getType().isTeleport())
                        effectiveExclusions.add(method);
                }
            }
            long rebuildStart = System.nanoTime();
            config.rebuildAvailabilityWithExclusions(effectiveExclusions);
            long searchStart = System.nanoTime();
            // Seed searches exclude every other global teleport, so the floor comes from the seed
            // itself and the search's own optimal route uses it — strongly directed by
            // construction, and the walk-cost cap bounds any residue.
            SearchHeuristic heuristic = SearchHeuristic.buildWithField(config, field, start);
            Pathfinder pathfinder = new Pathfinder(config, start, ends, costCap, heuristic);
            pathfinder.run();
            long searchEnd = System.nanoTime();
            synchronized (timer) {
                timer.rebuildNanos += searchStart - rebuildStart;
                timer.searchNanos += searchEnd - searchStart;
                timer.searches++;
            }
            String seedLabel = seed.getDisplayInfo() != null && !seed.getDisplayInfo().isEmpty()
                ? seed.getDisplayInfo()
                : WorldPointUtil.unpackWorldX(seed.getDestination()) + "," + WorldPointUtil.unpackWorldY(seed.getDestination());
            record(timer, "seed:" + seedLabel, searchEnd - searchStart, pathfinder, costCap);

            PathfinderResult result = pathfinder.getResult();
            List<PathStep> path = (result != null) ? result.getPathSteps() : List.of();
            if (result == null || path.isEmpty())
                return null;
            boolean reached = result.isReached();
            int remaining = reached ? 0 : remainingDistance(path, ends);
            if (RouteAcceptance.tooFar(reached, remaining, bestRemaining))
                return null;
            MethodScan scan = scanMethods(config, path);
            if (scan.methods.isEmpty())
                // Walk-only: the seed teleport didn't help.
                return null;
            return new SeedResult(path, scan, result.getTotalCost(), reached);
        }
        finally {
            config.portPromiseSearch = false;
            configPool.offer(config);
        }
    }

    /**
     * The walk-only search: every method in the catalog excluded (plain connectors — doors, stairs,
     * shortcuts — remain, walking uses those). Its reached cost is the universal search cap, and its
     * path is the last-resort route. Runs on the seed pool concurrently with the chain's first
     * searches, on its own config copy.
     */
    private WalkResult runWalkSearch(Generation g, AtomicInteger walkCeiling) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<Integer> ends = g.ends;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final List<TeleportMethod> catalog = g.catalog;
        final DistanceField field = g.field;
        final GenTimer timer = g.timer;
        if (gen != generation.get())
            return null;
        PathfinderConfig config = planningConfig.copyForParallelSearch();
        Set<TeleportMethod> walkExclusions = new HashSet<>(catalog);
        walkExclusions.addAll(userExclusions);
        long rebuildStart = System.nanoTime();
        config.rebuildAvailabilityWithExclusions(walkExclusions);
        long searchStart = System.nanoTime();
        // With every method excluded the floor is effectively unbounded, so h is the raw field —
        // the walk search (the biggest disc of the generation) collapses to a corridor.
        SearchHeuristic heuristic = SearchHeuristic.buildWithField(config, field, start);
        Pathfinder pathfinder = new Pathfinder(config, start, ends, Integer.MAX_VALUE, heuristic);
        pathfinder.setDynamicCostCap(walkCeiling::get);
        pathfinder.run();
        long searchEnd = System.nanoTime();
        synchronized (timer) {
            timer.rebuildNanos += searchStart - rebuildStart;
            timer.searchNanos += searchEnd - searchStart;
            timer.searches++;
        }
        record(timer, "walk", searchEnd - searchStart, pathfinder, Integer.MAX_VALUE);

        PathfinderResult result = pathfinder.getResult();
        List<PathStep> path = (result != null) ? result.getPathSteps() : List.of();
        if (result == null || path.isEmpty())
            return null;
        MethodScan scan = scanMethods(config, path);
        if (!scan.methods.isEmpty()) {
            // Aboard, the catalog-wide exclusion leaves the SAILING legs untouched (sea legs are
            // not catalog methods), so this search naturally yields the KEEP-SAILING route: sail
            // to the port nearest the target and walk ashore. That is the baseline a sailor
            // wants surfaced (capture 20260829-204334: every page slot was a disembark-teleport
            // chain and the band culled all keep-sailing options), not a defect - return it,
            // and its cost still serves as the universal ceiling. Any NON-sailing method here
            // remains a defect and must not become the walk cap or route.
            if (!(planningConfig.isOnSailingBoat() && isPureSail(scan.methods)))
                return null;
        }
        boolean reached = result.isReached();
        RouteOption route = new RouteOption(withoutIdleBankFlip(path, scan), scan.methods, scan.methodEdges, scan.methodDurations,
            result.getTotalCost(), scan.rawCost, reached, scan.bankGated, scan.bankGatedTransports, scan.walkBefore, scan.trailingWalk);
        // Only a walk that actually reaches the target is a valid cost ceiling; a closest-tile
        // partial walk (island target) must not constrain teleport routes that can truly get there.
        int cap = reached ? result.getTotalCost() : Integer.MAX_VALUE;
        return new WalkResult(route, cap, reached ? 0 : remainingDistance(path, ends));
    }

    /**
     * Extends each one-way route with its return leg: one search from the route's endpoint back to
     * the start — all sharing a single start-rooted distance field — the two paths concatenated and
     * re-scanned so methods, directions and progress work on the whole loop, then re-ranked by
     * combined cost. The best round-trip destination is not necessarily the nearest one-way one.
     * In bank mode the return leg naturally gets the banked-state teleports: the leg starts ON a
     * bank tile, so the engine flips into the banked state immediately.
     */
    private List<RouteOption> buildRoundTrips(Generation g, List<RouteOption> oneWays) {
        final int gen = g.gen;
        final int start = g.start;
        final Set<TeleportMethod> userExclusions = g.userExclusions;
        final List<TeleportMethod> catalog = g.catalog;
        final Map<TeleportMethod, MethodAvailability> unavailable = g.unavailable;
        final ResultListener listener = g.listener;
        final GenTimer timer = g.timer;
        final Set<Integer> home = Set.of(start);
        long fieldStart = System.nanoTime();
        // Return legs run uncapped, so keep the full flood here (a bounded one would stay correct
        // but could slow the uncapped searches); round-trip mode is the rare path.
        final DistanceField returnField = DistanceField.buildIfCompact(planningConfig, home, 0);
        timer.fieldNanos += System.nanoTime() - fieldStart;

        // Return searches run with the base availability (user exclusions only): the chain left
        // planningConfig with its last exclusion set.
        long rebuildStart = System.nanoTime();
        planningConfig.rebuildAvailabilityWithExclusions(userExclusions);
        timer.rebuildNanos += System.nanoTime() - rebuildStart;
        final SearchHeuristic heuristic = SearchHeuristic.buildWithField(planningConfig, returnField);

        final List<RouteOption> merged = new ArrayList<>();
        final Set<String> signatures = new HashSet<>();
        for (RouteOption oneWay : oneWays) {
            if (gen != generation.get())
                return merged;
            final List<PathStep> outPath = oneWay.getPath();
            final int endpoint = outPath.get(outPath.size() - 1).getPackedPosition();
            long searchStart = System.nanoTime();
            Pathfinder back = new Pathfinder(planningConfig, endpoint, home, Integer.MAX_VALUE, heuristic);
            back.run();
            long searchNanos = System.nanoTime() - searchStart;
            synchronized (timer) {
                timer.searchNanos += searchNanos;
                timer.searches++;
            }
            record(timer, "return:" + WorldPointUtil.unpackWorldX(endpoint)
                + "," + WorldPointUtil.unpackWorldY(endpoint), searchNanos, back, Integer.MAX_VALUE);

            PathfinderResult result = back.getResult();
            List<PathStep> returnPath = (result != null) ? result.getPathSteps() : List.of();
            if (result == null || returnPath.isEmpty() || !result.isReached())
                continue;
            // Concatenate, dropping the duplicated endpoint tile, and re-derive the method scan
            // over the whole loop so edges/durations/legs are consistent for the overlay.
            List<PathStep> fullPath = new ArrayList<>(outPath);
            // The return leg's cumulative costs continue from the outbound total, so the loop's
            // steps carry one monotone cost line (the overlay's ETA table reads it).
            for (PathStep step : returnPath.subList(Math.min(1, returnPath.size()), returnPath.size())) {
                fullPath.add(step.getCost() == PathStep.UNKNOWN_COST ? step
                    : new PathStep(step.getPackedPosition(), step.isBankVisited(), step.getCost() + oneWay.getTotalCost()));
            }
            MethodScan scan = scanMethods(planningConfig, fullPath);
            if (!signatures.add(signature(scan.methods))
                || RouteAcceptance.hasRedundantTeleportHop(hopBaselineTeleports, scan.methods)) {
                continue;
            }
            // The turnaround is the outbound path's last tile (the destination); the return leg's
            // duplicated first step was dropped, so outbound indexes are unshifted in fullPath.
            merged.add(new RouteOption(withoutIdleBankFlip(fullPath, scan), scan.methods, scan.methodEdges, scan.methodDurations,
                oneWay.getTotalCost() + result.getTotalCost(), scan.rawCost, oneWay.isReached(),
                scan.bankGated, scan.bankGatedTransports, scan.walkBefore, scan.trailingWalk, outPath.size() - 1));
            merged.sort(Comparator.comparingInt(RouteOption::getTotalCost));
            emit(gen, listener, new ArrayList<>(merged), catalog, unavailable, false);
        }
        return merged;
    }

    /**
     * Search-CPU budget for UNREACHED targets (sealed cells, through-the-bars NPC tiles): with
     * the heuristic degenerate, every chain route and seed costs an uninformed sweep — the page
     * fills with whatever the budget affords (fast machines get more escapes, slow ones fewer)
     * instead of enumerating the whole teleport catalog. "+" resumes with a fresh budget.
     */
    private static final long UNREACHED_SEARCH_BUDGET_NANOS = 4_000_000_000L;
    /** Cumulative search CPU spent this generation vs the unreached-target budget. */
    private static boolean searchBudgetExhausted(GenTimer timer) {
        synchronized (timer) {
            return timer.searchNanos >= UNREACHED_SEARCH_BUDGET_NANOS;
        }
    }

    private static int capOf(Future<WalkResult> walkFuture) {
        if (walkFuture == null || !walkFuture.isDone())
            return Integer.MAX_VALUE;
        try {
            WalkResult walk = walkFuture.get();
            return walk == null ? Integer.MAX_VALUE : walk.cap;
        }
        catch (InterruptedException e) {
            // Shutdown/cancellation: uncapped is always safe. (Hub rule: no Thread::interrupt.)
            return Integer.MAX_VALUE;
        }
        catch (ExecutionException e) {
            log.warn("Walk search failed", e);
            return Integer.MAX_VALUE;
        }
    }

    /** The finished walk search's result, waiting for it if needed (used once, at generation end). */
    private static WalkResult walkResult(Future<WalkResult> walkFuture) {
        if (walkFuture == null)
            return null;
        try {
            return walkFuture.get();
        }
        catch (InterruptedException e) {
            // Shutdown/cancellation: no walk route to append. (Hub rule: no Thread::interrupt.)
            return null;
        }
        catch (ExecutionException e) {
            log.warn("Walk search failed", e);
            return null;
        }
    }

    /** The walk-only search's route, its cost cap for other searches, and its closeness to the target. */
    private static final class WalkResult {
        private final RouteOption route;
        private final int cap;
        private final int remaining;

        WalkResult(RouteOption route, int cap, int remaining) {
            this.route = route;
            this.cap = cap;
            this.remaining = remaining;
        }
    }

    /**
     * A candidate route produced by one parallel seed search, before signature dedup on the
     * generation thread.
     */
    private static final class SeedResult {
        private final List<PathStep> path;
        private final MethodScan scan;
        private final int totalCost;
        private final boolean reached;

        SeedResult(List<PathStep> path, MethodScan scan, int totalCost, boolean reached) {
            this.path = path;
            this.scan = scan;
            this.totalCost = totalCost;
            this.reached = reached;
        }
    }

    private static int remainingDistance(List<PathStep> path, Set<Integer> targets) {
        int end = path.get(path.size() - 1).getPackedPosition();
        int best = Integer.MAX_VALUE;
        for (int target : targets)
            best = Math.min(best, distanceBetween(end, target));
        return best;
    }

    private void emit(int gen, ResultListener listener, List<RouteOption> routes,
        List<TeleportMethod> catalog, Map<TeleportMethod, MethodAvailability> unavailable, boolean done) {
        // A null listener means streaming is suppressed for this phase (round-trip mode streams
        // only merged results).
        if (listener != null && gen == generation.get())
            listener.onUpdate(routes, catalog, unavailable, done);
    }

    /**
     * Runs {@code setExcludedMethods + refresh} (and, when {@code endsToFilter} is non-null, target
     * wilderness filtering) on the client thread and blocks the worker until it completes.
     *
     * @return false if the client thread did not run the task within the timeout.
     */
    private boolean refreshOnClientThread(Set<TeleportMethod> excluded, Set<Integer> endsToFilter, AlternativeRoutesMode mode) {
        return refreshOnClientThread(planningConfig, excluded, endsToFilter, mode);
    }

    private boolean refreshOnClientThread(PathfinderConfig target, Set<TeleportMethod> excluded,
        Set<Integer> endsToFilter, AlternativeRoutesMode mode) {
        final Set<TeleportMethod> excludedSnapshot = new HashSet<>(excluded);
        final CountDownLatch latch = new CountDownLatch(1);
        clientThread.invokeLater(() -> {
            try {
                target.setPlanningMode(mode == AlternativeRoutesMode.ALL_EVERYTHING);
                target.setBypassItemPossession(!mode.isOwned());
                target.setConsiderBank(mode == AlternativeRoutesMode.OWNED_WITH_BANK);
                target.setExcludedMethods(excludedSnapshot);
                target.refresh();
                if (endsToFilter != null)
                    target.filterLocations(endsToFilter, true);
            }
            finally {
                latch.countDown();
            }
        });
        try {
            if (!latch.await(CLIENT_THREAD_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
                log.warn("Timed out waiting for planning config refresh on client thread");
                return false;
            }
            return true;
        }
        catch (InterruptedException e) {
            // Shutdown/cancellation while waiting on the client thread; the generation aborts.
            // (Hub rule: no Thread::interrupt.)
            return false;
        }
    }

    /**
     * Derives the ordered list of teleport/transport methods a path uses, by inspecting each edge for
     * a method-type transport (anything beyond plain walking connectors) whose destination matches.
     * Also collects which of those methods are bank-gated (only available in the post-bank state), i.e.
     * the route walks to a bank to withdraw that method's required item first — so the panel can say
     * which method the bank detour is for.
     */
    private MethodScan scanMethods(PathfinderConfig config, List<PathStep> path) {
        List<TeleportMethod> methods = new ArrayList<>();
        List<Integer> methodEdges = new ArrayList<>();
        List<Integer> methodDurations = new ArrayList<>();
        Set<TeleportMethod> bankGated = new LinkedHashSet<>();
        // Plain connectors (jungle bushes, a dig, a locked door) that ALSO only became usable
        // after the bank: not methods, so never on the card - but the withdraw step must name
        // their item or the route silently assumes a bank stop (issue #21: the machete).
        List<Transport> bankGatedTransports = new ArrayList<>();
        if (path == null)
            return new MethodScan(methods, methodEdges, methodDurations, bankGated, bankGatedTransports, 0, new ArrayList<>(), 0);
        int rawCost = 0;
        // Walking-leg lengths: tiles walked before each method (parallel to `methods`), and after the
        // last one. Plain connectors (doors, stairs, shortcuts) count into the leg they sit in.
        List<Integer> walkBefore = new ArrayList<>();
        int legSteps = 0;
        for (int i = 1; i < path.size(); i++) {
            PathStep from = path.get(i - 1);
            PathStep to = path.get(i);
            boolean bankVisited = from.isBankVisited() || to.isBankVisited();
            Transport chosen = matchMethodTransport(config, from.getPackedPosition(), to.getPackedPosition(), bankVisited);
            if (chosen != null) {
                TeleportMethod method = chosen.method();
                methods.add(method);
                methodEdges.add(i);
                methodDurations.add(chosen.getDuration());
                walkBefore.add(legSteps);
                legSteps = 0;
                // Bank-gated: used in the post-bank state and not available without the bank.
                if (bankVisited && !availableWithoutBank(config, from.getPackedPosition(), chosen))
                    bankGated.add(method);
            }
            // Raw cost: what the edge costs without any configured weights, in CostUnits (run-tiles) —
            // a transport edge counts its travel time normalized to units, a walking edge its tile
            // distance (mirrors the search's own cost accumulation minus the additional/weight terms).
            // With no weights the route's rawCost IS its ETA in units, so cost order == ETA order.
            Transport edgeTransport = chosen != null
                ? chosen
                : matchAnyTransport(config, from.getPackedPosition(), to.getPackedPosition(), bankVisited);
            if (chosen == null && edgeTransport != null && bankVisited
                && edgeTransport.getItemRequirements() != null
                && !availableWithoutBank(config, from.getPackedPosition(), edgeTransport)) {
                bankGatedTransports.add(edgeTransport);
            }
            int edgeCost = edgeTransport != null
                ? CostUnits.fromTicks(edgeTransport.getDuration())
                : distanceBetween(from.getPackedPosition(), to.getPackedPosition());
            rawCost += edgeCost;
            if (chosen == null)
                legSteps += edgeCost;
        }
        return new MethodScan(methods, methodEdges, methodDurations, bankGated, bankGatedTransports, rawCost, walkBefore, legSteps);
    }

    /**
     * A bank flip that unlocked nothing is not a bank stop (issues #20 / #7). The search may
     * enter the banked state on a bank tile the path merely crosses; when no method and no
     * connector after it needed a banked item, the flip is noise — and downstream a banked step
     * READS as a withdrawal (the overlay's pickup hint and bank glyph, the capture JSON). The
     * flags are cleared in place of the steps; no step is dropped, so the scan's edge indexes
     * still line up with the path.
     */
    static List<PathStep> withoutIdleBankFlip(List<PathStep> path, MethodScan scan) {
        if (path == null || !scan.bankGated.isEmpty() || !scan.bankGatedTransports.isEmpty())
            return path;
        boolean flipped = false;
        for (PathStep step : path) {
            if (step.isBankVisited()) {
                flipped = true;
                break;
            }
        }
        if (!flipped)
            return path;
        List<PathStep> plain = new ArrayList<>(path.size());
        for (PathStep step : path)
            plain.add(step.isBankVisited() ? new PathStep(step.getPackedPosition(), false, step.getCost()) : step);
        return plain;
    }

    private static boolean availableWithoutBank(PathfinderConfig config, int origin, Transport transport) {
        for (Transport candidate : config.getTransportsPacked(false)
            .getOrDefault(origin, TransportAvailability.EMPTY_TRANSPORTS)) {
            if (candidate == transport)
                return true;
        }
        for (Transport candidate : config.getUsableTeleports(false)) {
            if (candidate == transport)
                return true;
        }
        return false;
    }

    private static final class MethodScan {
        private final List<TeleportMethod> methods;
        // Path index of the edge each method sits on (parallel to methods): the index of the step the
        // method arrives at. Authoritative for the directions overlay, which cannot re-derive methods
        // against the main config (the route came from the planning config's availability).
        private final List<Integer> methodEdges;
        // Travel time of each method's transport in game ticks (parallel to methods), for ETAs.
        private final List<Integer> methodDurations;
        private final Set<TeleportMethod> bankGated;
        private final List<Transport> bankGatedTransports;
        // Path cost without any configured weights, in CostUnits (run-tiles, 0.3s each): walk
        // distance plus time-normalized transport travel times. This is the route's ETA.
        private final int rawCost;
        // Tiles walked before each method (parallel to methods) and after the last one.
        private final List<Integer> walkBefore;
        private final int trailingWalk;

        MethodScan(List<TeleportMethod> methods, List<Integer> methodEdges, List<Integer> methodDurations,
            Set<TeleportMethod> bankGated, List<Transport> bankGatedTransports, int rawCost,
            List<Integer> walkBefore, int trailingWalk) {
            this.methods = methods;
            this.methodEdges = methodEdges;
            this.methodDurations = methodDurations;
            this.bankGated = bankGated;
            this.bankGatedTransports = bankGatedTransports;
            this.rawCost = rawCost;
            this.walkBefore = walkBefore;
            this.trailingWalk = trailingWalk;
        }
    }

    private static Transport matchMethodTransport(PathfinderConfig config, int origin, int destination, boolean bankVisited) {
        return cheapestMatch(config, origin, destination, bankVisited, true);
    }

    /**
     * Like {@link #matchMethodTransport} but without the method-type filter: also matches plain
     * connectors (doors, stairs, agility shortcuts, ...) so the raw-cost scan can use the transport's
     * travel time for any edge the search traversed via a transport.
     */
    private static Transport matchAnyTransport(PathfinderConfig config, int origin, int destination, boolean bankVisited) {
        return cheapestMatch(config, origin, destination, bankVisited, false);
    }

    /**
     * The matching transport the search would have used for this edge: among the fixed-origin
     * transports at {@code origin} (fairy rings, boats, doors, ...) and the global teleports
     * (castable from anywhere, matched purely on destination), several can share the destination
     * tile — e.g. the Varrock Teleport spell and its tab. The search settles the cheapest edge, so
     * the scan must attribute the same one: picking any other misstates the raw (ETA) cost and can
     * even name the wrong method on the route card. {@code methodsOnly} restricts the match to
     * method-type transports (excluding plain connectors like doors and stairs).
     */
    private static Transport cheapestMatch(PathfinderConfig config, int origin, int destination,
        boolean bankVisited, boolean methodsOnly) {
        Transport best = null;
        long bestCost = Long.MAX_VALUE;
        Transport[] atOrigin = config.getTransportsPacked(bankVisited)
            .getOrDefault(origin, TransportAvailability.EMPTY_TRANSPORTS);
        for (Transport transport : atOrigin) {
            if (transport.getDestination() == destination
                && (!methodsOnly || TeleportMethod.isMethodType(transport.getType())
                    // Sailing is not a CATALOG method, but its legs must appear in the route
                    // methods: the cards, and the sea-track edge detection in the overlay.
                    || transport.getType() == gps.transport.TransportType.SAILING)
                && searchEdgeCost(config, transport) < bestCost) {
                best = transport;
                bestCost = searchEdgeCost(config, transport);
            }
        }
        for (Transport transport : config.getUsableTeleports(bankVisited)) {
            if (transport.getDestination() == destination
                && (!methodsOnly || TeleportMethod.isMethodType(transport.getType())
                    // Sailing is not a CATALOG method, but its legs must appear in the route
                    // methods: the cards, and the sea-track edge detection in the overlay.
                    || transport.getType() == gps.transport.TransportType.SAILING)
                && searchEdgeCost(config, transport) < bestCost) {
                best = transport;
                bestCost = searchEdgeCost(config, transport);
            }
        }
        return best;
    }

    /** A transport edge's cost as the search charges it (see NodeGraph.createTransport's clamp). */
    private static int searchEdgeCost(PathfinderConfig config, Transport transport) {
        return Math.max(0, CostUnits.fromTicks(transport.getDuration())
            + config.getAdditionalTransportCost(transport));
    }

    /**
     * Whether the candidate's method sequence ENDS WITH a kept route's entire (non-empty)
     * method sequence — the kept route is nested inside it: the candidate detours and then runs
     * the kept route anyway ("Ring of dueling + glory + carts" when "glory + carts" is already
     * shown; a field capture had SEVEN of these). Strictly costlier, zero new information.
     * Seeds produce them because a seed search only excludes fellow NEAR-TARGET teleports, so a
     * far teleport chain stays available inside every seed's search. Bank-fetching candidates
     * are spared when the kept route isn't via-bank: withdrawing the item IS their point.
     */
    /**
     * Two shared-destination networks reached the same tile as one (capture 20260823-213943): the
     * quetzal whistle lands at any built site, so "Whistle to Quetzacalli, quetzal to Civitas,
     * charter on" is "Whistle to Civitas, charter on" with extra steps — six of ten routes were
     * such variants, one per whistle destination the exclusion chain tried. A teleport followed
     * IMMEDIATELY by a flight of the network that shares its destinations
     * ({@link gps.transport.TransportType#sharesDestinationsWith}), landing where a usable
     * teleport of the same kind could already go, adds nothing over the direct form (which has
     * its own signature and its own slot). Bankless usability is checked: if the direct teleport
     * only works from the bank, the hop variant is a genuinely different (bankless) route.
     */
    /** Whether every method is a sailing leg (see RouteOption#isPureSail). */
    static boolean isPureSail(List<TeleportMethod> methods) {
        if (methods.isEmpty())
            return false;
        for (TeleportMethod method : methods) {
            if (method.getType() != gps.transport.TransportType.SAILING)
                return false;
        }
        return true;
    }

    /**
     * The teleports the hop filter treats as "already available": bankless-usable, of a kind
     * paired with a flight network (sharesDestinationsWith), minus the USER's exclusions — an
     * excluded direct teleport is genuinely unavailable, so its hop variants are then legitimate
     * alternatives. Captured once per generation (see computeRoutes) because the chain's own
     * exclusion rebuilds must not blind the filter to the direct teleport they just removed.
     */
    static List<Transport> teleportHopBaseline(PathfinderConfig config, Set<TeleportMethod> userExclusions) {
        List<Transport> baseline = new ArrayList<>();
        for (Transport teleport : config.getUsableTeleports(false)) {
            if (teleport.getType() != null && teleport.getType().sharesDestinationsWith() != null
                && !userExclusions.contains(teleport.method())) {
                baseline.add(teleport);
            }
        }
        return baseline;
    }

    /** The current generation's hop-filter baseline; set per generation, read by chain/seed/merge filters. */
    private volatile List<Transport> hopBaselineTeleports = List.of();

    private static String signature(List<TeleportMethod> methods) {
        if (methods.isEmpty())
            return "<walk-only>";
        StringBuilder sb = new StringBuilder();
        // Parking-variant collapse (capture 233931): when a LATER method re-embarks under
        // the summon assumption, the boat gets summoned away from wherever the route just
        // disembarked — the parking port has zero lasting effect, and five routes differing
        // only in it crowded out real alternatives. The leading disembark becomes a
        // wildcard so one such route represents the family. Abandon-off overland
        // continuations (finding 5) have no later embark: their ports stay distinct.
        boolean laterEmbark = false;
        for (int i = 1; i < methods.size(); i++) {
            TeleportMethod method = methods.get(i);
            laterEmbark |= gps.transport.TransportType.SAILING.equals(method.getType())
                && method.getDisplayInfo() != null
                && method.getDisplayInfo().startsWith("Embark at ");
        }
        TeleportMethod first = methods.get(0);
        boolean parkingFirst = gps.transport.TransportType.SAILING.equals(first.getType())
            && first.getDisplayInfo() != null
            && first.getDisplayInfo().startsWith("Disembark at ");
        for (int i = 0; i < methods.size(); i++) {
            sb.append(i == 0 && parkingFirst && laterEmbark
                ? "Disembark at *" : methods.get(i).toString()).append('|');
        }
        return sb.toString();
    }
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathStep;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntPredicate;
import java.util.function.Supplier;

/**
 * The arrival zone (plan step L19, out of the plugin class): every tile within the finish
 * distance of the destination in WALKING steps, a flood from the displayed path's end over the
 * collision map with the pathfinder's own movement rules, so a tile across a wall or fence is
 * not part of the zone. Standing on any of these tiles completes the journey; the debug overlay
 * renders exactly this set. Cached per (path end, finish distance): recomputed only when the
 * displayed route's end or the config changes, then read every tick and every frame. The
 * arrival rule itself ({@link #arrived}) is a pure function over the zone and the route state.
 */
final class ArrivalZone {
    // One immutable holder for the zone and its key: the render thread and the client thread
    // both read it, and two fields could publish one route's key beside another's zone.
    private static final class Cache {
        final int end;
        final int radius;
        final Set<Integer> zone;

        Cache(int end, int radius, Set<Integer> zone) {
            this.end = end;
            this.radius = radius;
            this.zone = zone;
        }
    }

    private final Supplier<CollisionMap> map;
    private volatile Cache cache = new Cache(WorldPointUtil.UNDEFINED, Integer.MIN_VALUE, Set.of());

    ArrivalZone(Supplier<CollisionMap> map) {
        this.map = map;
    }

    /**
     * The zone around the path's end, {@code radius} walking steps wide. Empty when there is no
     * path or the finish distance is negative (never finish).
     */
    Set<Integer> tiles(List<PathStep> path, int radius) {
        if (path == null || path.isEmpty() || radius < 0)
            return Set.of();
        int end = path.get(path.size() - 1).getPackedPosition();
        Cache cached = cache;
        if (end != cached.end || radius != cached.radius) {
            cached = new Cache(end, radius, flood(map.get(), end, radius));
            cache = cached;
        }
        return cached.zone;
    }

    /**
     * Whether the player has arrived: standing in {@code zone}, or, for a sailable target, moored
     * within {@code seaReachedDistance} of it (the zone floods over walkable tiles and the ocean
     * is sealed, so a water pin's zone is empty and on-foot arrival can never fire at sea; a hull
     * is several tiles of entity and moors off the mark, hence the wider, configurable distance).
     * Guards: a round trip only completes once its turnaround has been reached (the zone centres
     * on home, so it would otherwise fire at departure); while a round trip is wanted but no
     * round-trip route is displayed (regenerating) arrival is suspended rather than measured
     * against the outbound fallback path; an unreachable one-way target never completes.
     */
    static boolean arrived(int location, Set<Integer> zone, Set<Integer> targets, IntPredicate sailable,
        int seaReachedDistance, RouteOption displayed, boolean roundTripWanted, int progress, boolean unreachable) {
        boolean inZone = !zone.isEmpty() && zone.contains(location);
        if (!inZone) {
            for (int target : targets) {
                if (sailable.test(target) && WorldPointUtil.distanceBetween(location, target) <= seaReachedDistance) {
                    inZone = true;
                    break;
                }
            }
        }
        if (!inZone)
            return false;
        boolean roundTrip = displayed != null && displayed.isRoundTrip();
        if (roundTripWanted && !roundTrip)
            return false;
        if (roundTrip) {
            int turnaround = displayed.getTurnaroundIndex();
            return turnaround < 0 || progress >= turnaround - 2;
        }
        return !unreachable;
    }

    /**
     * Breadth-first flood from {@code end} over walkable edges, up to {@code maxSteps} moves.
     * Diagonal moves mirror {@link CollisionMap}'s corner rules (both cardinals of the corner
     * must be open on both sides), so the zone matches where the player can actually walk.
     * Without a map, or with no steps, the zone is the end tile alone.
     */
    static Set<Integer> flood(CollisionMap map, int end, int maxSteps) {
        Set<Integer> zone = new HashSet<>();
        zone.add(end);
        if (map == null || maxSteps <= 0)
            return zone;
        final int plane = WorldPointUtil.unpackWorldPlane(end);
        List<Integer> frontier = new ArrayList<>();
        frontier.add(end);
        for (int depth = 0; depth < maxSteps && !frontier.isEmpty(); depth++) {
            List<Integer> next = new ArrayList<>();
            for (int tile : frontier) {
                final int x = WorldPointUtil.unpackWorldX(tile);
                final int y = WorldPointUtil.unpackWorldY(tile);
                final boolean n = map.n(x, y, plane);
                final boolean s = map.s(x, y, plane);
                final boolean e = map.e(x, y, plane);
                final boolean w = map.w(x, y, plane);
                grow(zone, next, x, y + 1, plane, n);
                grow(zone, next, x, y - 1, plane, s);
                grow(zone, next, x + 1, y, plane, e);
                grow(zone, next, x - 1, y, plane, w);
                grow(zone, next, x + 1, y + 1, plane, n && e && map.e(x, y + 1, plane) && map.n(x + 1, y, plane));
                grow(zone, next, x - 1, y + 1, plane, n && w && map.w(x, y + 1, plane) && map.n(x - 1, y, plane));
                grow(zone, next, x + 1, y - 1, plane, s && e && map.e(x, y - 1, plane) && map.s(x + 1, y, plane));
                grow(zone, next, x - 1, y - 1, plane, s && w && map.w(x, y - 1, plane) && map.s(x - 1, y, plane));
            }
            frontier = next;
        }
        return zone;
    }

    private static void grow(Set<Integer> zone, List<Integer> next, int x, int y, int plane, boolean open) {
        if (!open)
            return;
        int packed = WorldPointUtil.packWorldPoint(x, y, plane);
        if (zone.add(packed))
            next.add(packed);
    }
}

package gps;

import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;

/**
 * Draws a small triangular arrowhead at the end of a line segment, rotated to the segment's
 * direction, in the current colour of the graphics context.
 * <p>
 * Adapted from Quest Helper's {@code DirectionArrow.drawLineArrowHead}
 * (Copyright (c) 2021, Zoinkwiz &lt;https://github.com/Zoinkwiz&gt;, BSD 2-Clause licence),
 * as also used by the port-tasks plugin.
 */
public final class ArrowHead {
    private ArrowHead() {
    }

    /**
     * Fills an arrowhead pointing from (x1, y1) towards (x2, y2), with its tip at (x2, y2).
     *
     * @param size length of the arrowhead in pixels (its width is {@code size})
     */
    public static void draw(Graphics2D graphics, double x1, double y1, double x2, double y2, double size) {
        Path2D head = new Path2D.Double();
        head.moveTo(0, 0);
        head.lineTo(-size / 2.0, -size);
        head.lineTo(size / 2.0, -size);
        head.closePath();

        AffineTransform tx = new AffineTransform();
        double angle = Math.atan2(y2 - y1, x2 - x1);
        tx.translate(x2, y2);
        tx.rotate(angle - Math.PI / 2d);

        Graphics2D g = (Graphics2D) graphics.create();
        // Compose (not replace) so the overlay's existing transform/clip stay intact.
        g.transform(tx);
        g.fill(head);
        g.dispose();
    }
}

package gps;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;

/**
 * Parses the balloon log-storage chat messages into per-type stored counts. The storage crates'
 * contents are not exposed through varbits or varps — the game only reveals them in chat (verified
 * against the dedicated tictac7x-balloon hub plugin, which uses the same approach; the message
 * patterns below follow its battle-tested set). Counts persist in the plugin config, so they
 * survive sessions; they start at 0 (conservative: no flight is assumed payable from storage until
 * the game has confirmed logs are there) and re-sync whenever the player stores logs, checks the
 * crate, or flies.
 */
public final class BalloonLogStorage {
    /** Config keys per log type, in {logs, oak, willow, yew, magic} order. */
    public static final String[] CONFIG_KEYS = {
        "balloonStoredLogs", "balloonStoredOakLogs", "balloonStoredWillowLogs",
        "balloonStoredYewLogs", "balloonStoredMagicLogs"};

    /** Display names per log type, in the same order as {@link #CONFIG_KEYS}. */
    public static final String[] TYPE_NAMES = {"normal", "oak", "willow", "yew", "magic"};

    /** Item ids per log type (for icons and requirement checks), in {@link #CONFIG_KEYS} order. */
    public static final int[] ITEM_IDS = {
        ItemID.LOGS, ItemID.OAK_LOGS, ItemID.WILLOW_LOGS, ItemID.YEW_LOGS, ItemID.MAGIC_LOGS};

    private static final Pattern LEFT_PLURAL = Pattern.compile("You have (?<count>\\d+) sets of (?<type>.*) left in storage\\.");
    private static final Pattern LEFT_SINGULAR = Pattern.compile("You have one set of (?<type>.*) left in storage\\.");
    private static final Pattern USED_LAST = Pattern.compile("You used the last of your (?<type>.*)\\.");
    private static final Pattern STORED = Pattern.compile("You put the (?<type>.*) in the crate\\. You now have (?<count>\\d+) stored\\.");
    private static final Pattern NEEDED = Pattern.compile("You need 1 (?<type>.*) logs to make this trip\\.");
    private static final Pattern CHECK = Pattern.compile(
        "This crate currently contains (?<regular>\\d+) logs, (?<oak>\\d+) oak logs, (?<willow>\\d+) willow logs, "
            + "(?<yew>\\d+) yew logs and (?<magic>\\d+) magic logs\\.");

    private BalloonLogStorage() {
    }

    /**
     * The stored-count updates a chat message implies: config key -> new count. Empty when the
     * message is not a balloon-storage message.
     */
    public static Map<String, Integer> parse(String message) {
        Map<String, Integer> updates = new LinkedHashMap<>();
        Matcher check = CHECK.matcher(message);
        if (check.find()) {
            updates.put(CONFIG_KEYS[0], Integer.parseInt(check.group("regular")));
            updates.put(CONFIG_KEYS[1], Integer.parseInt(check.group("oak")));
            updates.put(CONFIG_KEYS[2], Integer.parseInt(check.group("willow")));
            updates.put(CONFIG_KEYS[3], Integer.parseInt(check.group("yew")));
            updates.put(CONFIG_KEYS[4], Integer.parseInt(check.group("magic")));
            return updates;
        }
        Matcher stored = STORED.matcher(message);
        if (stored.find()) {
            put(updates, stored.group("type"), Integer.parseInt(stored.group("count")));
            return updates;
        }
        Matcher plural = LEFT_PLURAL.matcher(message);
        if (plural.find()) {
            put(updates, plural.group("type"), Integer.parseInt(plural.group("count")));
            return updates;
        }
        Matcher singular = LEFT_SINGULAR.matcher(message);
        if (singular.find()) {
            put(updates, singular.group("type"), 1);
            return updates;
        }
        Matcher last = USED_LAST.matcher(message);
        if (last.find()) {
            put(updates, last.group("type"), 0);
            return updates;
        }
        Matcher needed = NEEDED.matcher(message);
        if (needed.find()) {
            // "You need 1 X logs to make this trip" fires when neither inventory nor storage can
            // pay: the storage is empty for that type.
            put(updates, needed.group("type"), 0);
            return updates;
        }
        return updates;
    }

    /**
     * The log types worth warning about: below the threshold in storage AND belonging to a balloon
     * route the player has unlocked (a locked route's empty storage is noise, not a warning).
     * Arrays follow the {@link #TYPE_NAMES} order; returns display names.
     */
    /**
     * Tracks the storage from a chat line (plan step L34, out of the plugin class): the crates'
     * contents have no varbit, chat is the game's only client-side signal (the approach the
     * dedicated tictac7x-balloon plugin uses). Counts persist in config and let balloon flights be
     * paid from storage; the first count also marks the storage synced. Only with smart mode on,
     * and only the game (spam) and dialog (mesbox) channels carry these lines.
     */
    public static void track(ChatMessageType type, String message, ShortestPathConfig config,
        ConfigManager configManager, String configGroup) {
        if (!config.balloonSmartMode() || (type != ChatMessageType.SPAM && type != ChatMessageType.MESBOX))
            return;
        Map<String, Integer> updates = parse(message);
        for (Map.Entry<String, Integer> update : updates.entrySet())
            configManager.setConfiguration(configGroup, update.getKey(), update.getValue());
        if (!updates.isEmpty() && !config.balloonStorageSynced())
            configManager.setConfiguration(configGroup, "balloonStorageSynced", true);
    }

    public static List<String> lowTypes(int[] stored, boolean[] unlocked, int threshold) {
        List<String> low = new ArrayList<>();
        for (int i = 0; i < TYPE_NAMES.length; i++) {
            if (unlocked[i] && stored[i] < threshold)
                low.add(TYPE_NAMES[i]);
        }
        return low;
    }

    private static void put(Map<String, Integer> updates, String type, int count) {
        String key = keyOf(type);
        if (key != null)
            updates.put(key, count);
    }

    private static String keyOf(String type) {
        switch (type) {
            case "Logs":
            case "normal":
            case "regular":
                return CONFIG_KEYS[0];
            case "Oak logs":
            case "oak":
                return CONFIG_KEYS[1];
            case "Willow logs":
            case "willow":
                return CONFIG_KEYS[2];
            case "Yew logs":
            case "yew":
                return CONFIG_KEYS[3];
            case "Magic logs":
            case "magic":
                return CONFIG_KEYS[4];
            default:
                return null;
        }
    }
}

package gps;

import java.util.Set;

/**
 * The destination a nearest-bank trip replaced, resumed once the trip completes (a player
 * suggestion: bank mid-route, then carry on). Only the nearest-bank action starts a trip and only
 * an active destination is remembered; any other change of destination (a new pin, a clear,
 * another plugin's target) forgets it, so a resume never surprises. A second bank click during a
 * trip keeps the original destination: what that click replaces is the bank trip itself.
 */
final class BankDetour {
    /** A replaced destination: its targets, label, round-trip flag and world-map pin. */
    static final class Route {
        final Set<Integer> targets;
        final String source;
        final boolean roundTrip;
        final int marker;

        private Route(Set<Integer> targets, String source, boolean roundTrip, int marker) {
            this.targets = targets;
            this.source = source;
            this.roundTrip = roundTrip;
            this.marker = marker;
        }

        /** The route for a destination, or null when none is set. */
        static Route of(Set<Integer> targets, String source, boolean roundTrip, int marker) {
            return targets == null || targets.isEmpty()
                ? null : new Route(Set.copyOf(targets), source, roundTrip, marker);
        }
    }

    private Route saved;
    private boolean active;

    /** Whether a bank trip is under way. */
    synchronized boolean isActive() {
        return active;
    }

    /**
     * The destination this trip will resume, or null: no trip, or a trip that replaced nothing
     * (which is an ordinary destination, labelled and drawn as one).
     */
    synchronized Route pending() {
        return active ? saved : null;
    }

    /**
     * Whether a bank click now would add a stop, that is resume a route after the bank: during a
     * trip, when it saved one; otherwise, when a destination is set (the one it would replace).
     */
    synchronized boolean wouldResume(boolean destinationSet) {
        return active ? saved != null : destinationSet;
    }

    /**
     * The Bank quick button's tooltip: "Nearest bank", or while a click would add a stop, what that
     * does. Bank (and back) keeps its plain tooltip: it returns to where you are anyway.
     */
    static String bankButtonTooltip(boolean addsStop) {
        return addsStop
            ? "<html><b>Add a stop</b> at the nearest bank<br>Your current route resumes after the bank</html>"
            : "Nearest bank";
    }

    /**
     * The directions header's destination line: "Destination set by <source>", or while a bank
     * trip will resume a replaced destination, what happens after the bank ("Bank stop, then the
     * route set by map pin"). Null with nothing to say.
     */
    static String headerLine(String source, Route pending, boolean roundTrip) {
        if (pending != null) {
            String then = pending.source != null ? "the route set by " + pending.source : "your route";
            return (roundTrip ? "Bank and back, then " : "Bank stop, then ") + then;
        }
        return source == null ? null : "Destination set by " + source;
    }

    /**
     * What a new bank trip replaces: the original destination while a trip is already under way,
     * otherwise {@code current}. Read before the destination changes, since the change forgets it.
     */
    synchronized Route replacing(Route current) {
        return active ? saved : current;
    }

    /** A bank trip started; {@code replaced} is resumed when it completes (null: nothing). */
    synchronized void begin(Route replaced) {
        saved = replaced;
        active = true;
    }

    /** Another destination replaced or cleared the trip: nothing will be resumed. */
    synchronized void cancel() {
        saved = null;
        active = false;
    }

    /** The trip completed: the destination to resume (null if none), forgotten either way. */
    synchronized Route complete() {
        Route route = active ? saved : null;
        cancel();
        return route;
    }
}

package gps;

import gps.pathfinder.PathfinderConfig;
import java.util.function.BooleanSupplier;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.config.ConfigManager;

/**
 * What the client knows about the bank this session, and the cross-session snapshot (plan step
 * L16, out of the plugin class). The bank container is only populated once the bank has been
 * opened; until then "+ Bank" routes and the catalog's in-bank availability fall back to the
 * previous session's snapshot, persisted per character (RSProfile-scoped) when the setting is
 * on, and replaced by the live contents the first time the bank opens.
 */
final class BankSnapshotService {
    /** RSProfile-scoped (per character, per world type): {@code id:quantity} pairs. */
    static final String CONFIG_KEY_BANK_SNAPSHOT = "bankSnapshot";

    private final ConfigManager configManager;
    private final String configGroup;
    private final BooleanSupplier rememberBank;
    private final PathfinderConfig pathfinderConfig;

    // Whether the bank's contents are known this session (live or restored). The panel uses it to
    // explain why Bank mode finds nothing.
    private volatile boolean known;
    // True when the knowledge came from a previous session's snapshot rather than the bank being
    // opened this session; cleared the moment the live bank is seen. The panel shows the source.
    private volatile boolean restored;
    // The bank changed since it was last persisted; saved once when the bank closes, not per deposit.
    private boolean saveDirty;
    // The RS profile key captured while the bank was seen, so the save still lands in the right
    // profile if it happens after logout (when the current profile is no longer available).
    private String saveProfileKey;

    BankSnapshotService(ConfigManager configManager, String configGroup, BooleanSupplier rememberBank,
        PathfinderConfig pathfinderConfig) {
        this.configManager = configManager;
        this.configGroup = configGroup;
        this.rememberBank = rememberBank;
        this.pathfinderConfig = pathfinderConfig;
    }

    boolean isKnown() {
        return known;
    }

    boolean isRestored() {
        return restored;
    }

    /** Plugin start with the bank already populated this session: adopt it, nothing to stage. */
    void adoptLive(ItemContainer liveBank) {
        if (liveBank != null && liveBank.getItems().length > 0) {
            pathfinderConfig.bank = liveBank;
            pathfinderConfig.setBankSnapshot(liveBank.getItems());
            known = true;
        }
    }

    /**
     * The bank container changed while open. Snapshots the items now (the client may empty the
     * live container once the interface closes) and stages the cross-session save with the
     * profile key of the moment. True on the first sight of the bank this session.
     */
    boolean bankOpened(ItemContainer bank) {
        pathfinderConfig.bank = bank;
        pathfinderConfig.setBankSnapshot(bank.getItems());
        boolean firstSight = !known;
        known = true;
        restored = false;
        if (rememberBank.getAsBoolean()) {
            saveDirty = true;
            saveProfileKey = configManager.getRSProfileKey();
        }
        return firstSight;
    }

    /**
     * Writes the staged snapshot to RSProfile-scoped config so a later session can start with
     * it. One write per bank session: bank close, logout, plugin shutdown.
     */
    void persist() {
        if (!saveDirty || saveProfileKey == null)
            return;
        String encoded = encode(pathfinderConfig.getBankSnapshot());
        if (encoded == null)
            // Bank seen but nothing in it: drop any stale saved snapshot rather than keeping it.
            configManager.unsetConfiguration(configGroup, saveProfileKey, CONFIG_KEY_BANK_SNAPSHOT);
        else
            configManager.setConfiguration(configGroup, saveProfileKey, CONFIG_KEY_BANK_SNAPSHOT, encoded);
        saveDirty = false;
    }

    /**
     * Loads the previous session's snapshot for the current character, if one was saved and the
     * bank has not been seen live. Login and plugin start.
     */
    void restore() {
        if (!rememberBank.getAsBoolean() || known)
            return;
        Item[] items = decode(configManager.getRSProfileConfiguration(configGroup, CONFIG_KEY_BANK_SNAPSHOT));
        if (items == null)
            return;
        pathfinderConfig.setBankSnapshot(items);
        known = true;
        restored = true;
    }

    /** Logout: save the staged snapshot, then forget so the next character does not inherit it. */
    void forget() {
        persist();
        known = false;
        restored = false;
        pathfinderConfig.clearBank();
    }

    /** The setting turned on with the bank already seen live: save right away. */
    void rememberNow(boolean loggedIn) {
        if (known && !restored && loggedIn) {
            saveDirty = true;
            saveProfileKey = configManager.getRSProfileKey();
            persist();
        }
    }

    /**
     * The setting turned off: drop the stored snapshot. True when this session's knowledge came
     * from it (dropped as well, so the caller regenerates).
     */
    boolean forgetStored() {
        configManager.unsetRSProfileConfiguration(configGroup, CONFIG_KEY_BANK_SNAPSHOT);
        saveDirty = false;
        if (!restored)
            return false;
        restored = false;
        known = false;
        pathfinderConfig.clearBank();
        return true;
    }

    /**
     * Serializes bank items as {@code id:quantity} pairs joined by commas. Empty slots and
     * placeholders (quantity 0) carry no information and are dropped. Null when there is nothing
     * worth saving.
     */
    static String encode(Item[] items) {
        if (items == null)
            return null;
        StringBuilder sb = new StringBuilder(items.length * 10);
        for (Item item : items) {
            if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
                continue;
            if (sb.length() > 0)
                sb.append(',');
            sb.append(item.getId()).append(':').append(item.getQuantity());
        }
        return sb.length() > 0 ? sb.toString() : null;
    }

    /** Parses {@link #encode}'s format back into items. Null on missing or malformed data. */
    static Item[] decode(String encoded) {
        if (encoded == null || encoded.isEmpty())
            return null;
        String[] pairs = encoded.split(",");
        Item[] items = new Item[pairs.length];
        try {
            for (int i = 0; i < pairs.length; i++) {
                int sep = pairs[i].indexOf(':');
                if (sep <= 0)
                    return null;
                items[i] = new Item(Integer.parseInt(pairs[i].substring(0, sep)),
                    Integer.parseInt(pairs[i].substring(sep + 1)));
            }
        }
        catch (NumberFormatException e) {
            return null;
        }
        return items;
    }
}

package gps;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;

/**
 * The panel's boat banner (plan step L7, out of the plugin class): the owned boats as
 * {name, port label, hull} rows, read from the sailing varbits once they are seen this session
 * and restored from the character's profile before that. Routing does NOT read this;
 * PathfinderConfig reads the boat varbits itself at refresh. Berth changes arrive as varbit
 * bursts (login sync, docking), so a change only marks the banner dirty and the next game tick
 * rebuilds it at most once. Written on the client thread, read from the Swing thread.
 */
final class BoatBannerService {
    /** RSProfile-scoped: owned boats' last seen berths, "name|port|hull" rows joined by ';'. */
    static final String CONFIG_KEY_BOAT_PORTS = "boatPorts";

    private static final int[][] BOAT_VARBITS = {
        {VarbitID.SAILING_BOAT_1_OWNED, VarbitID.SAILING_BOAT_1_PORT, VarbitID.SAILING_BOAT_1_NAME_1,
            VarbitID.SAILING_BOAT_1_NAME_2, VarbitID.SAILING_BOAT_1_NAME_3, VarbitID.SAILING_BOAT_1_TYPE},
        {VarbitID.SAILING_BOAT_2_OWNED, VarbitID.SAILING_BOAT_2_PORT, VarbitID.SAILING_BOAT_2_NAME_1,
            VarbitID.SAILING_BOAT_2_NAME_2, VarbitID.SAILING_BOAT_2_NAME_3, VarbitID.SAILING_BOAT_2_TYPE},
        {VarbitID.SAILING_BOAT_3_OWNED, VarbitID.SAILING_BOAT_3_PORT, VarbitID.SAILING_BOAT_3_NAME_1,
            VarbitID.SAILING_BOAT_3_NAME_2, VarbitID.SAILING_BOAT_3_NAME_3, VarbitID.SAILING_BOAT_3_TYPE},
        {VarbitID.SAILING_BOAT_4_OWNED, VarbitID.SAILING_BOAT_4_PORT, VarbitID.SAILING_BOAT_4_NAME_1,
            VarbitID.SAILING_BOAT_4_NAME_2, VarbitID.SAILING_BOAT_4_NAME_3, VarbitID.SAILING_BOAT_4_TYPE},
        {VarbitID.SAILING_BOAT_5_OWNED, VarbitID.SAILING_BOAT_5_PORT, VarbitID.SAILING_BOAT_5_NAME_1,
            VarbitID.SAILING_BOAT_5_NAME_2, VarbitID.SAILING_BOAT_5_NAME_3, VarbitID.SAILING_BOAT_5_TYPE},
    };
    private static final Set<Integer> BOAT_VARBIT_IDS = Arrays.stream(BOAT_VARBITS)
        .flatMapToInt(Arrays::stream).boxed().collect(Collectors.toSet());

    private final Client client;
    private final ConfigManager configManager;
    private final String configGroup;
    /** Told after every rebuild or restore, so the panel's sailing section can relabel itself. */
    private final Runnable onChanged;

    /** The rows; null when never collected for this character. */
    private volatile List<String[]> banner;
    private volatile boolean live;
    private volatile boolean dirty;

    BoatBannerService(Client client, ConfigManager configManager, String configGroup, Runnable onChanged) {
        this.client = client;
        this.configManager = configManager;
        this.configGroup = configGroup;
        this.onChanged = onChanged;
    }

    /** Whether a varbit change concerns a boat's ownership, berth, name or hull. */
    boolean tracks(int varbitId) {
        return BOAT_VARBIT_IDS.contains(varbitId);
    }

    /** A tracked varbit changed: rebuild on the next tick (one rebuild per burst). */
    void markDirty() {
        dirty = true;
    }

    /** Client thread, once per game tick. */
    void onTick() {
        if (dirty) {
            dirty = false;
            refresh();
        }
    }

    /** Logged out: the next character starts from its own snapshot. */
    void reset() {
        banner = null;
        live = false;
        dirty = false;
    }

    /** Owned boats as {name, port label, hull} rows; null when never collected for this character. */
    List<String[]> banner() {
        return banner;
    }

    /** Whether the banner reflects this session's live varbits rather than a restored snapshot. */
    boolean isLive() {
        return live;
    }

    /** Client thread: re-read every boat's ownership, berth, name and hull, persist, and notify. */
    void refresh() {
        if (!GameState.LOGGED_IN.equals(client.getGameState()))
            return;
        List<String[]> rows = new ArrayList<>();
        for (int slot = 0; slot < BOAT_VARBITS.length; slot++) {
            int[] varbits = BOAT_VARBITS[slot];
            // Owned varbit alone is unreliable (Where's My Boat's field lesson); a set name
            // descriptor also proves ownership, and covers Port Sarim's port id 0.
            if (client.getVarbitValue(varbits[0]) <= 0 && client.getVarbitValue(varbits[3]) <= 0)
                continue;
            BoatHull hull = BoatHull.fromVarbit(client.getVarbitValue(varbits[5]));
            rows.add(new String[]{decodeBoatName(slot, varbits),
                SailingPorts.portName(client.getVarbitValue(varbits[1])),
                hull == null ? "" : hull.displayName()});
        }
        banner = rows;
        live = true;
        configManager.setRSProfileConfiguration(configGroup, CONFIG_KEY_BOAT_PORTS, encode(rows));
        changed();
    }

    /** Restores the persisted snapshot when nothing has been collected yet this session. */
    void restore() {
        if (banner != null)
            return;
        String raw = configManager.getRSProfileConfiguration(configGroup, CONFIG_KEY_BOAT_PORTS);
        if (raw != null) {
            banner = decode(raw);
            changed();
        }
    }

    private void changed() {
        if (onChanged != null)
            onChanged.run();
    }

    /** "name|port|hull" rows joined by ';'. */
    static String encode(List<String[]> rows) {
        return rows.stream().map(r -> r[0] + "|" + r[1] + "|" + r[2]).collect(Collectors.joining(";"));
    }

    /** The inverse of {@link #encode}; old snapshots lack the hull, and rows without a name are dropped. */
    static List<String[]> decode(String raw) {
        List<String[]> rows = new ArrayList<>();
        for (String row : raw.split(";")) {
            String[] parts = row.split("\\|", 3);
            if (parts.length >= 2 && !parts[0].isEmpty()) {
                rows.add(new String[]{parts[0], parts[1], parts.length > 2 ? parts[2] : ""});
            }
        }
        return rows;
    }

    /**
     * The three name varbits index the game's own name-part tables (prefix, descriptor, noun),
     * the same decode Where's My Boat ships. Any surprise falls back to a slot label.
     */
    private String decodeBoatName(int slot, int[] varbits) {
        try {
            int[] rowIds = {DBTableID.SailingBoatNameOptions.Row.SAILING_BOAT_NAME_PREFIX_OPTIONS,
                DBTableID.SailingBoatNameOptions.Row.SAILING_BOAT_NAME_DESCRIPTOR_OPTIONS,
                DBTableID.SailingBoatNameOptions.Row.SAILING_BOAT_NAME_NOUN_OPTIONS};
            List<String> parts = new ArrayList<>();
            for (int part = 0; part < 3; part++) {
                int index = client.getVarbitValue(varbits[2 + part]) - 1;
                if (index > 0) {
                    Object[] options = client.getDBTableField(rowIds[part],
                        DBTableID.SailingBoatNameOptions.COL_OPTION, 0);
                    if (index < options.length && options[index] instanceof String
                        && !((String) options[index]).isEmpty()) {
                        parts.add((String) options[index]);
                    }
                }
            }
            if (!parts.isEmpty())
                return String.join(" ", parts);
        }
        catch (RuntimeException e) {
            // Name tables unavailable (cache quirk): the slot label below still identifies it.
        }
        return "Boat " + (slot + 1);
    }
}

package gps;

/**
 * The player's boat hull tiers (plan step L5), as the hull type varbit counts them in
 * acquisition order: the Pandemonium quest raft is 0, the level-15 skiff 1, the level-50 sloop
 * 2 (verified against a capture with all three owned). An unknown future tier maps to nothing
 * and the panel simply shows no type.
 */
public enum BoatHull {
    RAFT(0, "Raft"),
    SKIFF(1, "Skiff"),
    SLOOP(2, "Sloop");

    private final int varbitValue;
    private final String displayName;

    BoatHull(int varbitValue, String displayName) {
        this.varbitValue = varbitValue;
        this.displayName = displayName;
    }

    public String displayName() {
        return displayName;
    }

    /** The hull for a hull-type varbit value, or null for a value this build does not know. */
    public static BoatHull fromVarbit(int value) {
        for (BoatHull hull : values()) {
            if (hull.varbitValue == value)
                return hull;
        }
        return null;
    }

    /** The hull for a persisted display name ("Raft"), or null for anything else. */
    public static BoatHull fromName(String name) {
        for (BoatHull hull : values()) {
            if (hull.displayName.equals(name))
                return hull;
        }
        return null;
    }
}

package gps;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/**
 * The running build's identity: the release version from the bundled plugin manifest and the git
 * commit stamped at build time, so reports always name exactly what ran (no constant to keep in
 * sync). "unknown" in a dev build where a file is not on the classpath.
 */
public final class BuildInfo {
    // A BARE constant, browsed as-is: the hub review reads any dynamic URL construction (the old
    // pre-filled ?title=&body=) as network I/O of player data. Context travels via the clipboard.
    static final String GITHUB_NEW_ISSUE = "https://github.com/PauloAguiar/runelite-gps-plugin/issues/new";

    private BuildInfo() {
    }

    /** The release version from {@code runelite-plugin.properties}. */
    public static String pluginVersion() {
        return property("/runelite-plugin.properties", "version");
    }

    /** The git commit from {@code gps-build.properties} (stamped by processResources). */
    public static String buildCommit() {
        return property("/gps-build.properties", "commit");
    }

    private static String property(String resource, String key) {
        try (InputStream in = BuildInfo.class.getResourceAsStream(resource)) {
            if (in != null) {
                Properties props = new Properties();
                props.load(in);
                String value = props.getProperty(key);
                if (value != null && !value.isEmpty())
                    return value;
            }
        }
        catch (IOException ignored) {
            // Fall through to "unknown".
        }
        return "unknown";
    }
}

package gps;

/**
 * When the teleport-methods catalog needs a re-classification after an inventory or equipment
 * change (plan step L29, out of the plugin class; issue #5). Only the routing-relevant slice of
 * the items counts: the dependency index fingerprints every item id (and quantity threshold) a
 * transport requirement can read, so logs, ore, food and loot pass through without ever
 * scheduling a refresh (issues #23/#24). The catalog exists for the sidebar, so a dirty flag
 * waits while the panel is hidden (every pickup, drop and gear switch used to run a full planning
 * refresh, hundreds of quest clientscripts, on the client thread: a per-action micro stutter for
 * players who never open the panel); route generations rebuild the catalog themselves, so routing
 * never sees the deferral. Bursts while the panel is open coalesce through a short cooldown; the
 * flag stays set, so no change is lost, only delayed a few ticks.
 */
final class CatalogRefresher {
    /** Ticks between two claimed refreshes while changes keep coming. */
    static final int COOLDOWN_TICKS = 5;

    private volatile boolean dirty;
    private int backoffTick;
    private long fingerprint;
    private boolean fingerprintValid;

    /** Whether a re-classification is pending (claimed on the next tick the panel is open). */
    boolean isDirty() {
        return dirty;
    }

    /** The catalog must be re-classified (no fingerprint available to compare). */
    void markDirty() {
        dirty = true;
    }

    /**
     * An inventory or equipment change: dirties the catalog only when the routing-relevant item
     * fingerprint differs from the last one seen (the first one always counts). True when it did.
     */
    boolean noteItems(long routingItemsFingerprint) {
        if (fingerprintValid && routingItemsFingerprint == fingerprint)
            return false;
        fingerprint = routingItemsFingerprint;
        fingerprintValid = true;
        dirty = true;
        return true;
    }

    /**
     * Whether a refresh should run now: the catalog is dirty, the panel is shown, no generation is
     * in flight (it re-snapshots anyway), the player is logged in and the cooldown has elapsed.
     * Claiming clears the flag and arms the cooldown from {@code tick}.
     */
    boolean claim(int tick, boolean panelVisible, boolean generationInFlight, boolean loggedIn) {
        if (!dirty || !panelVisible || generationInFlight || !loggedIn || tick < backoffTick)
            return false;
        backoffTick = tick + COOLDOWN_TICKS;
        dirty = false;
        return true;
    }
}

package gps;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The persisted user choices (plan step L15, out of the plugin class): the excluded methods, the
 * routes mode, the search history and the favourite destinations, each as one config value.
 * The plugin owns the live copies; this is where they are read at startup and written on change.
 */
@Slf4j
final class ChoiceStore {
    static final String CONFIG_KEY_EXCLUSIONS = "alternativeRoutesExclusions";
    static final String CONFIG_KEY_MODE = "alternativeRoutesMode";
    // The search box's recent selections (most recent first).
    static final String CONFIG_KEY_SEARCH_HISTORY = "searchHistory";
    static final String CONFIG_KEY_FAVORITES = "favoriteDestinations";
    static final int FAVORITES_LIMIT = 100;

    // Suppliers: the plugin's injected services arrive after its fields initialise.
    private final Supplier<ConfigManager> configManager;
    private final Supplier<Gson> gson;
    private final String configGroup;

    ChoiceStore(Supplier<ConfigManager> configManager, Supplier<Gson> gson, String configGroup) {
        this.configManager = configManager;
        this.gson = gson;
        this.configGroup = configGroup;
    }

    void saveExclusions(Set<TeleportMethod> exclusions) {
        try {
            configManager.get().setConfiguration(configGroup, CONFIG_KEY_EXCLUSIONS,
                gson.get().toJson(new ArrayList<>(exclusions)));
        }
        catch (Exception e) {
            log.warn("Failed to save alternative-route exclusions", e);
        }
    }

    /**
     * The persisted exclusion set. Entries without a type are dropped, and so are seasonal
     * methods: they used to be seeded here as the "disabled by default" mechanism and are gated by
     * the "Enable seasonal transports" toggle now, so any a prior version persisted would linger
     * in the set (and in debug captures) forever. The cleaned set is written back once.
     */
    Set<TeleportMethod> loadExclusions() {
        Set<TeleportMethod> exclusions = new HashSet<>();
        try {
            String json = configManager.get().getConfiguration(configGroup, CONFIG_KEY_EXCLUSIONS);
            if (json == null || json.isEmpty())
                return exclusions;
            TeleportMethod[] saved = gson.get().fromJson(json, TeleportMethod[].class);
            if (saved == null)
                return exclusions;
            boolean dropped = false;
            for (TeleportMethod method : saved) {
                if (method == null || method.getType() == null
                    || method.getType() == gps.transport.TransportType.SEASONAL_TRANSPORTS) {
                    dropped = true;
                    continue;
                }
                exclusions.add(method);
            }
            if (dropped)
                saveExclusions(exclusions);
        }
        catch (Exception e) {
            log.warn("Failed to load alternative-route exclusions", e);
        }
        return exclusions;
    }

    void saveRoutesMode(AlternativeRoutesMode mode) {
        configManager.get().setConfiguration(configGroup, CONFIG_KEY_MODE, mode.name());
    }

    /** The persisted routes mode, or null when none was saved (the plugin keeps its default). */
    AlternativeRoutesMode loadRoutesMode() {
        return decodeRoutesMode(configManager.get().getConfiguration(configGroup, CONFIG_KEY_MODE));
    }

    /** A mode by name, the legacy 3-mode names mapped onto the Owned/All split, else null. */
    static AlternativeRoutesMode decodeRoutesMode(String value) {
        if (value == null || value.isEmpty())
            return null;
        try {
            return AlternativeRoutesMode.valueOf(value);
        }
        catch (IllegalArgumentException e) {
            switch (value) {
                case "AVAILABLE":
                    return AlternativeRoutesMode.OWNED_INVENTORY;
                case "AVAILABLE_WITH_BANK":
                    return AlternativeRoutesMode.OWNED_WITH_BANK;
                case "ALL_TELEPORTS":
                case "ALL_UNLOCKED":
                    // The unlocked-only middle mode was folded into All.
                    return AlternativeRoutesMode.ALL_EVERYTHING;
                default:
                    log.warn("Unknown alternative-routes mode '{}'", value);
                    return null;
            }
        }
    }

    void saveSearchHistory(List<Destinations.Entry> history) {
        configManager.get().setConfiguration(configGroup, CONFIG_KEY_SEARCH_HISTORY, SearchHistory.serialize(history));
    }

    List<Destinations.Entry> loadSearchHistory() {
        return SearchHistory.deserialize(configManager.get().getConfiguration(configGroup, CONFIG_KEY_SEARCH_HISTORY));
    }

    void saveFavorites(List<Destinations.Entry> favorites) {
        configManager.get().setConfiguration(configGroup, CONFIG_KEY_FAVORITES, SearchHistory.serialize(favorites));
    }

    List<Destinations.Entry> loadFavorites() {
        return SearchHistory.deserialize(configManager.get().getConfiguration(configGroup, CONFIG_KEY_FAVORITES), FAVORITES_LIMIT);
    }
}

package gps;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

import static gps.WorldPointUtil.packWorldPoint;
import static gps.WorldPointUtil.unpackWorldPlane;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

/**
 * Openable doors and gates the collision map bakes passable, indexed by tile.
 *
 * The collision extraction treats every wall object with wallOrDoor set as open, so the
 * pathfinder happily routes through doors that are currently closed in the game — with no cue
 * that the walk will stop at them. This registry (dumped from the cache by the tooling repo's
 * doorDump task into doors.tsv) lets the path overlay find the door sitting on a walk edge so
 * it can hint "Open Door" while the closed object still stands in the scene.
 *
 * For straight walls (location type 0) the orientation identifies the tile edge the door
 * occupies: 0 = west, 1 = north, 2 = east, 3 = south. A walk between two adjacent tiles is
 * gated by a door on the crossed edge of either tile. Diagonal-wall doors (type 9) block the
 * whole tile, so any edge touching their tile matches.
 */
@Slf4j
public class ClosedDoors {
    private static final String RESOURCE_PATH = "/doors.tsv";

    private static final int ORIENTATION_WEST = 0;
    private static final int ORIENTATION_NORTH = 1;
    private static final int ORIENTATION_EAST = 2;
    private static final int ORIENTATION_SOUTH = 3;

    private static final int TYPE_WALL_STRAIGHT = 0;

    /**
     * Game ticks a route is charged per door it walks through: ~1 tick for the door to swing open
     * plus the stop-and-click reaction overhead. Deliberately priced so that walking a handful of
     * tiles around a doorway beats going through it. The search charges this on the crossing edge
     * (see CollisionMap) and the directions bill the same on the "Open X" step, so the route card
     * ETA and the overlay agree.
     */
    public static final int COST_TICKS = 3;

    // Edge-mask bits, matching gps.pathfinder.OrdinalDirection's ordinal order (the search tests
    // masks by direction index): W, E, S, N, SW, SE, NW, NE.
    private static final int BIT_WEST = 1;
    private static final int BIT_EAST = 1 << 1;
    private static final int BIT_SOUTH = 1 << 2;
    private static final int BIT_NORTH = 1 << 3;

    public static final class Door {
        public final int id;
        public final String name;
        public final int packedPosition;
        public final int type;
        public final int orientation;
        // True when the map data places this door in its OPEN state (its id has "Close").
        // Then presence of the id means passable, absence means someone closed it — the
        // inverse of the usual closed-variant test — and the recorded orientation is the
        // swung-open position, not the doorway edge.
        public final boolean placedOpen;

        Door(int id, String name, int packedPosition, int type, int orientation, boolean placedOpen) {
            this.id = id;
            this.name = name;
            this.packedPosition = packedPosition;
            this.type = type;
            this.orientation = orientation;
            this.placedOpen = placedOpen;
        }
    }

    /**
     * Live scene state of a door, from whichever variant the map places there.
     */
    public enum State {
        OPEN,
        CLOSED,
        UNKNOWN
    }

    public static State state(net.runelite.api.Client client, Door door) {
        SceneObjects.Presence presence = SceneObjects.presence(client, door.packedPosition, door.id);
        if (presence == SceneObjects.Presence.OUT_OF_SCENE)
            return State.UNKNOWN;
        boolean present = presence == SceneObjects.Presence.PRESENT;
        return door.placedOpen == present ? State.OPEN : State.CLOSED;
    }

    private static volatile Map<Integer, List<Door>> doorsByTile;
    private static volatile Map<Integer, Integer> edgeMasks;
    private static volatile PrimitiveIntHashMap<Integer> edgeMaskIndex;

    private ClosedDoors() {
    }

    /**
     * Packed tile -> bitmask of walk directions (bit i = {@code OrdinalDirection} ordinal i) that
     * cross a door when leaving that tile. Both sides of every doorway carry a bit, so the search
     * only ever looks up the tile it is expanding. Diagonal bits follow {@link #doorBetween}'s
     * semantics: a diagonal step is gated when any of its component cardinal boundaries is.
     * Doors placed open in the map data are skipped here exactly as in {@link #doorAt}.
     */
    public static Map<Integer, Integer> edgeMasks() {
        get();
        return edgeMasks;
    }

    /**
     * The same masks keyed by primitive int: the search looks one up per expanded tile, and the
     * boxed map allocated an Integer per lookup (plan step N2). Mask values are small, so the
     * stored Integers are the cached ones and a hit allocates nothing.
     */
    public static PrimitiveIntHashMap<Integer> edgeMaskIndex() {
        PrimitiveIntHashMap<Integer> index = edgeMaskIndex;
        if (index == null) {
            Map<Integer, Integer> masks = edgeMasks();
            index = new PrimitiveIntHashMap<>(Math.max(16, masks.size() * 2));
            for (Map.Entry<Integer, Integer> entry : masks.entrySet())
                index.put(entry.getKey(), entry.getValue());
            edgeMaskIndex = index;
        }
        return index;
    }

    private static Map<Integer, Integer> buildEdgeMasks(Map<Integer, List<Door>> byTile) {
        // Pass 1: cardinal bits, projected onto both tiles of each gated boundary.
        Map<Integer, Integer> cardinal = new HashMap<>();
        for (List<Door> doors : byTile.values()) {
            for (Door door : doors) {
                if (door.placedOpen)
                    continue;
                if (door.type == TYPE_WALL_STRAIGHT)
                    setEdgeBits(cardinal, door.packedPosition, door.orientation);
                else {
                    // Diagonal walls and corner pieces gate the whole tile: every boundary.
                    for (int orientation = 0; orientation < 4; orientation++)
                        setEdgeBits(cardinal, door.packedPosition, orientation);
                }
            }
        }

        // Pass 2: diagonal bits, derived from the cardinal bits of the tile and its neighbours —
        // candidates are every masked tile plus its 8 neighbours (a tile with no cardinal bits of
        // its own can still have a gated diagonal past a neighbouring door corner).
        Map<Integer, Integer> masks = new HashMap<>(cardinal);
        for (Map.Entry<Integer, Integer> entry : cardinal.entrySet()) {
            int tile = entry.getKey();
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    int candidate = packWorldPoint(
                        unpackWorldX(tile) + dx,
                        unpackWorldY(tile) + dy,
                        unpackWorldPlane(tile));
                    int diagonals = diagonalBits(cardinal, candidate);
                    if (diagonals != 0)
                        masks.merge(candidate, diagonals, (a, b) -> a | b);
                }
            }
        }
        return masks;
    }

    /** Marks the boundary on the door's edge: one bit on its own tile, the opposite on the neighbour. */
    private static void setEdgeBits(Map<Integer, Integer> masks, int tile, int orientation) {
        int x = unpackWorldX(tile);
        int y = unpackWorldY(tile);
        int plane = unpackWorldPlane(tile);
        int bit;
        int neighborBit;
        int nx = x;
        int ny = y;
        switch (orientation) {
            case ORIENTATION_WEST:
                bit = BIT_WEST;
                neighborBit = BIT_EAST;
                nx--;
                break;
            case ORIENTATION_NORTH:
                bit = BIT_NORTH;
                neighborBit = BIT_SOUTH;
                ny++;
                break;
            case ORIENTATION_EAST:
                bit = BIT_EAST;
                neighborBit = BIT_WEST;
                nx++;
                break;
            default:
                bit = BIT_SOUTH;
                neighborBit = BIT_NORTH;
                ny--;
                break;
        }
        masks.merge(tile, bit, (a, b) -> a | b);
        masks.merge(packWorldPoint(nx, ny, plane), neighborBit, (a, b) -> a | b);
    }

    /**
     * The four diagonal-direction bits for a tile: a diagonal crossing is gated when either of its
     * component cardinal boundaries is — from this tile, or around the corner via a neighbour
     * (mirroring {@link #doorBetween}'s four component checks).
     */
    private static int diagonalBits(Map<Integer, Integer> cardinal, int tile) {
        int x = unpackWorldX(tile);
        int y = unpackWorldY(tile);
        int plane = unpackWorldPlane(tile);
        int own = cardinal.getOrDefault(tile, 0);
        int west = cardinal.getOrDefault(packWorldPoint(x - 1, y, plane), 0);
        int east = cardinal.getOrDefault(packWorldPoint(x + 1, y, plane), 0);
        int south = cardinal.getOrDefault(packWorldPoint(x, y - 1, plane), 0);
        int north = cardinal.getOrDefault(packWorldPoint(x, y + 1, plane), 0);

        int bits = 0;
        // Bit order: SW=4, SE=5, NW=6, NE=7 (OrdinalDirection ordinals).
        if (((own | south) & BIT_WEST) != 0 || ((own | west) & BIT_SOUTH) != 0)
            bits |= 1 << 4;
        if (((own | south) & BIT_EAST) != 0 || ((own | east) & BIT_SOUTH) != 0)
            bits |= 1 << 5;
        if (((own | north) & BIT_WEST) != 0 || ((own | west) & BIT_NORTH) != 0)
            bits |= 1 << 6;
        if (((own | north) & BIT_EAST) != 0 || ((own | east) & BIT_NORTH) != 0)
            bits |= 1 << 7;
        return bits;
    }

    /**
     * The door gating the walk between two adjacent tiles on the same plane, or null when the
     * boundary is doorless (or the tiles aren't an adjacent same-plane pair). Diagonal steps
     * are gated by any of their four component boundaries.
     */
    public static Door doorBetween(int from, int to) {
        int plane = unpackWorldPlane(from);
        if (plane != unpackWorldPlane(to))
            return null;
        int fromX = unpackWorldX(from);
        int fromY = unpackWorldY(from);
        int dx = unpackWorldX(to) - fromX;
        int dy = unpackWorldY(to) - fromY;
        if ((dx == 0 && dy == 0) || Math.abs(dx) > 1 || Math.abs(dy) > 1)
            return null;

        if (dx != 0 && dy != 0) {
            // A diagonal step crosses a corner: it is blocked if any of the boundaries of the
            // two cardinal detours around that corner has a closed door.
            int cornerX = packWorldPoint(fromX + dx, fromY, plane);
            int cornerY = packWorldPoint(fromX, fromY + dy, plane);
            Door door = doorBetween(from, cornerX);
            if (door == null)
                door = doorBetween(from, cornerY);
            if (door == null)
                door = doorBetween(cornerX, to);
            if (door == null)
                door = doorBetween(cornerY, to);
            return door;
        }

        int facing = dx > 0 ? ORIENTATION_EAST
            : dx < 0 ? ORIENTATION_WEST
            : dy > 0 ? ORIENTATION_NORTH
            : ORIENTATION_SOUTH;
        Door door = doorAt(from, facing);
        if (door == null)
            door = doorAt(to, opposite(facing));
        return door;
    }

    private static Door doorAt(int packedPosition, int facing) {
        List<Door> doors = get().get(packedPosition);
        if (doors == null)
            return null;
        for (Door door : doors) {
            // Doors placed OPEN in the map data are open by default. Their rare closed state can't
            // be read reliably from the scene — the swung-open leaf anchors to a neighbouring tile,
            // so a presence check at the doorway misses it and wrongly reports "closed", which
            // false-blocked open doorways. They're skipped: an open door needs no hint, and never
            // blocking one is far better than blocking one that's actually open.
            if (door.placedOpen)
                continue;
            // Straight walls sit on one edge; anything else (diagonal walls, corner pieces) blocks
            // its whole tile, so every edge of the tile matches.
            if (door.type != TYPE_WALL_STRAIGHT || door.orientation == facing)
                return door;
        }
        return null;
    }

    private static int opposite(int orientation) {
        return (orientation + 2) % 4;
    }

    private static Map<Integer, List<Door>> get() {
        Map<Integer, List<Door>> snapshot = doorsByTile;
        if (snapshot == null) {
            synchronized (ClosedDoors.class) {
                snapshot = doorsByTile;
                if (snapshot == null) {
                    snapshot = loadFromResource();
                    // Masks are published before doorsByTile so edgeMasks() (which calls get()
                    // first) can never observe the registry without them.
                    edgeMasks = buildEdgeMasks(snapshot);
                    doorsByTile = snapshot;
                }
            }
        }
        return snapshot;
    }

    private static Map<Integer, List<Door>> loadFromResource() {
        try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(RESOURCE_PATH)) {
            if (in == null) {
                log.warn("Door registry resource not found at {}; closed-door hints disabled", RESOURCE_PATH);
                return new HashMap<>();
            }
            return parse(new String(Util.readAllBytes(in), StandardCharsets.UTF_8));
        }
        catch (IOException e) {
            log.error("Failed to load door registry from {}", RESOURCE_PATH, e);
            return new HashMap<>();
        }
    }

    private static Map<Integer, List<Door>> parse(String tsv) {
        Map<Integer, List<Door>> result = new HashMap<>();
        boolean header = true;
        for (String line : tsv.split("\\R")) {
            if (header) {
                header = false;
                continue;
            }
            if (line.isEmpty())
                continue;
            // id, name, x, y, plane, type, orientation, sizeX, sizeY, state
            String[] fields = line.split("\t");
            if (fields.length < 7) {
                log.warn("Skipping malformed door row: '{}'", line);
                continue;
            }
            try {
                int id = Integer.parseInt(fields[0]);
                String name = fields[1];
                int packed = packWorldPoint(
                    Integer.parseInt(fields[2]),
                    Integer.parseInt(fields[3]),
                    Integer.parseInt(fields[4]));
                int type = Integer.parseInt(fields[5]);
                int orientation = Integer.parseInt(fields[6]);
                boolean placedOpen = fields.length > 9 && "open".equals(fields[9]);
                result.computeIfAbsent(packed, k -> new ArrayList<>(1))
                    .add(new Door(id, name, packed, type, orientation, placedOpen));
            }
            catch (NumberFormatException e) {
                log.warn("Skipping door row with non-numeric field: '{}'", line);
            }
        }
        return result;
    }
}

package gps;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;

/**
 * The other plugins GPS cares about (plan step L20, out of the plugin class), matched by
 * descriptor name because each hub plugin has its own classloader and class identity cannot be
 * compared across them. The original Shortest Path plugin draws paths and answers the same
 * plugin-message integrations, so running both doubles the rendering: the panel recommends
 * disabling it. Quest Helper hands quest-step destinations over that integration only when its
 * own "Use Shortest Path plugin" option is on ({@code questhelper.useShortestPath}, default
 * off): enabled with the option off, it draws its own lines and GPS never hears about the step,
 * so the panel shows a dismissable banner.
 */
final class CompanionPlugins {
    static final String SHORTEST_PATH = "Shortest Path";
    static final String QUEST_HELPER = "Quest Helper";

    private final PluginManager pluginManager;
    private final ConfigManager configManager;
    private final Plugin self;
    private final Runnable onChanged;

    private volatile boolean shortestPathConflict;
    private volatile boolean questHelperPathingOff;

    CompanionPlugins(PluginManager pluginManager, ConfigManager configManager, Plugin self, Runnable onChanged) {
        this.pluginManager = pluginManager;
        this.configManager = configManager;
        this.self = self;
        this.onChanged = onChanged;
    }

    /** Whether the original Shortest Path plugin is also enabled. */
    boolean isShortestPathConflict() {
        return shortestPathConflict;
    }

    /** Whether Quest Helper runs WITHOUT its "Use Shortest Path plugin" option. */
    boolean isQuestHelperPathingOff() {
        return questHelperPathingOff;
    }

    /** Re-reads both verdicts (plugin start, a plugin toggled, the Quest Helper option changed). */
    void refresh() {
        boolean conflict = false;
        boolean off = false;
        for (Plugin other : pluginManager.getPlugins()) {
            if (other == self)
                continue;
            PluginDescriptor descriptor = other.getClass().getAnnotation(PluginDescriptor.class);
            if (descriptor == null || !pluginManager.isPluginEnabled(other))
                continue;
            if (SHORTEST_PATH.equals(descriptor.name()))
                conflict = true;
            else if (QUEST_HELPER.equals(descriptor.name()))
                off = !Boolean.parseBoolean(configManager.getConfiguration("questhelper", "useShortestPath"));
        }
        boolean changed = conflict != shortestPathConflict || off != questHelperPathingOff;
        shortestPathConflict = conflict;
        questHelperPathingOff = off;
        if (changed)
            onChanged.run();
    }
}

package gps;

import gps.transport.TransportType;
import java.awt.Color;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Config values another plugin overrides through the path plugin message (plan step L21, out
 * of the plugin class): every config read that a message may override goes through
 * {@code override(key, configValue)}, which answers the override while one is set and the
 * config value otherwise. Also the one place that knows which keys change what the routing
 * engine computes. Static, like the reads that consult it from the engine.
 */
@Slf4j
public final class ConfigOverrides {
    // Every config key the routing engine reads (PathfinderConfig.refresh / TransportTypeConfig):
    // a change to one of these regenerates the routes. RouteAffectingKeysTest scans the engine's
    // sources and fails when a key it reads is missing here; the pohMount*/sailing* toggles were
    // silently inert while this list was maintained by hand.
    private static final Pattern ROUTE_AFFECTING = Pattern.compile("^(avoidWilderness|includeBankPath|currencyThreshold|calculationCutoff|pohJewelleryBoxTier|pohMount\\w+|sailingAssumeSummon|sailingTeleportAbandon|balloonSmartMode|balloonStored\\w+|spiritTreeSmartMode|use\\w+|cost\\w+)$");

    private static final Map<String, Object> OVERRIDES = new HashMap<>(50);
    private static volatile Set<String> known = withTypeKeys(Collections.emptySet());

    private ConfigOverrides() {
    }

    /**
     * The plugin declares its @ConfigItem keys at start, read from the ConfigManager's descriptor
     * (the hub forbids reflection in shipped code, so the keys cannot be scanned here).
     */
    static void declareKeys(Collection<String> itemKeys) {
        known = withTypeKeys(itemKeys);
    }

    /** Every key a message may override: the declared config items plus the toggle-less types' keys. */
    static Set<String> knownKeys() {
        return known;
    }

    /** The transport types without a toggle keep an override key, so a message or a test can still switch one off. */
    private static Set<String> withTypeKeys(Collection<String> itemKeys) {
        Set<String> keys = new HashSet<>(itemKeys);
        for (TransportType type : TransportType.values()) {
            if (type.getEnabledKey() != null)
                keys.add(type.getEnabledKey());
        }
        return Collections.unmodifiableSet(keys);
    }

    /** Whether a change to this config key changes what the routing engine computes. */
    public static boolean affectsRouting(String key) {
        return key != null && ROUTE_AFFECTING.matcher(key).find();
    }

    /**
     * Replaces the override set with a message's. An unknown key would sit in the map forever
     * and never be diagnosable from either side, so it is rejected loudly instead.
     */
    static void apply(Map<String, Object> overrides) {
        OVERRIDES.clear();
        for (Map.Entry<String, Object> entry : overrides.entrySet()) {
            if (!knownKeys().contains(entry.getKey())) {
                log.warn("Plugin message config override ignored: unknown key '{}'", entry.getKey());
                continue;
            }
            OVERRIDES.put(entry.getKey(), entry.getValue());
        }
    }

    static void clear() {
        OVERRIDES.clear();
    }

    public static boolean override(String key, boolean defaultValue) {
        Object value = OVERRIDES.isEmpty() ? null : OVERRIDES.get(key);
        return value instanceof Boolean ? (boolean) value : defaultValue;
    }

    /** Override for a transport type's enabled state, by the config key the enum names. */
    public static boolean override(TransportType type, boolean defaultValue) {
        String key = type.getEnabledKey();
        return key != null ? override(key, defaultValue) : defaultValue;
    }

    /** Override for a transport type's cost threshold, by the config key the enum names. */
    public static int override(TransportType type, int defaultValue) {
        String key = type.getCostKey();
        return key != null ? override(key, defaultValue) : defaultValue;
    }

    public static int override(String key, int defaultValue) {
        Object value = OVERRIDES.isEmpty() ? null : OVERRIDES.get(key);
        return value instanceof Integer ? (int) value : defaultValue;
    }

    public static TeleportationItem override(String key, TeleportationItem defaultValue) {
        Object value = OVERRIDES.isEmpty() ? null : OVERRIDES.get(key);
        if (value instanceof String) {
            TeleportationItem item = TeleportationItem.fromType((String) value);
            if (item != null)
                return item;
        }
        return defaultValue;
    }

    public static JewelleryBoxTier override(String key, JewelleryBoxTier defaultValue) {
        Object value = OVERRIDES.isEmpty() ? null : OVERRIDES.get(key);
        if (value instanceof String) {
            JewelleryBoxTier tier = JewelleryBoxTier.fromType((String) value);
            if (tier != null)
                return tier;
        }
        return defaultValue;
    }

    public static Color override(String key, Color defaultValue) {
        Object value = OVERRIDES.isEmpty() ? null : OVERRIDES.get(key);
        return value instanceof Color ? (Color) value : defaultValue;
    }
}

package gps;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

import static gps.PanelWidgets.BANNER_WARN_ACCENT;
import static gps.PanelWidgets.banner;
import static gps.PanelWidgets.sectionShell;
import static gps.PanelWidgets.wrappedLabel;

/**
 * The "Travel options" configuration sections (panel series P2, out of the panel class): the
 * player-stated facts routing cannot detect on its own (the house, the wilderness policy, the
 * walking and bank biases, balloons, sailing, planted spirit trees), each a collapsible section
 * whose header chip summarises its state. The controls ARE the plugin's config items: a checkbox
 * or spinner is built from the item's key, takes its label and tooltip from the item's name and
 * description (hidden items, so that text shows nowhere else; the plugin reads them from the
 * ConfigManager's descriptor, since shipped code may not use reflection), reads the stored value
 * by key and writes the key back through the ConfigManager; any change regenerates the routes.
 */
final class ConfigSectionsView {
    private static final int LABEL_WIDTH = 168;

    private final ShortestPathPlugin plugin;
    // Rebuilds the sections slot after a header toggle.
    private final Runnable refresh;
    // Rebuilds the sections and the notes strip after a spinner change (the chip and the banner track it).
    private final Runnable refreshAll;

    private boolean pohExpanded;
    private boolean wildernessExpanded;
    private boolean walkingExpanded;
    private boolean bankExpanded;
    private boolean balloonExpanded;
    private boolean sailingExpanded;
    private boolean spiritTreeExpanded;

    ConfigSectionsView(ShortestPathPlugin plugin, Runnable refresh, Runnable refreshAll) {
        this.plugin = plugin;
        this.refresh = refresh;
        this.refreshAll = refreshAll;
    }

    /** The sections, freshly built, in display order. */
    List<JPanel> sections() {
        return List.of(poh(), wilderness(), walking(), bank(), balloon(), sailing(), spiritTree());
    }

    /** The config item a section binds; a misspelt key fails here, when the section is built. */
    private ConfigItem item(String key) {
        return plugin.configItem(key);
    }

    /**
     * The seconds chip for a section header, in the SAME sign convention as the route cards'
     * adjustment chips: green minus 15 s = "ranks as if 15 s cheaper". A preference of +15 s
     * therefore displays as minus 15 s; showing the raw preference read as a surcharge.
     */
    static String biasChip(int preferenceSeconds) {
        if (preferenceSeconds == 0)
            return "neutral";
        int adjustment = -preferenceSeconds;
        return (adjustment > 0 ? "+" : "−") + Math.abs(adjustment) + "s";
    }

    static Color biasColor(int seconds) {
        if (seconds == 0)
            return ColorScheme.LIGHT_GRAY_COLOR;
        return seconds > 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR;
    }

    /** The balloon section's chip: off, on, or "low logs" when an unlocked route's storage is low. */
    static String balloonState(boolean balloonsOn, boolean lowLogs) {
        return !balloonsOn ? "off" : (lowLogs ? "low logs" : "on");
    }

    /** The spirit-tree section's chip: all (smart tracking off), on (not synced yet), none, or the count. */
    static String spiritTreeState(boolean smart, boolean synced, int planted) {
        if (!smart)
            return "all";
        if (!synced)
            return "on";
        return planted == 0 ? "none" : planted + " planted";
    }

    /**
     * The Log-storage-low warning banner: like the bank warning, it lives in the notes strip so it
     * is visible even while the balloon section is collapsed. Shows the low types as item icons.
     */
    JPanel balloonLowBanner(List<String> lowTypes) {
        JPanel warning = banner(RouteIcons.BANNER_WARNING,
            "Log storage low", "Restock logs at a balloon station:", BANNER_WARN_ACCENT);
        int[] counts = plugin.getBalloonStoredCounts();
        JPanel icons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        icons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        for (int i = 0; i < BalloonLogStorage.TYPE_NAMES.length; i++) {
            if (lowTypes.contains(BalloonLogStorage.TYPE_NAMES[i]))
                icons.add(logIcon(i, counts[i]));
        }
        warning.add(icons, BorderLayout.SOUTH);
        warning.setMaximumSize(new Dimension(Integer.MAX_VALUE, warning.getPreferredSize().height));
        return warning;
    }

    private JPanel shell(String title, String tooltip, boolean expanded, Runnable toggle, String stateText, Color stateColor) {
        return sectionShell(title, tooltip, expanded, toggle, stateText, stateColor, false, refresh);
    }

    /**
     * The player-owned-house declarations: which POH teleport features GPS should assume exist.
     * Unlike the catalog's include/exclude (what the user WANTS used), these describe what is BUILT
     * in the house, facts GPS cannot detect from outside the house, so the player states them once.
     */
    private JPanel poh() {
        final boolean pohOn = plugin.getGpsConfig().usePoh();
        JPanel section = shell("Player-owned house",
            "Declare which teleport features are built in your house so routes can use them",
            pohExpanded, () -> pohExpanded = !pohExpanded,
            pohOn ? "on" : "off",
            pohOn ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
        if (!pohExpanded)
            return section;

        JPanel body = body();

        // What GPS detected on its own: the house location (varbit), a confidence hint that the
        // location-gated entries/exits will resolve correctly.
        String house = plugin.getHouseLocationName();
        body.add(statusLabel(house != null
                ? "Your house: " + house
                : "No house detected (log in, or you don't own one)",
            house != null ? ColorScheme.LIGHT_GRAY_COLOR : ColorScheme.MEDIUM_GRAY_COLOR));

        body.add(iconRow("house_portal", 0, toggle("usePoh", 0, true)));

        // Smart detection: while inside your house GPS auto-fills the furniture it can recognise.
        body.add(iconRow("house_portal", 18, toggle("pohSmartDetect", 0, true)));
        if (plugin.getGpsConfig().pohSmartDetect()) {
            List<String> detected = plugin.getDetectedPohFurniture();
            if (!plugin.isPohScanned())
                body.add(warningBanner("Enter your house once to auto-detect its furniture."));
            else if (detected.isEmpty())
                body.add(note("No auto-detectable furniture found in your house.", ColorScheme.MEDIUM_GRAY_COLOR));
            else
                body.add(note("Detected: " + String.join(", ", detected), ColorScheme.LIGHT_GRAY_COLOR));
        }

        ConfigItem tier = item("pohJewelleryBoxTier");
        JPanel tierInner = new JPanel(new BorderLayout(5, 0));
        tierInner.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        JLabel tierLabel = new JLabel(tier.name() + ":");
        tierLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        tierInner.add(tierLabel, BorderLayout.WEST);
        JComboBox<JewelleryBoxTier> tierBox = new JComboBox<>(JewelleryBoxTier.values());
        tierBox.setSelectedItem(plugin.getGpsConfig().pohJewelleryBoxTier());
        tierBox.setEnabled(pohOn);
        tierBox.setToolTipText(tooltip(tier));
        tierBox.addActionListener(e -> plugin.setPanelConfig("pohJewelleryBoxTier", tierBox.getSelectedItem()));
        tierInner.add(tierBox, BorderLayout.CENTER);
        body.add(iconRow("jewellery_box", 18, tierInner));

        body.add(iconRow("portal_chamber", 18, toggle("useTeleportationPortalsPoh", 0, pohOn)));
        body.add(iconRow("mounted_glory", 18, toggle("usePohMountedItems", 0, pohOn)));
        // The mounts cannot be scene-detected (no stable object ids), so each is its own
        // assumption: pick exactly the ones built in your house.
        boolean mountsOn = pohOn && plugin.getGpsConfig().usePohMountedItems();
        body.add(toggle("pohMountGlory", 36, mountsOn));
        body.add(toggle("pohMountXerics", 36, mountsOn));
        body.add(toggle("pohMountDigsite", 36, mountsOn));
        body.add(toggle("pohMountMythical", 36, mountsOn));
        body.add(iconRow("fairy_ring", 18, toggle("usePohFairyRing", 0, pohOn)));
        body.add(iconRow("spirit_tree", 18, toggle("usePohSpiritTree", 0, pohOn)));
        body.add(iconRow("obelisk", 18, toggle("usePohObelisk", 0, pohOn)));

        section.add(body);
        return section;
    }

    /** The wilderness travel policy: whether routes may cross the wilderness at all. */
    private JPanel wilderness() {
        final boolean avoid = plugin.getGpsConfig().avoidWilderness();
        JPanel section = shell("Wilderness",
            "Choose whether routes may cross the wilderness",
            wildernessExpanded, () -> wildernessExpanded = !wildernessExpanded,
            avoid ? "avoided" : "allowed",
            avoid ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);
        if (!wildernessExpanded)
            return section;

        JPanel body = body();
        body.add(toggle("avoidWilderness", 0, true));
        body.add(note("Routes still enter the wilderness when the destination itself is inside it.",
            ColorScheme.MEDIUM_GRAY_COLOR));
        section.add(body);
        return section;
    }

    /**
     * Walking as a travel POLICY (not a method): a seconds bias with finer control than the
     * method tiers. Positive = walking keeps the top spot unless a method beats it by more than
     * the bias; negative penalises the pure-walk route the same way.
     */
    private JPanel walking() {
        int bias = plugin.getWalkPreferenceSeconds();
        JPanel section = shell("Walking",
            "How plain walking ranks against travel methods",
            walkingExpanded, () -> walkingExpanded = !walkingExpanded,
            biasChip(bias), biasColor(bias));
        if (!walkingExpanded)
            return section;
        JPanel body = body();
        body.add(statusLabel(bias == 0
                ? "No preference: routes rank purely by time."
                : (bias > 0
                    ? "Walking wins unless a method is more than " + bias + "s faster."
                    : "Walking is ranked as if " + (-bias) + "s slower."),
            ColorScheme.LIGHT_GRAY_COLOR));
        body.add(biasSpinner("Prefer walking by (s):",
            "Ranking bias in seconds: positive keeps walking on top unless a method beats it by more, negative ranks it as if slower",
            bias, plugin::setWalkPreferenceSeconds));
        body.add(note("Ranking only: the walk route's ETA and path never change.", ColorScheme.MEDIUM_GRAY_COLOR));
        section.add(body);
        return section;
    }

    /**
     * Bank memory: whether GPS saves the bank's contents when the bank closes and restores them at
     * login, so "+ Bank" routes and in-bank availability work without opening the bank first. GPS
     * only ever sees the bank while it is open; this fills the gap between sessions.
     */
    private JPanel bank() {
        // The header chip is the ranking bias (same convention as Walking and the card chips);
        // the remember-between-sessions state is a detail inside the body.
        int bankBias = plugin.getBankPreferenceSeconds();
        JPanel section = shell("Bank",
            "How bank-detour routes rank, and remembering your bank between sessions",
            bankExpanded, () -> bankExpanded = !bankExpanded,
            biasChip(bankBias), biasColor(bankBias));
        if (!bankExpanded)
            return section;

        JPanel body = body();

        // What GPS currently knows, and where that knowledge came from: a restored snapshot can be
        // stale if the bank changed on another client since it was saved.
        String state;
        Color stateColor;
        if (!plugin.isBankContentsKnown()) {
            state = "Bank contents: unknown, open your bank once";
            stateColor = ColorScheme.MEDIUM_GRAY_COLOR;
        }
        else if (plugin.isBankRestored()) {
            state = "Bank contents: restored from your last session";
            stateColor = ColorScheme.LIGHT_GRAY_COLOR;
        }
        else {
            state = "Bank contents: seen this session";
            stateColor = ColorScheme.LIGHT_GRAY_COLOR;
        }
        body.add(statusLabel(state, stateColor));

        body.add(toggle("rememberBank", 0, true));
        body.add(note("Opening the bank always refreshes the snapshot; turning this off deletes it.",
            ColorScheme.MEDIUM_GRAY_COLOR));

        // Ranking bias for via-bank routes: finer control than the method tiers, and separate
        // from the withdrawal time already counted inside those routes' ETAs.
        body.add(biasSpinner("Prefer bank routes by (s):",
            "Ranking bias in seconds for routes that detour via a bank: positive ranks them as if faster, negative as if slower; the withdrawal time is already in their ETA",
            bankBias, plugin::setBankPreferenceSeconds));
        section.add(body);
        return section;
    }

    /**
     * Balloon travel: the master toggle plus smart mode, which tracks the stations' log storage
     * from chat so flights can be paid from storage, including a low-storage warning (threshold
     * configurable; only routes the player has unlocked are considered) and a first-time sync hint,
     * since the counts only become known once a storage message has been seen.
     */
    private JPanel balloon() {
        final ShortestPathConfig config = plugin.getGpsConfig();
        final boolean balloonsOn = config.useHotAirBalloons();
        final boolean smart = config.balloonSmartMode();
        List<String> lowTypes = plugin.getBalloonLowLogTypes();

        Color stateColor = !balloonsOn ? ColorScheme.LIGHT_GRAY_COLOR
            : (lowTypes.isEmpty() ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);
        JPanel section = shell("Hot air balloons",
            "Balloon travel and smart tracking of the stations' Log storage",
            balloonExpanded, () -> balloonExpanded = !balloonExpanded,
            balloonState(balloonsOn, !lowTypes.isEmpty()), stateColor);
        if (!balloonExpanded)
            return section;

        JPanel body = body();
        body.add(toggle("useHotAirBalloons", 0, true));
        body.add(toggle("balloonSmartMode", 18, balloonsOn));
        body.add(spinner("balloonLogWarningThreshold", 0, 100, 1, 28, balloonsOn && smart));

        if (balloonsOn && smart) {
            if (!config.balloonStorageSynced()) {
                body.add(warningBanner("Not synced yet: check the Log storage at a balloon station"
                    + " once to import your stored log counts."));
            }
            else {
                body.add(note("Log storage:", ColorScheme.LIGHT_GRAY_COLOR));
                int[] counts = plugin.getBalloonStoredCounts();
                JPanel storageRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
                storageRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
                storageRow.setAlignmentX(Component.LEFT_ALIGNMENT);
                storageRow.setBorder(new EmptyBorder(0, 14, 2, 0));
                for (int i = 0; i < counts.length; i++)
                    storageRow.add(logIcon(i, counts[i]));
                storageRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, storageRow.getPreferredSize().height));
                body.add(storageRow);
            }
        }

        section.add(body);
        return section;
    }

    /** Sailing your own boat: the master switch, the boarding assumptions and the known berths. */
    private JPanel sailing() {
        final boolean sailingOn = plugin.getGpsConfig().useSailing();
        JPanel section = shell("Sailing (beta)",
            "Sail your own boat between mooring points and port berths",
            sailingExpanded, () -> sailingExpanded = !sailingExpanded,
            sailingOn ? "on" : "off",
            sailingOn ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
        if (!sailingExpanded)
            return section;

        JPanel body = body();
        body.add(toggle("useSailing", 0, true));
        body.add(toggle("sailingTeleportAbandon", 18, sailingOn));
        body.add(toggle("sailingKeepSailing", 18, sailingOn));
        body.add(toggle("sailingAssumeSummon", 18, sailingOn));

        // Latest known berths: live varbits once seen this session, the stored snapshot from
        // the last one before that. One two-column row per boat: no glyphs (the panel font has
        // no boat, it fell back to a warning triangle) and no wrapping; the name clips with a
        // tooltip, the port keeps its own column and its colour.
        List<String[]> berths = plugin.getBoatBanner();
        if (berths == null || berths.isEmpty()) {
            JLabel none = wrappedLabel(berths == null
                ? "No boat seen yet. Berths appear after login."
                : "No owned boat detected.");
            none.setBorder(new EmptyBorder(4, 18, 2, 0));
            body.add(none);
        }
        else {
            for (String[] row : berths) {
                JPanel berthRow = new JPanel(new BorderLayout(8, 0));
                berthRow.setOpaque(false);
                berthRow.setBorder(new EmptyBorder(3, 18, 0, 0));
                // A raw JPanel defaults to CENTER alignmentX (0.5); one such row in a vertical
                // BoxLayout shifts every LEFT-aligned sibling toward mid-column: the sailing
                // checkboxes rendered half-indented AND clipped off the right edge.
                berthRow.setAlignmentX(Component.LEFT_ALIGNMENT);
                String type = row.length > 2 ? row[2] : "";
                JLabel name = new JLabel(row[0]);
                name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                BoatHull hull = BoatHull.fromName(type);
                if (hull != null)
                    name.setIcon(RouteIcons.hullIcon(hull));
                name.setIconTextGap(6);
                name.setToolTipText(row[0] + (type.isEmpty() ? "" : " (" + type + ")") + ", moored at " + row[1]);
                berthRow.add(name, BorderLayout.CENTER);
                JLabel port = new JLabel(row[1]);
                port.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
                port.setToolTipText(name.getToolTipText());
                berthRow.add(port, BorderLayout.EAST);
                body.add(berthRow);
            }
            if (!plugin.isBoatBannerLive()) {
                JLabel stale = wrappedLabel("(berths from last session)");
                stale.setBorder(new EmptyBorder(1, 18, 2, 0));
                body.add(stale);
            }
        }

        section.add(body);
        return section;
    }

    /**
     * Planted spirit trees: ONLY the five farmable patches; the permanent spirit trees are always
     * available and toggled in the Travel methods catalog like every other method. Smart tracking
     * reads the travel menu to learn which farmable trees you have grown; the detected list shows
     * here (or a sync hint, since GPS cannot see a farming patch until the menu has been opened).
     */
    private JPanel spiritTree() {
        final boolean smart = plugin.getGpsConfig().spiritTreeSmartMode();
        final boolean synced = plugin.isSpiritTreeSynced();
        List<String> planted = smart && synced ? plugin.getAvailablePlantedSpiritTrees() : List.of();

        Color stateColor = smart && !planted.isEmpty()
            ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR;
        JPanel section = shell("Planted spirit trees",
            "Smart detection of the farmable spirit trees you have grown (permanent trees are in Travel methods)",
            spiritTreeExpanded, () -> spiritTreeExpanded = !spiritTreeExpanded,
            spiritTreeState(smart, synced, planted.size()), stateColor);
        if (!spiritTreeExpanded)
            return section;

        JPanel body = body();
        body.add(iconRow("spirit_tree", 0, toggle("spiritTreeSmartMode", 0, true)));

        if (!smart)
            body.add(note("All farmable spirit trees assumed available.", ColorScheme.MEDIUM_GRAY_COLOR));
        else if (!synced) {
            body.add(warningBanner("Not synced yet: open a spirit tree travel menu once to detect"
                + " your planted trees."));
        }
        else if (planted.isEmpty())
            body.add(note("No planted spirit trees detected.", ColorScheme.MEDIUM_GRAY_COLOR));
        else {
            body.add(note("Detected:", ColorScheme.LIGHT_GRAY_COLOR));
            for (String name : planted) {
                JLabel label = new JLabel(name);
                label.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
                label.setFont(FontManager.getRunescapeSmallFont());
                body.add(iconRow("spirit_tree", 18, label));
            }
        }

        section.add(body);
        return section;
    }

    /** The body box of an expanded configuration section. */
    private static JPanel body() {
        JPanel body = new JPanel();
        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        body.setBorder(new EmptyBorder(4, 6, 6, 6));
        body.setAlignmentX(Component.LEFT_ALIGNMENT);
        return body;
    }

    /**
     * A status line at the top of a section body ("Your house: ...", "Bank contents: ...").
     * HTML-wrapped so text longer than the narrow panel wraps instead of clipping.
     */
    private static JLabel statusLabel(String text, Color color) {
        JLabel label = new JLabel("<html>" + text + "</html>");
        label.setForeground(color);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setBorder(new EmptyBorder(0, 0, 4, 0));
        return label;
    }

    /** A small wrapped note line inside a section body. */
    private static JLabel note(String text, Color color) {
        JLabel note = new JLabel("<html>" + text + "</html>");
        note.setFont(FontManager.getRunescapeSmallFont());
        note.setForeground(color);
        note.setAlignmentX(Component.LEFT_ALIGNMENT);
        note.setBorder(new EmptyBorder(2, 18, 2, 0));
        return note;
    }

    /**
     * An attention note inside a section rendered as a warning banner (amber accent bar plus
     * warning glyph), matching the panel's other banners; used for the "needs a sync" hints.
     */
    private static JPanel warningBanner(String text) {
        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
        wrap.setBorder(new EmptyBorder(3, 0, 1, 0));
        JPanel warning = banner(RouteIcons.BANNER_WARNING, text, BANNER_WARN_ACCENT);
        wrap.add(warning, BorderLayout.CENTER);
        wrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, warning.getPreferredSize().height + 4));
        return wrap;
    }

    /**
     * A POH construction icon (bundled OSRS-wiki furniture images under resources/poh/), scaled to
     * fit the row height and centred in a fixed-width slot so the row labels align.
     */
    private static JLabel pohIcon(String name) {
        JLabel label = new JLabel();
        label.setPreferredSize(new Dimension(26, 20));
        label.setHorizontalAlignment(SwingConstants.CENTER);
        BufferedImage img = ImageUtil.loadImageResource(ConfigSectionsView.class, "/poh/" + name + ".png");
        double scale = Math.min(1.0, Math.min(26.0 / img.getWidth(), 20.0 / img.getHeight()));
        if (scale < 1.0) {
            img = ImageUtil.resizeImage(img,
                (int) Math.round(img.getWidth() * scale), (int) Math.round(img.getHeight() * scale));
        }
        label.setIcon(new ImageIcon(img));
        return label;
    }

    /** A configuration row decorated with a small icon to the left of its control. */
    private static JPanel iconRow(String pohIconName, int leftInset, JComponent control) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        row.setBorder(new EmptyBorder(2, leftInset, 2, 0));
        row.add(pohIcon(pohIconName), BorderLayout.WEST);
        row.add(control, BorderLayout.CENTER);
        return row;
    }

    /**
     * An item icon for one Log storage log type, with the stored count drawn as the stack quantity
     * (the same rendering the inventory uses) and spelled out in the tooltip.
     */
    private JLabel logIcon(int typeIndex, int count) {
        JLabel icon = new JLabel();
        icon.setToolTipText(count + " " + BalloonLogStorage.TYPE_NAMES[typeIndex] + " logs in storage");
        plugin.getItemManager().getImage(BalloonLogStorage.ITEM_IDS[typeIndex], count, true).addTo(icon);
        return icon;
    }

    /** A config item's stored int, 0 when the store has none (it always has: defaults are written at start). */
    private int intValue(String key) {
        Integer value = plugin.configValue(key, Integer.class);
        return value == null ? 0 : value;
    }

    private static String tooltip(ConfigItem item) {
        return "<html><body style='width:220px'>" + item.description() + "</body></html>";
    }


    /**
     * A config checkbox: the item's name as its label, its description as the tooltip; writes the
     * key on change and the ConfigChanged regenerates. Indented {@code indent} px as a sub-toggle;
     * the HTML wrap width shrinks by the same amount, since a fixed-width HTML view never reflows,
     * it loses its right edge (the sailing sub-toggles once rendered as "Teleports may aban").
     */
    private JCheckBox toggle(String key, int indent, boolean enabled) {
        ConfigItem item = item(key);
        JCheckBox box = new JCheckBox(
            "<html><body style='width:" + (LABEL_WIDTH - indent) + "px'>" + item.name() + "</body></html>",
            Boolean.TRUE.equals(plugin.configValue(key, Boolean.class)));
        if (indent > 0)
            box.setBorder(new EmptyBorder(2, indent, 2, 0));
        box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        box.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        // HTML text ignores the look-and-feel's disabled dimming: mirror it by hand.
        box.addPropertyChangeListener("enabled", e -> box.setForeground(
            box.isEnabled() ? ColorScheme.LIGHT_GRAY_COLOR : ColorScheme.MEDIUM_GRAY_COLOR));
        box.setToolTipText(tooltip(item));
        box.setAlignmentX(Component.LEFT_ALIGNMENT);
        box.setFocusPainted(false);
        // The look-and-feel's box is nearly invisible on the dark background: use the catalog's
        // toggle glyphs instead (green check = on, grey cross = off, red on hover), dimmed while
        // disabled.
        box.setIcon(RouteIcons.CROSS);
        box.setRolloverIcon(RouteIcons.CROSS_HOVER);
        box.setSelectedIcon(RouteIcons.CHECK);
        box.setRolloverSelectedIcon(RouteIcons.CHECK_HOVER);
        box.setDisabledIcon(RouteIcons.CROSS_DIM);
        box.setDisabledSelectedIcon(RouteIcons.CHECK_DIM);
        box.setEnabled(enabled);
        box.addActionListener(e -> plugin.setPanelConfig(key, box.isSelected()));
        return box;
    }

    /** A config spinner row: the item's name as caption, its description as tooltip. */
    private JPanel spinner(String key, int min, int max, int step, int indent, boolean enabled) {
        ConfigItem item = item(key);
        return spinnerRow(item.name() + ":", tooltip(item), intValue(key), min, max, step, indent, enabled,
            v -> plugin.setPanelConfig(key, v));
    }

    /** A "Bias (seconds)" spinner row: minus 120 to 120 in steps of 5, wired to the given setter. */
    private JPanel biasSpinner(String caption, String tooltip, int value, IntConsumer setter) {
        return spinnerRow(caption, tooltip, value, -120, 120, 5, 0, true, v -> {
            setter.accept(v);
            SwingUtilities.invokeLater(refreshAll);
        });
    }

    private static JPanel spinnerRow(String caption, String tooltip, int value, int min, int max, int step,
        int indent, boolean enabled, IntConsumer setter) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setBorder(new EmptyBorder(2, indent, 2, 0));
        JLabel label = new JLabel(caption);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setToolTipText(tooltip);
        row.add(label, BorderLayout.CENTER);
        JSpinner spinner = new JSpinner(new SpinnerNumberModel(value, min, max, step));
        spinner.setEnabled(enabled);
        spinner.setToolTipText(tooltip);
        spinner.addChangeListener(e -> setter.accept((Integer) spinner.getValue()));
        row.add(spinner, BorderLayout.EAST);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, spinner.getPreferredSize().height + 4));
        return row;
    }
}

package gps;

import com.google.gson.Gson;
import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.RuneLite;

/**
 * A JSON snapshot of the current routing state, written to {@code ~/.runelite/gps-debug/}:
 * everything needed to reproduce and debug the current path (routes with their full tile paths,
 * methods and edge data, mode and exclusions, player position, GPS progress state, the relevant
 * config, every non-zero varbit, and the last generation's timing). Triggered by the panel's
 * "Save debug snapshot" item; confirms via a game message. Built on the client thread.
 */
@Slf4j
final class DebugSnapshot {
    private final ShortestPathPlugin plugin;

    DebugSnapshot(ShortestPathPlugin plugin) {
        this.plugin = plugin;
    }

    /** Builds and writes the snapshot, CLIENT THREAD. Failures are logged, never thrown. */
    void capture() {
        try {
            File out = write(build());
            log.info("GPS debug snapshot saved to {}", out.getAbsolutePath());
            Client client = plugin.getClient();
            if (GameState.LOGGED_IN.equals(client.getGameState())) {
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                    "GPS debug snapshot saved to " + out.getAbsolutePath(), null);
            }
        }
        catch (Exception e) {
            log.warn("Failed to capture GPS debug snapshot", e);
        }
    }

    private Map<String, Object> build() {
        Client client = plugin.getClient();
        RouteSession session = plugin.session();
        ShortestPathConfig config = plugin.getGpsConfig();
        Map<String, Object> snapshot = new LinkedHashMap<>();
        snapshot.put("capturedAt", new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date()));
        snapshot.put("pluginVersion", BuildInfo.pluginVersion());
        snapshot.put("buildCommit", BuildInfo.buildCommit());
        snapshot.put("varbitSnapshot", varbitSnapshot(client));
        Player local = client.getLocalPlayer();
        int playerPacked = local != null
            ? WorldPointUtil.fromLocalInstance(client, local) : WorldPointUtil.UNDEFINED;
        snapshot.put("player", packedPointJson(playerPacked));
        snapshot.put("routesMode", String.valueOf(plugin.getRoutesMode()));
        snapshot.put("routeLimit", session.limit());
        snapshot.put("routeCostMultiple", session.costMultiple());
        snapshot.put("targetSource", plugin.getTargetSource());
        snapshot.put("altStart", packedPointJson(session.lastStart()));
        List<Object> targets = new ArrayList<>();
        for (int target : session.lastTargets())
            targets.add(packedPointJson(target));
        snapshot.put("targets", targets);
        List<String> exclusions = new ArrayList<>();
        for (TeleportMethod method : plugin.getUserExclusions())
            exclusions.add(methodKey(method));
        snapshot.put("userExclusions", exclusions);
        snapshot.put("bankContentsKnown", plugin.isBankContentsKnown());
        snapshot.put("bankRestored", plugin.isBankRestored());
        // Smart-detection state, for diagnosing "GPS didn't notice my house/trees" reports.
        snapshot.put("pohSceneLoaded", PlayerOwnedHouse.isHouseScene(client.getTopLevelWorldView()));
        snapshot.put("pohScanned", plugin.isPohScanned());
        snapshot.put("pohDetectedFurniture", PohScanner.encode(plugin.pohDetection().detected()));
        snapshot.put("spiritTreesSynced", plugin.isSpiritTreeSynced());
        snapshot.put("spiritTreesParsedLive", plugin.spiritTreesParsedLive());

        // includeBankPath and useTeleportationItems are omitted: the Owned/All mode forces them
        // (see PathfinderConfig.refresh), so their config value is overridden and misleading;
        // routesMode above is the effective control.
        Map<String, Object> configValues = new LinkedHashMap<>();
        configValues.put("avoidWilderness", ConfigOverrides.override("avoidWilderness", config.avoidWilderness()));
        configValues.put("costBankPickup", ConfigOverrides.override("costBankPickup", config.costBankPickup()));
        configValues.put("defaultRouteCount", ConfigOverrides.override("defaultRouteCount", config.defaultRouteCount()));
        snapshot.put("config", configValues);

        RouteOption displayed = plugin.getDisplayedRoute();
        List<RouteOption> routes = session.routes();
        snapshot.put("displayedRouteIndex", displayed != null ? routes.indexOf(displayed) : -1);
        List<Object> routesJson = new ArrayList<>();
        for (RouteOption route : routes)
            routesJson.add(routeJson(route));
        snapshot.put("routes", routesJson);
        Map<String, Object> timing = generationTiming(plugin.altRoutesService());
        if (timing != null)
            snapshot.put("altGenTiming", timing);
        if (displayed != null) {
            snapshot.put("directions", stepsJson(plugin.getRouteDirections(displayed)));
            RouteDirectionsOverlay overlay = plugin.routeDirectionsOverlay();
            Map<String, Object> progress = new LinkedHashMap<>();
            progress.put("reachedIndex", overlay.getReachedIndex());
            progress.put("liveRemainingTicks", overlay.getLiveRemainingTicks());
            progress.put("speedTilesPerSecond", overlay.getSpeedTilesPerSecond());
            snapshot.put("progress", progress);
        }
        return snapshot;
    }

    /**
     * Every non-zero varbit, for identifying state-dependent transport gates (mushtree discovery,
     * balloon route unlocks): capture before and after the in-game action and diff the two files;
     * the flipped id is the gate. A few thousand entries, debug-file-sized only.
     */
    private static Map<String, Integer> varbitSnapshot(Client client) {
        Map<String, Integer> varbits = new LinkedHashMap<>();
        for (int id = 0; id <= 20000; id++) {
            try {
                int value = client.getVarbitValue(id);
                if (value != 0)
                    varbits.put(Integer.toString(id), value);
            }
            catch (Exception ignored) {
                // Unknown varbit ids past the cache's definitions: skip.
            }
        }
        return varbits;
    }

    private Map<String, Object> routeJson(RouteOption route) {
        Map<String, Object> routeJson = new LinkedHashMap<>();
        routeJson.put("totalCost", route.getTotalCost());
        routeJson.put("rawCost", route.getRawCost());
        routeJson.put("reached", route.isReached());
        routeJson.put("viaBank", route.isViaBank());
        List<String> methods = new ArrayList<>();
        for (TeleportMethod method : route.getMethods())
            methods.add(methodKey(method));
        routeJson.put("methods", methods);
        routeJson.put("methodEdgeIndexes", route.getMethodEdgeIndexes());
        routeJson.put("methodDurations", route.getMethodDurations());
        routeJson.put("walkBeforeSteps", route.getWalkBeforeSteps());
        routeJson.put("trailingWalkSteps", route.getTrailingWalkSteps());
        List<Integer> packedPath = new ArrayList<>(route.getPath().size());
        List<Integer> bankFlips = new ArrayList<>();
        for (int i = 0; i < route.getPath().size(); i++) {
            packedPath.add(route.getPath().get(i).getPackedPosition());
            if (route.getPath().get(i).isBankVisited()
                && (i == 0 || !route.getPath().get(i - 1).isBankVisited())) {
                bankFlips.add(i);
            }
        }
        routeJson.put("packedPath", packedPath);
        routeJson.put("bankVisitedFrom", bankFlips);
        // Fresh directions build per route, timed: the dashboard renders the step list for every
        // route and charts how long step derivation takes.
        long buildStart = System.nanoTime();
        List<RouteDirections.Step> routeSteps = RouteDirections.build(plugin, route);
        routeJson.put("directionsBuildMicros", (System.nanoTime() - buildStart) / 1_000);
        routeJson.put("directions", stepsJson(routeSteps));
        return routeJson;
    }

    /** The last generation's timing and per-search profiles (slowest first), or null when none ran. */
    private static Map<String, Object> generationTiming(AlternativeRoutesService service) {
        long[] genTiming = service != null ? service.getLastTimingSummary() : null;
        if (genTiming == null)
            return null;
        Map<String, Object> timingJson = new LinkedHashMap<>();
        timingJson.put("wallMs", genTiming[0]);
        timingJson.put("clientMs", genTiming[1]);
        timingJson.put("rebuildMs", genTiming[2]);
        timingJson.put("searchCpuMs", genTiming[3]);
        timingJson.put("searches", genTiming[4]);
        if (genTiming.length > 5)
            timingJson.put("fieldMs", genTiming[5]);
        // Which searches the time went to and how much each explored (a flat A* heuristic shows
        // up as a huge node count).
        List<Object> searchDetails = new ArrayList<>();
        for (AlternativeRoutesService.SearchRecord r : service.getLastSearchRecords()) {
            Map<String, Object> detail = new LinkedHashMap<>();
            detail.put("label", r.label);
            detail.put("cpuMs", r.cpuMs);
            detail.put("cost", r.resultCost);
            detail.put("reached", r.reached);
            detail.put("termination", r.termination);
            detail.put("nodes", r.nodesChecked);
            detail.put("transports", r.transportsChecked);
            detail.put("capped", r.capped);
            detail.put("astar", r.astar);
            searchDetails.add(detail);
        }
        timingJson.put("searchDetails", searchDetails);
        return timingJson;
    }

    private File write(Map<String, Object> snapshot) throws java.io.IOException {
        File dir = new File(RuneLite.RUNELITE_DIR, "gps-debug");
        //noinspection ResultOfMethodCallIgnored
        dir.mkdirs();
        File out = new File(dir, "gps-capture-" + new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date()) + ".json");
        Gson gson = plugin.gson().newBuilder().setPrettyPrinting().create();
        try (Writer writer = new OutputStreamWriter(new FileOutputStream(out), StandardCharsets.UTF_8)) {
            gson.toJson(snapshot, writer);
        }
        return out;
    }

    /** A method's identity as the dashboard reads it: type, display info, destination. */
    private static String methodKey(TeleportMethod method) {
        return method.getType() + "|" + method.getDisplayInfo() + "|" + method.getDestination();
    }

    /** The directions as JSON rows: text, indexes, ticks and the step kind flags. */
    static List<Object> stepsJson(List<RouteDirections.Step> steps) {
        List<Object> stepsJson = new ArrayList<>();
        for (RouteDirections.Step step : steps) {
            Map<String, Object> stepJson = new LinkedHashMap<>();
            stepJson.put("text", step.getText());
            stepJson.put("startIndex", step.getStartIndex());
            stepJson.put("endIndex", step.getEndIndex());
            stepJson.put("ticks", step.getTicks());
            stepJson.put("transport", step.isTransport());
            stepJson.put("door", step.isDoor());
            stepJson.put("obstacle", step.isObstacle());
            stepsJson.add(stepJson);
        }
        return stepsJson;
    }

    /** A packed point as {packed, x, y, plane}, or null when undefined. */
    static Map<String, Object> packedPointJson(int packed) {
        if (packed == WorldPointUtil.UNDEFINED)
            return null;
        Map<String, Object> point = new LinkedHashMap<>();
        point.put("packed", packed);
        point.put("x", WorldPointUtil.unpackWorldX(packed));
        point.put("y", WorldPointUtil.unpackWorldY(packed));
        point.put("plane", WorldPointUtil.unpackWorldPlane(packed));
        return point;
    }
}

package gps;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import gps.transport.parser.FieldParser;
import gps.transport.parser.QuestParser;
import gps.transport.parser.SkillRequirementParser;
import gps.transport.parser.VarRequirement;
import gps.transport.parser.VarRequirementParser;

/**
 * Utility loader for destination coordinate sets grouped by feature category.
 * <p>
 * Destination data is stored in tab-separated value (TSV) resources under
 * {@code /destinations/**}. Each file's
 * first non-empty line is treated as a header (leading comment markers
 * {@code #} or {@code # } are stripped) and
 * defines column names. Rows beginning with {@code #} or blank lines are
 * ignored. Columns named "Destination" are
 * parsed as space-delimited triples {@code (x y plane)} that are packed into
 * single {@code int} values via
 * {@link WorldPointUtil#packWorldPoint(int, int, int)}.
 */
@Slf4j
public class Destination {
    private static final FieldParser<int[]> SKILL_PARSER = new SkillRequirementParser();
    private static final FieldParser<Set<Quest>> QUEST_PARSER = new QuestParser();
    private static final FieldParser<Set<VarRequirement>> VARBIT_PARSER = VarRequirementParser.forVarbits();
    private static final FieldParser<Set<VarRequirement>> VARPLAYER_PARSER = VarRequirementParser.forVarPlayers();
    private static final String DELIM_COLUMN = "\t";
    private static final String PREFIX_COMMENT = "#";
    private static final String FILE_EXTENSION = ".";
    private static final String DELIM_PATH = "/";
    private static final String DELIM = " ";

    /**
     * Parses a TSV resource of destination coordinates and merges them into the provided map.
     * The key in the destination map is derived from the directory component immediately preceding the file
     * name (e.g., {@code /destinations/game_features/bank.tsv -> bank}).
     *
     * @param destinations accumulator map of category key to a set of packed world point integers.
     * @param path         classpath resource path to a TSV file beginning with a header line.
     * @throws RuntimeException wrapping {@link IOException} if the resource cannot be read.
     */
    private static void addDestinations(Map<String, Set<Integer>> destinations, String path) {
        try {
            String s = new String(Util.readAllBytes(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream(path))),
                StandardCharsets.UTF_8);
            Scanner scanner = new Scanner(s);

            // Header line is the first line in the file and will start with either '#' or
            // '# '
            String[] headers = parse_header_line(scanner);

            String[] parts = path.replace(FILE_EXTENSION, DELIM_PATH).split(DELIM_PATH);
            String entry = parts[parts.length - 2];

            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();

                if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
                    continue;

                String[] fields = line.split(DELIM_COLUMN);
                Map<String, List<String>> fieldMap = new HashMap<>();
                for (int i = 0; i < headers.length; i++) {
                    if (i < fields.length) {
                        List<String> values = fieldMap.getOrDefault(headers[i], new ArrayList<>());
                        values.add(fields[i]);
                        fieldMap.put(headers[i], values);
                    }
                }
                for (String field : fieldMap.keySet()) {
                    if ("Destination".equals(field)) {
                        for (String value : fieldMap.get(field)) {
                            try {
                                String[] destinationArray = value.split(DELIM);
                                if (destinationArray.length == 3) {
                                    Set<Integer> entryDestinations = destinations.getOrDefault(entry, new HashSet<>());
                                    entryDestinations.add(WorldPointUtil.packWorldPoint(
                                        Integer.parseInt(destinationArray[0]),
                                        Integer.parseInt(destinationArray[1]),
                                        Integer.parseInt(destinationArray[2])));
                                    destinations.put(entry, entryDestinations);
                                }
                            }
                            catch (NumberFormatException e) {
                                log.error("Invalid destination coordinate", e);
                            }
                        }
                    }
                }
            }
            scanner.close();
        }
        catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static String[] parse_header_line(Scanner scanner) {
        String headerLine = scanner.nextLine();
        headerLine = headerLine.startsWith(PREFIX_COMMENT + " ")
            ? headerLine.replace(PREFIX_COMMENT + " ", PREFIX_COMMENT)
            : headerLine;
        headerLine = headerLine.startsWith(PREFIX_COMMENT) ? headerLine.replace(PREFIX_COMMENT, "") : headerLine;
        return headerLine.split(DELIM_COLUMN);
    }

    /**
     * Loads a predefined subset of destination categories from bundled TSV resources.
     *
     * @return a map from destination category key to a set of packed world point integers.
     */
    public static Map<String, Set<Integer>> loadAllFromResources() {
        Map<String, Set<Integer>> destinations = new HashMap<>(10);
        addDestinations(destinations, "/destinations/game_features/altar.tsv");
        addDestinations(destinations, "/destinations/game_features/bank.tsv");
        addDestinations(destinations, "/destinations/training/anvil.tsv");
        addDestinations(destinations, "/destinations/shopping/apothecary.tsv");
        return destinations;
    }

    /**
     * Per-packed-point requirements for bank tiles, parsed from {@code bank.tsv} columns
     * Skills, Quests, Varbits, and VarPlayers (same TSV format as transports).
     * Tiles with no requirement rows behave as {@link DestinationRequirements#EMPTY}.
     */
    public static Map<Integer, DestinationRequirements> loadBankRequirementsFromResources() {
        Map<Integer, DestinationRequirements> requirements = new HashMap<>();
        final String path = "/destinations/game_features/bank.tsv";
        final String DELIM_COLUMN = "\t";
        final String PREFIX_COMMENT = "#";
        final String DELIM = " ";

        try {
            String s = new String(Util.readAllBytes(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream(path))), StandardCharsets.UTF_8);
            try (Scanner scanner = new Scanner(s)) {
                String[] headers = parse_header_line(scanner);
                for (int i = 0; i < headers.length; i++)
                    headers[i] = headers[i].trim();

                int destCol = indexOf(headers, "Destination");
                int skillsCol = indexOf(headers, "Skills");
                int questsCol = indexOf(headers, "Quests");
                int varbitsCol = indexOf(headers, "Varbits");
                int varPlayersCol = indexOf(headers, "VarPlayers");
                if (destCol < 0)
                    return requirements;

                while (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
                        continue;
                    String[] fields = line.split(DELIM_COLUMN, -1);
                    if (fields.length <= destCol)
                        continue;
                    String destField = fields[destCol].trim();
                    String[] destinationArray = destField.split(DELIM);
                    if (destinationArray.length != 3)
                        continue;
                    int packed;
                    try {
                        packed = WorldPointUtil.packWorldPoint(
                            Integer.parseInt(destinationArray[0]),
                            Integer.parseInt(destinationArray[1]),
                            Integer.parseInt(destinationArray[2]));
                    }
                    catch (NumberFormatException e) {
                        log.error("Invalid destination coordinate in bank.tsv", e);
                        continue;
                    }

                    String skillsStr = fieldAt(fields, skillsCol);
                    String questsStr = fieldAt(fields, questsCol);
                    String varbitsStr = fieldAt(fields, varbitsCol);
                    String varPlayersStr = fieldAt(fields, varPlayersCol);

                    int[] skillLevels = skillsCol >= 0 ? SKILL_PARSER.parse(blankToNull(skillsStr)) : new int[Skill.values().length + 3];
                    Set<Quest> quests = questsCol >= 0 ? QUEST_PARSER.parse(blankToNull(questsStr)) : Set.of();
                    Set<VarRequirement> varbits = varbitsCol >= 0 ? VARBIT_PARSER.parse(blankToNull(varbitsStr)) : Set.of();
                    Set<VarRequirement> varPlayers = varPlayersCol >= 0 ? VARPLAYER_PARSER.parse(blankToNull(varPlayersStr)) : Set.of();

                    DestinationRequirements rowReq = new DestinationRequirements(skillLevels, quests, varbits, varPlayers);
                    requirements.merge(packed, rowReq, DestinationRequirements::merge);
                }
            }
        }
        catch (IOException e) {
            throw new RuntimeException(e);
        }
        return requirements;
    }

    private static int indexOf(String[] headers, String name) {
        for (int i = 0; i < headers.length; i++) {
            if (name.equals(headers[i]))
                return i;
        }
        return -1;
    }

    private static String fieldAt(String[] fields, int col) {
        if (col < 0 || col >= fields.length)
            return "";
        return fields[col];
    }

    private static String blankToNull(String s) {
        return s == null || s.isBlank() ? null : s;
    }
}

package gps;

import gps.pathfinder.PathfinderConfig;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import net.runelite.api.ChatMessageType;

/**
 * The GPS destination (plan step L36, out of the plugin class): the single source of truth for
 * where the player is going, and every way of setting it. A map pin or a searched place expands
 * to its walkable ring (a pin on furniture, a fence or an NPC's tile can never be settled by the
 * search; the world-map pin stays on the tile itself); an amenity category targets every site so
 * the nearest surfaces first, optionally as a round trip; another plugin's request arrives
 * already expanded. Setting a destination refreshes the live pathfinder config, filters the
 * ends, resets the route budget and the off-route tracker, arms the journey clock and places the
 * pin; the routes themselves come from the auto-compute on the next tick, keyed on the target
 * set, or from an explicit recompute. Written on the client thread, read from ticks and overlays.
 */
final class DestinationController {
    private final ShortestPathPlugin plugin;
    private final RouteSession session;
    private final RouteController routes;
    private final WorldMapMarker marker;
    private final OffRouteTracker offRoute;
    private final JourneyTracker journey;

    private volatile int start = WorldPointUtil.UNDEFINED;
    private volatile Set<Integer> targets = Set.of();
    // Where the destination came from, for the GPS header: "map pin" for manual targets, the
    // sender's self-declared source for plugin messages (else "another plugin"), null when unset.
    private volatile String source;
    // Whether the destination is a round trip (out and back, "nearest bank (and back)"): set by
    // the round-trip entry point after the targets, carried into every generation for this
    // destination (refresh, show more), cleared when a new target is set.
    private volatile boolean roundTrip;
    // The destination a nearest-bank trip replaced, resumed when the trip completes (see BankDetour).
    private final BankDetour bankTrip = new BankDetour();

    DestinationController(ShortestPathPlugin plugin, RouteSession session, RouteController routes,
        WorldMapMarker marker, OffRouteTracker offRoute, JourneyTracker journey) {
        this.plugin = plugin;
        this.session = session;
        this.routes = routes;
        this.marker = marker;
        this.offRoute = offRoute;
        this.journey = journey;
    }

    int start() {
        return start;
    }

    Set<Integer> targets() {
        return targets;
    }

    boolean hasTargets() {
        return !targets.isEmpty();
    }

    String source() {
        return source;
    }

    /** Attributes the destination for the GPS header: the sender's source, "map pin", or null. */
    void setSource(String source) {
        this.source = source;
    }

    boolean isRoundTrip() {
        return roundTrip;
    }

    /** "Set GPS Target" from the map menu: the pick is attributed to the map pin. Client thread. */
    void pin(int packed) {
        source = "map pin";
        setTarget(packed, false);
    }

    /** "Find closest" from a world-map icon: every destination of that kind, the nearest wins. */
    void findClosest(String destinationType) {
        source = "map pin";
        setTargets(plugin.getPathfinderConfig().getDestinations(destinationType), true);
    }

    /** Clears the destination and its attribution, on the client thread (a tick, a hotkey, a clear request). */
    void clear() {
        source = null;
        setTarget(WorldPointUtil.UNDEFINED, false);
    }

    /** Clears the destination from another thread (the panel's Clear button). */
    void clearLater() {
        plugin.getClientThread().invokeLater(this::clear);
    }

    /**
     * The player arrived: the destination clears, and a completed bank trip picks the destination
     * it replaced back up, from the bank, with a chat line saying so (see BankDetour). Client thread.
     */
    void arrived() {
        // Read before the clear, which would forget it.
        BankDetour.Route resume = bankTrip.complete();
        clear();
        if (resume == null)
            return;
        source = resume.source;
        if (resume.marker != WorldPointUtil.UNDEFINED)
            marker.pinNextAt(resume.marker);
        setTargets(new HashSet<>(resume.targets), false);
        // After setTargets: it resets the round-trip flag for ordinary destinations.
        roundTrip = resume.roundTrip;
        if (resume.roundTrip)
            routes.recompute();
        plugin.getClient().addChatMessage(ChatMessageType.GAMEMESSAGE, "",
            "GPS: bank reached, resuming your previous route.", null);
    }

    /** Another plugin's new destination replaces a bank trip like any other change. */
    void forgetBankTrip() {
        bankTrip.cancel();
    }

    /** The destination the current bank trip will resume, or null (see BankDetour.pending). */
    BankDetour.Route pendingResume() {
        return bankTrip.pending();
    }

    /** Whether a bank click now would add a stop: a route would resume after it (see BankDetour.wouldResume). */
    boolean bankClickAddsStop() {
        return bankTrip.wouldResume(hasTargets());
    }

    /**
     * A searched place or amenity (the panel search box), attributed to {@code source}. A label
     * can sit on an unwalkable tile (a fountain): it expands to the nearest walkable ring, like a
     * map pin, while the world-map pin stays on the place itself.
     */
    void setSearched(int packedPosition, String source) {
        plugin.getClientThread().invokeLater(() -> {
            this.source = source;
            Set<Integer> expanded = new HashSet<>(walkable(packedPosition));
            if (expanded.size() > 1)
                marker.pinNextAt(packedPosition);
            setTargets(expanded, false);
        });
    }

    /**
     * The NEAREST of an amenity category (bank, altar, ...): every tile of the category is a
     * target, so the shortest paths with the teleports currently available surface first,
     * whichever site they reach. A round trip additionally routes BACK to the current position:
     * every route goes out to a site and home again, ranked by the combined cost (the best
     * round-trip bank is not necessarily the nearest one-way bank).
     */
    void setNearestCategory(Set<Integer> tiles, String source, boolean roundTrip) {
        if (tiles == null || tiles.isEmpty())
            return;
        plugin.getClientThread().invokeLater(() -> {
            this.source = source;
            setTargets(new HashSet<>(tiles), false);
            // After setTargets: it resets the round-trip flag for ordinary destinations.
            this.roundTrip = roundTrip;
            routes.recompute();
        });
    }

    /**
     * Runs one nearest-X option: the panel's quick buttons and menu, its search box's nearest-of
     * row, and the two bank hotkeys. A bank option starts a bank trip: the destination it replaces
     * is resumed once the trip completes (see BankDetour). The tiles are read on the calling
     * thread, as the panel always read them; the destination changes on the client thread.
     */
    void goToNearest(Destinations.NearestOption option) {
        Set<Integer> tiles = Destinations.tilesForCategory(option.id, plugin.getTransports());
        boolean trip = "bank_round_trip".equals(option.id);
        boolean bank = trip || "bank".equals(option.id);
        if (bank)
            // Union in the engine's accessible-bank tiles: the amenity dump misses oddly-named
            // bank objects (Slepe's "Bank Chest-wreck"), and "nearest bank" must never disagree
            // with where the engine itself can bank.
            tiles.addAll(plugin.getEngineBankTiles());
        String label = "nearest " + option.label.toLowerCase(Locale.ROOT);
        if (!bank) {
            setNearestCategory(tiles, label, false);
            return;
        }
        if (tiles.isEmpty())
            return;
        plugin.getClientThread().invokeLater(() -> {
            if (plugin.getPlayerLocation() == WorldPointUtil.UNDEFINED)
                // Logged out: setTargets would change nothing, so no trip may start either.
                return;
            // Read before the destination changes: setting it forgets any trip under way.
            BankDetour.Route replaced = bankTrip.replacing(
                BankDetour.Route.of(targets, source, roundTrip, marker.pinnedTile()));
            source = label;
            setTargets(new HashSet<>(tiles), false);
            // After setTargets: it resets the round-trip flag and forgets the trip.
            roundTrip = trip;
            bankTrip.begin(replaced);
            routes.recompute();
        });
    }

    /**
     * Records the destination (after the wilderness filter) and refreshes the live config so
     * display lookups (transport labels, house exits) see current availability. Route
     * computation happens in the generation, auto-triggered on the next tick by the target-set
     * change. Hops to the client thread.
     */
    void set(int newStart, Set<Integer> ends, boolean canReviveFiltered) {
        plugin.getClientThread().invokeLater(() -> {
            PathfinderConfig pathfinderConfig = plugin.getPathfinderConfig();
            // The panel's method catalog is the single customization surface: methods the user has
            // excluded there are also excluded here.
            pathfinderConfig.setExcludedMethods(plugin.getUserExclusions());
            pathfinderConfig.refresh();
            pathfinderConfig.filterLocations(ends, canReviveFiltered);
            if (ends.isEmpty())
                setTarget(WorldPointUtil.UNDEFINED, false);
            else {
                start = newStart;
                targets = Set.copyOf(ends);
            }
        });
    }

    /**
     * Regenerates from the player's current position for the same targets (the off-route
     * recalculation): explicit, because the auto-compute is keyed on the target set, which has
     * not changed. The stale selection is dropped so the fresh generation's route takes over
     * rather than the overlay clinging to the old line. Client thread.
     */
    void recalculateFrom(int newStart, Set<Integer> currentTargets) {
        session.clearSelection();
        session.resetBudget(routes.defaultLimit());
        Set<Integer> ends = new HashSet<>(currentTargets);
        start = newStart;
        routes.trigger(newStart, ends);
    }

    /** A single tile, expanded to its walkable ring; UNDEFINED clears. Client thread. */
    private void setTarget(int target, boolean append) {
        Set<Integer> expanded = new HashSet<>();
        if (target != WorldPointUtil.UNDEFINED) {
            // A pin on an unwalkable tile (furniture, a fence, an NPC's tile from Quest Helper) can
            // never be settled by the search: it would explore the entire map and fall back to a
            // closest-tile path (captured in-game: 11 exhausted searches, 8.2 s). Target the nearest
            // walkable ring instead; walkable pins stay exact, and the map pin stays on the tile.
            Set<Integer> ring = walkable(target);
            if (ring.size() > 1)
                marker.pinNextAt(target);
            expanded.addAll(ring);
        }
        setTargets(expanded, append);
    }

    private Set<Integer> walkable(int packed) {
        PathfinderConfig pathfinderConfig = plugin.getPathfinderConfig();
        return Destinations.walkableTargets(pathfinderConfig != null ? pathfinderConfig.getMap() : null, packed,
            pathfinderConfig != null ? pathfinderConfig::isTransportOrigin : null);
    }

    /** The target set as given (already expanded); empty clears. Client thread. */
    private void setTargets(Set<Integer> newTargets, boolean append) {
        // Any change of destination forgets a bank trip's saved route; a bank trip re-arms after.
        bankTrip.cancel();
        // Ordinary destinations are one-way; the round-trip entry point re-sets this after.
        roundTrip = false;
        // A fresh destination starts at the default cost band; "show more" widens it from there
        // (it bumps the multiple and regenerates without coming through here).
        session.resetCostMultiple();
        if (newTargets == null || newTargets.isEmpty()) {
            start = WorldPointUtil.UNDEFINED;
            targets = Set.of();
            marker.clear();
            session.clearSelection();
            session.setLimit(routes.defaultLimit());
            // Keep the teleport-methods catalog visible with no target selected.
            routes.trigger(WorldPointUtil.UNDEFINED, new HashSet<>());
            return;
        }
        int here = plugin.getPlayerLocation();
        if (here == WorldPointUtil.UNDEFINED)
            return;
        marker.place(newTargets);
        offRoute.reset(here);
        Set<Integer> destinations = new HashSet<>(newTargets);
        if (append)
            destinations.addAll(targets);
        // Arm the journey timer: it starts counting from the player's first movement.
        journey.arm();
        // The routes themselves come from the tick-level auto-compute (keyed on the target-set
        // change) or the panel's "Find routes" button.
        set(here, destinations, append);
    }
}

package gps;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import gps.transport.parser.VarRequirement;

/**
 * Optional access requirements for a destination tile (e.g. bank booths). Empty requirements mean
 * the destination is always usable when reached.
 */
public final class DestinationRequirements {
    /**
     * All-zero skill array; no skill requirements.
     */
    public static final DestinationRequirements EMPTY = new DestinationRequirements();

    @Getter
    private final int[] skillLevels;
    @Getter
    private final Set<Quest> quests;
    @Getter
    private final Set<VarRequirement> varbits;
    @Getter
    private final Set<VarRequirement> varPlayers;

    private DestinationRequirements() {
        this.skillLevels = new int[Skill.values().length + 3];
        this.quests = Collections.emptySet();
        this.varbits = Collections.emptySet();
        this.varPlayers = Collections.emptySet();
    }

    public DestinationRequirements(
        int[] skillLevels,
        Set<Quest> quests,
        Set<VarRequirement> varbits,
        Set<VarRequirement> varPlayers) {
        this.skillLevels = skillLevels != null ? skillLevels : new int[Skill.values().length + 3];
        this.quests = quests != null ? quests : Collections.emptySet();
        this.varbits = varbits != null ? varbits : Collections.emptySet();
        this.varPlayers = varPlayers != null ? varPlayers : Collections.emptySet();
    }

    /**
     * @return a merged requirement when the same tile appears on multiple rows (max skills, union sets).
     */
    public static DestinationRequirements merge(DestinationRequirements a, DestinationRequirements b) {
        if (a == null || a.isEmpty())
            return b != null ? b : EMPTY;
        if (b == null || b.isEmpty())
            return a;
        int[] skills = new int[Skill.values().length + 3];
        for (int i = 0; i < skills.length; i++)
            skills[i] = Math.max(a.skillLevels[i], b.skillLevels[i]);
        Set<Quest> q = new HashSet<>(a.quests);
        q.addAll(b.quests);
        Set<VarRequirement> vb = new HashSet<>(a.varbits);
        vb.addAll(b.varbits);
        Set<VarRequirement> vp = new HashSet<>(a.varPlayers);
        vp.addAll(b.varPlayers);
        return new DestinationRequirements(skills, q, vb, vp);
    }

    public boolean isEmpty() {
        if (!quests.isEmpty())
            return false;
        if (!varbits.isEmpty() || !varPlayers.isEmpty())
            return false;
        for (int level : skillLevels) {
            if (level > 0)
                return false;
        }
        return true;
    }
}

