final class DestinationSearchView extends JPanel {
    // The Bank quick button, restyled while a click would add a stop (see showBankStop).
    private JButton bankButton;
    private boolean bankButtonAddsStop;
    private static final int MAX_DESTINATION_RESULTS = 12;
    // "x, y" or "x y", with an optional plane (0-3): x is 4 digits (the playable range is roughly
    // 1000-4600), y 4-5 digits (surface ~3000-4200; dungeon/instance planes reach past 10000).
    private static final Pattern COORDINATE_QUERY = Pattern.compile("(\\d{4})[,;\\s]+(\\d{4,5})(?:[,;\\s]+([0-3]))?");
    // Selected search-result row: a blue-tinted background plus a GPS-blue accent bar; the two
    // near-identical dark greys the highlight used before were invisible when arrowing through.
    private static final Color RESULT_SELECTED_BG = new Color(0x2E, 0x3E, 0x5E);

    private final ShortestPathPlugin plugin;
    private final IconTextField searchField = new IconTextField();
    private final JPanel results = new JPanel();
    // The search results float over the panel in a non-focusable popup anchored under the search
    // field (autocomplete-style).
    private final JPopupMenu popup = new JPopupMenu();
    // The name-search index (places + dungeons + minigames), built once the transport data is
    // available: it is session-static, so caching avoids rescanning transports on every keystroke.
    private List<Destinations.Entry> index;
    // The currently-shown search result rows and their entries (parallel), plus the keyboard-
    // selected index into them (-1 = none). Up/Down move it, Enter picks it; mouse hover keeps it
    // in sync so both input methods share one highlight.
    private final List<JPanel> resultRows = new ArrayList<>();
    private final List<Destinations.Entry> resultEntries = new ArrayList<>();
    private int selectedResult = -1;
    // The inline favourite editor.
    private final JPanel favoriteEditor = new JPanel();
    private final JTextField favoriteLabelInput = new JTextField();
    private final JTextField favoritePositionInput = new JTextField();
    private final JLabel favoriteError = new JLabel();

    DestinationSearchView(ShortestPathPlugin plugin) {
        this.plugin = plugin;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 0, 0, 0));

        // Header: the section label plus the favourite-saving heart on the right.
        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setAlignmentX(LEFT_ALIGNMENT);
        header.add(sectionLabel("Go to a place"), BorderLayout.CENTER);
        IconActionLabel saveFavorite = new IconActionLabel(RouteIcons.FAVORITE, RouteIcons.FAVORITE_HOVER,
            "Save a favourite position with a label (your current tile, or any coordinates)",
            this::toggleFavoriteEditor);
        header.add(verticallyCentered(control(saveFavorite)), BorderLayout.EAST);

        buildFavoriteEditor();
        // Above the "Go to a place" header: saving a favourite is its own little task, not part
        // of the search flow below it.
        add(fullWidth(favoriteEditor));
        add(fullWidth(header));
        buildSearchField();
        add(searchField);

        results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
        results.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        // Hosted in a floating popup under the search field, NOT in the panel flow. Non-focusable
        // so typing stays in the search field while the popup is showing.
        popup.setFocusable(false);
        popup.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        popup.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        popup.setLayout(new BorderLayout());
        popup.add(results, BorderLayout.CENTER);

        // "Find nearest": a single button opening a menu of amenity types; picking one routes to the
        // closest of that type using available teleports.
        add(buildNearestRow());
    }

    /**
     * Focuses the search box and selects any existing text, so the focus-search hotkey lands the
     * caret ready to type. Marshalled to the EDT and deferred so the panel (just opened by the
     * hotkey) is laid out and focusable first.
     */
    void focusSearch() {
        SwingUtilities.invokeLater(() -> {
            searchField.requestFocusInWindow();
            JTextField inner = innerTextField(searchField);
            if (inner != null)
                inner.selectAll();
            // Surface the recent-searches list (the focus listener does this too, but requesting
            // focus on an already-focused field will not re-fire it).
            renderResults();
        });
    }

    /** Closes the results popup (the panel is being hidden). */
    void hidePopup() {
        popup.setVisible(false);
    }

    /**
     * Parses a typed coordinate query into a packed world point, or {@link WorldPointUtil#UNDEFINED}
     * when the text is not a plausible in-world coordinate pair.
     */
    static int parseCoordinateQuery(String query) {
        Matcher matcher = COORDINATE_QUERY.matcher(query);
        if (!matcher.matches())
            return WorldPointUtil.UNDEFINED;
        int x = Integer.parseInt(matcher.group(1));
        int y = Integer.parseInt(matcher.group(2));
        int plane = matcher.group(3) != null ? Integer.parseInt(matcher.group(3)) : 0;
        if (x > 4600 || y > 12900)
            return WorldPointUtil.UNDEFINED;
        return WorldPointUtil.packWorldPoint(x, y, plane);
    }

    /**
     * The name matches for {@code query} in {@code pool}, best first: the score tiers (exact,
     * prefix, word prefixes, substring, subsequence) rank the list; proximity to {@code player}
     * breaks ties within a tier, or the name when the player's position is unknown; at most
     * {@link #MAX_DESTINATION_RESULTS}.
     */
    static List<Destinations.Entry> rank(List<Destinations.Entry> pool, String query, int player) {
        List<Destinations.Entry> matches = new ArrayList<>();
        Map<Destinations.Entry, Integer> scores = new HashMap<>();
        for (Destinations.Entry entry : pool) {
            int score = SearchMatcher.score(entry.name, query);
            if (score > 0) {
                matches.add(entry);
                scores.put(entry, score);
            }
        }
        Comparator<Destinations.Entry> byScore = Comparator.comparingInt(e -> -scores.getOrDefault(e, 0));
        if (player != WorldPointUtil.UNDEFINED)
            matches.sort(byScore.thenComparingInt(e -> WorldPointUtil.distanceBetween(player, e.packedPosition)));
        else
            matches.sort(byScore.thenComparing(e -> e.name));
        return matches.size() > MAX_DESTINATION_RESULTS ? matches.subList(0, MAX_DESTINATION_RESULTS) : matches;
    }

    private void buildFavoriteEditor() {
        // Two labelled fields: Name and At (coordinates, prefilled with the current tile;
        // "3221 3218", "3221,3218,1" and "3221, 3218 0" all parse; empty = current tile). Tab
        // moves between them, Enter saves from either, Esc closes.
        KeyAdapter escapeCloses = new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
                    favoriteEditor.setVisible(false);
            }
        };
        for (JTextField field : new JTextField[]{favoriteLabelInput, favoritePositionInput}) {
            field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            field.setForeground(Color.WHITE);
            field.setCaretColor(Color.WHITE);
            field.setFont(FontManager.getRunescapeSmallFont());
            field.addActionListener(e -> attemptSaveFavorite());
            field.addKeyListener(escapeCloses);
        }
        favoriteLabelInput.setToolTipText("The favourite's name, shown in search results");
        favoritePositionInput.setToolTipText("<html>Where it is: \"3221 3218\", \"3221,3218,1\" or"
            + " \"3221, 3218 0\".<br>Empty = your current tile.</html>");
        JButton favoriteSave = new JButton("Save");
        favoriteSave.setMargin(new Insets(2, 8, 2, 8));
        favoriteSave.setFont(FontManager.getRunescapeSmallFont());
        favoriteSave.addActionListener(e -> attemptSaveFavorite());
        JPanel positionRow = new JPanel(new BorderLayout(4, 0));
        positionRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        positionRow.add(favoritePositionInput, BorderLayout.CENTER);
        positionRow.add(favoriteSave, BorderLayout.EAST);
        favoriteError.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
        favoriteError.setFont(FontManager.getRunescapeSmallFont());
        favoriteError.setVisible(false);
        favoriteEditor.setLayout(new BoxLayout(favoriteEditor, BoxLayout.Y_AXIS));
        favoriteEditor.setBackground(ColorScheme.DARK_GRAY_COLOR);
        favoriteEditor.setBorder(new EmptyBorder(0, 0, 6, 0));
        favoriteEditor.setAlignmentX(LEFT_ALIGNMENT);
        favoriteError.setAlignmentX(LEFT_ALIGNMENT);
        // Title row: the section label plus a red cross to close (the heart also toggles, Esc too).
        JPanel titleRow = new JPanel(new BorderLayout());
        titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleRow.setAlignmentX(LEFT_ALIGNMENT);
        titleRow.add(sectionLabel("Save a favourite"), BorderLayout.CENTER);
        IconActionLabel close = new IconActionLabel(RouteIcons.CROSS_RED, RouteIcons.CROSS_RED_HOVER,
            "Close without saving", () -> favoriteEditor.setVisible(false));
        titleRow.add(verticallyCentered(control(close)), BorderLayout.EAST);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, titleRow.getPreferredSize().height));
        favoriteEditor.add(titleRow);
        favoriteEditor.add(favoriteFieldRow("Name", favoriteLabelInput));
        favoriteEditor.add(Box.createVerticalStrut(3));
        favoriteEditor.add(favoriteFieldRow("At", positionRow));
        favoriteEditor.add(favoriteError);
        favoriteEditor.setVisible(false);
    }

    private void buildSearchField() {
        searchField.setIcon(IconTextField.Icon.SEARCH);
        searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
        searchField.setToolTipText("Search places, dungeons and minigames by name,"
            + " or type coordinates (\"3221, 3218\", optional plane: \"3221 3218 1\")");
        // Taller than the default field height for an easier click target and more presence: it
        // is the section's primary control.
        final int searchHeight = 32;
        searchField.setPreferredSize(new Dimension(searchField.getPreferredSize().width, searchHeight));
        searchField.setMinimumSize(new Dimension(0, searchHeight));
        searchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, searchHeight));
        searchField.setAlignmentX(LEFT_ALIGNMENT);
        searchField.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                renderResults();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                renderResults();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                renderResults();
            }
        });
        // Clicking into the empty box offers the recent searches; IconTextField does not expose its
        // inner text field, so find it in the component tree to hear focus.
        JTextField inner = innerTextField(searchField);
        if (inner == null)
            return;
        inner.addFocusListener(new FocusAdapter() {
            @Override
            public void focusGained(FocusEvent e) {
                renderResults();
            }
        });
        // Up/Down move the highlighted result, Enter picks it, Escape closes the popup, so a
        // destination can be chosen without leaving the keyboard.
        inner.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (!popup.isVisible())
                    return;
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_DOWN:
                        moveSelection(1);
                        e.consume();
                        break;
                    case KeyEvent.VK_UP:
                        moveSelection(-1);
                        e.consume();
                        break;
                    case KeyEvent.VK_ENTER:
                        if (selectedResult >= 0 && selectedResult < resultEntries.size()) {
                            selectEntry(resultEntries.get(selectedResult));
                            e.consume();
                        }
                        break;
                    case KeyEvent.VK_ESCAPE:
                        popup.setVisible(false);
                        e.consume();
                        break;
                    default:
                        break;
                }
            }
        });
    }

    /**
     * The nearest-X row: a compact "Find nearest" opener plus icon-only quick buttons for the most
     * common targets (bank, bank-and-back); the full-width button pulled attention away from the
     * search box above, the section's primary control.
     */
    private JPanel buildNearestRow() {
        JPanel row = new JPanel(new BorderLayout(4, 0));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.setBorder(new EmptyBorder(4, 0, 0, 0));
        row.setAlignmentX(LEFT_ALIGNMENT);

        JButton menuButton = subtleButton(new JButton("Find nearest…"));
        menuButton.setHorizontalAlignment(SwingConstants.CENTER);
        menuButton.setToolTipText("Route to the nearest altar / water source / furnace / … using available teleports");
        menuButton.addActionListener(e -> showNearestMenu(menuButton));
        row.add(menuButton, BorderLayout.CENTER);

        JPanel quick = new JPanel(new FlowLayout(FlowLayout.LEADING, 4, 0));
        quick.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton bank = nearestQuickButton("bank");
        bankButton = bank;
        if (bank != null)
            quick.add(bank);
        JButton bankAndBack = nearestQuickButton("bank_round_trip");
        if (bankAndBack != null)
            quick.add(bankAndBack);
        row.add(quick, BorderLayout.EAST);

        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        return row;
    }

    /**
     * Shows on the Bank quick button whether a click adds a stop: with a route under way (or a bank
     * trip that will resume one) the route resumes after the bank, so the icon carries a "+" badge
     * and the tooltip says so. Bank (and back) keeps its look: it returns to where you are anyway.
     * Called on every render; restyles only on a change. EDT.
     */
    void showBankStop(boolean addsStop) {
        if (bankButton == null || addsStop == bankButtonAddsStop)
            return;
        bankButtonAddsStop = addsStop;
        bankButton.setIcon(RouteIcons.bankButtonIcon(addsStop));
        bankButton.setToolTipText(BankDetour.bankButtonTooltip(addsStop));
    }

    /** An icon-only quick button running one nearest-X option directly (tooltip names it). */
    private JButton nearestQuickButton(String optionId) {
        for (Destinations.NearestOption option : Destinations.NEAREST_OPTIONS) {
            if (option.id.equals(optionId)) {
                JButton button = subtleButton(new JButton(RouteIcons.destinationIcon(option.id)));
                button.setToolTipText("Nearest " + option.label.toLowerCase(Locale.ROOT));
                button.addActionListener(e -> runNearestOption(option));
                return button;
            }
        }
        return null;
    }

    /** Runs one nearest-X option, shared by the menu items and the quick buttons (see DestinationController.goToNearest). */
    private void runNearestOption(Destinations.NearestOption option) {
        plugin.goToNearest(option);
        searchField.setText("");
    }

    private void showNearestMenu(JComponent anchor) {
        JPopupMenu menu = new JPopupMenu();
        menu.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        menu.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        for (Destinations.NearestOption option : Destinations.NEAREST_OPTIONS) {
            JMenuItem item = new JMenuItem(option.label, RouteIcons.destinationIcon(option.id));
            item.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            item.setForeground(Color.WHITE);
            item.setFont(FontManager.getRunescapeSmallFont());
            item.setIconTextGap(6);
            item.addActionListener(e -> runNearestOption(option));
            menu.add(item);
        }
        menu.show(anchor, 0, anchor.getHeight());
    }

    /** The cached name-search index; (re)built only once the transport data is available. */
    private List<Destinations.Entry> index() {
        List<Destinations.Entry> cached = index;
        if (cached != null)
            return cached;
        List<Destinations.Entry> built = Destinations.searchable(plugin.getTransports());
        if (plugin.getTransports() != null)
            index = built;
        return built;
    }

    private void renderResults() {
        results.removeAll();
        resultRows.clear();
        resultEntries.clear();
        selectedResult = -1;
        String query = searchField.getText().trim();
        final int player = plugin.getLastKnownPlayerLocation();
        if (query.isEmpty()) {
            // An empty box offers the saved favourites and the recent selections instead of hiding:
            // reopening a frequent destination without retyping it.
            List<Destinations.Entry> favorites = plugin.getFavoriteDestinations();
            List<Destinations.Entry> history = plugin.getSearchHistory();
            if (favorites.isEmpty() && history.isEmpty()) {
                popup.setVisible(false);
                return;
            }
            if (!favorites.isEmpty()) {
                results.add(resultsHeader("Favourites"));
                for (Destinations.Entry entry : favorites)
                    addResultRow(entry, player);
            }
            if (!history.isEmpty()) {
                results.add(resultsHeader("Recent searches"));
                for (Destinations.Entry entry : history)
                    addResultRow(entry, player);
            }
            preselectFirstResult();
            showPopup();
            return;
        }

        // A typed coordinate pair ("3221, 3218", "3221 3218", optional plane "3221 3218 1") becomes
        // a direct route-to-tile result ahead of the name matches.
        int coordinate = parseCoordinateQuery(query);
        if (coordinate != WorldPointUtil.UNDEFINED) {
            int plane = WorldPointUtil.unpackWorldPlane(coordinate);
            addResultRow(new Destinations.Entry("coordinates",
                "Tile (" + WorldPointUtil.unpackWorldX(coordinate) + ", " + WorldPointUtil.unpackWorldY(coordinate)
                    + (plane > 0 ? ", plane " + plane : "") + ")",
                coordinate), player);
        }

        // "nearest altar", or a bare category word: the category's nearest-of row comes first.
        Destinations.NearestOption nearest = Destinations.parseNearest(query);
        if (nearest != null) {
            Set<Integer> tiles = Destinations.tilesForCategory(nearest.id, plugin.getTransports());
            if (!tiles.isEmpty()) {
                String label = nearest.label;
                addResultRow(new Destinations.Entry("bank_round_trip".equals(nearest.id) ? "bank" : nearest.id,
                    "Nearest " + Character.toLowerCase(label.charAt(0)) + label.substring(1),
                    WorldPointUtil.UNDEFINED, tiles, nearest), player);
            }
        }

        // Fuzzy match, best first (see rank). Saved favourites are part of the pool, matched by
        // their label.
        List<Destinations.Entry> pool = new ArrayList<>(plugin.getFavoriteDestinations());
        pool.addAll(index());
        for (Destinations.Entry entry : rank(pool, query, player))
            addResultRow(entry, player);
        if (resultEntries.isEmpty()) {
            JLabel none = new JLabel("No matching destination");
            none.setForeground(Color.GRAY);
            none.setFont(FontManager.getRunescapeSmallFont());
            none.setBorder(new EmptyBorder(2, 4, 2, 4));
            results.add(none);
        }
        preselectFirstResult();
        showPopup();
    }

    /** Builds a result row, adds it to the popup and tracks it for keyboard navigation. */
    private void addResultRow(Destinations.Entry entry, int player) {
        JPanel row = destinationRow(entry, player);
        resultEntries.add(entry);
        resultRows.add(row);
        results.add(row);
    }

    /** A small grey group header inside the results popup ("Favourites", "Recent searches"). */
    private static JLabel resultsHeader(String text) {
        JLabel header = new JLabel(text);
        header.setForeground(Color.GRAY);
        header.setFont(FontManager.getRunescapeSmallFont());
        header.setBorder(new EmptyBorder(2, 4, 2, 4));
        return header;
    }

    /** A small captioned row for the favourite editor (caption west, component center). */
    private static JPanel favoriteFieldRow(String caption, Component component) {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.setAlignmentX(LEFT_ALIGNMENT);
        JLabel label = new JLabel(caption);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setPreferredSize(new Dimension(34, label.getPreferredSize().height));
        row.add(label, BorderLayout.WEST);
        row.add(component, BorderLayout.CENTER);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height + 4));
        return row;
    }

    /** The heart button: shows (or hides) the inline favourite editor, prefilled with the current tile. */
    private void toggleFavoriteEditor() {
        if (favoriteEditor.isVisible()) {
            favoriteEditor.setVisible(false);
            return;
        }
        int player = plugin.getLastKnownPlayerLocation();
        String prefill = "";
        if (player != WorldPointUtil.UNDEFINED) {
            int plane = WorldPointUtil.unpackWorldPlane(player);
            prefill = WorldPointUtil.unpackWorldX(player) + " " + WorldPointUtil.unpackWorldY(player)
                + (plane > 0 ? " " + plane : "");
        }
        favoriteLabelInput.setText("");
        favoritePositionInput.setText(prefill);
        favoriteError.setVisible(false);
        favoriteEditor.setVisible(true);
        favoriteEditor.revalidate();
        // Name first: type the label, Tab to adjust the (prefilled) position, Enter to save.
        favoriteLabelInput.requestFocusInWindow();
    }

    /** Enter/Save in the inline editor: label + position (empty position = current tile). */
    private void attemptSaveFavorite() {
        String label = favoriteLabelInput.getText().trim();
        if (label.isEmpty()) {
            favoriteInputError("Name the favourite: it is what search results show.");
            favoriteLabelInput.requestFocusInWindow();
            return;
        }
        String positionText = favoritePositionInput.getText().trim();
        int position = positionText.isEmpty()
            ? plugin.getLastKnownPlayerLocation() : parseCoordinateQuery(positionText);
        if (position == WorldPointUtil.UNDEFINED) {
            favoriteInputError(positionText.isEmpty()
                ? "No position: log in, or type coordinates (\"3221 3218\", optional plane)."
                : "Not a coordinate: \"3221 3218\", \"3221,3218,1\" and \"3221, 3218 0\" all work.");
            favoritePositionInput.requestFocusInWindow();
            return;
        }
        plugin.addFavoriteDestination(label, position);
        favoriteEditor.setVisible(false);
        if (popup.isVisible())
            renderResults();
    }

    private void favoriteInputError(String message) {
        favoriteError.setText(message);
        favoriteError.setVisible(true);
        favoriteEditor.revalidate();
    }

    /** Preselects the top result so Enter works immediately; -1 when there are none. */
    private void preselectFirstResult() {
        selectedResult = resultRows.isEmpty() ? -1 : 0;
        applySelectionHighlight();
    }

    /** Highlights the selected row (shared by keyboard and mouse) and resets the rest. */
    private void applySelectionHighlight() {
        for (int i = 0; i < resultRows.size(); i++) {
            boolean selected = i == selectedResult;
            JPanel row = resultRows.get(i);
            row.setBackground(selected ? RESULT_SELECTED_BG : ColorScheme.DARKER_GRAY_COLOR);
            // The accent bar replaces 3px of the left padding, so the row text does not shift.
            row.setBorder(selected
                ? BorderFactory.createCompoundBorder(
                    BorderFactory.createMatteBorder(0, 3, 0, 0, BANNER_INFO_ACCENT),
                    new EmptyBorder(3, 1, 3, 4))
                : new EmptyBorder(3, 4, 3, 4));
        }
    }

    /** Moves the keyboard selection by {@code delta}, wrapping around the result list. */
    private void moveSelection(int delta) {
        if (resultRows.isEmpty())
            return;
        selectedResult = ((selectedResult + delta) % resultRows.size() + resultRows.size()) % resultRows.size();
        applySelectionHighlight();
    }

    /** Commits a destination selection (from a click or Enter): route to it, remember it, close. */
    private void selectEntry(Destinations.Entry entry) {
        Destinations.Entry resolved = withTiles(entry);
        if (resolved.nearest != null)
            plugin.goToNearest(resolved.nearest);
        else if (resolved.tiles.size() > 1)
            // A named amenity (Falador Bank: every booth): the nearest of its tiles, like "nearest X".
            plugin.setNearestCategory(resolved.tiles, resolved.name);
        else
            plugin.setDestination(entry.packedPosition, "search");
        if (entry.nearest == null)
            plugin.recordSearchSelection(entry);
        // Clearing the text re-renders the popup with the recent list; a selection should end the
        // interaction instead.
        searchField.setText("");
        popup.setVisible(false);
    }

    /**
     * History and favourite entries persist one tile; a named amenity's full tile set comes back
     * from the index by category and name.
     */
    private Destinations.Entry withTiles(Destinations.Entry entry) {
        if (entry.tiles.size() > 1 || entry.nearest != null)
            return entry;
        for (Destinations.Entry indexed : index()) {
            if (indexed.tiles.size() > 1 && indexed.category.equals(entry.category) && indexed.name.equals(entry.name))
                return indexed;
        }
        return entry;
    }

    /**
     * Floats the results over the panel, matching the search field's width. Re-showing on every
     * keystroke would flicker and can steal the caret, so a visible popup is resized in place.
     */
    private void showPopup() {
        int width = Math.max(searchField.getWidth(), 180);
        popup.setPreferredSize(new Dimension(width, results.getPreferredSize().height + 2));
        if (popup.isVisible()) {
            popup.revalidate();
            popup.repaint();
            popup.pack();
        }
        else
            popup.show(searchField, 0, searchField.getHeight());
    }

    private JPanel destinationRow(Destinations.Entry entry, int player) {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(3, 4, 3, 4));
        row.setCursor(new Cursor(Cursor.HAND_CURSOR));

        JLabel name = new JLabel(entry.name, RouteIcons.destinationIcon(entry.category), SwingConstants.LEADING);
        name.setIconTextGap(3);
        name.setForeground(Color.WHITE);
        name.setFont(FontManager.getRunescapeSmallFont());
        row.add(name, BorderLayout.CENTER);

        JPanel east = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
        east.setOpaque(false);
        if (entry.nearest == null && entry.tiles.size() > 1) {
            // A named amenity: say which kind, since "Falador Bank" and "Falador" sit side by side.
            JLabel chip = new JLabel(Destinations.categoryLabel(entry.category));
            chip.setForeground(Color.GRAY);
            chip.setFont(FontManager.getRunescapeSmallFont());
            east.add(chip);
        }
        if (player != WorldPointUtil.UNDEFINED && entry.packedPosition != WorldPointUtil.UNDEFINED) {
            int distance = WorldPointUtil.distanceBetween(player, entry.packedPosition);
            if (distance != Integer.MAX_VALUE) {
                JLabel dist = new JLabel(distance + " tiles");
                dist.setForeground(Color.GRAY);
                dist.setFont(FontManager.getRunescapeSmallFont());
                east.add(dist);
            }
        }
        if ("favorite".equals(entry.category)) {
            east.add(new IconActionLabel(RouteIcons.CROSS, RouteIcons.CROSS_HOVER,
                "Remove this favourite", () -> {
                plugin.removeFavoriteDestination(entry);
                renderResults();
            }));
        }
        if (east.getComponentCount() > 0)
            row.add(verticallyCentered(east), BorderLayout.EAST);

        row.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                selectEntry(entry);
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                // Move the shared selection to the hovered row so keyboard and mouse agree.
                selectedResult = resultRows.indexOf(row);
                applySelectionHighlight();
            }
        });
        return row;
    }
}

package gps;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.HashMap;
import java.util.Map;
import java.util.Locale;
import java.util.LinkedHashMap;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import gps.transport.Transport;
import gps.transport.TransportType;

import static gps.WorldPointUtil.packWorldPoint;
import static gps.WorldPointUtil.unpackWorldPlane;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

/**
 * The GPS search index: named places and curated amenities (bank, altar, water source,
 * furnace, ...) a player can navigate to by name or as "nearest X". The bulk is a bundled
 * resource dumped from the cache (destinations.tsv); fairy rings and spirit trees are added
 * from the live transport data because their world objects carry no name in the cache.
 */
@Slf4j
public final class Destinations {
    private static final String RESOURCE_PATH = "/destinations.tsv";
    // Hand-curated additions (agility courses, skilling spots) kept OUT of the machine-dumped
    // resource above, so regenerating the dump never erases them.
    private static final String CURATED_PATH = "/destinations-curated.tsv";
    // Locations imported from the OSRS wiki's infobox map pins (see WikiLocationDumperTest):
    // searchable places that have no in-game world-map label, deduplicated against the above.
    private static final String WIKI_PATH = "/destinations-wiki.tsv";

    /**
     * One searchable destination: a category, a display name, a representative packed world tile,
     * and every target tile it stands for (one for a place; all access tiles for a named amenity
     * such as "Falador Bank", which routes to the nearest of its booths).
     */
    public static final class Entry {
        public final String category;
        public final String name;
        public final int packedPosition;
        public final Set<Integer> tiles;
        /** The "Nearest X" option a query row was synthesized from; null for ordinary entries. */
        public final NearestOption nearest;

        Entry(String category, String name, int packedPosition) {
            this(category, name, packedPosition, null, null);
        }

        Entry(String category, String name, int packedPosition, Set<Integer> tiles, NearestOption nearest) {
            this.category = category;
            this.name = name;
            this.packedPosition = packedPosition;
            this.tiles = tiles != null ? tiles
                : (packedPosition == WorldPointUtil.UNDEFINED ? Set.of() : Set.of(packedPosition));
            this.nearest = nearest;
        }
    }

    /** Categories the name search lists as-is (one tile each). */
    private static final Set<String> NAMED_CATEGORIES = Set.of(
        "place", "landmark", "dungeon", "minigame", "training", "fairy_ring", "spirit_tree");
    /** Amenity categories the name search groups by site name (plan step N11). */
    private static final Set<String> AMENITY_CATEGORIES = Set.of(
        "bank", "altar", "water", "furnace", "anvil", "range", "spinning_wheel", "pottery");

    /** A "nearest X" amenity category offered as a quick option: its id and its display label. */
    public static final class NearestOption {
        public final String id;
        public final String label;

        NearestOption(String id, String label) {
            this.id = id;
            this.label = label;
        }
    }

    /**
     * The amenity categories offered as "nearest X" options, in display order. Picking one routes
     * to ALL tiles of that category at once — the alternative-routes engine then ranks the shortest
     * paths (using available teleports), which may lead to different sites.
     */
    public static final List<NearestOption> NEAREST_OPTIONS = List.of(
        new NearestOption("bank", "Bank"),
        new NearestOption("bank_round_trip", "Bank (and back)"),
        new NearestOption("altar", "Altar"),
        new NearestOption("water", "Water source"),
        new NearestOption("furnace", "Furnace"),
        new NearestOption("anvil", "Anvil"),
        new NearestOption("range", "Cooking range"),
        new NearestOption("spinning_wheel", "Spinning wheel"),
        new NearestOption("pottery", "Potter's wheel"),
        new NearestOption("fairy_ring", "Fairy ring"),
        new NearestOption("spirit_tree", "Spirit tree"));

    /** The named places (cities/towns/landmarks) from the bundled resource. */
    public static List<Entry> places() {
        List<Entry> places = new ArrayList<>();
        for (Entry entry : resourceEntries()) {
            if ("place".equals(entry.category))
                places.add(entry);
        }
        return places;
    }

    /**
     * The entries offered by the name search: named places, landmarks, dungeons, minigames and
     * training spots as they are, fairy rings and spirit trees by their code, and every amenity
     * site ONCE under its name with all of its access tiles ("Falador Bank" is one entry whose
     * route ends at whichever booth is nearest). Before plan step N11 amenities were left out and
     * "Falador bank" found nothing.
     */
    public static List<Entry> searchable(PrimitiveIntHashMap<Transport[]> transports) {
        List<Entry> out = new ArrayList<>();
        Map<String, Entry> amenityFirst = new LinkedHashMap<>();
        Map<String, List<Integer>> amenityTiles = new HashMap<>();
        for (Entry entry : all(transports)) {
            if (NAMED_CATEGORIES.contains(entry.category))
                out.add(entry);
            else if (AMENITY_CATEGORIES.contains(entry.category)) {
                String key = entry.category + "\t" + entry.name;
                amenityFirst.putIfAbsent(key, entry);
                amenityTiles.computeIfAbsent(key, k -> new ArrayList<>()).add(entry.packedPosition);
            }
        }
        for (Map.Entry<String, Entry> grouped : amenityFirst.entrySet()) {
            Entry first = grouped.getValue();
            out.add(new Entry(first.category, first.name, first.packedPosition,
                Set.copyOf(amenityTiles.get(grouped.getKey())), null));
        }
        return out;
    }

    /**
     * The "nearest X" option a query asks for: a leading "nearest" followed by an option's label
     * or id ("nearest altar", "nearest bank and back"), or a bare category word ("bank"). Null for
     * anything else, including named searches ("falador bank").
     */
    public static NearestOption parseNearest(String query) {
        String q = query == null ? "" : query.toLowerCase(Locale.ROOT).trim().replaceAll("\\s+", " ");
        String rest = q.startsWith("nearest ") ? q.substring("nearest ".length()).trim() : q;
        if (rest.isEmpty())
            return null;
        for (NearestOption option : NEAREST_OPTIONS) {
            String label = option.label.toLowerCase(Locale.ROOT);
            if (rest.equals(option.id.replace('_', ' ')) || rest.equals(label)
                || rest.equals(label.replace("(", "").replace(")", ""))) {
                return option;
            }
        }
        return null;
    }

    /** A category as the panel names it ("range" is "Cooking range"); title-cased otherwise. */
    public static String categoryLabel(String category) {
        for (NearestOption option : NEAREST_OPTIONS) {
            if (option.id.equals(category))
                return option.label;
        }
        String words = category.replace('_', ' ');
        return words.isEmpty() ? words : Character.toUpperCase(words.charAt(0)) + words.substring(1);
    }

    /**
     * Every target tile of an amenity category — the target set for its "nearest X" search. The
     * bundled rows ARE the access tiles: the dump emits, per amenity, the perimeter tiles whose
     * shared edge with the object carries no wall (the collision map can't make that distinction
     * at runtime — walls and object-filled neighbours clear the same edge bits — so a blind 3x3
     * perimeter let "nearest water source" routes end one tile across a wall, OUTSIDE the
     * building the trough stands in). Tiles occupied by other objects are harmless: never
     * settled. Fairy rings and spirit trees come from the live transport data; their origins are
     * the standing tiles themselves.
     */
    public static Set<Integer> tilesForCategory(String category, PrimitiveIntHashMap<Transport[]> transports) {
        // The round-trip variant targets the same sites; the routing mode differs, not the tiles.
        String effective = "bank_round_trip".equals(category) ? "bank" : category;
        Set<Integer> tiles = new HashSet<>();
        boolean transportBacked = "fairy_ring".equals(effective) || "spirit_tree".equals(effective);
        for (Entry entry : transportBacked ? all(transports) : resourceEntries()) {
            if (effective.equals(entry.category))
                tiles.add(entry.packedPosition);
        }
        return tiles;
    }

    /**
     * The target set for an arbitrary single tile (a map pin, a Quest Helper NPC tile): the tile
     * itself when it's walkable — exact semantics preserved — otherwise the tile plus the nearest
     * ring of walkable tiles around it (radius up to {@code MAX_WALKABLE_RING}). A pin dropped on a
     * fence, a piece of furniture or an NPC's own tile can never be settled by the search, which
     * otherwise explores the entire map and falls back to a closest-tile path (the same pathology
     * the amenity perimeter fixes). If no walkable tile exists within range (a pin mid-pond), the
     * original tile is returned alone and the search keeps the old closest-tile behaviour.
     */
    public static Set<Integer> walkableTargets(gps.pathfinder.CollisionMap map, int packed) {
        return walkableTargets(map, packed, null);
    }

    /**
     * As above, but when {@code transportOrigin} is given and the blocked tile has a known
     * transport ORIGIN within range, the origin tiles alone become the target set. A Quest
     * Helper target on a cave's footprint would otherwise expand to whichever adjacent tile
     * the route approaches first — including the BACK of the cave (captured at Trollheim's
     * Troll Stronghold entrance: routed behind the mouth, then the game walked the long way
     * around). The mapped transport's origin tile is, by definition, the interactable side.
     */
    public static Set<Integer> walkableTargets(gps.pathfinder.CollisionMap map, int packed,
        java.util.function.IntPredicate transportOrigin) {
        packed = remapTemplateOnlyZones(packed);
        Set<Integer> land = walkableLandTargets(map, packed, transportOrigin);
        // A pin on SAILABLE water is a sea destination (a wreck, a fishing spot, an ocean
        // label): the water tile itself stays in the target set - aboard, the sea legs settle
        // it exactly (seaLegTransports + wet arrival) - alongside the land ring, which serves
        // the same pin on foot. Dropping the water tile disarmed the entire boat route: the
        // search only ever saw the shore (capture 20260827-220818).
        if (SailingSea.isSailable(packed) && !land.contains(packed)) {
            Set<Integer> both = new HashSet<>(land);
            both.add(packed);
            return both;
        }
        return land;
    }

    private static Set<Integer> walkableLandTargets(gps.pathfinder.CollisionMap map, int packed,
        java.util.function.IntPredicate transportOrigin) {
        final int x = unpackWorldX(packed);
        final int y = unpackWorldY(packed);
        final int plane = unpackWorldPlane(packed);
        if (map == null || !map.isBlocked(x, y, plane))
            return Set.of(packed);
        // Pass 1: a transport origin near the blocked tile beats plain proximity, even when it
        // sits a radius further out than the first walkable ring.
        if (transportOrigin != null) {
            for (int radius = 1; radius <= MAX_WALKABLE_RING; radius++) {
                Set<Integer> origins = new HashSet<>();
                for (int dx = -radius; dx <= radius; dx++) {
                    for (int dy = -radius; dy <= radius; dy++) {
                        if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
                            continue;
                        int tile = packWorldPoint(x + dx, y + dy, plane);
                        if (!map.isBlocked(x + dx, y + dy, plane) && transportOrigin.test(tile))
                            origins.add(tile);
                    }
                }
                if (!origins.isEmpty())
                    return origins;
            }
        }
        for (int radius = 1; radius <= MAX_WALKABLE_RING; radius++) {
            Set<Integer> ring = new HashSet<>();
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dy = -radius; dy <= radius; dy++) {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
                        continue;
                    if (!map.isBlocked(x + dx, y + dy, plane))
                        ring.add(packWorldPoint(x + dx, y + dy, plane));
                }
            }
            if (!ring.isEmpty()) {
                ring.add(packed);
                return ring;
            }
        }
        return Set.of(packed);
    }

    private static final int MAX_WALKABLE_RING = 5;

    /** A template-only zone: destinations inside the box snap to the anchor tile. */
    static final class Remap {
        final int minX;
        final int minY;
        final int maxX;
        final int maxY;
        final int plane;
        final int anchor;
        final String label;

        Remap(int minX, int minY, int maxX, int maxY, int plane, int anchor, String label) {
            this.minX = minX;
            this.minY = minY;
            this.maxX = maxX;
            this.maxY = maxY;
            this.plane = plane;
            this.anchor = anchor;
            this.label = label;
        }
    }

    private static List<Remap> remaps;

    /**
     * Some map areas are pure scenery: instance templates visible from outside (Iban's Temple
     * interior), display-only floors. A player can never stand there, so a destination inside
     * one — a clue step, a Quest Helper tile, a curious map pin — would either error as
     * unreachable or route to fake geometry. Those targets snap to the zone's anchor: the
     * nearest known-good tile, usually the entrance. Data: destination-remaps.tsv.
     */
    static int remapTemplateOnlyZones(int packed) {
        final int x = unpackWorldX(packed);
        final int y = unpackWorldY(packed);
        final int plane = unpackWorldPlane(packed);
        for (Remap remap : loadRemaps()) {
            if (plane == remap.plane && x >= remap.minX && x <= remap.maxX
                && y >= remap.minY && y <= remap.maxY) {
                return remap.anchor;
            }
        }
        return packed;
    }

    private static synchronized List<Remap> loadRemaps() {
        if (remaps != null)
            return remaps;
        List<Remap> loaded = new ArrayList<>();
        try (InputStream in = ShortestPathPlugin.class.getResourceAsStream("/destination-remaps.tsv")) {
            if (in != null) {
                try (java.util.Scanner scanner = new java.util.Scanner(in, "UTF-8")) {
                    while (scanner.hasNextLine()) {
                        String line = scanner.nextLine();
                        if (line.startsWith("#") || line.isBlank())
                            continue;
                        String[] f = line.split("\t");
                        if (f.length < 9)
                            continue;
                        loaded.add(new Remap(Integer.parseInt(f[0].trim()), Integer.parseInt(f[1].trim()),
                            Integer.parseInt(f[2].trim()), Integer.parseInt(f[3].trim()),
                            Integer.parseInt(f[4].trim()),
                            packWorldPoint(Integer.parseInt(f[5].trim()),
                                Integer.parseInt(f[6].trim()), Integer.parseInt(f[7].trim())),
                            f[8].trim()));
                    }
                }
            }
        }
        catch (IOException | NumberFormatException e) {
            // A malformed remap file must never break routing — fall through with what parsed.
        }
        remaps = loaded;
        return remaps;
    }

    private static volatile List<Entry> resourceEntries;

    private Destinations() {
    }

    /** The static place + amenity entries from the bundled resource (loaded once). */
    public static List<Entry> resourceEntries() {
        List<Entry> snapshot = resourceEntries;
        if (snapshot == null) {
            synchronized (Destinations.class) {
                snapshot = resourceEntries;
                if (snapshot == null) {
                    snapshot = load();
                    resourceEntries = snapshot;
                }
            }
        }
        return snapshot;
    }

    /**
     * The static entries plus destinations derived from the live transport data: one per fairy ring
     * and spirit tree (deduplicated by origin — these objects have no cache name, so they're named by
     * their transport display info like "Fairy ring AIQ"), and one per minigame (deduplicated by name,
     * placed at the minigame's teleport destination and named from its display info, e.g. "Castle Wars").
     */
    public static List<Entry> all(PrimitiveIntHashMap<Transport[]> transports) {
        List<Entry> entries = new ArrayList<>(resourceEntries());
        if (transports == null)
            return entries;
        PrimitiveIntList seen = new PrimitiveIntList();
        // Seed with the bundled minigame entries (curated rows), so a transport-derived duplicate
        // of the same minigame isn't added twice.
        Set<String> seenMinigames = new HashSet<>();
        for (Entry entry : entries) {
            if ("minigame".equals(entry.category))
                seenMinigames.add(entry.name.toLowerCase(java.util.Locale.ROOT));
        }
        for (int key : transports.keys()) {
            Transport[] set = transports.get(key);
            if (set == null)
                continue;
            for (Transport transport : set) {
                TransportType type = transport.getType();
                if (type == TransportType.FAIRY_RING || type == TransportType.SPIRIT_TREE) {
                    int origin = transport.getOrigin();
                    if (origin == Transport.UNDEFINED_ORIGIN || seen.contains(origin))
                        continue;
                    seen.add(origin);
                    String label = type == TransportType.FAIRY_RING ? "Fairy ring" : "Spirit tree";
                    String info = transport.getDisplayInfo();
                    String name = info != null && !info.isEmpty() ? label + " " + info : label;
                    entries.add(new Entry(type == TransportType.FAIRY_RING ? "fairy_ring" : "spirit_tree",
                        name, origin));
                }
                else if (type == TransportType.TELEPORTATION_MINIGAME) {
                    int destination = transport.getDestination();
                    String name = minigameName(transport.getDisplayInfo());
                    if (destination == WorldPointUtil.UNDEFINED
                        || !seenMinigames.add(name.toLowerCase(java.util.Locale.ROOT))) {
                        continue;
                    }
                    entries.add(new Entry("minigame", name, destination));
                }
            }
        }
        return entries;
    }

    /**
     * A clean minigame label from a minigame-teleport's display info: drops the "Minigame Teleport"
     * boilerplate and the numbered-variant prefix, e.g. "Castle Wars Minigame Teleport" -&gt;
     * "Castle Wars", and "Rat Pits Minigame Teleport: 1. Ardougne" -&gt; "Rat Pits: Ardougne".
     */
    private static String minigameName(String info) {
        if (info == null || info.isEmpty())
            return "Minigame";
        String name = info.replace("Minigame Teleport", " ").replaceAll("\\s+", " ").trim();
        name = name.replace(" :", ":").replaceAll(":\\s*\\d+\\.\\s*", ": ");
        return name.trim();
    }

    /** Minigame-only interior boxes (destination-exclusions.tsv): pins inside them are dropped. */
    private static final String EXCLUSIONS_PATH = "/destination-exclusions.tsv";

    private static final class ExclusionZone {
        final int minX, minY, maxX, maxY, plane;

        ExclusionZone(int minX, int minY, int maxX, int maxY, int plane) {
            this.minX = minX;
            this.minY = minY;
            this.maxX = maxX;
            this.maxY = maxY;
            this.plane = plane;
        }
    }

    private static volatile List<ExclusionZone> exclusionZones;

    /**
     * Whether a destination pin sits inside a minigame-only interior (Trouble Brewing's water
     * sources): such amenities serve the activity, not overworld routing, so the pin is dropped
     * from search, amenity sets and the reachability audits alike (field call 2026-08-27:
     * "there is no point in routing to it").
     */
    static boolean insideExcludedZone(int packed) {
        final int x = unpackWorldX(packed);
        final int y = unpackWorldY(packed);
        final int plane = unpackWorldPlane(packed);
        for (ExclusionZone zone : loadExclusionZones()) {
            if (plane == zone.plane && x >= zone.minX && x <= zone.maxX
                && y >= zone.minY && y <= zone.maxY) {
                return true;
            }
        }
        return false;
    }

    private static synchronized List<ExclusionZone> loadExclusionZones() {
        if (exclusionZones != null)
            return exclusionZones;
        List<ExclusionZone> loaded = new ArrayList<>();
        try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(EXCLUSIONS_PATH)) {
            if (in != null) {
                try (java.util.Scanner scanner = new java.util.Scanner(in, "UTF-8")) {
                    while (scanner.hasNextLine()) {
                        String line = scanner.nextLine();
                        if (line.isEmpty() || line.startsWith("#"))
                            continue;
                        String[] f = line.split("	");
                        if (f.length < 5)
                            continue;
                        loaded.add(new ExclusionZone(Integer.parseInt(f[0].trim()), Integer.parseInt(f[1].trim()),
                            Integer.parseInt(f[2].trim()), Integer.parseInt(f[3].trim()), Integer.parseInt(f[4].trim())));
                    }
                }
            }
        }
        catch (IOException e) {
            log.error("Failed to load destination exclusions", e);
        }
        exclusionZones = loaded;
        return loaded;
    }

    private static List<Entry> load() {
        List<Entry> entries = loadResource(RESOURCE_PATH);
        entries.addAll(loadResource(CURATED_PATH));
        entries.addAll(loadResource(WIKI_PATH));
        entries.removeIf(entry -> insideExcludedZone(entry.packedPosition));
        // Entries inside a template-only/minigame-arena remap zone adopt their anchor at load,
        // so search results and the reachability audits both see the real-world stand-in
        // ("Pest Control" lands on the Void outpost, not inside the lander-only arena).
        for (int i = 0; i < entries.size(); i++) {
            Entry entry = entries.get(i);
            int remapped = remapTemplateOnlyZones(entry.packedPosition);
            if (remapped != entry.packedPosition)
                entries.set(i, new Entry(entry.category, entry.name, remapped));
        }
        return entries;
    }

    private static List<Entry> loadResource(String path) {
        try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(path)) {
            if (in == null) {
                log.warn("Destinations resource not found at {}", path);
                return new ArrayList<>();
            }
            return parse(new String(Util.readAllBytes(in), StandardCharsets.UTF_8));
        }
        catch (IOException e) {
            log.error("Failed to load destinations from {}", path, e);
            return new ArrayList<>();
        }
    }

    private static List<Entry> parse(String tsv) {
        List<Entry> entries = new ArrayList<>();
        boolean header = true;
        for (String line : tsv.split("\\R")) {
            if (header) {
                header = false;
                continue;
            }
            if (line.isEmpty())
                continue;
            // category, name, x, y, plane [, verified_source, verified_date] — the trailing
            // verification columns are metadata for maintenance and are ignored at load time.
            String[] fields = line.split("\t");
            if (fields.length < 5)
                continue;
            try {
                int packed = packWorldPoint(
                    Integer.parseInt(fields[2]), Integer.parseInt(fields[3]), Integer.parseInt(fields[4]));
                entries.add(new Entry(fields[0], fields[1], packed));
            }
            catch (NumberFormatException e) {
                log.warn("Skipping malformed destination row: '{}'", line);
            }
        }
        return entries;
    }

    /**
     * The target set for destinations another plugin sends. Quest Helper often targets an NPC's
     * or object's own tile, which is not walkable: a search targeting only it exhausts the
     * entire map and ends "closest tile" (captured: ~880 ms per search), so each tile expands to
     * its walkable ring like a manual pin. When any expanded tile is a mapped transport ORIGIN
     * (Quest Helper caves, stairs), that origin IS the interactable side: the rest is dropped,
     * or the search ends wherever the approach is cheapest, including BEHIND the object
     * (captured at the Troll Stronghold south cave).
     */
    public static Set<Integer> externalTargets(Set<Integer> targets, gps.pathfinder.CollisionMap map,
        java.util.function.IntPredicate transportOrigin) {
        Set<Integer> ends = new HashSet<>();
        for (int target : targets)
            ends.addAll(walkableTargets(map, target, transportOrigin));
        if (transportOrigin == null)
            return ends;
        Set<Integer> origins = new HashSet<>();
        for (int end : ends) {
            if (transportOrigin.test(end))
                origins.add(end);
        }
        return origins.isEmpty() ? ends : origins;
    }
}

package gps;

import java.util.List;

/**
 * The step-by-step directions of the displayed route, built once per route instance (plan step
 * L28, out of the plugin class): the overlay renders every frame, and the path scan only reruns
 * when the displayed route object changes. One immutable holder, not two fields: the render
 * thread and the client thread both read it, and a two-field cache could publish one route's
 * key beside another's steps.
 */
final class DirectionsCache {
    private static final class Entry {
        final RouteOption route;
        final List<RouteDirections.Step> steps;

        Entry(RouteOption route, List<RouteDirections.Step> steps) {
            this.route = route;
            this.steps = steps;
        }
    }

    private volatile Entry entry = new Entry(null, List.of());

    /** The directions for {@code route}, built through the plugin on the first ask per route. */
    List<RouteDirections.Step> of(ShortestPathPlugin plugin, RouteOption route) {
        Entry cached = entry;
        if (route != cached.route) {
            cached = new Entry(route, RouteDirections.build(plugin, route));
            entry = cached;
        }
        return cached.steps;
    }
}

package gps;

import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TransportAvailability;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * The candidate transports for a rendered path edge (plan step L23, out of the plugin class),
 * re-derived from the current path state for display code. Path display is edge-based, not
 * node-based: the origin comes from the current step, the destination from the next, and the
 * applicable set may depend on whether the edge transitions into the banked state. Banking is
 * not its own path edge: the "becomes banked" change is conflated into the edge that reaches
 * the banked step, so neither step alone resolves the transports; the edge does. This is a
 * fallback for display and stays ambiguous when several valid transports share an origin and
 * destination under the same edge state; the structural fix would be explicit edges on
 * reconstructed paths.
 */
final class EdgeTransports {
    private EdgeTransports() {
    }

    /**
     * The transports that ride the edge from {@code current} to {@code next}: the local ones
     * from the current tile plus the anywhere-teleports landing on the next, filtered while
     * collecting because this runs per edge per frame. A same-plane adjacent edge is a plain
     * walking step, so no teleport is hinted on it; a teleport whose type shares destinations
     * with a local type (the quetzal whistle and the quetzal) is dropped when that local type is
     * on the edge, or when the edge is within the shared type's radius (the path is walking to
     * the landing site, not teleporting there).
     */
    static Set<Transport> forEdge(PathfinderConfig config, PathStep current, PathStep next) {
        if (current == null || next == null)
            return Set.of();
        boolean bankVisited = current.isBankVisited() || next.isBankVisited();
        final int landing = next.getPackedPosition();
        Set<Transport> stepTransports = new HashSet<>();
        for (Transport transport : config.getTransportsPacked(bankVisited)
            .getOrDefault(current.getPackedPosition(), TransportAvailability.EMPTY_TRANSPORTS)) {
            if (transport.getDestination() == landing)
                stepTransports.add(transport);
        }
        for (Transport transport : config.getUsableTeleports(bankVisited)) {
            if (transport.getDestination() == landing)
                stepTransports.add(transport);
        }
        Set<TransportType> localTypes = EnumSet.noneOf(TransportType.class);
        for (Transport t : stepTransports) {
            if (t.getOrigin() != Transport.UNDEFINED_ORIGIN && t.getType() != null)
                localTypes.add(t.getType());
        }
        int edgeDistance = WorldPointUtil.distanceBetween2D(current.getPackedPosition(), next.getPackedPosition());
        boolean samePlane = WorldPointUtil.unpackWorldPlane(current.getPackedPosition())
            == WorldPointUtil.unpackWorldPlane(next.getPackedPosition());
        stepTransports.removeIf(t -> {
            if (t.getOrigin() != Transport.UNDEFINED_ORIGIN || t.getType() == null) {
                return false; // local transports stay
            }
            if (samePlane && edgeDistance <= 1) {
                return true; // a walking step across a teleport's landing tile
            }
            TransportType sharedType = t.getType().sharesDestinationsWith();
            if (sharedType == null)
                return false;
            return localTypes.contains(sharedType)
                || (sharedType.getRadiusThreshold() != null && edgeDistance <= sharedType.getRadiusThreshold());
        });
        return stepTransports;
    }

    /** The step after {@code index}, or null at the end of the path. */
    static PathStep nextStep(List<PathStep> path, int index) {
        if (path == null || index < 0 || index + 1 >= path.size())
            return null;
        return path.get(index + 1);
    }
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import java.util.function.BiFunction;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * The fairy-ring log helper (plan step L17, out of the plugin class): while the log is open and
 * a destination is set, the code the displayed route uses is marked "(GPS)" in green and the
 * list is scrolled to it, every client tick (the log rebuilds its rows).
 */
final class FairyRingHighlighter {
    private final Client client;
    private final Supplier<List<PathStep>> displayPath;
    private final BiFunction<PathStep, PathStep, Set<Transport>> transportsForEdge;

    private boolean logOpen;

    FairyRingHighlighter(Client client, Supplier<List<PathStep>> displayPath,
        BiFunction<PathStep, PathStep, Set<Transport>> transportsForEdge) {
        this.client = client;
        this.displayPath = displayPath;
        this.transportsForEdge = transportsForEdge;
    }

    /** A widget opened: the log counts as open only while a destination is set. */
    void widgetLoaded(int groupId, boolean hasTargets) {
        if (hasTargets && groupId == InterfaceID.FAIRYRINGS_LOG)
            logOpen = true;
    }

    void widgetClosed(int groupId) {
        if (groupId == InterfaceID.FAIRYRINGS_LOG)
            logOpen = false;
    }

    /** After each client tick: re-mark and re-scroll while the log is open. */
    void onPostClientTick(boolean hasTargets) {
        if (logOpen && hasTargets)
            highlight();
    }

    /** The fairy-ring code the route uses (the last one on the path), or null. */
    static String routeCode(List<PathStep> path, BiFunction<PathStep, PathStep, Set<Transport>> transportsForEdge) {
        String code = null;
        for (int i = 1; i < path.size(); i++) {
            for (Transport transport : transportsForEdge.apply(path.get(i - 1), path.get(i))) {
                if (TransportType.FAIRY_RING.equals(transport.getType()))
                    code = transport.getDisplayInfo();
            }
        }
        return code;
    }

    private void highlight() {
        List<PathStep> path = displayPath.get();
        if (path.isEmpty())
            return;
        String fairyRingCode = routeCode(path, transportsForEdge);
        if (fairyRingCode == null)
            return;

        Widget codeWidget = null;
        Widget favesPanel = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        if (favesPanel != null)
            codeWidget = rowWithCode(favesPanel.getStaticChildren(), fairyRingCode);
        Widget contentsList = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        if (contentsList != null && codeWidget == null)
            codeWidget = rowWithCode(contentsList.getDynamicChildren(), fairyRingCode);
        if (codeWidget == null)
            return;

        codeWidget.setTextColor(0x00FF00);
        String codeWidgetText = codeWidget.getText();
        if (codeWidgetText != null && !codeWidgetText.contains("(GPS)"))
            codeWidget.setText("(GPS) " + codeWidgetText);

        if (contentsList == null)
            return;
        int panelScrollY = Math.min(codeWidget.getRelativeY(), contentsList.getScrollHeight() - contentsList.getHeight());
        contentsList.setScrollY(panelScrollY);
        contentsList.revalidateScroll();
        client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.FairyringsLog.SCROLLBAR,
            InterfaceID.FairyringsLog.CONTENTS, panelScrollY);
    }

    private static Widget rowWithCode(Widget[] rows, String code) {
        if (rows == null)
            return null;
        for (Widget widget : rows) {
            if (widget != null) {
                String text = widget.getText();
                if (code.equals(text) || ("(GPS) " + code).equals(text))
                    return widget;
            }
        }
        return null;
    }
}

package gps;

import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;

/**
 * A clickable icon control, modelled on the tile-packs panel action labels: shows a base icon, swaps
 * to a hover icon while the cursor is over it, runs an action on left-click, and carries a tooltip.
 */
class IconActionLabel extends JLabel {
    // The at-rest icon, swappable so a container (e.g. a route row) can reveal the control on its
    // own hover; the direct-hover icon still wins while the cursor is over the control itself.
    private ImageIcon restIcon;
    private boolean hovered;

    IconActionLabel(ImageIcon icon, ImageIcon hoverIcon, String tooltip, Runnable onClick) {
        this.restIcon = icon;
        setIcon(icon);
        setToolTipText(tooltip);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e))
                    onClick.run();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                setIcon(hoverIcon);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                setIcon(restIcon);
            }
        });
    }

    /** Sets the at-rest icon; applied immediately unless the cursor is directly over this control. */
    void setRestIcon(ImageIcon icon) {
        restIcon = icon;
        if (!hovered)
            setIcon(icon);
    }
}

package gps;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/**
 * The "report an issue" context: the routing state (mode, start, target, config, method counts,
 * carried items, detections, the routes found) as plain text the player copies BY HAND into a
 * GitHub issue. Nothing is sent anywhere by the plugin and the player sees exactly what they
 * share. Built on the client thread (item names come from the item definitions).
 */
final class IssueReport {
    private final ShortestPathPlugin plugin;

    IssueReport(ShortestPathPlugin plugin) {
        this.plugin = plugin;
    }

    /** The context block, CLIENT THREAD. */
    String body() {
        RouteSession session = plugin.session();
        ShortestPathConfig config = plugin.getGpsConfig();
        StringBuilder body = new StringBuilder();
        // No "describe the issue" headings here: the GitHub issue template provides those; this
        // block is what the player pastes under them.
        body.append("*Auto-captured context — please keep:*\n");
        body.append("- GPS ").append(BuildInfo.pluginVersion()).append('\n');
        body.append("- Build ").append(BuildInfo.buildCommit()).append('\n');
        body.append("- Mode: ").append(plugin.getRoutesMode()).append(" · limit ").append(session.limit())
            .append(" · band x").append(session.costMultiple()).append('\n');
        body.append("- Start: ").append(pointText(session.lastStart())).append('\n');
        List<String> targets = new ArrayList<>();
        for (int target : session.lastTargets())
            targets.add(pointText(target));
        body.append("- Target(s): ").append(targets.isEmpty() ? "(none)" : String.join("; ", targets)).append('\n');
        // Only settings that genuinely affect routing here: avoidWilderness applies in every mode,
        // bankPickup weights the bank detour. The mode (above) already implies bank routing and the
        // item scope, so those are not repeated (they would show the overridden config value).
        body.append("- Config: avoidWilderness=")
            .append(ConfigOverrides.override("avoidWilderness", config.avoidWilderness()))
            .append(", bankPickup=").append(ConfigOverrides.override("costBankPickup", config.costBankPickup()))
            .append('\n');

        // Method availability at a glance: the full catalog is far too big, so counts per status
        // plus the user's own exclusions (the part that varies by choice, usually short).
        List<TeleportMethod> catalog = plugin.teleportCatalog();
        Map<TeleportMethod, MethodAvailability> unavailable = plugin.unavailableMethods();
        if (!catalog.isEmpty()) {
            Map<MethodAvailability, Integer> counts = new EnumMap<>(MethodAvailability.class);
            for (MethodAvailability status : unavailable.values())
                counts.merge(status, 1, Integer::sum);
            body.append("- Methods: ").append(catalog.size() - unavailable.size()).append(" usable of ")
                .append(catalog.size());
            for (Map.Entry<MethodAvailability, Integer> entry : counts.entrySet()) {
                body.append(" · ").append(entry.getValue()).append(' ')
                    .append(entry.getKey().name().toLowerCase(Locale.ROOT).replace('_', ' '));
            }
            body.append('\n');
        }
        Set<TeleportMethod> userExclusions = plugin.getUserExclusions();
        if (!userExclusions.isEmpty()) {
            List<String> excluded = new ArrayList<>();
            for (TeleportMethod method : userExclusions)
                excluded.add(method.routeLabel());
            Collections.sort(excluded);
            int cap = Math.min(excluded.size(), 10);
            body.append("- Excluded by user: ").append(String.join("; ", excluded.subList(0, cap)));
            if (excluded.size() > cap)
                body.append(" … ").append(excluded.size() - cap).append(" more");
            body.append('\n');
        }
        // What the player carries decides the Owned modes' teleports, so name it (user-reviewed
        // before submitting: they can trim anything they would rather not share).
        Client client = plugin.getClient();
        body.append("- Equipped: ").append(itemNames(client, InventoryID.WORN)).append('\n');
        body.append("- Inventory: ").append(itemNames(client, InventoryID.INV)).append('\n');
        body.append("- Bank contents known: ").append(plugin.isBankContentsKnown())
            .append(plugin.isBankRestored() ? " (restored from previous session)" : "").append('\n');
        body.append("- House scanned: ").append(plugin.isPohScanned());
        String pohEncoded = PohScanner.encode(plugin.pohDetection().detected());
        if (pohEncoded != null)
            body.append(" (").append(pohEncoded).append(')');
        body.append('\n');
        body.append("- Spirit trees synced: ").append(plugin.isSpiritTreeSynced())
            .append(plugin.spiritTreesParsedLive() ? " (live)" : "").append('\n');

        List<RouteOption> routes = session.routes();
        body.append("- Routes (").append(routes.size()).append("):\n");
        int shown = Math.min(routes.size(), 12);
        for (int i = 0; i < shown; i++) {
            RouteOption route = routes.get(i);
            body.append("  ").append(i).append(". ").append(route.getTotalCost())
                .append(route.isReached() ? "" : " (closest)").append(" · ").append(methodSummary(route)).append('\n');
        }
        if (routes.size() > shown)
            body.append("  … ").append(routes.size() - shown).append(" more\n");
        body.append("\nFor a full reproduction, attach the newest file from your `.runelite/gps-debug/` folder"
            + " (use \"Save debug snapshot\" in the ⋯ menu first).\n");
        return body.toString();
    }

    /**
     * The names of the items in a container, stacks as "xN", duplicates collapsed, CLIENT THREAD
     * (item definitions). "(empty)" when nothing is carried, "(unknown)" when not logged in.
     */
    static String itemNames(Client client, int inventoryId) {
        ItemContainer container = client.getItemContainer(inventoryId);
        if (container == null)
            return "(unknown)";
        Map<String, Integer> names = new LinkedHashMap<>();
        for (Item item : container.getItems()) {
            if (item == null || item.getId() <= 0)
                continue;
            String name;
            try {
                ItemComposition definition = client.getItemDefinition(item.getId());
                name = definition != null ? definition.getName() : "item " + item.getId();
            }
            catch (RuntimeException e) {
                name = "item " + item.getId();
            }
            names.merge(name, Math.max(1, item.getQuantity()), Integer::sum);
        }
        if (names.isEmpty())
            return "(empty)";
        List<String> parts = new ArrayList<>(names.size());
        for (Map.Entry<String, Integer> entry : names.entrySet())
            parts.add(entry.getValue() > 1 ? entry.getKey() + " x" + entry.getValue() : entry.getKey());
        return String.join(", ", parts);
    }

    /** A packed point as "x, y, plane", or "(none)" when undefined. */
    static String pointText(int packed) {
        if (packed == WorldPointUtil.UNDEFINED)
            return "(none)";
        return WorldPointUtil.unpackWorldX(packed) + ", " + WorldPointUtil.unpackWorldY(packed)
            + ", " + WorldPointUtil.unpackWorldPlane(packed);
    }

    /** A route's methods joined with " + ", or "walk" when it has none. */
    static String methodSummary(RouteOption route) {
        if (route.getMethods().isEmpty())
            return "walk";
        List<String> parts = new ArrayList<>();
        for (TeleportMethod method : route.getMethods())
            parts.add(method.routeLabel());
        return String.join(" + ", parts);
    }
}

package gps;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import lombok.Getter;

/**
 * An item family: the name the transport TSVs use in their Items column ("AXE", "COINS") and
 * every item id that counts as that item, read from item-variations.tsv. For a rune family,
 * rune-sources.tsv names the staff and offhand (tome) families that stand in for it. Data rather
 * than code, so a new ornament kit is a row, not a release of logic.
 */
public final class ItemVariations {
    private static final Map<String, ItemVariations> FAMILIES = load();
    /** The one family code names directly: the fairy rings' staff, with its bank and withdraw hints. */
    public static final ItemVariations DRAMEN_STAFF = fromName("DRAMEN_STAFF");

    private final String name;
    @Getter
    private int[] ids = new int[0];
    private ItemVariations staves;
    private ItemVariations offhands;

    private ItemVariations(String name) {
        this.name = name;
    }

    /** The family of that name, or null when no family carries it (the parser then tries a raw item id). */
    public static ItemVariations fromName(String name) {
        return FAMILIES.get(name);
    }

    /** The item ids of the staff family that is an unlimited source of this rune family, or null. */
    public static int[] staves(ItemVariations family) {
        return family == null || family.staves == null ? null : family.staves.ids;
    }

    /** The item ids of the offhand family (a tome) that covers this rune family, or null. */
    public static int[] offhands(ItemVariations family) {
        return family == null || family.offhands == null ? null : family.offhands.ids;
    }

    @Override
    public String toString() {
        return name;
    }

    private static Map<String, ItemVariations> load() {
        Map<String, ItemVariations> families = new LinkedHashMap<>();
        for (String[] row : rows("/item-variations.tsv")) {
            ItemVariations family = families.computeIfAbsent(row[0], ItemVariations::new);
            family.ids = Arrays.copyOf(family.ids, family.ids.length + 1);
            family.ids[family.ids.length - 1] = Integer.parseInt(row[1]);
        }
        for (String[] row : rows("/rune-sources.tsv")) {
            ItemVariations rune = families.get(row[0]);
            rune.staves = row.length > 1 && !row[1].isEmpty() ? families.get(row[1]) : null;
            rune.offhands = row.length > 2 && !row[2].isEmpty() ? families.get(row[2]) : null;
        }
        return families;
    }

    /** The data rows of a TSV resource: comment lines and the header skipped, fields tab-split. */
    static List<String[]> rows(String resource) {
        List<String[]> rows = new ArrayList<>();
        try (InputStream in = ItemVariations.class.getResourceAsStream(resource);
            Scanner scanner = new Scanner(in, "UTF-8")) {
            boolean header = true;
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                if (line.isEmpty() || line.startsWith("#"))
                    continue;
                if (header) {
                    header = false;
                    continue;
                }
                rows.add(line.split("\t"));
            }
        }
        catch (java.io.IOException e) {
            throw new IllegalStateException(resource, e);
        }
        return rows;
    }
}

