/**
 * The "Travel methods" catalog (panel series P3, out of the panel class): every teleport and
 * transport method for the current mode, grouped into collapsible categories with per-method
 * priority menus (prefer, avoid, exclude) and per-category include/exclude toggles, a text
 * filter and a funnel filter by unavailability kind. The rows scroll inside their own bounded
 * box so a long catalog never pushes the route list off screen. The route cards and the catalog
 * share one exclusion set: a route's method menu and the catalog row flip the same state.
 */
final class MethodCatalogView {
    /** The funnel-filter options. */
    enum Filter {
        ALL("Show all methods", null, false),
        DISABLED("Disabled (excluded)", null, true),
        MISSING_ITEM("Missing an item", MethodAvailability.MISSING_ITEM, false),
        IN_BANK("Item in the bank", MethodAvailability.IN_BANK, false),
        MISSING_LEVEL("Missing a skill level", MethodAvailability.MISSING_LEVEL, false),
        MISSING_QUEST("Missing a quest", MethodAvailability.MISSING_QUEST, false),
        LOCKED("Not unlocked yet", MethodAvailability.LOCKED, false);

        final String label;
        // The availability kind this filter keeps (null when it does not filter by availability).
        final MethodAvailability availability;
        // True for the "disabled" filter, which keeps user-excluded methods regardless of availability.
        final boolean disabled;

        Filter(String label, MethodAvailability availability, boolean disabled) {
            this.label = label;
            this.availability = availability;
            this.disabled = disabled;
        }

        boolean isActive() {
            return this != ALL;
        }
    }

    private final ShortestPathPlugin plugin;
    // Rebuilds the whole Travel options slot (a tier or funnel change alters none of the inputs
    // the slot's dirty check watches, so the change would otherwise wait for the next render).
    private final Runnable rebuild;
    // Re-lays out the slot after the rows box changed height in place.
    private final Runnable relayout;
    // The filter box: a persistent component so typing keeps focus while only the rows below
    // repopulate. Shown only while the catalog is expanded.
    private final IconTextField search = new IconTextField();
    // The scrollable rows box of the expanded catalog; repopulated in place when the filter changes.
    private JPanel rowsPanel;
    private JScrollPane rowsScroll;
    private final Set<String> expandedCategories = new HashSet<>();
    // Collapsed by default so the routes stay the focus; the user opens it to browse and toggle.
    private boolean expanded;
    private Filter filter = Filter.ALL;
    // The inputs of the next build (see update).
    private List<TeleportMethod> catalog = List.of();
    private Set<TeleportMethod> exclusions = Set.of();
    private Map<TeleportMethod, MethodAvailability> unavailable = Map.of();

    MethodCatalogView(ShortestPathPlugin plugin, Runnable rebuild, Runnable relayout) {
        this.plugin = plugin;
        this.rebuild = rebuild;
        this.relayout = relayout;
        search.setIcon(IconTextField.Icon.SEARCH);
        search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
        search.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                populateRows();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                populateRows();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                populateRows();
            }
        });
    }

    /** The inputs the next {@link #section()} builds from. */
    void update(List<TeleportMethod> catalog, Set<TeleportMethod> exclusions, Map<TeleportMethod, MethodAvailability> unavailable) {
        this.catalog = catalog;
        this.exclusions = exclusions;
        this.unavailable = unavailable;
    }

    List<TeleportMethod> catalog() {
        return catalog;
    }

    Set<TeleportMethod> exclusions() {
        return exclusions;
    }

    Map<TeleportMethod, MethodAvailability> unavailable() {
        return unavailable;
    }

    boolean isExpanded() {
        return expanded;
    }

    /** The methods a search can actually use: usable in the current mode and not excluded. */
    int enabledCount() {
        int enabled = 0;
        for (TeleportMethod method : catalog) {
            if (isUsable(method) && !exclusions.contains(method))
                enabled++;
        }
        return enabled;
    }

    /** The rows box's scroll position, to carry over a rebuild (0 when there is none). */
    int scrollPosition() {
        return rowsScroll != null ? rowsScroll.getVerticalScrollBar().getValue() : 0;
    }

    /**
     * Restores a carried-over scroll position after the rebuilt pane has been laid out (nested
     * invokeLater), since a fresh scrollbar clamps everything to 0 until validation.
     */
    void restoreScroll(int position) {
        if (position > 0 && rowsScroll != null) {
            final JScrollPane scroll = rowsScroll;
            SwingUtilities.invokeLater(() -> SwingUtilities.invokeLater(
                () -> scroll.getVerticalScrollBar().setValue(position)));
        }
    }

    /** The enclosing Travel options section collapsed: the rows box is gone with it. */
    void slotCollapsed() {
        rowsPanel = null;
        rowsScroll = null;
    }

    /** The catalog section a method is grouped under: teleport items split by charge model. */
    static String groupKey(TeleportMethod method) {
        if (method.getType() == TransportType.TELEPORTATION_ITEM)
            return method.isConsumable() ? "Items (charged)" : "Items (permanent)";
        return method.category();
    }

    /**
     * Whether a method with {@code status} is usable in {@code mode}. The availability map is
     * mode-independent (a banked item is always recorded IN_BANK); a banked item counts as usable
     * in the "Inventory + bank" mode, whose route walks to a bank to withdraw it.
     */
    static boolean usable(MethodAvailability status, AlternativeRoutesMode mode) {
        return status == null || (status == MethodAvailability.IN_BANK && mode == AlternativeRoutesMode.OWNED_WITH_BANK);
    }

    /**
     * Whether a method passes the funnel filter (only excluded methods, or one unavailability
     * kind) and the text filter, which matches the category or the label, case-insensitively; an
     * empty text keeps everything.
     */
    static boolean matches(TeleportMethod method, Filter filter, String text,
        Set<TeleportMethod> exclusions, Map<TeleportMethod, MethodAvailability> unavailable) {
        if (filter.disabled && !exclusions.contains(method))
            return false;
        if (filter.availability != null && unavailable.get(method) != filter.availability)
            return false;
        String needle = text.trim().toLowerCase(Locale.ROOT);
        return needle.isEmpty()
            || method.category().toLowerCase(Locale.ROOT).contains(needle)
            || method.label().toLowerCase(Locale.ROOT).contains(needle);
    }

    private boolean isUsable(TeleportMethod method) {
        return usable(unavailable.get(method), plugin.getRoutesMode());
    }

    /** The collapsible "Travel methods" section for the current inputs. */
    JPanel section() {
        // The headline count is the methods a search can ACTUALLY use: usable right now (not
        // missing an item, level, quest or unlock) AND not excluded, so it responds to the
        // toggles. Broken down into permanent (unlimited use) and charged (consumes a charge or
        // the item itself: tabs, charged jewellery).
        int enabled = 0;
        int usable = 0;
        int included = 0;
        int permanent = 0;
        int charged = 0;
        for (TeleportMethod method : catalog) {
            boolean canUse = isUsable(method);
            boolean isIncluded = !exclusions.contains(method);
            if (canUse)
                usable++;
            if (isIncluded)
                included++;
            if (canUse && isIncluded) {
                enabled++;
                if (method.isConsumable())
                    charged++;
                else
                    permanent++;
            }
        }
        // Same collapsible shell as the other Travel options sub-sections; the enabled count is
        // the state text.
        JPanel section = sectionShell("Travel methods",
            enabled + " enabled (usable and included) · " + usable + " usable now · "
                + included + " included in searches · " + catalog.size() + " total",
            expanded, () -> expanded = !expanded,
            enabled + "/" + catalog.size(), ColorScheme.LIGHT_GRAY_COLOR, false, rebuild);

        if (!expanded) {
            slotCollapsed();
            section.setBorder(new EmptyBorder(0, 0, 4, 0));
            return section;
        }

        // Enabled breakdown, permanent (unlimited) against charged (consumes a charge or the
        // item). Only shown while expanded, where the split matters; the header count already
        // carries the total collapsed.
        if (enabled > 0) {
            JLabel breakdown = new JLabel(permanent + " permanent · " + charged + " charged");
            breakdown.setFont(FontManager.getRunescapeSmallFont());
            breakdown.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            breakdown.setToolTipText("Of the enabled methods: " + permanent + " permanent (unlimited use) · "
                + charged + " charged (teleport tabs, charged jewellery: consumed or lose a charge)");
            breakdown.setAlignmentX(Component.LEFT_ALIGNMENT);
            breakdown.setBorder(new EmptyBorder(0, 0, 4, 0));
            section.add(breakdown);
        }

        // The filter box (persistent, see the field comment), only mounted while expanded, with a
        // funnel that opens a menu to narrow by disabled or unavailability kind.
        search.setAlignmentX(Component.LEFT_ALIGNMENT);
        search.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        JPanel filterWrap = new JPanel(new BorderLayout());
        filterWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
        filterWrap.setBorder(new EmptyBorder(0, 4, 0, 2));
        filterWrap.add(control(funnel()), BorderLayout.CENTER);
        JPanel searchWrap = new JPanel(new BorderLayout());
        searchWrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
        searchWrap.setBorder(new EmptyBorder(0, 0, 4, 0));
        searchWrap.setAlignmentX(Component.LEFT_ALIGNMENT);
        searchWrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
        searchWrap.add(search, BorderLayout.CENTER);
        searchWrap.add(filterWrap, BorderLayout.EAST);
        section.add(searchWrap);

        // The method rows scroll inside their own bounded box with their own scrollbar, so a long
        // (or fully expanded) catalog never pushes the route list off screen. The rows panel tracks
        // the viewport width so the scrollbar sits beside the rows instead of clipping them.
        ScrollableBox rows = new ScrollableBox(null);
        rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
        rows.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JScrollPane scroll = new JScrollPane(rows,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        rowsPanel = rows;
        rowsScroll = scroll;
        populateRows();
        section.add(scroll);
        section.setBorder(new EmptyBorder(0, 0, 8, 0));
        return section;
    }

    /**
     * The tier context menu for {@code method}. Preferences re-rank the current list instantly
     * (no recalculation); Exclude keeps its existing semantics (applies on the next refresh).
     */
    void showPriorityMenu(Component anchor, TeleportMethod method) {
        JPopupMenu menu = new JPopupMenu();
        MethodPriority current = plugin.getMethodPriority(method);
        for (MethodPriority tier : new MethodPriority[]{
            MethodPriority.PREFER_3, MethodPriority.PREFER_2, MethodPriority.PREFER_1,
            MethodPriority.NORMAL,
            MethodPriority.AVOID_1, MethodPriority.AVOID_2, MethodPriority.AVOID_3}) {
            String text = tier.label + (tier.chipText().isEmpty() ? "" : "  " + tier.chipText());
            JMenuItem entry = new JMenuItem(text, priorityRestIcon(tier));
            entry.setFont(tier == current ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
            // The slot only rebuilds when catalog, exclusions or availability change; a tier
            // change alters none of them, so rebuild here or the row keeps the old tier until
            // something else re-renders the panel.
            entry.addActionListener(e -> {
                plugin.setMethodPriority(method, tier);
                rebuild.run();
            });
            menu.add(entry);
        }
        menu.addSeparator();
        JMenuItem exclude = new JMenuItem(MethodPriority.EXCLUDED.label, RouteIcons.CROSS);
        exclude.setFont(current == MethodPriority.EXCLUDED
            ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
        exclude.addActionListener(e -> {
            plugin.setMethodPriority(method, MethodPriority.EXCLUDED);
            rebuild.run();
        });
        menu.add(exclude);
        menu.show(anchor, 0, anchor.getHeight());
    }

    /** The funnel icon that opens the filter menu; orange while a filter is active. */
    private JLabel funnel() {
        boolean active = filter.isActive();
        JLabel funnel = new JLabel(active ? RouteIcons.FILTER_ACTIVE : RouteIcons.FILTER);
        funnel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        funnel.setToolTipText("Filter: " + filter.label + " (click to change)");
        funnel.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                showFilterMenu(funnel);
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                funnel.setIcon(active ? RouteIcons.FILTER_ACTIVE_HOVER : RouteIcons.FILTER_HOVER);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                funnel.setIcon(active ? RouteIcons.FILTER_ACTIVE : RouteIcons.FILTER);
            }
        });
        return funnel;
    }

    private void showFilterMenu(JComponent anchor) {
        JPopupMenu menu = new JPopupMenu();
        menu.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        menu.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        ButtonGroup group = new ButtonGroup();
        for (Filter option : Filter.values()) {
            JRadioButtonMenuItem item = new JRadioButtonMenuItem(option.label, option == filter);
            item.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            item.setForeground(Color.WHITE);
            item.setFont(FontManager.getRunescapeSmallFont());
            item.addActionListener(e -> {
                filter = option;
                rebuild.run();
            });
            group.add(item);
            menu.add(item);
        }
        menu.show(anchor, 0, anchor.getHeight());
    }

    /**
     * (Re)fills the expanded rows box from the current filters. Called on every filter keystroke;
     * repopulates in place so the search field keeps focus. While a filter is active, matching
     * categories are shown force-expanded (a filter that only matched collapsed categories would
     * otherwise look like it found nothing).
     */
    private void populateRows() {
        JPanel rows = rowsPanel;
        JScrollPane scroll = rowsScroll;
        if (rows == null || scroll == null)
            return;
        rows.removeAll();

        String text = search.getText() == null ? "" : search.getText().trim();
        boolean filtering = !text.isEmpty();

        Map<String, List<TeleportMethod>> grouped = new TreeMap<>();
        for (TeleportMethod method : catalog) {
            if (matches(method, filter, text, exclusions, unavailable))
                grouped.computeIfAbsent(groupKey(method), k -> new ArrayList<>()).add(method);
        }
        for (List<TeleportMethod> items : grouped.values())
            items.sort(Comparator.comparing(m -> m.label().toLowerCase(Locale.ROOT)));

        if (grouped.isEmpty()) {
            String message = filter.isActive() ? "No methods: " + filter.label.toLowerCase(Locale.ROOT)
                : "No methods match \"" + escapeHtml(text) + "\"";
            JLabel none = wrappedLabel("<i>" + message + "</i>");
            none.setBorder(new EmptyBorder(2, 4, 2, 0));
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            rows.add(none);
        }
        for (Map.Entry<String, List<TeleportMethod>> entry : grouped.entrySet()) {
            String category = entry.getKey();
            List<TeleportMethod> items = entry.getValue();
            // A text filter or an active funnel filter force categories open so the matches show.
            boolean open = filtering || filter.isActive() || expandedCategories.contains(category);
            rows.add(categoryHeader(category, items, open));
            if (open) {
                for (TeleportMethod item : items)
                    rows.add(itemRow(item));
            }
        }

        // Bounded height: natural size for short lists, capped so the routes below stay visible.
        int height = Math.min(rows.getPreferredSize().height + 2, CATALOG_MAX_HEIGHT);
        scroll.setPreferredSize(new Dimension(10, height));
        scroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
        rows.revalidate();
        rows.repaint();
        relayout.run();
    }

    private JPanel categoryHeader(String category, List<TeleportMethod> items, boolean open) {
        int excludedCount = 0;
        for (TeleportMethod method : items) {
            if (exclusions.contains(method))
                excludedCount++;
        }
        boolean allIncluded = excludedCount == 0;
        boolean allExcluded = excludedCount == items.size();

        JPanel row = new JPanel(new BorderLayout(3, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
            new EmptyBorder(3, 4, 3, 4)));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        ImageIcon icon;
        ImageIcon hover;
        String tip;
        Runnable action;
        if (allIncluded) {
            icon = RouteIcons.CHECK;
            hover = RouteIcons.CHECK_HOVER;
            tip = "All included: click to exclude every " + category.toLowerCase(Locale.ROOT);
            action = () -> plugin.excludeMethods(items);
        }
        else if (allExcluded) {
            icon = RouteIcons.CROSS;
            hover = RouteIcons.CROSS_HOVER;
            tip = "All excluded: click to include every " + category.toLowerCase(Locale.ROOT);
            action = () -> plugin.includeMethods(items);
        }
        else {
            icon = RouteIcons.DASH;
            hover = RouteIcons.DASH_HOVER;
            tip = (items.size() - excludedCount) + " of " + items.size() + " included: click to include all";
            action = () -> plugin.includeMethods(items);
        }
        // Chevron on the left (matching the section headers above), the include/exclude toggle at
        // the row's right edge: with the toggle up front it sat exactly where users click to
        // expand, so category toggles kept getting flipped by accident.
        row.add(control(new JLabel(open ? RouteIcons.CHEVRON_DOWN : RouteIcons.CHEVRON_RIGHT)), BorderLayout.WEST);

        String count = allIncluded
            ? " (" + items.size() + ")"
            : " (" + (items.size() - excludedCount) + "/" + items.size() + ")";
        JLabel name = new JLabel(category + count);
        name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        row.add(name, BorderLayout.CENTER);

        row.add(control(new IconActionLabel(icon, hover, tip, action)), BorderLayout.EAST);

        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        row.setToolTipText(open ? "Collapse" : "Expand to toggle individual methods");
        addClickRecursively(row, new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                toggleCategory(category);
            }
        });
        return row;
    }

    private JPanel itemRow(TeleportMethod item) {
        boolean excluded = exclusions.contains(item);

        JPanel row = new JPanel(new BorderLayout(3, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(2, 18, 2, 4));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        // Priority control (replaces the old include/exclude toggle): the icon shows the current
        // tier (check = normal, stacked arrows = prefer/avoid, cross = excluded) and clicking
        // opens the tier menu (exclude is its bottom entry).
        MethodPriority tier = plugin.getMethodPriority(item);
        final IconActionLabel[] toggleHolder = new IconActionLabel[1];
        toggleHolder[0] = new IconActionLabel(priorityRestIcon(tier), priorityHoverIcon(tier),
            priorityTooltip(item.label(), tier),
            () -> showPriorityMenu(toggleHolder[0], item));
        IconActionLabel toggle = toggleHolder[0];
        // The status marker (lock/bank) stays by the name; the toggle sits at the row's right edge,
        // aligned with the category toggles, away from where users click to expand.
        MethodAvailability status = unavailable.get(item);
        if (status != null) {
            JLabel statusMarker = statusMarker(plugin, status, item);
            statusMarker.setBorder(new EmptyBorder(0, 0, 0, 3));
            row.add(verticallyCentered(statusMarker), BorderLayout.WEST);
        }

        JLabel text = wrappedLabel(escapeHtml(item.label()));
        text.setToolTipText(methodTooltip(item));
        if (excluded)
            text.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
        // Centre the label at its preferred height instead of letting BorderLayout stretch it: a
        // stretched html JLabel top-anchors its text (the html view claims the full height), which
        // left the text floating high beside the vertically-centred icons.
        row.add(verticallyCentered(text), BorderLayout.CENTER);

        row.add(verticallyCentered(control(toggle)), BorderLayout.EAST);

        return row;
    }

    private void toggleCategory(String category) {
        if (!expandedCategories.add(category))
            expandedCategories.remove(category);
        // Repopulate the rows in place: cheaper than a full rebuild, and the slot's dirty check
        // (which does not track per-category expansion) would skip the rebuild anyway.
        populateRows();
    }
}

package gps;

import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The methods the user has excluded from the search (plan step L26, out of the plugin class).
 * Exclusions apply on the next generation, never at once: a change persists and refreshes the
 * panel (catalog icons and counts), and the route list reads as stale until the user refreshes.
 * The live set is shared by reference with the ranking preferences (the EXCLUDED mask) and the
 * generation.
 */
final class MethodExclusions {
    private final Set<TeleportMethod> live = ConcurrentHashMap.newKeySet();
    // The exclusions the current route list was generated with; diverging from the live set
    // means the list is stale until the user refreshes.
    private volatile Set<TeleportMethod> generatedWith = Set.of();
    private final ChoiceStore store;
    private final Runnable onChanged;

    MethodExclusions(ChoiceStore store, Runnable onChanged) {
        this.store = store;
        this.onChanged = onChanged;
    }

    /** The live set itself (concurrent), for the readers that must see every change. */
    Set<TeleportMethod> live() {
        return live;
    }

    /** A snapshot copy, for callers that iterate off the client thread. */
    Set<TeleportMethod> copy() {
        return new HashSet<>(live);
    }

    boolean contains(TeleportMethod method) {
        return live.contains(method);
    }

    boolean isEmpty() {
        return live.isEmpty();
    }

    void load() {
        live.addAll(store.loadExclusions());
    }

    void exclude(TeleportMethod method) {
        if (method != null && live.add(method))
            changed();
    }

    void include(TeleportMethod method) {
        if (method != null && live.remove(method))
            changed();
    }

    void excludeAll(Collection<TeleportMethod> methods) {
        boolean changed = false;
        if (methods != null) {
            for (TeleportMethod method : methods)
                changed |= live.add(method);
        }
        if (changed)
            changed();
    }

    void includeAll(Collection<TeleportMethod> methods) {
        boolean changed = false;
        if (methods != null) {
            for (TeleportMethod method : methods)
                changed |= live.remove(method);
        }
        if (changed)
            changed();
    }

    void clear() {
        if (!live.isEmpty()) {
            live.clear();
            changed();
        }
    }

    /** A generation started with the current set: the list is fresh until the set changes. */
    void markGenerated() {
        generatedWith = copy();
    }

    /** Whether the set changed since the current route list was generated. */
    boolean isStale() {
        return !live.equals(generatedWith);
    }

    private void changed() {
        store.saveExclusions(live);
        onChanged.run();
    }
}

package gps;

import gps.pathfinder.CostUnits;

/**
 * A user-set ranking bias for a travel method — RimWorld-style tiers. Priorities shift a route's
 * EFFECTIVE ETA (the sort key and the card's adjustment chip) by a fixed number of seconds per
 * prioritised method used; they never change the search itself, so adjusting them re-sorts the
 * existing list instantly with no recalculation. EXCLUDED is the terminal tier and delegates to
 * the existing exclusion machinery (which does affect the search).
 */
public enum MethodPriority {
    PREFER_3(-20, "Strongly prefer"),
    PREFER_2(-10, "Prefer"),
    PREFER_1(-5, "Slightly prefer"),
    NORMAL(0, "Normal"),
    AVOID_1(5, "Slightly avoid"),
    AVOID_2(10, "Avoid"),
    AVOID_3(20, "Strongly avoid"),
    EXCLUDED(0, "Exclude");

    /** Seconds added to the route's effective ETA (negative = preferred, ranks earlier). */
    public final int adjustSeconds;
    public final String label;

    MethodPriority(int adjustSeconds, String label) {
        this.adjustSeconds = adjustSeconds;
        this.label = label;
    }

    /** The adjustment in search cost units (1 tick = 0.6s), rounded to the nearest unit. */
    public int adjustUnits() {
        return unitsFromSeconds(adjustSeconds);
    }

    /** Seconds -> cost units: seconds / 0.6s-per-tick * units-per-tick, away-from-zero rounding. */
    public static int unitsFromSeconds(int seconds) {
        return (int) Math.round(seconds / 0.6 * CostUnits.UNITS_PER_TICK);
    }

    /** The +Ns / -Ns chip text ("" for no adjustment). */
    public String chipText() {
        if (adjustSeconds == 0)
            return "";
        return (adjustSeconds > 0 ? "+" : "−") + Math.abs(adjustSeconds) + "s";
    }
}

package gps;

import java.awt.Color;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;

/**
 * The minimap's clip shape (plan step L13, out of the plugin class): the outline of the fixed or
 * resizable mask sprite, positioned where the minimap widget sits, cached until the widget moves
 * or changes size; an ellipse over the widget bounds when the sprite is not loaded yet. The
 * minimap overlay clips to it and the map menu tests the mouse against it.
 */
final class MinimapClip {
    private final Client client;
    private final SpriteManager spriteManager;

    private Shape clipFixed;
    private Shape clipResizeable;
    private BufferedImage spriteFixed;
    private BufferedImage spriteResizeable;
    private Rectangle rectangle = new Rectangle();

    MinimapClip(Client client, SpriteManager spriteManager) {
        this.client = client;
        this.spriteManager = spriteManager;
    }

    /** The clip shape, or null while the minimap is hidden. */
    Shape area() {
        Widget minimapWidget = drawWidget();

        if (minimapWidget == null || minimapWidget.isHidden() || !rectangle.equals(rectangle = minimapWidget.getBounds())) {
            clipFixed = null;
            clipResizeable = null;
            spriteFixed = null;
            spriteResizeable = null;
        }

        if (minimapWidget == null || minimapWidget.isHidden())
            return null;

        if (client.isResized()) {
            if (clipResizeable != null)
                return clipResizeable;
            if (spriteResizeable == null)
                spriteResizeable = spriteManager.getSprite(SpriteID.RESIZE_MAP_MASK, 0);
            if (spriteResizeable != null) {
                clipResizeable = polygonOf(spriteResizeable, rectangle.x, rectangle.y);
                return clipResizeable;
            }
            return simpleArea();
        }
        if (clipFixed != null)
            return clipFixed;
        if (spriteFixed == null)
            spriteFixed = spriteManager.getSprite(SpriteID.FIXED_MAP_MASK, 0);
        if (spriteFixed != null) {
            clipFixed = polygonOf(spriteFixed, rectangle.x, rectangle.y);
            return clipFixed;
        }
        return simpleArea();
    }

    private Widget drawWidget() {
        if (client.isResized()) {
            if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1)
                return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
            return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
        }
        return client.getWidget(InterfaceID.Toplevel.MINIMAP);
    }

    private Shape simpleArea() {
        Widget minimapDrawArea = drawWidget();

        if (minimapDrawArea == null || minimapDrawArea.isHidden())
            return null;

        Rectangle bounds = minimapDrawArea.getBounds();

        return new Ellipse2D.Double(bounds.getX(), bounds.getY(), bounds.getWidth(), bounds.getHeight());
    }

    /**
     * The outline of a mask sprite's non-background region: the corner pixel is the background;
     * each row contributes its left edge (appended) and right edge (prepended), so the points run
     * down one side and back up the other. Offset to the widget's screen position.
     */
    static Polygon polygonOf(BufferedImage image, int offsetX, int offsetY) {
        Color outsideColour = null;
        Color previousColour;
        final int width = image.getWidth();
        final int height = image.getHeight();
        List<java.awt.Point> points = new ArrayList<>();
        for (int y = 0; y < height; y++) {
            previousColour = outsideColour;
            for (int x = 0; x < width; x++) {
                int rgb = image.getRGB(x, y);
                int a = (rgb & 0xff000000) >>> 24;
                int r = (rgb & 0x00ff0000) >> 16;
                int g = (rgb & 0x0000ff00) >> 8;
                int b = (rgb & 0x000000ff);
                Color colour = new Color(r, g, b, a);
                if (x == 0 && y == 0) {
                    outsideColour = colour;
                    previousColour = colour;
                }
                if (!colour.equals(outsideColour) && previousColour.equals(outsideColour))
                    points.add(new java.awt.Point(x, y));
                if ((colour.equals(outsideColour) || x == (width - 1)) && !previousColour.equals(outsideColour))
                    points.add(0, new java.awt.Point(x, y));
                previousColour = colour;
            }
        }
        Polygon polygon = new Polygon();
        for (java.awt.Point point : points)
            polygon.addPoint(point.x + offsetX, point.y + offsetY);
        return polygon;
    }
}

package gps;

import java.awt.event.KeyEvent;
import java.util.function.Supplier;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;

/**
 * The keyboard twins of the panel's "Bank" and "Bank (and back)" quick buttons (a player
 * suggestion). Each runs the same action as its button, so the destination a trip replaces is
 * resumed at the bank too. Unset by default (see ShortestPathConfig); the bindings are read at
 * key time, so a changed binding applies at once.
 */
final class NearestBankHotkeys {
    private final KeyListener bank;
    private final KeyListener bankAndBack;

    NearestBankHotkeys(Supplier<Keybind> bankKey, Runnable onBank,
        Supplier<Keybind> bankAndBackKey, Runnable onBankAndBack) {
        bank = hotkey(bankKey, onBank);
        bankAndBack = hotkey(bankAndBackKey, onBankAndBack);
    }

    /** Routes to the nearest bank. */
    KeyListener bank() {
        return bank;
    }

    /** Routes to the nearest bank and back. */
    KeyListener bankAndBack() {
        return bankAndBack;
    }

    private static KeyListener hotkey(Supplier<Keybind> key, Runnable action) {
        return new KeyListener() {
            @Override
            public void keyTyped(KeyEvent e) {
            }

            @Override
            public void keyPressed(KeyEvent e) {
                Keybind bound = key.get();
                if (bound != null && bound.matches(e))
                    action.run();
            }

            @Override
            public void keyReleased(KeyEvent e) {
            }
        };
    }
}

package gps;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import static gps.PanelWidgets.BANNER_INFO_ACCENT;
import static gps.PanelWidgets.BANNER_OK_ACCENT;
import static gps.PanelWidgets.BANNER_TEXT_WIDTH;
import static gps.PanelWidgets.BANNER_WARN_ACCENT;
import static gps.PanelWidgets.banner;
import static gps.PanelWidgets.verticalGap;
import static gps.PanelWidgets.verticallyCentered;

/**
 * The notices strip below the header (panel series P5, out of the panel class). Banners are for
 * NOTICES only: the status banner (unreachable, nothing found, arrived, no destination; routine
 * result state lives in the routes header instead) and the warnings (Quest Helper not routing
 * through GPS, Shortest Path also enabled, stale exclusions, low balloon logs, the sync hints),
 * grouped behind a compact "N warnings" row that hides and shows them. With no notices at all,
 * the common "routes found" case, the strip collapses entirely.
 */
final class NoticesView extends JPanel {
    /** The status banner's flavour, which picks its icon and accent. */
    enum Kind {
        WARNING, OK, INFO
    }

    /** What the status banner says. */
    static final class Status {
        final String text;
        final Kind kind;

        Status(String text, Kind kind) {
            this.text = text;
            this.kind = kind;
        }
    }

    private final ShortestPathPlugin plugin;
    // A full re-render after the warnings toggle (it is a config change the whole panel reflects).
    private final Runnable rerender;
    // The Log-storage-low banner is built by the balloon section, which knows the item icons.
    private final Function<List<String>, JPanel> balloonLowBanner;
    // Set by the plugin the instant it clears the target on arrival, so the status shows an arrival
    // banner rather than "No destination set". Cleared when a new destination is set.
    private boolean showingArrival;
    private boolean arrivalImmediate;

    NoticesView(ShortestPathPlugin plugin, Runnable rerender, Function<List<String>, JPanel> balloonLowBanner) {
        this.plugin = plugin;
        this.rerender = rerender;
        this.balloonLowBanner = balloonLowBanner;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(4, 0, 6, 0));
    }

    /**
     * The plugin reached (or cleared an already-at) destination: the next show says so instead
     * of "No destination set". {@code elapsedMillis} is about 0 when the destination was set
     * while already there. Marshalled onto the EDT.
     */
    void markArrived(long elapsedMillis) {
        SwingUtilities.invokeLater(() -> {
            showingArrival = true;
            arrivalImmediate = elapsedMillis < 3000;
        });
    }

    /**
     * The status banner, or null when nothing needs saying: unreachable (every route stops short,
     * with WHY: a route exists with items or unlocks you lack, or no known route at all), nothing
     * found for the target (with a broader-mode hint unless already in All), arrived (or already
     * there), or no destination set. Nothing while calculating, nothing when a route reaches.
     */
    static Status status(boolean calculating, boolean anyRoute, boolean allStopShort, boolean missingUnlocks,
        boolean hasTarget, boolean arrived, boolean arrivedImmediately, boolean allMode) {
        if (calculating)
            return null;
        if (anyRoute) {
            if (!allStopShort)
                return null;
            // Plan step N12: the generator tells "reachable with everything, not with what you
            // have" from "no known route" (a sealed tile, or a gap in the map data).
            return new Status(missingUnlocks
                ? "<b>Not reachable with what you have.</b><br>A route exists with items or unlocks you lack: "
                    + "switch to All to see it. Showing the closest reachable point."
                : "<b>No known route to this destination.</b><br>The spot may be sealed off, or the map may be "
                    + "missing a connection. Showing the closest reachable point.", Kind.WARNING);
        }
        if (hasTarget) {
            // A search ran for the current target but produced nothing: distinct from "no target set".
            return new Status("<b>No routes found to the target.</b>"
                + (allMode ? "" : "<br>Try a broader mode (+ Bank, or All)."), Kind.WARNING);
        }
        if (arrived)
            return new Status(arrivedImmediately ? "You're already at your destination." : "Arrived at your destination.", Kind.OK);
        // GPS has no active target. (Quest Helper draws its own line for some steps and does not
        // hand GPS a destination: set one on the map to find routes.)
        return new Status("<b>No destination set.</b><br>Search a place or amenity above, pick a Nearest button, "
            + "right-click a spot on the world map, or shift right-click a tile in the game.", Kind.INFO);
    }

    /** Rebuilds the strip for the current routes and the plugin's state. EDT. */
    void show(List<RouteOption> routes, boolean calculating, boolean hasTarget) {
        // A live destination (or its routes) supersedes any lingering arrival banner.
        if (hasTarget)
            showingArrival = false;
        removeAll();
        Status status = status(calculating, !routes.isEmpty(),
            routes.stream().noneMatch(plugin::routeReachesTarget),
            plugin.getUnreachableCause() == AlternativeRoutesService.UnreachableCause.MISSING_UNLOCKS,
            hasTarget, showingArrival, arrivalImmediate,
            plugin.getRoutesMode() == AlternativeRoutesMode.ALL_EVERYTHING);
        if (status != null)
            add(banner(icon(status.kind), status.text, accent(status.kind)));

        // The sync hints (house, spirit trees, balloon logs) live here at the top: inside their
        // (collapsed) sections they were easy to miss.
        List<JPanel> warnings = new ArrayList<>();
        // Quest Helper only hands its quest-step destinations to GPS when its own "Use Shortest
        // Path plugin" option is on; with it off, quest steps silently never arrive. Dismissable
        // (the x persists via config) for users who prefer it that way.
        if (plugin.isQuestHelperPathingOff() && !plugin.getGpsConfig().questHelperBannerDismissed()) {
            warnings.add(withDismiss(banner(RouteIcons.BANNER_WARNING,
                "Quest Helper isn't routing through GPS",
                "Turn on <b>Use Shortest Path plugin</b> in Quest Helper's settings so quest"
                    + " steps hand their destinations to GPS.",
                BANNER_WARN_ACCENT), "questHelperBannerDismissed"));
        }
        // Running the original Shortest Path plugin alongside GPS doubles the path rendering and
        // the plugin-message integrations (both answer Quest Helper's destinations).
        if (plugin.isShortestPathConflict()) {
            warnings.add(banner(RouteIcons.BANNER_WARNING,
                "Shortest Path is also enabled",
                "Both plugins draw paths and respond to the same integrations. GPS includes its "
                    + "functionality: disable Shortest Path to avoid doubled rendering.",
                BANNER_WARN_ACCENT));
        }
        // Method toggles no longer recalculate; flag a route list generated with different exclusions.
        if (!calculating && hasTarget && plugin.isRouteListStale()) {
            warnings.add(banner(RouteIcons.BANNER_WARNING,
                "Exclusions changed: press \"Refresh routes\" to apply.", BANNER_WARN_ACCENT));
        }
        // Log storage running low at the balloon stations (smart mode, synced, unlocked routes only).
        List<String> lowLogs = plugin.getBalloonLowLogTypes();
        if (!lowLogs.isEmpty())
            warnings.add(balloonLowBanner.apply(lowLogs));
        ShortestPathConfig cfg = plugin.getGpsConfig();
        if (cfg.usePoh() && cfg.pohSmartDetect() && !plugin.isPohScanned()) {
            warnings.add(banner(RouteIcons.BANNER_WARNING,
                "House furniture not detected",
                "Enter your house once to auto-detect its teleport furniture.",
                BANNER_WARN_ACCENT));
        }
        if (cfg.useSpiritTrees() && cfg.spiritTreeSmartMode() && !plugin.isSpiritTreeSynced()) {
            warnings.add(banner(RouteIcons.BANNER_WARNING,
                "Planted spirit trees not synced",
                "Open a spirit tree's travel menu once to detect which trees you have planted.",
                BANNER_WARN_ACCENT));
        }
        if (cfg.useHotAirBalloons() && cfg.balloonSmartMode() && !cfg.balloonStorageSynced()) {
            warnings.add(banner(RouteIcons.BANNER_WARNING,
                "Balloon log storage not synced",
                "Check the Log storage at a balloon station once so flights can be paid from it.",
                BANNER_WARN_ACCENT));
        }
        if (!warnings.isEmpty()) {
            boolean hidden = cfg.hideWarningBanners();
            if (getComponentCount() > 0)
                add(verticalGap(4));
            add(warningToggleRow(warnings.size(), hidden));
            if (!hidden) {
                for (JPanel warning : warnings) {
                    add(verticalGap(4));
                    add(warning);
                }
            }
        }
        setVisible(getComponentCount() > 0);
        revalidate();
        repaint();
    }

    private static Icon icon(Kind kind) {
        switch (kind) {
            case OK:
                return RouteIcons.CHECK;
            case INFO:
                return RouteIcons.BANNER_INFO;
            case WARNING:
            default:
                return RouteIcons.BANNER_WARNING;
        }
    }

    private static Color accent(Kind kind) {
        switch (kind) {
            case OK:
                return BANNER_OK_ACCENT;
            case INFO:
                return BANNER_INFO_ACCENT;
            case WARNING:
            default:
                return BANNER_WARN_ACCENT;
        }
    }

    /**
     * The compact row heading the warning group: a warning glyph, the count, and a chevron.
     * Clicking it hides the banners below (leaving just this row as the reminder that warnings
     * exist) or shows them again; the choice persists in config.
     */
    private JPanel warningToggleRow(int count, boolean hidden) {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(3, 8, 3, 8));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel label = new JLabel(count + (count == 1 ? " warning" : " warnings") + (hidden ? " hidden" : ""),
            RouteIcons.BANNER_WARNING, JLabel.LEFT);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(FontManager.getRunescapeSmallFont());
        row.add(label, BorderLayout.WEST);
        row.add(new JLabel(hidden ? RouteIcons.CHEVRON_RIGHT : RouteIcons.CHEVRON_DOWN), BorderLayout.EAST);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        row.setToolTipText(hidden ? "Show the warnings" : "Hide the warnings (the count stays visible)");
        row.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                plugin.setPanelConfig("hideWarningBanners", !hidden);
                rerender.run();
            }
        });
        return row;
    }

    /**
     * Adds a small persistent-dismiss x to a banner's right edge: clicking writes the given
     * boolean config key and the next render drops the banner for good.
     */
    private JPanel withDismiss(JPanel banner, String dismissedConfigKey) {
        JLabel close = new JLabel("✕");
        close.setFont(FontManager.getRunescapeSmallFont());
        close.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        close.setToolTipText("Dismiss permanently");
        close.setBorder(new EmptyBorder(0, 4, 0, 2));
        close.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        close.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                plugin.setPanelConfig(dismissedConfigKey, true);
            }
        });
        // The x eats ~18px of the CENTER label's fixed HTML width: renarrow the text or its last
        // word clips under the button (screenshot report: 'plugin' became 'plu').
        for (Component comp : banner.getComponents()) {
            if (comp instanceof JLabel && ((JLabel) comp).getText() != null
                && ((JLabel) comp).getText().startsWith("<html>")) {
                JLabel text = (JLabel) comp;
                text.setText(text.getText().replace(
                    "width:" + BANNER_TEXT_WIDTH + "px",
                    "width:" + (BANNER_TEXT_WIDTH - 18) + "px"));
            }
        }
        banner.add(verticallyCentered(close), BorderLayout.EAST);
        // The narrower text may wrap one line further: recompute the height cap.
        banner.setMaximumSize(new Dimension(Integer.MAX_VALUE, banner.getPreferredSize().height));
        return banner;
    }
}

package gps;

import gps.pathfinder.PathStep;
import java.util.List;
import java.util.function.IntSupplier;

import static gps.WorldPointUtil.distanceBetween;

/**
 * Off-route handling (plan step L10, out of the plugin class), in three bands of distance from
 * the path: on route (nothing), a warning band (the overlay shows a red "drifting off route"
 * message), and, on a MOVE that reaches the recalculate distance, a full recompute (or, if the
 * player prefers, cancelling the route). Recalculation fires only on movement so a stationary
 * far position (just teleported off-path) does not loop. With auto-recalculate off, GPS keeps
 * the original route and only ever warns. At the helm the bands stretch: a boat's wide turning
 * arcs swing off the decimated track farther than a walker drifts off a path. A boat cutscene or
 * a teleport landing carries the player far from the path in one leap; that is not drifting, so
 * a jump bigger than running arms a grace window that refreshes while the transport keeps moving
 * them and clears once they are back within the warning band. Client-thread owned; the warning
 * and the distance are read by the overlays.
 */
final class OffRouteTracker {
    enum Verdict {
        ON_ROUTE,
        WARNING,
        RECALCULATE,
        CANCEL
    }

    // A single-tick displacement larger than running (2 tiles) means a transport is carrying the
    // player, not that they walked off route.
    static final int TRANSPORT_STEP_TILES = 3;
    // Ticks to keep suppressing after such a displacement (long enough to cover a boat cutscene).
    static final int TRANSPORT_GRACE_TICKS = 20;

    private int lastLocation = WorldPointUtil.packWorldPoint(0, 0, 0);
    private int graceTicks;
    private volatile int distance = -1;
    private volatile boolean warning;

    /** The distance from the path at the last tick, or -1 when unknown (no same-plane tile). */
    int distance() {
        return distance;
    }

    /** Whether the overlays should show the drifting-off-route warning. */
    boolean isWarning() {
        return warning;
    }

    /** Records where the player stands so the next tick is not read as a move from elsewhere. */
    void reset(int location) {
        lastLocation = location;
    }

    /**
     * One game tick. {@code distanceFromPath} is consulted only when recalculation is enabled
     * ({@code recalculateDistance >= 0}); it is the plugin's path scan. {@code warnDistance} is
     * clamped into {@code [0, recalculateDistance]}. {@code aboard} stretches the bands (recalc x2,
     * warn x3: field-tuned, 3x let the boat wander before a recalc rescued it, arcs fit inside 2x).
     */
    Verdict tick(int location, IntSupplier distanceFromPath, int recalculateDistance, int warnDistance,
        boolean autoRecalculate, boolean cancelInstead, boolean aboard) {
        if (recalculateDistance < 0) {
            warning = false;
            return Verdict.ON_ROUTE;
        }
        int step = distanceBetween(lastLocation, location);
        boolean moved = lastLocation != location;
        lastLocation = location;
        int d = distanceFromPath.getAsInt();
        distance = d;
        int recalc = recalculateDistance;
        int warn = Math.max(0, Math.min(warnDistance, recalc));
        if (aboard) {
            recalc *= 2;
            warn *= 3;
        }
        if (step > TRANSPORT_STEP_TILES)
            graceTicks = TRANSPORT_GRACE_TICKS;
        else if (graceTicks > 0)
            graceTicks = (d >= 0 && d < warn) ? 0 : graceTicks - 1;
        if (d < 0 || graceTicks > 0) {
            warning = false;
            return Verdict.ON_ROUTE;
        }
        if (moved && d >= recalc && autoRecalculate) {
            warning = false;
            return cancelInstead ? Verdict.CANCEL : Verdict.RECALCULATE;
        }
        warning = d >= warn;
        return warning ? Verdict.WARNING : Verdict.ON_ROUTE;
    }

    /**
     * Chebyshev distance from {@code location} to the nearest tile of the displayed path, or -1
     * without a path. Measured against the DISPLAYED route (the line the player follows), not a
     * classic pathfinder path: when a search picked an alternative route those diverge, and
     * measuring off the invisible one made off-route and recalculation misfire. A sailing leg
     * contributes only its two endpoints to the path, so mid-sail the player would be hundreds
     * of tiles off route by node distance: the legs' SEA TRACKS count too (cached waypoints);
     * while a track is still computing the sailor is on route rather than measured against
     * incomplete geometry.
     */
    static int distanceFromPath(int location, List<PathStep> path, RouteOption displayed) {
        if (path == null || path.isEmpty())
            return -1;
        int best = Integer.MAX_VALUE;
        for (PathStep pathStep : path)
            best = Math.min(best, distanceBetween(location, pathStep.getPackedPosition()));
        if (displayed != null && !displayed.sailingJumpDepartures().isEmpty() && SailingSea.isSailable(location)) {
            for (int departure : displayed.sailingJumpDepartures()) {
                if (departure < 0 || departure + 1 >= path.size())
                    continue;
                int[] track = SailingSea.seaPath(path.get(departure).getPackedPosition(),
                    path.get(departure + 1).getPackedPosition());
                if (track == null)
                    return 0;
                for (int waypoint : track)
                    best = Math.min(best, distanceBetween(location, waypoint));
            }
        }
        return best;
    }
}

package gps;

/**
 * Text-size presets for the directions overlay. The RuneScape fonts are pixel-art TTFs designed for
 * size 16, which stay sharpest at their native size or an exact pixel-doubling — so Small shifts the
 * three-tier hierarchy down onto the native small face (16), Normal keeps the native faces (16), and
 * Extra large pixel-doubles everything to 32. Large sits between at 24 (1.5x): a genuine middle step,
 * a touch softer than the exact-multiple sizes since the pixel grid no longer lands on whole screen
 * pixels, but the most-requested in-between.
 */
public enum OverlayFontSize {
    SMALL("Small"),
    NORMAL("Normal"),
    LARGE("Large"),
    EXTRA_LARGE("Extra large");

    private final String label;

    OverlayFontSize(String label) {
        this.label = label;
    }

    @Override
    public String toString() {
        return label;
    }
}

package gps;

import java.awt.Color;

/**
 * The display settings the overlays read every frame (plan step L24, out of the plugin
 * class): one immutable snapshot, taken from the config (with any plugin-message override
 * applied) at startup and again on every config change, so a render never sees a half-updated
 * set and never touches the config proxy.
 */
final class OverlaySettings {
    final boolean drawMap;
    final boolean drawMinimap;
    final boolean drawTiles;
    final boolean drawRecalculationRanges;
    final boolean showTransportInfo;
    final boolean showBankPickupInfo;
    final Color colourPath;
    final Color colourPathSailing;
    final Color colourPathBlocked;
    final Color colourPathCalculating;
    final Color colourPathUnreachable;
    final Color colourText;
    final Color colourTeleportPulse;
    final Color colourOverlayAccent;
    final Color colourRouteItem;
    final boolean showTeleportPulse;
    final boolean showPathPulse;
    final boolean showPathArrows;
    final boolean highlightRouteItem;
    final boolean showDirections;
    final boolean overrideOverlayTransparency;
    final int overlayTransparency;
    // Display-only preference; not part of the capture-replay override set.
    final OverlayFontSize overlayFontSize;
    final boolean arrivalAutoDismiss;
    final int arrivalDismissSeconds;
    final int unreachableTargetDistance;
    final String unreachableText;

    private OverlaySettings(ShortestPathConfig config) {
        drawMap = ConfigOverrides.override("drawMap", config.drawMap());
        drawMinimap = ConfigOverrides.override("drawMinimap", config.drawMinimap());
        drawTiles = ConfigOverrides.override("drawTiles", config.drawTiles());
        drawRecalculationRanges = ConfigOverrides.override("drawRecalculationRanges", config.drawRecalculationRanges());
        showTransportInfo = ConfigOverrides.override("showTransportInfo", config.showTransportInfo());
        showBankPickupInfo = ConfigOverrides.override("showBankPickupInfo", config.showBankPickupInfo());

        colourPath = ConfigOverrides.override("colourPath", config.colourPath());
        colourPathSailing = ConfigOverrides.override("colourPathSailing", config.colourPathSailing());
        colourPathBlocked = ConfigOverrides.override("colourPathBlocked", config.colourPathBlocked());
        colourPathCalculating = ConfigOverrides.override("colourPathCalculating", config.colourPathCalculating());
        colourPathUnreachable = ConfigOverrides.override("colourPathUnreachable", config.colourPathUnreachable());
        colourText = ConfigOverrides.override("colourText", config.colourText());
        colourTeleportPulse = ConfigOverrides.override("colourTeleportPulse", config.colourTeleportPulse());
        colourOverlayAccent = ConfigOverrides.override("colourOverlayAccent", config.colourOverlayAccent());
        colourRouteItem = ConfigOverrides.override("colourRouteItem", config.colourRouteItem());

        unreachableTargetDistance = ConfigOverrides.override("unreachableTargetDistanceThreshold", config.unreachableTargetDistance());
        unreachableText = config.unreachableText();

        showTeleportPulse = ConfigOverrides.override("showTeleportPulse", config.showTeleportPulse());
        showPathPulse = ConfigOverrides.override("showPathPulse", config.showPathPulse());
        showPathArrows = ConfigOverrides.override("showPathArrows", config.showPathArrows());
        highlightRouteItem = ConfigOverrides.override("highlightRouteItem", config.highlightRouteItem());
        showDirections = ConfigOverrides.override("showDirections", config.showDirections());
        overrideOverlayTransparency = ConfigOverrides.override("overrideOverlayTransparency", config.overrideOverlayTransparency());
        overlayTransparency = ConfigOverrides.override("overlayTransparency", config.overlayTransparency());
        overlayFontSize = config.overlayFontSize();
        arrivalAutoDismiss = ConfigOverrides.override("arrivalAutoDismiss", config.arrivalAutoDismiss());
        arrivalDismissSeconds = ConfigOverrides.override("arrivalDismissSeconds", config.arrivalDismissSeconds());
    }

    /** A snapshot of the config as it stands, overrides applied. */
    static OverlaySettings from(ShortestPathConfig config) {
        return new OverlaySettings(config);
    }
}

