 * uses, and the small stateless builders (a centred cell, a control label, a subtle button, a
 * wrapped label, the category dots). Built on the tile-packs style: small icon controls with
 * hover states and tooltips.
 */
final class PanelWidgets {
    static final int CONTROL_SIZE = 18;
    static final int METHOD_TEXT_WIDTH = 132;
    // Wrap width for message-banner text: the sidebar content (~192px after the panel's outer
    // padding and scrollbar) minus the banner's accent bar, paddings, icon and gap (~40px), with
    // slack for font-metric variance; wrapping a line early is invisible, clipping is not.
    static final int BANNER_TEXT_WIDTH = 138;
    static final Color BANNER_INFO_ACCENT = new Color(0x4C, 0x8B, 0xF5);   // GPS blue
    static final Color BANNER_WARN_ACCENT = new Color(0xFF, 0x98, 0x1F);   // amber
    static final Color BANNER_OK_ACCENT = new Color(0x4C, 0xAF, 0x50);     // green
    // Tallest the expanded teleport-methods box may grow before it scrolls internally.
    static final int CATALOG_MAX_HEIGHT = 240;

    // Neutral dot colour for walking legs; deliberately outside the category palette so walking
    // does not masquerade as a teleport category.
    static final Color WALK_DOT_COLOUR = new Color(0x9E, 0x9E, 0x9E);
    static final Color SAIL_DOT_COLOUR = new Color(0x2E, 0x86, 0xC1);
    // Teleport-item dots are coloured by charge model, permanent (reusable) against charged
    // (consumes a charge or the item), so the two read apart in a route card.
    static final Color PERMANENT_ITEM_DOT = new Color(0x4D, 0xB6, 0xAC); // teal
    static final Color CHARGED_ITEM_DOT = new Color(0xF2, 0xC1, 0x4E);   // amber

    // Stable, distinct-ish palette; categories without a fixed colour hash into it so the same
    // category always gets the same dot colour.
    private static final Color[] CATEGORY_PALETTE = {
        new Color(0x5B, 0x9B, 0xD5), // blue
        new Color(0x4C, 0xAF, 0x50), // green
        new Color(0xE9, 0x7D, 0x3B), // orange
        new Color(0xB4, 0x6F, 0xD4), // purple
        new Color(0x4D, 0xB6, 0xAC), // teal
        new Color(0xE5, 0x73, 0x99), // pink
        new Color(0xC0, 0xA8, 0x3B), // gold
        new Color(0x7E, 0x8C, 0x9A), // slate
        new Color(0x8B, 0xC3, 0x4A), // lime
        new Color(0xD1, 0x5B, 0x5B), // red
    };

    private PanelWidgets() {
    }

    /**
     * Wraps a component so that, in a BorderLayout WEST/EAST cell (stretched to the row's full
     * height), it sits vertically centred against the possibly two-line label in CENTER, while
     * staying left-aligned horizontally.
     */
    static JPanel verticallyCentered(Component content) {
        JPanel wrap = new JPanel(new GridBagLayout());
        wrap.setOpaque(false);
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.anchor = GridBagConstraints.WEST;
        wrap.add(content, gbc);
        return wrap;
    }

    /** Sizes an icon label as a small square control. */
    static JLabel control(JLabel label) {
        label.setPreferredSize(new Dimension(CONTROL_SIZE, CONTROL_SIZE));
        label.setHorizontalAlignment(SwingConstants.CENTER);
        return label;
    }

    /** Shared subtle-button chrome: small font, outline, tight padding, hand cursor, hover lift. */
    static JButton subtleButton(JButton button) {
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setForeground(Color.WHITE);
        button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
        button.setFocusPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            new EmptyBorder(3, 8, 3, 8)));
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
            }
        });
        return button;
    }

    /** The first JTextField inside a composite component (IconTextField hides its own). */
    static JTextField innerTextField(Container root) {
        for (Component component : root.getComponents()) {
            if (component instanceof JTextField)
                return (JTextField) component;
            if (component instanceof Container) {
                JTextField inner = innerTextField((Container) component);
                if (inner != null)
                    return inner;
            }
        }
        return null;
    }

    /** A small white section title with the sections' vertical rhythm. */
    static JLabel sectionLabel(String text) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(Color.WHITE);
        label.setBorder(new EmptyBorder(6, 0, 4, 0));
        return label;
    }

    /** Left-aligns a component and lets it stretch to the full width at its preferred height. */
    static JComponent fullWidth(JComponent component) {
        component.setAlignmentX(Component.LEFT_ALIGNMENT);
        component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
        return component;
    }

    /** A small grey label wrapped at the method text width, top-aligned for two-line rows. */
    static JLabel wrappedLabel(String innerHtml) {
        JLabel label = new JLabel("<html><body style='width:" + METHOD_TEXT_WIDTH + "px'>" + innerHtml + "</body></html>");
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setVerticalAlignment(SwingConstants.TOP);
        return label;
    }

    /**
     * A full-width, left-aligned note row for a route card. Bare JLabels must not be added straight
     * into the vertical BoxLayout: they do not stretch and default to centred alignment, which floats
     * them into odd positions and clips them at the card edge.
     */
    static JPanel noteRow(String innerHtml, String tooltip) {
        JPanel row = new JPanel(new BorderLayout());
        row.setOpaque(false);
        JLabel text = wrappedLabel(innerHtml);
        if (tooltip != null)
            text.setToolTipText(tooltip);
        row.add(text, BorderLayout.WEST);
        return row;
    }

    static String escapeHtml(String text) {
        if (text == null)
            return "";
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    /** A fixed-height spacer in the panel's background colour. */
    static Component verticalGap(int height) {
        JPanel gap = new JPanel();
        gap.setBackground(ColorScheme.DARK_GRAY_COLOR);
        gap.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
        gap.setPreferredSize(new Dimension(1, height));
        return gap;
    }

    /** A 9px rounded dot icon in {@code colour}. */
    static Icon dot(Color colour) {
        final int s = 9;
        BufferedImage image = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(colour);
        g.fillRoundRect(0, 1, s - 1, s - 2, 4, 4);
        g.dispose();
        return new ImageIcon(image);
    }

    static Icon categoryDot(String category) {
        return dot(categoryColour(category));
    }

    /** The category dot for a route-card method, splitting teleport items by charge model. */
    static Icon methodDot(TeleportMethod method) {
        if (method.getType() == TransportType.TELEPORTATION_ITEM)
            return dot(method.isConsumable() ? CHARGED_ITEM_DOT : PERMANENT_ITEM_DOT);
        return categoryDot(method.category());
    }

    /**
     * Fixed, deliberately-distinct colour per known category (the old hash assignment gave
     * "Boats & ships" the exact same teal as the permanent-item dot). Items are teal to match the
     * permanent-item dot; charged items get the amber dot via {@link #methodDot}. The hashed
     * palette remains only as a fallback for categories added later.
     */
    static Color categoryColour(String category) {
        switch (category) {
            case "Spells": return new Color(0x5B, 0x9B, 0xD5);          // blue
            case "Items": return PERMANENT_ITEM_DOT;                     // teal (charged = amber)
            case "Jewellery box": return new Color(0xB4, 0x6F, 0xD4);   // purple
            case "Levers": return new Color(0xD1, 0x5B, 0x5B);          // red
            case "Minigame teleports": return new Color(0xE5, 0x73, 0x99); // pink
            case "Portals": return new Color(0x9C, 0x7B, 0xE8);         // violet
            case "Fairy rings": return new Color(0x4C, 0xAF, 0x50);     // green
            case "Spirit trees": return new Color(0x8B, 0xC3, 0x4A);    // lime
            case "Gnome gliders": return new Color(0xC9, 0x69, 0xC9);   // magenta
            case "Hot air balloons": return new Color(0xE9, 0x7D, 0x3B); // orange
            case "Magic carpets": return new Color(0xB0, 0x3A, 0x5B);   // wine
            case "Mushtrees": return new Color(0xE0, 0x60, 0x60);       // light red
            case "Minecarts": return new Color(0x60, 0x7D, 0x8B);       // slate
            case "Mountain guides": return new Color(0x8D, 0x6E, 0x63); // mountain brown
            case "Quetzals": return new Color(0x4A, 0xC6, 0xE0);        // cyan
            case "Obelisks": return new Color(0x9A, 0xA5, 0xB1);        // steel
            case "Boats & ships": return new Color(0x5C, 0x6B, 0xC0);   // indigo, NOT the item teal
            case "Canoes": return new Color(0xB5, 0x79, 0x3B);          // wood brown
            case "Seasonal": return new Color(0x94, 0xB4, 0x4A);        // olive
            default: return CATEGORY_PALETTE[Math.floorMod(category.hashCode(), CATEGORY_PALETTE.length)];
        }
    }

    /**
     * A message banner: a coloured left accent bar, an icon, and wrapped text; used for status
     * and warnings instead of loose labels.
     */
    static JPanel banner(Icon icon, String innerHtml, Color accent) {
        JPanel banner = new JPanel(new BorderLayout(7, 0));
        banner.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        banner.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
            new EmptyBorder(5, 7, 5, 6)));
        banner.setAlignmentX(Component.LEFT_ALIGNMENT);

        // The icon sits vertically centred against the (possibly multi-line) text.
        banner.add(verticallyCentered(new JLabel(icon)), BorderLayout.WEST);

        JLabel text = new JLabel("<html><body style='width:" + BANNER_TEXT_WIDTH + "px'>" + innerHtml + "</body></html>");
        text.setFont(FontManager.getRunescapeSmallFont());
        text.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        banner.add(text, BorderLayout.CENTER);

        banner.setMaximumSize(new Dimension(Integer.MAX_VALUE, banner.getPreferredSize().height));
        return banner;
    }

    /**
     * A titled banner: a bold white title on the first line, the description beneath it. For
     * warnings and notices that read better as heading plus body than one run.
     */
    static JPanel banner(Icon icon, String title, String body, Color accent) {
        String html = "<font color='#FFFFFF'><b>" + escapeHtml(title) + "</b></font>";
        if (body != null && !body.isEmpty())
            html += "<br>" + body;
        return banner(icon, html, accent);
    }

    /**
     * Collapsible shell shared by the configuration sections: a clickable header row (chevron,
     * title, coloured state text) that runs {@code toggle} to flip the caller's expanded flag,
     * then {@code afterToggle} to rebuild. The caller adds the body when expanded.
     * {@code headline} styles the title like the panel's top-level section headers (bold, brand
     * orange), used by the "Travel options" section that groups the others.
     */
    static JPanel sectionShell(String title, String tooltip, boolean expanded, Runnable toggle,
        String stateText, Color stateColor, boolean headline, Runnable afterToggle) {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(ColorScheme.DARK_GRAY_COLOR);
        section.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel titleRow = new JPanel(new BorderLayout(5, 0));
        titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleRow.setBorder(new EmptyBorder(0, 0, 4, 0));
        titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        titleRow.add(control(new JLabel(expanded ? RouteIcons.CHEVRON_DOWN : RouteIcons.CHEVRON_RIGHT)),
            BorderLayout.WEST);
        JLabel titleLabel = new JLabel(title);
        if (headline) {
            titleLabel.setFont(FontManager.getRunescapeBoldFont());
            titleLabel.setForeground(ColorScheme.BRAND_ORANGE);
        }
        else
            titleLabel.setForeground(Color.WHITE);
        titleRow.add(titleLabel, BorderLayout.CENTER);
        JLabel state = new JLabel(stateText);
        state.setForeground(stateColor);
        titleRow.add(state, BorderLayout.EAST);
        titleRow.setToolTipText(tooltip);
        titleRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        titleRow.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                toggle.run();
                afterToggle.run();
            }
        });
        section.add(titleRow);
        return section;
    }

    /** The rest icon of a priority tier: stacked arrows for prefer/avoid, a cross when excluded. */
    static ImageIcon priorityRestIcon(MethodPriority tier) {
        switch (tier) {
            case PREFER_1:
                return RouteIcons.PRIORITY_UP_ICONS[0];
            case PREFER_2:
                return RouteIcons.PRIORITY_UP_ICONS[1];
            case PREFER_3:
                return RouteIcons.PRIORITY_UP_ICONS[2];
            case AVOID_1:
                return RouteIcons.PRIORITY_DOWN_ICONS[0];
            case AVOID_2:
                return RouteIcons.PRIORITY_DOWN_ICONS[1];
            case AVOID_3:
                return RouteIcons.PRIORITY_DOWN_ICONS[2];
            case EXCLUDED:
                return RouteIcons.CROSS;
            default:
                return RouteIcons.PRIORITY_NEUTRAL;
        }
    }

    static ImageIcon priorityHoverIcon(MethodPriority tier) {
        switch (tier) {
            case PREFER_1:
                return RouteIcons.PRIORITY_UP_HOVER_ICONS[0];
            case PREFER_2:
                return RouteIcons.PRIORITY_UP_HOVER_ICONS[1];
            case PREFER_3:
                return RouteIcons.PRIORITY_UP_HOVER_ICONS[2];
            case AVOID_1:
                return RouteIcons.PRIORITY_DOWN_HOVER_ICONS[0];
            case AVOID_2:
                return RouteIcons.PRIORITY_DOWN_HOVER_ICONS[1];
            case AVOID_3:
                return RouteIcons.PRIORITY_DOWN_HOVER_ICONS[2];
            case EXCLUDED:
                return RouteIcons.CROSS_HOVER;
            default:
                return RouteIcons.PRIORITY_NEUTRAL_HOVER;
        }
    }

    static String priorityTooltip(String label, MethodPriority tier) {
        String state = tier == MethodPriority.NORMAL
            ? "Normal priority"
            : tier.label + (tier.chipText().isEmpty() ? "" : " (" + tier.chipText() + " on ranking)");
        return "<html><b>" + escapeHtml(label) + "</b>: " + state
            + "<br>Click for priority options: prefer/avoid shift the ranking, exclude removes it.</html>";
    }

    /** The hover text of a method: its category, label and arrival tile. */
    static String methodTooltip(TeleportMethod method) {
        return "<html>" + methodTooltipBody(method) + "</html>";
    }

    /** The tooltip's inner HTML, for callers that prepend their own line (the route cards). */
    static String methodTooltipBody(TeleportMethod method) {
        int destination = method.getDestination();
        int x = WorldPointUtil.unpackWorldX(destination);
        int y = WorldPointUtil.unpackWorldY(destination);
        int plane = WorldPointUtil.unpackWorldPlane(destination);
        return "<b>" + escapeHtml(method.category()) + "</b><br>"
            + escapeHtml(method.label()) + "<br>"
            + "Arrives at " + x + ", " + y + (plane > 0 ? " (plane " + plane + ")" : "");
    }

    /** Human list of method labels: "Fairy ring", or "Fairy ring and Cowbell amulet". */
    static String joinLabels(Set<TeleportMethod> methods) {
        StringBuilder joined = new StringBuilder();
        int i = 0;
        for (TeleportMethod method : methods) {
            if (i > 0)
                joined.append(i == methods.size() - 1 ? " and " : ", ");
            joined.append(method.label());
            i++;
        }
        return joined.toString();
    }

    /**
     * Attaches a click listener to a component and its descendants, skipping {@link IconActionLabel}s
     * so the icon controls keep their own action. Swing only delivers a click to the deepest component
     * under the cursor, hence the recursion.
     */
    static void addClickRecursively(Component component, MouseListener listener) {
        if (component instanceof IconActionLabel)
            return;
        component.addMouseListener(listener);
        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents())
                addClickRecursively(child, listener);
        }
    }

    /**
     * Marker for a method the player cannot use in the current mode: a bank glyph for an item
     * that is only in the bank, a padlock for everything else, each with a reason tooltip. The
     * classification's own detail ("Requires 60 Mining", "Missing item: Willow logs") names
     * exactly what is missing when it recorded one; the per-status wording is the fallback.
     */
    static JLabel statusMarker(ShortestPathPlugin plugin, MethodAvailability status, TeleportMethod method) {
        JLabel label = new JLabel(status == MethodAvailability.IN_BANK ? RouteIcons.IN_BANK : RouteIcons.LOCKED);
        String detail = plugin.methodUnavailabilityDetail(method);
        if (detail == null)
            label.setToolTipText(statusReason(status));
        else {
            label.setToolTipText(status == MethodAvailability.IN_BANK
                ? detail + ": switch to + Bank or withdraw it"
                : detail);
        }
        return label;
    }

    /** The generic reason wording per unavailability kind. */
    static String statusReason(MethodAvailability status) {
        switch (status) {
            case IN_BANK:
                return "In your bank: switch to + Bank or withdraw it";
            case MISSING_ITEM:
                return "You don't have the required item";
            case MISSING_LEVEL:
                return "Your skill level is too low";
            case MISSING_QUEST:
                return "Requires an unfinished quest";
            case LOCKED:
            default:
                return "Not unlocked yet (diary, minigame, purchase or setting)";
        }
    }
}

package gps;

import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;

import static gps.WorldPointUtil.distanceBetween;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

public class PathMapOverlay extends Overlay {
    private final Client client;
    private final ShortestPathPlugin plugin;

    @Inject
    private PathMapOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_LOW);
        setLayer(OverlayLayer.MANUAL);
        drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.display().drawMap)
            return null;

        if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
            return null;

        Rectangle worldMapRectangle = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
        Area worldMapClipArea = getWorldMapClipArea(worldMapRectangle);
        graphics.setClip(worldMapClipArea);



        if (plugin.hasPathTargets()) {
            Color colour = plugin.getPathColor();
            java.util.List<PathStep> path = plugin.getDisplayPath();
            Point cursorPos = client.getMouseCanvasPosition();
            graphics.setColor(colour);
            drawArrowPath(graphics, path, plugin.getDisplaySailingEdges());
            for (int target : plugin.getPathTargets()) {
                if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition()) {
                    graphics.setColor(plugin.display().colourPathCalculating);
                    drawOnMap(graphics, target, true, cursorPos);
                }
            }
        }

        return null;
    }

    /**
     * Draws the path as a directed polyline: consecutive same-direction walking steps are compressed
     * into one straight segment, each segment ends in a small arrowhead showing travel direction, and
     * teleport/transport jumps are dashed. (Arrowhead technique adapted from Quest Helper's
     * DirectionArrow, see {@link ArrowHead}.)
     */
    private void drawArrowPath(Graphics2D graphics, java.util.List<PathStep> path,
        java.util.Set<Integer> sailingEdges) {
        final java.awt.Stroke walkStroke = new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
        final java.awt.Stroke jumpStroke = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0);

        int i = 0;
        while (i < path.size() - 1) {
            int from = path.get(i).getPackedPosition();
            int next = path.get(i + 1).getPackedPosition();

            if (distanceBetween(from, next) > 1) {
                // Sailing leg: draw the actual sea track (bounded Dijkstra over the shipped
                // ocean, cached per leg) as a solid line; anything else — and any sailing leg
                // whose track cannot be computed — stays the dashed jump hint.
                // sailingEdges holds DEPARTURE indexes (RouteOption.sailingJumpDepartures
                // owns the arrival->departure arithmetic, pinned by its unit test).
                int[] track = sailingEdges.contains(i) ? SailingSea.seaPath(from, next) : null;
                if (track != null) {
                    // Sea legs draw in their own (configurable) colour: amber reads over both
                    // the ocean and the cyan walking path, then the path colour is restored
                    // for the legs that follow.
                    java.awt.Color pathColour = graphics.getColor();
                    graphics.setColor(plugin.getSailingPathColor());
                    for (int s = 0; s < track.length - 1; s++)
                        drawMapSegment(graphics, track[s], track[s + 1], walkStroke);
                    graphics.setColor(pathColour);
                }
                else
                    drawMapSegment(graphics, from, next, jumpStroke);
                i++;
                continue;
            }

            // Extend the straight walking run while the direction stays the same.
            int dx = unpackWorldX(next) - unpackWorldX(from);
            int dy = unpackWorldY(next) - unpackWorldY(from);
            int j = i + 1;
            while (j < path.size() - 1) {
                int a = path.get(j).getPackedPosition();
                int b = path.get(j + 1).getPackedPosition();
                if (distanceBetween(a, b) > 1
                    || unpackWorldX(b) - unpackWorldX(a) != dx
                    || unpackWorldY(b) - unpackWorldY(a) != dy) {
                    break;
                }
                j++;
            }
            drawMapSegment(graphics, from, path.get(j).getPackedPosition(), walkStroke);
            i = j;
        }
    }

    private void drawMapSegment(Graphics2D graphics, int from, int to, java.awt.Stroke stroke) {
        int x1 = plugin.worldMap().toGraphicsX(from);
        int y1 = plugin.worldMap().toGraphicsY(from);
        int x2 = plugin.worldMap().toGraphicsX(to);
        int y2 = plugin.worldMap().toGraphicsY(to);
        if (x1 == Integer.MIN_VALUE || y1 == Integer.MIN_VALUE
            || x2 == Integer.MIN_VALUE || y2 == Integer.MIN_VALUE) {
            return;
        }
        graphics.setStroke(stroke);
        graphics.drawLine(x1, y1, x2, y2);
        // Skip the head on segments too short to fit it (e.g. zoomed far out).
        if (Math.hypot(x2 - x1, y2 - y1) >= 10)
            ArrowHead.draw(graphics, x1, y1, x2, y2, 7);
    }

    private void drawOnMap(Graphics2D graphics, int point, boolean checkHover, Point cursorPos) {
        drawOnMap(graphics, point, WorldPointUtil.dxdy(point, 1, -1), checkHover, cursorPos);
    }

    private void drawOnMap(Graphics2D graphics, int point, int offsetPoint, boolean checkHover, Point cursorPos) {
        int startX = plugin.worldMap().toGraphicsX(point);
        int startY = plugin.worldMap().toGraphicsY(point);
        int endX = plugin.worldMap().toGraphicsX(offsetPoint);
        int endY = plugin.worldMap().toGraphicsY(offsetPoint);

        if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
            endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE) {
            return;
        }

        int x = startX;
        int y = startY;
        final int width = endX - x;
        final int height = endY - y;
        x -= width / 2;
        y -= height / 2;

        if (distanceBetween(point, offsetPoint) > 1) {
            graphics.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0));
            graphics.drawLine(startX, startY, endX, endY);
        }
        else {
            if (checkHover && cursorPos != null &&
                cursorPos.getX() >= x && cursorPos.getX() <= (endX - width / 2) &&
                cursorPos.getY() >= y && cursorPos.getY() <= (endY - width / 2)) {
                graphics.setColor(graphics.getColor().darker());
            }
            graphics.fillRect(x, y, width, height);
        }
    }

    private Area getWorldMapClipArea(Rectangle baseRectangle) {
        final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
        final Widget surfaceSelector = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0);

        Area clipArea = new Area(baseRectangle);

        if (overview != null && !overview.isHidden())
            clipArea.subtract(new Area(overview.getBounds()));

        if (surfaceSelector != null && !surfaceSelector.isHidden())
            clipArea.subtract(new Area(surfaceSelector.getBounds()));

        return clipArea;
    }
}

package gps;

import com.google.inject.Inject;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;
import gps.transport.Transport;

public class PathMapTooltipOverlay extends Overlay {
    private static final int TOOLTIP_OFFSET_HEIGHT = 25;
    private static final int TOOLTIP_OFFSET_WIDTH = 15;
    private static final int TOOLTIP_PADDING_HEIGHT = 1;
    private static final int TOOLTIP_PADDING_WIDTH = 2;
    private static final int TOOLTIP_TEXT_OFFSET_HEIGHT = -2;

    private final Client client;
    private final ShortestPathPlugin plugin;

    @Inject
    private PathMapTooltipOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_HIGHEST);
        setLayer(OverlayLayer.MANUAL);
        drawAfterInterface(InterfaceID.WORLDMAP);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.display().drawMap || client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
            return null;

        if (plugin.hasPathTargets()) {
            List<PathStep> path = plugin.getDisplayPath();
            Point cursorPos = client.getMouseCanvasPosition();
            for (int i = 0; i < path.size(); i++) {
                int nextPoint = WorldPointUtil.UNDEFINED;
                if (path.size() > i + 1)
                    nextPoint = path.get(i + 1).getPackedPosition();
                if (drawTooltip(graphics, cursorPos, path.get(i).getPackedPosition(), nextPoint, i + 1, path, i))
                    return null;
            }
            for (int target : plugin.getPathTargets()) {
                if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
                    drawTooltip(graphics, cursorPos, target, WorldPointUtil.UNDEFINED, -1, path, -1);
            }
        }

        return null;
    }

    private boolean drawTooltip(Graphics2D graphics, Point cursorPos, int point, int nextPoint, int n,
        List<PathStep> path, int pathIndex) {
        int offsetPoint = WorldPointUtil.dxdy(point, 1, -1);
        int startX = plugin.worldMap().toGraphicsX(point);
        int startY = plugin.worldMap().toGraphicsY(point);
        int endX = plugin.worldMap().toGraphicsX(offsetPoint);
        int endY = plugin.worldMap().toGraphicsY(offsetPoint);

        if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
            endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE) {
            return false;
        }

        int width = endX - startX;

        if (cursorPos.getX() < (startX - width / 2) || cursorPos.getX() > (endX - width / 2) ||
            cursorPos.getY() < (startY - width / 2) || cursorPos.getY() > (endY - width / 2)) {
            return false;
        }

        List<String> rows = new ArrayList<>(Arrays.asList("GPS route:",
            n < 0 ? "Unused target" : ("Step " + n + " of " + path.size())));
        if (nextPoint != WorldPointUtil.UNDEFINED) {
            PathStep currentStep = path.get(pathIndex);
            PathStep nextStep = EdgeTransports.nextStep(path, pathIndex);
            for (Transport transport : plugin.transportsForEdge(currentStep, nextStep)) {
                if (transport.getDisplayInfo() != null && !transport.getDisplayInfo().isEmpty()) {
                    String displayInfo = transport.getDisplayInfo();
                    // Check if this transport goes to POH - if so, look ahead to find the exit
                    // transport
                    String pohExitInfo = PlayerOwnedHouse.exitInfo(nextPoint, path, pathIndex, plugin::transportsForEdge);
                    if (pohExitInfo != null)
                        displayInfo = displayInfo + " (Exit: " + pohExitInfo + ")";
                    rows.add(displayInfo);
                    break;
                }
            }
        }

        graphics.setFont(FontManager.getRunescapeFont());
        FontMetrics fm = graphics.getFontMetrics();
        int tooltipHeight = fm.getHeight();
        int tooltipWidth = 0;
        if (rows.stream().map(fm::stringWidth).max(Integer::compare).isPresent())
            tooltipWidth = rows.stream().map(fm::stringWidth).max(Integer::compareTo).get();
        int clippedHeight = tooltipHeight * rows.size() + TOOLTIP_PADDING_HEIGHT * 2;
        int clippedWidth = tooltipWidth + TOOLTIP_PADDING_WIDTH * 2;

        Rectangle worldMapBounds = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
        int worldMapRightBoundary = worldMapBounds.width + worldMapBounds.x;
        int worldMapBottomBoundary = worldMapBounds.height + worldMapBounds.y;

        int drawPointX = startX + TOOLTIP_OFFSET_WIDTH;
        int drawPointY = startY;
        if (drawPointX + clippedWidth > worldMapRightBoundary)
            drawPointX = worldMapRightBoundary - clippedWidth;
        if (drawPointY + clippedHeight > worldMapBottomBoundary)
            drawPointY = startY - clippedHeight;
        drawPointY += TOOLTIP_OFFSET_HEIGHT;

        int tooltipRectX = drawPointX - TOOLTIP_PADDING_WIDTH;
        int tooltipRectY = drawPointY - TOOLTIP_PADDING_HEIGHT;

        graphics.setColor(JagexColors.TOOLTIP_BACKGROUND);
        graphics.fillRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

        graphics.setColor(JagexColors.TOOLTIP_BORDER);
        graphics.drawRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

        graphics.setColor(JagexColors.TOOLTIP_TEXT);
        for (int i = 0; i < rows.size(); i++)
            graphics.drawString(rows.get(i), drawPointX, drawPointY + TOOLTIP_TEXT_OFFSET_HEIGHT + (i + 1) * tooltipHeight);

        return true;
    }
}

package gps;

import com.google.inject.Inject;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;

public class PathMinimapOverlay extends Overlay {
    private final Client client;
    private final ShortestPathPlugin plugin;

    @Inject
    private PathMinimapOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_LOW);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color) {
        double angle = client.getCameraYawTarget() * Perspective.UNIT;
        double tileSize = client.getMinimapZoom();
        int x = (int) Math.round(center.getX() - tileSize / 2);
        int y = (int) Math.round(center.getY() - tileSize / 2);
        int width = (int) Math.round(tileSize);
        int height = (int) Math.round(tileSize);
        graphics.setColor(color);
        graphics.rotate(angle, center.getX(), center.getY());
        graphics.fillRect(x, y, width, height);
        graphics.rotate(-angle, center.getX(), center.getY());
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.display().drawMinimap || !plugin.hasPathTargets())
            return null;

        Shape minimapClipArea = plugin.minimapClip().area();
        if (minimapClipArea == null)
            return null;
        graphics.setClip(minimapClipArea);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

        java.util.List<PathStep> pathPoints = plugin.getDisplayPath();
        Color pathColor = plugin.getPathColor();
        Color doneColor = new Color(0x80, 0x80, 0x80);
        // Same tri-state colouring as the scene: grey for the covered stretch, blocked colour past
        // the first un-crossed obstacle, normal in between.
        int progress = plugin.displayedRouteProgress();
        int blockedFrom = plugin.blockedFromIndex(pathPoints);
        for (int i = 0; i < pathPoints.size(); i++) {
            int pathPoint = pathPoints.get(i).getPackedPosition();
            if (WorldPointUtil.unpackWorldPlane(pathPoint) != client.getTopLevelWorldView().getPlane())
                continue;

            Color color = i <= progress ? doneColor
                : (i >= blockedFrom ? plugin.display().colourPathBlocked : pathColor);
            drawOnMinimap(graphics, pathPoint, color);
        }
        for (int target : plugin.getPathTargets()) {
            if (!pathPoints.isEmpty() && target != pathPoints.get(pathPoints.size() - 1).getPackedPosition())
                drawOnMinimap(graphics, target, plugin.display().colourPathCalculating);
        }

        return null;
    }

    private void drawOnMinimap(Graphics2D graphics, int location, Color color) {
        PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
        for (int i = 0; i < points.size(); i++) {
            LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));

            if (lp == null)
                continue;

            Point posOnMinimap = Perspective.localToMinimap(client, lp);

            if (posOnMinimap == null)
                continue;

            renderMinimapRect(client, graphics, posOnMinimap, color);
        }
    }
}

package gps;

import com.google.inject.Inject;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;
import gps.transport.BankPickupRequirements;
import gps.transport.Transport;

import static gps.WorldPointUtil.distanceBetween;
import static gps.WorldPointUtil.fromLocalInstance;
import static gps.WorldPointUtil.toLocalInstance;
import static gps.WorldPointUtil.toLocalPoint;
import static gps.WorldPointUtil.unpackWorldPlane;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

public class PathTileOverlay extends Overlay {
    private static final int TRANSPORT_LABEL_GAP = 3;
    // The flowing highlight on the drawn line: a train of small ripples travelling towards the
    // destination — one every WAVE_SPACING steps, each fading over WAVE_HALF_WIDTH steps to either
    // side, moving at WAVE_TILES_PER_SECOND.
    private static final double WAVE_TILES_PER_SECOND = 20;
    private static final double WAVE_SPACING = 60;
    private static final double WAVE_HALF_WIDTH = 4;
    // Half-size of the window the debug off-route bands are computed over, in tiles. Bounds the cost and
    // keeps the render on-screen even when the configured recalculate distance is very large.
    private static final int BAND_WINDOW = 32;
    private final Client client;
    private final ShortestPathPlugin plugin;
    // Labels stack only with the other labels on their own tile; keyed by packed world tile, per frame.
    private final Map<Integer, Integer> tileLabelOffsets = new HashMap<>();
    // Door tiles already hinted this frame — a door can sit on two path edges (a diagonal
    // approach then the straight crossing), which would otherwise stack "Open Door" twice.
    private final Set<Integer> hintedDoorTiles = new HashSet<>();
    // Pickup hints already drawn this frame: a route fetching an item walks across neighbouring bank
    // stand tiles, each a "bank step", and the label would otherwise stack once per tile.
    private final Set<String> hintedPickups = new HashSet<>();

    @Inject
    public PathTileOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_LOW);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        tileLabelOffsets.clear();
        hintedDoorTiles.clear();
        hintedPickups.clear();

        if (plugin.display().drawRecalculationRanges) {
            drawArrivalTiles(graphics);
            drawRecalculationRanges(graphics);
        }

        if (plugin.display().drawTiles && !plugin.getDisplayPath().isEmpty()) {
            Color pathColor = plugin.getPathColor();
            Color color = new Color(
                pathColor.getRed(),
                pathColor.getGreen(),
                pathColor.getBlue(),
                pathColor.getAlpha() / 2);
            Color blockedColor = new Color(
                plugin.display().colourPathBlocked.getRed(),
                plugin.display().colourPathBlocked.getGreen(),
                plugin.display().colourPathBlocked.getBlue(),
                plugin.display().colourPathBlocked.getAlpha() / 2);
            // The stretch the player has already covered is greyed out — the live part is what's ahead.
            Color doneColor = new Color(0x80, 0x80, 0x80, pathColor.getAlpha() / 2);

            List<PathStep> path = plugin.getDisplayPath();
            // The path beyond the first door not yet seen open renders in the blocked colour: the
            // route assumes doors are passable, this marks the part the player can't walk yet.
            int blockedFrom = plugin.blockedFromIndex(path);
            // Progress along the displayed route: edges up to here are done (greyed).
            int progress = plugin.displayedRouteProgress();
            // Repeating ripples flow along the line towards the destination: each edge's glow is
            // its proximity to the nearest ripple centre in a train spaced WAVE_SPACING apart.
            double waveOffset = ((System.currentTimeMillis() % 600_000L) / 1000.0 * WAVE_TILES_PER_SECOND)
                % WAVE_SPACING;
            java.util.Set<Integer> sailingEdges = plugin.getDisplaySailingEdges();
            // Per-frame context hoisted out of the per-edge loop: this used to rebuild the
            // player's item map and a teleport set for EVERY edge of the route, every frame
            // (~1M short-lived objects per second on a long route). Edges with neither end
            // near the loaded scene draw nothing and are skipped; sea tracks cross the scene
            // between far endpoints, so they are handled before the cull. Instances map
            // template coordinates, so they are never culled by world bounds.
            final net.runelite.api.WorldView worldView = client.getTopLevelWorldView();
            final boolean cullByScene = !worldView.isInstance();
            final int sceneMinX = worldView.getBaseX() - 2;
            final int sceneMinY = worldView.getBaseY() - 2;
            final int sceneMaxX = worldView.getBaseX() + worldView.getSizeX() + 2;
            final int sceneMaxY = worldView.getBaseY() + worldView.getSizeY() + 2;
            final Map<Integer, Integer> playerHas = plugin.display().showTransportInfo
                ? BankPickupRequirements.collectPlayerItems(client) : Map.of();
            for (int i = 1; i < path.size(); i++) {
                PathStep currentStep = path.get(i - 1);
                PathStep nextStep = path.get(i);
                // A non-adjacent pair is a teleport/transport jump, not a walkable edge.
                boolean jump = distanceBetween(
                    currentStep.getPackedPosition(), nextStep.getPackedPosition()) > 1;
                // Sailing legs draw their sea track through the scene: the jump's endpoints
                // are ports/pins far outside the loaded scene mid-voyage, so the dashed beam
                // below rendered NOTHING while actually sailing. Track segments near the boat
                // project fine; drawLine skips the rest.
                if (jump && sailingEdges.contains(i - 1)) {
                    int[] track = SailingSea.seaPath(
                        currentStep.getPackedPosition(), nextStep.getPackedPosition());
                    if (track != null && track.length > 1) {
                        boolean done = i <= progress;
                        // The sailed stretch greys waypoint by waypoint behind the boat: the
                        // aboard position scored against the track, same rule the tracker uses.
                        int sailedUpTo = -1;
                        if (!done && client.getVarbitValue(
                            net.runelite.api.gameval.VarbitID.SAILING_BOARDED_BOAT) != 0) {
                            int playerPacked = fromLocalInstance(
                                client, client.getLocalPlayer());
                            if (playerPacked != WorldPointUtil.UNDEFINED) {
                                int nearestDistance = Integer.MAX_VALUE;
                                for (int w = 0; w < track.length; w++) {
                                    int d = distanceBetween(playerPacked, track[w]);
                                    if (d < nearestDistance) {
                                        nearestDistance = d;
                                        sailedUpTo = w;
                                    }
                                }
                                if (nearestDistance > 30) {
                                    sailedUpTo = -1; // aboard on a DIFFERENT leg: grey nothing here
                                }
                            }
                        }
                        Color sail = plugin.getSailingPathColor();
                        Color sailColor = new Color(sail.getRed(), sail.getGreen(), sail.getBlue(),
                            sail.getAlpha() / 2);
                        for (int s = 1; s < track.length; s++) {
                            Color segment = done || s <= sailedUpTo ? doneColor
                                : (i >= blockedFrom ? blockedColor : sailColor);
                            drawLine(graphics, track[s - 1], track[s], segment,
                                s == track.length - 1, 0, false);
                        }
                        drawTransportInfo(graphics, currentStep, nextStep, path, i - 1, playerHas);
                        continue;
                    }
                }
                // Arrowheads only where they carry information: at direction changes and the end.
                boolean head = i == path.size() - 1
                    || directionChanges(currentStep.getPackedPosition(), nextStep.getPackedPosition(),
                        path.get(i + 1).getPackedPosition());
                double phase = (i - waveOffset) % WAVE_SPACING;
                if (phase < 0)
                    phase += WAVE_SPACING;
                double waveDistance = Math.min(phase, WAVE_SPACING - phase);
                if (cullByScene
                    && !nearScene(currentStep.getPackedPosition(), sceneMinX, sceneMinY, sceneMaxX, sceneMaxY)
                    && !nearScene(nextStep.getPackedPosition(), sceneMinX, sceneMinY, sceneMaxX, sceneMaxY)) {
                    continue;
                }
                // Edge i covers path[i-1]->path[i]; it's done once progress has reached path[i].
                boolean done = i <= progress;
                double glow = jump || done || !plugin.display().showPathPulse ? 0 : Math.max(0, 1 - waveDistance / WAVE_HALF_WIDTH);
                Color edgeColor = done ? doneColor : (i >= blockedFrom ? blockedColor : color);
                drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(),
                    edgeColor, head, glow, jump);
                drawTransportInfo(graphics, currentStep, nextStep, path, i - 1, playerHas);
            }

            // GPS decorations for the displayed route: a small waypoint dot where each section ends
            // (walk up to here, then do the next step) and a growing green pulse on the destination.
            RouteOption displayedRoute = plugin.getDisplayedRoute();
            if (displayedRoute != null && plugin.display().showDirections)
                drawGpsMarkers(graphics, displayedRoute);

            if (plugin.isPathUnreachable())
                drawLabelOnPlayerTile(graphics, plugin.display().unreachableText);
        }

        return null;
    }

    /**
     * The hint for a door/gate transport on the path, shown only while it needs opening: when the
     * closed door object (whose id is the trailing token of the objectInfo, e.g. "Open Door 9398")
     * is still standing at either end of the edge. Opening the door replaces the object, so the hint
     * disappears by itself. Null for non-door transports and doors that are already open.
     */
    private String closedDoorText(Transport transport) {
        String objectInfo = transport.getObjectInfo();
        if (objectInfo == null || !RouteDirections.isDoorway(transport))
            return null;
        int lastSpace = objectInfo.lastIndexOf(' ');
        if (lastSpace <= 0)
            return null;
        String idText = objectInfo.substring(lastSpace + 1);
        if (idText.isEmpty() || !idText.chars().allMatch(Character::isDigit))
            return null;
        int objectId = Integer.parseInt(idText);
        if (objectPresent(transport.getOrigin(), objectId) || objectPresent(transport.getDestination(), objectId))
            return objectInfo.substring(0, lastSpace);
        return null;
    }

    private boolean objectPresent(int packedLocation, int objectId) {
        return SceneObjects.objectPresent(client, packedLocation, objectId);
    }

    private void drawGpsMarkers(Graphics2D graphics, RouteOption route) {
        List<RouteDirections.Step> steps = plugin.getRouteDirections(route);
        List<PathStep> path = route.getPath();
        if (steps.isEmpty() || path.isEmpty())
            return;
        int destinationIndex = path.size() - 1;
        Set<Integer> marked = new HashSet<>();
        for (RouteDirections.Step step : steps) {
            int end = step.getEndIndex();
            if (end <= 0 || end >= destinationIndex) {
                continue; // the destination gets the pulse, not a dot
            }
            int packed = path.get(end).getPackedPosition();
            if (marked.add(packed))
                drawSectionMarker(graphics, packed);
        }
        // A round trip's halfway point (the bank) pulses GOLD while the outbound leg is being
        // walked — reach it and the beacon vanishes, leaving the green home pulse for the way back.
        RouteOption displayed = plugin.getDisplayedRoute();
        if (displayed != null && displayed.isRoundTrip()) {
            int turnaround = displayed.getTurnaroundIndex();
            if (turnaround > 0 && turnaround < path.size()
                && plugin.displayedRouteProgress() < turnaround - 2) {
                drawDestinationPulse(graphics, path.get(turnaround).getPackedPosition(), PULSE_TURNAROUND);
            }
        }
        drawDestinationPulse(graphics, path.get(destinationIndex).getPackedPosition());
    }

    /**
     * A small waypoint dot on the tile where a route section ends: white ring with a path-coloured
     * core, so the "walk up to here" points stand out along the drawn line.
     */
    private void drawSectionMarker(Graphics2D graphics, int location) {
        PrimitiveIntList points = toLocalInstance(client, location);
        for (int i = 0; i < points.size(); i++) {
            LocalPoint lp = toLocalPoint(client, points.get(i));
            if (lp == null)
                continue;
            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null)
                continue;
            final double cx = poly.getBounds().getCenterX();
            final double cy = poly.getBounds().getCenterY();
            graphics.setColor(Color.WHITE);
            graphics.fill(new Ellipse2D.Double(cx - 4.5, cy - 4.5, 9, 9));
            Color pathColour = plugin.getPathColor();
            graphics.setColor(new Color(pathColour.getRed(), pathColour.getGreen(), pathColour.getBlue()));
            graphics.fill(new Ellipse2D.Double(cx - 3, cy - 3, 6, 6));
        }
    }

    /**
     * The journey's end: a green circle growing out of the destination tile and fading, looping —
     * the same rhythm as the teleport pulse. The flattening follows the camera: a circle drawn on
     * the ground plane projects to an ellipse with the same height/width ratio as the projected
     * tile itself (the yaw factor cancels out of a square tile's bounding box, leaving only the
     * pitch compression) — so it's a perfect circle seen top-down and flattens as the camera drops.
     */
    /**
     * Debug view of the off-route bands, drawn as contours hugging the PATH (not the player): tiles
     * exactly the warning distance from the nearest path tile are tinted yellow and those exactly the
     * recalculate distance red — the same Chebyshev metric the recalc check uses, so the two thresholds
     * trace the corridor the player must stay inside. Computed over a bounded window around the player
     * (the on-screen stretch) so a large configured distance can't blow up the render. A label reports
     * the live distance from the path.
     */
    private void drawRecalculationRanges(Graphics2D graphics) {
        final Player player = client.getLocalPlayer();
        final int recalc = plugin.getRecalculateDistance();
        final List<PathStep> path = plugin.getDisplayPath();
        if (player == null || recalc < 0 || path == null || path.isEmpty())
            return;
        final int warn = plugin.getOffRouteWarnDistance();
        final int centre = fromLocalInstance(client, player);
        final int cx = unpackWorldX(centre);
        final int cy = unpackWorldY(centre);
        final int plane = unpackWorldPlane(centre);
        final int window = Math.min(recalc + 1, BAND_WINDOW);

        // Path tiles near enough to be some window tile's nearest (within window of a tile within window).
        final int[] near = new int[path.size()];
        int nearCount = 0;
        for (PathStep step : path) {
            final int p = step.getPackedPosition();
            if (unpackWorldPlane(p) == plane
                && distanceBetween(centre, p) <= 2 * window) {
                near[nearCount++] = p;
            }
        }
        if (nearCount > 0) {
            final Color warnFill = new Color(0xFF, 0xE0, 0x00, 70);
            final Color warnLine = new Color(0xFF, 0xE0, 0x00, 200);
            final Color recalcFill = new Color(0xFF, 0x3C, 0x3C, 70);
            final Color recalcLine = new Color(0xFF, 0x3C, 0x3C, 200);
            for (int dx = -window; dx <= window; dx++) {
                for (int dy = -window; dy <= window; dy++) {
                    final int tile = WorldPointUtil.packWorldPoint(cx + dx, cy + dy, plane);
                    int dmin = Integer.MAX_VALUE;
                    for (int k = 0; k < nearCount; k++) {
                        final int dist = distanceBetween(tile, near[k]);
                        if (dist < dmin)
                            dmin = dist;
                        if (dmin < warn) {
                            break; // interior to the warning band — not a boundary tile
                        }
                    }
                    // Only the two contour lines; the recalc boundary wins a tie with the warn boundary.
                    if (dmin == recalc)
                        highlightWorldTile(graphics, tile, recalcFill, recalcLine);
                    else if (dmin == warn)
                        highlightWorldTile(graphics, tile, warnFill, warnLine);
                }
            }
        }

        final int d = plugin.getPathDistance();
        final Point anchor = Perspective.localToCanvas(client, player.getLocalLocation(), plane);
        if (anchor != null) {
            final String label = "off-route: " + (d < 0 ? "?" : d)
                + " (warn " + warn + " / recalc " + recalc + ")";
            graphics.setColor(plugin.isOffRouteWarning() ? new Color(0xFF, 0x4C, 0x4C) : Color.WHITE);
            graphics.drawString(label, anchor.getX() + 6, anchor.getY());
        }
    }

    private void highlightWorldTile(Graphics2D graphics, int location, Color fill, Color outline) {
        final PrimitiveIntList points = toLocalInstance(client, location);
        for (int i = 0; i < points.size(); i++) {
            final LocalPoint lp = toLocalPoint(client, points.get(i));
            if (lp == null)
                continue;
            final Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null)
                continue;
            graphics.setColor(fill);
            graphics.fill(poly);
            graphics.setColor(outline);
            graphics.draw(poly);
        }
    }

    /**
     * Tint the ACTUAL arrival tiles green: the plugin's arrival zone, i.e. every walkable tile within
     * the finish distance of the destination (flooded over the collision map). This is the exact set
     * the arrival check tests membership of — standing on any tinted tile completes the journey.
     */
    private void drawArrivalTiles(Graphics2D graphics) {
        final Color fill = new Color(0x3C, 0xC8, 0x6A, 60);
        final Color outline = new Color(0x3C, 0xC8, 0x6A, 170);
        for (int tile : plugin.getArrivalTiles())
            highlightWorldTile(graphics, tile, fill, outline);
    }

    // The two pulse colours: green marks the journey's end; gold marks a round trip's turnaround
    // (the bank) while the outbound leg is being walked — an "arrive here first" beacon that
    // disappears once the player reaches it and the trip continues home.
    private static final Color PULSE_DESTINATION = new Color(0, 220, 90);
    private static final Color PULSE_TURNAROUND = new Color(255, 196, 64);

    private void drawDestinationPulse(Graphics2D graphics, int location) {
        drawDestinationPulse(graphics, location, PULSE_DESTINATION);
    }

    private void drawDestinationPulse(Graphics2D graphics, int location, Color colour) {
        PrimitiveIntList points = toLocalInstance(client, location);
        for (int i = 0; i < points.size(); i++) {
            LocalPoint lp = toLocalPoint(client, points.get(i));
            if (lp == null)
                continue;
            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null)
                continue;
            final double cx = poly.getBounds().getCenterX();
            final double cy = poly.getBounds().getCenterY();
            final double tileWidth = Math.max(8, poly.getBounds().getWidth());
            // Ground-plane flattening from the tile's own projection; clamped for degenerate polys.
            final double flatten = Math.min(1.0, Math.max(0.1,
                poly.getBounds().getHeight() / Math.max(1.0, poly.getBounds().getWidth())));

            final long period = 1400L;
            final int rings = 2;
            final Stroke previousStroke = graphics.getStroke();
            graphics.setStroke(new BasicStroke(2.2f));
            for (int r = 0; r < rings; r++) {
                double phase = ((System.currentTimeMillis() + (long) (r * period / (double) rings)) % period)
                    / (double) period;
                double radius = tileWidth * (0.25 + phase * 1.1);
                int alpha = (int) Math.round(180 * (1.0 - phase));
                if (alpha <= 0)
                    continue;
                graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
                graphics.draw(new Ellipse2D.Double(
                    cx - radius, cy - radius * flatten, radius * 2, radius * 2 * flatten));
            }
            graphics.setStroke(previousStroke);
        }
    }

    private static boolean directionChanges(int previous, int current, int next) {
        int dx1 = unpackWorldX(current) - unpackWorldX(previous);
        int dy1 = unpackWorldY(current) - unpackWorldY(previous);
        int dx2 = unpackWorldX(next) - unpackWorldX(current);
        int dy2 = unpackWorldY(next) - unpackWorldY(current);
        return dx1 != dx2 || dy1 != dy2;
    }

    // Immutable strokes shared by every edge (BasicStroke is immutable; allocating three per edge
    // per frame was pure garbage).
    private static final BasicStroke JUMP_STROKE = new BasicStroke(2, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND,
        10f, new float[]{8, 8}, 0);
    private static final BasicStroke LINE_STROKE = new BasicStroke(5, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
    private static final BasicStroke GLOW_STROKE = new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

    private void drawLine(Graphics2D graphics, int startLoc, int endLoc, Color color, boolean arrowHead,
        double glow, boolean jump) {
        PrimitiveIntList starts = toLocalInstance(client, startLoc);
        PrimitiveIntList ends = toLocalInstance(client, endLoc);

        if (starts.isEmpty() || ends.isEmpty())
            return;

        int start = starts.get(0);
        int end = ends.get(0);

        final int z = client.getTopLevelWorldView().getPlane();
        if (unpackWorldPlane(start) != z)
            return;

        LocalPoint lpStart = toLocalPoint(client, start);
        LocalPoint lpEnd = toLocalPoint(client, end);

        if (lpStart == null || lpEnd == null)
            return;

        final int startHeight = Perspective.getTileHeight(client, lpStart, z);
        final int endHeight = Perspective.getTileHeight(client, lpEnd, z);

        Point p1 = Perspective.localToCanvas(client, lpStart.getX(), lpStart.getY(), startHeight);
        Point p2 = Perspective.localToCanvas(client, lpEnd.getX(), lpEnd.getY(), endHeight);

        if (p1 == null || p2 == null)
            return;

        Line2D.Double line = new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY());

        graphics.setColor(color);
        if (jump)
            // Teleport/transport jumps: a thin dashed hint, like the world map draws them —
            // a full solid beam across the scene reads as a walkable line, which it isn't.
            graphics.setStroke(JUMP_STROKE);
        else
            graphics.setStroke(LINE_STROKE);
        graphics.draw(line);
        if (arrowHead && plugin.display().showPathArrows)
            ArrowHead.draw(graphics, p1.getX(), p1.getY(), p2.getX(), p2.getY(), 12);
        if (glow > 0) {
            // The flowing ripple: a subtly brighter core stroke — only a mild step towards white,
            // at the path colour's own opacity, so it reads as a sheen rather than a flash.
            graphics.setColor(new Color(
                color.getRed() + (int) ((255 - color.getRed()) * glow * 0.18),
                color.getGreen() + (int) ((255 - color.getGreen()) * glow * 0.18),
                color.getBlue() + (int) ((255 - color.getBlue()) * glow * 0.18),
                color.getAlpha()));
            graphics.setStroke(GLOW_STROKE);
            graphics.draw(line);
        }
    }

    private int drawLabelAtCanvasPoint(Graphics2D graphics, Point point, String text, int verticalOffset) {
        if (point == null || text == null || text.isEmpty())
            return 0;

        double height = drawLabel(graphics, point, text, verticalOffset);

        return (int) height + TRANSPORT_LABEL_GAP;
    }

    /** Draws a label above the tile, stacked over the labels already drawn on that tile this frame. */
    private void drawLabelAtPackedLocation(Graphics2D graphics, int location, String text) {
        int base = tileLabelOffsets.getOrDefault(location, 0);
        int used = base;
        PrimitiveIntList points = toLocalInstance(client, location);
        for (int i = 0; i < points.size(); i++) {
            LocalPoint lp = toLocalPoint(client, points.get(i));
            if (lp == null)
                continue;

            Point p = Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane());
            if (p == null)
                continue;

            // an instanced tile has a copy per chunk: each copy gets the label at the same height
            used = Math.max(used, base + drawLabelAtCanvasPoint(graphics, p, text, base));
        }
        tileLabelOffsets.put(location, used);
    }

    /**
     * A pulsing "teleport from here" highlight: diamond rings expanding out from the tile and fading,
     * looping. Drawn every frame (scene overlays repaint continuously) off wall-clock time, so the motion
     * stays smooth regardless of game ticks. Anchored to the tile the player casts from — for a
     * cast-from-anywhere teleport that sits under the player, drawing the eye to "teleport now".
     */
    private void drawTeleportPulse(Graphics2D graphics, int location) {
        PrimitiveIntList points = toLocalInstance(client, location);
        for (int i = 0; i < points.size(); i++) {
            LocalPoint lp = toLocalPoint(client, points.get(i));
            if (lp == null)
                continue;
            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null || poly.npoints == 0)
                continue;
            final double cx = poly.getBounds().getCenterX();
            final double cy = poly.getBounds().getCenterY();

            final long period = 1400L;
            final int rings = 2;
            final Color base = plugin.display().colourTeleportPulse;
            final Stroke previousStroke = graphics.getStroke();
            graphics.setStroke(new BasicStroke(2.2f));
            for (int r = 0; r < rings; r++) {
                // Stagger the two rings by half a period so one is always small/bright while the other
                // is large/faint — a continuous outward pulse.
                double phase = ((System.currentTimeMillis() + (long) (r * period / (double) rings)) % period)
                    / (double) period;
                double scale = 1.0 + phase * 2.6;
                int alpha = (int) Math.round(170 * (1.0 - phase));
                if (alpha <= 0)
                    continue;
                Path2D ring = new Path2D.Double();
                for (int v = 0; v < poly.npoints; v++) {
                    double x = cx + (poly.xpoints[v] - cx) * scale;
                    double y = cy + (poly.ypoints[v] - cy) * scale;
                    if (v == 0)
                        ring.moveTo(x, y);
                    else
                        ring.lineTo(x, y);
                }
                ring.closePath();
                graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
                graphics.draw(ring);
            }
            graphics.setStroke(previousStroke);
        }
    }

    private double drawLabel(Graphics2D graphics, Point point, String text, int verticalOffset) {
        Rectangle2D textBounds = graphics.getFontMetrics().getStringBounds(text, graphics);
        double height = textBounds.getHeight();
        int x = (int) (point.getX() - textBounds.getWidth() / 2);
        int y = (int) (point.getY() - height) - verticalOffset;
        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 1, y + 1);
        graphics.setColor(plugin.display().colourText);
        graphics.drawString(text, x, y);
        return height;
    }

    private void drawLabelOnPlayerTile(Graphics2D graphics, String text) {
        if (client.getLocalPlayer() == null)
            return;

        LocalPoint local = client.getLocalPlayer().getLocalLocation();
        int tile = fromLocalInstance(client, local);
        int base = tileLabelOffsets.getOrDefault(tile, 0);
        Point playerPoint = Perspective.localToCanvas(client, local, client.getTopLevelWorldView().getPlane());
        tileLabelOffsets.put(tile, base + drawLabelAtCanvasPoint(graphics, playerPoint, text, base));
    }

    private static boolean nearScene(int packed, int minX, int minY, int maxX, int maxY) {
        int x = unpackWorldX(packed);
        int y = unpackWorldY(packed);
        return x >= minX && x <= maxX && y >= minY && y <= maxY;
    }

    private void drawTransportInfo(Graphics2D graphics, PathStep currentStep, PathStep nextStep, List<PathStep> path,
        int pathIndex, Map<Integer, Integer> playerHas) {
        int location = currentStep.getPackedPosition();
        if (nextStep == null || !plugin.display().showTransportInfo ||
            unpackWorldPlane(location) != client.getTopLevelWorldView().getPlane()) {
            return;
        }

        // Sailing: teleports are suppressed while aboard a boat. When the path is
        // unreachable as a result, show a one-time hint on the player tile.
        if (pathIndex == 0 && plugin.getPathfinderConfig().isOnSailingBoat()
            && plugin.isPathUnreachable()) {
            drawLabelOnPlayerTile(graphics, "Disembark the boat to resume pathfinding");
            return;
        }

        if (plugin.isPathUnreachable())
            return;
        int locationEnd = nextStep.getPackedPosition();

        // Workaround for weird pathing inside PoH to instead show info on the player
        // tile
        LocalPoint playerLocalPoint = client.getLocalPlayer().getLocalLocation();
        int playerPackedPoint = fromLocalInstance(client, playerLocalPoint);
        int px = unpackWorldX(playerPackedPoint);
        int py = unpackWorldY(playerPackedPoint);
        int tx = unpackWorldX(location);
        int ty = unpackWorldY(location);
        boolean transportAndPlayerInsidePoh = PlayerOwnedHouse.isInside(tx, ty)
            && PlayerOwnedHouse.isInside(px, py);
        Set<Transport> candidateTransports = plugin.transportsForEdge(currentStep, nextStep);

        // When inside POH, only show the POH exit info once (not per-transport)
        if (transportAndPlayerInsidePoh) {
            String pohExitInfo = PlayerOwnedHouse.exitInfo(locationEnd, path, pathIndex, plugin::transportsForEdge);
            if (pohExitInfo == null)
                return;

            // Find the display name of the teleport that brought us to POH using bank-aware
            // lookup
            String text = null;
            for (Transport transport : candidateTransports) {
                text = transport.getDisplayInfo();
                if (text != null && !text.isEmpty())
                    break;
            }
            if (text == null || text.isEmpty())
                return;
            text = text + " (Exit: " + pohExitInfo + ")";

            Point p = Perspective.localToCanvas(client, playerLocalPoint, client.getTopLevelWorldView().getPlane());
            if (p == null)
                return;

            drawLabel(graphics, p, text, 0);
            return;
        }

        // A doorway on a plain walk edge: the collision map bakes openable doors passable, so
        // the path assumes they are open. Hint while the door is actually closed (the closed
        // object still stands in the scene) — opening it replaces the object, so the hint
        // clears by itself. Edges with a mapped door transport are handled below instead.
        if (candidateTransports.isEmpty()) {
            ClosedDoors.Door door = ClosedDoors.doorBetween(location, locationEnd);
            if (door != null && ClosedDoors.state(client, door) == ClosedDoors.State.CLOSED
                && hintedDoorTiles.add(door.packedPosition)) {
                drawLabelAtPackedLocation(graphics, door.packedPosition, "Open " + door.name);
            }
        }

        // Check if this is a bank step and items need to be picked up. The SNAPSHOT (live
        // contents once a bank opens, the previous session's persisted state before that)
        // stands in for the live container so the hint works from login.
        Set<Integer> bankLocations = plugin.getPathfinderConfig().getDestinations("bank");
        if (bankLocations != null && plugin.getPathfinderConfig().getBankSnapshot() != null) {
            List<String> bankPickupItems = BankPickupRequirements.compute(
                client,
                plugin.getPathfinderConfig().getBankSnapshot(),
                plugin.getPathfinderConfig(),
                bankLocations,
                path,
                pathIndex
            ).phrases;
            if (!bankPickupItems.isEmpty()) {
                String pickupText = "Pick up: " + String.join(", ", bankPickupItems);
                if (hintedPickups.add(pickupText))
                    drawLabelAtPackedLocation(graphics, location, pickupText);

                // By default, bank pickup info replaces the default transport hint text;
                // enable the option to show both
                if (!plugin.display().showBankPickupInfo)
                    return;
            }
        }

        // Only show transports the player can currently use; fall back to all if none are usable.
        List<Transport> usableTransports = new ArrayList<>();
        for (Transport t : candidateTransports) {
            if (BankPickupRequirements.transportSatisfiedBy(t, playerHas, plugin.getPathfinderConfig().farePercent(t)))
                usableTransports.add(t);
        }
        Collection<Transport> transportsToShow = usableTransports.isEmpty() ? candidateTransports : usableTransports;

        // Teleports ("use this item/spell") get a pulsing highlight on the tile you cast from, drawn
        // once for the edge even if several teleport options share it.
        boolean teleportEdge = false;
        for (Transport transport : transportsToShow) {
            if (transport.getType() != null && transport.getType().isTeleport()) {
                teleportEdge = true;
                break;
            }
        }
        // Also pulse when the DISPLAYED route teleports on this edge but the config-derived lookup
        // above missed it — a charged jewellery leg under a "perm-only" teleport-item setting.
        if (!teleportEdge)
            teleportEdge = plugin.displayedRouteTeleportsAt(pathIndex);
        if (teleportEdge && plugin.display().showTeleportPulse)
            drawTeleportPulse(graphics, location);

        Set<String> shownTexts = new HashSet<>();
        for (Transport transport : transportsToShow) {
            String text = transport.getDisplayInfo();
            if (text == null || text.isEmpty()) {
                // Stairs, ladders, agility shortcuts and other object transports have no display
                // info, so the drawn line just ends at them with no cue. Fall back to their menu
                // text ("Climb-up Staircase", "Walk-across Log balance") so the player is told to
                // use them. Doors are left to the closed-door hint below — an open door needs no
                // label.
                String objectText = RouteDirections.objectText(transport);
                if (objectText != null && !RouteDirections.isDoorway(transport))
                    text = objectText;
            }
            if (text == null || text.isEmpty())
                // Doors/gates: hint only while the door is actually closed (the closed object still
                // stands in the scene) — an open door needs no cue, and labelling every doorway on
                // the path would be noise.
                text = closedDoorText(transport);
            if (text == null || text.isEmpty() || !shownTexts.add(text))
                continue;

            // Check if this transport goes to POH - if so, look ahead to find the exit
            // transport
            String pohExitInfo = PlayerOwnedHouse.exitInfo(locationEnd, path, pathIndex, plugin::transportsForEdge);
            if (pohExitInfo != null)
                text = text + " (Exit: " + pohExitInfo + ")";

            drawLabelAtPackedLocation(graphics, location, text);
        }

        // Fallback: the displayed route teleports here (e.g. a charged tablet/jewellery) but the
        // config-derived lookup above found no matching transport — its teleport-item setting
        // ("Inventory (perm)") excludes consumables. Label it straight from the route's method so
        // the world cue matches the pulse and the panel step.
        if (shownTexts.isEmpty()) {
            TeleportMethod routeMethod = plugin.displayedRouteMethodAt(pathIndex);
            if (routeMethod != null && routeMethod.getType() != null && routeMethod.getType().isTeleport()) {
                String label = routeMethod.label();
                if (label != null && !label.isEmpty())
                    drawLabelAtPackedLocation(graphics, location, label);
            }
        }
    }

}

package gps;

public class PendingTask {
    private final int tick;
    private final Runnable task;

    PendingTask(int tick, Runnable task) {
        this.tick = tick;
        this.task = task;
    }

    public boolean check(int tick) {
        return tick >= this.tick;
    }

    public void run() {
        task.run();
    }
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.BiFunction;
import net.runelite.api.GameObject;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;

import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

/**
 * What GPS knows about the player-owned house (plan step L18, out of the plugin class): the
 * model area route tiles live in, the template regions a live house scene is assembled from,
 * the exit-transport label for a route that ends inside, and the two adapters the furniture
 * detection reads the client through.
 */
public final class PlayerOwnedHouse {
    // The POH model area (the transport data's y 5696 band) route tiles use. MIN_X is 1856 to
    // exclude the Daddy's Home miniquest area.
    private static final int MIN_X = 1856;
    private static final int MAX_X = 2047;
    private static final int MIN_Y = 5696;
    private static final int MAX_Y = 5767;
    // The map regions LIVE house instances are assembled from (rx 29-32, ry 110-111), distinct
    // from the model area above. Confirmed three ways (2026-07-17): a real house's chunk-dump
    // log, a cache scan (PohTemplateScanTest in shortest-path-tooling; ~13 copies of every room
    // hotspot, one per house STYLE), and the same region set hardcoded by other POH-aware
    // plugins. Every style and house location resolves to these regions. Checking the wrong band
    // here is why presence detection failed repeatedly.
    private static final Set<Integer> TEMPLATE_REGIONS =
        Set.of(7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);

    private PlayerOwnedHouse() {
    }

    /** Whether a world coordinate lies in the house model area. */
    public static boolean isInside(int x, int y) {
        return x >= MIN_X && x <= MAX_X && y >= MIN_Y && y <= MAX_Y;
    }

    /**
     * Whether the world view is a player-owned house: an instance whose loaded map regions
     * (which for instances are the TEMPLATE regions the scene is assembled from) include a house
     * template region.
     */
    public static boolean isHouseScene(WorldView worldView) {
        if (worldView == null || !worldView.isInstance())
            return false;
        int[] regions = worldView.getMapRegions();
        if (regions != null) {
            for (int region : regions) {
                if (TEMPLATE_REGIONS.contains(region))
                    return true;
            }
        }
        return false;
    }

    /**
     * For a destination inside the house, the transport the path takes out of it (the first
     * inside-to-outside edge after {@code currentIndex}), labelled by what it is: a mounted
     * jewellery piece, the nexus, a fairy ring, a spirit tree, the obelisk. Null when the
     * destination is outside, the path leaves the house before a transport, or none is found.
     */
    public static String exitInfo(int destination, List<PathStep> path, int currentIndex,
        BiFunction<PathStep, PathStep, Set<Transport>> transportsForEdge) {
        if (path == null || currentIndex < 0)
            return null;
        if (!isInside(unpackWorldX(destination), unpackWorldY(destination)))
            return null;
        for (int i = currentIndex + 1; i < path.size() - 1; i++) {
            int stepLocation = path.get(i).getPackedPosition();
            int nextLocation = path.get(i + 1).getPackedPosition();
            boolean stepInside = isInside(unpackWorldX(stepLocation), unpackWorldY(stepLocation));
            boolean nextInside = isInside(unpackWorldX(nextLocation), unpackWorldY(nextLocation));
            if (stepInside && !nextInside) {
                for (Transport transport : transportsForEdge.apply(path.get(i), path.get(i + 1))) {
                    String exitInfo = transport.getDisplayInfo();
                    return exitInfo == null || exitInfo.isEmpty() ? null : exitLabel(transport, exitInfo);
                }
                return null;
            }
            if (!stepInside) {
                return null; // left the house without a transport
            }
        }
        return null;
    }

    private static String exitLabel(Transport transport, String exitInfo) {
        TransportType exitType = transport.getType();
        if (TransportType.TELEPORTATION_BOX.equals(exitType)) {
            String objInfo = transport.getObjectInfo();
            if (objInfo != null && objInfo.contains("Amulet of Glory"))
                return "Mounted Glory: " + exitInfo;
            if (objInfo != null && objInfo.contains("Mythical cape"))
                return "Mythical Cape: " + exitInfo;
            if (objInfo != null && objInfo.contains("Xeric's Talisman"))
                return "Xeric's Talisman: " + exitInfo;
            if (objInfo != null && objInfo.contains("Digsite"))
                return "Digsite Pendant: " + exitInfo;
            return "Jewelry Box: " + exitInfo;
        }
        if (TransportType.TELEPORTATION_PORTAL_POH.equals(exitType))
            return "Nexus: " + exitInfo;
        if (TransportType.FAIRY_RING.equals(exitType))
            return "Fairy Ring " + exitInfo;
        if (TransportType.SPIRIT_TREE.equals(exitType))
            return "Spirit Tree: " + exitInfo;
        if (TransportType.WILDERNESS_OBELISK.equals(exitType))
            return "Obelisk: " + exitInfo;
        return exitInfo;
    }

    /** What the furniture detection reads from a loaded scene. */
    static PohDetectionService.Scene scene(WorldView worldView) {
        return new PohDetectionService.Scene() {
            @Override
            public boolean isHouse() {
                return isHouseScene(worldView);
            }

            @Override
            public boolean isInstance() {
                return worldView != null && worldView.isInstance();
            }

            @Override
            public String describeChunks() {
                return WorldPointUtil.describeInstanceChunks(worldView);
            }

            @Override
            public Set<Integer> objectIds() {
                return sceneObjectIds(worldView);
            }
        };
    }

    /** Every game object id in the loaded scene: the tile walk behind the house scan. */
    private static Set<Integer> sceneObjectIds(WorldView worldView) {
        Set<Integer> ids = new HashSet<>();
        Tile[][][] tiles = worldView.getScene().getTiles();
        for (Tile[][] plane : tiles) {
            if (plane == null)
                continue;
            for (Tile[] column : plane) {
                if (column == null)
                    continue;
                for (Tile tile : column) {
                    if (tile == null || tile.getGameObjects() == null)
                        continue;
                    for (GameObject object : tile.getGameObjects()) {
                        if (object != null)
                            ids.add(object.getId());
                    }
                }
            }
        }
        return ids;
    }

    /** The house declarations a scan may raise: read from the config, written through {@code raise}. */
    static PohDetectionService.Declarations declarations(ShortestPathConfig config, BiConsumer<String, Object> raise) {
        return new PohDetectionService.Declarations() {
            @Override
            public boolean fairyRing() {
                return config.usePohFairyRing();
            }

            @Override
            public boolean spiritTree() {
                return config.usePohSpiritTree();
            }

            @Override
            public boolean obelisk() {
                return config.usePohObelisk();
            }

            @Override
            public JewelleryBoxTier jewelleryBoxTier() {
                return config.pohJewelleryBoxTier();
            }

            @Override
            public void raise(String key, Object value) {
                raise.accept(key, value);
            }
        };
    }
}

package gps;

import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.function.Predicate;
import java.util.function.Supplier;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;

/**
 * The plugin's input listeners (plan step L32, out of the plugin class): the clear-path hotkey,
 * the focus-search hotkey (opens the GPS side panel and focuses its destination box, so a place
 * can be searched without opening the panel by hand), and the click that dismisses the overlay's
 * lingering "Arrived!" panel. The bindings are read on every press, so a config change applies
 * at once.
 */
final class PluginHotkeys {
    private final KeyListener clearPath;
    private final KeyListener focusSearch;
    private final MouseAdapter dismissArrival;

    PluginHotkeys(Supplier<Keybind> clearPathKey, Runnable onClearPath,
        Supplier<Keybind> focusSearchKey, Runnable onFocusSearch, Predicate<Point> dismissArrivalAt) {
        this.clearPath = hotkey(clearPathKey, onClearPath);
        this.focusSearch = hotkey(focusSearchKey, onFocusSearch);
        this.dismissArrival = new MouseAdapter() {
            @Override
            public MouseEvent mousePressed(MouseEvent event) {
                if (dismissArrivalAt.test(event.getPoint()))
                    event.consume();
                return event;
            }
        };
    }

    private static KeyListener hotkey(Supplier<Keybind> key, Runnable action) {
        return new KeyListener() {
            @Override
            public void keyTyped(KeyEvent e) {
            }

            @Override
            public void keyPressed(KeyEvent e) {
                if (key.get().matches(e))
                    action.run();
            }

            @Override
            public void keyReleased(KeyEvent e) {
            }
        };
    }

    void register(KeyManager keys, MouseManager mouse) {
        keys.registerKeyListener(clearPath);
        keys.registerKeyListener(focusSearch);
        mouse.registerMouseListener(dismissArrival);
    }

    void unregister(KeyManager keys, MouseManager mouse) {
        keys.unregisterKeyListener(clearPath);
        keys.unregisterKeyListener(focusSearch);
        mouse.unregisterMouseListener(dismissArrival);
    }

    KeyListener clearPath() {
        return clearPath;
    }

    KeyListener focusSearch() {
        return focusSearch;
    }

    MouseAdapter dismissArrival() {
        return dismissArrival;
    }
}

package gps;

import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * The plugin-message integration (plan step L31, out of the plugin class). Other plugins set or
 * clear the GPS destination, with config overrides, and hear the displayed route's transports
 * back. GPS answers on its own namespace and on Shortest Path's legacy one: Quest Helper and
 * others drive the pathfinder through that channel (set path/target, config overrides) and
 * listen for its broadcasts, and GPS supersedes Shortest Path, so inbound messages are accepted
 * on either and broadcasts go out on both (no listener subscribes to both today, so nothing
 * double-processes; drop the legacy channel only if that ever changes). Decoding lives in
 * {@link PluginMessageCodec}; this is the flow: which start, which ends, whether the journey
 * re-arms.
 */
final class PluginMessageBridge {
    private final ShortestPathPlugin plugin;
    // A supplier: the plugin builds the bridge at field initialisation, before injection.
    private final Supplier<EventBus> eventBus;

    PluginMessageBridge(ShortestPathPlugin plugin, Supplier<EventBus> eventBus) {
        this.plugin = plugin;
        this.eventBus = eventBus;
    }

    /** An inbound message on either namespace: a path request or a clear. */
    void receive(PluginMessage event) {
        if (!PluginMessageCodec.isOurs(event.getNamespace()))
            return;
        String action = event.getName();
        if (PluginMessageCodec.ACTION_PATH.equals(action)) {
            Map<String, Object> data = event.getData();
            Map<String, Object> overrides = PluginMessageCodec.configOverrideOf(data);
            if (!overrides.isEmpty())
                plugin.applyConfigOverrides(overrides);
            PluginMessageCodec.PathRequest request = PluginMessageCodec.parsePath(data);
            if (request == null)
                return;
            int start = request.start;
            if (start == WorldPointUtil.UNDEFINED) {
                start = plugin.getPlayerLocation();
                if (start == WorldPointUtil.UNDEFINED)
                    return;
            }
            // Attribute the destination for the GPS header (a "source" the sender chose, else
            // all we can say is that a plugin asked for it).
            plugin.setTargetSource(request.source);
            boolean useOld = request.targets.isEmpty() && plugin.hasPathTargets();
            Set<Integer> ends;
            if (useOld)
                ends = new HashSet<>(plugin.getPathTargets());
            else {
                // A NEW destination from another plugin bypasses the manual target path, so the
                // journey timer is armed here too; otherwise the arrival time would carry over from
                // whatever destination was last set. Reusing the previous target keeps the running
                // journey.
                plugin.armJourney();
                // A new destination replaces a bank trip like any other change.
                plugin.forgetBankTrip();
                // An NPC's or object's own tile expands like a map pin; a transport origin among
                // the expansion is the interactable side (see Destinations.externalTargets).
                PathfinderConfig pathfinderConfig = plugin.getPathfinderConfig();
                ends = Destinations.externalTargets(request.targets,
                    pathfinderConfig != null ? pathfinderConfig.getMap() : null,
                    pathfinderConfig != null ? pathfinderConfig::isTransportOrigin : null);
            }
            plugin.setDestination(start, ends, useOld);
        }
        else if (PluginMessageCodec.ACTION_CLEAR.equals(action)) {
            plugin.clearConfigOverrides();
            plugin.clearPinnedTarget();
        }
    }

    /**
     * Publishes the displayed route's transports to other plugins (the {@code postTransports}
     * integration) on both namespaces. Called when the displayed route settles: the displayed
     * route is what the player actually follows.
     */
    void postTransports() {
        if (!plugin.hasPathTargets()
            || !ConfigOverrides.override("postTransports", plugin.getGpsConfig().postTransports())) {
            return;
        }
        List<PathStep> currentPath = plugin.getDisplayPath();
        if (currentPath.isEmpty())
            return;
        Map<String, Object> data = PluginMessageCodec.encodeTransports(currentPath, plugin::transportsForEdge);
        EventBus bus = eventBus.get();
        bus.post(new PluginMessage(PluginMessageCodec.NAMESPACE, PluginMessageCodec.ACTION_TRANSPORTS, data));
        bus.post(new PluginMessage(PluginMessageCodec.NAMESPACE_LEGACY, PluginMessageCodec.ACTION_TRANSPORTS, data));
    }
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import net.runelite.api.coords.WorldPoint;

/**
 * The plugin-message wire format (plan step L8, out of the plugin class): what other plugins
 * send GPS ("path" with a start, a target or targets, an optional config override and an optional
 * source; "clear") and what GPS publishes back (the displayed route's transports). Pure parsing
 * and encoding; the plugin keeps the actions. Both the current namespace and the pre-fork one
 * are honoured so older integrations keep working.
 */
final class PluginMessageCodec {
    static final String NAMESPACE = "gps";
    static final String NAMESPACE_LEGACY = "shortestpath";
    static final String ACTION_PATH = "path";
    static final String ACTION_CLEAR = "clear";
    static final String ACTION_TRANSPORTS = "transports";
    static final String KEY_START = "start";
    static final String KEY_TARGET = "target";
    static final String KEY_CONFIG_OVERRIDE = "config";
    static final String KEY_SOURCE = "source";
    /** PluginMessage does not identify its sender; this is all GPS can say without a "source". */
    static final String DEFAULT_SOURCE = "another plugin";

    /** A parsed "path" request. */
    static final class PathRequest {
        /** The packed start, or {@link WorldPointUtil#UNDEFINED} for "where the player stands". */
        final int start;
        /** The packed targets; empty means "keep the current destination". */
        final Set<Integer> targets;
        /** The attribution shown in the GPS header. */
        final String source;

        PathRequest(int start, Set<Integer> targets, String source) {
            this.start = start;
            this.targets = targets;
            this.source = source;
        }
    }

    private PluginMessageCodec() {
    }

    static boolean isOurs(String namespace) {
        return NAMESPACE.equals(namespace) || NAMESPACE_LEGACY.equals(namespace);
    }

    /** The config override carried by the message, or an empty map when there is none. */
    @SuppressWarnings("unchecked")
    static Map<String, Object> configOverrideOf(Map<String, Object> data) {
        Object override = data.get(KEY_CONFIG_OVERRIDE);
        return override instanceof Map<?, ?> ? (Map<String, Object>) override : Map.of();
    }

    /**
     * Parses a "path" request. Null when the message carries neither a start nor a target (an
     * override-only message), or a target that is not a world point (an integer that is the
     * undefined sentinel, or a set holding one): the request is dropped whole, never half-applied.
     * A target of an unknown type counts as no target.
     */
    static PathRequest parsePath(Map<String, Object> data) {
        Object objStart = data.get(KEY_START);
        Object objTarget = data.get(KEY_TARGET);
        if (objStart == null && objTarget == null)
            return null;
        int start = objStart instanceof WorldPoint ? WorldPointUtil.packWorldPoint((WorldPoint) objStart)
            : objStart instanceof Integer ? (Integer) objStart : WorldPointUtil.UNDEFINED;

        Set<Integer> targets = new HashSet<>();
        if (objTarget instanceof Set<?>) {
            for (Object member : (Set<?>) objTarget) {
                int packed = packed(member);
                if (packed == WorldPointUtil.UNDEFINED)
                    return null;
                targets.add(packed);
            }
        }
        else if (objTarget instanceof Integer || objTarget instanceof WorldPoint) {
            int packed = packed(objTarget);
            if (packed == WorldPointUtil.UNDEFINED)
                return null;
            targets.add(packed);
        }

        Object objSource = data.get(KEY_SOURCE);
        String source = objSource instanceof String && !((String) objSource).isEmpty()
            ? (String) objSource : DEFAULT_SOURCE;
        return new PathRequest(start, targets, source);
    }

    private static int packed(Object value) {
        if (value instanceof Integer)
            return (Integer) value;
        if (value instanceof WorldPoint)
            return WorldPointUtil.packWorldPoint((WorldPoint) value);
        return WorldPointUtil.UNDEFINED;
    }

    /**
     * The "transports" payload for a displayed path: one entry per transport edge, as parallel
     * lists of origins, destinations, object infos and display infos (the shape older consumers
     * expect). {@code transportsForEdge} resolves the transports a path edge rides.
     */
    static Map<String, Object> encodeTransports(List<PathStep> path,
        BiFunction<PathStep, PathStep, ? extends Iterable<Transport>> transportsForEdge) {
        List<WorldPoint> origins = new ArrayList<>();
        List<WorldPoint> destinations = new ArrayList<>();
        List<String> objectInfos = new ArrayList<>();
        List<String> displayInfos = new ArrayList<>();
        for (int i = 1; i < path.size(); i++) {
            PathStep from = path.get(i - 1);
            PathStep to = path.get(i);
            for (Transport transport : transportsForEdge.apply(from, to)) {
                origins.add(WorldPointUtil.unpackWorldPoint(from.getPackedPosition()));
                destinations.add(WorldPointUtil.unpackWorldPoint(to.getPackedPosition()));
                objectInfos.add(transport.getObjectInfo());
                displayInfos.add(transport.getDisplayInfo());
            }
        }
        Map<String, Object> data = new HashMap<>();
        data.put("origin", origins);
        data.put("destination", destinations);
        data.put("objectInfo", objectInfos);
        data.put("displayInfo", displayInfos);
        return data;
    }
}

package gps;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Smart house-furniture detection (plan step L11, out of the plugin class). While the player is
 * inside their house, the loaded scene is scanned for the furniture GPS can recognise (jewellery
 * box, fairy ring, spirit tree, obelisk) and the matching declarations are turned ON, never off,
 * so detection can only add routes, never silently drop one. Being inside is judged by two
 * independent signals (single-signal attempts failed in the field): the instance's template
 * regions are house regions, or recognised house furniture spawned in this scene. The scan
 * repeats each tick until something is found (the scene can still be populating on the entry
 * tick), capped so a bare house does not rescan forever; leaving the house or leaving building
 * mode re-arms it. The result persists per character so the next session starts scanned.
 */
@Slf4j
final class PohDetectionService {
    /** RSProfile-scoped: the last scan's furniture (see PohScanner.encode); present = scanned. */
    static final String CONFIG_KEY_POH_FURNITURE = "pohFurniture";
    /** Bounds the "scene still loading" retries. */
    static final int MAX_ATTEMPTS = 6;

    /** What the scan reads from the loaded scene. */
    interface Scene {
        boolean isHouse();

        boolean isInstance();

        String describeChunks();

        Set<Integer> objectIds();
    }

    /** The house declarations a scan may raise (a feature on, a higher jewellery tier), never lower. */
    interface Declarations {
        boolean fairyRing();

        boolean spiritTree();

        boolean obelisk();

        JewelleryBoxTier jewelleryBoxTier();

        void raise(String key, Object value);
    }

    private final Supplier<Scene> scene;
    private final BooleanSupplier buildingMode;
    private final BooleanSupplier smartDetect;
    private final Declarations declarations;
    private final ConfigManager configManager;
    private final String configGroup;
    private final Runnable onChanged;

    private volatile boolean scanned;
    private volatile PohScanner.Detected detected;
    // Reset when the player leaves the house, so the next visit re-scans (catching new furniture).
    private boolean foundThisVisit;
    private int attempts;
    // Recognised furniture ids seen spawning in the current scene: proof of being in a house.
    private final Set<Integer> spawned = new HashSet<>();
    // One decoded chunk dump per scene when an instance is judged NOT a house.
    private boolean chunksLogged;
    // Tracks building mode so leaving it re-arms the scan.
    private boolean building;

    PohDetectionService(Supplier<Scene> scene, BooleanSupplier buildingMode, BooleanSupplier smartDetect,
        Declarations declarations, ConfigManager configManager, String configGroup, Runnable onChanged) {
        this.scene = scene;
        this.buildingMode = buildingMode;
        this.smartDetect = smartDetect;
        this.declarations = declarations;
        this.configManager = configManager;
        this.configGroup = configGroup;
        this.onChanged = onChanged;
    }

    /** Whether the house has been scanned (this session or restored from the last). */
    boolean isScanned() {
        return scanned;
    }

    PohScanner.Detected detected() {
        return detected;
    }

    /** The furniture the last scan recognised, as display names (empty until scanned). */
    List<String> detectedNames() {
        PohScanner.Detected found = detected;
        if (found == null)
            return List.of();
        List<String> names = new ArrayList<>();
        if (found.jewelleryBox != JewelleryBoxTier.NONE)
            names.add(found.jewelleryBox + " jewellery box");
        if (found.fairyRing)
            names.add("Fairy ring");
        if (found.spiritTree)
            names.add("Spirit tree");
        if (found.obelisk)
            names.add("Obelisk");
        return names;
    }

    /** A scene rebuild: the spawn evidence belonged to the old scene; the chunk-dump log re-arms. */
    void onSceneLoading() {
        spawned.clear();
        chunksLogged = false;
    }

    /** Logged out: the next character starts from its own snapshot. */
    void reset() {
        scanned = false;
        detected = null;
        foundThisVisit = false;
        attempts = 0;
        spawned.clear();
    }

    /** A game object spawned: recognised house furniture is unambiguous in-house evidence. */
    void furnitureSpawned(int objectId) {
        if (PohScanner.isRecognised(objectId) && spawned.add(objectId)) {
            log.debug("[poh] recognised furniture spawned: {}", objectId);
        }
    }

    /** Restores the persisted scan when none has run this session. */
    void restore() {
        if (scanned)
            return;
        PohScanner.Detected stored = PohScanner.decode(
            configManager.getRSProfileConfiguration(configGroup, CONFIG_KEY_POH_FURNITURE));
        if (stored != null) {
            detected = stored;
            scanned = true;
        }
    }

    /** Client thread, once per game tick. */
    void onTick() {
        Scene current = scene.get();
        boolean sceneIsHouse = current.isHouse();
        boolean inside = sceneIsHouse || !spawned.isEmpty();
        if (!inside) {
            // Diagnosability: when an instance is judged not-a-house, log its decoded template
            // chunks once per scene, so a missed house shows in the client log.
            if (!chunksLogged && log.isDebugEnabled() && current.isInstance()) {
                chunksLogged = true;
                log.debug("[poh] instance not judged a house; template chunks: {}", current.describeChunks());
            }
            foundThisVisit = false;
            attempts = 0;
            return;
        }
        // Leaving building mode re-arms the scan: furniture built this visit gets detected without
        // exiting the house.
        boolean buildingNow = buildingMode.getAsBoolean();
        if (building && !buildingNow) {
            foundThisVisit = false;
            attempts = 0;
        }
        building = buildingNow;
        if (!smartDetect.getAsBoolean() || foundThisVisit || attempts >= MAX_ATTEMPTS)
            return;
        attempts++;
        log.debug("[poh] scan attempt {} (sceneIsHouse={}, spawned={})", attempts, sceneIsHouse, spawned);
        scan(current);
        foundThisVisit = detected != null && detected.any();
    }

    private void scan(Scene current) {
        Set<Integer> ids = new HashSet<>(current.objectIds());
        // Spawn-event evidence joins the tile scan: authoritative even if the tile walk missed it.
        ids.addAll(spawned);
        PohScanner.Detected found = PohScanner.detect(ids);
        log.debug("[poh] scanned {} object ids, detected: {}", ids.size(), PohScanner.encode(found));
        boolean changed = !scanned || !found.sameAs(detected);
        scanned = true;
        detected = found;
        if (!changed) {
            return; // nothing new this scan: do not churn the config or the panel
        }
        // Persist per character, so next session's panel starts in the "scanned" state.
        configManager.setRSProfileConfiguration(configGroup, CONFIG_KEY_POH_FURNITURE, PohScanner.encode(found));
        // Only ever raise declarations (turn a feature on, raise the jewellery tier): a partial
        // scene load that missed a piece can never wipe an existing declaration.
        if (found.fairyRing && !declarations.fairyRing())
            declarations.raise("usePohFairyRing", true);
        if (found.spiritTree && !declarations.spiritTree())
            declarations.raise("usePohSpiritTree", true);
        if (found.obelisk && !declarations.obelisk())
            declarations.raise("usePohObelisk", true);
        if (found.jewelleryBox.ordinal() > declarations.jewelleryBoxTier().ordinal())
            declarations.raise("pohJewelleryBoxTier", found.jewelleryBox);
        if (onChanged != null)
            onChanged.run();
    }
}

package gps;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ObjectID;

/**
 * Maps the furniture object ids seen in a scanned player-owned house to the config declarations
 * they imply. Pure logic over object ids (the plugin supplies them from the live scene), so the
 * mapping is unit-testable.
 * <p>
 * Only furniture with an EXACT 1:1 config mapping is auto-detected — the jewellery box (its tier),
 * fairy ring, spirit tree and obelisk. The "Teleport portals & nexus" and "Mounted items" toggles
 * each bundle several furniture pieces, some with no stable object id (the portal nexus and the
 * functional glory/Xeric's/digsite mounts), so auto-enabling them would claim furniture GPS can't
 * verify; those stay manual.
 */
public final class PohScanner {
    private PohScanner() {
    }

    /** What a house scan found: the present 1:1 features, and the jewellery-box tier. */
    public static final class Detected {
        final boolean fairyRing;
        final boolean spiritTree;
        final boolean obelisk;
        final JewelleryBoxTier jewelleryBox;

        Detected(boolean fairyRing, boolean spiritTree, boolean obelisk, JewelleryBoxTier jewelleryBox) {
            this.fairyRing = fairyRing;
            this.spiritTree = spiritTree;
            this.obelisk = obelisk;
            this.jewelleryBox = jewelleryBox;
        }

        boolean any() {
            return fairyRing || spiritTree || obelisk || jewelleryBox != JewelleryBoxTier.NONE;
        }

        boolean sameAs(Detected other) {
            return other != null
                && fairyRing == other.fairyRing
                && spiritTree == other.spiritTree
                && obelisk == other.obelisk
                && jewelleryBox == other.jewelleryBox;
        }
    }

    /**
     * Serializes a scan result for cross-session storage: the jewellery-box tier followed by the
     * present feature flags, comma-separated (e.g. {@code "ORNATE,fairyRing,obelisk"}).
     */
    public static String encode(Detected detected) {
        if (detected == null)
            return null;
        StringBuilder sb = new StringBuilder(detected.jewelleryBox.name());
        if (detected.fairyRing)
            sb.append(",fairyRing");
        if (detected.spiritTree)
            sb.append(",spiritTree");
        if (detected.obelisk)
            sb.append(",obelisk");
        return sb.toString();
    }

    /** Parses {@link #encode}'s format. Null on missing or malformed data (treated as "never scanned"). */
    public static Detected decode(String encoded) {
        if (encoded == null || encoded.isEmpty())
            return null;
        String[] parts = encoded.split(",");
        JewelleryBoxTier tier;
        try {
            tier = JewelleryBoxTier.valueOf(parts[0]);
        }
        catch (IllegalArgumentException e) {
            return null;
        }
        Set<String> flags = new HashSet<>(Arrays.asList(parts));
        return new Detected(flags.contains("fairyRing"), flags.contains("spiritTree"),
            flags.contains("obelisk"), tier);
    }

    /** Every furniture object id the scanner recognises — the spawn-event fast path filters on this. */
    private static final Set<Integer> RECOGNISED_IDS = Set.of(
        ObjectID.POH_FAIRY_RING, ObjectID.POH_FAIRY_HOUSE, ObjectID.POH_FAIRY_HOUSE_OPEN,
        ObjectID.POH_SPIRIT_TREE, ObjectID.POH_WILDERNESS_OBELISK,
        ObjectID.POH_JEWELLERY_BOX_1, ObjectID.POH_JEWELLERY_BOX_2, ObjectID.POH_JEWELLERY_BOX_3);

    /**
     * Whether this object id is POH furniture the scanner recognises. These ids only exist inside
     * player-owned houses, so one spawning is also proof the loaded scene is a house.
     */
    public static boolean isRecognised(int objectId) {
        return RECOGNISED_IDS.contains(objectId);
    }

    public static Detected detect(Set<Integer> objectIds) {
        boolean fairyRing = objectIds.contains(ObjectID.POH_FAIRY_RING)
            || objectIds.contains(ObjectID.POH_FAIRY_HOUSE)
            || objectIds.contains(ObjectID.POH_FAIRY_HOUSE_OPEN);
        boolean spiritTree = objectIds.contains(ObjectID.POH_SPIRIT_TREE);
        boolean obelisk = objectIds.contains(ObjectID.POH_WILDERNESS_OBELISK);
        // Tiers are cumulative (each includes the ones below); pick the highest built.
        JewelleryBoxTier box = JewelleryBoxTier.NONE;
        if (objectIds.contains(ObjectID.POH_JEWELLERY_BOX_3))
            box = JewelleryBoxTier.ORNATE;
        else if (objectIds.contains(ObjectID.POH_JEWELLERY_BOX_2))
            box = JewelleryBoxTier.FANCY;
        else if (objectIds.contains(ObjectID.POH_JEWELLERY_BOX_1))
            box = JewelleryBoxTier.BASIC;
        return new Detected(fairyRing, spiritTree, obelisk, box);
    }
}

package gps;

import java.util.Arrays;
import java.util.Collection;

/**
 * A lightweight hash map keyed by primitive {@code int} values using an open-addressed table with
 * linear probing.
 * <p>
 * Keys and values are stored in two parallel arrays ({@link #keys} / {@link #values}) rather than a
 * node object per entry, so the map holds only a couple of arrays regardless of how many entries it
 * contains (issue #491). A slot is occupied iff its value reference is non-null; since null values
 * are rejected, {@code int} keys including {@code 0} need no separate sentinel. When the entry count
 * reaches the configured {@linkplain #capacity load threshold} the table is rehashed into a larger
 * power-of-two array.
 * <p>
 * This implementation is intentionally minimal and tailored for the plugin's pathfinding needs:
 * <ul>
 * <li>No support for removing entries.</li>
 * <li>No iteration views (keys, values, or entry set) are exposed beyond {@link #keys()}.</li>
 * <li>Duplicate key insertion replaces the previous value, or appends collection contents when both
 * the old and new values are {@link Collection}s (best effort; falls back to replacement on
 * errors).</li>
 * </ul>
 *
 * @param <V> the value type stored for each primitive {@code int} key. Must be non-null.
 */
public class PrimitiveIntHashMap<V> {
    private static final int MINIMUM_SIZE = 8;

    // How full the map should get before growing it again. Smaller values speed up
    // lookup times at the expense of space
    private static final float DEFAULT_LOAD_FACTOR = 0.75f;
    private final float loadFactor;
    private int[] keys;
    private Object[] values;
    private int size;
    private int capacity;
    private int maxSize;
    private int mask;

    /**
     * Creates a new map with the specified initial size and the default load factor (0.75).
     *
     * @param initialSize initial expected number of elements; rounded to the next power of two
     *                    internally.
     */
    public PrimitiveIntHashMap(int initialSize) {
        this(initialSize, DEFAULT_LOAD_FACTOR);
    }

    /**
     * Creates a new map with the given initial size and load factor.
     *
     * @param initialSize initial expected number of elements; rounded up to maintain a
     *                    power-of-two capacity.
     * @param loadFactor  a value in the range {@code [0.0, 1.0]} determining when the map rehashes.
     * @throws IllegalArgumentException if {@code loadFactor} is outside the inclusive range 0..1.
     */
    public PrimitiveIntHashMap(int initialSize, float loadFactor) {
        if (loadFactor < 0.0f || loadFactor > 1.0f)
            throw new IllegalArgumentException("Load factor must be between 0 and 1");

        this.loadFactor = loadFactor;
        size = 0;
        setNewSize(initialSize);
        recreateArrays();
    }

    /**
     * A copy that shares no arrays with {@code source} (plan step N3: per-search availability
     * rebuilds are copy-on-write views of the base maps, so a copy must be two array clones and
     * nothing else).
     */
    public PrimitiveIntHashMap(PrimitiveIntHashMap<V> source) {
        this.loadFactor = source.loadFactor;
        this.size = source.size;
        this.capacity = source.capacity;
        this.maxSize = source.maxSize;
        this.mask = source.mask;
        this.keys = source.keys.clone();
        this.values = source.values.clone();
    }

    /** Callback for {@link #forEach}: one primitive key and its value, no boxing. */
    public interface IntObjConsumer<V> {
        void accept(int key, V value);
    }

    /**
     * Visits every entry without allocating (unlike {@link #keys()}). The map must not be
     * modified during the visit.
     */
    @SuppressWarnings("unchecked")
    public void forEach(IntObjConsumer<? super V> consumer) {
        for (int i = 0; i < values.length; ++i) {
            if (values[i] != null)
                consumer.accept(keys[i], (V) values[i]);
        }
    }

    /**
     * Hash function tuned for packed world point integer encodings. Mixes higher bits downward to
     * reduce clustering while remaining inexpensive.
     */
    private static int hash(int value) {
        // Full multiplicative avalanche. Linear probing is very sensitive to clustering, and packed
        // world points of nearby tiles differ only in a few low bits, so the cheap xor-shift mix used
        // previously left spatially-clustered transport origins clustered in the table too -> long
        // probe runs on the per-tile miss lookups. Fibonacci-style multiply + xorshift spreads them.
        int h = value * 0x9E3779B1;
        return h ^ (h >>> 16);
    }

    /**
     * Returns the number of key/value pairs currently stored.
     *
     * @return current entry count (always {@code >= 0}).
     */
    public int size() {
        return size;
    }

    /**
     * Returns all keys present in the map as a freshly allocated {@code int[]}.
     *
     * @return array of all keys in unspecified order; length equals {@link #size()}.
     */
    @SuppressWarnings("unused")
    public int[] keys() {
        int[] result = new int[size];
        int index = 0;
        for (int i = 0; i < values.length; ++i) {
            if (values[i] != null)
                result[index++] = keys[i];
        }
        return result;
    }

    /**
     * Retrieves the value mapped to the provided key, or {@code null} if absent.
     *
     * @param key primitive key to look up.
     * @return the mapped value, or {@code null} if the key does not exist.
     */
    public V get(int key) {
        return getOrDefault(key, null);
    }

    /**
     * Retrieves the value mapped to the provided key.
     *
     * @param key          primitive key to look up.
     * @param defaultValue value to return if the key is not present.
     * @return the mapped value, or {@code defaultValue} when absent.
     */
    @SuppressWarnings("unchecked")
    public V getOrDefault(int key, V defaultValue) {
        final int slot = findSlot(key);
        if (slot < 0)
            return defaultValue;
        return (V) values[slot];
    }

    /**
     * Associates the specified value with the given key.
     * <p>
     * If a mapping already exists and both the existing and new values implement {@link Collection},
     * the method attempts to append all elements of the new collection into the existing one. If the
     * append fails (e.g., due to incompatible element types or an unsupported operation) the existing
     * value is replaced entirely. Otherwise the existing value is simply replaced.
     *
     * @param key   primitive key to insert or update.
     * @param value non-null value to associate.
     * @param <E>   inferred element type if both values are collections.
     * @return the previous value mapped to {@code key} (if any), or {@code null} if inserting a new
     * entry.
     * @throws IllegalArgumentException if {@code value} is {@code null}.
     */
    @SuppressWarnings({"unchecked"})
    public <E> V put(int key, V value) {
        if (value == null)
            throw new IllegalArgumentException("Cannot insert a null value");

        int i = (hash(key) & 0x7FFFFFFF) & mask;
        while (values[i] != null) {
            if (keys[i] == key) {
                V previous = (V) values[i];
                if (previous instanceof Collection<?> && value instanceof Collection<?>) { // append
                    try {
                        Collection<E> prevCollection = (Collection<E>) values[i];
                        Collection<E> newCollection = (Collection<E>) value;
                        prevCollection.addAll(newCollection);
                    }
                    catch (ClassCastException | UnsupportedOperationException e) {
                        // If the collections contain incompatible types or the operation is not
                        // supported, just replace instead of append
                        values[i] = value;
                    }
                }
                else { // replace
                    values[i] = value;
                }
                return previous;
            }
            i = (i + 1) & mask;
        }

        keys[i] = key;
        values[i] = value;
        incrementSize();
        return null;
    }

    private int findSlot(int key) {
        int i = (hash(key) & 0x7FFFFFFF) & mask;
        while (values[i] != null) {
            if (keys[i] == key)
                return i;
            i = (i + 1) & mask;
        }
        return -1;
    }

    private void incrementSize() {
        size++;
        if (size >= capacity)
            rehash();
    }

    private int getNewMaxSize(int size) {
        int nextPow2 = -1 >>> Integer.numberOfLeadingZeros(size);
        if (nextPow2 >= (Integer.MAX_VALUE >>> 1))
            return (Integer.MAX_VALUE >>> 1) + 1;
        return nextPow2 + 1;
    }

    private void setNewSize(int size) {
        if (size < MINIMUM_SIZE)
            size = MINIMUM_SIZE - 1;

        maxSize = getNewMaxSize(size);
        mask = maxSize - 1;
        capacity = (int) (maxSize * loadFactor);
    }

    private void growCapacity() {
        setNewSize(maxSize);
    }

    // Grow the table then rehash all the values into it and discard the old arrays
    private void rehash() {
        growCapacity();

        final int[] oldKeys = keys;
        final Object[] oldValues = values;
        recreateArrays();

        for (int i = 0; i < oldValues.length; ++i) {
            if (oldValues[i] == null)
                continue;

            int slot = (hash(oldKeys[i]) & 0x7FFFFFFF) & mask;
            while (values[slot] != null)
                slot = (slot + 1) & mask;
            keys[slot] = oldKeys[i];
            values[slot] = oldValues[i];
        }
    }

    private void recreateArrays() {
        keys = new int[maxSize];
        values = new Object[maxSize];
    }

    /**
     * Approximate fullness of the table as a percentage of the entry count over the table length.
     *
     * @return fullness percentage in {@code [0.0, 100.0]}, or {@link Double#NaN} when the map is
     * empty.
     */
    public double calculateFullness() {
        if (size == 0)
            return Double.NaN;
        return 100.0 * (double) size / (double) maxSize;
    }

    /**
     * Removes all entries from the map. The backing arrays are retained and reused.
     */
    public void clear() {
        size = 0;
        Arrays.fill(values, null);
    }
}

package gps;

import java.util.Arrays;

/**
 * A minimal, growable list implementation for primitive {@code int} values.
 * <p>
 * This class avoids boxing overhead present in {@link java.util.List Integer}
 * collections
 * by storing values in a backing {@code int[]} that grows as needed. It
 * purposefully
 * implements only the operations required by the pathfinding logic in this
 * plugin; it is
 * <strong>not</strong> a drop‑in replacement for {@link java.util.ArrayList}.
 * <p>
 * The growth policy increases capacity by 50% (similar to {@code ArrayList})
 * when the
 * existing array is exhausted. Capacity never shrinks.
 */
public class PrimitiveIntList {
    private static final int MAX_ARRAY_SIZE = Integer.MAX_VALUE - 8;

    private int[] elementData;
    private int size;

    /**
     * Creates a new list with the specified initial capacity.
     *
     * @param initialCapacity the initial length of the backing array (must be
     *                        {@code >= 0}).
     * @param initialize      if {@code true}, the {@link #size} is set equal to
     *                        {@code initialCapacity},
     *                        effectively pre-filling the logical list with zeroes.
     *                        If {@code false},
     *                        the list is created empty.
     * @throws IllegalArgumentException if {@code initialCapacity < 0}.
     */
    public PrimitiveIntList(int initialCapacity, boolean initialize) {
        if (initialCapacity < 0)
            throw new IllegalArgumentException("Illegal capacity: " + initialCapacity);
        this.elementData = new int[initialCapacity];
        if (initialize)
            size = initialCapacity;
    }

    /**
     * Creates an empty list with the given backing array capacity.
     *
     * @param initialCapacity initial length of the internal array (must be
     *                        {@code >= 0}).
     */
    public PrimitiveIntList(int initialCapacity) {
        this(initialCapacity, false);
    }

    /**
     * Creates an empty list with a default initial capacity of 10.
     */
    public PrimitiveIntList() {
        this(10);
    }

    private static int hugeCapacity(int minCapacity) {
        if (minCapacity < 0) { // overflow
            throw new OutOfMemoryError();
        }
        return (minCapacity > MAX_ARRAY_SIZE) ? Integer.MAX_VALUE : MAX_ARRAY_SIZE;
    }

    /**
     * Ensures that the backing array can store at least {@code minCapacity}
     * elements.
     * If the current capacity is already sufficient the call is a no-op.
     *
     * @param minCapacity the desired minimum capacity (ignored if {@code <= 0}).
     */
    public void ensureCapacity(int minCapacity) {
        if (minCapacity > 0)
            ensureCapacityInternal(minCapacity);
    }

    private void ensureCapacityInternal(int minCapacity) {
        if (minCapacity - elementData.length > 0)
            grow(minCapacity);
    }

    private void grow(int minCapacity) {
        int oldCapacity = elementData.length;
        int newCapacity = oldCapacity + (oldCapacity >> 1);
        if (newCapacity - minCapacity < 0)
            newCapacity = minCapacity;
        if (newCapacity - MAX_ARRAY_SIZE > 0)
            newCapacity = hugeCapacity(minCapacity);
        elementData = Arrays.copyOf(elementData, newCapacity);
    }

    /**
     * Returns the number of elements that have been added to (or initialized in)
     * this list.
     *
     * @return current element count (always {@code >= 0}).
     */
    public int size() {
        return size;
    }

    /**
     * Indicates whether the list currently holds zero elements.
     *
     * @return {@code true} if {@link #size()} is zero; {@code false} otherwise.
     */
    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Tests whether the specified primitive value exists in the list.
     *
     * @param e the value to search for.
     * @return {@code true} if the value occurs at least once; {@code false}
     * otherwise.
     */
    public boolean contains(int e) {
        return indexOf(e) >= 0;
    }

    /**
     * Returns the index of the first occurrence of the given value, or {@code -1}
     * if absent.
     *
     * @param e the value to locate.
     * @return zero-based index of the value, or {@code -1} if not found.
     */
    public int indexOf(int e) {
        for (int i = 0; i < size; i++) {
            if (e == elementData[i])
                return i;
        }
        return -1;
    }

    /**
     * Retrieves the value at the specified index.
     *
     * @param index zero-based position of the element to return.
     * @return the value stored at {@code index}.
     * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
     */
    public int get(int index) {
        rangeCheck(index);
        return elementData[index];
    }

    /**
     * Replaces the value at the specified index.
     *
     * @param index   zero-based position of the element to overwrite.
     * @param element the new value.
     * @return the previous value stored at {@code index}.
     * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
     */
    public int set(int index, int element) {
        rangeCheck(index);
        int oldValue = elementData[index];
        elementData[index] = element;
        return oldValue;
    }

    /**
     * Appends a value to the end of the list, growing the backing array if
     * required.
     *
     * @param e value to append.
     */
    public void add(int e) {
        ensureCapacityInternal(size + 1);
        elementData[size++] = e;
    }

    /**
     * Inserts a value at the specified index, shifting subsequent elements one
     * position to the right.
     *
     * @param index   zero-based insertion point (may be equal to {@link #size()} to
     *                append).
     * @param element the value to insert.
     * @throws IndexOutOfBoundsException if {@code index < 0 || index > size}.
     */
    public void add(int index, int element) {
        rangeCheckForAdd(index);
        ensureCapacityInternal(size + 1);
        System.arraycopy(elementData, index, elementData, index + 1, size - index);
        elementData[index] = element;
        size++;
    }

    /**
     * Removes the value at the specified index and compacts the list.
     *
     * @param index zero-based index of the element to remove.
     * @return the removed value.
     * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
     */
    public int removeAt(int index) {
        rangeCheck(index);
        int oldValue = elementData[index];
        int numMoved = size - index - 1;
        if (numMoved > 0)
            System.arraycopy(elementData, index + 1, elementData, index, numMoved);
        elementData[--size] = 0;
        return oldValue;
    }

    /**
     * Removes the first occurrence of the specified value, if present.
     *
     * @param e value to remove.
     * @return {@code true} if a value was removed; {@code false} otherwise.
     */
    public boolean remove(int e) {
        for (int i = 0; i < size; i++) {
            if (e == elementData[i]) {
                fastRemove(i);
                return true;
            }
        }
        return false;
    }

    private void fastRemove(int index) {
        int numMoved = size - index - 1;
        if (numMoved > 0)
            System.arraycopy(elementData, index + 1, elementData, index, numMoved);
        elementData[--size] = 0;
    }

    /**
     * Removes all elements from the list and resets {@link #size()} to zero.
     * The backing array is retained for reuse.
     */
    public void clear() {
        for (int i = 0; i < size; i++)
            elementData[i] = 0;
        size = 0;
    }

    private void rangeCheck(int index) {
        if (index >= size)
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
    }

    private void rangeCheckForAdd(int index) {
        if (index > size || index < 0)
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
    }
}

package gps;

import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.List;
import java.util.function.Predicate;

/**
 * The one copy of the page acceptance rule (plan step L1). The exclusion chain, the seed pass and
 * the tail-diversity pass each decide whether a found route joins the page and which route makes
 * room for it; before this class each of them carried its own copy of the closeness rule, the
 * hybrid cost band with its page-fill ceiling, and the eviction loop, with small drifts between
 * the copies. Everything here is a pure function of the candidate and the page, so each rule is
 * testable on its own (see RouteAcceptanceTest); the passes keep the wiring and the logging.
 */
final class RouteAcceptance {
    // A super-cheap best route must not strangle the cost band: with the best route at cost 9 (a
    // direct teleport), best x 3 = 27 hid every teleport+short-walk combination (a 28-cost quetzal
    // whistle route) behind "more". The band prices off max(best, this), so the default band is
    // never tighter than ~100 units (~30s of travel) and still grows with every "more" press.
    static final int MIN_BEST_FOR_BAND = 35;
    // The band/cliff gates don't apply until this many routes are on the page: one direct teleport
    // far cheaper than everything else otherwise made a one-entry page with no alternatives. The
    // chain search's own sanity cap (2x the band) still bounds how far these fill routes may cost.
    static final int MIN_PAGE_ROUTES = 4;
    // Past the band a route is still shown while its cost stays within this gap (or an eighth of
    // the reference, whichever is larger) of max(band, costliest accepted route).
    static final int PAGE_FILL_MIN_GAP = 10;
    // For an unreachable target every route ends at the closest reachable area; later routes are
    // only accepted while they get equally close, within this many tiles.
    static final int CLOSEST_DISTANCE_TOLERANCE = 10;
    /** How close a same-kind teleport must land to a flight's destination to make the hop pointless. */
    private static final int SHARED_DESTINATION_RADIUS = 10;

    private RouteAcceptance() {
    }

    /** The display band: {@code max(best, MIN_BEST_FOR_BAND) * multiple}. The page must not be empty. */
    static long band(List<RouteOption> routes, int multiple) {
        return (long) Math.max(routes.get(0).getTotalCost(), MIN_BEST_FOR_BAND) * multiple;
    }

    /**
     * The page-fill acceptance ceiling: past the display band a route is still shown while its cost
     * stays within a modest gap of {@code max(band, costliest accepted route)}. Referencing the band
     * (not just the last route) matters when a cluster STARTS just past the band edge: routes at
     * 32/86 with a 105 band and the next cluster at 106: measured from 86 the gap is 20 (a stop),
     * measured from the band it is 1 (the cluster the band edge landed in). The ceiling ratchets as
     * fill routes are accepted, so it follows a dense cluster and stops at the first real cliff.
     */
    static long pageFillCeiling(int bestCost, int maxAcceptedCost, int multiple) {
        long ref = Math.max((long) Math.max(bestCost, MIN_BEST_FOR_BAND) * multiple, maxAcceptedCost);
        return ref + Math.max(PAGE_FILL_MIN_GAP, ref / 8);
    }

    /** The costliest accepted route's cost (walk-only entries included: they bound the page too). */
    static int maxAcceptedCost(List<RouteOption> routes) {
        int max = 0;
        for (RouteOption route : routes)
            max = Math.max(max, route.getTotalCost());
        return max;
    }

    /**
     * Tightens a search's cost cap to {@code best route cost * multiple} once a route is found, so
     * searches for far-worse alternatives don't flood the map. Routes are added in non-decreasing
     * cost order, so the first is the cheapest. No effect before the first route, when
     * {@code multiple <= 0} (uncapped), or when the product exceeds {@code cap}.
     */
    static int cappedByBestCost(int cap, List<RouteOption> routes, int multiple) {
        if (routes.isEmpty() || multiple <= 0)
            return cap;
        long byBest = band(routes, multiple);
        return byBest < cap ? (int) byBest : cap;
    }

    /**
     * Whether a candidate at {@code cost} lies beyond what this page shows. The hybrid band edge:
     * routes inside the display band are always accepted; past it the page keeps filling while the
     * cost stays within the page-fill ceiling, so a cost cluster straddling the band edge is shown
     * whole, but a genuine cliff still ends the page. A minimum page overrides the cliff: one
     * super-cheap route otherwise produced a single-entry page with no alternatives at all. With
     * {@code limit} the page being full past the band is a stop as well (the chain cannot evict);
     * the passes that evict pass {@link Integer#MAX_VALUE}.
     */
    static boolean beyondBand(int cost, List<RouteOption> routes, int multiple, int limit) {
        if (multiple <= 0 || routes.size() < MIN_PAGE_ROUTES || cost <= band(routes, multiple))
            return false;
        return routes.size() >= limit
            || cost > pageFillCeiling(routes.get(0).getTotalCost(), maxAcceptedCost(routes), multiple);
    }

    static boolean beyondBand(int cost, List<RouteOption> routes, int multiple) {
        return beyondBand(cost, routes, multiple, Integer.MAX_VALUE);
    }

    /**
     * Closeness. With the best route reaching the target ({@code bestRemaining == 0}) an unreached
     * result is not "the closest reachable area": it is a search truncated by the cost cap a few
     * tiles short of the goal, and showing it painted a phantom "unreachable" route. With an
     * unreachable target every route ends at the closest reachable area, and later ones are
     * accepted only while they get about as close. Before any route ({@code bestRemaining < 0})
     * nothing is too far; the caller records the first as the best.
     */
    static boolean tooFar(boolean reached, int remaining, int bestRemaining) {
        if (!reached && bestRemaining == 0)
            return true;
        return bestRemaining >= 0 && remaining > bestRemaining + CLOSEST_DISTANCE_TOLERANCE;
    }

    /**
     * The route to make room with when the page is full: the costliest one the predicate allows,
     * strictly costlier than {@code costlierThan} (pass -1 to allow any cost), never the sole
     * port-first route (the "park the boat properly" promise is evict-proof like the walk
     * baseline). -1 when nothing qualifies, in which case the candidate is dropped instead.
     */
    static int evictionIndex(List<RouteOption> routes, int costlierThan, Predicate<RouteOption> evictable) {
        int sole = solePortFirstIndex(routes);
        int evict = -1;
        int maxCost = costlierThan;
        for (int r = 0; r < routes.size(); r++) {
            RouteOption route = routes.get(r);
            if (r != sole && evictable.test(route) && route.getTotalCost() > maxCost) {
                maxCost = route.getTotalCost();
                evict = r;
            }
        }
        return evict;
    }

    /** Whether the route starts by disembarking at a port. */
    static boolean portFirst(RouteOption route) {
        List<TeleportMethod> methods = route.getMethods();
        return !methods.isEmpty()
            && TransportType.SAILING.equals(methods.get(0).getType())
            && methods.get(0).getDisplayInfo() != null
            && methods.get(0).getDisplayInfo().startsWith("Disembark");
    }

    /** The index of the only port-first route on the page, or -1 when there is none or several. */
    static int solePortFirstIndex(List<RouteOption> routes) {
        int found = -1;
        for (int r = 0; r < routes.size(); r++) {
            if (portFirst(routes.get(r))) {
                if (found >= 0)
                    return -1;
                found = r;
            }
        }
        return found;
    }

    /** Whether any shown route already starts by disembarking at a port. */
    static boolean hasPortFirstRoute(List<RouteOption> routes) {
        for (RouteOption route : routes) {
            if (portFirst(route))
                return true;
        }
        return false;
    }

    /**
     * A kept route nested inside the candidate: the candidate is a detour that ends with exactly a
     * kept route's methods (a bank trip before the same teleport chain counts only against a kept
     * route that also banks). Such a candidate adds nothing the page does not already say.
     */
    static boolean nestsAKeptRoute(List<TeleportMethod> candidate, boolean candidateViaBank,
        List<RouteOption> kept) {
        for (RouteOption route : kept) {
            List<TeleportMethod> base = route.getMethods();
            if (base.isEmpty() || candidate.size() <= base.size()
                || (candidateViaBank && !route.isViaBank())) {
                continue;
            }
            if (candidate.subList(candidate.size() - base.size(), candidate.size()).equals(base))
                return true;
        }
        return false;
    }

    /**
     * A whistle-hop variant of a direct teleport: a teleport followed by a flight of the kind that
     * shares its destinations, when a same-kind teleport in the baseline already lands within
     * {@link #SHARED_DESTINATION_RADIUS} of the flight's destination. The hop only exists because
     * the chain excluded the direct teleport, so it is filtered rather than shown.
     */
    static boolean hasRedundantTeleportHop(List<Transport> baselineTeleports, List<TeleportMethod> methods) {
        for (int i = 0; i + 1 < methods.size(); i++) {
            TeleportMethod teleport = methods.get(i);
            TeleportMethod flight = methods.get(i + 1);
            if (teleport.getType() == null || flight.getType() == null
                || !flight.getType().equals(teleport.getType().sharesDestinationsWith())) {
                continue;
            }
            for (Transport candidate : baselineTeleports) {
                if (teleport.getType().equals(candidate.getType())
                    && WorldPointUtil.distanceBetween(candidate.getDestination(), flight.getDestination())
                        <= SHARED_DESTINATION_RADIUS) {
                    return true;
                }
            }
        }
        return false;
    }
}

package gps;

import gps.pathfinder.PathfinderConfig;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;

/**
 * The alternative-routes generation (plan step L35, out of the plugin class): when a generation
 * runs (auto on a target-set change, the panel's Find routes, show more, a mode change), what it
 * runs with (the page budget, the cost band, the mode, the exclusions snapshot) and what happens
 * to its results (the effective order, the session's stream and settle, the panel push, the
 * broadcast to other plugins), plus the catalog-only refresh after an item change and the
 * panel's route pick. The plugin supplies the client-bound facts (the player's tile, the tick,
 * the game state, the round-trip wish) and the collaborators.
 */
@Slf4j
final class RouteController {
    private final ShortestPathPlugin plugin;
    private final RouteSession session;
    private final MethodExclusions exclusions;
    private final ChoiceStore choices;
    private final PluginMessageBridge messages;
    // Whether and when the catalog is re-classified after an item change (see CatalogRefresher).
    private final CatalogRefresher catalogRefresh = new CatalogRefresher();
    // The async generator; created at startup with the planning copy, null before and after.
    private AlternativeRoutesService service;
    // Which methods the alternatives consider: carried (default), carried + bank, or every teleport.
    private volatile AlternativeRoutesMode mode = AlternativeRoutesMode.OWNED_INVENTORY;
    private volatile List<TeleportMethod> catalog = new ArrayList<>();
    // Catalog methods the player cannot use in the current mode, mapped to why (the panel markers).
    private volatile Map<TeleportMethod, MethodAvailability> unavailable = Map.of();
    // Whether the GPS side panel is shown (sidebar tab selected). It no longer changes how much a
    // generation does (see routeLimitFor); opening the panel re-checks the auto-compute decision.
    private volatile boolean panelVisible;

    RouteController(ShortestPathPlugin plugin, RouteSession session, MethodExclusions exclusions,
        ChoiceStore choices, PluginMessageBridge messages) {
        this.plugin = plugin;
        this.session = session;
        this.exclusions = exclusions;
        this.choices = choices;
        this.messages = messages;
    }

    /** Startup, before the panel exists: the saved mode, the generator, the page budget. */
    void start(AlternativeRoutesService generator) {
        AlternativeRoutesMode saved = choices.loadRoutesMode();
        if (saved != null)
            mode = saved;
        service = generator;
        session.setLimit(defaultLimit());
    }

    void shutdown() {
        if (service != null) {
            service.shutdown();
            service = null;
        }
    }

    /** The generator, or null outside the plugin's lifetime. */
    AlternativeRoutesService service() {
        return service;
    }

    AlternativeRoutesMode mode() {
        return mode;
    }

    List<TeleportMethod> catalog() {
        return catalog;
    }

    Map<TeleportMethod, MethodAvailability> unavailable() {
        return unavailable;
    }

    /** Panel (EDT) entry point: routing state is client-thread owned, so hop over (invoke runs inline when already there). */
    void setMode(AlternativeRoutesMode newMode) {
        plugin.getClientThread().invoke(() -> {
            if (newMode == null || mode == newMode)
                return;
            mode = newMode;
            choices.saveRoutesMode(newMode);
            trigger(session.lastStart(), session.lastTargetsCopy());
        });
    }

    /**
     * Manually (re)computes the routes for whatever destination GPS currently has set, read live
     * from the player's position. With no target set there is nothing to route: the methods
     * catalog is marked for its debounced re-classification (see CatalogRefresher) instead of a
     * generation, which used to run, and log, on every bank close.
     */
    void recompute() {
        plugin.getClientThread().invokeLater(() -> {
            Set<Integer> targets = plugin.getPathTargets();
            if (!targets.isEmpty()) {
                int start = plugin.altStart();
                log.debug("[alt-routes] Find routes: target set, searchStart={}, target={}",
                    WorldPointUtil.unpackWorldPoint(start),
                    WorldPointUtil.unpackWorldPoint(targets.iterator().next()));
                session.setLimit(defaultLimit());
                trigger(start, new HashSet<>(targets));
            }
            else
                catalogRefresh.markDirty();
        });
    }

    /** The configured number of routes to search for per query (clamped to the service's hard cap). */
    int defaultLimit() {
        return routeLimitFor(panelVisible, ConfigOverrides.override("defaultRouteCount", plugin.getGpsConfig().defaultRouteCount()));
    }

    /**
     * The route budget a generation runs with: the SAME whether the side panel is shown or
     * hidden. A panel-hidden run used to search only the primary route (one search, a handful of
     * seeds) and found a different "best" often enough that opening the panel visibly changed
     * the overlay's route (issue #18, field reports). A full run costs tens to a few hundred
     * milliseconds more and streams its first route at the same moment, so the overlay shows that
     * one provisionally and settles once, consistently, with or without the panel. The panel
     * flag is taken only to state the rule where it is decided. Pure, unit-tested.
     */
    static int routeLimitFor(boolean panelVisible, int configured) {
        return Math.max(1, Math.min(configured, 25));
    }

    boolean canLoadMore() {
        return session.canLoadMore();
    }

    /** "Search for more routes": widens the cost band and the route budget, then regenerates. */
    void loadMore() {
        plugin.getClientThread().invoke(() -> {
            // Each poll grows both dimensions of the cap so genuinely more routes surface (see
            // RouteSession.widen): the cost band and the route-count budget, toward the service's
            // runaway backstop. A new destination resets both.
            if (session.widen(defaultLimit(), AlternativeRoutesService.MAX_ROUTES_CAP))
                trigger(session.lastStart(), session.lastTargetsCopy());
        });
    }

    /**
     * Light auto-detect, run each game tick: when GPS's destination changes (a new target set
     * manually, by Quest Helper, on reaching the previous one) compute the alternatives once.
     * Deliberately keyed on the target SET only, never on start or movement, so live path recalcs
     * cannot thrash it. If it ever misses, the panel's Find routes button forces a recompute.
     */
    void maybeAutoCompute() {
        if (service == null)
            return;
        Set<Integer> targets = plugin.getPathTargets();
        // The full route budget, panel shown or hidden (see routeLimitFor).
        int desiredLimit = defaultLimit();
        if (!RouteSession.shouldAutoCompute(targets, session.lastTargets(), session.lastLimit(), desiredLimit))
            return;
        session.setLimit(desiredLimit);
        trigger(plugin.altStart(), new HashSet<>(targets));
    }

    /**
     * The panel's sidebar tab was shown or hidden. Every generation runs with the full route
     * budget regardless (see routeLimitFor); opening the panel only re-checks the auto-compute
     * decision, so a generation that ran under a smaller budget is widened.
     */
    void setPanelVisible(boolean visible) {
        panelVisible = visible;
        if (visible)
            plugin.getClientThread().invokeLater(this::maybeAutoCompute);
    }

    /** Starts a generation for {@code targets} from {@code start}; with no target, the catalog alone streams. */
    void trigger(int start, Set<Integer> targets) {
        if (service == null)
            return;
        Set<Integer> ends = (targets == null) ? new HashSet<>() : new HashSet<>(targets);
        // The session clears the committed route for a NEW destination (so the overlay stays blank
        // until the fresh routes settle) and keeps it for the same one; the previous routes go
        // immediately (the catalog stays) and the new ones stream in as they are found.
        session.begin(start, ends);
        // Snapshot the exclusions this generation runs with, so the panel can flag the route list as
        // stale once the user toggles methods afterwards (recalculation is manual via Refresh).
        exclusions.markGenerated();
        final List<TeleportMethod> currentCatalog = catalog;
        final boolean hasTarget = !ends.isEmpty();
        ShortestPathPanel panel = plugin.panel();
        if (panel != null) {
            final Map<TeleportMethod, MethodAvailability> currentUnavailable = unavailable;
            SwingUtilities.invokeLater(() ->
                panel.displayRoutes(List.of(), currentCatalog, currentUnavailable, plugin.getUserExclusions(), true, hasTarget));
        }
        service.generate(start, ends, exclusions.live(), mode, session.limit(), session.costMultiple(),
            plugin.isRoundTripWanted(), this::onUpdate);
    }

    /** A generation's stream (partial lists as routes are found) and its settle ({@code done}). */
    void onUpdate(List<RouteOption> routes, List<TeleportMethod> newCatalog,
        Map<TeleportMethod, MethodAvailability> newUnavailable, boolean done) {
        // Priorities re-rank the list (effective ETA = cost + tier adjustments): everything
        // downstream (panel, default display pick, rematch) sees the effective order.
        final List<RouteOption> ordered = plugin.sortByEffectiveOrder(routes);
        catalog = newCatalog;
        unavailable = newUnavailable;
        if (done) {
            // The session re-matches or drops the pick and commits the overlay's route in one step
            // (see RouteSession.settle); the tracker's progress is the pick's progress.
            session.settle(ordered, service.wasMoreLikely(), AlternativeRoutesService.MAX_ROUTES_CAP,
                plugin::displayedRouteProgress);
            // The displayed route just settled: publish it to other plugins (postTransports).
            messages.postTransports();
        }
        else
            // Mid-stream updates deliberately do NOT clear a stale selection: the overlay keeps
            // drawing the picked route steadily while the new list streams in.
            session.stream(ordered);
        final boolean hasTarget = !session.lastTargets().isEmpty();
        SwingUtilities.invokeLater(() -> {
            ShortestPathPanel panel = plugin.panel();
            if (panel != null)
                panel.displayRoutes(ordered, newCatalog, newUnavailable, plugin.getUserExclusions(), !done, hasTarget);
        });
    }

    /** The panel's pick: toggles the shown route, re-arms the journey and republishes the path. */
    void select(int index) {
        plugin.getClientThread().invoke(() -> {
            // Toggle: clicking the route that is already shown hides it (RouteSession.select).
            if (session.select(index)) {
                // Picking a different path starts a new journey: time it from here, not from the
                // original destination (re-arm; the timer restarts on the next movement).
                plugin.armJourney();
                // The displayed path changed: republish it to other plugins (postTransports).
                messages.postTransports();
                refreshPanel(false);
            }
        });
    }

    /**
     * An inventory or equipment change: only the routing-relevant slice of the items dirties the
     * catalog (see CatalogRefresher); without a dependency index yet, every change does. Whether
     * the catalog became dirty.
     */
    boolean itemsChanged(PathfinderConfig pathfinderConfig, ItemContainer inventory, ItemContainer equipment) {
        if (pathfinderConfig == null) {
            catalogRefresh.markDirty();
            return true;
        }
        return catalogRefresh.noteItems(pathfinderConfig.getRoutingItemDependencies().fingerprint(inventory, equipment));
    }

    /** Whether a catalog re-classification is pending. */
    boolean isCatalogDirty() {
        return catalogRefresh.isDirty();
    }

    /** Catalog-only re-classification after an item change, when due (see CatalogRefresher); each tick. */
    void refreshCatalogIfDue() {
        if (service == null || plugin.panel() == null || !catalogRefresh.claim(plugin.getClient().getTickCount(),
            panelVisible, session.inFlight(), GameState.LOGGED_IN.equals(plugin.getClient().getGameState()))) {
            return;
        }
        service.refreshCatalog(mode, (newCatalog, newUnavailable) -> {
            catalog = newCatalog;
            unavailable = newUnavailable;
            refreshPanel(session.inFlight());
        });
    }

    /** Pushes the current routes and catalog to the panel (EDT). */
    void refreshPanel(boolean calculating) {
        final boolean hasTarget = !session.lastTargets().isEmpty();
        ShortestPathPanel panel = plugin.panel();
        if (panel != null) {
            SwingUtilities.invokeLater(() ->
                panel.displayRoutes(session.routes(), catalog, unavailable, plugin.getUserExclusions(), calculating, hasTarget));
        }
    }
}

package gps;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import lombok.Getter;
import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * Builds the "Google Maps"-style step list for a route: walking legs with their length and target,
 * "Use ..." entries for each teleport/transport method, bank detours with what to withdraw, and
 * climb steps (stairs, ladders, trapdoors). Each step records the span of path indexes it covers so
 * the overlay can track execution progress from the player's position. Built once per displayed
 * route and cached by the plugin; rendered by {@link RouteDirectionsOverlay}.
 */
final class RouteDirections {
    /**
     * Running covers 2 tiles per 0.6s game tick; estimates assume the player runs.
     */
    static final double SECONDS_PER_TICK = 0.6;

    /**
     * One direction step, the route-path index range [start, end] it spans, and its estimated
     * duration in game ticks (for wall-time ETAs).
     */
    @Getter
    static final class Step {
        private final String text;
        private final int startIndex;
        private final int endIndex;
        private final int ticks;
        // True for "Use <method>" steps: rides the overlay can interpolate progress through
        // (carpet/canoe/glider flights) rather than freezing the ETA until landing.
        private final boolean transport;
        // True for "Open <door>" steps: their edge gates progress until actually crossed —
        // straight-line proximity sees through the closed door.
        private final boolean door;
        // True for object-transport obstacles the player must click to cross (agility shortcuts,
        // stairs/ladders, ...). Like a closed door, the player can't click-walk PAST it, so the
        // path beyond it is drawn blocked until they use it. Doors carry {@link #door} instead.
        private final boolean obstacle;
        // True for the boarding half of a sailing leg: standing on the boarding tile does NOT
        // finish it — only actually being aboard (the BOARDED varbit) does, else the step
        // greyed out while the player was still on the dock.
        private final boolean embark;
        // Sub-lines rendered indented under the step's own line (the withdraw step's
        // per-item list). Empty for ordinary steps.
        private List<String> details = List.of();

        private Step(String text, int startIndex, int endIndex, int ticks) {
            this(text, startIndex, endIndex, ticks, false, false, false, false);
        }

        private Step(String text, int startIndex, int endIndex, int ticks, List<String> details) {
            this(text, startIndex, endIndex, ticks, false, false, false, false);
            this.details = details;
        }

        /** The same step with another duration (see {@link RouteDirections#alignedToPathCosts}). */
        Step withTicks(int newTicks) {
            Step copy = new Step(text, startIndex, endIndex, newTicks, transport, door, obstacle, embark);
            copy.details = details;
            return copy;
        }

        private Step(String text, int startIndex, int endIndex, int ticks, boolean transport) {
            this(text, startIndex, endIndex, ticks, transport, false, false, false);
        }

        private Step(String text, int startIndex, int endIndex, int ticks, boolean transport,
            boolean door, boolean obstacle) {
            this(text, startIndex, endIndex, ticks, transport, door, obstacle, false);
        }

        private Step(String text, int startIndex, int endIndex, int ticks, boolean transport, boolean door) {
            this(text, startIndex, endIndex, ticks, transport, door, false);
        }

        private Step(String text, int startIndex, int endIndex, int ticks,
            boolean transport, boolean door, boolean obstacle, boolean embark) {
            this.text = text;
            this.startIndex = startIndex;
            this.endIndex = endIndex;
            this.ticks = ticks;
            this.transport = transport;
            this.door = door;
            this.obstacle = obstacle;
            this.embark = embark;
        }

        /** Whether the player must interact with something to cross this edge (door or shortcut). */
        boolean gatesWalk() {
            return door || obstacle;
        }
    }

    private RouteDirections() {
    }

    /**
     * The steps for the route, in travel order. Method steps come from the route's own recorded edge
     * indexes — the route was computed with the planning config's availability, so re-deriving its
     * methods against the main config would silently miss some (and count a missed teleport's jump as
     * a thousand-tile walking leg). Only climbs are matched against the main config: they're plain
     * always-enabled transports, present in any mode.
     */
    static List<Step> build(ShortestPathPlugin plugin, RouteOption route) {
        List<Step> steps = new ArrayList<>();
        List<PathStep> path = route.getPath();
        if (path == null || path.size() < 2)
            return steps;
        // When the target can't be reached, the route stops at the closest tile — the final leg walks
        // "as close as possible", not "to the destination", so the overlay doesn't imply arrival.
        boolean reaches = plugin.routeReachesTarget(route);

        // Edge index -> position in the route's method list.
        List<Integer> methodEdges = route.getMethodEdgeIndexes();
        int nextMethod = 0;

        int walk = 0;
        int legStart = 0;
        boolean banked = false;
        for (int i = 1; i < path.size(); i++) {
            PathStep from = path.get(i - 1);
            PathStep to = path.get(i);

            // The tile where the path first enters the banked state is the bank it withdraws at —
            // but only worth a step when the route actually needs the bank for a method's item.
            if (!banked && to.isBankVisited()) {
                banked = true;
                if (route.isViaBank()) {
                    steps.add(new Step(walkText("the bank"), legStart, i, walkTicks(walk)));
                    walk = 0;
                    legStart = i;
                    steps.add(withdrawStep(plugin, route, path, i));
                }
            }

            if (nextMethod < methodEdges.size() && methodEdges.get(nextMethod) == i) {
                flushWalk(steps, walk, legStart, i - 1);
                walk = 0;
                TeleportMethod method = route.getMethods().get(nextMethod);
                int duration = route.getMethodDurations().get(nextMethod);
                if (TransportType.SAILING.equals(method.getType()))
                    addSailingSteps(steps, method, duration, i);
                else {
                    steps.add(new Step(methodText(method) + fareText(plugin, from, to),
                        i - 1, i, duration, true));
                }
                nextMethod++;
                legStart = i;
                continue;
            }

            Transport object = findObjectTransport(plugin, from, to);
            ClosedDoors.Door door = object == null
                ? ClosedDoors.doorBetween(from.getPackedPosition(), to.getPackedPosition())
                : null;
            if (object != null) {
                // Any transport with menu-style object info becomes its own step: climbs
                // ("Climb-up Staircase"), agility shortcuts ("Walk-across Log balance"),
                // mapped doors ("Open Door" — flagged so the door progress gate applies), ...
                flushWalk(steps, walk, legStart, i - 1);
                walk = 0;
                String text = objectText(object) + fareOf(plugin, object);
                boolean isDoor = isDoorway(object);
                // Advisory note from the transport data ("fire arrow needed", "can fail") — the
                // route is offered regardless; the player just gets told what to expect.
                if (object.getNote() != null)
                    text += " — " + object.getNote();
                // Doors carry the door flag (closed-state gated); every other object transport
                // (climbs, agility shortcuts, tunnels) is an obstacle the player must click to
                // cross, so the path beyond it is blocked until used.
                steps.add(new Step(text, i - 1, i, Math.max(1, object.getDuration()),
                    false, isDoor, !isDoor));
                legStart = i;
            }
            else if (door != null) {
                // A doorway splits the walking leg: walk up to the door, open it, walk on. Whether
                // it will actually be closed is live scene state the world overlay handles; as a
                // step it is a stable landmark either way. Billed at the same cost the search
                // charged for the crossing, so the step total and the card ETA agree.
                flushWalk(steps, walk, legStart, i - 1);
                walk = 0;
                steps.add(new Step("Open " + door.name, i - 1, i, ClosedDoors.COST_TICKS, false, true));
                legStart = i;
            }
            else {
                // Plain walking, or a small connector (shortcut, dungeon entrance). Cap the
                // contribution so an unrecognised transport edge can never inflate the leg with its
                // coordinate distance.
                int distance = WorldPointUtil.distanceBetween(from.getPackedPosition(), to.getPackedPosition());
                walk += Math.max(1, Math.min(distance, 10));
            }
        }
        if (walk > 0) {
            steps.add(new Step(reaches ? walkText("the destination") : "Walk as close as possible (can't reach the target)",
                legStart, path.size() - 1, walkTicks(walk)));
        }
        return alignedToPathCosts(steps, path);
    }

    /**
     * Re-derives each step's duration from the path's cumulative search costs when the path
     * carries them (plan step N9): a step spanning [start, end] takes {@code (cost[end] -
     * cost[start]) / 2} ticks, so the per-step times, the overlay's ETA and the route card all
     * read the one number the search computed. Paths without costs (hand-built, older captures)
     * keep the estimates above.
     */
    private static List<Step> alignedToPathCosts(List<Step> steps, List<PathStep> path) {
        if (path.isEmpty())
            return steps;
        for (PathStep step : path) {
            if (step.getCost() == PathStep.UNKNOWN_COST)
                return steps;
        }
        List<Step> aligned = new ArrayList<>(steps.size());
        for (Step step : steps) {
            int start = Math.max(0, Math.min(step.getStartIndex(), path.size() - 1));
            int end = Math.max(start, Math.min(step.getEndIndex(), path.size() - 1));
            int units = Math.max(0, path.get(end).getCost() - path.get(start).getCost());
            aligned.add(step.withTicks((int) Math.round(units / (double) gps.pathfinder.CostUnits.UNITS_PER_TICK)));
        }
        return aligned;
    }

    /**
     * The bank-withdrawal step's duration in game ticks: the configured bank-pickup cost (in cost
     * units) converted to ticks — the SAME value the search charges and the route card's ETA adds,
     * so the overlay total and the card ETA agree on the bank detour. A negative modifier is a
     * "favour banking" preference, not negative time, so it's clamped out.
     */
    static int bankWithdrawTicks(int costBankPickup) {
        return (int) Math.round(Math.max(0, costBankPickup) / (double) gps.pathfinder.CostUnits.UNITS_PER_TICK);
    }

    /**
     * Game ticks to cover a walking leg, assuming the player runs (2 tiles per tick).
     */
    private static int walkTicks(int tiles) {
        return (tiles + 1) / 2;
    }

    private static final int COINS_ITEM_ID = 995;

    /**
     * " — N gp fare" when the edge's transport charges coins (Barnaby's ship, charters,
     * travel carts), else "". A paid crossing looked free in the step list — the fare is a
     * real cost the player must carry, and the card's item chips don't say WHICH step
     * spends it.
     */
    private static String fareText(ShortestPathPlugin plugin, PathStep from, PathStep to) {
        int fare = Integer.MAX_VALUE;
        // UNFILTERED edge rows: the route already committed to this edge, and the
        // availability-filtered sets drop a row whose fare is banked (capture 205518).
        for (Transport transport : plugin.getPathfinderConfig()
            .transportsOnEdge(from.getPackedPosition(), to.getPackedPosition())) {
            int coins = coinsOf(plugin, transport);
            if (coins > 0)
                fare = Math.min(fare, coins);
        }
        return fare == Integer.MAX_VALUE ? "" : " — " + fare + " gp fare";
    }

    private static String fareOf(ShortestPathPlugin plugin, Transport transport) {
        int coins = coinsOf(plugin, transport);
        return coins > 0 ? " — " + coins + " gp fare" : "";
    }

    /** The fare the player actually pays: the listed coins scaled by the charter discount. */
    private static int coinsOf(ShortestPathPlugin plugin, Transport transport) {
        int base = coinsOf(transport);
        if (base <= 0 || plugin == null || plugin.getPathfinderConfig() == null)
            return base;
        // A mocked config answers 0: treat anything outside 1..99 as no discount.
        return PathfinderConfig.scaleCoins(base, plugin.getPathfinderConfig().farePercent(transport));
    }

    private static int coinsOf(Transport transport) {
        if (transport.getItemRequirements() == null)
            return 0;
        for (gps.transport.requirement.ItemRequirement requirement
            : transport.getItemRequirements().getRequirements()) {
            for (int itemId : requirement.getItemIds()) {
                if (itemId == COINS_ITEM_ID)
                    return requirement.getQuantity();
            }
        }
        return 0;
    }

    private static Transport findObjectTransport(ShortestPathPlugin plugin, PathStep from, PathStep to) {
        Set<Transport> candidates = plugin.transportsForEdge(from, to);
        for (Transport transport : candidates) {
            if (objectText(transport) != null)
                return transport;
        }
        return null;
    }

    private static void flushWalk(List<Step> steps, int walk, int legStart, int endIndex) {
        if (walk <= 0)
            return;
        // No coordinates or tile counts: they mean nothing to the player. The leg's endpoint is
        // marked in the world instead (section marker / destination pulse), the next step names
        // what's there, and the time column already sizes the leg.
        steps.add(new Step("Walk", legStart, endIndex, walkTicks(walk)));
    }

    /**
     * A sailing leg reads like the player experiences it: board the boat at a NAMED port, then
     * sail — with the fixed boarding overhead and the travel time split the way Walk legs get
     * their own time. The display info carries "Sailing: {origin} \u2192 {destination}"; when
     * the arrow is absent (older data), the leg stays one step.
     */
    private static void addSailingSteps(List<Step> steps, TeleportMethod method, int duration, int i) {
        String label = method.getDisplayInfo() == null ? "" : method.getDisplayInfo();
        String trimmed = label.startsWith("Sailing: ") ? label.substring(9) : label;
        String origin;
        String destination;
        int arrow = trimmed.indexOf(" \u2192 ");
        if (arrow >= 0) {
            // Port-to-port rows: "Sailing: {origin} \u2192 {destination}".
            origin = trimmed.substring(0, arrow);
            destination = trimmed.substring(arrow + 3);
        }
        else if (trimmed.startsWith("Embark at ")) {
            // Synthetic water-pin legs: the card just says where to board; the sail step
            // mirrors the walk phrasing.
            origin = trimmed.substring(10);
            destination = "the destination";
        }
        else {
            steps.add(new Step("\u26F5 " + (trimmed.isEmpty() ? "Sail" : trimmed), i - 1, i,
                duration, true));
            return;
        }
        int sailTicks = Math.max(1, duration - SailingSea.OVERHEAD_TICKS);
        steps.add(new Step("\u26F5 Embark at " + origin, i - 1, i - 1,
            Math.max(0, duration - sailTicks), true, false, false, true));
        steps.add(new Step("Sail to " + destination, i - 1, i, sailTicks, true));
    }

    private static String walkText(String target) {
        return "Walk to " + target;
    }

    /**
     * The instruction for a method step. Fairy rings get their own glyph and phrasing: the raw
     * data label is a spaced dial code ("A I Q", chained hops "A I R - D L R"), which reads
     * better compacted the way players write them ("AIQ", "AIR → DLR"); named destinations
     * (ZANARIS) are shouted in the data and get title-cased. Everything else keeps "Use X".
     */
    static String methodText(TeleportMethod method) {
        if (TransportType.FAIRY_RING.equals(method.getType()) && method.getDisplayInfo() != null)
            // The mushroom renders via the JVM's system-font fallback (verified in-game on
            // Windows, monochrome); if other platforms report missing-glyph boxes, drop it.
            return "🍄 Fairy ring to " + fairyRingLabel(method.getDisplayInfo());
        // Network methods (balloons, minecarts, mountain guides, ...) phrase themselves as
        // "<Vehicle> to X" — their bare data label is a destination, so "Use Varrock" read as
        // nonsense. Everything else keeps "Use X".
        String routeLabel = method.routeLabel();
        return routeLabel.equals(method.label()) ? "Use " + method.label() : routeLabel;
    }

    private static String fairyRingLabel(String displayInfo) {
        StringBuilder sb = new StringBuilder();
        for (String hop : displayInfo.split(" - ")) {
            if (sb.length() > 0)
                sb.append(" → ");
            String code = hop.replace(" ", "");
            if (code.length() > 3)
                code = code.charAt(0) + code.substring(1).toLowerCase(Locale.ROOT);
            sb.append(code);
        }
        return sb.toString();
    }

    /**
     * The withdraw step as a titled per-item LIST — one indented line per bank method,
     * fares attributed ("30 gp — Brimhaven fare"), plain items by name — resolved from the
     * UNFILTERED edge rows like {@link #fareText} (availability drops rows whose
     * requirement is banked, which is every row this step exists for). Falls back to the
     * single-line text when nothing resolves.
     */
    private static Step withdrawStep(ShortestPathPlugin plugin, RouteOption route,
        List<PathStep> path, int pathIndex) {
        List<String> details = pickupLines(plugin, route);
        int ticks = bankWithdrawTicks(plugin.getPathfinderConfig().getBankPickupCost());
        if (details.isEmpty())
            return new Step(withdrawText(plugin, route, path, pathIndex), pathIndex, pathIndex, ticks);
        return new Step("Withdraw item(s):", pathIndex, pathIndex, ticks, details);
    }

    /**
     * All pickup lines of a via-bank route, in method order — shared by the withdraw step
     * and the panel's bank tooltips.
     */
    static List<String> pickupLines(ShortestPathPlugin plugin, RouteOption route) {
        List<String> details = new ArrayList<>();
        // Connectors first: they are the ones nobody would otherwise know about.
        for (Transport connector : route.getBankTransports()) {
            String label = objectText(connector);
            String line = pickupLine(plugin, List.of(connector), label == null ? "the way" : label);
            if (line != null && !details.contains(line))
                details.add(line);
        }
        for (TeleportMethod method : route.getMethods()) {
            if (!route.getBankMethods().contains(method))
                continue;
            String line = pickupLineFor(plugin, route, method);
            if (line != null && !details.contains(line))
                details.add(line);
        }
        // The fairy-ring staff is a SPECIAL requirement (hasRequiredItems' Dramen/Lunar case),
        // carried on no ring row — so the loops above name nothing for a bank-gated ring and
        // the withdraw step listed everything BUT the staff (field capture 20260824-183101:
        // "Withdraw: Salve graveyard tablet" while the ring needed the banked Dramen staff).
        TeleportMethod bankedRing = null;
        for (TeleportMethod method : route.getBankMethods()) {
            if (TransportType.FAIRY_RING.equals(method.getType())) {
                bankedRing = method;
                break;
            }
        }
        for (int i = 0; bankedRing == null && i < route.getBankTransports().size(); i++) {
            if (TransportType.FAIRY_RING.equals(route.getBankTransports().get(i).getType()))
                bankedRing = route.getBankTransports().get(i).method();
        }
        if (bankedRing != null && plugin.getClient()
            .getVarbitValue(net.runelite.api.gameval.VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1) {
            String line = bankedStaffName(plugin) + " — " + joinLabels(java.util.Set.of(bankedRing));
            if (!details.contains(line))
                details.add(line);
        }
        return details;
    }

    /** The banked Dramen/Lunar staff's proper name, or the generic pair when unresolvable. */
    private static String bankedStaffName(ShortestPathPlugin plugin) {
        net.runelite.api.Item[] bank = plugin.getPathfinderConfig().getBankSnapshot();
        if (bank != null) {
            for (int staffId : ItemVariations.DRAMEN_STAFF.getIds()) {
                for (net.runelite.api.Item item : bank) {
                    if (item.getId() == staffId && item.getQuantity() > 0) {
                        String name = plugin.getClient().getItemDefinition(staffId).getName();
                        if (name != null && !name.isEmpty() && !"null".equals(name))
                            return name;
                    }
                }
            }
        }
        return "Dramen or Lunar staff";
    }

    /** The pickup line for ONE of a route's bank methods, or null when it can't resolve. */
    static String pickupLineFor(ShortestPathPlugin plugin, RouteOption route, TeleportMethod method) {
        List<TeleportMethod> methods = route.getMethods();
        List<Integer> edges = route.getMethodEdgeIndexes();
        List<PathStep> path = route.getPath();
        for (int m = 0; m < methods.size() && m < edges.size(); m++) {
            if (!methods.get(m).equals(method))
                continue;
            int edge = edges.get(m);
            if (path == null || edge <= 0 || edge >= path.size())
                continue;
            List<Transport> rows = plugin.getPathfinderConfig().transportsOnEdge(
                path.get(edge - 1).getPackedPosition(), path.get(edge).getPackedPosition());
            if (rows.isEmpty()) {
                rows = plugin.getPathfinderConfig().teleportsOnEdge(
                    path.get(edge).getPackedPosition(), method.getDisplayInfo());
            }
            String line = pickupLine(plugin, rows, joinLabels(java.util.Set.of(method)));
            if (line != null)
                return line;
        }
        return null;
    }

    /** One pickup line for a bank method: its fare attributed, else its items by name. */
    private static String pickupLine(ShortestPathPlugin plugin, List<Transport> rows, String label) {
        for (Transport row : rows) {
            int coins = coinsOf(plugin, row);
            if (coins > 0)
                return coins + " gp — " + label + " fare";
            if (row.getItemRequirements() == null)
                continue;
            List<String> names = new ArrayList<>();
            for (gps.transport.requirement.ItemRequirement requirement
                : row.getItemRequirements().getRequirements()) {
                int[] ids = requirement.getItemIds();
                if (ids.length == 0)
                    continue;
                // The first alternative is the data's canonical choice for this slot.
                String name = plugin.getClient().getItemDefinition(ids[0]).getName();
                if (name == null || name.isEmpty() || "null".equals(name))
                    continue;
                names.add(requirement.getQuantity() > 1
                    ? name + " (" + requirement.getQuantity() + ")" : name);
            }
            if (!names.isEmpty())
                return String.join(", ", names) + " — " + label;
        }
        return null;
    }

    /**
     * The single-line fallback: the same pickup phrases as the bank-tile overlay hint,
     * then the bare method list when even those are unknown. The singleton location set
     * stands in for the bank-destination guard: this call site already KNOWS index
     * {@code pathIndex} is the tile where the path flips banked.
     */
    private static String withdrawText(ShortestPathPlugin plugin, RouteOption route,
        List<PathStep> path, int pathIndex) {
        net.runelite.api.Item[] bank = plugin.getPathfinderConfig().getBankSnapshot();
        if (bank != null) {
            List<String> items = gps.transport.BankPickupRequirements.compute(
                plugin.getClient(), bank, plugin.getPathfinderConfig(),
                Set.of(path.get(pathIndex).getPackedPosition()), path, pathIndex).phrases;
            if (!items.isEmpty()) {
                return "Withdraw " + String.join(", ", items)
                    + " for: " + joinLabels(route.getBankMethods());
            }
        }
        return "Withdraw item for: " + joinLabels(route.getBankMethods());
    }

    private static String joinLabels(Set<TeleportMethod> methods) {
        StringBuilder sb = new StringBuilder();
        for (TeleportMethod method : methods) {
            if (sb.length() > 0)
                sb.append(", ");
            sb.append(method.label());
        }
        return sb.toString();
    }

    /**
     * The menu-style instruction carried by an object transport's data ("Climb-up Staircase",
     * "Walk-across Log balance", "Open Door"), with the trailing object id stripped. Null when
     * the transport carries no object info.
     */
    /**
     * Whether an "Open ..." transport is a doorway: a door or gate crossed between neighbouring tiles
     * on one plane, which needs no cue once open. "Open Trapdoor" to the tunnels below is the
     * transport itself and keeps its label (capture 2026-10-03, the Mourner HQ trapdoor).
     */
    static boolean isDoorway(Transport transport) {
        String text = objectText(transport);
        int origin = transport.getOrigin();
        int destination = transport.getDestination();
        return text != null && text.startsWith("Open ")
            && WorldPointUtil.unpackWorldPlane(origin) == WorldPointUtil.unpackWorldPlane(destination)
            && WorldPointUtil.distanceBetween2D(origin, destination) <= 2;
    }

    static String objectText(Transport transport) {
        String objectInfo = transport.getObjectInfo();
        if (objectInfo == null || objectInfo.isEmpty())
            return null;
        int lastSpace = objectInfo.lastIndexOf(' ');
        if (lastSpace > 0 && objectInfo.substring(lastSpace + 1).chars().allMatch(Character::isDigit))
            return objectInfo.substring(0, lastSpace);
        return objectInfo;
    }
}

package gps;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.font.TextLayout;
import java.awt.geom.Rectangle2D;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;

import static gps.WorldPointUtil.distanceBetween;
import static gps.WorldPointUtil.unpackWorldPlane;

/**
 * Movable "directions" panel for the route currently shown on the map: the numbered steps to follow
 * — walking legs, teleports/transports to use, bank withdrawals and climbs — with live progress from
 * the player's position. Completed steps grey out (and collapse into a summary line), the step being
 * executed is orange (amber once it's nearly finished), the next step is white. Drag it wherever you
 * like (RuneLite overlay editing); hidden when no route is shown or via the config toggle.
 */
public class RouteDirectionsOverlay extends OverlayPanel {
    private static final int MAX_LINES = 14;
    // The panel grows to fit its widest line between these bounds; only beyond MAX_WIDTH do lines
    // get ellipsized (clipping "Use Rat Pits M…" is worse than a wider panel).
    private static final int MIN_WIDTH = 140;
    private static final int MAX_WIDTH = 360;
    // Component insets plus the gap between the left text and the right-aligned time.
    private static final int PANEL_PADDING = 18;

    private static final Color DONE = new Color(0x80, 0x80, 0x80);
    // The overlay's accent tone (map-app navigation blue by default, user-configurable): the
    // active step, header pin, divider rule and ETA badge. The lighter "about to end" shade and
    // the badge's border are derived from it each frame.
    private Color accent = new Color(0x4C, 0x8B, 0xF5);
    private Color accentEnding = lighten(accent, 0.35f);
    private static final Color NEXT = Color.WHITE;
    private static final Color UPCOMING = new Color(0xB4, 0xB4, 0xB4);
    private static final Color OFF_ROUTE = new Color(0xFF, 0x4C, 0x4C);

    // Magnifying-glass hierarchy: bold > regular > small, mapped from the text-size preset onto
    // combinations that render crisply (see OverlayFontSize — the pixel-art fonts only look right
    // at their native size 16 or exactly pixel-doubled).
    private OverlayFontSize fontSize = OverlayFontSize.NORMAL;
    private Font fontCurrent = FontManager.getRunescapeBoldFont();
    private Font fontNext = FontManager.getRunescapeFont();
    private Font fontOther = FontManager.getRunescapeSmallFont();

    private final Client client;
    private final ShortestPathPlugin plugin;

    // Progress along the displayed route: each frame the marker moves to the eligible path tile
    // nearest the player, and the ETA is (walk time to that tile + remaining route time from it).
    // It counts down as the player travels, grows again when backtracking or straying off the
    // path, and mid-ride transports are interpolated separately (see the riding branch).
    private RouteOption progressRoute;
    private int reachedIndex;
    // Remaining route time (ticks) from each path index, precomputed per route.
    private double[] remainingTicksAt;
    // The live remaining estimate chosen by the scoring pass.
    private double liveRemainingTicks;
    // Distance from the player to the tile the scoring pass selected: 0 = standing on the
    // path. Arrival is only trusted at 0 — anything else may be proximity through a wall.
    private int lastSelectionDistance = Integer.MAX_VALUE;

    // Straight-line proximity is not reachability: a later leg can pass close by across a cliff the
    // route detours around, and straight-line cost always underprices a transport that exists
    // because you can't walk there. Progress therefore moves INCREMENTALLY — a few indexes per
    // update, and only while genuinely near the line — with two jump exceptions: standing exactly ON
    // a path tile at walking speed (teleport/transport landings), and ride interpolation.
    // Progress-selection thresholds live in RouteProgress (the unit-testable tracker); this alias
    // remains for the vehicle-speed heuristic below.
    private static final int NEAR_DISTANCE = RouteProgress.NEAR_DISTANCE;
    /**
     * Arrival radius for SAILING legs: the tracked position is the hull's anchor tile, and a
     * boat stops short — hull clearance, quarter-tile velocity snapping, and the game halting
     * adjacent to the target can leave the anchor several tiles out while the bow touches it.
     */
    private static final int SEA_NEAR_DISTANCE = 12;
    // Walk-distance flood memo (see updateProgress): recomputed only when the player's tile changes.
    private java.util.Map<Integer, Integer> walkCache;
    private int walkCacheTile = WorldPointUtil.UNDEFINED;
    private static final double VEHICLE_TILES_PER_SECOND = 4.5;
    private static final long SPEED_SAMPLE_MILLIS = 400;
    private long speedSampleAt;
    private int speedSamplePosition = WorldPointUtil.UNDEFINED;
    private double speedTilesPerSecond;

    // Arrival lingering: the plugin clears the target the moment the destination is reached, which
    // would vanish the panel mid-glance. When the route disappears right after progress was at the
    // end, an "Arrived!" panel lingers instead — until clicked, or until the configurable
    // auto-dismiss timer runs out (when enabled).
    private static final long NEAR_END_GRACE_MILLIS = 4_000;
    private long nearEndAtMillis = Long.MIN_VALUE / 2;
    private boolean arrivalShowing;
    private long arrivalUntilMillis;
    // Snapshots for the arrival panel — the plugin clears the target (and its source) the moment the
    // destination is reached, so they must be captured while the route is still alive. The journey
    // start itself is owned by the plugin (movement-based), read via getJourneyStartMillis.
    private String arrivalSource;
    private long arrivalElapsedMillis;

    private static final Color ARRIVED = new Color(0x3C, 0xC8, 0x6A);

    @Inject
    public RouteDirectionsOverlay(Client client, ShortestPathPlugin plugin) {
        super(plugin);
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.display().showDirections)
            return null;
        // Override RuneLite's overlay transparency on request: the base OverlayPanel only
        // substitutes the user's preferred colour when the panel still has the STANDARD
        // background, so setting our own (and restoring STANDARD when the override is off)
        // overrides or yields cleanly. The transparency spinner picks how see-through: the
        // standard colour's tone with 100% = fully invisible, 0% = solid. Every text row draws
        // with a shadow, so the panel stays readable on bare game background.
        panelComponent.setBackgroundColor(plugin.display().overrideOverlayTransparency
            ? overriddenBackground(plugin.display().overlayTransparency)
            : ComponentConstants.STANDARD_BACKGROUND_COLOR);
        accent = plugin.display().colourOverlayAccent;
        accentEnding = lighten(accent, 0.35f);
        refreshFonts();
        long now = System.currentTimeMillis();
        RouteOption route = plugin.getDisplayedRoute();
        if (route == null) {
            // A fresh destination whose routes are still computing: the ground stays clear, the
            // HUD says so — a line that may still change is never shown as the route.
            if (plugin.isFindingRoute()) {
                arrivalShowing = false;
                return renderFinding(graphics);
            }
            // The route just ended: if progress was at the destination moments ago, this is an
            // arrival — linger with a farewell instead of vanishing mid-glance.
            if (!arrivalShowing && now - nearEndAtMillis < NEAR_END_GRACE_MILLIS) {
                arrivalShowing = true;
                arrivalUntilMillis = plugin.display().arrivalAutoDismiss
                    ? now + plugin.display().arrivalDismissSeconds * 1000L : Long.MAX_VALUE;
                long journeyStart = plugin.getJourneyStartMillis();
                arrivalElapsedMillis = journeyStart == 0 ? 0 : Math.max(0, now - journeyStart);
            }
            nearEndAtMillis = Long.MIN_VALUE / 2;
            if (arrivalShowing && now < arrivalUntilMillis)
                return renderArrival(graphics);
            arrivalShowing = false;
            return null;
        }
        arrivalShowing = false;
        List<RouteDirections.Step> steps = plugin.getRouteDirections(route);
        if (steps.isEmpty())
            return null;
        updateProgress(route, steps);
        // "About to arrive" needs more than a small ETA — straight-line proximity can undercut
        // walls (the goal one tile away across a fence). It must be EARNED: standing exactly on
        // a path tile in the final stretch, with no unopened door left between here and the end.
        if (liveRemainingTicks <= 3.5 && lastSelectionDistance == 0 && lastLegClear(route, steps))
            nearEndAtMillis = now;

        // The first step whose span the player hasn't finished yet is the one being executed.
        int current = steps.size() - 1;
        for (int i = 0; i < steps.size(); i++) {
            if (!finished(steps.get(i))) {
                current = i;
                break;
            }
        }

        String etaText = "ETA: " + formatTime((int) Math.ceil(liveRemainingTicks * RouteDirections.SECONDS_PER_TICK));

        // First pass: collect the lines, then size the panel to the widest one (within bounds) so
        // content is neither wrapped nor needlessly clipped; only lines beyond MAX_WIDTH truncate.
        List<Line> lines = new ArrayList<>();
        arrivalSource = plugin.getTargetSource();
        // "Destination set by ...", or during a bank trip what resumes after it (BankDetour.headerLine).
        String destinationLine = plugin.getDestinationLine();
        if (destinationLine != null)
            lines.add(new Line(destinationLine, fontOther, UPCOMING, null, null));
        // Drifting off the drawn path: warn before the route is recomputed (the middle of the three
        // distance bands — see ShortestPathPlugin's off-route handling).
        if (plugin.isOffRouteWarning()) {
            // With auto-recalculate off the route is deliberately kept, so don't promise a recompute.
            lines.add(new Line(plugin.isAutoRecalculateEnabled()
                ? "Off route — recomputing if you drift further"
                : "Off route", fontNext, OFF_ROUTE, null, null));
        }

        // Window: collapse all but the most recent completed step into one summary line, then show
        // the current step and what follows, capped.
        int windowStart = Math.max(0, current - 1);
        if (windowStart > 0) {
            lines.add(new Line("✓ " + windowStart + (windowStart == 1 ? " step done" : " steps done"),
                fontOther, DONE, null, null));
        }
        int shown = 0;
        int i = windowStart;
        for (; i < steps.size() && shown < MAX_LINES; i++, shown++) {
            RouteDirections.Step step = steps.get(i);
            String stepText = i >= current && step.isDoor()
                ? doorStepText(route, step) : step.getText();
            String text = (i + 1) + ". " + stepText;
            Color colour;
            Font font;
            if (i < current) {
                // The RuneScape fonts carry no U+2713 glyph, but the JVM's font pipeline substitutes
                // one from a system font (verified in-game on Windows). If reports of missing-glyph
                // boxes come in from other platforms, drop the prefix — the grey colour already
                // marks completion on its own.
                text = "✓ " + text;
                colour = DONE;
                font = fontOther;
            }
            else if (i == current) {
                colour = nearEnd(step) ? accentEnding : accent;
                font = fontCurrent;
            }
            else if (i == current + 1) {
                colour = NEXT;
                font = fontNext;
            }
            else {
                colour = UPCOMING;
                font = fontOther;
            }
            lines.add(new Line(text, font, colour,
                formatTime((int) Math.ceil(step.getTicks() * RouteDirections.SECONDS_PER_TICK)), colour));
            // The withdraw step's per-item list: indented, un-numbered, no own time.
            for (String detail : step.getDetails()) {
                if (shown + 1 >= MAX_LINES)
                    break;
                lines.add(new Line("      • " + detail, fontOther, colour, null, null));
                shown++;
            }
        }
        if (i < steps.size())
            lines.add(new Line("… " + (steps.size() - i) + " more", fontOther, DONE, null, null));

        Dimension dimension = renderPanel(graphics, lines);
        if (dimension != null)
            drawEtaBadge(graphics, dimension, etaText);
        return dimension;
    }

    /**
     * Sizes the panel to its widest line (within bounds), emits the header spacer and the lines, and
     * draws the decorated title over the reserved header row.
     */
    private Dimension renderPanel(Graphics2D graphics, List<Line> lines) {
        // Fit the panel to the content: widest left text + its time column, clamped to sane bounds.
        // The bounds scale with the text-size preset (2x for Large) — at doubled glyph widths a
        // fixed cap would ellipsize twice as much of every step.
        final float widthScale = fontCurrent.getSize2D() / 16f;
        final int minWidth = Math.round(MIN_WIDTH * widthScale);
        final int maxWidth = Math.round(MAX_WIDTH * widthScale);
        int contentWidth = minWidth;
        for (Line line : lines) {
            // A centred line (arrival, finding) reads as a label, not a list row: give it the
            // margin on both sides, or the text hugs the panel edges.
            int width = graphics.getFontMetrics(line.font).stringWidth(line.left)
                + rightWidth(graphics, line) + (line.centred ? 2 * PANEL_PADDING : PANEL_PADDING);
            contentWidth = Math.max(contentWidth, width);
        }
        int panelWidth = Math.min(contentWidth, maxWidth);
        panelComponent.setPreferredSize(new Dimension(panelWidth, 0));

        // Spacer reserving the header row; the decorated title (pin glyph + bold text + accent rule)
        // is custom-drawn over it after the panel renders — TitleComponent supports no font/styling.
        panelComponent.getChildren().add(
            LineComponent.builder()
                .left(" ")
                .leftFont(fontCurrent)
                .build());
        for (Line line : lines) {
            if (line.centred) {
                // Reserve the row with a spacer in the same font; the text itself is drawn
                // centred over the panel afterwards.
                panelComponent.getChildren().add(
                    LineComponent.builder().left(" ").leftFont(line.font).build());
                continue;
            }
            LineComponent.LineComponentBuilder builder = LineComponent.builder()
                .left(ellipsize(graphics, line.font, line.left, panelWidth - rightWidth(graphics, line) - PANEL_PADDING))
                .leftColor(line.colour)
                .leftFont(line.font);
            if (line.right != null) {
                builder.right(line.right)
                    .rightColor(line.rightColour)
                    .rightFont(line.font == fontCurrent ? fontNext : fontOther);
            }
            panelComponent.getChildren().add(builder.build());
        }

        Dimension dimension = super.render(graphics);
        if (dimension != null) {
            drawTitle(graphics, dimension);
            drawCentredLines(graphics, dimension, lines);
        }
        return dimension;
    }

    /**
     * Draws the trailing centred lines over their reserved spacer rows, anchored bottom-up to the
     * panel's bottom edge. TextLayout's tight glyph bounds centre the text properly — the
     * RuneScape fonts' metrics don't match their visual size (see {@link #drawEtaBadge}).
     */
    private void drawCentredLines(Graphics2D graphics, Dimension panelSize, List<Line> lines) {
        int first = lines.size();
        while (first > 0 && lines.get(first - 1).centred)
            first--;
        float bottom = panelSize.height - 7;
        for (int i = lines.size() - 1; i >= first; i--) {
            Line line = lines.get(i);
            if (line.left.isBlank()) {
                // A blank centred line is vertical air: its row is reserved in the panel, and the
                // text above it moves up by half that row (a full row would leave it floating).
                bottom -= line.font.getSize() / 2f + 5;
                continue;
            }
            TextLayout layout = new TextLayout(line.left, line.font, graphics.getFontRenderContext());
            Rectangle2D bounds = layout.getBounds();
            float x = (float) ((panelSize.width - bounds.getWidth()) / 2 - bounds.getX());
            // Place the glyph box's bottom on the anchor, then move the anchor up past it.
            float baseline = (float) (bottom - bounds.getHeight() - bounds.getY());
            drawLayout(graphics, layout, x, baseline, line.colour);
            bottom -= bounds.getHeight() + 5;
        }
    }

    /** Draws laid-out text with the stock one-pixel drop shadow (spacing-neutral in every mode). */
    private static void drawLayout(Graphics2D graphics, TextLayout layout, float x, float baseline, Color colour) {
        graphics.setColor(Color.BLACK);
        layout.draw(graphics, x + 1, baseline + 1);
        graphics.setColor(colour);
        layout.draw(graphics, x, baseline);
    }

    /**
     * The overridden overlay background: the standard background's tone at the configured
     * TRANSPARENCY (100% = invisible, 0% = solid), so a partially visible override still matches
     * RuneLite's palette. Never null — a null would re-enable the base panel's colour handling.
     */
    private static Color overriddenBackground(int transparencyPercent) {
        final int alpha = Math.max(0, Math.min(255, Math.round(255 * (100 - transparencyPercent) / 100f)));
        final Color standard = ComponentConstants.STANDARD_BACKGROUND_COLOR;
        return new Color(standard.getRed(), standard.getGreen(), standard.getBlue(), alpha);
    }

    /** Rebuilds the three fonts when the text-size preset changes. */
    private void refreshFonts() {
        final OverlayFontSize preset = plugin.display().overlayFontSize == null
            ? OverlayFontSize.NORMAL : plugin.display().overlayFontSize;
        if (preset == fontSize)
            return;
        fontSize = preset;
        final Font bold = FontManager.getRunescapeBoldFont();
        final Font regular = FontManager.getRunescapeFont();
        final Font small = FontManager.getRunescapeSmallFont();
        switch (preset) {
            case SMALL:
                // The hierarchy shifted one tier down, every face at its native size.
                fontCurrent = regular;
                fontNext = small;
                fontOther = small;
                break;
            case LARGE:
                // The in-between step at 1.5x — a touch softer than the exact-multiple sizes.
                fontCurrent = bold.deriveFont(24f);
                fontNext = regular.deriveFont(24f);
                fontOther = small.deriveFont(24f);
                break;
            case EXTRA_LARGE:
                // Exactly pixel-doubled: the enlargement that keeps the pixel fonts sharp.
                fontCurrent = bold.deriveFont(32f);
                fontNext = regular.deriveFont(32f);
                fontOther = small.deriveFont(32f);
                break;
            default:
                fontCurrent = bold;
                fontNext = regular;
                fontOther = small;
                break;
        }
    }

    /** Blends a colour toward white — the derived "about to end" shade of the accent. */
    private static Color lighten(Color colour, float factor) {
        return new Color(
            colour.getRed() + Math.round((255 - colour.getRed()) * factor),
            colour.getGreen() + Math.round((255 - colour.getGreen()) * factor),
            colour.getBlue() + Math.round((255 - colour.getBlue()) * factor));
    }

    /**
     * Decorated header drawn over the reserved top row: a small location-pin glyph, bold "GPS", and
     * a navigation-blue rule under the header separating it from the steps.
     */
    private void drawTitle(Graphics2D graphics, Dimension panelSize) {
        // All header geometry scales with the header font (1x at the native 16, 2x for Large).
        final float s = fontCurrent.getSize2D() / 16f;
        final int px = 8;
        final int py = 4;
        // The destination's glyph: a location pin, or a bank while a bank trip will resume a
        // replaced route (the destination line says what comes after it).
        if (plugin.isBankDetour())
            drawBankGlyph(graphics, px, py, s, accent);
        else
            drawPinGlyph(graphics, px, py, s, accent);

        graphics.setFont(fontCurrent);
        graphics.setColor(Color.BLACK);
        graphics.drawString("GPS", px + Math.round(14 * s), py + Math.round(12 * s));
        graphics.setColor(Color.WHITE);
        graphics.drawString("GPS", px + Math.round(13 * s), py + Math.round(11 * s));

        // Accent rule under the header row.
        graphics.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), 170));
        graphics.drawLine(4, py + Math.round(15 * s), panelSize.width - 4, py + Math.round(15 * s));
    }

    /** Location pin: round head with a tail, hollow centre, 9 x 13 at scale 1. */
    static void drawPinGlyph(Graphics2D graphics, int px, int py, float s, Color accent) {
        graphics.setColor(accent);
        graphics.fillOval(px, py, Math.round(9 * s), Math.round(9 * s));
        Polygon tail = new Polygon(
            new int[]{px + Math.round(1 * s), px + Math.round(8 * s), px + Math.round(4 * s)},
            new int[]{py + Math.round(7 * s), py + Math.round(7 * s), py + Math.round(13 * s)},
            3);
        graphics.fillPolygon(tail);
        graphics.setColor(new Color(0x10, 0x10, 0x10));
        graphics.fillOval(px + Math.round(3 * s), py + Math.round(3 * s), Math.round(3 * s), Math.round(3 * s));
    }

    /**
     * Bank, the map-legend kind: a pediment over three columns on a plinth, 10 x 13 at scale 1,
     * the pin's footprint so the "GPS" title beside it stays put.
     */
    static void drawBankGlyph(Graphics2D graphics, int px, int py, float s, Color accent) {
        graphics.setColor(accent);
        int width = Math.round(10 * s);
        graphics.fillPolygon(new Polygon(
            new int[]{px, px + width, px + Math.round(5 * s)},
            new int[]{py + Math.round(4 * s), py + Math.round(4 * s), py},
            3));
        graphics.fillRect(px, py + Math.round(4 * s), width, Math.max(1, Math.round(1 * s)));
        int columnWidth = Math.max(1, Math.round(2 * s));
        for (int i = 0; i < 3; i++)
            graphics.fillRect(px + Math.round((1 + 3 * i) * s), py + Math.round(5 * s), columnWidth, Math.round(6 * s));
        graphics.fillRect(px, py + Math.round(11 * s), width, Math.max(1, Math.round(2 * s)));
    }

    /**
     * The ETA as a floating pill overlapping the panel's top-right corner — a badge rather than a
     * list row, map-app style.
     */
    private void drawEtaBadge(Graphics2D graphics, Dimension panelSize, String etaText) {
        // TextLayout gives the glyphs' tight pixel bounds — the RuneScape fonts' metrics (ascent,
        // leading) don't match their visual size, which kept mis-centring the text in the pill.
        TextLayout layout = new TextLayout(etaText, fontOther, graphics.getFontRenderContext());
        Rectangle2D bounds = layout.getBounds();
        int width = (int) Math.ceil(bounds.getWidth()) + 12;
        int height = (int) Math.ceil(bounds.getHeight()) + 8;
        // Right edge pinned just inside the panel corner; the pill grows leftward as the countdown's
        // text widens. No overhang: with the overlay snapped to the screen edge, an overhanging pill
        // gets clipped and its text looks misaligned.
        int x = panelSize.width - width - 2;
        int y = 2;

        graphics.setColor(accent);
        graphics.fillRoundRect(x, y, width, height, 8, 8);
        graphics.setColor(accent.darker());
        graphics.drawRoundRect(x, y, width, height, 8, 8);
        // Centre the tight glyph box inside the pill on both axes.
        float textX = (float) (x + (width - bounds.getWidth()) / 2 - bounds.getX());
        float textY = (float) (y + (height - bounds.getHeight()) / 2 - bounds.getY());
        graphics.setColor(Color.BLACK);
        layout.draw(graphics, textX + 1, textY + 1);
        graphics.setColor(Color.WHITE);
        layout.draw(graphics, textX, textY);
    }

    /**
     * One pending panel line: collected first so the panel can be sized to the widest line before
     * any component is built.
     */
    private static final class Line {
        private final String left;
        private final Font font;
        private final Color colour;
        private final String right;
        private final Color rightColour;
        // Centred lines are reserved as spacer rows and custom-drawn centred over the panel
        // afterwards — LineComponent only aligns left/right. Only trailing lines may be centred.
        private final boolean centred;

        private Line(String left, Font font, Color colour, String right, Color rightColour) {
            this(left, font, colour, right, rightColour, false);
        }

        private Line(String left, Font font, Color colour, String right, Color rightColour, boolean centred) {
            this.left = left;
            this.font = font;
            this.colour = colour;
            this.right = right;
            this.rightColour = rightColour;
            this.centred = centred;
        }
    }

    private int rightWidth(Graphics2D graphics, Line line) {
        return line.right == null ? 0 : graphics.getFontMetrics(fontOther).stringWidth(line.right) + 6;
    }

    /**
     * Compact wall-time: "34s" under a minute, "2m 05s" above.
     */
    private static String formatTime(int seconds) {
        if (seconds < 60)
            return seconds + "s";
        return (seconds / 60) + "m " + String.format("%02ds", seconds % 60);
    }

    /**
     * Truncates a line to {@code maxWidth} instead of letting LineComponent wrap it — wrapped steps
     * blur into their neighbours and break the list rhythm. With the panel sized to its content this
     * only kicks in past {@link #MAX_WIDTH}.
     */
    private static String ellipsize(Graphics2D graphics, Font font, String text, int maxWidth) {
        java.awt.FontMetrics metrics = graphics.getFontMetrics(font);
        if (metrics.stringWidth(text) <= maxWidth)
            return text;
        int end = text.length();
        while (end > 1 && metrics.stringWidth(text.substring(0, end) + "…") > maxWidth)
            end--;
        return text.substring(0, end) + "…";
    }

    /**
     * Live wording for a pending door step: a door that already stands open needs walking
     * through, not opening. Out-of-scene doors keep the "Open" default — regular doors shut
     * themselves, so closed is the safe assumption until the door is visible.
     */
    private String doorStepText(RouteOption route, RouteDirections.Step step) {
        List<gps.pathfinder.PathStep> path = route.getPath();
        if (step.getStartIndex() < 0 || step.getEndIndex() >= path.size())
            return step.getText();
        ClosedDoors.Door door = ClosedDoors.doorBetween(
            path.get(step.getStartIndex()).getPackedPosition(),
            path.get(step.getEndIndex()).getPackedPosition());
        if (door != null && ClosedDoors.state(client, door) == ClosedDoors.State.OPEN)
            return "Go through " + door.name;
        return step.getText();
    }

    /**
     * Whether the current step is nearly finished: within the last fifth (or last 3 tiles) of its
     * span. Only meaningful for longer spans — short steps (a teleport edge) flip states quickly
     * anyway.
     */
    private boolean nearEnd(RouteDirections.Step step) {
        int span = step.getEndIndex() - step.getStartIndex();
        if (span < 8)
            return false;
        int remaining = step.getEndIndex() - reachedIndex;
        return remaining <= Math.max(3, span / 5);
    }

    /**
     * The lingering arrival panel: who set the destination, a green "Arrived!" and the total
     * wall time the journey took. The whole panel is the dismiss button (see
     * {@link #dismissArrivalAt}).
     */
    /**
     * The HUD while a fresh destination's routes compute: no route yet, just the label with a row
     * of air above and below it. Static text on purpose — animated dots shift the centred label
     * and the panel width a few pixels every beat, which reads as jitter, not progress.
     */
    private Dimension renderFinding(Graphics2D graphics) {
        List<Line> lines = new ArrayList<>();
        String destinationLine = plugin.getDestinationLine();
        if (destinationLine != null)
            lines.add(new Line(destinationLine, fontOther, UPCOMING, null, null));
        lines.add(new Line(" ", fontOther, UPCOMING, null, null));
        lines.add(new Line("Finding the best route...", fontCurrent, NEXT, null, null, true));
        lines.add(new Line(" ", fontOther, NEXT, null, null, true));
        return renderPanel(graphics, lines);
    }

    private Dimension renderArrival(Graphics2D graphics) {
        List<Line> lines = new ArrayList<>();
        if (arrivalSource != null)
            lines.add(new Line("Destination set by " + arrivalSource, fontOther, UPCOMING, null, null));
        lines.add(new Line("Arrived!", fontCurrent, ARRIVED, null, null, true));
        lines.add(new Line("in " + formatTime((int) (arrivalElapsedMillis / 1000)), fontNext, NEXT, null, null, true));
        lines.add(new Line("(click to dismiss)", fontOther, DONE, null, null, true));
        return renderPanel(graphics, lines);
    }

    /** Hides the lingering "Arrived!" panel (the right-click menu's "Dismiss Arrival"). */
    public void dismissArrival() {
        arrivalShowing = false;
    }

    /** Whether the lingering "Arrived!" panel is what the overlay currently shows. */
    public boolean isArrivalShowing() {
        return arrivalShowing;
    }

    /**
     * Dismisses the arrival panel when {@code point} (canvas coordinates) is inside it. Called from
     * the plugin's mouse listener; returns true when the click was consumed.
     */
    public boolean dismissArrivalAt(java.awt.Point point) {
        if (!arrivalShowing)
            return false;
        java.awt.Rectangle bounds = getBounds();
        if (bounds == null || !bounds.contains(point))
            return false;
        arrivalShowing = false;
        return true;
    }

    /**
     * Latches the "Arrived!" panel. Called by the plugin the moment it clears the target on arrival,
     * so arrival is shown even when the near-end proximity stamp never happened — e.g. a destination
     * set while already at it, which the plugin clears on the very next tick before the route renders.
     */
    public void markArrived(String source, long elapsedMillis) {
        arrivalSource = source;
        arrivalElapsedMillis = Math.max(0, elapsedMillis);
        arrivalShowing = true;
        long now = System.currentTimeMillis();
        arrivalUntilMillis = plugin.display().arrivalAutoDismiss
            ? now + plugin.display().arrivalDismissSeconds * 1000L : Long.MAX_VALUE;
    }

    /**
     * Moves the progress marker to the eligible path tile nearest the player, preferring the one
     * closest to the previous position on ties — so standing where the path crosses itself doesn't
     * teleport the highlight to the other pass. The ETA is then (walk time to that tile + remaining
     * route time from it). No same-plane tile at all (e.g. an off-route dungeon detour) freezes the
     * estimate.
     */
    private void updateProgress(RouteOption route, List<RouteDirections.Step> steps) {
        List<gps.pathfinder.PathStep> path = route.getPath();
        if (route != progressRoute) {
            progressRoute = route;
            reachedIndex = 0;
            remainingTicksAt = buildRemainingTicks(route, steps);
            liveRemainingTicks = remainingTicksAt.length > 0 ? remainingTicksAt[0] : 0;
        }
        Player player = client.getLocalPlayer();
        if (player == null || remainingTicksAt.length != path.size())
            return;
        // Boat-aware: aboard, the raw local position is in the boat's sub-WorldView — the
        // tracker froze the moment the player boarded. UNDEFINED transients (view swaps)
        // simply skip this frame's update.
        int playerPacked = WorldPointUtil.fromLocalInstance(client, player);
        if (playerPacked == WorldPointUtil.UNDEFINED)
            return;
        int playerPlane = unpackWorldPlane(playerPacked);

        // Rolling speed estimate (tiles/second): faster than any running player means a transport is
        // carrying us — freeze the estimate until we land instead of scoring transient positions.
        long now = System.currentTimeMillis();
        if (speedSamplePosition == WorldPointUtil.UNDEFINED || now - speedSampleAt >= SPEED_SAMPLE_MILLIS) {
            if (speedSamplePosition != WorldPointUtil.UNDEFINED && now > speedSampleAt) {
                // A plane change between samples reads as a big move (stairs/teleports).
                int moved = unpackWorldPlane(speedSamplePosition) == playerPlane
                    ? distanceBetween(speedSamplePosition, playerPacked)
                    : NEAR_DISTANCE * 2;
                speedTilesPerSecond = moved * 1000.0 / (now - speedSampleAt);
            }
            speedSampleAt = now;
            speedSamplePosition = playerPacked;
        }
        // Speed alone cannot see a slow boat: 2 tiles/tick equals running speed, so the
        // vehicle threshold never trips aboard and the ETA froze (field report at sea). The
        // boarded varbit says it plainly.
        boolean riding = speedTilesPerSecond > VEHICLE_TILES_PER_SECOND || aboard();

        if (riding) {
            // Mid-transport: interpolate through the ride geometrically. Distance to the landing
            // tile over the full hop length gives the fraction completed; the ETA becomes the
            // remainder of the ride plus everything after it. Progress itself (step completion)
            // still only advances on landing — and mid-flight never counts as standing on the
            // path, so a ride passing over the destination can't stamp an arrival.
            lastSelectionDistance = Integer.MAX_VALUE;
            RouteDirections.Step ride = currentStep(plugin.getRouteDirections(route));
            // Aboard, the ride is found by GEOMETRY: boarding happens from range, so the
            // boarding node may never have been stood on — currentStep would stay the walk
            // leg forever, freezing the list at "Walk" and never stamping the arrival. The
            // sail step whose cached track passes nearest the boat is the active one; being
            // aboard also means everything before its departure node is done.
            if (aboard()) {
                RouteDirections.Step sail = activeSailRide(
                    route, plugin.getRouteDirections(route), playerPacked);
                if (sail != null) {
                    ride = sail;
                    reachedIndex = Math.max(reachedIndex, sail.getStartIndex());
                }
            }
            if (ride != null && ride.isTransport()) {
                int origin = path.get(Math.max(0, ride.getStartIndex())).getPackedPosition();
                int destination = path.get(ride.getEndIndex()).getPackedPosition();
                // Sailing rides follow a CURVED track: the embarked world position scores
                // directly against the leg's own waypoints (no walls at sea, so straight-line
                // to the track IS the walk metric — the collision BFS the land selector uses
                // cannot flood a sealed ocean). Progress advances waypoint by waypoint; the
                // last waypoint, or proximity to the landing, stamps the arrival — that is
                // what greys the sailed stretch and completes water-pin routes.
                boolean sailingRide = route.sailingJumpDepartures().contains(ride.getStartIndex());
                // Proximity to the landing IS arrival — checked before anything track-based,
                // because the live learner invalidates the track cache exactly when arriving
                // at an obstacle-rich port, and the stamp must not depend on a cache.
                if (sailingRide && distanceBetween(playerPacked, destination)
                    <= SEA_NEAR_DISTANCE) {
                    reachedIndex = Math.max(reachedIndex, ride.getEndIndex());
                    liveRemainingTicks = remainingTicksAt[ride.getEndIndex()];
                    // The completion banner gates on selection distance ZERO — a land-selector
                    // concept the riding branch pins to MAX_VALUE. Sea arrival IS selection.
                    lastSelectionDistance = 0;
                    return;
                }
                int[] track = sailingRide ? SailingSea.seaPath(origin, destination) : null;
                if (track != null && track.length > 1) {
                    int nearest = 0;
                    int nearestDistance = Integer.MAX_VALUE;
                    for (int w = 0; w < track.length; w++) {
                        int d = distanceBetween(playerPacked, track[w]);
                        if (d < nearestDistance) {
                            nearestDistance = d;
                            nearest = w;
                        }
                    }
                    // Last FEW waypoints, not the literal last: waypoints are decimated
                    // (every 3rd tile) and the hull parks short of the pin.
                    if (nearest >= track.length - 3
                        || distanceBetween(playerPacked, destination) <= SEA_NEAR_DISTANCE) {
                        reachedIndex = Math.max(reachedIndex, ride.getEndIndex());
                        liveRemainingTicks = remainingTicksAt[ride.getEndIndex()];
                        lastSelectionDistance = 0;
                    }
                    else {
                        double completed = nearest / (double) (track.length - 1);
                        liveRemainingTicks = remainingTicksAt[ride.getEndIndex()]
                            + rideTicks(ride) * (1 - completed);
                    }
                }
                else if (unpackWorldPlane(destination) == playerPlane) {
                    double total = distanceBetween(origin, destination);
                    if (total > 4) {
                        double completed = Math.min(1,
                            1 - distanceBetween(playerPacked, destination) / total);
                        liveRemainingTicks = remainingTicksAt[ride.getEndIndex()]
                            + rideTicks(ride) * (1 - Math.max(0, completed));
                    }
                }
            }
            return;
        }

        // The first uncrossed door ahead gates progress: straight-line proximity sees through a
        // closed door (path tiles beyond it are physically a wall's width away — even adjacent,
        // from the near doorway tile), so several door steps used to complete at once while
        // still outside. Anything at or past that edge only counts once the player is standing
        // exactly on the path beyond it, which a one-tile doorway forces anyway.
        int doorGate = Integer.MAX_VALUE;
        for (RouteDirections.Step step : steps) {
            if (step.isDoor() && step.getEndIndex() > reachedIndex) {
                doorGate = step.getEndIndex();
                break;
            }
        }

        // Round trips: the return leg often retraces the outbound street, so its tiles match the
        // player's position from the very first step OUT. Until the turnaround (the destination)
        // has been reached, return-leg indexes are ineligible — otherwise walking out reads as
        // coming back and the route completes instantly.
        int turnaround = route.getTurnaroundIndex();
        int returnGate = (turnaround >= 0 && reachedIndex < turnaround - 2)
            ? turnaround : Integer.MAX_VALUE;

        // Progress = the eligible path tile NEAREST the player by WALKING distance (ties broken
        // toward the current position) — see RouteProgress for the wall-aware maze rules; the
        // selection logic lives there so it is unit-testable. The ETA is derived from the selected
        // tile afterwards, keeping its walk-back charge without steering the selection.
        // The BFS is memoized by player tile: render runs per FRAME, but the flood only changes
        // when the player's tile does (game movement is tick-paced) — ~2 floods/s instead of ~100.
        if (playerPacked != walkCacheTile) {
            walkCache = RouteProgress.walkDistances(
                plugin.getCollisionMap(), playerPacked, RouteProgress.REACH_RADIUS);
            walkCacheTile = playerPacked;
        }
        RouteProgress.Result selection = RouteProgress.select(
            path, reachedIndex, doorGate, returnGate, playerPacked, walkCache);
        if (selection == null)
            // Nowhere near the route (long off-path detour): hold the last honest estimate.
            return;
        reachedIndex = selection.index;
        liveRemainingTicks = selection.distance / 2.0 + remainingTicksAt[selection.index];
        lastSelectionDistance = selection.distance;
    }

    /**
     * Whether the remaining leg is clear of doors that haven't been seen open — the "green"
     * condition for arrival: a small ETA behind a still-closed (or unverified) door is not
     * an arrival.
     */
    private boolean lastLegClear(RouteOption route, List<RouteDirections.Step> steps) {
        List<gps.pathfinder.PathStep> path = route.getPath();
        for (RouteDirections.Step step : steps) {
            if (!step.isDoor() || step.getEndIndex() <= reachedIndex || step.getEndIndex() >= path.size())
                continue;
            ClosedDoors.Door door = ClosedDoors.doorBetween(
                path.get(step.getStartIndex()).getPackedPosition(),
                path.get(step.getEndIndex()).getPackedPosition());
            if (door != null && ClosedDoors.state(client, door) != ClosedDoors.State.OPEN)
                return false;
        }
        return true;
    }

    /**
     * Progress state exposed for the debug snapshot.
     */
    int getReachedIndex() {
        return reachedIndex;
    }

    /**
     * The tracked progress along {@code route}, or 0 when that route isn't the one being
     * tracked (different selection, or nothing tracked yet).
     */
    int reachedIndexFor(RouteOption route) {
        return route == progressRoute ? reachedIndex : 0;
    }

    double getLiveRemainingTicks() {
        return liveRemainingTicks;
    }

    double getSpeedTilesPerSecond() {
        return speedTilesPerSecond;
    }

    /**
     * The step the player is currently executing: the first whose span isn't finished.
     */
    private RouteDirections.Step currentStep(List<RouteDirections.Step> steps) {
        for (RouteDirections.Step step : steps) {
            if (!finished(step))
                return step;
        }
        return steps.isEmpty() ? null : steps.get(steps.size() - 1);
    }

    /**
     * A step is finished once the player has passed its last path node — EXCEPT the boarding
     * half of a sailing leg, which shares its node with the walk that leads there: standing on
     * the dock is not boarding, only the BOARDED varbit finishes it.
     */
    private boolean finished(RouteDirections.Step step) {
        if (step.getEndIndex() > reachedIndex)
            return false;
        return !step.isEmbark() || aboard();
    }

    /**
     * The sailing ride step whose cached sea track passes nearest the aboard player (within
     * 30 tiles), or null: multiple sail legs in one route disambiguate by geometry.
     */
    private RouteDirections.Step activeSailRide(RouteOption route,
        List<RouteDirections.Step> steps, int playerPacked) {
        List<gps.pathfinder.PathStep> path = route.getPath();
        RouteDirections.Step best = null;
        int bestDistance = 30;
        for (RouteDirections.Step step : steps) {
            if (!step.isTransport() || step.getEndIndex() >= path.size()
                || !route.sailingJumpDepartures().contains(step.getStartIndex())) {
                continue;
            }
            int origin = path.get(Math.max(0, step.getStartIndex())).getPackedPosition();
            int destination = path.get(step.getEndIndex()).getPackedPosition();
            int[] track = SailingSea.seaPath(origin, destination);
            if (track == null) {
                // Track cache just invalidated (the live learner clears it precisely at
                // obstacle-rich ports — i.e. at ARRIVAL): endpoints still identify the leg.
                int d = Math.min(distanceBetween(playerPacked, origin),
                    distanceBetween(playerPacked, destination));
                if (d < bestDistance) {
                    bestDistance = d;
                    best = step;
                }
                continue;
            }
            for (int waypoint : track) {
                int d = distanceBetween(playerPacked, waypoint);
                if (d < bestDistance) {
                    bestDistance = d;
                    best = step;
                }
            }
        }
        return best;
    }

    /** Whether the player is at the helm (SAILING_BOARDED_BOAT). */
    private boolean aboard() {
        return client.getVarbitValue(net.runelite.api.gameval.VarbitID.SAILING_BOARDED_BOAT) != 0;
    }

    /**
     * Remaining route time (ticks) from each path index. When the path carries the search's
     * cumulative costs (plan step N9) the table is exact: {@code (cost[last] - cost[i]) / 2}, the
     * same number the route card shows in seconds. Otherwise: total of all later steps plus the
     * linear remainder of the step spanning the index. Index 0 holds the whole journey.
     */
    /** A ride's duration as the ETA table sees it, so mid-ride interpolation stays on the same line. */
    private double rideTicks(RouteDirections.Step ride) {
        int start = Math.max(0, Math.min(ride.getStartIndex(), remainingTicksAt.length - 1));
        int end = Math.max(start, Math.min(ride.getEndIndex(), remainingTicksAt.length - 1));
        return Math.max(0, remainingTicksAt[start] - remainingTicksAt[end]);
    }

    static double[] buildRemainingTicks(RouteOption route, List<RouteDirections.Step> steps) {
        List<gps.pathfinder.PathStep> path = route.getPath();
        int pathSize = path.size();
        boolean costed = pathSize > 0;
        for (gps.pathfinder.PathStep step : path) {
            if (step.getCost() == gps.pathfinder.PathStep.UNKNOWN_COST) {
                costed = false;
                break;
            }
        }
        if (costed) {
            double[] exact = new double[pathSize];
            int end = path.get(pathSize - 1).getCost();
            for (int i = 0; i < pathSize; i++)
                exact[i] = Math.max(0, end - path.get(i).getCost()) / (double) gps.pathfinder.CostUnits.UNITS_PER_TICK;
            return exact;
        }
        double[] remaining = new double[pathSize];
        double after = 0;
        for (int s = steps.size() - 1; s >= 0; s--) {
            RouteDirections.Step step = steps.get(s);
            int start = Math.max(0, Math.min(step.getStartIndex(), pathSize - 1));
            int end = Math.max(start, Math.min(step.getEndIndex(), pathSize - 1));
            int span = Math.max(1, end - start);
            for (int i = end; i >= start; i--) {
                double throughStep = step.getTicks() * ((end - i) / (double) span);
                remaining[i] = Math.max(remaining[i], after + throughStep);
            }
            after += step.getTicks();
        }
        return remaining;
    }
}

