package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportType;
import gps.transport.requirement.ItemRequirement;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;

/**
 * What the displayed route's NEXT step uses, for the widget highlights: the first method edge the
 * player has not reached, its items when the transport is an item teleport (every variant of the
 * item counts, so whichever the player carries lights up) and its spell when it is a spell
 * teleport, plus the carried staff or tome that stands in for runes the player lacks, since the
 * engine counts it from the bag but the game only when wielded; a fairy ring asks for the Dramen
 * or Lunar staff until the Lumbridge Elite diary waives it, and asks one method ahead, so the
 * staff is wielded before the ring is reached. Null when the next thing to do is none of these. Also the route's bank step, whose pickup the bank highlight lights, and the rule for
 * "worn-only" items (the Camulet: its teleports are worn options), whose bag copy gets an "Equip" tag.
 */
final class RouteItemCue {
    /** Inventory options that use an item where it lies; an item with none of them teleports worn. */
    private static final String[] USE_VERBS = {"Rub", "Teleport", "Break", "Operate", "Commune", "Invoke", "Activate"};

    final Set<Integer> itemIds;
    /** The spell's Display info, for the spellbook; null unless the step casts one. */
    final String spell;
    /** The items that do their work worn (the fairy-ring staff): the equipment tab has nothing to point at. */
    final Set<Integer> wornDone;

    private RouteItemCue(Set<Integer> itemIds, String spell, Set<Integer> wornDone) {
        this.itemIds = itemIds;
        this.spell = spell;
        this.wornDone = wornDone;
    }

    static RouteItemCue next(RouteOption route, int reachedIndex, BiFunction<PathStep, PathStep, Set<Transport>> transportsForEdge,
        boolean fairyRingsNeedStaff, Map<Integer, Integer> carried) {
        if (route == null)
            return null;
        List<PathStep> path = route.getPath();
        Set<Integer> ids = new HashSet<>();
        Set<Integer> wornDone = new HashSet<>();
        String spell = null;
        int ahead = 0;
        for (int edge : route.getMethodEdgeIndexes()) {
            if (edge <= reachedIndex || edge <= 0 || edge >= path.size())
                continue;
            if (ahead++ > 1)
                break;
            for (Transport transport : transportsForEdge.apply(path.get(edge - 1), path.get(edge))) {
                TransportType type = transport.getType();
                if (type == TransportType.FAIRY_RING) {
                    if (fairyRingsNeedStaff)
                        for (int id : ItemVariations.DRAMEN_STAFF.getIds()) {
                            ids.add(id);
                            wornDone.add(id);
                        }
                    continue;
                }
                if (ahead > 1)
                    continue; // only the staff is asked for ahead of its step
                if (type == TransportType.TELEPORTATION_SPELL) {
                    if (spell == null)
                        spell = transport.getDisplayInfo();
                    if (transport.getItemRequirements() != null)
                        for (ItemRequirement req : transport.getItemRequirements().getRequirements())
                            if (req.getQuantity() > 0 && !held(carried, req.getItemIds(), req.getQuantity())) {
                                carriedOf(carried, req.getStaffIds(), ids, wornDone);
                                carriedOf(carried, req.getOffhandIds(), ids, wornDone);
                            }
                    continue;
                }
                if ((type != TransportType.TELEPORTATION_ITEM && type != TransportType.QUETZAL_WHISTLE
                    && type != TransportType.TELEPORTATION_BOX) || transport.getItemRequirements() == null)
                    continue;
                for (int[] variants : transport.getItemRequirements().getItems())
                    for (int id : variants)
                        ids.add(id);
            }
        }
        return ids.isEmpty() && spell == null ? null : new RouteItemCue(ids, spell, wornDone);
    }

    private static boolean held(Map<Integer, Integer> carried, int[] ids, int quantity) {
        if (ids != null)
            for (int id : ids)
                if (carried.getOrDefault(id, 0) >= quantity)
                    return true;
        return false;
    }

    /** Adds the ids of {@code candidates} the player carries to both sets: a stand-in that must be wielded. */
    private static void carriedOf(Map<Integer, Integer> carried, int[] candidates, Set<Integer> ids, Set<Integer> wornDone) {
        if (candidates != null)
            for (int id : candidates)
                if (carried.getOrDefault(id, 0) > 0) {
                    ids.add(id);
                    wornDone.add(id);
                }
    }

    /** The index of the bank the route withdraws at (the first banked step), or -1 when it withdraws nothing. */
    static int bankStep(RouteOption route) {
        if (route == null || !route.isViaBank())
            return -1;
        List<PathStep> path = route.getPath();
        for (int i = 0; i < path.size(); i++)
            if (path.get(i).isBankVisited())
                return i;
        return -1;
    }

    /** Whether the item teleports only from the worn slot: none of its inventory options uses it. */
    static boolean wornOnly(String[] inventoryActions) {
        if (inventoryActions == null)
            return true;
        for (String action : inventoryActions) {
            if (action == null)
                continue;
            for (String verb : USE_VERBS)
                if (action.contains(verb))
                    return false;
        }
        return true;
    }
}

package gps;

import java.awt.Color;
import java.awt.Image;
import java.awt.image.BufferedImage;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

/**
 * The widget mark for the route's next item, built once per item and kept by the overlay: the
 * client's outline of the sprite thickened by one pixel outward, plus a light fill of the sprite.
 * Quest Helper marks its items with the same one-pixel ring and fill from an always-on-top overlay,
 * which draws after the inventory's own draw hook where this mark lands; on an item both plugins
 * want, its ring covers the inner pixel of ours and the outer ring stays visible in this plugin's
 * colour. The outline is drawn one pixel up and left of the slot, the fill at the slot.
 */
final class RouteItemMark {
    final BufferedImage outline;
    final Image fill;

    private RouteItemMark(BufferedImage outline, Image fill) {
        this.outline = outline;
        this.fill = fill;
    }

    static RouteItemMark of(ItemManager itemManager, int itemId, int quantity, Color colour) {
        BufferedImage sprite = itemManager.getImage(itemId, quantity, false);
        BufferedImage ring = itemManager.getItemOutline(itemId, quantity, colour);
        return new RouteItemMark(thickened(sprite, ring, colour.getRGB()),
            ImageUtil.fillImage(sprite, ColorUtil.colorWithAlpha(colour, 65)));
    }

    /**
     * The ring plus every pixel touching it from outside the sprite, in {@code rgb}, on a canvas one
     * pixel larger on each side so a ring at the sprite's edge still grows.
     */
    static BufferedImage thickened(BufferedImage sprite, BufferedImage ring, int rgb) {
        int w = ring.getWidth(), h = ring.getHeight();
        BufferedImage out = new BufferedImage(w + 2, h + 2, BufferedImage.TYPE_INT_ARGB);
        for (int x = 0; x < w + 2; x++) {
            for (int y = 0; y < h + 2; y++) {
                int ringPixel = pixel(ring, x - 1, y - 1);
                if (ringPixel >>> 24 != 0) {
                    out.setRGB(x, y, ringPixel);
                    continue;
                }
                if (pixel(sprite, x - 1, y - 1) >>> 24 == 0 && touchesRing(ring, x - 1, y - 1))
                    out.setRGB(x, y, rgb);
            }
        }
        return out;
    }

    private static boolean touchesRing(BufferedImage ring, int x, int y) {
        for (int dx = -1; dx <= 1; dx++)
            for (int dy = -1; dy <= 1; dy++)
                if (pixel(ring, x + dx, y + dy) >>> 24 != 0)
                    return true;
        return false;
    }

    private static int pixel(BufferedImage image, int x, int y) {
        return x < 0 || y < 0 || x >= image.getWidth() || y >= image.getHeight() ? 0 : image.getRGB(x, y);
    }
}

package gps;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Marks the items the displayed route needs with a {@link RouteItemMark} in the "Next item" colour
 * (Quest Helper's look, a ring thicker so both show on an item both plugins want): in the inventory
 * and the equipment tab the next step's item (not a worn fairy-ring staff: worn, it is done), in an
 * open bank every slot the route's bank step still has to supply. A worn-only item sitting in the bag says "Equip": the step cannot be taken until it
 * is worn.
 */
final class RouteItemOverlay extends WidgetItemOverlay {
    private final ShortestPathPlugin plugin;
    private final Map<Long, RouteItemMark> marks = new HashMap<>();
    private Color marksColour;

    RouteItemOverlay(ShortestPathPlugin plugin) {
        this.plugin = plugin;
        showOnInventory();
        showOnEquipment();
        showOnBank();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem item) {
        if (!plugin.display().highlightRouteItem)
            return;
        int group = WidgetUtil.componentToInterface(item.getWidget().getId());
        if (group == InterfaceID.BANKMAIN || group == InterfaceID.SHARED_BANK) {
            if (!plugin.bankPickupIds().contains(itemId))
                return;
        }
        else {
            RouteItemCue cue = plugin.nextStepItems();
            if (cue == null || !cue.itemIds.contains(itemId) || (group == InterfaceID.WORNITEMS && cue.wornDone.contains(itemId)))
                return;
        }
        Rectangle bounds = item.getCanvasBounds();
        Color colour = plugin.display().colourRouteItem;
        RouteItemMark mark = mark(itemId, item.getQuantity(), colour);
        graphics.drawImage(mark.outline, bounds.x - 1, bounds.y - 1, null);
        graphics.drawImage(mark.fill, bounds.x, bounds.y, null);
        if ((group == InterfaceID.INVENTORY || group == InterfaceID.BANKSIDE) && plugin.wornOnly(itemId)) {
            graphics.setFont(FontManager.getRunescapeSmallFont());
            int x = bounds.x + 1;
            int y = bounds.y + bounds.height - 2;
            graphics.setColor(Color.BLACK);
            graphics.drawString("Equip", x + 1, y + 1);
            graphics.setColor(colour);
            graphics.drawString("Equip", x, y);
        }
    }

    /** The mark for an item, built on first sight and dropped with the colour that made it. */
    private RouteItemMark mark(int itemId, int quantity, Color colour) {
        if (!colour.equals(marksColour) || marks.size() > 64) {
            marks.clear();
            marksColour = colour;
        }
        return marks.computeIfAbsent(((long) itemId << 32) | quantity,
            k -> RouteItemMark.of(plugin.getItemManager(), itemId, quantity, colour));
    }
}

