final class RouteListView extends JPanel {
    // The found routes now span more than this multiple of the cheapest: the good options are in,
    // the search is grinding out longer alternatives.
    static final int LONG_ROUTE_MULTIPLE = 3;

    private final ShortestPathPlugin plugin;
    // Opens the tier menu for a method (the catalog owns it; both views share one exclusion set).
    private final BiConsumer<Component, TeleportMethod> priorityMenu;
    // Fixed (non-scrolling) slot for the routes header, mounted above the card scroll area so the
    // count and controls stay visible while the cards scroll.
    private final JPanel headerHolder = new JPanel();
    private final JPanel listPanel = new JPanel();
    // The last shown inputs, for the header's busy note and the cards' status markers.
    private List<RouteOption> routes = List.of();
    private Map<TeleportMethod, MethodAvailability> unavailable = Map.of();

    RouteListView(ShortestPathPlugin plugin, BiConsumer<Component, TeleportMethod> priorityMenu) {
        super(new BorderLayout());
        this.plugin = plugin;
        this.priorityMenu = priorityMenu;
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        // Top-anchor the content so a short list keeps each row at its natural height. The wrapper
        // tracks the viewport width: without that, HORIZONTAL_SCROLLBAR_NEVER still lays the view out
        // at its preferred width and CLIPS the overflow at the right edge (the "scrollbar eats the
        // cards" effect) instead of shrinking the rows to fit.
        ScrollableBox listWrapper = new ScrollableBox(new BorderLayout());
        listWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        listWrapper.add(listPanel, BorderLayout.NORTH);
        JScrollPane scroll = new JScrollPane(listWrapper,
            ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
            ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        headerHolder.setLayout(new BoxLayout(headerHolder, BoxLayout.Y_AXIS));
        headerHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
        add(headerHolder, BorderLayout.NORTH);
        add(scroll, BorderLayout.CENTER);
    }

    /**
     * Shows {@code routes} (as they stream in; the previous list was cleared when the generation
     * started), highlighting {@code selected}; the header appears once there is a target, a
     * generation or a result to head.
     */
    void show(List<RouteOption> newRoutes, RouteOption selected, boolean calculating, boolean hasTarget,
        Map<TeleportMethod, MethodAvailability> newUnavailable) {
        routes = newRoutes;
        unavailable = newUnavailable;
        headerHolder.removeAll();
        if (hasTarget || calculating || !routes.isEmpty())
            headerHolder.add(header(routes.size(), calculating));
        headerHolder.revalidate();
        headerHolder.repaint();
        listPanel.removeAll();
        for (int i = 0; i < routes.size(); i++) {
            listPanel.add(card(i, routes.get(i), routes.get(i) == selected));
            listPanel.add(verticalGap(6));
        }
        listPanel.revalidate();
        listPanel.repaint();
    }

    /**
     * The ETA is the route's full configured cost: travel time, the bank detour, AND the
     * implicit cost modifiers (charged items, transport type, currency). The modifiers are
     * REAL-WORLD corrections, not preferences: tick-optimal cost is a lower bound no human hits,
     * and interacting with a method (finding the item, its menu, the confirm click) has latency
     * the raw path math cannot see, so the corrected number is the honest estimate. Explicit
     * priorities stay outside (they are the chip): list order = this ETA + priority chips,
     * nothing hidden. Static for tests.
     */
    static int routeEtaUnits(RouteOption route) {
        return route.getTotalCost();
    }

    static int routeEtaSeconds(RouteOption route) {
        return (int) Math.ceil(routeEtaUnits(route) * CostUnits.SECONDS_PER_UNIT);
    }

    /** Seconds as "59s" or "1m 5s". */
    static String formatDuration(int seconds) {
        if (seconds < 60)
            return seconds + "s";
        return (seconds / 60) + "m " + (seconds % 60) + "s";
    }

    /**
     * Whether the found routes already span more than {@link #LONG_ROUTE_MULTIPLE} times the
     * cheapest: the good options are in and fully usable, and the search is grinding out longer
     * alternatives, so the busy note says so instead of a bare "calculating".
     */
    static boolean searchingLongerRoutes(List<RouteOption> routes) {
        if (routes.isEmpty())
            return false;
        int min = Integer.MAX_VALUE;
        int max = 0;
        for (RouteOption route : routes) {
            int cost = route.getTotalCost();
            min = Math.min(min, cost);
            max = Math.max(max, cost);
        }
        return max > (long) min * LONG_ROUTE_MULTIPLE;
    }

    /**
     * The results section: a bold orange "Routes (N)" title (with a quiet "calculating" note while
     * the generation streams) over a centred control panel: bordered, coloured icon buttons for
     * more routes (green plus), refresh (blue) and clear (red). Tooltips explain each.
     */
    private JPanel header(int count, boolean calculating) {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(ColorScheme.DARK_GRAY_COLOR);
        // Extra top inset separates the routes header from the search controls and notes above it.
        section.setBorder(new EmptyBorder(10, 0, 6, 0));
        section.setAlignmentX(Component.LEFT_ALIGNMENT);
        section.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        JPanel titleRow = new JPanel(new BorderLayout(5, 0));
        titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        JLabel title = new JLabel(calculating && count == 0 ? "Routes" : "Routes (" + count + ")");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(ColorScheme.BRAND_ORANGE);
        titleRow.add(title, BorderLayout.WEST);
        if (calculating) {
            boolean longer = searchingLongerRoutes(routes);
            JLabel busy = new JLabel(longer ? "longer routes…" : "calculating…",
                RouteIcons.BANNER_BUSY, SwingConstants.LEADING);
            busy.setIconTextGap(4);
            busy.setFont(FontManager.getRunescapeSmallFont());
            busy.setForeground(Color.GRAY);
            busy.setToolTipText(longer
                ? "Your best routes are ready to use; still searching for longer alternatives"
                : "Calculating routes…");
            titleRow.add(busy, BorderLayout.EAST);
        }
        section.add(titleRow);

        JPanel controls = new JPanel(new FlowLayout(FlowLayout.CENTER, 6, 0));
        controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
        controls.setAlignmentX(Component.LEFT_ALIGNMENT);
        controls.setBorder(new EmptyBorder(6, 0, 0, 0));
        controls.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        if (!calculating && !routes.isEmpty() && plugin.canLoadMoreRoutes()) {
            controls.add(controlButton(RouteIcons.SHOW_MORE, RouteIcons.SHOW_MORE_HOVER,
                "Search for more routes", plugin::loadMoreRoutes));
        }
        if (!calculating) {
            controls.add(controlButton(RouteIcons.CTRL_REFRESH, RouteIcons.CTRL_REFRESH_HOVER,
                "Recalculate the routes to the current destination", plugin::recomputeAlternatives));
        }
        controls.add(controlButton(RouteIcons.CTRL_CLEAR, RouteIcons.CTRL_CLEAR_HOVER,
            "Clear the current destination and its route", plugin::clearTarget));
        section.add(controls);
        return section;
    }

    /** A bordered, colour-icon control button (rollover swaps the icon; the panel lifts on hover). */
    private static JButton controlButton(ImageIcon icon, ImageIcon hover, String tooltip, Runnable action) {
        JButton button = new JButton(icon);
        button.setRolloverIcon(hover);
        button.setFocusPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
        button.setToolTipText(tooltip);
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            new EmptyBorder(3, 12, 3, 12)));
        button.addActionListener(e -> action.run());
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
            }
        });
        return button;
    }

    private JPanel card(int index, RouteOption route, boolean selected) {
        JPanel card = new JPanel(new BorderLayout());
        // Selection reads as a filled state: slightly lighter card plus a 3px orange edge stripe,
        // instead of the old full orange outline. Children are non-opaque so one background rules.
        Color cardBg = selected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR;
        card.setBackground(cardBg);
        card.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(0x3A, 0x3A, 0x3A)),
            BorderFactory.createMatteBorder(0, 3, 0, 0, selected ? ColorScheme.BRAND_ORANGE : cardBg)));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        JPanel topRow = new JPanel(new BorderLayout());
        topRow.setOpaque(false);
        // Left inset 4 (not the methods' 8): the pin glyph is centred in its 16px canvas while the
        // method dots start at their canvas edge, so the smaller inset lines the pin up with the
        // dot column below.
        topRow.setBorder(new EmptyBorder(4, 4, 2, 5));

        boolean reaches = plugin.routeReachesTarget(route);
        // Shown-on-map pin leads the card (orange when this route is the one drawn), then the
        // quiet rank chip, then the ETA, the decision-making number.
        JPanel left = new JPanel(new FlowLayout(FlowLayout.LEADING, 0, 0));
        left.setOpaque(false);
        // Pin and rank read as one unit (no gap); the clock and ETA sit a space apart.
        JLabel rank = new JLabel(Integer.toString(index + 1),
            selected ? RouteIcons.SHOW_ACTIVE : RouteIcons.SHOW, SwingConstants.LEADING);
        rank.setIconTextGap(1);
        rank.setFont(FontManager.getRunescapeSmallFont());
        rank.setForeground(Color.GRAY);
        left.add(rank);
        // The ETA counts travel plus the bank detour; ordering additionally counts preference
        // modifiers (transport type, currency), so a route can be faster yet ranked lower.
        JLabel eta = new JLabel(formatDuration(routeEtaSeconds(route)), RouteIcons.CLOCK, SwingConstants.LEADING);
        eta.setIconTextGap(3);
        eta.setBorder(new EmptyBorder(0, 12, 0, 0));
        eta.setFont(FontManager.getRunescapeBoldFont());
        eta.setForeground(selected ? ColorScheme.BRAND_ORANGE : Color.WHITE);
        eta.setToolTipText("<html>Estimated time, assuming you run"
            + (route.isViaBank() ? " (includes the bank detour)" : "")
            + ".<br>Includes your cost modifiers: real-world corrections for the clicks and"
            + "<br>menus a method costs beyond raw travel (charged items, transport type,"
            + "<br>currency). Routes are ordered by this plus the green/red priority chips.</html>");
        if (!reaches)
            eta.setToolTipText("The target can't be reached; this ends at the closest reachable tile");
        left.add(eta);
        // Explicit-priority chip beside the ETA. Implicit cost modifiers are inside the ETA
        // itself now, so the chip is purely the user's prefer/avoid/walk/bank bias, and list
        // order is always ETA plus chip, nothing hidden. Green = ranks as if faster, red = slower.
        int adjustment = plugin.routeAdjustmentSeconds(route);
        if (adjustment != 0) {
            JLabel priorityChip = new JLabel((adjustment > 0 ? "+" : "−") + Math.abs(adjustment) + "s");
            priorityChip.setFont(FontManager.getRunescapeSmallFont());
            priorityChip.setBorder(new EmptyBorder(0, 4, 0, 0));
            priorityChip.setForeground(adjustment < 0
                ? new Color(70, 200, 90) : ColorScheme.PROGRESS_ERROR_COLOR);
            priorityChip.setToolTipText("Your priority bias: changes this route's position, not its ETA");
            left.add(priorityChip);
        }
        topRow.add(left, BorderLayout.WEST);

        JPanel right = new JPanel(new FlowLayout(FlowLayout.TRAILING, 5, 0));
        right.setOpaque(false);
        if (route.isViaBank()) {
            // The bank detour as a compact header chip; the coin glyph on the method row below
            // marks WHICH method the detour is for. The tooltip states WHAT gets withdrawn,
            // resolved on the CLIENT thread (item names come from getItemDefinition, which
            // asserts it; the EDT crash of 2026-08-15) and swapped in when ready.
            JLabel bankChip = new JLabel(RouteIcons.IN_BANK);
            // Connectors (a jungle bush, a dig) are bank-gated too but have no method row; the
            // placeholder names them by object so the chip never reads "for: <nothing>".
            StringBuilder needs = new StringBuilder(joinLabels(route.getBankMethods()));
            for (Transport connector : route.getBankTransports()) {
                String text = RouteDirections.objectText(connector);
                if (text != null && needs.indexOf(text) < 0)
                    needs.append(needs.length() == 0 ? "" : ", ").append(text);
            }
            bankChip.setToolTipText("<html>Walks to a bank first; withdraws the item for: <b>"
                + escapeHtml(needs.toString()) + "</b></html>");
            plugin.getClientThread().invokeLater(() -> {
                List<String> pickups = RouteDirections.pickupLines(plugin, route);
                if (!pickups.isEmpty()) {
                    StringBuilder tip = new StringBuilder("<html>Withdraws at a bank:");
                    for (String pickup : pickups)
                        tip.append("<br>• <b>").append(escapeHtml(pickup)).append("</b>");
                    SwingUtilities.invokeLater(() ->
                        bankChip.setToolTipText(tip.append("</html>").toString()));
                }
            });
            right.add(bankChip);
        }
        topRow.add(right, BorderLayout.EAST);
        card.add(topRow, BorderLayout.NORTH);

        JPanel methods = new JPanel();
        methods.setLayout(new BoxLayout(methods, BoxLayout.Y_AXIS));
        methods.setOpaque(false);
        methods.setBorder(new EmptyBorder(1, 8, 5, 5));
        if (!reaches) {
            methods.add(noteRow("<font color='#FF981F'>Can't reach the target, ends at the closest point.</font>",
                "This destination isn't reachable; the route stops at the nearest tile GPS can get to."));
        }
        // Each method row reveals its OWN priority control only while the pointer is over that row.
        for (int m = 0; m < route.getMethods().size(); m++)
            methods.add(methodRow(route.getMethods().get(m), route, route.walkBefore(m)));
        // One walking row for the WHOLE route: every leg between methods plus the trailing leg;
        // per-method walk counts live in the method tooltips instead of cluttering each row.
        int totalWalk = route.getTrailingWalkSteps();
        for (int m = 0; m < route.getMethods().size(); m++)
            totalWalk += route.walkBefore(m);
        if (totalWalk > 0 || route.isWalkOnly())
            methods.add(walkRow(totalWalk));
        // One sailing row for the whole route, mirroring the walk row: total sea tiles across
        // every sailing leg (distances inverted from the legs' durations).
        int totalSail = 0;
        for (int m = 0; m < route.getMethods().size(); m++) {
            if (route.getMethods().get(m).getType() == TransportType.SAILING
                && m < route.getMethodDurations().size()) {
                totalSail += SailingSea.tilesFromDuration(route.getMethodDurations().get(m));
            }
        }
        if (totalSail > 0)
            methods.add(sailRow(totalSail));
        card.add(methods, BorderLayout.CENTER);

        // The best route is the fallback whenever nothing else is selected, so hiding it never
        // shows anything else: say what the click does, not what it cannot (plan step N12).
        card.setToolTipText(selected
            ? (index == 0 ? "Showing on map (the best route)" : "Showing on map, click to hide")
            : "Click to show this route on the map");
        card.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        // A click anywhere on the card (its icon controls aside) shows that route on the map.
        addClickRecursively(card, new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                plugin.selectRoute(index);
            }
        });
        return card;
    }

    /**
     * Fires the handler with true when the pointer enters the component tree and false when it
     * truly leaves it (Swing fires exit when moving onto a CHILD, so exits are checked against the
     * root's bounds). Used to reveal a route row's priority control only while hovering that row.
     */
    private static void addHoverRecursively(Component root, Consumer<Boolean> handler) {
        MouseAdapter hover = new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                handler.accept(true);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                Point p = SwingUtilities.convertPoint((Component) e.getSource(), e.getPoint(), root);
                if (!root.contains(p))
                    handler.accept(false);
            }
        };
        addHoverListener(root, hover);
    }

    private static void addHoverListener(Component component, MouseAdapter hover) {
        component.addMouseListener(hover);
        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents())
                addHoverListener(child, hover);
        }
    }

    /** The sailing twin of the walk row: sea-blue dot, total tiles sailed across the route. */
    private static JPanel sailRow(int tiles) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setOpaque(false);
        JLabel dot = new JLabel(dot(SAIL_DOT_COLOUR));
        dot.setToolTipText("Sailing");
        row.add(verticallyCentered(dot), BorderLayout.WEST);
        JLabel text = wrappedLabel("Sail <font color='#9E9E9E'>" + tiles + " tiles</font>");
        text.setVerticalAlignment(SwingConstants.CENTER);
        text.setToolTipText("Total open-sea distance across this route's sailing legs"
            + " (ETAs assume a mid-tier hull speed)");
        row.add(text, BorderLayout.CENTER);
        return row;
    }

    /**
     * The walking-leg row, shaped exactly like a method row: a neutral grey dot in the
     * category-dot column, then the step count.
     */
    private static JPanel walkRow(int steps) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setOpaque(false);

        JLabel dot = new JLabel(dot(WALK_DOT_COLOUR));
        dot.setToolTipText("Walking");
        row.add(verticallyCentered(dot), BorderLayout.WEST);

        JLabel text = wrappedLabel(steps > 0
            ? "Walk <font color='#9E9E9E'>" + steps + " tiles</font>"
            : "Walk");
        text.setVerticalAlignment(SwingConstants.CENTER);
        text.setToolTipText("Total walking across this route: every leg between methods plus the final stretch");
        row.add(text, BorderLayout.CENTER);
        return row;
    }

    /**
     * A route-card method row: category dot plus wrapped label plus the priority control.
     * Methods whose required item must first be withdrawn from the bank get a bank glyph, so it
     * is clear which method the route's bank detour is for. {@code walkBefore} tiles of walking to
     * reach the method go into the tooltip.
     */
    private JPanel methodRow(TeleportMethod method, RouteOption route, int walkBefore) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setOpaque(false);

        JLabel dot = new JLabel(methodDot(method));
        dot.setAlignmentY(Component.CENTER_ALIGNMENT);
        dot.setToolTipText(method.getType() == TransportType.TELEPORTATION_ITEM
            ? (method.isConsumable() ? "Item (charged: consumes a charge or the item)" : "Item (permanent: reusable)")
            : method.category());
        MethodAvailability status = unavailable.get(method);
        boolean bankGated = route.getBankMethods().contains(method);
        // The dot and any inline glyphs form a left-to-right box, centred against each other; the
        // whole box is then centred vertically against the (possibly two-line) label.
        JPanel west = new JPanel();
        west.setLayout(new BoxLayout(west, BoxLayout.X_AXIS));
        west.setOpaque(false);
        west.add(dot);
        // Network methods carry their real glyph inline after the dot (like the bank marker and
        // the overlay's fairy-ring step), so "C K S" reads as a fairy-ring code at a glance.
        String networkGlyph = method.getType() == TransportType.FAIRY_RING ? "fairy_ring"
            : method.getType() == TransportType.SPIRIT_TREE ? "spirit_tree" : null;
        if (networkGlyph != null) {
            JLabel glyph = new JLabel(RouteIcons.destinationIcon(networkGlyph));
            glyph.setAlignmentY(Component.CENTER_ALIGNMENT);
            glyph.setBorder(new EmptyBorder(0, 3, 0, 0));
            glyph.setToolTipText(method.category());
            west.add(glyph);
        }
        if (bankGated) {
            JLabel bankMarker = new JLabel(RouteIcons.IN_BANK);
            bankMarker.setAlignmentY(Component.CENTER_ALIGNMENT);
            bankMarker.setBorder(new EmptyBorder(0, 3, 0, 0));
            // Client-thread resolution, same as the header chip: item names assert it.
            bankMarker.setToolTipText("This method needs an item from your bank; the route withdraws it first");
            plugin.getClientThread().invokeLater(() -> {
                String pickup = RouteDirections.pickupLineFor(plugin, route, method);
                if (pickup != null) {
                    SwingUtilities.invokeLater(() -> bankMarker.setToolTipText(
                        "<html>From your bank: <b>" + escapeHtml(pickup) + "</b></html>"));
                }
            });
            west.add(bankMarker);
        }
        // The availability map records IN_BANK in every mode; on a route it is already shown by
        // the bank marker above, so only add the status marker for other, distinct reasons.
        if (status != null && !bankGated) {
            JLabel statusMarker = statusMarker(plugin, status, method);
            statusMarker.setAlignmentY(Component.CENTER_ALIGNMENT);
            statusMarker.setBorder(new EmptyBorder(0, 3, 0, 0));
            west.add(statusMarker);
        }
        row.add(verticallyCentered(west), BorderLayout.WEST);

        // No per-row step counts: the card's walk row totals every leg, and this row's tooltip
        // still carries its own walk-to-reach detail. Route rows sit without their category header,
        // so network methods name their vehicle ("Balloon to Varrock", not a bare "Varrock").
        JLabel text = wrappedLabel(escapeHtml(method.routeLabel()));
        text.setVerticalAlignment(SwingConstants.CENTER);
        text.setToolTipText(walkBefore > 0
            ? "<html>Walk " + walkBefore + " tiles to reach this method.<br>" + methodTooltipBody(method) + "</html>"
            : methodTooltip(method));
        row.add(text, BorderLayout.CENTER);

        // Shows the method's CURRENT tier: near-invisible dash at rest when normal (so the row
        // stays quiet), the stacked arrows when a preference is set. Hovering the row brightens
        // it; clicking opens the priority menu (prefer/avoid tiers; exclude at the bottom).
        MethodPriority cardTier = plugin.getMethodPriority(method);
        final IconActionLabel[] holder = new IconActionLabel[1];
        holder[0] = new IconActionLabel(
            cardTier == MethodPriority.NORMAL ? RouteIcons.PRIORITY_NEUTRAL_DIM : priorityRestIcon(cardTier),
            priorityHoverIcon(cardTier),
            "Priority: " + cardTier.label + ", click to change",
            () -> priorityMenu.accept(holder[0], method));
        IconActionLabel priority = holder[0];
        JPanel actionWrap = new JPanel(new GridBagLayout());
        actionWrap.setOpaque(false);
        actionWrap.setPreferredSize(new Dimension(CONTROL_SIZE, CONTROL_SIZE));
        actionWrap.add(control(priority));
        row.add(actionWrap, BorderLayout.EAST);

        // Reveal only this row's control on hover, not the whole card.
        final MethodPriority hoverTier = cardTier;
        addHoverRecursively(row, hovered ->
            priority.setRestIcon(hovered
                ? priorityHoverIcon(hoverTier)
                : (hoverTier == MethodPriority.NORMAL
                    ? RouteIcons.PRIORITY_NEUTRAL_DIM : priorityRestIcon(hoverTier))));
        return row;
    }
}

package gps;

import java.util.List;
import java.util.Set;
import lombok.Getter;
import gps.pathfinder.PathStep;
import gps.transport.Transport;

/**
 * One alternative route to the target, produced by {@link AlternativeRoutesService}. Each route is a
 * shortest path under the constraint that it uses a different set of teleport/transport methods than
 * the other routes in the same result list.
 */
@Getter
public final class RouteOption {
    /**
     * The full tile path, as returned by the pathfinder.
     */
    private final List<PathStep> path;
    /**
     * The teleport/transport methods used along the path, in travel order. Empty for a walk-only route.
     */
    private final List<TeleportMethod> methods;
    /**
     * Path index of the edge each method sits on, parallel to {@link #methods}: the index of the path
     * step the method arrives at. Authoritative method positions for the directions overlay — the
     * route was computed with the planning config's availability, so its methods cannot be reliably
     * re-derived against the main config's.
     */
    private final List<Integer> methodEdgeIndexes;
    /**
     * Travel time of each method's transport in game ticks, parallel to {@link #methods} — for the
     * directions overlay's time estimates.
     */
    private final List<Integer> methodDurations;
    /**
     * Blended search cost in CostUnits (run-tiles, 0.3s each): time-normalized walk + transport
     * travel, plus any configured method weights. Routes are ordered by this; lower is faster.
     */
    private final int totalCost;
    /**
     * The path's cost without any configured weights, in CostUnits (run-tiles, 0.3s each): its ETA.
     * Equal to {@link #totalCost} when no weights applied to this route.
     */
    private final int rawCost;
    /**
     * Whether the path actually reaches the exact target. When false it ends at the closest reachable
     * tile (mirrors Shortest Path's own behaviour for unreachable targets, e.g. an NPC/object tile).
     */
    private final boolean reached;
    /**
     * The subset of {@link #methods} that require an item that must first be withdrawn from the bank —
     * the path includes a walk to a bank before each of these is used. Empty when the route needs no
     * bank visit. Lets the panel say <em>which</em> method the bank detour is for.
     */
    private final Set<TeleportMethod> bankMethods;
    /**
     * Plain connectors (not methods) the route can only use after the bank - a jungle bush
     * needing a banked machete. Named in the withdraw step; never on the card.
     */
    private final List<Transport> bankTransports;
    /**
     * Tiles walked before each method, parallel to {@link #methods} (walking to a minecart, a fairy
     * ring, a bank, ...). Plain connectors along the way (doors, stairs, shortcuts) count into the leg.
     */
    private final List<Integer> walkBeforeSteps;
    /**
     * Tiles walked after the last method to the destination; the whole walk for walk-only routes.
     */
    private final int trailingWalkSteps;
    /**
     * For round trips (out to the destination and back to the start): the path index of the
     * turnaround — the destination tile where the outbound leg ends. -1 for ordinary routes.
     * A round trip's path ends where it began, and its return leg often retraces the outbound
     * street, so progress tracking and the arrival check gate the return leg behind this index —
     * otherwise walking OUT reads as coming back (instant false arrival).
     */
    private final int turnaroundIndex;

    /**
     * DEPARTURE indexes of this route's sailing jumps: values i such that the path edge
     * path[i] -> path[i+1] is a SAILING leg. methodEdgeIndexes stores each transport edge by
     * its ARRIVAL step (scanMethods records edge (i-1)->i as i) — an implicit convention that
     * cost us an invisible off-by-one in the overlay (every sea leg permanently dashed); this
     * method is the single place that arithmetic lives now, pinned by RouteOptionTest.
     */
    public java.util.Set<Integer> sailingJumpDepartures() {
        // Memoized: the overlay asks once per rendered frame, and this object is immutable.
        // Benign race — concurrent first calls compute identical sets.
        java.util.Set<Integer> cached = sailingJumpDeparturesCache;
        if (cached != null)
            return cached;
        java.util.Set<Integer> departures = new java.util.HashSet<>();
        for (int i = 0; i < methods.size() && i < methodEdgeIndexes.size(); i++) {
            if (methods.get(i).getType() == gps.transport.TransportType.SAILING)
                departures.add(methodEdgeIndexes.get(i) - 1);
        }
        sailingJumpDeparturesCache = java.util.Collections.unmodifiableSet(departures);
        return sailingJumpDeparturesCache;
    }

    private transient volatile java.util.Set<Integer> sailingJumpDeparturesCache;

    public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
        List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
        List<Integer> walkBeforeSteps, int trailingWalkSteps) {
        this(path, methods, methodEdgeIndexes, methodDurations, totalCost, rawCost, reached, bankMethods,
            List.of(), walkBeforeSteps, trailingWalkSteps, -1);
    }

    public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
        List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
        List<Transport> bankTransports, List<Integer> walkBeforeSteps, int trailingWalkSteps) {
        this(path, methods, methodEdgeIndexes, methodDurations, totalCost, rawCost, reached, bankMethods,
            bankTransports, walkBeforeSteps, trailingWalkSteps, -1);
    }

    public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
        List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
        List<Integer> walkBeforeSteps, int trailingWalkSteps, int turnaroundIndex) {
        this(path, methods, methodEdgeIndexes, methodDurations, totalCost, rawCost, reached, bankMethods,
            List.of(), walkBeforeSteps, trailingWalkSteps, turnaroundIndex);
    }

    public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
        List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
        List<Transport> bankTransports, List<Integer> walkBeforeSteps, int trailingWalkSteps, int turnaroundIndex) {
        this.path = path;
        this.methods = methods;
        this.methodEdgeIndexes = methodEdgeIndexes;
        this.methodDurations = methodDurations;
        this.totalCost = totalCost;
        this.rawCost = rawCost;
        this.reached = reached;
        this.bankMethods = bankMethods;
        this.bankTransports = bankTransports == null ? List.of() : bankTransports;
        this.walkBeforeSteps = walkBeforeSteps;
        this.trailingWalkSteps = trailingWalkSteps;
        this.turnaroundIndex = turnaroundIndex;
    }

    /** Whether this route is a round trip — see {@link #turnaroundIndex}. */
    public boolean isRoundTrip() {
        return turnaroundIndex >= 0;
    }

    /**
     * Tiles walked before the method at {@code index}, or 0 when unknown.
     */
    public int walkBefore(int index) {
        return (index >= 0 && index < walkBeforeSteps.size()) ? walkBeforeSteps.get(index) : 0;
    }

    /**
     * Whether one of this route's methods requires a bank withdrawal first (see {@link #bankMethods}).
     */
    public boolean isViaBank() {
        return !bankMethods.isEmpty() || !bankTransports.isEmpty();
    }

    /** Whether every method is a sailing leg: the route never leaves the water system. */
    public boolean isPureSail() {
        if (methods.isEmpty())
            return false;
        for (TeleportMethod method : methods) {
            if (method.getType() != gps.transport.TransportType.SAILING)
                return false;
        }
        return true;
    }

    public boolean isWalkOnly() {
        return methods.isEmpty();
    }

    /** The method whose edge arrives at path index {@code arriveIndex}, or null when that edge is walking. */
    public TeleportMethod methodArrivingAt(int arriveIndex) {
        for (int m = 0; m < methodEdgeIndexes.size() && m < methods.size(); m++) {
            if (methodEdgeIndexes.get(m) == arriveIndex)
                return methods.get(m);
        }
        return null;
    }
}

package gps;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The ranking preferences (plan step L14, out of the plugin class): per-method tiers (see
 * MethodPriority), the walk preference and the bank bias, and the effective order they produce.
 * Preferences re-rank the routes a generation found; they never touch the search. Exclusion is
 * not a tier here: it lives in the plugin's exclusion set (it affects the search) and reads back
 * as EXCLUDED, a mask over the stored tier so re-including restores the user's tuning.
 */
@Slf4j
final class RoutePreferences {
    static final String CONFIG_KEY_PRIORITIES = "methodPriorities";
    static final String CONFIG_KEY_WALK_PREFERENCE = "walkPreferenceSeconds";
    static final String CONFIG_KEY_BANK_PREFERENCE = "bankPreferenceSeconds";

    /** One serialized priority entry (method identity + tier), for the config JSON. */
    private static final class PriorityEntry {
        TeleportMethod method;
        MethodPriority priority;
    }

    // Method -> ranking-bias tier. EXCLUDED and NORMAL never appear here.
    private final Map<TeleportMethod, MethodPriority> priorities = new ConcurrentHashMap<>();
    // The plugin's live exclusion set, read for the EXCLUDED mask.
    private final Set<TeleportMethod> exclusions;
    private final BooleanSupplier keepSailingFirst;
    // Suppliers: the plugin's injected services arrive after its fields initialise.
    private final Supplier<ConfigManager> configManager;
    private final Supplier<Gson> gson;
    private final String configGroup;

    private volatile int walkPreferenceSeconds;
    private volatile int bankPreferenceSeconds;

    RoutePreferences(Set<TeleportMethod> exclusions, BooleanSupplier keepSailingFirst,
        Supplier<ConfigManager> configManager, Supplier<Gson> gson, String configGroup) {
        this.exclusions = exclusions;
        this.keepSailingFirst = keepSailingFirst;
        this.configManager = configManager;
        this.gson = gson;
        this.configGroup = configGroup;
    }

    /** The method's tier: EXCLUDED when in the exclusion set, else its stored tier or NORMAL. */
    MethodPriority priorityOf(TeleportMethod method) {
        if (exclusions.contains(method))
            return MethodPriority.EXCLUDED;
        return priorities.getOrDefault(method, MethodPriority.NORMAL);
    }

    /** Stores a ranking tier (NORMAL removes the entry) and persists. EXCLUDED is not a stored tier. */
    void setTier(TeleportMethod method, MethodPriority tier) {
        if (tier == MethodPriority.EXCLUDED)
            throw new IllegalArgumentException("exclusion is not a stored tier");
        if (tier == MethodPriority.NORMAL)
            priorities.remove(method);
        else
            priorities.put(method, tier);
        save();
    }

    /** The walk-preference bias in seconds (negative effective ETA for the pure-walk route). */
    int walkPreferenceSeconds() {
        return walkPreferenceSeconds;
    }

    void setWalkPreferenceSeconds(int seconds) {
        configManager.get().setConfiguration(configGroup, CONFIG_KEY_WALK_PREFERENCE, seconds);
        walkPreferenceSeconds = seconds;
    }

    /** The bank-detour bias in seconds: positive prefers via-bank routes, negative avoids them. */
    int bankPreferenceSeconds() {
        return bankPreferenceSeconds;
    }

    void setBankPreferenceSeconds(int seconds) {
        configManager.get().setConfiguration(configGroup, CONFIG_KEY_BANK_PREFERENCE, seconds);
        bankPreferenceSeconds = seconds;
    }

    /**
     * The route's ranking adjustment in seconds: the sum of its methods' tiers, less the bank
     * bias for a via-bank route; or, for the pure-walk route, minus the walk preference (walking
     * wins ties up to that many seconds).
     */
    int adjustmentSeconds(RouteOption route) {
        if (route.getMethods().isEmpty())
            return -walkPreferenceSeconds;
        int seconds = 0;
        for (TeleportMethod method : route.getMethods())
            seconds += priorities.getOrDefault(method, MethodPriority.NORMAL).adjustSeconds;
        if (route.isViaBank())
            seconds -= bankPreferenceSeconds;
        return seconds;
    }

    /** Effective sort key: reached routes first, then raw cost plus the priority adjustment. */
    Comparator<RouteOption> effectiveOrder() {
        return Comparator
            .comparingInt((RouteOption r) -> r.isReached() ? 0 : 1)
            // At the helm, routes that STAY ON THE WATER outrank disembark-and-teleport chains
            // (capture 20260829-204334: every offer abandoned the boat at the nearest mooring
            // because the tick math favors teleports; a sailor mid-task wants the sea route
            // first, the land chains listed below). Sailing-section toggle, on by default.
            .thenComparingInt(r -> keepSailingFirst.getAsBoolean() && !r.isPureSail() ? 1 : 0)
            .thenComparingInt(r -> r.getTotalCost() + MethodPriority.unitsFromSeconds(adjustmentSeconds(r)));
    }

    /** A copy of the routes in effective order (stable). */
    List<RouteOption> sorted(List<RouteOption> routes) {
        List<RouteOption> sorted = new ArrayList<>(routes);
        sorted.sort(effectiveOrder());
        return sorted;
    }

    private void save() {
        try {
            List<PriorityEntry> entries = new ArrayList<>();
            for (Map.Entry<TeleportMethod, MethodPriority> e : priorities.entrySet()) {
                PriorityEntry entry = new PriorityEntry();
                entry.method = e.getKey();
                entry.priority = e.getValue();
                entries.add(entry);
            }
            configManager.get().setConfiguration(configGroup, CONFIG_KEY_PRIORITIES, gson.get().toJson(entries));
        }
        catch (Exception e) {
            log.warn("Failed to save method priorities", e);
        }
    }

    /** Loads the persisted tiers and biases (plugin start). */
    void load() {
        ConfigManager manager = configManager.get();
        try {
            String json = manager.getConfiguration(configGroup, CONFIG_KEY_PRIORITIES);
            if (json != null && !json.isEmpty()) {
                PriorityEntry[] saved = gson.get().fromJson(json, PriorityEntry[].class);
                if (saved != null) {
                    for (PriorityEntry entry : saved) {
                        if (entry != null && entry.method != null && entry.method.getType() != null
                            && entry.priority != null && entry.priority != MethodPriority.NORMAL
                            && entry.priority != MethodPriority.EXCLUDED) {
                            priorities.put(entry.method, entry.priority);
                        }
                    }
                }
            }
        }
        catch (Exception e) {
            log.warn("Failed to load method priorities", e);
        }
        Integer walk = manager.getConfiguration(configGroup, CONFIG_KEY_WALK_PREFERENCE, Integer.class);
        walkPreferenceSeconds = walk != null ? walk : 0;
        Integer bank = manager.getConfiguration(configGroup, CONFIG_KEY_BANK_PREFERENCE, Integer.class);
        bankPreferenceSeconds = bank != null ? bank : 0;
    }
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathStep;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pure route-progress selection: which path index the player has honestly reached. Extracted from
 * the directions overlay so the maze rules are unit-testable.
 * <p>
 * Straight-line proximity is wall-blind — standing one tile OUTSIDE a wall used to snap progress
 * onto an unreachable path tile, and maze corridors that double back within a few tiles teleported
 * the marker across walls. Eligibility is therefore based on WALKING distance (a small bounded BFS
 * through the collision map around the player): a candidate tile must be genuinely walkable-to in
 * roughly its straight-line distance, or it doesn't count. When no collision map is available yet,
 * the legacy straight-line rules apply unchanged.
 */
final class RouteProgress {
    /** Max index drift per update for near-line matches (honest travel, not teleports). */
    static final int STEP_WINDOW = 8;
    /** Max straight-line distance for near-line matches. */
    static final int NEAR_DISTANCE = 10;
    /** Walking may exceed the straight line by this much before a match reads as through-a-wall. */
    static final int REACH_SLACK = 2;
    /** BFS radius: the largest walking distance any eligibility rule can accept. */
    static final int REACH_RADIUS = NEAR_DISTANCE + REACH_SLACK;

    private RouteProgress() {
    }

    /** A selection: the reached path index and the walking distance to it (for the ETA). */
    static final class Result {
        final int index;
        final int distance;

        Result(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }

    /**
     * Walking distances (in steps, diagonals allowed) from the player to every tile within
     * {@code radius} steps, honouring walls via {@link CollisionMap#canStep}. Null when no map is
     * available (callers fall back to straight-line rules).
     */
    static Map<Integer, Integer> walkDistances(CollisionMap map, int fromPacked, int radius) {
        if (map == null)
            return null;
        Map<Integer, Integer> distances = new HashMap<>();
        distances.put(fromPacked, 0);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.add(fromPacked);
        int x = WorldPointUtil.unpackWorldX(fromPacked);
        int y = WorldPointUtil.unpackWorldY(fromPacked);
        int plane = WorldPointUtil.unpackWorldPlane(fromPacked);
        while (!queue.isEmpty()) {
            int tile = queue.poll();
            int steps = distances.get(tile);
            if (steps >= radius)
                continue;
            int tx = WorldPointUtil.unpackWorldX(tile);
            int ty = WorldPointUtil.unpackWorldY(tile);
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (dx == 0 && dy == 0)
                        continue;
                    int next = WorldPointUtil.packWorldPoint(tx + dx, ty + dy, plane);
                    if (!distances.containsKey(next)
                        && Math.max(Math.abs(tx + dx - x), Math.abs(ty + dy - y)) <= radius
                        && map.canStep(tile, next)) {
                        distances.put(next, steps + 1);
                        queue.add(next);
                    }
                }
            }
        }
        return distances;
    }

    /**
     * The path index the player has reached, or null to hold the previous estimate.
     *
     * @param path        the route's tiles
     * @param reachedIndex the previous selection (index drift is measured from here)
     * @param doorGate    first path index at/past an uncrossed door — only exact on-tile presence
     *                    counts from there on
     * @param returnGate  first index of a round trip's return leg while still outbound
     *                    ({@code Integer.MAX_VALUE} when not applicable)
     * @param playerPacked the player's tile
     * @param walk        walking distances around the player, or null for legacy straight-line rules
     */
    static Result select(List<PathStep> path, int reachedIndex, int doorGate, int returnGate,
        int playerPacked, Map<Integer, Integer> walk) {
        int best = -1;
        int bestDistance = Integer.MAX_VALUE;
        int bestOffset = Integer.MAX_VALUE;
        for (int i = 0; i < path.size(); i++) {
            if (i > returnGate)
                break;
            int packed = path.get(i).getPackedPosition();
            // distanceBetween is MAX_VALUE across planes, so other-plane tiles filter out here.
            int straight = WorldPointUtil.distanceBetween(packed, playerPacked);
            Integer walked = walk != null ? walk.get(packed) : null;
            boolean beyondDoor = i >= doorGate;
            boolean eligible;
            int metric;
            if (walk != null) {
                // Wall-aware rules: same tile always counts; "on path" needs a genuinely walkable
                // single step; near-line matches must be walkable in about their straight-line
                // distance, or the "closeness" is through a wall.
                if (beyondDoor)
                    eligible = straight == 0;
                else if (walked != null && walked <= 1)
                    eligible = true;
                else {
                    eligible = walked != null
                        && Math.abs(i - reachedIndex) <= STEP_WINDOW
                        && straight <= NEAR_DISTANCE
                        && walked <= straight + REACH_SLACK;
                }
                metric = walked != null ? walked : straight;
            }
            else {
                // Legacy straight-line rules (no collision map yet).
                boolean incremental = !beyondDoor && Math.abs(i - reachedIndex) <= STEP_WINDOW
                    && straight <= NEAR_DISTANCE;
                boolean onPath = straight <= (beyondDoor ? 0 : 1);
                eligible = incremental || onPath;
                metric = straight;
            }
            if (!eligible)
                continue;
            int offset = Math.abs(i - reachedIndex);
            if (metric < bestDistance || (metric == bestDistance && offset < bestOffset)) {
                best = i;
                bestDistance = metric;
                bestOffset = offset;
            }
        }
        return best < 0 ? null : new Result(best, bestDistance);
    }
}

package gps;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntSupplier;

/**
 * The alternative-routes session (plan step L9, out of the plugin class): the page of routes for
 * the current destination, which one is selected, which one the overlays draw, whether a
 * generation is in flight, what the last generation ran from and with, and the "more routes"
 * budget. Owned by the client thread; the volatile fields are read by the overlays and the panel.
 * The plugin keeps everything with a side effect (panel refreshes, the journey timer, plugin
 * messages, persistence); every decision here is a pure function of this state.
 */
final class RouteSession {
    // The cost cap for a generation, as a multiple of the best route's cost: only routes up to this
    // many times the cheapest are computed (a cheap teleport otherwise floods the map searching for
    // far-worse alternatives). "Show more" raises it; reset to the default on a new destination.
    static final int DEFAULT_COST_MULTIPLE = 3;
    static final int COST_MULTIPLE_STEP = 3;

    private volatile List<RouteOption> routes = new ArrayList<>();
    private volatile RouteOption selected;
    // The route the overlays draw, committed ONLY when a generation settles (its "done" update),
    // never mid-stream: while alternatives are still generating and re-ranking, the overlays hold
    // this instead of flipping through the streaming top result. Null for a fresh destination,
    // so the overlay stays clear until the routes settle.
    private volatile RouteOption committed;
    private volatile boolean inFlight;
    // Whether the last generation left routes unshown (the cost cap or the route-count budget).
    private volatile boolean moreLikely;
    // Start, targets and limit the alternatives were last generated from, reused by exclusion,
    // mode and show-more edits so they re-run against the same destination.
    private volatile int lastStart = WorldPointUtil.UNDEFINED;
    private volatile Set<Integer> lastTargets = Set.of();
    private volatile int lastLimit;
    private int limit = AlternativeRoutesService.MAX_ROUTES;
    private int costMultiple = DEFAULT_COST_MULTIPLE;

    List<RouteOption> routes() {
        return routes;
    }

    RouteOption selected() {
        return selected;
    }

    boolean inFlight() {
        return inFlight;
    }

    int lastStart() {
        return lastStart;
    }

    Set<Integer> lastTargets() {
        return lastTargets;
    }

    int lastLimit() {
        return lastLimit;
    }

    int limit() {
        return limit;
    }

    int costMultiple() {
        return costMultiple;
    }

    boolean canLoadMore() {
        return moreLikely;
    }

    void setLimit(int limit) {
        this.limit = limit;
    }

    /** A fresh destination starts at the default cost band; "show more" widens it from there. */
    void resetCostMultiple() {
        costMultiple = DEFAULT_COST_MULTIPLE;
    }

    void resetBudget(int defaultLimit) {
        costMultiple = DEFAULT_COST_MULTIPLE;
        limit = defaultLimit;
    }

    /** Drops the pick so a fresh generation's best takes over rather than the overlay clinging to the old line. */
    void clearSelection() {
        selected = null;
    }

    /**
     * A generation begins for {@code targets} (empty: the catalog alone). A NEW destination clears
     * the committed route so the overlay stays blank until the fresh routes settle; regenerating
     * the SAME destination (off-route recalc, method toggle, "more") keeps it, so the overlay holds
     * the current route steadily rather than blinking blank. The page empties either way.
     */
    void begin(int start, Set<Integer> targets) {
        Set<Integer> ends = targets == null ? Set.of() : Set.copyOf(targets);
        if (!ends.equals(lastTargets))
            committed = null;
        lastStart = start;
        lastTargets = ends;
        lastLimit = limit;
        routes = new ArrayList<>();
        moreLikely = false;
        inFlight = !ends.isEmpty();
    }

    /** A streaming update: the page so far, in effective order. The selection and the committed route stay. */
    void stream(List<RouteOption> ordered) {
        routes = ordered;
    }

    /**
     * The generation's final update. A recalculation must not yank the player off the route they
     * PICKED: when the fresh list holds an equivalent route it stays selected, even if its rank
     * moved, unless the pick was never started ({@code progress} 0) and the fresh list found
     * something far better (more than twice cheaper), in which case keeping it is not stability
     * but clinging to a stale result. Otherwise the pick is dropped and the overlay settles to the
     * new best. The committed route is settled BEFORE the in-flight flag clears, so the overlay
     * adopts it in one step. "More" stays available while routes were left unshown and the
     * route-count budget is below {@code cap}.
     */
    void settle(List<RouteOption> ordered, boolean wasMoreLikely, int cap, IntSupplier progressOfSelected) {
        routes = ordered;
        moreLikely = !ordered.isEmpty() && wasMoreLikely && limit < cap;
        RouteOption rematched = null;
        if (selected != null) {
            int progress = progressOfSelected.getAsInt();
            rematched = rematch(selected, ordered, progress);
            if (rematched != null && !ordered.isEmpty() && rematched != ordered.get(0)
                && progress == 0 && rematched.getTotalCost() > ordered.get(0).getTotalCost() * 2) {
                rematched = null;
            }
        }
        if (rematched != null) {
            selected = rematched;
            committed = rematched;
        }
        else {
            selected = null;
            committed = ordered.isEmpty() ? null : ordered.get(0);
        }
        inFlight = false;
    }

    /**
     * The route the overlays draw for {@code currentTargets}: the pick when there is one; the
     * committed route while a generation is in flight (null for a fresh destination: the HUD then
     * says it is finding the route); else the best route, and only when the page was generated
     * for these targets (a stale page for a previous destination is never shown).
     */
    RouteOption displayed(Set<Integer> currentTargets) {
        RouteOption pick = selected;
        if (pick != null)
            return pick;
        if (inFlight)
            return committed;
        List<RouteOption> page = routes;
        if (page.isEmpty() || currentTargets.isEmpty() || !lastTargets.equals(currentTargets))
            return null;
        return page.get(0);
    }

    /**
     * Whether the HUD is in its "Finding the best route" state for {@code currentTargets}: a
     * destination is set, its routes are still computing and nothing is on the overlay yet (a
     * same-destination regeneration keeps the previous route on screen instead).
     */
    boolean isFinding(Set<Integer> currentTargets) {
        return inFlight && !currentTargets.isEmpty() && displayed(currentTargets) == null;
    }

    /** Toggles the pick at {@code index} (clicking the shown route hides it). False when out of range. */
    boolean select(int index) {
        List<RouteOption> page = routes;
        if (index < 0 || index >= page.size())
            return false;
        RouteOption route = page.get(index);
        selected = selected == route ? null : route;
        return true;
    }

    void resort(Comparator<RouteOption> order) {
        List<RouteOption> page = routes;
        if (!page.isEmpty()) {
            List<RouteOption> sorted = new ArrayList<>(page);
            sorted.sort(order);
            routes = sorted;
        }
    }

    /**
     * "More routes": grows both dimensions of the cap so genuinely more routes surface (widen the
     * cost band and raise the route-count budget by another page, capped). False when there is no
     * destination or the last generation left nothing unshown.
     */
    boolean widen(int defaultLimit, int cap) {
        if (lastTargets.isEmpty() || !moreLikely)
            return false;
        costMultiple += COST_MULTIPLE_STEP;
        limit = Math.min(limit + defaultLimit, cap);
        return true;
    }

    /**
     * Whether a new generation is needed: there is a target, and either it changed since the last
     * generation or the last generation was allowed fewer routes than wanted now.
     */
    static boolean shouldAutoCompute(Set<Integer> targets, Set<Integer> lastTargets, int lastLimit, int desiredLimit) {
        return !targets.isEmpty() && (!targets.equals(lastTargets) || lastLimit < desiredLimit);
    }

    /**
     * The route in {@code routes} equivalent to {@code previous}, matching what is LEFT of the
     * plan rather than its full history: methods whose edges the player has already crossed (per
     * {@code progress}, the reached path index) are consumed, so after riding the minecart the
     * equivalent route is the one continuing with the remaining methods. Bank-ness only
     * distinguishes routes while nothing is consumed yet. Null when no equivalent exists.
     */
    static RouteOption rematch(RouteOption previous, List<RouteOption> routes, int progress) {
        List<TeleportMethod> methods = previous.getMethods();
        List<Integer> edges = previous.getMethodEdgeIndexes();
        int consumed = 0;
        while (consumed < methods.size() && consumed < edges.size() && edges.get(consumed) <= progress)
            consumed++;
        List<TeleportMethod> remaining = methods.subList(consumed, methods.size());
        boolean checkBank = consumed == 0;
        for (RouteOption route : routes) {
            if ((!checkBank || route.isViaBank() == previous.isViaBank())
                && route.getMethods().equals(remaining)) {
                return route;
            }
        }
        return null;
    }

    /** A defensive copy of the targets, for callers that mutate. */
    Set<Integer> lastTargetsCopy() {
        return new HashSet<>(lastTargets);
    }
}

package gps;

import gps.pathfinder.PathStep;
import java.util.List;
import java.util.Set;
import java.util.function.Predicate;

/**
 * Judgements about a route (plan step L28, out of the plugin class): whether its endpoint is
 * close enough to the targets to count as reached, and where along it the player cannot
 * click-walk yet. Pure over the route, the targets and the configured tolerance.
 */
final class RouteVerdicts {
    private RouteVerdicts() {
    }

    /**
     * Whether a route that stopped short ends too far from every target to count as reached for
     * colouring: a route that stops at the closest reachable tile (the exact target being an NPC
     * or object spot) still counts while its endpoint is within {@code tolerance}.
     */
    static boolean endTooFar(RouteOption route, Set<Integer> targets, int tolerance) {
        if (route.isReached())
            return false;
        List<PathStep> path = route.getPath();
        if (path == null || path.isEmpty() || targets.isEmpty())
            return false;
        return closestTargetDistance(path, targets) > tolerance;
    }

    /**
     * Whether a route actually gets to the target: the exact tile, or, for object and other
     * adjacent destinations that legitimately end beside the goal (a bank booth, an altar),
     * within {@code tolerance} of it. False means the destination cannot be reached and the route
     * only got to the closest reachable tile. Judged on the route's own endpoint, so a target
     * reachable only by a teleport is not misreported.
     */
    static boolean reachesTarget(RouteOption route, Set<Integer> targets, int tolerance) {
        if (route == null)
            return false;
        if (route.isReached())
            return true;
        List<PathStep> path = route.getPath();
        if (path == null || path.isEmpty() || targets.isEmpty()) {
            return true; // not enough information to declare it unreachable
        }
        return closestTargetDistance(path, targets) <= tolerance;
    }

    private static int closestTargetDistance(List<PathStep> path, Set<Integer> targets) {
        int endPoint = path.get(path.size() - 1).getPackedPosition();
        int closest = Integer.MAX_VALUE;
        for (int target : targets)
            closest = Math.min(closest, WorldPointUtil.distanceBetween(target, endPoint));
        return closest;
    }

    /**
     * The first path index the player cannot click-walk to yet: at or beyond the first obstacle
     * ahead of {@code progress} they must interact with to cross (an agility shortcut, stairs, or
     * a door not seen open, per {@code doorOpen}). The path from there is drawn blocked.
     * {@link Integer#MAX_VALUE} when nothing ahead blocks.
     */
    static int blockedFromIndex(List<PathStep> path, List<RouteDirections.Step> steps, int progress,
        Predicate<ClosedDoors.Door> doorOpen) {
        for (RouteDirections.Step step : steps) {
            if (!step.gatesWalk() || step.getEndIndex() <= progress)
                continue;
            if (step.isDoor()) {
                ClosedDoors.Door door = ClosedDoors.doorBetween(
                    path.get(step.getStartIndex()).getPackedPosition(),
                    path.get(step.getEndIndex()).getPackedPosition());
                if (door == null || doorOpen.test(door))
                    continue;
            }
            return step.getEndIndex();
        }
        return Integer.MAX_VALUE;
    }
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.transport.Transport;
import gps.transport.requirement.ItemRequirement;
import gps.transport.requirement.TransportItems;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/**
 * Precomputed item-dependency index: which item IDs, at which quantity thresholds, can change
 * any transport's availability. Built once from the loaded transports; the plugin fingerprints
 * the routing-relevant slice of the inventory and equipment on every container change and only
 * marks the teleport catalog dirty when that slice actually changed - most inventory traffic
 * (logs, ore, food, loot) touches nothing any transport cares about (issues #23/#24).
 */
public final class RoutingItemDependencies {
    /** Item id -> sorted distinct quantities at which some requirement flips. */
    private final Map<Integer, int[]> thresholds;

    private RoutingItemDependencies(Map<Integer, int[]> thresholds) {
        this.thresholds = thresholds;
    }

    public static RoutingItemDependencies build(Transport[] transports) {
        Map<Integer, TreeSet<Integer>> collected = new HashMap<>();
        for (Transport transport : transports) {
            TransportItems items = transport.getItemRequirements();
            if (items == null)
                continue;
            for (ItemRequirement req : items.getRequirements()) {
                // Threshold 1 is always included alongside the required quantity, so checks
                // with presence semantics (staff substitution) are covered regardless of the
                // possession logic's internals; extra thresholds only cost a rare false dirty.
                collect(collected, req.getItemIds(), req.getQuantity());
                collect(collected, req.getStaffIds(), 1);
                collect(collected, req.getOffhandIds(), 1);
            }
        }
        // Implicit requirements that appear in no transport row: fairy rings demand a wielded
        // or carried Dramen/Lunar staff (PathfinderConfig's DRAMEN_STAFF special case), and a
        // rune pouch in the inventory unlocks its varbit-tracked runes for spell requirements.
        collect(collected, ItemVariations.DRAMEN_STAFF.getIds(), 1);
        collect(collected, ItemVariations.staves(ItemVariations.DRAMEN_STAFF), 1);
        collect(collected, ItemVariations.offhands(ItemVariations.DRAMEN_STAFF), 1);
        for (int pouch : PathfinderConfig.RUNE_POUCHES) {
            collect(collected, new int[]{pouch}, 1);
        }

        Map<Integer, int[]> thresholds = new HashMap<>(collected.size() * 2);
        for (Map.Entry<Integer, TreeSet<Integer>> entry : collected.entrySet()) {
            int[] sorted = new int[entry.getValue().size()];
            int i = 0;
            for (int quantity : entry.getValue())
                sorted[i++] = quantity;
            thresholds.put(entry.getKey(), sorted);
        }
        return new RoutingItemDependencies(thresholds);
    }

    private static void collect(Map<Integer, TreeSet<Integer>> collected, int[] ids, int quantity) {
        if (ids == null)
            return;
        for (int id : ids) {
            TreeSet<Integer> set = collected.computeIfAbsent(id, k -> new TreeSet<>());
            set.add(1);
            if (quantity > 1)
                set.add(quantity);
        }
    }

    /** Whether this item id can influence any transport's availability at all. */
    public boolean isRelevant(int itemId) {
        return thresholds.containsKey(itemId);
    }

    public int size() {
        return thresholds.size();
    }

    /**
     * Order-independent fingerprint of the routing-relevant item state across the inventory and
     * equipment. Two states with the same fingerprint satisfy exactly the same requirement
     * thresholds, so a transport availability pass would classify every method identically -
     * equal fingerprints mean the catalog refresh can be skipped. The container matters (a
     * wielded staff counts differently from a carried one), so each is folded in separately.
     */
    public long fingerprint(ItemContainer inventory, ItemContainer equipment) {
        long acc = 0;
        acc += containerDigest(inventory, 1);
        acc += containerDigest(equipment, 2);
        return acc;
    }

    private long containerDigest(ItemContainer container, int tag) {
        if (container == null)
            return 0;
        // Duplicate un-stacked items (two dramen staffs) aggregate per id before thresholding.
        Map<Integer, Integer> quantities = null;
        for (Item item : container.getItems()) {
            if (item == null || !thresholds.containsKey(item.getId()))
                continue;
            if (quantities == null)
                quantities = new HashMap<>();
            quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        if (quantities == null)
            return 0;
        long digest = 0;
        for (Map.Entry<Integer, Integer> entry : quantities.entrySet()) {
            int[] sorted = thresholds.get(entry.getKey());
            int met = metCount(sorted, entry.getValue());
            if (met > 0)
                // Commutative sum of well-mixed terms keeps the digest independent of slot order.
                digest += mix64(((long) tag << 40) ^ ((long) entry.getKey() << 8) ^ met);
        }
        return digest;
    }

    private static int metCount(int[] sorted, int quantity) {
        int idx = Arrays.binarySearch(sorted, quantity);
        return idx >= 0 ? idx + 1 : -idx - 1;
    }

    /** splitmix64 finalizer; also the mixer behind the refresh's usable-transport fingerprint. */
    public static long mix64(long z) {
        z = (z ^ (z >>> 30)) * 0xbf58476d1ce4e5b9L;
        z = (z ^ (z >>> 27)) * 0x94d049bb133111ebL;
        return z ^ (z >>> 31);
    }
}

package gps;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * The game's boat-location registry: SAILING_BOAT_N_PORT varbit values joined to this
 * plugin's mooring tiles (shipped sailing-ports.tsv, ids adapted from the 'Dude, Where's
 * My Boat?' hub plugin). A port may span several moorings; the first is the primary
 * (teleport landing) berth. Special values: 254 = capsized, 255 = bottled — no mooring.
 */
public final class SailingPorts {
    public static final int PORT_CAPSIZED = 254;
    public static final int PORT_BOTTLED = 255;

    private static volatile SailingPorts instance;

    private final Map<Integer, String> names = new HashMap<>();
    /** Packed mooring land tiles per port id; first entry is the primary berth. */
    private final Map<Integer, List<Integer>> moorings = new HashMap<>();

    private SailingPorts() {
        try (InputStream in = SailingPorts.class.getResourceAsStream("/sailing-ports.tsv");
            Scanner scanner = new Scanner(in, "UTF-8")) {
            while (scanner.hasNextLine()) {
                String[] fields = scanner.nextLine().split("\t");
                if (fields.length < 4 || fields[0].startsWith("#") || "portId".equals(fields[0]))
                    continue;
                int id = Integer.parseInt(fields[0]);
                names.putIfAbsent(id, fields[1].trim());
                moorings.computeIfAbsent(id, k -> new ArrayList<>()).add(WorldPointUtil.packWorldPoint(
                    Integer.parseInt(fields[2]), Integer.parseInt(fields[3]), 0));
            }
        }
        catch (java.io.IOException | RuntimeException e) {
            // A missing registry only disables boat-location awareness, never routing.
        }
    }

    private static SailingPorts get() {
        SailingPorts loaded = instance;
        if (loaded == null) {
            synchronized (SailingPorts.class) {
                loaded = instance;
                if (loaded == null)
                    instance = loaded = new SailingPorts();
            }
        }
        return loaded;
    }

    /** Packed mooring land tiles of the port, empty for capsized/bottled/unknown ids. */
    public static List<Integer> portMoorings(int portId) {
        return get().moorings.getOrDefault(portId, List.of());
    }

    /** Display name for a port id; capsized/bottled and unknown ids get honest fallbacks. */
    public static String portName(int portId) {
        if (portId == PORT_CAPSIZED)
            return "capsized";
        if (portId == PORT_BOTTLED)
            return "in a bottle";
        String name = get().names.get(portId);
        return name != null ? name : "port " + portId;
    }
}

package gps;

import gps.transport.Transport;
import gps.transport.TransportType;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;
import java.util.zip.InflaterInputStream;

import static gps.WorldPointUtil.packWorldPoint;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

/**
 * The sailable ocean and the mooring endpoints, shipped as resources by the tooling repo's
 * WaterMapResourceTest. Lets routing treat a sea tile as a destination: when a target is
 * sailable water, {@link #seaLegTransports} synthesizes the final leg — board at a nearby
 * mooring's land tile, sail straight out to the target. Durations use the same PROVISIONAL
 * speed model as the generated port-to-port rows until the calibration pass.
 */
@lombok.extern.slf4j.Slf4j
public final class SailingSea {
    /** Deliberate fixed approximation, not a placeholder: hulls cruise 1.5 (wooden) to 3.0
     * (rosewood) tiles/tick per the wiki hull table, so the mid-table 2.0 keeps every ETA
     * within ~33% without per-boat calibration machinery. */
    private static final double TILES_PER_TICK = 2.0;
    /** Board + cast off + moor + disembark, in ticks — every sailing edge's fixed cost.
     * Shared with RouteDirections, which splits a leg into embark + sail steps. */
    static final int OVERHEAD_TICKS = 20;
    /** Wet-endpoint flood early stop: only the closest few moorings can appear in sea legs. */
    private static final int SETTLE_ENDPOINTS = 12;
    /** Wet floods keep going until this many WALK-REACHABLE ports settle (field anchors). */
    private static final int REACHABLE_QUOTA = 4;
    /** Sea-leg sets always include at least this many walk-reachable ports (field anchors). */
    private static final int REACHABLE_LEGS = 3;
    /** Moor + step off, for legs that START aboard (the full cycle is OVERHEAD_TICKS). */
    private static final int DISEMBARK_TICKS = 8;

    private static volatile SailingSea instance;

    private final int minX;
    private final int minY;
    private final int width;
    private final int height;
    private final byte[] bits;
    /** Rows of {landX, landY, waterX, waterY, walkReachable(0/1)}. */
    private final List<int[]> moorings;
    /** Port display names, parallel to {@link #moorings} (shipped, nearest-pin derived). */
    private final List<String> mooringNames;
    /** Water-endpoint grid index -> mooring index, precomputed at load: the wet flood
     * consults it once per popped node (millions on mid-ocean floods), so no boxed keys. */
    private final PrimitiveIntHashMap<Integer> endpointIndex;
    /** Packed land tiles of every mooring — the origins of boarding legs, for the
     * boat-location gate to tell "boards a boat here" from "already under way". */
    private final java.util.Set<Integer> mooringLandTiles;
    /** Port-to-port sea distances in centitiles (shipped matrix, MAX_VALUE = unconnected),
     * indexed like {@link #moorings} — lets partial wet floods reach EVERY port by
     * composing through a settled near one. Null when the resource is absent. */
    private int[][] portMatrix;

    private SailingSea(int minX, int minY, int width, int height, byte[] bits,
        List<int[]> moorings, List<String> mooringNames) {
        this.minX = minX;
        this.minY = minY;
        this.width = width;
        this.height = height;
        this.bits = bits;
        this.moorings = moorings;
        this.mooringNames = mooringNames;
        this.endpointIndex = new PrimitiveIntHashMap<>(Math.max(1, moorings.size() * 2));
        this.mooringLandTiles = new java.util.HashSet<>();
        for (int i = 0; i < moorings.size(); i++) {
            int[] mooring = moorings.get(i);
            endpointIndex.put((mooring[3] - minY) * width + (mooring[2] - minX), i);
            mooringLandTiles.add(packWorldPoint(mooring[0], mooring[1], 0));
        }
    }

    /** Whether the tile is a mooring's boarding (land) tile — the origin class of every
     * static sailing row and synthetic embark leg. */
    public static boolean isMooringLand(int packed) {
        return get().mooringLandTiles.contains(packed);
    }

    /** The shipped port-to-port matrix, re-keyed from land tiles to mooring indices; null
     * (composition disabled, floods stand alone) when the resource is missing. */
    private static int[][] loadPortMatrix(List<int[]> moorings) {
        java.util.Map<Long, Integer> byLand = new java.util.HashMap<>();
        for (int i = 0; i < moorings.size(); i++)
            byLand.put((long) moorings.get(i)[0] << 16 | moorings.get(i)[1], i);
        try (InputStream tsv = SailingSea.class.getResourceAsStream("/sailing-sea-matrix.tsv");
            Scanner scanner = new Scanner(tsv, "UTF-8")) {
            int[][] matrix = new int[moorings.size()][moorings.size()];
            for (int[] row : matrix)
                java.util.Arrays.fill(row, Integer.MAX_VALUE);
            for (int i = 0; i < matrix.length; i++)
                matrix[i][i] = 0;
            while (scanner.hasNextLine()) {
                String[] fields = scanner.nextLine().split("\t");
                if (fields.length < 5 || fields[0].startsWith("#") || "fromLandX".equals(fields[0]))
                    continue;
                Integer from = byLand.get(Long.parseLong(fields[0]) << 16 | Long.parseLong(fields[1]));
                Integer to = byLand.get(Long.parseLong(fields[2]) << 16 | Long.parseLong(fields[3]));
                // Self-pairs never carry information (a mooring is 0 from itself).
                if (from != null && to != null && !from.equals(to))
                    matrix[from][to] = Integer.parseInt(fields[4]);
            }
            return matrix;
        }
        catch (IOException | RuntimeException e) {
            return null;
        }
    }

    /**
     * Sea distance from {@code packed} to EVERY mooring: the partial wet flood's exact
     * values where it settled, and flood + port-matrix composition everywhere else — so far
     * ports get honest (slightly conservative: the join is a settled endpoint, not the true
     * merge point) distances instead of MAX_VALUE. This is what lets aboard starts offer a
     * single continuous sail to ANY port rather than a disembark/re-embark chain.
     */
    private static int[] composedPortDistances(int packed) {
        int[] flood = seaDistances(packed);
        int[][] matrix = get().portMatrix;
        if (matrix == null)
            return flood;
        int[] out = flood.clone();
        for (int far = 0; far < out.length; far++) {
            if (flood[far] != Integer.MAX_VALUE)
                continue;
            for (int near = 0; near < flood.length; near++) {
                if (flood[near] != Integer.MAX_VALUE && matrix[near][far] != Integer.MAX_VALUE)
                    out[far] = Math.min(out[far], flood[near] + matrix[near][far]);
            }
        }
        return out;
    }

    private static SailingSea get() {
        SailingSea loaded = instance;
        if (loaded == null) {
            synchronized (SailingSea.class) {
                loaded = instance;
                if (loaded == null) {
                    loaded = load();
                    instance = loaded;
                }
            }
        }
        return loaded;
    }

    private static SailingSea load() {
        try (InputStream in = SailingSea.class.getResourceAsStream("/sailing-sea.bin")) {
            DataInputStream header = new DataInputStream(in);
            int minX = header.readInt();
            int minY = header.readInt();
            int width = header.readInt();
            int height = header.readInt();
            byte[] bits = new InflaterInputStream(in).readAllBytes();

            List<int[]> moorings = new ArrayList<>();
            List<String> mooringNames = new ArrayList<>();
            try (InputStream tsv = SailingSea.class.getResourceAsStream("/sailing-moorings.tsv");
                Scanner scanner = new Scanner(tsv, "UTF-8")) {
                while (scanner.hasNextLine()) {
                    String[] fields = scanner.nextLine().split("\t");
                    if (fields.length < 5 || fields[0].startsWith("#") || "type".equals(fields[0]))
                        continue;
                    int landX = Integer.parseInt(fields[1]);
                    int landY = Integer.parseInt(fields[2]);
                    // The port matrix is keyed by land tile, so two moorings sharing one landing
                    // tile are one mooring to routing: keep the first, or the second silently
                    // overwrites the first's matrix index and its rows are lost (Wyrmscraig).
                    boolean duplicateLand = false;
                    for (int[] existing : moorings) {
                        if (existing[0] == landX && existing[1] == landY) {
                            duplicateLand = true;
                            break;
                        }
                    }
                    if (duplicateLand)
                        continue;
                    moorings.add(new int[]{landX, landY,
                        Integer.parseInt(fields[3]), Integer.parseInt(fields[4]),
                        fields.length > 5 && "true".equals(fields[5].trim()) ? 1 : 0});
                    mooringNames.add(fields.length > 6 ? fields[6].trim() : "");
                }
            }
            SailingSea loaded = new SailingSea(minX, minY, width, height, bits, moorings, mooringNames);
            loaded.portMatrix = loadPortMatrix(moorings);
            return loaded;
        }
        catch (IOException | RuntimeException e) {
            // Missing/corrupt resources must not break routing; sailing sea targets just
            // won't resolve.
            return new SailingSea(0, 0, 0, 0, new byte[0], List.of(), List.of());
        }
    }

    /** Whether this tile is on the sailable ocean (plane 0 only). */
    public static boolean isSailable(int packed) {
        if (WorldPointUtil.unpackWorldPlane(packed) != 0)
            return false;
        SailingSea sea = get();
        int x = unpackWorldX(packed) - sea.minX;
        int y = unpackWorldY(packed) - sea.minY;
        if (x < 0 || y < 0 || x >= sea.width || y >= sea.height)
            return false;
        return bit(sea, x, y);
    }

    // A target set spanning more than this on either axis is a category spread over the map
    // ("nearest bank"), not one place (a pin, a searched spot, a named bank's booths).
    private static final int COMPACT_SPAN = 64;

    /**
     * The targets that get sea legs: the blocked ones (open water is sealed to walkers; stilt
     * decks are walkable, so never wet), for whose sailable members {@link #seaLegTransports}
     * then builds the legs. A compact set is one place and always qualifies. A category spread
     * over the map qualifies only for a player already aboard: its few water tiles (the Bank Boat,
     * the Fossil Island shipwreck's chest) matter to a sailor at sea, while synthesizing them
     * anyway cost every on-foot "nearest bank" click four ocean floods, about 700 ms (measured
     * 2026-09-27).
     */
    public static Set<Integer> waterPins(gps.pathfinder.CollisionMap map, Set<Integer> targets, boolean aboard) {
        if (map == null || targets.isEmpty() || (!aboard && !isCompact(targets)))
            return Set.of();
        Set<Integer> wet = new HashSet<>();
        for (int target : targets) {
            if (map.isBlocked(unpackWorldX(target), unpackWorldY(target),
                WorldPointUtil.unpackWorldPlane(target))) {
                wet.add(target);
            }
        }
        return wet;
    }

    /** Whether the targets fit within {@link #COMPACT_SPAN} tiles on both axes: one place. */
    private static boolean isCompact(Set<Integer> targets) {
        int minX = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE;
        int maxY = Integer.MIN_VALUE;
        for (int target : targets) {
            int x = unpackWorldX(target);
            int y = unpackWorldY(target);
            minX = Math.min(minX, x);
            maxX = Math.max(maxX, x);
            minY = Math.min(minY, y);
            maxY = Math.max(maxY, y);
        }
        return maxX - minX <= COMPACT_SPAN && maxY - minY <= COMPACT_SPAN;
    }

    /**
     * The synthesized final sea legs for a sailable-water target: board at each of the
     * {@code count} closest-by-sea moorings' land tiles and sail out. Distances come from the
     * wet-endpoint flood ({@link #seaDistances}) — a real Dijkstra over the shipped ocean, so
     * islands and coastlines are respected. Gated like any SAILING transport (master toggle).
     */
    /**
     * Legs for a search STARTING on the water (player aboard): sail from the start to EVERY
     * sea-connected mooring and disembark — the start-side twin of {@link #seaLegTransports},
     * matrix-composed so far ports get one continuous sail instead of the field's
     * disembark/re-embark chains (findings 6-7) — plus, when a target is itself sailable
     * water, one direct sail-to-the-pin leg (staged-box exact, matrix-composed when the pin
     * is beyond the boxes). Without these, a search from aboard dies on its sealed start
     * tile ("unreachable" the moment the player boards and drops a pin).
     */
    public static List<Transport> aboardLegTransports(int startPacked,
        java.util.Set<Integer> targets) {
        if (!isSailable(startPacked))
            return List.of();
        List<Transport> legs = new ArrayList<>();
        SailingSea sea = get();
        int[] distances = composedPortDistances(startPacked);
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < distances.length; i++) {
            if (distances[i] != Integer.MAX_VALUE)
                order.add(i);
        }
        // Nearest-first so the service's port seeding keeps its ranking for free.
        order.sort(Comparator.comparingInt(i -> distances[i]));
        for (int i : order) {
            int[] mooring = sea.moorings.get(i);
            // Moor + step off only (~8 ticks): the player is already aboard and under way;
            // the full 20-tick cycle (board, cast off, moor, disembark) double-charged every
            // aboard hop — a berth-adjacent disembark priced at 16 seconds in the field.
            int duration = DISEMBARK_TICKS + (int) Math.ceil(
                distances[i] / 100.0 / TILES_PER_TICK);
            legs.add(new Transport.TransportBuilder()
                .origin(startPacked)
                .destination(packWorldPoint(mooring[0], mooring[1], 0))
                .type(TransportType.SAILING)
                .duration(duration)
                .displayInfo("Disembark at " + portName(i))
                .build());
        }
        for (int target : targets) {
            int centitiles = seaDistanceBetween(startPacked, target);
            if (centitiles < 0) {
                // Beyond the staged boxes: sail via the cheapest port join — the composed
                // start-side distances plus the target's own composed distances share every
                // mooring as a meeting point.
                int[] toTarget = composedPortDistances(target);
                long best = Long.MAX_VALUE;
                for (int i = 0; i < distances.length; i++) {
                    if (distances[i] != Integer.MAX_VALUE && toTarget[i] != Integer.MAX_VALUE)
                        best = Math.min(best, (long) distances[i] + toTarget[i]);
                }
                if (best < Long.MAX_VALUE)
                    centitiles = (int) Math.min(Integer.MAX_VALUE, best);
            }
            if (centitiles >= 0) {
                legs.add(new Transport.TransportBuilder()
                    .origin(startPacked)
                    .destination(target)
                    .type(TransportType.SAILING)
                    .duration(Math.max(1, (int) Math.ceil(centitiles / 100.0 / TILES_PER_TICK)))
                    .displayInfo("Sail to the destination")
                    .build());
            }
        }
        return legs;
    }

    /**
     * Exact sea distance between two sailable tiles in centitiles, or -1 when either tile is
     * not sailable or no path fits the staged search boxes (60 then 600 margin — no full-grid
     * stage: this runs on the generation thread, and a leg the 600 box cannot connect is
     * served by the mooring legs instead).
     */
    public static synchronized int seaDistanceBetween(int fromPacked, int toPacked) {
        SailingSea sea = get();
        if (sea.width == 0 || !isSailable(fromPacked) || !isSailable(toPacked))
            return -1;
        int start = (unpackWorldY(fromPacked) - sea.minY) * sea.width
            + (unpackWorldX(fromPacked) - sea.minX);
        int goal = (unpackWorldY(toPacked) - sea.minY) * sea.width
            + (unpackWorldX(toPacked) - sea.minX);
        if (start == goal)
            return 0;
        int cost = boxDistance(sea, start, goal, 60);
        return cost >= 0 ? cost : boxDistance(sea, start, goal, 600);
    }

    /** Box-bounded Dijkstra cost from start to goal grid index, or -1 when unconnected. */
    private static int boxDistance(SailingSea sea, int start, int goal, int margin) {
        int x0 = Math.max(0, Math.min(start % sea.width, goal % sea.width) - margin);
        int y0 = Math.max(0, Math.min(start / sea.width, goal / sea.width) - margin);
        int x1 = Math.min(sea.width - 1, Math.max(start % sea.width, goal % sea.width) + margin);
        int y1 = Math.min(sea.height - 1, Math.max(start / sea.width, goal / sea.width) + margin);
        int boxWidth = x1 - x0 + 1;
        int boxHeight = y1 - y0 + 1;
        int[] dist = new int[boxWidth * boxHeight];
        java.util.Arrays.fill(dist, Integer.MAX_VALUE);
        int boxStart = (start / sea.width - y0) * boxWidth + (start % sea.width - x0);
        int boxGoal = (goal / sea.width - y0) * boxWidth + (goal % sea.width - x0);
        LongHeap queue = new LongHeap();
        dist[boxStart] = 0;
        queue.push(boxStart);
        while (!queue.isEmpty()) {
            long head = queue.pop();
            int index = (int) (head & 0xFFFFFFFFL);
            if ((int) (head >>> 32) > dist[index])
                continue;
            if (index == boxGoal)
                return dist[index];
            int x = index % boxWidth;
            int y = index / boxWidth;
            for (int[] move : MOVES) {
                int nx = x + move[0];
                int ny = y + move[1];
                if (nx < 0 || ny < 0 || nx >= boxWidth || ny >= boxHeight
                    || !bit(sea, x0 + nx, y0 + ny)
                    || obstacleAtGrid(sea, x0 + nx, y0 + ny)
                    || knightBlocked(sea, x0 + x, y0 + y, move[0], move[1])) {
                    continue;
                }
                int next = ny * boxWidth + nx;
                if (dist[index] + move[2] < dist[next]) {
                    dist[next] = dist[index] + move[2];
                    queue.push((long) dist[next] << 32 | next);
                }
            }
        }
        return -1;
    }

    public static List<Transport> seaLegTransports(int targetPacked, int count) {
        return seaLegTransports(targetPacked, count, java.util.Set.of());
    }

    /**
     * @param mustIncludeLands packed mooring land tiles that get an embark leg even when
     *                         outside the nearest-{@code count} — with Summon Boat not
     *                         assumed, the boat's actual berth is the ONLY legal embark, and
     *                         nearest-selection would happily gate every offered leg away.
     */
    public static List<Transport> seaLegTransports(int targetPacked, int count,
        java.util.Set<Integer> mustIncludeLands) {
        if (!isSailable(targetPacked))
            return List.of();
        int tx = unpackWorldX(targetPacked);
        int ty = unpackWorldY(targetPacked);
        int[] distances = composedPortDistances(targetPacked);
        List<int[]> moorings = get().moorings;
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < moorings.size(); i++) {
            if (distances[i] != Integer.MAX_VALUE)
                order.add(i);
        }
        order.sort(Comparator.comparingInt(i -> distances[i]));
        // Nearest-by-sea plus a guarantee of REACHABLE_LEGS walk-reachable ports. Near new
        // islands every nearby mooring is an unreachable unlock — legs only from those give
        // the heuristic field nothing on the mainland, and every search of the generation
        // runs blind (the 30s water-pin captures).
        List<Integer> chosen = new ArrayList<>();
        int reachableChosen = 0;
        for (int i : order) {
            boolean reachable = reachable(moorings.get(i));
            if (chosen.size() < count) {
                chosen.add(i);
                if (reachable)
                    reachableChosen++;
            }
            else if (reachableChosen < REACHABLE_LEGS && reachable) {
                chosen.add(i);
                reachableChosen++;
            }
            else if (!mustIncludeLands.isEmpty() && mustIncludeLands.contains(
                packWorldPoint(moorings.get(i)[0], moorings.get(i)[1], 0))) {
                chosen.add(i);
            }
        }
        List<Transport> legs = new ArrayList<>();
        for (int i : chosen) {
            int[] mooring = moorings.get(i);
            int duration = OVERHEAD_TICKS + (int) Math.ceil(
                distances[i] / 100.0 / TILES_PER_TICK);
            legs.add(new Transport.TransportBuilder()
                .origin(packWorldPoint(mooring[0], mooring[1], 0))
                .destination(targetPacked)
                .type(TransportType.SAILING)
                .duration(duration)
                .displayInfo("Embark at " + portName(i))
                .build());
        }
        return legs;
    }

    /**
     * 16-bearing moves: 8 grid steps plus 8 half-wind (knight) steps at cost 224 (euclidean
     * centitiles, sqrt5 x 100) — cuts the 8-dir staircase overestimate on off-axis legs from
     * ~8.2% to ~2.8%, matching the offline matrix. Knight steps require both interposed tiles
     * sailable so no move skips across an obstacle corner.
     */
    private static final int[][] MOVES = {
        {1, 0, 100}, {-1, 0, 100}, {0, 1, 100}, {0, -1, 100},
        {1, 1, 141}, {1, -1, 141}, {-1, 1, 141}, {-1, -1, 141},
        {2, 1, 224}, {2, -1, 224}, {-2, 1, 224}, {-2, -1, 224},
        {1, 2, 224}, {1, -2, 224}, {-1, 2, 224}, {-1, -2, 224},
    };

    /** The last wet-endpoint flood, keyed by target: generations repeat the same pin. */
    private static volatile int cachedTarget = WorldPointUtil.UNDEFINED;
    private static volatile int[] cachedDistances;

    /**
     * Array-backed min-heap of packed longs (dist << 32 | gridIndex): natural long ordering is
     * distance-major, so Dijkstra needs no comparator and — the actual point — no allocation
     * per node. The boxed PriorityQueue<long[]> it replaces allocated a long[2] per push;
     * mid-ocean wet floods push millions.
     */
    static final class LongHeap {
        private long[] heap = new long[1 << 12];
        private int size;

        boolean isEmpty() {
            return size == 0;
        }

        void push(long value) {
            if (size == heap.length)
                heap = java.util.Arrays.copyOf(heap, size * 2);
            int i = size++;
            while (i > 0) {
                int parent = (i - 1) >> 1;
                if (heap[parent] <= value)
                    break;
                heap[i] = heap[parent];
                i = parent;
            }
            heap[i] = value;
        }

        long pop() {
            long top = heap[0];
            long last = heap[--size];
            int i = 0;
            while (true) {
                int child = 2 * i + 1;
                if (child >= size)
                    break;
                if (child + 1 < size && heap[child + 1] < heap[child])
                    child++;
                if (heap[child] >= last)
                    break;
                heap[i] = heap[child];
                i = child;
            }
            heap[i] = last;
            return top;
        }

        void clear() {
            size = 0;
        }
    }

    /** Scratch distance grid reused across wet floods (24MB: never reallocate per pin). */
    private static int[] wetScratch;
    private static final LongHeap wetHeap = new LongHeap();

    /**
     * The wet-endpoint flood: exact sea distance in centitiles from a sailable target to every
     * mooring's water endpoint (MAX_VALUE where no sea path exists). Dijkstra over the shipped
     * ocean bitset, stopping early once the {@link #SETTLE_ENDPOINTS} nearest endpoints AND
     * {@link #REACHABLE_QUOTA} walk-reachable ports are settled.
     */
    public static synchronized int[] seaDistances(int targetPacked) {
        if (targetPacked == cachedTarget && cachedDistances != null)
            return cachedDistances;
        SailingSea sea = get();
        int[] result = new int[sea.moorings.size()];
        java.util.Arrays.fill(result, Integer.MAX_VALUE);
        if (!isSailable(targetPacked) || sea.width == 0)
            return result;
        if (wetScratch == null || wetScratch.length != sea.width * sea.height)
            wetScratch = new int[sea.width * sea.height];
        int[] dist = wetScratch;
        java.util.Arrays.fill(dist, Integer.MAX_VALUE);
        LongHeap queue = wetHeap;
        queue.clear();
        int start = (unpackWorldY(targetPacked) - sea.minY) * sea.width
            + (unpackWorldX(targetPacked) - sea.minX);
        dist[start] = 0;
        queue.push(start);
        int settled = 0;
        int settledReachable = 0;
        while (!queue.isEmpty()
            && (settled < SETTLE_ENDPOINTS || settledReachable < REACHABLE_QUOTA)) {
            long head = queue.pop();
            int index = (int) (head & 0xFFFFFFFFL);
            if ((int) (head >>> 32) > dist[index])
                continue;
            Integer mooring = sea.endpointIndex.get(index);
            if (mooring != null && result[mooring] == Integer.MAX_VALUE) {
                result[mooring] = dist[index];
                settled++;
                if (reachable(sea.moorings.get(mooring)))
                    settledReachable++;
            }
            int x = index % sea.width;
            int y = index / sea.width;
            for (int[] move : MOVES) {
                int dx = move[0];
                int dy = move[1];
                int nx = x + dx;
                int ny = y + dy;
                if (nx < 0 || ny < 0 || nx >= sea.width || ny >= sea.height
                    || !bit(sea, nx, ny) || obstacleAtGrid(sea, nx, ny)) {
                    continue;
                }
                if (knightBlocked(sea, x, y, dx, dy))
                    continue;
                int next = ny * sea.width + nx;
                if (dist[index] + move[2] < dist[next]) {
                    dist[next] = dist[index] + move[2];
                    queue.push((long) dist[next] << 32 | next);
                }
            }
        }
        cachedDistances = result;
        cachedTarget = targetPacked;
        return result;
    }

    /** Sea tracks for the displayed route's sailing legs, keyed by (from, to). */
    /**
     * Session-learned sea blockers: tiles the shipped ocean calls sailable but LIVE scene
     * collision blocks — moored vessels, harbour clutter, true hazards. The offline map stays
     * the approximate planner; the client corrects itself as scenes reveal the truth (the
     * user's chosen architecture over curated harvests). Dilated by one tile for hull
     * standoff; water within 4 of a mooring's water endpoint is never masked so berth
     * approaches survive. Volatile copy-on-write: hot flood loops read without locks.
     */
    private static volatile PrimitiveIntHashMap<Boolean> liveObstacles;

    /** Whether a world tile is masked by a live-learned obstacle. */
    public static boolean obstacleAt(int worldX, int worldY) {
        PrimitiveIntHashMap<Boolean> mask = liveObstacles;
        return mask != null
            && mask.get(packWorldPoint(worldX, worldY, 0)) != null;
    }

    private static boolean obstacleAtGrid(SailingSea sea, int gridX, int gridY) {
        PrimitiveIntHashMap<Boolean> mask = liveObstacles;
        return mask != null && mask.get(
            packWorldPoint(sea.minX + gridX, sea.minY + gridY, 0)) != null;
    }

    /**
     * Learns live-blocked sailable tiles (packed world points). New knowledge invalidates
     * every cached track and wet flood — they recompute lazily against the corrected sea.
     */
    public static synchronized void learnObstacles(java.util.List<Integer> packedTiles) {
        SailingSea sea = get();
        if (sea.width == 0 || packedTiles.isEmpty())
            return;
        PrimitiveIntHashMap<Boolean> current = liveObstacles;
        PrimitiveIntHashMap<Boolean> grown = null;
        for (int packed : packedTiles) {
            int px = unpackWorldX(packed);
            int py = unpackWorldY(packed);
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    int tile = packWorldPoint(px + dx, py + dy, 0);
                    if (!isSailable(tile) || nearMooringWater(sea, px + dx, py + dy)
                        || (current != null && current.get(tile) != null)
                        || (grown != null && grown.get(tile) != null)) {
                        continue;
                    }
                    if (grown == null)
                        grown = copyMask(current);
                    grown.put(tile, Boolean.TRUE);
                }
            }
        }
        if (grown != null) {
            liveObstacles = grown;
            synchronized (trackCache) {
                trackCache.clear();
            failedTracks.clear();
            }
            cachedTarget = WorldPointUtil.UNDEFINED;
            cachedDistances = null;
        }
    }

    private static PrimitiveIntHashMap<Boolean> copyMask(PrimitiveIntHashMap<Boolean> current) {
        PrimitiveIntHashMap<Boolean> copy = new PrimitiveIntHashMap<>(256);
        if (current != null) {
            for (int key : current.keys())
                copy.put(key, Boolean.TRUE);
        }
        return copy;
    }

    private static boolean nearMooringWater(SailingSea sea, int x, int y) {
        for (int[] mooring : sea.moorings) {
            if (Math.max(Math.abs(mooring[2] - x), Math.abs(mooring[3] - y)) <= 4)
                return true;
        }
        return false;
    }

    /** Test seam: forget everything learned this session. */
    static synchronized void clearLiveObstacles() {
        liveObstacles = null;
        synchronized (trackCache) {
            trackCache.clear();
            failedTracks.clear();
        }
        cachedTarget = WorldPointUtil.UNDEFINED;
        cachedDistances = null;
    }

    private static final java.util.LinkedHashMap<Long, int[]> trackCache =
        new java.util.LinkedHashMap<Long, int[]>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(java.util.Map.Entry<Long, int[]> eldest) {
                return size() > 8;
            }
        };

    /**
     * The actual sea track between two sailing-leg endpoints, as decimated packed waypoints —
     * what the overlays draw instead of a straight jump line. Runs a bounded 16-bearing
     * Dijkstra inside the leg's bounding box (+60 tiles margin) on first request and caches;
     * null when either endpoint has no sailable water within 6 tiles or no track fits the box
     * (the caller falls back to the dashed jump).
     */
    private static final java.util.Set<Long> tracksInFlight =
        java.util.concurrent.ConcurrentHashMap.newKeySet();
    private static final java.util.concurrent.ExecutorService trackExecutor =
        java.util.concurrent.Executors.newSingleThreadExecutor(runnable -> {
            Thread thread = new Thread(runnable, "gps-sea-track");
            thread.setDaemon(true);
            return thread;
        });

    /**
     * The overlay-facing track lookup: NEVER computes on the caller's thread. Absent tracks
     * schedule a background computation and return null — the overlay draws the dashed hint
     * for a beat and the solid track appears once cached. Long legs (rounding a continent,
     * threading to Weiss) can take seconds on the full grid; render must not pay that.
     */
    public static int[] seaPath(int fromPacked, int toPacked) {
        long key = trackKey(fromPacked, toPacked);
        int[] cached = cachedTrack(key);
        if (cached != null || trackCached(key))
            return cached;
        if (failureCoolingDown(key))
            return null;
        if (tracksInFlight.add(key)) {
            trackExecutor.submit(() -> {
                // try/finally: an exception here must not wedge the key in-flight forever
                // (permanent silent dashes) — cache the null so the overlay falls back cleanly.
                try {
                    seaPathBlocking(fromPacked, toPacked);
                }
                catch (RuntimeException e) {
                    log.warn("sea track computation failed for {} -> {}",
                        fromPacked, toPacked, e);
                    synchronized (trackCache) {
                        failedTracks.put(key, System.currentTimeMillis());
                    }
                }
                finally {
                    tracksInFlight.remove(key);
                }
            });
        }
        return null;
    }

    /** Synchronous computation+cache, for tests and background workers. */
    static int[] seaPathBlocking(int fromPacked, int toPacked) {
        long key = trackKey(fromPacked, toPacked);
        int[] cached = cachedTrack(key);
        if (cached != null || trackCached(key))
            return cached;
        int[] track = computeSeaPath(fromPacked, toPacked);
        synchronized (trackCache) {
            if (track != null && track.length > 1)
                trackCache.put(key, track);
            else
                failedTracks.put(key, System.currentTimeMillis());
        }
        return track;
    }

    private static int[] computeSeaPath(int fromPacked, int toPacked) {
        SailingSea sea = get();
        if (sea.width == 0)
            return null;
        int start = trackEndpoint(sea, fromPacked);
        int goal = trackEndpoint(sea, toPacked);
        if (start < 0 || goal < 0 || start == goal)
            return null;
        // Leg bounding box + margin first (cheap, covers open-water legs); a leg that must
        // round a continent — Sunset coast to Kandarin dips far south of its box — retries on
        // the full grid. Both results cache, so the expensive case pays once per leg.
        // Staged margins: 60 covers open-water legs; 600 covers rounding a continent
        // (Sunset coast -> Kandarin dips ~500 south of its leg box). No full-grid stage —
        // a 6M-cell Dijkstra is too heavy for the render thread even once.
        int[] track = computeSeaPathInBox(sea, start, goal, 60);
        if (track == null)
            track = computeSeaPathInBox(sea, start, goal, 600);
        if (track == null)
            // Rounding half the world (Weiss, Grimstone): full grid, seconds — but only ever
            // off-thread and only once per leg, then cached.
            track = computeSeaPathInBox(sea, start, goal, Integer.MAX_VALUE);
        return track;
    }

    private static int[] computeSeaPathInBox(SailingSea sea, int start, int goal, int margin) {
        int x0 = margin >= sea.width ? 0
            : Math.max(0, Math.min(start % sea.width, goal % sea.width) - margin);
        int y0 = margin >= sea.height ? 0
            : Math.max(0, Math.min(start / sea.width, goal / sea.width) - margin);
        int x1 = margin >= sea.width ? sea.width - 1
            : Math.min(sea.width - 1, Math.max(start % sea.width, goal % sea.width) + margin);
        int y1 = margin >= sea.height ? sea.height - 1
            : Math.min(sea.height - 1, Math.max(start / sea.width, goal / sea.width) + margin);
        int boxWidth = x1 - x0 + 1;
        int boxHeight = y1 - y0 + 1;
        int[] dist = new int[boxWidth * boxHeight];
        int[] parent = new int[boxWidth * boxHeight];
        java.util.Arrays.fill(dist, Integer.MAX_VALUE);
        java.util.Arrays.fill(parent, -1);
        int boxStart = (start / sea.width - y0) * boxWidth + (start % sea.width - x0);
        int boxGoal = (goal / sea.width - y0) * boxWidth + (goal % sea.width - x0);
        byte[] shore = shoreDistances(sea, x0, y0, boxWidth, boxHeight);
        byte[] parentMove = new byte[boxWidth * boxHeight];
        java.util.Arrays.fill(parentMove, (byte) -1);
        LongHeap queue = new LongHeap();
        dist[boxStart] = 0;
        queue.push(boxStart);
        while (!queue.isEmpty()) {
            long head = queue.pop();
            int index = (int) (head & 0xFFFFFFFFL);
            if ((int) (head >>> 32) > dist[index])
                continue;
            if (index == boxGoal)
                break;
            int x = index % boxWidth;
            int y = index / boxWidth;
            for (int m = 0; m < MOVES.length; m++) {
                int[] move = MOVES[m];
                int nx = x + move[0];
                int ny = y + move[1];
                if (nx < 0 || ny < 0 || nx >= boxWidth || ny >= boxHeight
                    || !bit(sea, x0 + nx, y0 + ny)
                    || obstacleAtGrid(sea, x0 + nx, y0 + ny)) {
                    continue;
                }
                if (knightBlocked(sea, x0 + x, y0 + y, move[0], move[1]))
                    continue;
                // Distance-optimal paths GRAZE obstacles (tangents are shortest) and
                // stair-step for free, so pure Dijkstra hugs every coastline and wiggles.
                // The graded shore penalty pushes tracks into open water wherever it is
                // free; the turn tax makes straight runs win every tie. Track aesthetics
                // only: durations come from the un-penalised wet flood and boxDistance.
                int next = ny * boxWidth + nx;
                int step = move[2] + SHORE_PENALTIES[shore[next]]
                    + (parentMove[index] >= 0 && parentMove[index] != m ? TURN_PENALTY : 0);
                if (dist[index] + step < dist[next]) {
                    dist[next] = dist[index] + step;
                    parent[next] = index;
                    parentMove[next] = (byte) m;
                    queue.push((long) dist[next] << 32 | next);
                }
            }
        }
        if (dist[boxGoal] == Integer.MAX_VALUE)
            return null;
        java.util.List<Integer> waypoints = new ArrayList<>();
        for (int at = boxGoal; at != -1; at = parent[at]) {
            waypoints.add(packWorldPoint(
                sea.minX + x0 + at % boxWidth, sea.minY + y0 + at / boxWidth, 0));
        }
        java.util.Collections.reverse(waypoints);
        return smoothTrack(sea, waypoints);
    }

    /**
     * Graded near-land penalty, indexed by tiles-from-land (capped): hugging (≤2) stays
     * expensive, the 3–5 band is mildly taxed so open water wins whenever it is free, and
     * beyond that the sea is flat. Replaces the old single-radius check — tracks sat at
     * exactly radius 2 because one tile past the cliff was already "free".
     */
    private static final int[] SHORE_PENALTIES = {200, 200, 140, 40, 20, 10, 0};
    /**
     * Per direction-change tax (~1.5 tiles): distance-optimal 16-move paths stair-step for
     * free, and the smoothing could only partially clean the resulting wiggle (screenshot
     * report 2026-08-14). Straightness now wins every tie at the search itself; real turns
     * (channels, headlands) cost one small constant each.
     */
    private static final int TURN_PENALTY = 150;

    /**
     * Tiles-from-land for every box cell (8-dir BFS from land, capped at the penalty
     * table) — one linear pass instead of a 5x5 scan per relaxation.
     */
    private static byte[] shoreDistances(SailingSea sea, int x0, int y0, int boxWidth, int boxHeight) {
        byte[] shore = new byte[boxWidth * boxHeight];
        java.util.Arrays.fill(shore, (byte) (SHORE_PENALTIES.length - 1));
        java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
        for (int y = 0; y < boxHeight; y++) {
            for (int x = 0; x < boxWidth; x++) {
                int gx = x0 + x;
                int gy = y0 + y;
                if (gx >= sea.width || gy >= sea.height || !bit(sea, gx, gy)) {
                    shore[y * boxWidth + x] = 0;
                    queue.add(y * boxWidth + x);
                }
            }
        }
        while (!queue.isEmpty()) {
            int index = queue.poll();
            int depth = shore[index];
            if (depth >= SHORE_PENALTIES.length - 1)
                continue;
            int x = index % boxWidth;
            int y = index / boxWidth;
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int nx = x + dx;
                    int ny = y + dy;
                    if (nx < 0 || ny < 0 || nx >= boxWidth || ny >= boxHeight)
                        continue;
                    int next = ny * boxWidth + nx;
                    if (shore[next] > depth + 1) {
                        shore[next] = (byte) (depth + 1);
                        queue.add(next);
                    }
                }
            }
        }
        return shore;
    }
    /** Re-densified waypoint spacing: progress tracking and off-route bands need dense points. */
    private static final int TRACK_POINT_SPACING = 4;

    /** Standoff radius: hugging means within TWO tiles of land — one tile still reads
     * "almost touching" at sea scale (field capture 212843). */
    private static final int STANDOFF = 2;

    private static boolean nearLand(SailingSea sea, int gridX, int gridY) {
        for (int dx = -STANDOFF; dx <= STANDOFF; dx++) {
            for (int dy = -STANDOFF; dy <= STANDOFF; dy++) {
                int x = gridX + dx;
                int y = gridY + dy;
                if (x < 0 || y < 0 || x >= sea.width || y >= sea.height || !bit(sea, x, y))
                    return true;
            }
        }
        return false;
    }

    /**
     * Long straight legs from a jittery grid path: greedy line-of-sight simplification (extend
     * each leg to the farthest waypoint the straight line can reach over sailable water), then
     * re-densify points every {@link #TRACK_POINT_SPACING} tiles along the straight legs —
     * the overlays and off-route bands measure against WAYPOINTS, so long bare segments would
     * break progress tracking mid-leg.
     */
    private static int[] smoothTrack(SailingSea sea, java.util.List<Integer> waypoints) {
        java.util.List<Integer> corners = new ArrayList<>();
        int trackStart = waypoints.get(0);
        int trackGoal = waypoints.get(waypoints.size() - 1);
        int at = 0;
        corners.add(trackStart);
        while (at < waypoints.size() - 1) {
            int reach = at + 1;
            for (int j = waypoints.size() - 1; j > at + 1; j--) {
                if (lineKeepsStandoff(sea, waypoints.get(at), waypoints.get(j), trackStart, trackGoal)) {
                    reach = j;
                    break;
                }
            }
            corners.add(waypoints.get(reach));
            at = reach;
        }
        // Greedy never revisits: a second pass merges corners whose neighbours connect
        // directly (13 -> fewer helm changes on the capture-212843 leg), repeated to fixpoint.
        boolean merged = true;
        while (merged) {
            merged = false;
            for (int c = 1; c + 1 < corners.size(); c++) {
                if (lineKeepsStandoff(sea, corners.get(c - 1), corners.get(c + 1),
                    trackStart, trackGoal)) {
                    corners.remove(c);
                    merged = true;
                    c--;
                }
            }
        }
        // The boat steers 16 quantized bearings: snap every leg onto them by decomposing
        // each chord into (at most) two runs along adjacent bearings — the adjacent basis
        // determinants are 1, so the decomposition is exact and integer. Points sampled
        // along an exact bearing run are perfectly collinear: the drawn line is straight
        // because the geometry is, not because rendering hides jitter (field screenshot:
        // tracks neither straight nor on sailable headings).
        corners = snapCornersToBearings(sea, corners, trackStart, trackGoal);
        java.util.List<Integer> dense = new ArrayList<>();
        for (int c = 0; c + 1 < corners.size(); c++)
            densifyLeg(dense, corners.get(c), corners.get(c + 1));
        dense.add(corners.get(corners.size() - 1));
        int[] track = new int[dense.size()];
        for (int i = 0; i < track.length; i++)
            track[i] = dense.get(i);
        return track;
    }

    /**
     * Indices of the REAL corners of a dense track: direction measured over a two-point
     * window on each side, so the integer stair-stepping of a densified straight chord
     * (E, E, NE, E...) does not count as helm changes. First and last index included.
     */
    public static java.util.List<Integer> trackCorners(int[] track) {
        java.util.List<Integer> corners = new ArrayList<>();
        corners.add(0);
        for (int w = 2; w + 2 < track.length; w++) {
            double inX = unpackWorldX(track[w]) - unpackWorldX(track[w - 2]);
            double inY = unpackWorldY(track[w]) - unpackWorldY(track[w - 2]);
            double outX = unpackWorldX(track[w + 2]) - unpackWorldX(track[w]);
            double outY = unpackWorldY(track[w + 2]) - unpackWorldY(track[w]);
            double cross = inX * outY - inY * outX;
            double dot = inX * outX + inY * outY;
            // > ~18 degrees of direction change across the window = a genuine turn.
            if (Math.abs(Math.atan2(cross, dot)) > Math.toRadians(18)) {
                corners.add(w);
                w += 2;
            }
        }
        corners.add(track.length - 1);
        return corners;
    }

    /**
     * The 16 boat bearings in angular order — the game's OWN movement vectors (chart-plotter's
     * DX/DY table): a uniform 22.5-degree grid. NOT knight vectors: (2,1) is 26.6 degrees,
     * visibly off the heading a boat actually holds; (9,4) is 24.0, within 1.5 of the grid.
     */
    private static final int[][] BEARINGS = {
        {10, 0}, {9, 4}, {7, 7}, {4, 9}, {0, 10}, {-4, 9}, {-7, 7}, {-9, 4},
        {-10, 0}, {-9, -4}, {-7, -7}, {-4, -9}, {0, -10}, {4, -9}, {7, -7}, {9, -4},
    };

    /**
     * Rewrites each leg between corners as at most two exact bearing runs (A -> A+a*u -> B,
     * u and v adjacent bearings whose cone contains the displacement). Both runs must keep
     * the standoff or the raw chord stays — port approaches and tight channels degrade
     * gracefully instead of failing.
     */
    /** Dogleg turn positions along the first bearing run, tried in order. */
    private static final double[] DOGLEG_FRACTIONS = {0.8, 0.65, 0.5, 0.35, 0.2};

    private static java.util.List<Integer> snapCornersToBearings(SailingSea sea,
        java.util.List<Integer> corners, int trackStart, int trackGoal) {
        java.util.List<Integer> snapped = new ArrayList<>();
        snapped.add(corners.get(0));
        for (int c = 1; c < corners.size(); c++) {
            int from = snapped.get(snapped.size() - 1);
            int to = corners.get(c);
            // Strict standoff only: the corner chord already passed the standoff gates in
            // simplification, so when no on-bearing shape holds the same clearance, the
            // off-grid chord is the HONEST fallback — a relaxed on-bearing shape would
            // trade real shore clearance for grid purity (it legalized a hugging departure
            // at the Pandemonium; hulls gain nothing from relaxing, they are hard line
            // blockers with no clearance band).
            if (!snapLeg(sea, snapped, from, to, trackStart, trackGoal, 0))
                snapped.add(to);
        }
        return snapped;
    }

    /**
     * Appends an on-bearing rewrite of from -> to (two-leg corner, else a three-leg
     * dogleg with the turn slid along the first run — the shape that clears a moored
     * hull the single corner cannot). False when no shape fits at this clearance.
     */
    private static boolean snapLeg(SailingSea sea, java.util.List<Integer> snapped,
        int from, int to, int trackStart, int trackGoal, int depth) {
        int dx = unpackWorldX(to) - unpackWorldX(from);
        int dy = unpackWorldY(to) - unpackWorldY(from);
        int mid = bearingMidpoint(from, dx, dy, false);
        if (mid == from || mid == to) {
            // Already (nearly) a single bearing run: nothing to rewrite. Inside a split
            // that IS the half's answer — the chord was standoff-checked by the caller.
            if (depth > 0) {
                snapped.add(to);
                return true;
            }
            return false;
        }
        int alt = bearingMidpoint(from, dx, dy, true);
        int[] mids = alt == from || alt == to ? new int[]{mid} : new int[]{mid, alt};
        for (int full : mids) {
            if (lineKeepsStandoff(sea, from, full, trackStart, trackGoal)
                && lineKeepsStandoff(sea, full, to, trackStart, trackGoal)) {
                snapped.add(full);
                snapped.add(to);
                return true;
            }
        }
        // Doglegs: mid1 = lerp(from, full, t) stays on the first bearing; mid2 = mid1 +
        // (to - full) makes the middle leg EXACTLY the second bearing's displacement;
        // the final leg is the first bearing's remainder. Only mid1 rounds.
        for (int full : mids) {
            int fx = unpackWorldX(full);
            int fy = unpackWorldY(full);
            int sx = unpackWorldX(from);
            int sy = unpackWorldY(from);
            for (double t : DOGLEG_FRACTIONS) {
                int mid1 = packWorldPoint(
                    sx + (int) Math.round((fx - sx) * t),
                    sy + (int) Math.round((fy - sy) * t), 0);
                int mid2 = packWorldPoint(
                    unpackWorldX(mid1) + unpackWorldX(to) - fx,
                    unpackWorldY(mid1) + unpackWorldY(to) - fy, 0);
                if (mid1 == from || mid1 == mid2 || mid2 == to)
                    continue;
                if (lineKeepsStandoff(sea, from, mid1, trackStart, trackGoal)
                    && lineKeepsStandoff(sea, mid1, mid2, trackStart, trackGoal)
                    && lineKeepsStandoff(sea, mid2, to, trackStart, trackGoal)) {
                    snapped.add(mid1);
                    snapped.add(mid2);
                    snapped.add(to);
                    return true;
                }
            }
        }
        // A gap too narrow for any two-corner shape (hull channels): split at the chord's
        // midpoint — it lies ON the standoff-true chord, so it is sailable — and give each
        // half its own, smaller maneuver. Bounded: two levels, legs no shorter than 8.
        if (depth < 2 && Math.max(Math.abs(dx), Math.abs(dy)) >= 8) {
            int half = packWorldPoint(
                unpackWorldX(from) + dx / 2,
                unpackWorldY(from) + dy / 2, 0);
            if (half != from && half != to && isSailable(half)) {
                int mark = snapped.size();
                if (snapLeg(sea, snapped, from, half, trackStart, trackGoal, depth + 1)
                    && snapLeg(sea, snapped, half, to, trackStart, trackGoal, depth + 1)) {
                    return true;
                }
                while (snapped.size() > mark)
                    snapped.remove(snapped.size() - 1);
            }
        }
        return false;
    }

    /**
     * The corner of the two-bearing decomposition of (dx, dy): from + a*u (or from + b*v
     * when {@code swapOrder}). Returns {@code from} when the displacement is already a
     * single bearing run or the cone search fails.
     */
    private static int bearingMidpoint(int from, int dx, int dy, boolean swapOrder) {
        for (int k = 0; k < BEARINGS.length; k++) {
            int[] u = BEARINGS[k];
            int[] v = BEARINGS[(k + 1) % BEARINGS.length];
            double det = u[0] * v[1] - u[1] * v[0];
            double a = (dx * v[1] - dy * v[0]) / det;
            double b = (dy * u[0] - dx * u[1]) / det;
            // Real-valued cone test: the true bearing vectors have det 40-ish, so the
            // decomposition is fractional; the midpoint rounds to the nearest tile (the
            // half-tile error tilts a long leg by well under a degree).
            if (a < -1e-9 || b < -1e-9)
                continue;
            if (a < 0.5 || b < 0.5)
                return from;
            int x = unpackWorldX(from);
            int y = unpackWorldY(from);
            return swapOrder
                ? packWorldPoint(x + (int) Math.round(b * v[0]),
                    y + (int) Math.round(b * v[1]), 0)
                : packWorldPoint(x + (int) Math.round(a * u[0]),
                    y + (int) Math.round(a * u[1]), 0);
        }
        return from;
    }

    /**
     * Densifies one leg. Exact bearing runs step their basis vector (points ON the line);
     * fallback chords keep the rounded interpolation.
     */
    private static void densifyLeg(java.util.List<Integer> dense, int from, int to) {
        int ax = unpackWorldX(from);
        int ay = unpackWorldY(from);
        int dx = unpackWorldX(to) - ax;
        int dy = unpackWorldY(to) - ay;
        // Bearing-aligned legs interpolate along the true (fractional) direction; rounding
        // keeps every point within half a tile of the ideal line, which is sub-pixel on the
        // world map — no basis-stepping special case needed with the 10-scale vectors.
        int steps = Math.max(1, Math.max(Math.abs(dx), Math.abs(dy)) / TRACK_POINT_SPACING);
        for (int s = 0; s < steps; s++) {
            dense.add(packWorldPoint(
                ax + Math.round((float) dx * s / steps),
                ay + Math.round((float) dy * s / steps), 0));
        }
    }

    /**
     * Supercover line test that PRESERVES the standoff: every cell sailable, and — except
     * within 8 tiles of the track's endpoints (port water must be approachable) — no cell
     * within {@link #STANDOFF} of land. Without the standoff requirement the simplification
     * chords cut straight back around every headland, undoing what the Dijkstra penalty paid
     * to avoid (field capture 212843: smoothed tracks still touching the shore).
     */
    private static boolean lineKeepsStandoff(SailingSea sea, int fromPacked, int toPacked,
        int trackStart, int trackGoal) {
        return lineKeepsStandoff(sea, fromPacked, toPacked, trackStart, trackGoal, true);
    }

    /** {@code requireClearance} false = sailable, obstacle-free water only — the reduced
     * bar for last-resort on-bearing shapes through corridors the raw chord would have
     * threaded anyway. */
    private static boolean lineKeepsStandoff(SailingSea sea, int fromPacked, int toPacked,
        int trackStart, int trackGoal, boolean requireClearance) {
        int x0 = unpackWorldX(fromPacked) - sea.minX;
        int y0 = unpackWorldY(fromPacked) - sea.minY;
        int x1 = unpackWorldX(toPacked) - sea.minX;
        int y1 = unpackWorldY(toPacked) - sea.minY;
        int steps = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)) * 2;
        for (int s = 0; s <= steps; s++) {
            int x = x0 + Math.round((float) (x1 - x0) * s / steps);
            int y = y0 + Math.round((float) (y1 - y0) * s / steps);
            if (!bit(sea, x, y) || obstacleAtGrid(sea, x, y))
                return false;
            int world = packWorldPoint(sea.minX + x, sea.minY + y, 0);
            boolean nearEndpoint =
                WorldPointUtil.distanceBetween(world, trackStart) <= 8
                    || WorldPointUtil.distanceBetween(world, trackGoal) <= 8;
            if (requireClearance && !nearEndpoint && nearLand(sea, x, y))
                return false;
        }
        return true;
    }

    /**
     * Failed or uncomputable tracks RETRY after a cooldown instead of poisoning the cache
     * forever: an early computation (water grid mid-load, a transient failure) permanently
     * dashed its leg - capture 20260827-223426's direct-sail track computed fine offline yet
     * never rendered in the client. Genuine no-track pairs just re-verify every cooldown while
     * a route keeps asking; the BFS is bounded.
     */
    private static final long TRACK_RETRY_MS = 10_000;
    private static final java.util.HashMap<Long, Long> failedTracks = new java.util.HashMap<>();

    private static boolean failureCoolingDown(long key) {
        synchronized (trackCache) {
            Long at = failedTracks.get(key);
            if (at == null)
                return false;
            if (System.currentTimeMillis() - at < TRACK_RETRY_MS)
                return true;
            failedTracks.remove(key);
            return false;
        }
    }

    /** Test visibility: whether a SUCCESSFUL track sits in the cache for this pair. */
    static boolean trackPermanentlyCached(int fromPacked, int toPacked) {
        synchronized (trackCache) {
            return trackCache.get(trackKey(fromPacked, toPacked)) != null;
        }
    }

    private static long trackKey(int fromPacked, int toPacked) {
        return (long) fromPacked << 32 | toPacked & 0xFFFFFFFFL;
    }

    private static int[] cachedTrack(long key) {
        synchronized (trackCache) {
            return trackCache.get(key);
        }
    }

    /** Distinguishes a cached null (no track computable) from a cache miss. */
    private static boolean trackCached(long key) {
        synchronized (trackCache) {
            return trackCache.containsKey(key);
        }
    }

    /**
     * The sea tile a track starts/ends at. A mooring LAND tile maps to its PAIRED water
     * endpoint from the shipped data — the radius spiral can snap to a disconnected inland
     * magenta pocket instead of the harbour (Sunset coast: every track from that port flooded
     * a puddle, returned null, and dashed the whole port). Water tiles map to themselves.
     */
    private static int trackEndpoint(SailingSea sea, int packed) {
        int x = unpackWorldX(packed);
        int y = unpackWorldY(packed);
        for (int[] mooring : sea.moorings) {
            if (mooring[0] == x && mooring[1] == y)
                return (mooring[3] - sea.minY) * sea.width + (mooring[2] - sea.minX);
        }
        if (isSailable(packed))
            return (y - sea.minY) * sea.width + (x - sea.minX);
        return nearestSailable(sea, packed);
    }

    /**
     * Grid index of the nearest sailable tile within 10 of the endpoint, or -1. Ten, not six:
     * the mooring dumper pairs land tiles with water up to 8 tiles away (piers), and the track
     * must reach the water from the same land tile the transport departs from.
     */
    private static int nearestSailable(SailingSea sea, int packed) {
        int px = unpackWorldX(packed);
        int py = unpackWorldY(packed);
        for (int radius = 0; radius <= 10; radius++) {
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dy = -radius; dy <= radius; dy++) {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
                        continue;
                    int x = px + dx - sea.minX;
                    int y = py + dy - sea.minY;
                    if (x >= 0 && y >= 0 && x < sea.width && y < sea.height && bit(sea, x, y))
                        return y * sea.width + x;
                }
            }
        }
        return -1;
    }

    /**
     * Sea tiles covered by a sailing leg of the given duration — the inverse of the duration
     * model every sailing edge (static rows and synthetic legs) is generated with:
     * OVERHEAD_TICKS + tiles / TILES_PER_TICK. COUPLED to that model: if the constants ever
     * change, this must keep inverting whatever replaces them.
     */
    public static int tilesFromDuration(int durationTicks) {
        return (int) Math.round(Math.max(0, durationTicks - OVERHEAD_TICKS) * TILES_PER_TICK);
    }

    /** The shipped port display name, falling back to the boarding tile's coordinates. */
    private static String portName(int mooringIndex) {
        SailingSea sea = get();
        String name = mooringIndex < sea.mooringNames.size()
            ? sea.mooringNames.get(mooringIndex) : "";
        if (!name.isEmpty())
            return name;
        int[] mooring = sea.moorings.get(mooringIndex);
        return mooring[0] + "," + mooring[1];
    }

    /** The shipped walk-reachable flag: a mainland port the walking network serves. */
    private static boolean reachable(int[] mooring) {
        return mooring[4] == 1;
    }

    /**
     * Half-wind (knight) steps must not cut across obstacle corners: both interposed tiles —
     * the half-step along the long axis, and the full short-axis neighbour beside it — must be
     * sailable. The one subtle piece of the 16-bearing geometry, shared by both Dijkstras.
     */
    private static boolean knightBlocked(SailingSea sea, int x, int y, int dx, int dy) {
        return Math.abs(dx) + Math.abs(dy) == 3
            && (!bit(sea, x + dx / 2, y + dy / 2)
                || !bit(sea,
                    Math.abs(dx) == 2 ? x + dx / 2 : x + dx,
                    Math.abs(dx) == 2 ? y + dy : y + dy / 2));
    }

    /** Local-grid sailability test used by the wet-endpoint flood's move loop. */
    private static boolean bit(SailingSea sea, int x, int y) {
        long index = (long) y * sea.width + x;
        return (sea.bits[(int) (index >> 3)] & 1 << (index & 7)) != 0;
    }

    }

package gps;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Tile;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;

/**
 * Live-scene object queries shared by the overlays, mainly the "is this door still closed"
 * check: a door is closed exactly while its closed-variant object id stands on the tile, and
 * opening it swaps the object out, so presence is the whole test.
 */
public class SceneObjects {
    private SceneObjects() {
    }

    /**
     * Scene knowledge about an object id on a tile: standing there, verified absent (the tile is
     * loaded and the object isn't on it — for a door's closed variant that means it stands open),
     * or unknowable because the tile isn't in the loaded scene.
     */
    public enum Presence {
        PRESENT,
        ABSENT,
        OUT_OF_SCENE
    }

    /**
     * Whether an object with this id currently stands on the tile (wall objects cover doors;
     * gates and double doors can be game objects). Only tiles inside the loaded scene can
     * match — which is fine for hints, they matter when the player is close enough to see the
     * object.
     */
    public static boolean objectPresent(Client client, int packedLocation, int objectId) {
        return presence(client, packedLocation, objectId) == Presence.PRESENT;
    }

    public static Presence presence(Client client, int packedLocation, int objectId) {
        boolean inScene = false;
        PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, packedLocation);
        for (int i = 0; i < points.size(); i++) {
            LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
            if (lp == null)
                continue;
            int plane = WorldPointUtil.unpackWorldPlane(points.get(i));
            Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
            if (plane < 0 || plane >= tiles.length)
                continue;
            int sceneX = lp.getSceneX();
            int sceneY = lp.getSceneY();
            if (sceneX < 0 || sceneY < 0 || sceneX >= tiles[plane].length || sceneY >= tiles[plane][sceneX].length)
                continue;
            Tile tile = tiles[plane][sceneX][sceneY];
            if (tile == null)
                continue;
            inScene = true;
            WallObject wall = tile.getWallObject();
            if (wall != null && wall.getId() == objectId)
                return Presence.PRESENT;
            GameObject[] gameObjects = tile.getGameObjects();
            if (gameObjects != null) {
                for (GameObject gameObject : gameObjects) {
                    if (gameObject != null && gameObject.getId() == objectId)
                        return Presence.PRESENT;
                }
            }
        }
        return inScene ? Presence.ABSENT : Presence.OUT_OF_SCENE;
    }
}

package gps;

import java.awt.Dimension;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;

/**
 * A panel that always lays out at the scroll viewport's width. A plain JPanel inside a JScrollPane
 * keeps its preferred width even with the horizontal scrollbar disabled, so any row slightly wider
 * than the viewport pushes the whole content under the vertical scrollbar and gets clipped.
 */
final class ScrollableBox extends JPanel implements Scrollable {
    ScrollableBox(LayoutManager layout) {
        super(layout);
    }

    @Override
    public Dimension getPreferredScrollableViewportSize() {
        return getPreferredSize();
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
        return Math.max(visibleRect.height - 16, 16);
    }

    @Override
    public boolean getScrollableTracksViewportWidth() {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight() {
        return false;
    }
}

package gps;

import java.util.ArrayList;
import java.util.List;
import java.util.function.IntSupplier;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;

/**
 * Passive sea-obstacle learning (plan step L19, out of the plugin class): every ten ticks,
 * harvest scene tiles that the shipped ocean calls sailable but live collision blocks (moored
 * vessels, harbour clutter). The offline map plans; the client corrects itself as scenes
 * reveal the truth.
 */
final class SeaObstacleLearner {
    static final int SCAN_PERIOD_TICKS = 10;
    // Scene border padding reads 0xFFFFFF (everything blocked); the first field harvest showed
    // the border bands dwarfing the actual galleon, so a 3-tile edge margin is skipped too.
    private static final int EDGE_MARGIN = 3;
    // The player's own hull is a WorldEntity projecting live-blocked collision onto sailable
    // water: without this exclusion every scan learned the boat's footprint as a permanent
    // obstacle, a breadcrumb trail along everywhere the player sailed (field capture 232906:
    // the direct channel home was sealed by the player's own wake, forcing a disembark and
    // re-embark detour through Cairn Isle).
    private static final int OWN_BOAT_RADIUS = 10;

    private final Client client;
    private final IntSupplier playerLocation;
    private int cooldown;

    SeaObstacleLearner(Client client, IntSupplier playerLocation) {
        this.client = client;
        this.playerLocation = playerLocation;
    }

    /** Client thread, once per game tick. */
    void onTick() {
        if (--cooldown <= 0) {
            cooldown = SCAN_PERIOD_TICKS;
            scan();
        }
    }

    /** A real obstacle carries BLOCK_MOVEMENT_OBJECT; the border padding and margin are skipped. */
    private void scan() {
        WorldView view = client.getTopLevelWorldView();
        if (view == null || view.getCollisionMaps() == null || view.getPlane() != 0)
            return;
        CollisionData collision = view.getCollisionMaps()[0];
        if (collision == null)
            return;
        int[][] flags = collision.getFlags();
        int baseX = view.getBaseX();
        int baseY = view.getBaseY();
        int playerAt = playerLocation.getAsInt();
        List<Integer> found = null;
        for (int sx = EDGE_MARGIN; sx < flags.length - EDGE_MARGIN; sx++) {
            for (int sy = EDGE_MARGIN; sy < flags[sx].length - EDGE_MARGIN; sy++) {
                int tileFlags = flags[sx][sy];
                if (tileFlags == 0xFFFFFF || (tileFlags & CollisionDataFlag.BLOCK_MOVEMENT_OBJECT) == 0)
                    continue;
                int x = baseX + sx;
                int y = baseY + sy;
                if (playerAt != WorldPointUtil.UNDEFINED
                    && Math.max(Math.abs(WorldPointUtil.unpackWorldX(playerAt) - x),
                        Math.abs(WorldPointUtil.unpackWorldY(playerAt) - y)) <= OWN_BOAT_RADIUS) {
                    continue;
                }
                int packed = WorldPointUtil.packWorldPoint(x, y, 0);
                if (SailingSea.isSailable(packed) && !SailingSea.obstacleAt(x, y)) {
                    if (found == null)
                        found = new ArrayList<>();
                    found.add(packed);
                }
            }
        }
        if (found != null)
            SailingSea.learnObstacles(found);
    }
}

package gps;

import java.util.Locale;
import java.util.Map;

/**
 * Player vocabulary for the destination search (plan step N11): query tokens that are neither a
 * prefix nor a subsequence of the place they mean. Prefix forms ("brim", "cath", "dray") already
 * match through the tiers, so only the genuinely different spellings live here.
 */
final class SearchAliases {
    private static final Map<String, String> ALIASES = Map.ofEntries(
        Map.entry("ge", "grand exchange"),
        Map.entry("wildy", "wilderness"),
        Map.entry("lumby", "lumbridge"),
        Map.entry("fally", "falador"),
        Map.entry("cammy", "camelot"),
        Map.entry("ardy", "ardougne"),
        Map.entry("priff", "prifddinas"),
        Map.entry("pc", "pest control"),
        Map.entry("cw", "castle wars"),
        Map.entry("cwars", "castle wars"),
        Map.entry("gwd", "god wars dungeon"),
        Map.entry("cox", "chambers of xeric"),
        Map.entry("tob", "theatre of blood"),
        Map.entry("toa", "tombs of amascut"),
        Map.entry("sw", "soul wars"),
        Map.entry("mta", "mage training arena"),
        Map.entry("wt", "wintertodt"),
        Map.entry("bf", "blast furnace"),
        Map.entry("nmz", "nightmare zone"),
        Map.entry("barb", "barbarian"),
        Map.entry("kq", "kalphite queen"),
        Map.entry("zmi", "ourania"));

    private SearchAliases() {
    }

    /**
     * The query with every alias token replaced by what it stands for, lower-cased; the query
     * itself (lower-cased, trimmed) when no token is an alias.
     */
    static String expand(String query) {
        String[] tokens = query.toLowerCase(Locale.ROOT).trim().split("\\s+");
        StringBuilder out = new StringBuilder();
        boolean changed = false;
        for (String token : tokens) {
            String expansion = ALIASES.get(token);
            if (out.length() > 0)
                out.append(' ');
            out.append(expansion != null ? expansion : token);
            changed |= expansion != null;
        }
        return changed ? out.toString() : query.toLowerCase(Locale.ROOT).trim();
    }
}

package gps;

import java.util.ArrayList;
import java.util.List;

/**
 * The destination search's recent-selections list: the last {@link #LIMIT} picks, most recent
 * first, persisted across sessions as one config string (rows of {@code category\tname\tpacked}).
 * Pure functions — the plugin owns the stored copy and the config write.
 */
final class SearchHistory {
    static final int LIMIT = 10;

    private SearchHistory() {
    }

    /** A new list with {@code entry} at the front, duplicates removed, capped at {@link #LIMIT}. */
    static List<Destinations.Entry> push(List<Destinations.Entry> history, Destinations.Entry entry) {
        List<Destinations.Entry> out = new ArrayList<>();
        out.add(entry);
        for (Destinations.Entry old : history) {
            if (out.size() >= LIMIT)
                break;
            if (old.packedPosition != entry.packedPosition || !old.name.equals(entry.name))
                out.add(old);
        }
        return out;
    }

    static String serialize(List<Destinations.Entry> history) {
        StringBuilder sb = new StringBuilder();
        for (Destinations.Entry entry : history) {
            if (sb.length() > 0)
                sb.append('\n');
            sb.append(entry.category).append('\t').append(entry.name).append('\t').append(entry.packedPosition);
        }
        return sb.toString();
    }

    static List<Destinations.Entry> deserialize(String raw) {
        return deserialize(raw, LIMIT);
    }

    /** Deserializes an entry list with a caller-chosen cap (the favourites list allows more rows). */
    static List<Destinations.Entry> deserialize(String raw, int limit) {
        List<Destinations.Entry> out = new ArrayList<>();
        if (raw == null || raw.isEmpty())
            return out;
        for (String line : raw.split("\\R")) {
            String[] fields = line.split("\t");
            if (fields.length < 3)
                continue;
            try {
                out.add(new Destinations.Entry(fields[0], fields[1], Integer.parseInt(fields[2])));
                if (out.size() >= limit)
                    break;
            }
            catch (NumberFormatException e) {
                // A malformed row (hand-edited config) is dropped rather than poisoning the list.
            }
        }
        return out;
    }
}

package gps;

import java.util.Locale;

/**
 * Fuzzy name matching for the destination search. {@link #score} returns 0 for no match and a
 * positive score otherwise, tiered so tighter matches always outrank looser ones:
 * exact name &gt; name prefix &gt; word prefixes ("var pal" finds "Varrock Palace") &gt;
 * substring &gt; subsequence (query letters appear in order with gaps — typo-tolerant
 * abbreviations like "brmhvn" for "Brimhaven"). Within a tier, shorter names rank higher.
 */
final class SearchMatcher {
    private static final int TIER_EXACT = 1000;
    private static final int TIER_PREFIX = 900;
    private static final int TIER_WORD_PREFIX = 800;
    private static final int TIER_SUBSTRING = 700;
    private static final int TIER_SUBSEQUENCE = 300;
    // Within-tier penalty for longer names; kept below the tier spacing so tiers never cross.
    private static final int MAX_LENGTH_PENALTY = 80;
    // Subsequence matching needs a few characters to say anything — 1-2 letters match everything.
    private static final int MIN_SUBSEQUENCE_QUERY = 3;

    private SearchMatcher() {
    }

    static int score(String name, String query) {
        final String literal = query.toLowerCase(Locale.ROOT).trim();
        final String expanded = SearchAliases.expand(query);
        final int direct = scoreLiteral(name, literal);
        return expanded.equals(literal) ? direct : Math.max(direct, scoreLiteral(name, expanded));
    }

    private static int scoreLiteral(String name, String query) {
        final String n = name.toLowerCase(Locale.ROOT);
        final String q = query;
        if (q.isEmpty())
            return 0;
        final int lengthPenalty = Math.min(n.length(), MAX_LENGTH_PENALTY);
        if (n.equals(q))
            return TIER_EXACT;
        if (n.startsWith(q))
            return TIER_PREFIX - lengthPenalty;
        if (wordPrefixes(n, q))
            return TIER_WORD_PREFIX - lengthPenalty;
        if (n.contains(q))
            return TIER_SUBSTRING - lengthPenalty;
        final String letters = q.replaceAll("\\s+", "");
        if (letters.length() >= MIN_SUBSEQUENCE_QUERY && isSubsequence(n, letters))
            return TIER_SUBSEQUENCE - lengthPenalty;
        return 0;
    }

    /** Every whitespace-separated query token prefixes a distinct name word, in order. */
    private static boolean wordPrefixes(String name, String query) {
        final String[] tokens = query.split("\\s+");
        final String[] words = name.split("[^a-z0-9]+");
        int w = 0;
        for (String token : tokens) {
            boolean matched = false;
            while (w < words.length) {
                if (words[w++].startsWith(token)) {
                    matched = true;
                    break;
                }
            }
            if (!matched)
                return false;
        }
        return true;
    }

    /** The query's letters appear in the name in order, gaps allowed. */
    private static boolean isSubsequence(String name, String letters) {
        int i = 0;
        for (int j = 0; j < name.length() && i < letters.length(); j++) {
            if (name.charAt(j) == letters.charAt(i))
                i++;
        }
        return i == letters.length();
    }
}

package gps;

import java.util.ArrayList;
import java.util.List;

/**
 * What the destination search remembers (plan step L27, out of the plugin class): the recent
 * selections, most recent first, and the saved favourite positions in saved order. Both live
 * as immutable snapshots the panel reads on the Swing thread and persist on every change.
 */
final class SearchMemory {
    private final ChoiceStore store;
    private volatile List<Destinations.Entry> history = new ArrayList<>();
    private volatile List<Destinations.Entry> favorites = new ArrayList<>();

    SearchMemory(ChoiceStore store) {
        this.store = store;
    }

    void load() {
        history = store.loadSearchHistory();
        favorites = store.loadFavorites();
    }

    /** The search box's recent selections, most recent first. */
    List<Destinations.Entry> history() {
        return history;
    }

    /** Records a search selection at the front of the history (deduplicated, capped). */
    void recordSelection(Destinations.Entry entry) {
        List<Destinations.Entry> updated = SearchHistory.push(history, entry);
        history = updated;
        store.saveSearchHistory(updated);
    }

    /** The saved favourite positions, in saved order. */
    List<Destinations.Entry> favorites() {
        return favorites;
    }

    /** Saves a favourite position; a favourite with the same label is replaced; the list is capped. */
    void addFavorite(String label, int packedPosition) {
        List<Destinations.Entry> updated = new ArrayList<>();
        for (Destinations.Entry entry : favorites) {
            if (!entry.name.equals(label))
                updated.add(entry);
        }
        if (updated.size() < ChoiceStore.FAVORITES_LIMIT)
            updated.add(new Destinations.Entry("favorite", label, packedPosition));
        favorites = updated;
        store.saveFavorites(updated);
    }

    /** Removes the favourite with that label and position. */
    void removeFavorite(Destinations.Entry favorite) {
        List<Destinations.Entry> updated = new ArrayList<>();
        for (Destinations.Entry entry : favorites) {
            if (!entry.name.equals(favorite.name) || entry.packedPosition != favorite.packedPosition)
                updated.add(entry);
        }
        favorites = updated;
        store.saveFavorites(updated);
    }
}

