    public int getWalkPreferenceSeconds() {
        return preferences.walkPreferenceSeconds();
    }

    public void setWalkPreferenceSeconds(int seconds) {
        preferences.setWalkPreferenceSeconds(seconds);
        resortRoutesByPriority();
