     * Manually (re)compute the alternative routes for whatever destination GPS currently has
     * set — read live from the active pathfinder. With no target set, just refreshes the methods catalog.
     */
    /** Clears the current destination and its route (panel Clear button / clear-path hotkey). */
    public void clearTarget() {
        destination.clearLater();
    }

    public void recomputeAlternatives() {
        routes.recompute();
    }

    /**
     * The start tile to search alternatives from: the player's current (instance-correct) location,
     * matching what GPS itself uses for recalculation, falling back to the destination's recorded
     * start. Client thread.
     */
    int altStart() {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer != null)
            return fromLocalInstance(client, localPlayer);
        return destination.start();
    }

    public boolean canLoadMoreRoutes() {
        return routes.canLoadMore();
    }

    public void loadMoreRoutes() {
        routes.loadMore();
    }

    // The displayed route's directions, built once per route instance (see DirectionsCache).
    private final DirectionsCache directions = new DirectionsCache();

    /** The step-by-step directions for {@code route}, cached per route instance. */
    public List<RouteDirections.Step> getRouteDirections(RouteOption route) {
        return directions.of(this, route);
    }

    /**
     * Where the current destination came from ("map pin", "Quest Helper", ...) or null when unknown.
     */
    public String getTargetSource() {
        return destination.source();
    }

    /**
     * Reports an issue WITHOUT sending or touching anything outside the panel: the routing
     * context (see IssueReport) is shown in a text box at the top of the panel for the player to
     * copy BY HAND, and a plain, static GitHub new-issue link opens (the repo's issue template
     * says where to paste). No pre-filled URL, no clipboard API: nothing for the hub review to
     * flag, and the player sees exactly what they share.
     */
    public void reportIssue() {
        // Item names come from the item definitions, which are client-thread-only: build the
        // whole body there; the panel work then happens on the EDT.
        clientThread.invokeLater(() -> {
            final String context = new IssueReport(this).body();
            SwingUtilities.invokeLater(() -> {
                if (altPanel != null)
                    altPanel.showReportContext(context);
                net.runelite.client.util.LinkBrowser.browse(BuildInfo.GITHUB_NEW_ISSUE);
            });
        });
    }

    /** Writes the routing-state snapshot (see DebugSnapshot); the panel's "Save debug snapshot". */
    public void captureDebugSnapshot() {
        clientThread.invokeLater(() -> new DebugSnapshot(this).capture());
    }

    /** World-map pixel projection, for the map overlays. */
    WorldMapProjection worldMap() {
        return worldMap;
    }

    /** The minimap clip shape, for the minimap overlay. */
    MinimapClip minimapClip() {
        return minimapClip;
    }

    // ---- State the diagnostics classes (IssueReport, DebugSnapshot) read; package-private ----

    RouteSession session() {
        return session;
    }

    List<TeleportMethod> teleportCatalog() {
        return routes.catalog();
    }

    Map<TeleportMethod, MethodAvailability> unavailableMethods() {
        return routes.unavailable();
    }

    ShortestPathPanel panel() {
        return altPanel;
    }

    /** Whether the current destination is a round trip (out and back), carried into every generation for it. */
    boolean isRoundTripWanted() {
        return destination.isRoundTrip();
    }

    PohDetectionService pohDetection() {
        return pohDetection;
    }

    boolean spiritTreesParsedLive() {
        return spiritTrees != null && spiritTrees.isParsedLive();
    }

    AlternativeRoutesService altRoutesService() {
        return routes.service();
    }

    RouteDirectionsOverlay routeDirectionsOverlay() {
        return routeDirectionsOverlay;
    }

    Gson gson() {
        return gson;
    }

    /** Reset excluded methods (the burger menu). Seasonal methods are gated by their own toggle, not here. */
    public void clearExclusions() {
        clientThread.invoke(exclusions::clear);
    }

    /**
     * Whether the displayed route list was generated with different method exclusions than are
     * currently selected — i.e. the user toggled methods since and hasn't pressed Refresh yet.
     */
    public boolean isRouteListStale() {
        return exclusions.isStale();
    }

    public AlternativeRoutesMode getRoutesMode() {
        return routes.mode();
    }

    /**
     * Whether the bank's contents are known this session (false until the bank has been opened once).
     * Bank mode cannot see banked teleports until this is true — same constraint as the classic Shortest Path engine's
     * own INVENTORY_AND_BANK setting.
     */
    public boolean isBankContentsKnown() {
        return bankSnapshots != null && bankSnapshots.isKnown();
    }

    /**
     * Whether the known bank contents were restored from a previous session's saved snapshot rather
     * than seen live — the panel labels the source, since a restored snapshot can be stale.
     */
    public boolean isBankRestored() {
        return bankSnapshots != null && bankSnapshots.isRestored();
    }

    public void setRoutesMode(AlternativeRoutesMode mode) {
        routes.setMode(mode);
    }

    /** Called by the panel when the GPS sidebar tab is shown or hidden (see RouteController). */
    void setAltPanelVisible(boolean visible) {
        routes.setPanelVisible(visible);
    }

}

package gps;

import net.runelite.api.GameState;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

/**
 * The GPS sidebar button (plan step L20, out of the plugin class): mounted only in-game, since
 * it does nothing useful on the login screen. LOADING, HOPPING and CONNECTION_LOST leave it as
 * it is, so world hops do not flicker it.
 */
final class SidebarButton {
    private final ClientToolbar toolbar;
    private final NavigationButton button;
    private boolean shown;

    SidebarButton(ClientToolbar toolbar, NavigationButton button) {
        this.toolbar = toolbar;
        this.button = button;
    }

    /** Every game-state change: shown when logged in, hidden on the login screens. */
    void onGameState(GameState state) {
        switch (state) {
            case LOGGED_IN:
                show(true);
                break;
            case LOGIN_SCREEN:
            case LOGIN_SCREEN_AUTHENTICATOR:
            case STARTING:
                show(false);
                break;
            default:
                break;
        }
    }

    void show(boolean show) {
        if (show == shown)
            return;
        shown = show;
        if (show)
            toolbar.addNavigation(button);
        else
            toolbar.removeNavigation(button);
    }

    /** Opens the panel (the focus-search hotkey). */
    void open() {
        toolbar.openPanel(button);
    }

    /** Plugin shutdown: off the toolbar whatever the state. */
    void remove() {
        toolbar.removeNavigation(button);
        shown = false;
    }
}

package gps;

import java.util.HashMap;
import java.util.Map;

/**
 * Which spellbook component a teleport spell's Display info names, from spell-widgets.tsv: the
 * exact text first, else its stem before ": ", " — " or " (", so every "Teleport to Boat" variant
 * and "Varrock Teleport: GE" land on their one spell.
 */
final class SpellWidgets {
    private static final String[] QUALIFIERS = {": ", " — ", " ("};
    private static Map<String, Integer> components;

    private SpellWidgets() {
    }

    /** The packed component id of the spell, or -1 when the table has no row for it. */
    static synchronized int componentFor(String spell) {
        if (spell == null)
            return -1;
        if (components == null) {
            components = new HashMap<>();
            for (String[] row : ItemVariations.rows("/spell-widgets.tsv"))
                components.put(row[0], Integer.parseInt(row[1]));
        }
        Integer id = components.get(spell);
        if (id == null)
            id = components.get(stem(spell));
        return id == null ? -1 : id;
    }

    private static String stem(String spell) {
        for (String qualifier : QUALIFIERS) {
            int at = spell.indexOf(qualifier);
            if (at > 0)
                spell = spell.substring(0, at);
        }
        return spell;
    }
}

package gps;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.RoundRectangle2D;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Frames the spell the displayed route casts next in the open spellbook (see {@link SpellWidgets}),
 * in the "Next item" colour; nothing when the next step is not a spell or its spellbook is not the
 * one shown.
 */
final class SpellbookOverlay extends Overlay {
    private final Client client;
    private final ShortestPathPlugin plugin;

    SpellbookOverlay(Client client, ShortestPathPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        RouteItemCue cue = plugin.nextStepItems();
        if (cue == null || cue.spell == null || !plugin.display().highlightRouteItem)
            return null;
        int component = SpellWidgets.componentFor(cue.spell);
        Widget spell = component < 0 ? null : client.getWidget(component);
        if (spell == null || spell.isHidden())
            return null;
        Rectangle bounds = spell.getBounds();
        graphics.setColor(plugin.display().colourRouteItem);
        graphics.setStroke(new BasicStroke(2));
        graphics.draw(new RoundRectangle2D.Double(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, 6, 6));
        return null;
    }
}

package gps;

import gps.pathfinder.PathfinderConfig;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

/**
 * The planted spirit trees (plan step L17, out of the plugin class): read once per session from
 * the spirit-tree travel menu when it opens, persisted per character so the next session starts
 * synced, and restored from that snapshot until the live menu is seen. The pathfinder config
 * holds the set (null = never synced: farmable trees are then treated conservatively).
 */
final class SpiritTreeSync {
    /** RSProfile-scoped: the planted spirit trees detected from the travel menu, comma-separated. */
    static final String CONFIG_KEY_SPIRIT_TREES = "plantedSpiritTrees";

    private static final Pattern LABEL_MENU = Pattern.compile("<col=735a28>(.+)</col>: (<col=5f5f5f>)?(.+)");
    private static final Pattern LABEL_MENU_NEW = Pattern.compile("<col=ffffff>(.+)</col>: (<col=5f5f5f>)?(.+)");
    // Tree Gnome Village is always the first row and always available; a cheap length check
    // before the regex. "<col=735a28>1</col>: Tree Gnome Village" and its new-menu twin are 39.
    private static final int FIRST_ROW_LENGTH = 39;

    private final Client client;
    private final ClientThread clientThread;
    private final ConfigManager configManager;
    private final String configGroup;
    private final PathfinderConfig pathfinderConfig;
    private final Runnable onSynced;

    // Whether the travel menu has been parsed THIS session. Distinct from the set being non-null:
    // a restored snapshot fills the set but must not block the fresher live read when the menu
    // opens (a newly planted tree only shows up in the menu).
    private boolean parsedLive;

    SpiritTreeSync(Client client, ClientThread clientThread, ConfigManager configManager, String configGroup,
        PathfinderConfig pathfinderConfig, Runnable onSynced) {
        this.client = client;
        this.clientThread = clientThread;
        this.configManager = configManager;
        this.configGroup = configGroup;
        this.pathfinderConfig = pathfinderConfig;
        this.onSynced = onSynced;
    }

    /** Whether the travel menu has been seen this session or restored, so the planted set is known. */
    boolean isSynced() {
        return pathfinderConfig.availableSpiritTrees != null;
    }

    /** Whether the set came from the live menu this session rather than the snapshot. */
    boolean isParsedLive() {
        return parsedLive;
    }

    /** The farmable trees detected as planted-and-grown (menu order), or empty when not synced. */
    List<String> planted() {
        Set<String> available = pathfinderConfig.availableSpiritTrees;
        if (available == null)
            return List.of();
        List<String> planted = new ArrayList<>();
        for (String name : PathfinderConfig.FARMABLE_SPIRIT_TREES) {
            if (available.contains(name))
                planted.add(name);
        }
        return planted;
    }

    /** A widget opened: the travel menu (either interface) is parsed once per session. */
    void widgetLoaded(int groupId) {
        if (parsedLive)
            return;
        switch (groupId) {
            case InterfaceID.MENU:
                clientThread.invokeLater(() -> parseMenu(false));
                break;
            case InterfaceID.MENU_NEW:
                clientThread.invokeLater(() -> parseMenu(true));
                break;
            default:
                break;
        }
    }

    /** Restores the persisted set when none is known yet (login, plugin start). */
    void restore() {
        if (pathfinderConfig.availableSpiritTrees != null)
            return;
        String raw = configManager.getRSProfileConfiguration(configGroup, CONFIG_KEY_SPIRIT_TREES);
        if (raw != null) {
            pathfinderConfig.availableSpiritTrees = raw.isEmpty()
                ? new HashSet<>() : new HashSet<>(Arrays.asList(raw.split(",")));
        }
    }

    /** Logged out: the next character starts from its own snapshot. */
    void reset() {
        pathfinderConfig.availableSpiritTrees = null;
        parsedLive = false;
    }

    private void parseMenu(boolean newMenu) {
        // Referencing
        // https://github.com/trs/runelite-teleport-maps/blob/e006270494500ab8e4826903b377bb945ca9fc96/src/main/java/com/mjhylkema/TeleportMaps/components/adventureLog/SpiritTreeMap.java#L141
        Widget container = newMenu ? client.getWidget(InterfaceID.MENU_NEW, 9) : client.getWidget(InterfaceID.MENU, 3);
        if (container == null)
            return;
        Widget[] children = container.getDynamicChildren();
        if (children == null || children.length == 0)
            return;
        String[] rows = new String[children.length];
        for (int i = 0; i < children.length; i++)
            rows[i] = children[i].getText();
        Set<String> available = parseLabels(rows, newMenu);
        if (available == null)
            return;
        pathfinderConfig.availableSpiritTrees = available;
        parsedLive = true;
        // Persist per character, so next session starts synced instead of asking for a travel-menu
        // visit again. (Comma-safe: no spirit tree location name contains a comma.)
        configManager.setRSProfileConfiguration(configGroup, CONFIG_KEY_SPIRIT_TREES, String.join(",", available));
        onSynced.run();
    }

    /**
     * The usable trees named in the menu rows, or null when the rows are not the spirit-tree
     * travel menu. A greyed row (group 2, the disabled colour tag) is a tree the player cannot use.
     */
    static Set<String> parseLabels(String[] rows, boolean newMenu) {
        if (rows == null || rows.length == 0 || rows[0] == null || rows[0].length() != FIRST_ROW_LENGTH)
            return null;
        Pattern pattern = newMenu ? LABEL_MENU_NEW : LABEL_MENU;
        Set<String> available = new HashSet<>();
        for (String row : rows) {
            if (row == null)
                continue;
            Matcher matcher = pattern.matcher(row);
            if (!matcher.matches() || matcher.group(2) != null)
                continue;
            available.add(matcher.group(3));
        }
        return available;
    }
}

package gps;

import lombok.Getter;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * A stable, human-meaningful identity for a single teleport/transport option, used by the
 * alternative-routes feature both as the row shown in the side panel and as the key that the user
 * can exclude from the next search.
 * <p>
 * Identity is {@code (type, displayInfo, destination)}: the {@link TransportType} groups options
 * into a category (Spells, Fairy Rings, Items, ...), {@code displayInfo} is the per-option label the
 * data files carry (e.g. "Varrock Teleport", "Ardougne cloak: Monastery", or a fairy-ring code), and
 * the packed {@code destination} disambiguates options that carry no display info.
 */
@Getter
public final class TeleportMethod {
    private final TransportType type;
    private final String displayInfo;
    private final int destination;
    // Carried metadata (NOT part of identity/equals): whether using this consumes a charge or the
    // item itself (teleport tabs, charged jewellery) versus being permanent/unlimited. Only
    // meaningful for item methods; defaults false for methods built without a transport.
    private final boolean consumable;
    // Carried metadata (NOT identity): for the jewellery-box transport type, WHICH piece of
    // furniture the row is — the same type covers the box itself and the mounted Xeric's
    // talisman / glory / digsite pendant / mythical cape (issue #19: a Xeric's route read
    // "Jewellery box to 2: Glade"). Null for every other type.
    private final String mount;

    public TeleportMethod(TransportType type, String displayInfo, int destination) {
        this(type, displayInfo, destination, false, null);
    }

    public TeleportMethod(TransportType type, String displayInfo, int destination, boolean consumable) {
        this(type, displayInfo, destination, consumable, null);
    }

    public TeleportMethod(TransportType type, String displayInfo, int destination, boolean consumable,
        String objectInfo) {
        this.type = type;
        this.displayInfo = (displayInfo == null || displayInfo.isEmpty()) ? null : displayInfo;
        this.destination = destination;
        this.consumable = consumable;
        this.mount = TransportType.TELEPORTATION_BOX.equals(type) ? mountOf(objectInfo) : null;
    }

    public static TeleportMethod fromTransport(Transport transport) {
        return new TeleportMethod(transport.getType(), transport.getDisplayInfo(),
            transport.getDestination(), transport.isConsumable(), transport.getObjectInfo());
    }

    /** The furniture a jewellery-box-type row belongs to, from its "menuOption menuTarget id". */
    static String mountOf(String objectInfo) {
        if (objectInfo == null)
            return null;
        String lower = objectInfo.toLowerCase(java.util.Locale.ROOT);
        if (lower.contains("xeric"))
            return "Xeric's talisman";
        if (lower.contains("glory"))
            return "Amulet of glory";
        if (lower.contains("digsite"))
            return "Digsite pendant";
        if (lower.contains("mythical"))
            return "Mythical cape";
        return null;
    }

    /**
     * The grouping bucket shown as a section header in the panel.
     */
    public String category() {
        return categoryOf(type);
    }

    /**
     * The per-option label shown in the panel row. Falls back to the category plus the destination
     * tile when the data file carries no display info (common for spells whose info is the spell name).
     */
    public String label() {
        if (displayInfo != null) {
            // A mounted item under the jewellery-box type names its furniture, or the catalog
            // shows "2: Glade" under a "Jewellery box" heading it never belonged to.
            if (mount != null)
                return mount + ": " + displayInfo;
            // Charters share the "Boats & ships" bucket with ships to the same towns — two bare
            // "Port Sarim" rows were indistinguishable, and searching "charter" found nothing.
            if (TransportType.CHARTER_SHIP.equals(type))
                return "Charter: " + displayInfo;
            return displayInfo;
        }
        int x = WorldPointUtil.unpackWorldX(destination);
        int y = WorldPointUtil.unpackWorldY(destination);
        return category() + " (" + x + ", " + y + ")";
    }

    /**
     * The label used where the method appears WITHOUT its category heading (route cards, direction
     * steps): network methods' data labels are bare destinations ("Varrock", "6: Kourend Woodland"),
     * which read as places rather than travel methods there, so the vehicle is named. Catalog rows,
     * which sit under their category header, keep the bare {@link #label()}.
     */
    public String routeLabel() {
        String vehicle = displayInfo == null ? null : (mount != null ? mount : vehiclePhrase(type));
        return vehicle == null ? label() : vehicle + " to " + displayInfo;
    }

    /** The vehicle name for network methods whose data label is a bare destination; null otherwise. */
    private static String vehiclePhrase(TransportType type) {
        return gps.transport.TransportTypePresentation.vehicleOf(type);
    }

    /**
     * Whether a transport type counts as a travel "method" worth listing and excluding. Plain local
     * connectors (doors/ladders/stairs and agility/grapple shortcuts) are walking, not a method.
     */
    public static boolean isMethodType(TransportType type) {
        return type != null
            && type != TransportType.TRANSPORT
            && type != TransportType.AGILITY_SHORTCUT
            && type != TransportType.GRAPPLE_SHORTCUT
            // Sailing is deliberately NOT a catalog method: 2,756 generated port-pair rows
            // would drown the hand-curated methods, and it has its own Travel options section.
            && type != TransportType.SAILING;
    }

    public static String categoryOf(TransportType type) {
        return gps.transport.TransportTypePresentation.categoryOf(type);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o)
            return true;
        if (!(o instanceof TeleportMethod))
            return false;
        TeleportMethod other = (TeleportMethod) o;
        return destination == other.destination
            && type == other.type
            && (displayInfo == null ? other.displayInfo == null : displayInfo.equals(other.displayInfo));
    }

    @Override
    public int hashCode() {
        int result = type == null ? 0 : type.hashCode();
        result = 31 * result + (displayInfo == null ? 0 : displayInfo.hashCode());
        result = 31 * result + destination;
        return result;
    }

    @Override
    public String toString() {
        return category() + ": " + label();
    }
}

