package gps;

import java.awt.Component;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

import static gps.PanelWidgets.sectionShell;

/**
 * The "Travel options" slot (panel series P3, out of the panel class): one collapsible home for
 * everything routing may use, the player-stated configuration sections and the teleport-methods
 * catalog, all sharing the same header style. Fixed below the panel header (the catalog scrolls
 * inside its own bounded box instead of pushing the route list down). Rebuilt only when its
 * inputs change: routes stream several updates per generation, and rebuilding a thousand
 * catalog rows on the EDT for each of them made the toggles unresponsive (the row under the
 * cursor kept being replaced).
 */
final class TravelOptionsView extends JPanel {
    private final ConfigSectionsView sections;
    private final MethodCatalogView catalog;
    private boolean expanded;
    // Snapshot of the inputs the slot was last built from (see needsRebuild).
    private List<TeleportMethod> builtCatalog;
    private Set<TeleportMethod> builtExclusions;
    private Map<TeleportMethod, MethodAvailability> builtUnavailable;
    private boolean builtCatalogExpanded;

    TravelOptionsView(ShortestPathPlugin plugin, Runnable refreshAll) {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        sections = new ConfigSectionsView(plugin, this::rebuild, refreshAll);
        catalog = new MethodCatalogView(plugin, this::rebuild, () -> {
            revalidate();
            repaint();
        });
    }

    /** Whether the inputs changed since the slot was last built. */
    boolean needsRebuild(List<TeleportMethod> newCatalog, Set<TeleportMethod> exclusions,
        Map<TeleportMethod, MethodAvailability> unavailable) {
        return !newCatalog.equals(builtCatalog) || !exclusions.equals(builtExclusions)
            || !unavailable.equals(builtUnavailable) || catalog.isExpanded() != builtCatalogExpanded;
    }

    /** Rebuilds the slot for the given inputs, carrying the catalog rows' scroll position over. */
    void rebuild(List<TeleportMethod> newCatalog, Set<TeleportMethod> exclusions,
        Map<TeleportMethod, MethodAvailability> unavailable) {
        catalog.update(newCatalog, exclusions, unavailable);
        rebuild();
    }

    /** The Log-storage-low banner for the notes strip (see ConfigSectionsView). */
    JPanel balloonLowBanner(List<String> lowTypes) {
        return sections.balloonLowBanner(lowTypes);
    }

    /** The tier menu for a method, shared by the route cards and the catalog rows. */
    void showPriorityMenu(Component anchor, TeleportMethod method) {
        catalog.showPriorityMenu(anchor, method);
    }

    /** Rebuilds with the current inputs (a header toggle, a tier or funnel change). */
    private void rebuild() {
        // The rebuild replaces the method-rows scroll pane; carry its position over so toggling a
        // method or category (which regenerates routes and re-renders) does not jump the list back
        // to the top.
        int rowsScrollPosition = catalog.scrollPosition();
        removeAll();
        add(section());
        revalidate();
        repaint();
        catalog.restoreScroll(rowsScrollPosition);
        builtCatalog = catalog.catalog();
        builtExclusions = catalog.exclusions();
        builtUnavailable = catalog.unavailable();
        builtCatalogExpanded = catalog.isExpanded();
    }

    private JPanel section() {
        List<TeleportMethod> methods = catalog.catalog();
        JPanel section = sectionShell("Travel options",
            "Everything routing may use: your house, wilderness policy, bank, balloons and the travel methods",
            expanded, () -> expanded = !expanded,
            methods.isEmpty() ? "" : catalog.enabledCount() + "/" + methods.size(),
            ColorScheme.LIGHT_GRAY_COLOR, true, this::rebuild);
        if (!expanded) {
            catalog.slotCollapsed();
            return section;
        }

        JPanel body = new JPanel();
        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setBackground(ColorScheme.DARK_GRAY_COLOR);
        body.setAlignmentX(Component.LEFT_ALIGNMENT);
        body.setBorder(new EmptyBorder(0, 8, 0, 0));
        for (JPanel part : sections.sections())
            body.add(part);
        if (!methods.isEmpty())
            body.add(catalog.section());
        section.add(body);
        return section;
    }
}

package gps;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;

/**
 * General utility helpers for I/O and primitive array manipulation used by the
 * shortest path plugin.
 */
public class Util {
    /**
     * Reads all bytes from the provided {@link InputStream} until EOF.
     * This method does not close the stream; the caller retains responsibility for
     * resource management.
     *
     * @param in the input stream to read from.
     * @return a newly allocated byte array containing all bytes read (may be empty,
     * never {@code null}).
     * @throws IOException if an I/O error occurs while reading.
     */
    public static byte[] readAllBytes(InputStream in) throws IOException {
        ByteArrayOutputStream result = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];

        while (true) {
            int read = in.read(buffer, 0, buffer.length);

            if (read == -1)
                return result.toByteArray();

            result.write(buffer, 0, read);
        }
    }

    /**
     * Concatenates the contents of multiple {@code int[]} arrays into one
     * contiguous array.
     * {@code null} elements in {@code arrays} are skipped. If all arrays are
     * {@code null} or empty, {@code null}
     * is returned (this mirrors the existing behavior relied upon by callers).
     *
     * @param arrays an array of {@code int[]} segments to concatenate (may contain
     *               {@code null}).
     * @return a new combined array, or {@code null} if there are no elements to
     * copy.
     */
    public static int[] concatenate(int[][] arrays) {
        int n = 0;
        for (int[] value : arrays)
            n += (value == null) ? 0 : value.length;
        if (n == 0)
            return null;
        int[] array = new int[n];
        int k = 0;
        for (int[] ints : arrays) {
            if (ints != null) {
                for (int anInt : ints)
                    array[k++] = anInt;
            }
        }
        return array;
    }
}

package gps;

import java.awt.image.BufferedImage;
import java.util.Set;
import java.util.function.Supplier;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;

/**
 * The destination pin on the world map (plan step L33, out of the plugin class). A single target
 * gets a pin on its tile; a multi-target set (an amenity category, "nearest bank") gets none,
 * unless a one-shot override names the tile the set was expanded from (a searched bank booth
 * and its walkable surround still pins the booth). Clicking the pin jumps the map to it.
 */
final class WorldMapMarker {
    private static final BufferedImage IMAGE = ImageUtil.loadImageResource(ShortestPathPlugin.class, "/marker.png");

    // A supplier: the manager is injected into the plugin after field initialisation.
    private final Supplier<WorldMapPointManager> manager;
    private WorldMapPoint marker;
    // The one-shot override for the next placement; UNDEFINED = the default rule.
    private int pinNext = WorldPointUtil.UNDEFINED;

    WorldMapMarker(Supplier<WorldMapPointManager> manager) {
        this.manager = manager;
    }

    /** The next placement pins {@code tile} whatever the target set (consumed by that placement). */
    void pinNextAt(int tile) {
        pinNext = tile;
    }

    /** Replaces the pin for a new target set: the override, else the single target, else none. */
    void place(Set<Integer> targets) {
        clear();
        int tile = pinNext != WorldPointUtil.UNDEFINED ? pinNext
            : (targets.size() == 1 ? targets.iterator().next() : WorldPointUtil.UNDEFINED);
        pinNext = WorldPointUtil.UNDEFINED;
        if (tile == WorldPointUtil.UNDEFINED)
            return;
        marker = new WorldMapPoint(WorldPointUtil.unpackWorldPoint(tile), IMAGE);
        marker.setName("Target");
        marker.setTarget(marker.getWorldPoint());
        marker.setJumpOnClick(true);
        manager.get().add(marker);
    }

    /** Removes the pin, if any. */
    void clear() {
        manager.get().removeIf(x -> x == marker);
        marker = null;
    }

    /** The pinned tile, or UNDEFINED when there is no pin. */
    int pinnedTile() {
        return marker == null ? WorldPointUtil.UNDEFINED : WorldPointUtil.packWorldPoint(marker.getWorldPoint());
    }
}

package gps;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;

/**
 * World map projection (plan step L13, out of the plugin class): world points to the map
 * widget's screen pixels, from the map's zoom, centre and bounds, and a screen pixel back to the
 * world point it shows (the shift-click "Set GPS Target" on the world map). Client thread and
 * render thread both read the live widget; no widget means no projection.
 */
final class WorldMapProjection {
    /** The pixel result when the world map is not open. */
    static final int NONE = Integer.MIN_VALUE;

    private final Client client;

    WorldMapProjection(Client client) {
        this.client = client;
    }

    /** The world point under a screen pixel, or UNDEFINED when the map is not open. */
    int worldPointAt(int pixelX, int pixelY) {
        WorldMap worldMap = client.getWorldMap();
        float zoom = worldMap.getWorldMapZoom();
        int mapPoint = WorldPointUtil.packWorldPoint(worldMap.getWorldMapPosition().getX(), worldMap.getWorldMapPosition().getY(), 0);
        int middleX = toGraphicsX(mapPoint);
        int middleY = toGraphicsY(mapPoint);

        if (pixelX == NONE || pixelY == NONE || middleX == NONE || middleY == NONE)
            return WorldPointUtil.UNDEFINED;

        final int dx = (int) ((pixelX - middleX) / zoom);
        final int dy = (int) ((-(pixelY - middleY)) / zoom);

        return WorldPointUtil.dxdy(mapPoint, dx, dy);
    }

    /** The screen x of a world point on the map, or NONE when the map is not open. */
    int toGraphicsX(int packedWorldPoint) {
        WorldMap worldMap = client.getWorldMap();

        float pixelsPerTile = worldMap.getWorldMapZoom();

        Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
        if (map != null) {
            Rectangle worldMapRect = map.getBounds();

            int widthInTiles = (int) Math.ceil(worldMapRect.getWidth() / pixelsPerTile);

            Point worldMapPosition = worldMap.getWorldMapPosition();

            int xTileOffset = WorldPointUtil.unpackWorldX(packedWorldPoint) + widthInTiles / 2 - worldMapPosition.getX();

            int xGraphDiff = ((int) (xTileOffset * pixelsPerTile));
            xGraphDiff += (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
            xGraphDiff += (int) worldMapRect.getX();

            return xGraphDiff;
        }
        return NONE;
    }

    /** The screen y of a world point on the map, or NONE when the map is not open. */
    int toGraphicsY(int packedWorldPoint) {
        WorldMap worldMap = client.getWorldMap();

        float pixelsPerTile = worldMap.getWorldMapZoom();

        Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
        if (map != null) {
            Rectangle worldMapRect = map.getBounds();

            int heightInTiles = (int) Math.ceil(worldMapRect.getHeight() / pixelsPerTile);

            Point worldMapPosition = worldMap.getWorldMapPosition();

            int yTileMax = worldMapPosition.getY() - heightInTiles / 2;
            int yTileOffset = (yTileMax - WorldPointUtil.unpackWorldY(packedWorldPoint) - 1) * -1;

            int yGraphDiff = (int) (yTileOffset * pixelsPerTile);
            yGraphDiff -= (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
            yGraphDiff = worldMapRect.height - yGraphDiff;
            yGraphDiff += (int) worldMapRect.getY();

            return yGraphDiff;
        }
        return NONE;
    }
}

package gps;

import net.runelite.api.Client;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Perspective.LOCAL_COORD_BITS;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

/**
 * Utility functions for packing, unpacking, and transforming {@link WorldPoint}
 * coordinates as compact {@code int} values.
 * <p>
 * A packed world point encodes {@code x}, {@code y}, and {@code plane} into a
 * single 32-bit integer using:
 *
 * <pre>
 * bits 0..14   : x (15 bits)
 * bits 15..29  : y (15 bits)
 * bits 30..31  : plane (2 bits)
 * </pre>
 * <p>
 * This representation allows efficient storage and hashing of coordinates
 * within the pathfinding data structures.
 */
public class WorldPointUtil {
    public static final int CHEBYSHEV_DISTANCE_METRIC = 1;
    public static final int EUCLIDEAN_SQUARED_DISTANCE_METRIC = 1414213562;
    public static final int MANHATTAN_DISTANCE_METRIC = 2;
    public static final int UNDEFINED = -1;

    /**
     * Packs a {@link WorldPoint} into a compact {@code int} encoding.
     *
     * @param point world point (may be {@code null}).
     * @return packed integer value, or {@link #UNDEFINED} if {@code point} is
     * {@code null}.
     */
    public static int packWorldPoint(WorldPoint point) {
        if (point == null)
            return -1;
        return packWorldPoint(point.getX(), point.getY(), point.getPlane());
    }

    /**
     * Packs the provided coordinate triple into a single {@code int}.
     * First 15 bits are {@code x}, next 15 bits are {@code y}, final 2 bits are the
     * plane.
     * Values are masked into range; overflow bits are discarded.
     *
     * @param x     world x (0..32767 effectively supported).
     * @param y     world y (0..32767 effectively supported).
     * @param plane plane (0..3).
     * @return packed integer representation.
     */
    public static int packWorldPoint(int x, int y, int plane) {
        return (x & 0x7FFF) | ((y & 0x7FFF) << 15) | ((plane & 0x3) << 30);
    }

    /**
     * Unpacks a packed world point into a new {@link WorldPoint} instance.
     *
     * @param packedPoint packed coordinate.
     * @return decoded {@link WorldPoint}.
     */
    public static WorldPoint unpackWorldPoint(int packedPoint) {
        final int x = unpackWorldX(packedPoint);
        final int y = unpackWorldY(packedPoint);
        final int plane = unpackWorldPlane(packedPoint);
        return new WorldPoint(x, y, plane);
    }

    /**
     * Extracts the x component from a packed world point.
     *
     * @param packedPoint packed coordinate.
     * @return x value.
     */
    public static int unpackWorldX(int packedPoint) {
        return packedPoint & 0x7FFF;
    }

    /**
     * Extracts the y component from a packed world point.
     *
     * @param packedPoint packed coordinate.
     * @return y value.
     */
    public static int unpackWorldY(int packedPoint) {
        return (packedPoint >> 15) & 0x7FFF;
    }

    /**
     * Extracts the plane component from a packed world point.
     *
     * @param packedPoint packed coordinate.
     * @return plane value (0..3).
     */
    public static int unpackWorldPlane(int packedPoint) {
        return (packedPoint >> 30) & 0x3;
    }

    /**
     * Offsets a packed world point by {@code (dx, dy)} on the same plane.
     *
     * @param packedPoint base packed point.
     * @param dx          delta x to add.
     * @param dy          delta y to add.
     * @return packed point after applying deltas.
     */
    public static int dxdy(int packedPoint, int dx, int dy) {
        int x = unpackWorldX(packedPoint);
        int y = unpackWorldY(packedPoint);
        int z = unpackWorldPlane(packedPoint);
        return packWorldPoint(x + dx, y + dy, z);
    }

    /**
     * Computes the distance between two packed points using Chebyshev metric
     * (diagonal = 1).
     */
    public static int distanceBetween(int previousPacked, int currentPacked) {
        return distanceBetween(previousPacked, currentPacked, 1);
    }

    /**
     * Computes the 2D distance (ignoring plane) between two packed points using
     * Chebyshev metric (diagonal = 1).
     */
    public static int distanceBetween2D(int previousPacked, int currentPacked) {
        return distanceBetween2D(previousPacked, currentPacked, 1);
    }

    /**
     * Computes distance between two packed points with selectable distance metric.
     *
     * @param previousPacked first packed point.
     * @param currentPacked  second packed point.
     * @param diagonal       {@code 1} for Chebyshev (max), {@code 2} for Manhattan
     *                       (sum). Otherwise returns Euclidean squared distance.
     * @return distance or {@code Integer.MAX_VALUE} if plane differs.
     */
    public static int distanceBetween(int previousPacked, int currentPacked, int diagonal) {
        final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
        final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
        final int previousZ = WorldPointUtil.unpackWorldPlane(previousPacked);
        final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
        final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
        final int currentZ = WorldPointUtil.unpackWorldPlane(currentPacked);
        return distanceBetween(previousX, previousY, previousZ,
            currentX, currentY, currentZ, diagonal);
    }

    /**
     * Computes 2D distance (ignoring plane) between two packed points with
     * selectable metric.
     *
     * @see #distanceBetween(int, int, int, int, int, int, int)
     */
    public static int distanceBetween2D(int previousPacked, int currentPacked, int diagonal) {
        final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
        final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
        final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
        final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
        return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
    }

    /**
     * Computes distance between two coordinates with selectable metric; returns
     * {@code Integer.MAX_VALUE} if planes differ.
     *
     * @param previousX x of first point.
     * @param previousY y of first point.
     * @param previousZ plane of first point.
     * @param currentX  x of second point.
     * @param currentY  y of second point.
     * @param currentZ  plane of second point.
     * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
     *                  otherwise Euclidean squared distance).
     * @return distance or {@code Integer.MAX_VALUE} if planes differ.
     */
    public static int distanceBetween(
        int previousX,
        int previousY,
        int previousZ,
        int currentX,
        int currentY,
        int currentZ,
        int diagonal) {
        final int dz = previousZ - currentZ;

        if (dz != 0)
            return Integer.MAX_VALUE;

        return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
    }

    /**
     * Computes a 2D distance using either Chebyshev, Manhattan or Euclidean squared
     * distance metric.
     *
     * @param previousX x of first point.
     * @param previousY y of first point.
     * @param currentX  x of second point.
     * @param currentY  y of second point.
     * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
     *                  otherwise Euclidean squared distance).
     * @return distance.
     */
    public static int distanceBetween2D(int previousX, int previousY,
        int currentX, int currentY, int diagonal) {
        final int dx = previousX - currentX;
        final int dy = previousY - currentY;

        if (diagonal == CHEBYSHEV_DISTANCE_METRIC)
            return Math.max(Math.abs(dx), Math.abs(dy));
        else if (diagonal == MANHATTAN_DISTANCE_METRIC)
            return Math.abs(dx) + Math.abs(dy);

        return dx * dx + dy * dy;
    }

    /**
     * Convenience overload using Chebyshev distance between two
     * {@link WorldPoint}s.
     */
    public static int distanceBetween(WorldPoint previous, WorldPoint current) {
        return distanceBetween(previous, current, 1);
    }

    /**
     * Distance between two {@link WorldPoint}s with selectable metric.
     *
     * @see #distanceBetween(int, int, int, int, int, int, int)
     */
    public static int distanceBetween(WorldPoint previous, WorldPoint current, int diagonal) {
        return distanceBetween(previous.getX(), previous.getY(), previous.getPlane(),
            current.getX(), current.getY(), current.getPlane(), diagonal);
    }

    /**
     * Distance from a packed point to a {@link WorldArea} using Chebyshev metric,
     * respecting plane.
     * Returns {@code Integer.MAX_VALUE} if the plane differs.
     */
    public static int distanceToArea(int packedPoint, WorldArea area) {
        final int plane = unpackWorldPlane(packedPoint);
        if (area.getPlane() != plane)
            return Integer.MAX_VALUE;
        return distanceToArea2D(packedPoint, area);
    }

    /**
     * 2D distance (Chebyshev) from a packed point to a {@link WorldArea} ignoring
     * plane, equivalent to
     * {@link WorldArea#distanceTo(WorldPoint)} semantics in 2D.
     */
    public static int distanceToArea2D(int packedPoint, WorldArea area) {
        final int y = unpackWorldY(packedPoint);
        final int x = unpackWorldX(packedPoint);
        final int areaMaxX = area.getX() + area.getWidth() - 1;
        final int areaMaxY = area.getY() + area.getHeight() - 1;
        final int dx = Math.max(Math.max(area.getX() - x, 0), x - areaMaxX);
        final int dy = Math.max(Math.max(area.getY() - y, 0), y - areaMaxY);

        return Math.max(dx, dy);
    }

    private static int rotate(int originalX, int originalY, int z, int rotation) {
        int chunkX = originalX & -CHUNK_SIZE;
        int chunkY = originalY & -CHUNK_SIZE;
        int x = originalX & (CHUNK_SIZE - 1);
        int y = originalY & (CHUNK_SIZE - 1);
        switch (rotation) {
            case 1:
                return packWorldPoint(chunkX + y, chunkY + (CHUNK_SIZE - 1 - x), z);
            case 2:
                return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - x), chunkY + (CHUNK_SIZE - 1 - y), z);
            case 3:
                return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - y), chunkY + x, z);
        }
        return packWorldPoint(originalX, originalY, z);
    }

    private static int unpackChunkRotation(int chunkData) {
        return chunkData >> 1 & 0x3;
    }

    private static int unpackChunkTemplateY(int chunkData) {
        return (chunkData >> 3 & 0x7FF) * CHUNK_SIZE;
    }

    private static int unpackChunkTemplateX(int chunkData) {
        return (chunkData >> 14 & 0x3FF) * CHUNK_SIZE;
    }

    private static int unpackChunkTemplatePlane(int chunkData) {
        return chunkData >> 24 & 0x3;
    }

    /**
     * A compact human-readable summary of an instance's template chunk origins, for debug logging:
     * the distinct template chunk world coordinates, deduplicated, capped at 40 entries. "not an
     * instance" when the world view isn't one.
     */
    public static String describeInstanceChunks(WorldView worldView) {
        if (worldView == null || !worldView.isInstance())
            return "not an instance";
        int[][][] chunks = worldView.getInstanceTemplateChunks();
        if (chunks == null)
            return "no chunk data";
        java.util.LinkedHashSet<String> seen = new java.util.LinkedHashSet<>();
        for (int[][] planeChunks : chunks) {
            if (planeChunks == null)
                continue;
            for (int[] column : planeChunks) {
                if (column == null)
                    continue;
                for (int chunkData : column) {
                    if (chunkData == -1)
                        continue;
                    seen.add("(" + unpackChunkTemplateX(chunkData) + "," + unpackChunkTemplateY(chunkData)
                        + ",p" + unpackChunkTemplatePlane(chunkData) + ")");
                    if (seen.size() >= 40)
                        return String.join(" ", seen) + " …";
                }
            }
        }
        return seen.isEmpty() ? "all chunks empty" : String.join(" ", seen);
    }

    public static int fromLocalInstance(Client client, Player localPlayer) {
        WorldView worldView = localPlayer.getWorldView();
        int worldViewId = worldView.getId();
        boolean isOnBoat = worldViewId != WorldView.TOPLEVEL;
        if (isOnBoat) {
            // The boat is a WorldEntity in the top level; byIndex is briefly null during view
            // transitions (boarding, chunk swaps) — a single NPE here used to stall every
            // position consumer for the rest of the session. Resolution goes through
            // RuneLite's own fromLocalInstance, which stays correct on the open sea
            // (port-tasks' path matching depends on the same call mid-sail).
            WorldEntity worldEntity = client.getTopLevelWorldView().worldEntities().byIndex(worldViewId);
            if (worldEntity == null)
                return UNDEFINED;
            net.runelite.api.coords.LocalPoint boatLocal = worldEntity.getLocalLocation();
            if (boatLocal == null)
                return UNDEFINED;
            net.runelite.api.coords.WorldPoint world =
                net.runelite.api.coords.WorldPoint.fromLocalInstance(client, boatLocal);
            return world != null
                ? packWorldPoint(world.getX(), world.getY(), world.getPlane())
                : UNDEFINED;
        }
        return fromLocalInstance(client, localPlayer.getLocalLocation());
    }

    /**
     * Converts an instanced {@link LocalPoint} to its corresponding packed world
     * point coordinate, resolving the
     * underlying template chunk mapping and rotation.
     *
     * @param client     RuneLite client.
     * @param localPoint local scene coordinate.
     * @return packed world point.
     */
    public static int fromLocalInstance(Client client, LocalPoint localPoint) {
        WorldView worldView = client.getWorldView(localPoint.getWorldView());
        int plane = worldView.getPlane();

        if (!worldView.isInstance()) {
            return packWorldPoint(
                (localPoint.getX() >> LOCAL_COORD_BITS) + worldView.getBaseX(),
                (localPoint.getY() >> LOCAL_COORD_BITS) + worldView.getBaseY(),
                plane);
        }

        int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

        // get position in the scene
        int sceneX = localPoint.getSceneX();
        int sceneY = localPoint.getSceneY();

        // get chunk from scene
        int chunkX = sceneX / CHUNK_SIZE;
        int chunkY = sceneY / CHUNK_SIZE;

        // get the template chunk for the chunk
        int templateChunk = instanceTemplateChunks[plane][chunkX][chunkY];

        int rotation = unpackChunkRotation(templateChunk);
        int templateChunkY = unpackChunkTemplateY(templateChunk);
        int templateChunkX = unpackChunkTemplateX(templateChunk);
        int templateChunkPlane = unpackChunkTemplatePlane(templateChunk);

        // calculate world point of the template
        int x = templateChunkX + (sceneX & (CHUNK_SIZE - 1));
        int y = templateChunkY + (sceneY & (CHUNK_SIZE - 1));

        // create and rotate point back to 0, to match with template
        return rotate(x, y, templateChunkPlane, 4 - rotation);
    }

    /**
     * Converts a packed world point to one or more packed world points representing
     * its locations within an instanced
     * map (e.g., dungeons or raids). If the current top-level world is not
     * instanced, the result contains exactly the
     * original point.
     *
     * @param client      RuneLite client.
     * @param packedPoint packed world coordinate.
     * @return list of packed coordinates valid in the current instance.
     */
    public static PrimitiveIntList toLocalInstance(Client client, int packedPoint) {
        WorldView worldView = client.getTopLevelWorldView();

        PrimitiveIntList worldPoints = new PrimitiveIntList();
        if (!worldView.isInstance()) {
            worldPoints.add(packedPoint);
            return worldPoints;
        }

        int baseX = worldView.getBaseX();
        int baseY = worldView.getBaseY();
        int worldPointX = unpackWorldX(packedPoint);
        int worldPointY = unpackWorldY(packedPoint);
        int worldPointPlane = unpackWorldPlane(packedPoint);

        int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

        // find instance chunks using the template point. there might be more than one.
        for (int z = 0; z < instanceTemplateChunks.length; z++) {
            for (int x = 0; x < instanceTemplateChunks[z].length; ++x) {
                for (int y = 0; y < instanceTemplateChunks[z][x].length; ++y) {
                    int chunkData = instanceTemplateChunks[z][x][y];
                    int rotation = unpackChunkRotation(chunkData);
                    int templateChunkY = unpackChunkTemplateY(chunkData);
                    int templateChunkX = unpackChunkTemplateX(chunkData);
                    int plane = unpackChunkTemplatePlane(chunkData);
                    if (worldPointX >= templateChunkX && worldPointX < templateChunkX + CHUNK_SIZE
                        && worldPointY >= templateChunkY && worldPointY < templateChunkY + CHUNK_SIZE
                        && plane == worldPointPlane) {
                        worldPoints.add(rotate(
                            baseX + x * CHUNK_SIZE + (worldPointX & (CHUNK_SIZE - 1)),
                            baseY + y * CHUNK_SIZE + (worldPointY & (CHUNK_SIZE - 1)),
                            z,
                            rotation));
                    }
                }
            }
        }
        return worldPoints;
    }

    private static boolean isInScene(WorldView worldView, int packedPoint) {
        int x = unpackWorldX(packedPoint);
        int y = unpackWorldY(packedPoint);

        int baseX = worldView.getBaseX();
        int baseY = worldView.getBaseY();

        int maxX = baseX + worldView.getSizeX();
        int maxY = baseY + worldView.getSizeY();

        return x >= baseX && x < maxX && y >= baseY && y < maxY;
    }

    /**
     * Converts a packed world point into a {@link LocalPoint} relative to the
     * top-level world view if it resides in
     * the currently loaded scene and on the same plane; returns {@code null}
     * otherwise.
     *
     * @param client      RuneLite client.
     * @param packedPoint packed world point.
     * @return {@link LocalPoint} or {@code null} if out of scene or plane.
     */
    public static LocalPoint toLocalPoint(Client client, int packedPoint) {
        WorldView worldView = client.getTopLevelWorldView();

        if (worldView.getPlane() != unpackWorldPlane(packedPoint))
            return null;

        if (!isInScene(worldView, packedPoint))
            return null;

        return new LocalPoint(
            (unpackWorldX(packedPoint) - worldView.getBaseX() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
            (unpackWorldY(packedPoint) - worldView.getBaseY() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
            worldView.getId());
    }
}

package gps.leagues;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

/**
 * Snapshot of the player's Demonic Pacts League state, refreshed once per
 * {@code PathfinderConfig.refresh()} cycle (i.e. on world change, login, or
 * any config-driven recompute).
 *
 * <p>
 * The Pathfinder asks two questions of this object on the hot path:
 * </p>
 * <ul>
 *   <li>{@link #isSeasonal()} — is the player currently on a Leagues world?
 *       When false, all league-specific filtering is bypassed.</li>
 *   <li>{@link #isUnlocked(LeagueRegion)} — has the player unlocked the
 *       supplied region? Always-unlocked regions
 *       ({@link LeagueRegion#isAlwaysUnlocked()}) return {@code true}
 *       regardless of seasonal status; always-blocked regions
 *       ({@link LeagueRegion#isAlwaysBlocked()}) always return {@code false}
 *       when seasonal.</li>
 * </ul>
 *
 * <p>
 * The unlock set is rebuilt from the {@code LEAGUE_AREA_SELECTION_*} varbit
 * slots ({@link #AREA_SELECTION_VARBITS}). Each slot stores a numeric area
 * id matching the wiki's enumeration (mapping defined in
 * {@link #AREA_VARBIT_TO_REGION}):
 * </p>
 * <ul>
 *   <li>Slot 0 ({@code 10662}) — pre-set to Varlamore on a seasonal world.</li>
 *   <li>Slot 1 ({@code 10663}) — Karamja, awarded for free with the player's
 *       first paid pick at 80 tasks.</li>
 *   <li>Slots 2-3 ({@code 10664}/{@code 10665}) — the player's three area
 *       picks at 200/300/450 tasks.</li>
 *   <li>Slots 4-5 ({@code 10666}/{@code 10667}) — reserved by the game for
 *       additional bonus unlocks; we read them defensively.</li>
 * </ul>
 *
 * <p>
 * The mapping is deliberately hard-coded here — these IDs are known not to
 * change during a league season.
 * </p>
 */
public class LeagueModeState {
    /**
     * Varbit IDs storing the league area unlocks. The values match
     * {@code LEAGUE_AREA_SELECTION_0..5} from RuneLite's gameval VarbitID
     * table. Slot 0 is the auto-set Varlamore slot, slot 1 is the Karamja
     * free pick, and the remaining slots correspond to the three player
     * picks at 200/300/450 tasks plus two bonus slots reserved by the game.
     */
    static final int[] AREA_SELECTION_VARBITS = {
        10662, 10663, 10664, 10665, 10666, 10667,
    };

    /**
     * Maps the numeric area id stored in a {@code LEAGUE_AREA_SELECTION_*}
     * varbit to its {@link LeagueRegion}. Numbering was found through trial
     * and error (id 1 = Misthalin is included for completeness even though
     * it is never selectable).
     */
    private static final Map<Integer, LeagueRegion> AREA_VARBIT_TO_REGION;

    static {
        AREA_VARBIT_TO_REGION = Map.ofEntries(
            Map.entry(1, LeagueRegion.MISTHALIN),
            Map.entry(2, LeagueRegion.KARAMJA),
            Map.entry(3, LeagueRegion.ASGARNIA),
            Map.entry(4, LeagueRegion.KANDARIN),
            Map.entry(5, LeagueRegion.MORYTANIA),
            Map.entry(6, LeagueRegion.DESERT),
            Map.entry(7, LeagueRegion.TIRANNWN),
            Map.entry(8, LeagueRegion.FREMENNIK),
            Map.entry(11, LeagueRegion.WILDERNESS),
            Map.entry(20, LeagueRegion.KOUREND),
            Map.entry(21, LeagueRegion.VARLAMORE));
    }

    @Getter
    private boolean seasonal;

    private Set<LeagueRegion> unlockedRegions = EnumSet.noneOf(LeagueRegion.class);

    /**
     * Re-reads {@link Client#getWorldType()} and the area-unlock varbits.
     * Called from {@code PathfinderConfig.refresh()} which already runs on
     * world change, login, and config edits.
     *
     * <p>
     * Off the game thread (or on a {@code null} client) this resets to a
     * non-seasonal state with no extra unlocks; this is the safe default
     * because non-seasonal logic mirrors normal pathfinding.
     * </p>
     */
    public void refresh(Client client) {
        if (client == null) {
            seasonal = false;
            unlockedRegions = EnumSet.noneOf(LeagueRegion.class);
            return;
        }
        EnumSet<WorldType> worldTypes = client.getWorldType();
        seasonal = worldTypes != null && worldTypes.contains(WorldType.SEASONAL);

        EnumSet<LeagueRegion> next = EnumSet.noneOf(LeagueRegion.class);
        if (seasonal) {
            for (int varbitId : AREA_SELECTION_VARBITS)
                addRegionFromSlot(client, varbitId, next);
        }
        unlockedRegions = next;
    }

    /**
     * Whether the supplied region is currently traversable. Outside of
     * seasonal mode every region is considered unlocked.
     */
    public boolean isUnlocked(LeagueRegion region) {
        if (region == null)
            return true;
        if (region.isAlwaysUnlocked())
            return true;
        if (!seasonal)
            return true;
        if (region.isAlwaysBlocked())
            return false;
        return unlockedRegions.contains(region);
    }

    /**
     * Whether the supplied tile is in the always-blocked region while the
     * player is on a seasonal world. Returns {@code false} on non-seasonal
     * worlds so normal pathfinding is unaffected.
     */
    public boolean isInBlockedRegion(int packedPoint) {
        if (!seasonal)
            return false;
        return LeagueRegionChecker.getRegion(packedPoint).isAlwaysBlocked();
    }

    /**
     * Test hook: forces the seasonal flag and unlock set without touching
     * the client.
     */
    public void setForTest(boolean seasonal, Set<LeagueRegion> unlocked) {
        this.seasonal = seasonal;
        this.unlockedRegions = unlocked == null
            ? EnumSet.noneOf(LeagueRegion.class)
            : EnumSet.copyOf(unlocked);
    }

    private static void addRegionFromSlot(Client client, int varbitId, Set<LeagueRegion> out) {
        int value = client.getVarbitValue(varbitId);
        if (value <= 0)
            return;
        LeagueRegion region = AREA_VARBIT_TO_REGION.get(value);
        if (region != null)
            out.add(region);
    }
}

package gps.leagues;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

import lombok.extern.slf4j.Slf4j;
import gps.ShortestPathPlugin;
import gps.Util;
import gps.WorldPointUtil;

/**
 * Resolves a packed world point to its {@link LeagueRegion} for the Demonic
 * Pacts League.
 *
 * <p>
 * Mirrors the static-utility shape of
 * {@link gps.pathfinder.WildernessChecker}. The mapping is keyed by
 * OSRS map region id (a 64x64-tile chunk identifier matching
 * {@code WorldPoint.getRegionID()}: {@code (x >> 6) << 8 | (y >> 6)}) and
 * loaded from {@code /leagues/regions.tsv} on first access.
 * </p>
 *
 * <p>
 * Tiles whose region id is absent from the mapping fall back to
 * {@link LeagueRegion#NEUTRAL}. This is deliberate: it covers instances and
 * dynamic regions (POH, raids, dungeon entrances) which are universally
 * accessible during the league regardless of unlocked areas.
 * </p>
 */
@Slf4j
public class LeagueRegionChecker {
    private static final String RESOURCE_PATH = "/leagues/regions.tsv";

    private static volatile Map<Integer, LeagueRegion> regionsById;

    private LeagueRegionChecker() {
    }

    /**
     * Returns the league region containing the supplied packed world point.
     * Never returns {@code null}; unmapped tiles resolve to
     * {@link LeagueRegion#NEUTRAL}.
     */
    public static LeagueRegion getRegion(int packedPoint) {
        final int x = WorldPointUtil.unpackWorldX(packedPoint);
        final int y = WorldPointUtil.unpackWorldY(packedPoint);
        final int regionId = ((x >> 6) << 8) | (y >> 6);
        return regions().getOrDefault(regionId, LeagueRegion.NEUTRAL);
    }

    /**
     * Convenience predicate for the always-blocked region.
     */
    public static boolean isInMisthalin(int packedPoint) {
        return getRegion(packedPoint) == LeagueRegion.MISTHALIN;
    }

    /**
     * Returns the underlying region-id-to-region map. Lazily initialised on
     * first call. Visible to tests via {@link #reload(String)}.
     */
    private static Map<Integer, LeagueRegion> regions() {
        Map<Integer, LeagueRegion> snapshot = regionsById;
        if (snapshot == null) {
            synchronized (LeagueRegionChecker.class) {
                snapshot = regionsById;
                if (snapshot == null) {
                    snapshot = loadFromResource();
                    regionsById = snapshot;
                }
            }
        }
        return snapshot;
    }

    /**
     * Replaces the in-memory mapping with a parsed copy of the supplied
     * TSV body. Intended for tests. Pass {@code null} to clear the cache so
     * the next call re-loads from the resource file.
     */
    static synchronized void reload(String tsv) {
        if (tsv == null) {
            regionsById = null;
            return;
        }
        regionsById = parse(tsv);
    }

    private static Map<Integer, LeagueRegion> loadFromResource() {
        try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(RESOURCE_PATH)) {
            if (in == null) {
                log.warn("League regions resource not found at {}; defaulting all tiles to NEUTRAL", RESOURCE_PATH);
                return new HashMap<>();
            }
            String body = new String(Util.readAllBytes(Objects.requireNonNull(in)), StandardCharsets.UTF_8);
            return parse(body);
        }
        catch (IOException e) {
            log.error("Failed to load league regions from {}", RESOURCE_PATH, e);
            return new HashMap<>();
        }
    }

    private static Map<Integer, LeagueRegion> parse(String tsv) {
        Map<Integer, LeagueRegion> result = new HashMap<>();
        if (tsv == null || tsv.isEmpty())
            return result;
        int lineNumber = 0;
        for (String rawLine : tsv.split("\\R")) {
            lineNumber++;
            String line = rawLine.trim();
            if (line.isEmpty() || line.startsWith("#"))
                continue;
            String[] parts = line.split("\\s+", 2);
            if (parts.length != 2) {
                log.warn("Skipping malformed league regions row {}: '{}'", lineNumber, rawLine);
                continue;
            }
            final int regionId;
            try {
                regionId = Integer.parseInt(parts[0]);
            }
            catch (NumberFormatException e) {
                log.warn("Skipping league regions row {} with non-numeric region id '{}'", lineNumber, parts[0]);
                continue;
            }
            final LeagueRegion region;
            try {
                region = LeagueRegion.valueOf(parts[1]);
            }
            catch (IllegalArgumentException e) {
                log.warn("Skipping league regions row {} with unknown region '{}'", lineNumber, parts[1]);
                continue;
            }
            result.put(regionId, region);
        }
        return result;
    }
}

package gps.pathfinder;

public enum AbstractNodeKind {
    // These four abstract teleport states mirror the wilderness buckets that change
    // which teleports are legal.
    GLOBAL_TELEPORTS_OVER_30,
    GLOBAL_TELEPORTS_OVER_20,
    GLOBAL_TELEPORTS_OVER_0,
    GLOBAL_TELEPORTS_NORMAL;

    public static AbstractNodeKind fromWildernessLevel(int wildernessLevel) {
        if (wildernessLevel > 30)
            return GLOBAL_TELEPORTS_OVER_30;
        if (wildernessLevel > 20)
            return GLOBAL_TELEPORTS_OVER_20;
        if (wildernessLevel > 0)
            return GLOBAL_TELEPORTS_OVER_0;
        return GLOBAL_TELEPORTS_NORMAL;
    }

    public int maxWildernessLevel() {
        switch (this) {
            case GLOBAL_TELEPORTS_OVER_30:
                return 31;
            case GLOBAL_TELEPORTS_OVER_20:
                return 30;
            case GLOBAL_TELEPORTS_OVER_0:
                return 20;
            case GLOBAL_TELEPORTS_NORMAL:
            default:
                return 0;
        }
    }
}

package gps.pathfinder;

import gps.PrimitiveIntList;
import gps.WorldPointUtil;
import gps.transport.Transport;

import static gps.WorldPointUtil.unpackWorldPlane;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;

public class CollisionMap {
    // Enum.values() makes copies every time which hurts performance in the hotpath
    private static final OrdinalDirection[] ORDINAL_VALUES = OrdinalDirection.values();

    // Walking through a door costs real time: the collision data bakes doors open, so the walk
    // edge is passable, but the player still stops, clicks, and waits ~a tick for the swing —
    // priced here so the search prefers pure walking around a doorway when it's close. One mask
    // lookup per expanded tile (same profile as the transports lookup above it in the hot path).
    private static final int DOOR_COST_UNITS = CostUnits.fromTicks(gps.ClosedDoors.COST_TICKS);

    private final SplitFlagMap collisionData;
    // This is only safe if pathfinding is single-threaded. Holds the ids of the neighbour nodes
    // appended to the NodeGraph during the most recent getNeighbors call.
    private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
    private final boolean[] traversable = new boolean[8];
    private final gps.PrimitiveIntHashMap<Integer> doorMasks = gps.ClosedDoors.edgeMaskIndex();

    public CollisionMap(SplitFlagMap collisionData) {
        this.collisionData = collisionData;
    }

    private static int packedPointFromOrdinal(int startPacked, OrdinalDirection direction) {
        final int x = unpackWorldX(startPacked);
        final int y = unpackWorldY(startPacked);
        final int plane = unpackWorldPlane(startPacked);
        return WorldPointUtil.packWorldPoint(x + direction.x, y + direction.y, plane);
    }

    /**
     * Walkable plane count for allocating region-indexed side arrays — never below one:
     * pure-ocean regions record ZERO walkable planes, and every consumer that sized an array
     * from the raw count silently refused plane 0 there (the water-pin blind-search outage,
     * fixed three times in three consumers before the clamp moved here).
     */
    public byte getRegionPlaneCounts(int regionIndex) {
        return (byte) Math.max(1, collisionData.getRegionPlaneCounts(regionIndex));
    }

    private boolean get(int x, int y, int z, int flag) {
        return collisionData.get(x, y, z, flag);
    }

    public boolean n(int x, int y, int z) {
        return get(x, y, z, 0);
    }

    public boolean s(int x, int y, int z) {
        return n(x, y - 1, z);
    }

    public boolean e(int x, int y, int z) {
        return get(x, y, z, 1);
    }

    public boolean w(int x, int y, int z) {
        return e(x - 1, y, z);
    }

    /**
     * Whether a single walking step between two ADJACENT tiles is traversable, using the same
     * edge rules as the neighbour expansion (walls block even between two walkable tiles). False
     * for non-adjacent or cross-plane pairs. Used by the route progress tracker so straight-line
     * proximity can't see through walls.
     */
    public boolean canStep(int fromPacked, int toPacked) {
        int x = unpackWorldX(fromPacked);
        int y = unpackWorldY(fromPacked);
        int z = unpackWorldPlane(fromPacked);
        if (z != unpackWorldPlane(toPacked))
            return false;
        int dx = unpackWorldX(toPacked) - x;
        int dy = unpackWorldY(toPacked) - y;
        if (dx == 0 && dy == 1)
            return n(x, y, z);
        if (dx == 0 && dy == -1)
            return s(x, y, z);
        if (dx == 1 && dy == 0)
            return e(x, y, z);
        if (dx == -1 && dy == 0)
            return w(x, y, z);
        if (dx == 1 && dy == 1)
            return ne(x, y, z);
        if (dx == -1 && dy == 1)
            return nw(x, y, z);
        if (dx == 1 && dy == -1)
            return se(x, y, z);
        if (dx == -1 && dy == -1)
            return sw(x, y, z);
        return false;
    }

    private boolean ne(int x, int y, int z) {
        return n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z);
    }

    private boolean nw(int x, int y, int z) {
        return n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z);
    }

    private boolean se(int x, int y, int z) {
        return s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z);
    }

    private boolean sw(int x, int y, int z) {
        return s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z);
    }

    public boolean isBlocked(int x, int y, int z) {
        return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
    }

    public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, boolean targetInWilderness, NodeGraph graph) {
        return getNeighbors(node, visited, config, wildernessLevel, targetInWilderness, graph, null);
    }

    /**
     * {@code tentative} (nullable) is the duplicate-enqueue pruner for settle-dedup searches: a
     * neighbour whose candidate cost does not improve on an already-queued arrival at the same
     * (tile, bank) state is skipped before its node is even created.
     */
    public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, boolean targetInWilderness, NodeGraph graph, TentativeCosts tentative) {
        if (graph.isTile(node))
            return getTileNeighbors(node, visited, config, wildernessLevel, graph, tentative);
        else
            return getAbstractNodeNeighbors(node, visited, config, targetInWilderness, graph);
    }

    // Get neighbours for a walkable tile:
    //      * Neighbouring tiles we can walk to
    //      * An OPTIONAL same-tile transition into the banked state, if the current tile is a bank
    //        (priced at the bank-pickup cost — the un-banked path continues in parallel).
    //      * Transition into abstract global teleport nodes, if we haven't tried that yet.
    private PrimitiveIntList getTileNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, NodeGraph graph, TentativeCosts tentative) {
        final int packedPosition = graph.packedPosition(node);
        final int x = unpackWorldX(packedPosition);
        final int y = unpackWorldY(packedPosition);
        final int z = unpackWorldPlane(packedPosition);

        neighbors.clear();

        // Banking is a CHOICE, not a consequence of standing near a booth: from an un-banked node
        // on a bank-accessible tile, offer a same-tile transition into the banked state priced at
        // the pickup cost — every other edge continues un-banked, free of the surcharge. (The flip
        // used to be FORCED on every path touching a bank tile, which charged routes that never
        // withdraw anything — e.g. every route starting at the GE — cancelling the surcharge out
        // of the route ranking, and made plain walking detour around bank plazas to dodge it.)
        final boolean bankVisited = graph.bankVisited(node);
        if (!bankVisited && config.isBankPathEnabled() && config.bankAccessible(packedPosition)
            && !visited.get(packedPosition, true)
            && (tentative == null || !tentative.shouldPrune(packedPosition, true,
                graph.cost(node) + config.getBankPickupCost()))) {
            neighbors.add(graph.createTile(packedPosition, node, true, config.getBankPickupCost()));
        }

        // Firstly check if there are any transports or teleports which are applicable from the current tile.
        Transport[] transports = config.getTransportsPacked(bankVisited).getOrDefault(packedPosition, TransportAvailability.EMPTY_TRANSPORTS);
        for (Transport transport : transports) {
            // A transport to an already-SETTLED destination is pointless (settled = final under
            // cost-ordered settling); same-destination competitors race in the queue otherwise.
            if (visited.get(transport.getDestination(), bankVisited))
                continue;
            // NB: Do not need to check for wilderness level for transports, since transports have specific origin tile.
            // The whistle differential is REAL cost inside getAdditionalTransportCost, so a chain
            // (whistle -> landing site A -> fly to B) prices itself above the direct whistle-to-B
            // teleport with no special inheritance.
            final int transportTravelTime = CostUnits.fromTicks(transport.getDuration());
            final int transportAdditionalCost = config.getAdditionalTransportCost(transport);
            if (tentative != null && tentative.shouldPrune(transport.getDestination(), bankVisited,
                graph.cost(node) + Math.max(0, transportTravelTime + transportAdditionalCost))) {
                continue;
            }
            neighbors.add(graph.createTransport(
                transport.getDestination(),
                node,
                transportTravelTime,
                transportAdditionalCost,
                bankVisited));
        }

        // Global teleports are only considered from an abstract node, so each
        // wilderness/bank state expands them once. Water nodes may be barred from expanding
        // it entirely (abandonment forbidden: no casting from the helm; land nodes fine).
        AbstractNodeKind abstractKind = AbstractNodeKind.fromWildernessLevel(wildernessLevel);
        if (!visited.getAbstract(abstractKind, bankVisited)
            && !config.teleportsBlockedAt(WorldPointUtil.packWorldPoint(x, y, z))) {
            neighbors.add(graph.createAbstract(abstractKind, node, bankVisited, 0));
        }

        // Then add tiles which we can walk to, which go into the FIFO boundary queue.
        if (isBlocked(x, y, z)) {
            boolean westBlocked = isBlocked(x - 1, y, z);
            boolean eastBlocked = isBlocked(x + 1, y, z);
            boolean southBlocked = isBlocked(x, y - 1, z);
            boolean northBlocked = isBlocked(x, y + 1, z);
            boolean southWestBlocked = isBlocked(x - 1, y - 1, z);
            boolean southEastBlocked = isBlocked(x + 1, y - 1, z);
            boolean northWestBlocked = isBlocked(x - 1, y + 1, z);
            boolean northEastBlocked = isBlocked(x + 1, y + 1, z);
            traversable[0] = !westBlocked;
            traversable[1] = !eastBlocked;
            traversable[2] = !southBlocked;
            traversable[3] = !northBlocked;
            traversable[4] = !southWestBlocked && !westBlocked && !southBlocked;
            traversable[5] = !southEastBlocked && !eastBlocked && !southBlocked;
            traversable[6] = !northWestBlocked && !westBlocked && !northBlocked;
            traversable[7] = !northEastBlocked && !eastBlocked && !northBlocked;
        }
        else {
            traversable[0] = w(x, y, z);
            traversable[1] = e(x, y, z);
            traversable[2] = s(x, y, z);
            traversable[3] = n(x, y, z);
            traversable[4] = sw(x, y, z);
            traversable[5] = se(x, y, z);
            traversable[6] = nw(x, y, z);
            traversable[7] = ne(x, y, z);
        }

        // One walking step costs 1 (Chebyshev-adjacent); stepping through a doorway adds the
        // door's opening + reaction time on top.
        final int walkStepCost = graph.cost(node) + 1;
        final Integer doorMaskBoxed = doorMasks.get(packedPosition);
        final int doorMask = doorMaskBoxed == null ? 0 : doorMaskBoxed;
        for (int i = 0; i < traversable.length; i++) {
            OrdinalDirection d = ORDINAL_VALUES[i];
            int neighborPacked = packedPointFromOrdinal(packedPosition, d);
            if (visited.get(neighborPacked, bankVisited))
                continue;

            if (traversable[i]) {
                final int doorCost = (doorMask & (1 << i)) != 0 ? DOOR_COST_UNITS : 0;
                if (tentative != null && tentative.shouldPrune(neighborPacked, bankVisited, walkStepCost + doorCost))
                    continue;
                neighbors.add(graph.createTile(neighborPacked, node, bankVisited, doorCost));
            }
            else if (Math.abs(d.x + d.y) == 1 && isBlocked(x + d.x, y + d.y, z)) {
                // The transport starts from a blocked adjacent tile, e.g. fairy ring
                // Only checks non-teleport transports (includes portals and levers, but not
                // items and spells)
                Transport[] neighborTransports = config.getTransportsPacked(bankVisited).getOrDefault(neighborPacked,
                    TransportAvailability.EMPTY_TRANSPORTS);
                for (Transport transport : neighborTransports) {
                    // Remapped transports (POH interiors re-homed onto the landing by MAP KEY) keep
                    // their original origin field; stepping onto it would jump the path into the
                    // house template. Only true blocked-tile transports (origin == the map key,
                    // e.g. fairy rings) may be entered this way.
                    if (transport.getOrigin() != neighborPacked
                        || !(transport.isUsableAtWildernessLevel(wildernessLevel))
                        || visited.get(transport.getOrigin(), bankVisited)) {
                        continue;
                    }
                    if (tentative != null && tentative.shouldPrune(transport.getOrigin(), bankVisited,
                        graph.cost(node) + WorldPointUtil.distanceBetween(packedPosition, transport.getOrigin()))) {
                        continue;
                    }
                    neighbors.add(graph.createTile(transport.getOrigin(), node, bankVisited, 0));
                }
            }
        }

        return neighbors;
    }

    // The only abstract nodes are currently for global teleports
    private PrimitiveIntList getAbstractNodeNeighbors(int node, VisitedTiles visited, PathfinderConfig config,
        boolean targetInWilderness, NodeGraph graph) {
        neighbors.clear();
        int sourceTile = graph.getClosestTilePosition(node);
        boolean bankVisited = graph.bankVisited(node);
        int maxWildernessLevel = graph.abstractKind(node).maxWildernessLevel();
        for (Transport transport : config.getUsableTeleports(bankVisited)) {
            if (visited.get(transport.getDestination(), bankVisited))
                continue;
            if (!transport.isUsableAtWildernessLevel(maxWildernessLevel))
                continue;
            if (config.avoidWilderness(sourceTile, transport.getDestination(), targetInWilderness))
                continue;
            neighbors.add(graph.createTransport(
                transport.getDestination(),
                node,
                CostUnits.fromTicks(transport.getDuration()),
                config.getAdditionalTransportCost(transport),
                bankVisited));
        }
        return neighbors;
    }
}

package gps.pathfinder;

/**
 * The pathfinder's cost currency, normalized to real time: one unit is the time a RUNNING player
 * takes to cover one tile — half a game tick (0.3 seconds). A walking edge costs its tile distance
 * (unchanged), and a transport's travel time in game ticks converts at {@link #UNITS_PER_TICK}
 * units per tick, so both kinds of edge are priced in the same wall-clock currency.
 * <p>
 * With no configured weights a path's cost IS its ETA ({@code units × 0.3s}), so routes ordered by
 * cost are ordered by estimated time. The per-method config weights are preference modifiers in
 * this same currency — positive disfavors a method, negative favors it — never a different unit,
 * which is what keeps the ordering consistent with the displayed ETAs.
 */
public final class CostUnits {
    /** Cost units per game tick: one tick of transport travel time = two run-tiles of walking. */
    public static final int UNITS_PER_TICK = 2;
    /** Wall-clock seconds per cost unit (a 0.6s game tick covers 2 run-tiles). */
    public static final double SECONDS_PER_UNIT = 0.3;

    /** Converts a duration in game ticks to cost units. */
    public static int fromTicks(int ticks) {
        return UNITS_PER_TICK * ticks;
    }

    private CostUnits() {
    }
}

package gps.pathfinder;

import static gps.WorldPointUtil.packWorldPoint;
import static gps.WorldPointUtil.unpackWorldPlane;
import static gps.WorldPointUtil.unpackWorldX;
import static gps.WorldPointUtil.unpackWorldY;
import static net.runelite.api.Constants.REGION_SIZE;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;
import gps.PrimitiveIntHashMap;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * A target-rooted distance field: for every tile, a LOWER BOUND of the cost to reach the nearest
 * target — the per-generation preprocessing behind the near-exact A* heuristic. Built by one
 * multi-source reverse Dijkstra from the target set over:
 * <ul>
 * <li>walking edges (symmetric, mirrored from {@link CollisionMap}'s traversability rules with a
 * superset bias — anything uncertain is treated as walkable, which can only shorten distances and
 * therefore keeps the bound admissible), and</li>
 * <li>origin-bound transports reversed EXACTLY via a destination-keyed index (approximating
 * reverse edges with forward ones would overestimate across one-way transports — a jump-down
 * shortcut next to the target — and break admissibility).</li>
 * </ul>
 * Origin-less (global) teleports are deliberately NOT flooded: their reverse edge would reach
 * every tile at once, which is precisely the heuristic's constant floor —
 * {@link SearchHeuristic#buildWithField} computes it per search from the search's own usable
 * teleports, so per-search exclusions raise the floor exactly when searches get expensive.
 * <p>
 * The field is built from the generation's BASE availability (no per-search exclusions). Excluding
 * transports only raises true costs, so the field stays a valid lower bound for every search of
 * the generation. Unflooded tiles (reverse-unreachable from the targets) report
 * {@link #UNREACHED}; the heuristic maps them to its floor, which the consistency argument covers
 * because a forward transport edge into the flooded region implies its reversed edge existed in
 * the flood (so its origin would have been flooded) — EXCEPT teleport/transport landings on
 * blocked tiles, which the walking flood cannot step onto; {@link #patchBlockedLandings} values
 * those from their step-off neighbours after the flood (leaving them at the floor overestimated
 * the remaining cost, burying genuinely cheap routes through such landings).
 */
public final class DistanceField {
    public static final int UNREACHED = Integer.MAX_VALUE;
    private static final short EMPTY = -1;
    // Distances are stored as shorts; anything longer than this is indistinguishable from
    // unreached for heuristic purposes (searches never run that far).
    private static final int MAX_DISTANCE = Short.MAX_VALUE - 1;
    // Extra flood distance past the bare floor * multiple horizon: covers the small gap between the
    // floor (a lower bound built from field values) and the best route's true cost, plus the +-1s of
    // blocked-landing patching. A pure speed knob — correctness never depends on the horizon (an
    // unflooded tile's true remaining provably exceeds the horizon, so reporting the horizon as its
    // heuristic is always admissible); overshooting just floods a little more.
    private static final int HORIZON_SLACK = 64;
    // The eight neighbour offsets (four cardinals, then four diagonals), shared by expandWalking and
    // patchBlockedLandings. Static so the per-tile flood never re-allocates them.
    private static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1};
    private static final int[] DY = {0, 0, -1, 1, -1, -1, 1, 1};

    private final SplitFlagMap.RegionExtent regionExtents;
    private final int widthInclusive;
    private final short[][] regions;
    private final CollisionMap map;
    // Reused scratch for expandWalking's neighbour walkability. The flood is single-threaded per
    // DistanceField instance, so one buffer avoids a boolean[8] allocation on every settled tile —
    // which, across a whole-map flood, was the dominant allocation in build().
    private final boolean[] traversable = new boolean[8];
    // Every tile whose true field distance is <= this value is guaranteed flooded (the flood settles
    // in cost order and only stops past it), so an unflooded tile's remaining cost provably exceeds
    // it — the admissible fallback SearchHeuristic uses for unflooded tiles. MAX_VALUE = full flood
    // (unflooded means genuinely reverse-unreachable, e.g. an island).
    private int floodHorizon = Integer.MAX_VALUE;

    /** The bounded flood's horizon: a strict lower bound on any unflooded tile's distance. */
    public int horizon() {
        return floodHorizon;
    }

    private DistanceField(CollisionMap map) {
        this.map = map;
        regionExtents = SplitFlagMap.getRegionExtents();
        widthInclusive = regionExtents.getWidth() + 1;
        final int heightInclusive = regionExtents.getHeight() + 1;
        regions = new short[widthInclusive * heightInclusive][];
    }

    /** The field value for a packed tile: cost lower bound to the nearest target, or UNREACHED. */
    public int distance(int packedPosition) {
        final int x = unpackWorldX(packedPosition);
        final int y = unpackWorldY(packedPosition);
        final int plane = unpackWorldPlane(packedPosition);
        final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
        if (regionIndex < 0 || regionIndex >= regions.length)
            return UNREACHED;
        final short[] region = regions[regionIndex];
        if (region == null)
            return UNREACHED;
        final int index = tileIndex(x, y, plane, region.length);
        if (index < 0)
            return UNREACHED;
        final short value = region[index];
        return value == EMPTY ? UNREACHED : value;
    }

    /** Relaxes a tile to the given distance; true when it improved (and should be enqueued). */
    private boolean relax(int x, int y, int plane, int distance) {
        final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
        if (regionIndex < 0 || regionIndex >= regions.length)
            return false;
        short[] region = regions[regionIndex];
        if (region == null) {
            final byte planeCount = map.getRegionPlaneCounts(regionIndex);
            region = new short[planeCount * REGION_SIZE * REGION_SIZE];
            java.util.Arrays.fill(region, EMPTY);
            regions[regionIndex] = region;
        }
        final int index = tileIndex(x, y, plane, region.length);
        if (index < 0)
            return false;
        final short clamped = (short) Math.min(distance, MAX_DISTANCE);
        final short current = region[index];
        if (current != EMPTY && current <= clamped)
            return false;
        region[index] = clamped;
        return true;
    }

    private int getRegionIndex(int regionX, int regionY) {
        return (regionX - regionExtents.minX) + (regionY - regionExtents.minY) * widthInclusive;
    }

    private static int tileIndex(int x, int y, int plane, int regionLength) {
        final int index = (plane * REGION_SIZE + (y % REGION_SIZE)) * REGION_SIZE + (x % REGION_SIZE);
        return index < regionLength ? index : -1;
    }

    /**
     * Builds the field for the given targets over the config's current (base) availability, or
     * null for an empty target set. A map-wide "nearest X" set gets a field too (plan step N1).
     * <p>
     * {@code costMultiple > 0} bounds the flood (see {@link #build(PathfinderConfig, Set, int)}):
     * pass the generation's cost multiple so the flood stops once nothing beyond it can matter to
     * any search of the generation. 0 floods the full map.
     */
    public static DistanceField buildIfCompact(PathfinderConfig config, Set<Integer> targets, int costMultiple) {
        if (targets == null || targets.isEmpty())
            return null;
        // No span gate any more (plan step N1): a map-wide "nearest bank" set used to get NO field
        // on the theory that such searches are cheap and h ~ 0 everywhere, so every search of
        // the generation ran blind. They are cheap only when the nearest target is close; when it
        // is far each blind search floods its whole cost ball (~1M nodes, ~400 ms measured). The
        // multi-source flood costs the same as a single-target one, bounds itself the same way,
        // and turns every search of the generation into a guided corridor.
        return build(config, targets, costMultiple);
    }

    /** Builds the full-map field (tests use this directly). */
    public static DistanceField build(PathfinderConfig config, Set<Integer> targets) {
        return build(config, targets, 0);
    }

    /**
     * Builds the field, optionally bounding the flood by the heuristic's own clamp: {@code h(n) =
     * min(field(n), floor)}, so any value above the floor collapses to the floor, and every search is
     * capped at {@code best * costMultiple} (≈ floor * costMultiple) — flooding past that band
     * computes distances no consumer can distinguish from "far" (measured at 95%+ of the flood for
     * teleport-rich configs). The floor is discovered DURING the flood: it is the cheapest
     * {@code cast + field(landing)} over the base origin-free teleports, and since tiles settle in
     * cost order, landings near the targets surface early; once the popped distance exceeds
     * {@code floorSoFar * (costMultiple + 1) + HORIZON_SLACK} the flood stops itself.
     * <p>
     * Correctness does not depend on the horizon: the flood settles in cost order, so an unflooded
     * tile's field distance — and therefore its true remaining cost, which the field lower-bounds —
     * provably exceeds the recorded {@link #horizon()}. {@link SearchHeuristic} reports
     * {@code min(horizon, floor)} for unflooded tiles, which is admissible and consistent
     * unconditionally; an undersized horizon can only weaken the heuristic (slower searches), never
     * change a result.
     */
    static DistanceField build(PathfinderConfig config, Set<Integer> targets, int costMultiple) {
        final CollisionMap map = config.getMap();
        final DistanceField field = new DistanceField(map);
        final PrimitiveIntHashMap<Map<Integer, Integer>> reverseTransports = buildReverseTransportIndex(config);
        final VisitedTiles settled = new VisitedTiles(map);
        final IntDeque fifo = new IntDeque(4096);
        // Transport relaxations only (a few tens of thousands at most): boxed entries are fine.
        // Entry = (distance << 32) | (packed & 0xFFFFFFFF); natural ordering sorts by distance.
        final PriorityQueue<Long> heap = new PriorityQueue<>();
        // Bounded mode: cheapest cast cost per origin-free teleport landing, for in-flood floor
        // discovery. Null = unbounded (full flood).
        final PrimitiveIntHashMap<Integer> landingCasts =
            costMultiple > 0 ? buildTeleportLandingIndex(config) : null;
        int cheapestFloor = Integer.MAX_VALUE;
        long horizonTarget = Long.MAX_VALUE;

        for (int target : targets) {
            final int x = unpackWorldX(target);
            final int y = unpackWorldY(target);
            final int plane = unpackWorldPlane(target);
            if (field.relax(x, y, plane, 0))
                fifo.addLast(target);
        }

        while (!fifo.isEmpty() || !heap.isEmpty()) {
            int packed;
            if (!heap.isEmpty()
                && (fifo.isEmpty() || (heap.peek() >>> 32) < field.distance(fifo.peekFirst()))) {
                packed = (int) (long) heap.poll();
            }
            else
                packed = fifo.pollFirst();
            final int x = unpackWorldX(packed);
            final int y = unpackWorldY(packed);
            final int plane = unpackWorldPlane(packed);
            if (!settled.set(x, y, plane, false))
                continue;
            final int distance = field.distance(packed);

            if (landingCasts != null) {
                // Everything below the popped distance is settled (cost-ordered), so once it passes
                // the horizon nothing else can matter: unflooded tiles provably lie beyond it.
                if (distance > horizonTarget) {
                    field.floodHorizon = (int) Math.min(Integer.MAX_VALUE - 1L, horizonTarget);
                    break;
                }
                final Integer cast = landingCasts.get(packed);
                if (cast != null && cast + distance < cheapestFloor) {
                    cheapestFloor = cast + distance;
                    horizonTarget = (long) cheapestFloor * costMultiple + cheapestFloor + HORIZON_SLACK;
                }
            }

            field.expandWalking(packed, x, y, plane, distance, fifo, settled, config, reverseTransports);

            final Map<Integer, Integer> intoHere = reverseTransports.get(packed);
            if (intoHere != null) {
                for (Map.Entry<Integer, Integer> edge : intoHere.entrySet()) {
                    final int origin = edge.getKey();
                    final int cost = edge.getValue();
                    final int candidate = distance + cost;
                    final int ox = unpackWorldX(origin);
                    final int oy = unpackWorldY(origin);
                    final int oplane = unpackWorldPlane(origin);
                    if (!settled.get(ox, oy, oplane, false) && field.relax(ox, oy, oplane, candidate))
                        heap.add(((long) candidate << 32) | (origin & 0xFFFFFFFFL));
                }
            }
        }
        field.patchBlockedLandings(config, reverseTransports.keys());
        return field;
    }

    /**
     * Values the landings the walking flood cannot reach: a teleport/transport destination on a
     * BLOCKED tile (a quetzal platform, a jetty) is forward-occupiable — the player lands there and
     * steps off — but the reverse flood never steps ONTO a blocked tile, so such landings stayed
     * {@link #UNREACHED} and the heuristic sent them to its floor. That OVERESTIMATES the remaining
     * cost from the landing (breaking admissibility: the search then buries routes through it), and
     * inflates the floor itself, which skips unreached landings. Each such landing takes
     * {@code min(field(step-off neighbour)) + 1}, mirroring the forward blocked-tile step-off rules
     * exactly — a real forward edge, so the value stays a valid lower bound and h stays consistent.
     * Transport landings adjacent to a flooded tile are already valued in the loop (see
     * {@link #expandWalking}), so their reverse edges propagate; this pass covers the rest:
     * origin-free teleport landings, which have no reverse edges, and landings whose step-off
     * neighbours settled only after the horizon cut the flood.
     */
    private void patchBlockedLandings(PathfinderConfig config, int[] transportDestinations) {
        final Set<Integer> landings = new HashSet<>();
        for (int destination : transportDestinations)
            landings.add(destination);
        for (boolean bankVisited : new boolean[]{false, true}) {
            for (Transport teleport : config.getUsableTeleports(bankVisited)) {
                if (teleport.getDestination() != WorldPointUtil.UNDEFINED)
                    landings.add(teleport.getDestination());
            }
        }
        for (int landing : landings) {
            final int x = unpackWorldX(landing);
            final int y = unpackWorldY(landing);
            final int plane = unpackWorldPlane(landing);
            if (distance(landing) != UNREACHED || !map.isBlocked(x, y, plane))
                continue;
            // Forward step-off adjacency from a blocked tile (CollisionMap.getTileNeighbors'
            // isBlocked branch): any unblocked cardinal; diagonals need both flanking cardinals too.
            final boolean westBlocked = map.isBlocked(x - 1, y, plane);
            final boolean eastBlocked = map.isBlocked(x + 1, y, plane);
            final boolean southBlocked = map.isBlocked(x, y - 1, plane);
            final boolean northBlocked = map.isBlocked(x, y + 1, plane);
            final boolean[] stepOpen = {
                !westBlocked, !eastBlocked, !southBlocked, !northBlocked,
                !map.isBlocked(x - 1, y - 1, plane) && !westBlocked && !southBlocked,
                !map.isBlocked(x + 1, y - 1, plane) && !eastBlocked && !southBlocked,
                !map.isBlocked(x - 1, y + 1, plane) && !westBlocked && !northBlocked,
                !map.isBlocked(x + 1, y + 1, plane) && !eastBlocked && !northBlocked,
            };
            int best = UNREACHED;
            for (int i = 0; i < 8; i++) {
                if (!stepOpen[i])
                    continue;
                final int neighbour = distance(packWorldPoint(x + DX[i], y + DY[i], plane));
                if (neighbour != UNREACHED && neighbour + 1 < best)
                    best = neighbour + 1;
            }
            if (best != UNREACHED)
                relax(x, y, plane, best);
        }
    }

    /**
     * Relaxes the walking neighbours of a popped tile, mirroring {@link CollisionMap}'s forward
     * traversability (walking is symmetric in the collision data). The blocked-tile branches mirror
     * the forward rules for transport endpoints standing on blocked tiles (e.g. fairy ring
     * platforms) with a superset bias — extra edges only shorten the field, which is safe.
     */
    private void expandWalking(int packed, int x, int y, int plane, int distance,
        IntDeque fifo, VisitedTiles settled, PathfinderConfig config,
        PrimitiveIntHashMap<Map<Integer, Integer>> reverseTransports) {
        final boolean fromBlocked = map.isBlocked(x, y, plane);
        if (map.isBlocked(x, y, plane)) {
            final boolean westBlocked = map.isBlocked(x - 1, y, plane);
            final boolean eastBlocked = map.isBlocked(x + 1, y, plane);
            final boolean southBlocked = map.isBlocked(x, y - 1, plane);
            final boolean northBlocked = map.isBlocked(x, y + 1, plane);
            traversable[0] = !westBlocked;
            traversable[1] = !eastBlocked;
            traversable[2] = !southBlocked;
            traversable[3] = !northBlocked;
            traversable[4] = !map.isBlocked(x - 1, y - 1, plane) && !westBlocked && !southBlocked;
            traversable[5] = !map.isBlocked(x + 1, y - 1, plane) && !eastBlocked && !southBlocked;
            traversable[6] = !map.isBlocked(x - 1, y + 1, plane) && !westBlocked && !northBlocked;
            traversable[7] = !map.isBlocked(x + 1, y + 1, plane) && !eastBlocked && !northBlocked;
        }
        else {
            // Diagonals composed exactly like CollisionMap's private sw/se/nw/ne: the diagonal is
            // walkable when all four half-edges around it are.
            final boolean w = map.w(x, y, plane);
            final boolean e = map.e(x, y, plane);
            final boolean s = map.s(x, y, plane);
            final boolean n = map.n(x, y, plane);
            traversable[0] = w;
            traversable[1] = e;
            traversable[2] = s;
            traversable[3] = n;
            traversable[4] = s && map.w(x, y - 1, plane) && w && map.s(x - 1, y, plane);
            traversable[5] = s && map.e(x, y - 1, plane) && e && map.s(x + 1, y, plane);
            traversable[6] = n && map.w(x, y + 1, plane) && w && map.n(x - 1, y, plane);
            traversable[7] = n && map.e(x, y + 1, plane) && e && map.n(x + 1, y, plane);
        }
        for (int i = 0; i < 8; i++) {
            final int nx = x + DX[i];
            final int ny = y + DY[i];
            boolean canStep = traversable[i];
            if (!canStep && map.isBlocked(nx, ny, plane)) {
                final int neighborPacked = packWorldPoint(nx, ny, plane);
                final boolean cardinal = Math.abs(DX[i] + DY[i]) == 1;
                if (cardinal && config.getTransportsPacked(true)
                    .getOrDefault(neighborPacked, TransportAvailability.EMPTY_TRANSPORTS).length > 0) {
                    // Mirror of the forward rule that lets a path step onto a blocked tile hosting
                    // a transport origin (fairy ring platform). Superset bias: any transport counts.
                    canStep = true;
                }
                else if (!fromBlocked && reverseTransports.get(neighborPacked) != null
                    && (cardinal || (!map.isBlocked(x, ny, plane) && !map.isBlocked(nx, y, plane)))) {
                    // A transport LANDING on a blocked tile (a jetty, the Moss Giant Island rope
                    // landing): forward-occupiable, valued at step-off cost exactly like the
                    // post-flood patch, but flooded IN the loop so the reverse edges out of it
                    // (into the transport's origin) are followed. The post-flood patch valued the
                    // landing and stopped there, so everything behind the transport stayed
                    // unreached: a reachable island read as provably unreachable, and the
                    // heuristic sent the far side of every blocked landing to its floor
                    // (plan step N7). Step-off mirrors the forward blocked-tile rule: any
                    // unblocked cardinal, a diagonal only with both flanking cardinals open.
                    canStep = true;
                }
            }
            if (!canStep || settled.get(nx, ny, plane, false))
                continue;
            if (relax(nx, ny, plane, distance + 1))
                fifo.addLast(packWorldPoint(nx, ny, plane));
        }
    }

    /**
     * Destination-keyed index of every origin-bound transport in the config's base availability:
     * {@code destination -> (origin -> cheapest cost to make that hop)}. Built over both bank states
     * because a superset only shortens the field.
     * <p>
     * The inner map is keyed by origin and keeps the MINIMUM cost on purpose. The same origin lands
     * on the same destination more than once here — a transport not gated on banking appears in both
     * the no-bank and bank-visited availability, and two distinct methods can share an origin and
     * landing — so a flat list would hold duplicate and redundant edges. The flood only ever relaxes
     * an origin to the cheapest way it can reach the destination ({@code relax} keeps the minimum), so
     * a pricier or duplicate edge could never improve the field. Folding them to one min-cost entry
     * per origin as we build keeps the index minimal (and the flood's relax attempts non-redundant)
     * without changing a single field value.
     */
    /**
     * Cheapest effective cast cost per origin-free teleport landing, over the config's base
     * availability (both bank states) — the same teleport set {@link SearchHeuristic#buildWithField}
     * scans, so the floor the bounded flood discovers matches the one the heuristic will use.
     * Landings on blocked tiles never settle in the walk flood, so their casts simply never
     * contribute — the floor stays a little high and the horizon a little wide, which is safe.
     */
    private static PrimitiveIntHashMap<Integer> buildTeleportLandingIndex(PathfinderConfig config) {
        final PrimitiveIntHashMap<Integer> index = new PrimitiveIntHashMap<>(256);
        for (boolean bankVisited : new boolean[]{false, true}) {
            for (Transport teleport : config.getUsableTeleports(bankVisited)) {
                final int destination = teleport.getDestination();
                if (destination == WorldPointUtil.UNDEFINED)
                    continue;
                final int cost = Math.max(0, CostUnits.fromTicks(teleport.getDuration())
                    + config.getAdditionalTransportCost(teleport));
                final Integer current = index.get(destination);
                if (current == null || cost < current)
                    index.put(destination, cost);
            }
        }
        return index;
    }

    // Package-private for DistanceFieldTest's index-shape assertion. The OUTER map is keyed by a
    // primitive int (the destination): the flood looks it up for every settled tile, and a
    // Map<Integer, ...> would box that int into a throwaway Integer on each of the millions of tiles
    // — the second-biggest allocation in build() after the per-tile scratch arrays. The inner
    // origin -> min-cost map stays boxed: it is only iterated for the few thousand tiles that are
    // actually transport destinations, not per settled tile.
    static PrimitiveIntHashMap<Map<Integer, Integer>> buildReverseTransportIndex(PathfinderConfig config) {
        final PrimitiveIntHashMap<Map<Integer, Integer>> index = new PrimitiveIntHashMap<>(4096);
        for (boolean bankVisited : new boolean[]{false, true}) {
            final PrimitiveIntHashMap<Transport[]> transports = config.getTransportsPacked(bankVisited);
            for (int origin : transports.keys()) {
                final Transport[] set = transports.get(origin);
                if (set == null)
                    continue;
                for (Transport transport : set) {
                    final int destination = transport.getDestination();
                    if (destination == WorldPointUtil.UNDEFINED)
                        continue;
                    final int cost = Math.max(0, CostUnits.fromTicks(transport.getDuration())
                        + config.getAdditionalTransportCost(transport));
                    Map<Integer, Integer> byOrigin = index.get(destination);
                    if (byOrigin == null) {
                        byOrigin = new HashMap<>();
                        index.put(destination, byOrigin);
                    }
                    // Keyed by the availability map's origin (the loop key), NOT transport.getOrigin():
                    // the POH remap re-homes interior transports onto the landing tile by MAP KEY while
                    // each Transport keeps its interior origin. Crediting the interior tile left the
                    // landing unflooded, so the heuristic overestimated inside the POH (inadmissible)
                    // and house-mediated best routes only surfaced after "+" (user capture pair).
                    byOrigin.merge(origin, cost, Math::min);
                }
            }
        }
        return index;
    }
}

package gps.pathfinder;

import java.util.ArrayList;

/**
 * A monotone priority queue of {@code int} node ids keyed by small non-negative integer costs —
 * Dial's algorithm: one FIFO bucket per cost value, popped in cost order by a forward-only cursor.
 * Push and pop are O(1), which is what lets the uninformed (no-heuristic) searches keep their old
 * FIFO-era speed after moving to cost-ordered settling: a binary heap pays log n per operation on
 * exactly the searches that explore the most nodes (map-wide "nearest X" floods).
 * <p>
 * Correct for Dijkstra because pops are monotone: every inserted key is {@code >=} the key being
 * expanded (non-negative edges), so the cursor never needs to move backwards. FIFO order within a
 * bucket preserves the creation-order tie-break the searches always had. Single-threaded (worker
 * only), like the heap it complements.
 */
class IntBucketQueue {
    private final ArrayList<IntDeque> buckets = new ArrayList<>();
    // The lowest bucket that can still hold anything; only ever moves forward (monotone inserts).
    private int cursor;
    private int size;

    int size() {
        return size;
    }

    boolean isEmpty() {
        return size == 0;
    }

    void add(int id, int key) {
        if (key < cursor)
            // Monotonicity safety net: never true with non-negative edges, but a backwards insert
            // must not be silently skipped by the cursor.
            cursor = key;
        while (buckets.size() <= key)
            buckets.add(null);
        IntDeque bucket = buckets.get(key);
        if (bucket == null) {
            bucket = new IntDeque(16);
            buckets.set(key, bucket);
        }
        bucket.addLast(id);
        size++;
    }

    /**
     * @return the minimum-key element, or {@link NodeGraph#NO_NODE} if empty.
     */
    int poll() {
        if (size == 0)
            return NodeGraph.NO_NODE;
        while (cursor < buckets.size()) {
            IntDeque bucket = buckets.get(cursor);
            if (bucket != null && !bucket.isEmpty()) {
                size--;
                return bucket.pollFirst();
            }
            cursor++;
        }
        size = 0;
        return NodeGraph.NO_NODE;
    }

    void clear() {
        buckets.clear();
        cursor = 0;
        size = 0;
    }
}

package gps.pathfinder;

/**
 * A minimal growable FIFO of primitive {@code int} node ids backed by a ring buffer.
 * <p>
 * Replaces the {@code ArrayDeque<Node>} boundary queue in {@link Pathfinder} so the search frontier
 * no longer boxes node references. Only the operations the pathfinder needs are implemented; it is
 * single-threaded (worker only) like the queue it replaces.
 */
class IntDeque {
    private int[] elements;
    private int head;
    private int tail;
    private int size;

    IntDeque(int initialCapacity) {
        elements = new int[Math.max(1, initialCapacity)];
    }

    boolean isEmpty() {
        return size == 0;
    }

    void addLast(int value) {
        if (size == elements.length)
            grow();
        elements[tail] = value;
        tail = increment(tail);
        size++;
    }

    void addFirst(int value) {
        if (size == elements.length)
            grow();
        head = decrement(head);
        elements[head] = value;
        size++;
    }

    /**
     * @return the first element, or {@link NodeGraph#NO_NODE} if empty.
     */
    int peekFirst() {
        return size == 0 ? NodeGraph.NO_NODE : elements[head];
    }

    /**
     * @return the removed first element, or {@link NodeGraph#NO_NODE} if empty.
     */
    int pollFirst() {
        if (size == 0)
            return NodeGraph.NO_NODE;
        final int value = elements[head];
        head = increment(head);
        size--;
        return value;
    }

    void clear() {
        head = 0;
        tail = 0;
        size = 0;
    }

    private int increment(int index) {
        return index + 1 == elements.length ? 0 : index + 1;
    }

    private int decrement(int index) {
        return index == 0 ? elements.length - 1 : index - 1;
    }

    private void grow() {
        final int oldCapacity = elements.length;
        final int[] grown = new int[oldCapacity << 1];
        for (int i = 0; i < size; i++)
            grown[i] = elements[(head + i) % oldCapacity];
        elements = grown;
        head = 0;
        tail = size;
    }
}

package gps.pathfinder;

import java.util.Arrays;

/**
 * A binary min-heap of primitive {@code int} node ids ordered by {@link NodeGraph#orderCost} (the
 * accumulated cost, plus the heuristic in A* mode).
 * <p>
 * Replaces the {@code PriorityQueue<TransportNode>} pending queue in {@link Pathfinder} so transport
 * candidates are stored as int ids rather than boxed node objects. The ordering key is fixed when a
 * node is created, so no decrease-key support is needed; the pathfinder discards stale costlier
 * duplicates with its dequeue-time visited re-check. Single-threaded (worker only), matching the
 * queue it replaces.
 */
class IntMinHeap {
    private final NodeGraph graph;
    private int[] heap;
    private int size;

    IntMinHeap(NodeGraph graph, int initialCapacity) {
        this.graph = graph;
        this.heap = new int[Math.max(1, initialCapacity)];
    }

    boolean isEmpty() {
        return size == 0;
    }

    /**
     * @return the minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
     */
    int peek() {
        return size == 0 ? NodeGraph.NO_NODE : heap[0];
    }

    void add(int id) {
        if (size == heap.length)
            heap = Arrays.copyOf(heap, heap.length << 1);
        heap[size] = id;
        siftUp(size);
        size++;
    }

    /**
     * @return the removed minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
     */
    int poll() {
        if (size == 0)
            return NodeGraph.NO_NODE;
        final int top = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            siftDown(0);
        }
        return top;
    }

    void clear() {
        size = 0;
    }

    /**
     * Ordering: orderCost (f = g + h) first, then HIGHER g, then node id (creation order).
     * <p>
     * The g tie-break is what keeps a near-exact heuristic from flooding its own plateau: every
     * tile on any optimal corridor shares the same f, so f-only ordering explores that whole
     * plateau breadth-first — for a long walk that is the entire diamond of equal-cost grid paths
     * (hundreds of thousands of tiles) — before the target can pop. Preferring the higher g among
     * equal f always advances the deepest node (the one closest to the goal), so the search dives
     * down one corridor and reaches the target having settled little beside it. Any tie-break
     * among equal f is optimality-neutral under a consistent heuristic.
     * <p>
     * The final id (creation order) tie-break keeps the claims of same-f same-g tiles mirroring
     * the FIFO search's (cardinals are generated first), which produces the long straight runs
     * that match the game's own click-walk movement, and makes searches fully deterministic.
     */
    private boolean less(int a, int b) {
        final int costA = graph.orderCost(a);
        final int costB = graph.orderCost(b);
        if (costA != costB)
            return costA < costB;
        final int gA = graph.cost(a);
        final int gB = graph.cost(b);
        if (gA != gB)
            return gA > gB;
        return a < b;
    }

    private void siftUp(int index) {
        final int id = heap[index];
        while (index > 0) {
            final int parent = (index - 1) >> 1;
            if (!less(id, heap[parent]))
                break;
            heap[index] = heap[parent];
            index = parent;
        }
        heap[index] = id;
    }

    private void siftDown(int index) {
        final int id = heap[index];
        final int half = size >> 1;
        while (index < half) {
            int child = (index << 1) + 1;
            final int right = child + 1;
            if (right < size && less(heap[right], heap[child]))
                child = right;
            if (!less(heap[child], id))
                break;
            heap[index] = heap[child];
            index = child;
        }
        heap[index] = id;
    }
}

package gps.pathfinder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import gps.WorldPointUtil;

/**
 * Structure-of-Arrays store for pathfinding nodes.
 * <p>
 * The previous design allocated one {@link Object} per explored tile (a {@code Node} or
 * {@code TransportNode}). Heavy searches explore hundreds of thousands of tiles, so this produced
 * hundreds of thousands of live objects, each carrying a ~16-byte header plus several object
 * references (issue #491). Here every node is instead an {@code int} index into parallel primitive
 * arrays, so a whole search holds only a handful of arrays regardless of how many nodes it visits.
 * <p>
 * The fields packed per node are: packed world position, the index of the previous node
 * ({@link #NO_NODE} for the start), accumulated cost, a set of boolean flags, and the
 * {@link AbstractNodeKind} ordinal for abstract nodes. The priority-queue ordering key is
 * EXACTLY the accumulated cost plus (in A* mode) a consistent heuristic — never anything else:
 * any ordering-only term breaks the first-settle-is-optimal invariant the searches rely on.
 * <p>
 * <strong>Threading.</strong> The search runs on a single worker thread, but the render thread
 * reads the partial path while the search is still running (progressive rendering via
 * {@code Pathfinder.getPath()}). Node data is write-once and is published to the render thread by
 * the single volatile {@code Pathfinder.bestLastNode} handoff rather than by marking these arrays
 * {@code volatile} (which would cripple the hot loop, see the field comment). The chain walks
 * ({@link #getPathSteps} / {@link #getClosestTilePosition}) snapshot the page tables into locals
 * and tolerate an index that is out of bounds or released. This means a walk concurrent with a
 * grow/release can never throw; at worst it yields a one-frame-stale path.
 * <p>
 * <strong>Paging.</strong> Storage is paged (fixed {@link #PAGE_SIZE} nodes per page): growing
 * allocates one more page per array and never copies the nodes already written. The flat
 * design grew by 50% with Arrays.copyOf, which for a two-million-node search copied ~36 MB
 * a dozen times and then released it all - hundreds of megabytes of garbage per generation
 * (plan step N2; SearchAllocationTest measures bytes per settled node).
 */
public class NodeGraph {
    public static final int NO_NODE = -1;

    private static final byte FLAG_BANK_VISITED = 1;       // bit0
    private static final byte FLAG_ABSTRACT = 1 << 1;      // bit1
    private static final byte FLAG_TRANSPORT = 1 << 3;     // bit3

    // Enum.values() copies on every call, so cache it for the abstractKind lookup.
    private static final AbstractNodeKind[] ABSTRACT_KINDS = AbstractNodeKind.values();

    /** Nodes per page: 16K keeps a small search at one ~300 KB page set. */
    static final int PAGE_SHIFT = 14;
    static final int PAGE_SIZE = 1 << PAGE_SHIFT;
    private static final int PAGE_MASK = PAGE_SIZE - 1;

    // The page tables are NOT volatile: making them volatile forces every accessor (packedPosition,
    // cost, isTile, orderCost, the append() writes, ...) to re-read the reference on each call and
    // blocks the JIT from caching the base in a register. The hot loop touches these hundreds of
    // times per node, so volatile reads roughly halved field throughput (~1.6x slower searches).
    // Safe publication to the render thread is provided instead by the single volatile
    // Pathfinder.bestLastNode handoff: the worker writes the node data, then volatile-writes
    // bestLastNode; the render thread volatile-reads bestLastNode before walking, which establishes
    // happens-before for all the plain writes above it. The walk methods snapshot the page tables
    // into locals and tolerate a null (post-release) or stale-but-valid (mid-grow: a grown table is
    // a copy that keeps every existing page) table, so a concurrent grow/release never throws.
    private int[][] packedPosition;
    private int[][] previous;
    private int[][] cost;
    // The priority-queue ordering key, precomputed at append time: the accumulated cost plus -
    // when a heuristic is attached (A* mode) - the node's heuristic value. With no heuristic it
    // equals the cost exactly, so Dijkstra-mode ordering is pure g.
    private int[][] orderCost;
    private byte[][] flags;
    private byte[][] abstractKind;
    private int size;
    private int capacity;
    // Optional A* heuristic; null = uninformed (Dijkstra) ordering.
    private final SearchHeuristic heuristic;

    public NodeGraph(int initialCapacity) {
        this(initialCapacity, null);
    }

    public NodeGraph(int initialCapacity, SearchHeuristic heuristic) {
        final int pages = Math.max(1, (Math.max(1, initialCapacity) + PAGE_MASK) >>> PAGE_SHIFT);
        packedPosition = new int[pages][];
        previous = new int[pages][];
        cost = new int[pages][];
        orderCost = new int[pages][];
        flags = new byte[pages][];
        abstractKind = new byte[pages][];
        for (int page = 0; page < pages; page++)
            allocatePage(page);
        capacity = pages * PAGE_SIZE;
        this.heuristic = heuristic;
    }

    private void allocatePage(int page) {
        packedPosition[page] = new int[PAGE_SIZE];
        previous[page] = new int[PAGE_SIZE];
        cost[page] = new int[PAGE_SIZE];
        orderCost[page] = new int[PAGE_SIZE];
        flags[page] = new byte[PAGE_SIZE];
        abstractKind[page] = new byte[PAGE_SIZE];
    }

    public int size() {
        return size;
    }

    private void ensureCapacity() {
        if (size < capacity)
            return;
        // One more page per array. The page tables are small (one reference per 16K nodes), so
        // growing them by copy is cheap and keeps every existing page for a concurrent reader.
        final int pages = packedPosition.length;
        final int newPages = pages + Math.max(1, pages >> 1);
        packedPosition = Arrays.copyOf(packedPosition, newPages);
        previous = Arrays.copyOf(previous, newPages);
        cost = Arrays.copyOf(cost, newPages);
        orderCost = Arrays.copyOf(orderCost, newPages);
        flags = Arrays.copyOf(flags, newPages);
        abstractKind = Arrays.copyOf(abstractKind, newPages);
        allocatePage(pages);
        capacity = (pages + 1) * PAGE_SIZE;
    }

    private int append(int packed, int prev, int nodeCost, byte flagBits, byte kind) {
        ensureCapacity();
        final int id = size;
        final int page = id >>> PAGE_SHIFT;
        final int slot = id & PAGE_MASK;
        if (packedPosition[page] == null) {
            allocatePage(page);
            capacity = Math.max(capacity, (page + 1) * PAGE_SIZE);
        }
        packedPosition[page][slot] = packed;
        previous[page][slot] = prev;
        cost[page][slot] = nodeCost;
        orderCost[page][slot] = nodeCost + (heuristic == null ? 0 : heuristic.of(packed));
        abstractKind[page][slot] = kind;
        flags[page][slot] = flagBits;
        size = id + 1;
        return id;
    }

    private int costOf(int id) {
        return id == NO_NODE ? 0 : cost[id >>> PAGE_SHIFT][id & PAGE_MASK];
    }

    /**
     * The search root. Carries no previous node and zero cost.
     */
    public int createStart(int packedPosition) {
        return append(packedPosition, NO_NODE, 0, (byte) 0, (byte) 0);
    }

    /**
     * A concrete walkable tile. Travel cost is the walking distance from the previous node, but
     * only when the previous node is itself a tile (mirrors the old {@code Node.cost}); reaching a
     * tile from an abstract node adds no travel cost. {@code extraCost} is a one-off surcharge on this
     * edge (used to charge the bank-pickup penalty on the step that first enters the banked state).
     * The edge is clamped at free: configured weights may be negative (favoring), but a negative-cost
     * edge would break the search's Dijkstra invariant.
     */
    public int createTile(int packedPosition, int previous, boolean bankVisited, int extraCost) {
        final int travelTime = (previous != NO_NODE && isTile(previous))
            ? WorldPointUtil.distanceBetween(packedPosition(previous), packedPosition)
            : 0;
        final byte flagBits = bankVisited ? FLAG_BANK_VISITED : 0;
        return append(packedPosition, previous, costOf(previous) + Math.max(0, travelTime + extraCost),
            flagBits, (byte) 0);
    }

    /**
     * A transport destination tile. Cost is the previous cost plus the transport's travel time (in
     * {@link CostUnits}) and any additional configured cost; there is no walking-distance term
     * (mirrors the old {@code TransportNode}). The edge is clamped at free: a negative configured
     * weight can make a transport free but never cheaper than free (Dijkstra needs non-negative edges).
     */
    public int createTransport(int packedPosition, int previous, int travelTime, int additionalCost,
        boolean bankVisited) {
        byte flagBits = FLAG_TRANSPORT;
        if (bankVisited)
            flagBits |= FLAG_BANK_VISITED;
        return append(packedPosition, previous, costOf(previous) + Math.max(0, travelTime + additionalCost),
            flagBits, (byte) 0);
    }

    /**
     * An abstract search-state node (global teleports). Has no world position and inherits the
     * previous node's cost (mirrors the old {@code Node.abstractNode}). {@code extraCost} is a one-off
     * surcharge (the bank-pickup penalty when this abstract state is first entered via a bank tile), so
     * global teleports expanded from it inherit the penalty. Clamped at free like every other edge.
     */
    public int createAbstract(AbstractNodeKind abstractKind, int previous, boolean bankVisited, int extraCost) {
        byte flagBits = FLAG_ABSTRACT;
        if (bankVisited)
            flagBits |= FLAG_BANK_VISITED;
        return append(WorldPointUtil.UNDEFINED, previous, costOf(previous) + Math.max(0, extraCost), flagBits,
            (byte) abstractKind.ordinal());
    }

    public int packedPosition(int id) {
        return packedPosition[id >>> PAGE_SHIFT][id & PAGE_MASK];
    }

    public int previous(int id) {
        return previous[id >>> PAGE_SHIFT][id & PAGE_MASK];
    }

    public int cost(int id) {
        return cost[id >>> PAGE_SHIFT][id & PAGE_MASK];
    }

    /**
     * The precomputed priority-queue key: the accumulated cost plus the A* heuristic value when
     * one is attached (equal to {@link #cost} otherwise).
     */
    public int orderCost(int id) {
        return orderCost[id >>> PAGE_SHIFT][id & PAGE_MASK];
    }

    public boolean bankVisited(int id) {
        return (flags[id >>> PAGE_SHIFT][id & PAGE_MASK] & FLAG_BANK_VISITED) != 0;
    }

    public boolean isTile(int id) {
        return (flags[id >>> PAGE_SHIFT][id & PAGE_MASK] & FLAG_ABSTRACT) == 0;
    }

    public boolean isAbstract(int id) {
        return (flags[id >>> PAGE_SHIFT][id & PAGE_MASK] & FLAG_ABSTRACT) != 0;
    }

    public boolean isTransport(int id) {
        return (flags[id >>> PAGE_SHIFT][id & PAGE_MASK] & FLAG_TRANSPORT) != 0;
    }


    public AbstractNodeKind abstractKind(int id) {
        return ABSTRACT_KINDS[abstractKind[id >>> PAGE_SHIFT][id & PAGE_MASK]];
    }

    /** A node id the snapshotted page tables can serve (every page up to the table's length exists). */
    private static boolean readable(int id, int[][] prev, int[][] packed, byte[][] flg) {
        if (id == NO_NODE)
            return false;
        final int page = id >>> PAGE_SHIFT;
        return page < prev.length && page < packed.length && page < flg.length
            && prev[page] != null && packed[page] != null && flg[page] != null;
    }

    /**
     * Walks the previous chain from {@code id} to the start, collecting the tile nodes (abstract
     * nodes are skipped) into an ordered list of path steps.
     * <p>
     * Safe to call from the render thread during the search: the page tables are snapshotted into
     * locals and the walk is bounds-tolerant, so a concurrent grow or {@link #release()} yields an
     * empty or one-frame-stale result rather than throwing.
     */
    public List<PathStep> getPathSteps(int id) {
        final int[][] prev = previous;
        final int[][] packed = packedPosition;
        final byte[][] flg = flags;
        final int[][] cst = cost;
        if (prev == null || packed == null || flg == null || cst == null || id == NO_NODE)
            return new ArrayList<>();

        int node = id;
        int n = 0;
        while (readable(node, prev, packed, flg)) {
            if ((flg[node >>> PAGE_SHIFT][node & PAGE_MASK] & FLAG_ABSTRACT) == 0)
                n++;
            node = prev[node >>> PAGE_SHIFT][node & PAGE_MASK];
        }

        final List<PathStep> pathSteps = new ArrayList<>(n);
        for (int i = 0; i < n; i++)
            pathSteps.add(null);

        node = id;
        int i = n;
        while (readable(node, prev, packed, flg) && i > 0) {
            final int page = node >>> PAGE_SHIFT;
            final int slot = node & PAGE_MASK;
            if ((flg[page][slot] & FLAG_ABSTRACT) == 0) {
                pathSteps.set(--i, new PathStep(packed[page][slot], (flg[page][slot] & FLAG_BANK_VISITED) != 0,
                    cst[page][slot]));
            }
            node = prev[page][slot];
        }

        return pathSteps;
    }

    /**
     * Walks the previous chain from {@code id} until the first tile node and returns its packed
     * position, or {@link WorldPointUtil#UNDEFINED} if none. Same threading guarantees as
     * {@link #getPathSteps}.
     */
    public int getClosestTilePosition(int id) {
        final int[][] prev = previous;
        final int[][] packed = packedPosition;
        final byte[][] flg = flags;
        if (prev == null || packed == null || flg == null)
            return WorldPointUtil.UNDEFINED;
        int node = id;
        while (readable(node, prev, packed, flg) && (flg[node >>> PAGE_SHIFT][node & PAGE_MASK] & FLAG_ABSTRACT) != 0)
            node = prev[node >>> PAGE_SHIFT][node & PAGE_MASK];
        return readable(node, prev, packed, flg) ? packed[node >>> PAGE_SHIFT][node & PAGE_MASK] : WorldPointUtil.UNDEFINED;
    }

    /**
     * Releases the backing pages once the search is finished and the final path has been
     * materialised, so the large per-search working set becomes eligible for garbage collection
     * (the old design dropped the explored {@code Node} objects the same way by clearing the
     * frontier collections). A render-thread walk in flight keeps its own local references and
     * finishes safely.
     */
    public void release() {
        packedPosition = null;
        previous = null;
        cost = null;
        orderCost = null;
        flags = null;
        abstractKind = null;
        size = 0;
        capacity = 0;
    }
}

