/** Probe (-Dgps.apeProbe=true): what the Grand Tree -> Ape Atoll routes carry as methods vs plain steps. */
public class ApeAtollProbeTest
{
	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	@Test
	public void grandTreeToApeAtoll() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.apeProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.currencyThreshold()).thenReturn(10000000);
		Mockito.when(cfg.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY);
		Mockito.when(cfg.useSpiritTrees()).thenReturn(true);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, config);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2465, 3496, 0),
			Set.of(WorldPointUtil.packWorldPoint(2803, 2706, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		latch.await(120, TimeUnit.SECONDS);
		StringBuilder sb = new StringBuilder("\nPROBE ape atoll\n");
		for (RouteOption route : out.get())
		{
			sb.append(String.format("cost %d walkOnly=%s methods=%s%n", route.getTotalCost(), route.isWalkOnly(), route.getMethods()));
			List<PathStep> path = route.getPath();
			for (int i = 1; i < path.size(); i++)
			{
				int a = path.get(i - 1).getPackedPosition(), b = path.get(i).getPackedPosition();
				if (WorldPointUtil.distanceBetween(a, b) > 1 || WorldPointUtil.unpackWorldPlane(a) != WorldPointUtil.unpackWorldPlane(b))
				{
					List<Transport> rows = config.transportsOnEdge(a, b);
					sb.append(String.format("   jump@%d %d,%d,%d -> %d,%d,%d : %s%n", i,
						WorldPointUtil.unpackWorldX(a), WorldPointUtil.unpackWorldY(a), WorldPointUtil.unpackWorldPlane(a),
						WorldPointUtil.unpackWorldX(b), WorldPointUtil.unpackWorldY(b), WorldPointUtil.unpackWorldPlane(b),
						rows.stream().map(t -> t.getType() + "/" + t.getObjectInfo() + "/" + t.getDisplayInfo()).collect(java.util.stream.Collectors.toList())));
				}
			}
		}
		System.out.println(sb);
		service.shutdown();
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathStep;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Plan step L19: the arrival zone, out of the plugin class. The flood follows the collision
 * map's movement rules (a blocked cardinal also closes both diagonals beside it), no map or no
 * steps means the end tile alone, and the zone is cached per path end and radius. Plan step
 * L30 adds the arrival rule itself: in the zone, or moored near a sailable target; a round trip
 * only past its turnaround, and never while its round-trip route is regenerating; an unreachable
 * one-way target never completes.
 */
public class ArrivalZoneTest
{
	private static int at(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	private static CollisionMap openMap()
	{
		CollisionMap map = mock(CollisionMap.class);
		when(map.n(anyInt(), anyInt(), anyInt())).thenReturn(true);
		when(map.s(anyInt(), anyInt(), anyInt())).thenReturn(true);
		when(map.e(anyInt(), anyInt(), anyInt())).thenReturn(true);
		when(map.w(anyInt(), anyInt(), anyInt())).thenReturn(true);
		return map;
	}

	@Test
	public void theFloodFollowsTheMovementRules()
	{
		assertEquals("open ground: the 3x3 block", 9, ArrivalZone.flood(openMap(), at(10, 10), 1).size());

		CollisionMap wallEast = openMap();
		when(wallEast.e(10, 10, 0)).thenReturn(false);
		Set<Integer> zone = ArrivalZone.flood(wallEast, at(10, 10), 1);
		assertEquals("east and both diagonals beside it are closed", 6, zone.size());
		assertFalse(zone.contains(at(11, 10)));
		assertFalse(zone.contains(at(11, 11)));
		assertFalse(zone.contains(at(11, 9)));
		assertTrue(zone.contains(at(9, 11)));
	}

	@Test
	public void noMapOrNoStepsIsTheEndTileAlone()
	{
		assertEquals(Set.of(at(10, 10)), ArrivalZone.flood(null, at(10, 10), 3));
		assertEquals(Set.of(at(10, 10)), ArrivalZone.flood(openMap(), at(10, 10), 0));
	}

	@Test
	public void theZoneIsCachedPerEndAndRadius()
	{
		ArrivalZone arrival = new ArrivalZone(ArrivalZoneTest::openMap);
		List<PathStep> path = List.of(new PathStep(at(1, 1), false), new PathStep(at(10, 10), false));
		Set<Integer> first = arrival.tiles(path, 1);
		assertSame(first, arrival.tiles(List.of(new PathStep(at(10, 10), false)), 1));
		assertEquals(25, arrival.tiles(path, 2).size());
		assertTrue(arrival.tiles(path, -1).isEmpty());
		assertTrue(arrival.tiles(List.of(), 1).isEmpty());
		assertTrue(arrival.tiles(null, 1).isEmpty());
	}

	private static RouteOption route(int turnaround)
	{
		List<PathStep> path = List.of(new PathStep(at(1, 1), false), new PathStep(at(10, 10), false));
		return new RouteOption(path, List.of(), List.of(), List.of(), 10, 10, true, Set.of(), List.of(), 0, turnaround);
	}

	@Test
	public void arrivalIsTheZoneOrAMooringNearASailableTarget()
	{
		Set<Integer> zone = Set.of(at(10, 10), at(11, 10));
		assertTrue(ArrivalZone.arrived(at(11, 10), zone, Set.of(at(10, 10)), t -> false, 12, null, false, 0, false));
		assertFalse(ArrivalZone.arrived(at(12, 10), zone, Set.of(at(10, 10)), t -> false, 12, null, false, 0, false));

		// A water pin has an empty zone: a boat parked within the sea distance of it has arrived.
		Set<Integer> seaTarget = Set.of(at(20, 20));
		assertTrue(ArrivalZone.arrived(at(20, 10), Set.of(), seaTarget, t -> true, 12, null, false, 0, false));
		assertFalse("13 tiles off with a 12-tile sea distance",
			ArrivalZone.arrived(at(20, 7), Set.of(), seaTarget, t -> true, 12, null, false, 0, false));
		assertFalse("a land target gets no sea tolerance",
			ArrivalZone.arrived(at(20, 10), Set.of(), seaTarget, t -> false, 12, null, false, 0, false));
	}

	@Test
	public void aRoundTripCompletesOnlyPastItsTurnaround()
	{
		Set<Integer> zone = Set.of(at(10, 10));
		RouteOption roundTrip = route(10);
		assertFalse("standing at home before the turnaround: the outbound leg",
			ArrivalZone.arrived(at(10, 10), zone, Set.of(at(10, 10)), t -> false, 12, roundTrip, true, 5, false));
		assertTrue("two steps short of the turnaround counts as reached",
			ArrivalZone.arrived(at(10, 10), zone, Set.of(at(10, 10)), t -> false, 12, roundTrip, true, 8, false));
		assertFalse("a round trip wanted but only the one-way fallback displayed: suspended",
			ArrivalZone.arrived(at(10, 10), zone, Set.of(at(10, 10)), t -> false, 12, route(-1), true, 50, false));
		assertFalse("a round trip wanted and nothing displayed yet: suspended",
			ArrivalZone.arrived(at(10, 10), zone, Set.of(at(10, 10)), t -> false, 12, null, true, 50, false));
	}

	@Test
	public void anUnreachableOneWayTargetNeverCompletes()
	{
		Set<Integer> zone = Set.of(at(10, 10));
		assertFalse(ArrivalZone.arrived(at(10, 10), zone, Set.of(at(10, 10)), t -> false, 12, route(-1), false, 0, true));
		assertTrue("the flag is a one-way judgement; a round trip past its turnaround completes",
			ArrivalZone.arrived(at(10, 10), zone, Set.of(at(10, 10)), t -> false, 12, route(10), true, 9, true));
	}
}

package gps;

import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Covers the auto-compute decision ({@link RouteSession#shouldAutoCompute}): alternatives are
 * (re)generated when the target changes or when the last generation was allowed fewer routes than
 * wanted now (its budget grew meanwhile). The route budget itself never depends on whether the
 * side panel is shown ({@link RouteController#routeLimitFor}).
 */
public class AutoComputeDecisionTest
{
	private static final Set<Integer> TARGETS = Set.of(WorldPointUtil.packWorldPoint(3200, 3200, 0));
	private static final Set<Integer> OTHER_TARGETS = Set.of(WorldPointUtil.packWorldPoint(3300, 3300, 0));
	private static final int FULL = 5;
	private static final int PRIMARY_ONLY = 1;

	@Test
	public void routeBudgetDoesNotDependOnThePanel()
	{
		// The overlay's route must be the same with the panel open or hidden: both states run the
		// configured budget, never a primary-only search (the "different route once the panel
		// opens" experience).
		assertEquals(RouteController.routeLimitFor(true, 10), RouteController.routeLimitFor(false, 10));
		assertEquals(10, RouteController.routeLimitFor(false, 10));
		assertEquals(1, RouteController.routeLimitFor(false, 0));
		assertEquals(25, RouteController.routeLimitFor(true, 99));
	}

	@Test
	public void noTargetsNeverComputes()
	{
		assertFalse("No destination -> nothing to compute",
			RouteSession.shouldAutoCompute(Set.of(), Set.of(), 0, FULL));
	}

	@Test
	public void newTargetComputes()
	{
		assertTrue("A destination the last generation didn't cover must compute",
			RouteSession.shouldAutoCompute(TARGETS, OTHER_TARGETS, FULL, FULL));
		assertTrue("The first destination of the session must compute",
			RouteSession.shouldAutoCompute(TARGETS, Set.of(), 0, PRIMARY_ONLY));
	}

	@Test
	public void sameTargetAlreadyGeneratedSkips()
	{
		assertFalse("Same destination, already generated at the wanted limit -> skip",
			RouteSession.shouldAutoCompute(TARGETS, TARGETS, FULL, FULL));
		assertFalse("Panel hidden after a primary-only run for the same destination -> skip",
			RouteSession.shouldAutoCompute(TARGETS, TARGETS, PRIMARY_ONLY, PRIMARY_ONLY));
	}

	@Test
	public void openingThePanelCatchesUpAPrimaryOnlyGeneration()
	{
		assertTrue("Panel opened after a hidden primary-only run -> full generation",
			RouteSession.shouldAutoCompute(TARGETS, TARGETS, PRIMARY_ONLY, FULL));
	}

	@Test
	public void closingThePanelDoesNotDiscardAFullGeneration()
	{
		assertFalse("Panel hidden after a full generation -> keep it, no primary-only redo",
			RouteSession.shouldAutoCompute(TARGETS, TARGETS, FULL, PRIMARY_ONLY));
	}

	@Test
	public void showMoreRoutesIsNotUndoneByTheAutoCompute()
	{
		assertFalse("A generation grown past the default (Show more) must not be regenerated smaller",
			RouteSession.shouldAutoCompute(TARGETS, TARGETS, FULL + 10, FULL));
	}
}

package gps;

import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.mockito.Mockito.when;

/**
 * The balloon storage crates have no varbits — the chat messages are the only source of truth for
 * the stored counts (same approach and message set as the dedicated tictac7x-balloon plugin). Each
 * game message form must resolve to the right config key and count.
 */
public class BalloonLogStorageTest
{
	@Test
	public void checkMessageSyncsEveryLogType()
	{
		Map<String, Integer> updates = BalloonLogStorage.parse(
			"This crate currently contains 12 logs, 3 oak logs, 0 willow logs, 5 yew logs and 2 magic logs.");
		assertEquals(Integer.valueOf(12), updates.get("balloonStoredLogs"));
		assertEquals(Integer.valueOf(3), updates.get("balloonStoredOakLogs"));
		assertEquals(Integer.valueOf(0), updates.get("balloonStoredWillowLogs"));
		assertEquals(Integer.valueOf(5), updates.get("balloonStoredYewLogs"));
		assertEquals(Integer.valueOf(2), updates.get("balloonStoredMagicLogs"));
		assertEquals(5, updates.size());
	}

	@Test
	public void storingLogsReportsTheNewTotal()
	{
		assertEquals(Map.of("balloonStoredWillowLogs", 7),
			BalloonLogStorage.parse("You put the Willow logs in the crate. You now have 7 stored."));
		assertEquals(Map.of("balloonStoredLogs", 4),
			BalloonLogStorage.parse("You put the Logs in the crate. You now have 4 stored."));
	}

	@Test
	public void flyingReportsTheRemainingCount()
	{
		assertEquals(Map.of("balloonStoredMagicLogs", 3),
			BalloonLogStorage.parse("You have 3 sets of Magic logs left in storage."));
		assertEquals(Map.of("balloonStoredOakLogs", 1),
			BalloonLogStorage.parse("You have one set of Oak logs left in storage."));
		assertEquals(Map.of("balloonStoredYewLogs", 0),
			BalloonLogStorage.parse("You used the last of your Yew logs."));
	}

	@Test
	public void aRefusedTripMeansTheStorageIsEmptyForThatType()
	{
		assertEquals(Map.of("balloonStoredWillowLogs", 0),
			BalloonLogStorage.parse("You need 1 willow logs to make this trip."));
	}

	@Test
	public void unrelatedAndUnknownTypeMessagesAreIgnored()
	{
		assertTrue(BalloonLogStorage.parse("You board the balloon and fly to Varrock.").isEmpty());
		assertTrue(BalloonLogStorage.parse(
			"You put the Redwood logs in the crate. You now have 2 stored.").isEmpty());
	}

	@Test
	public void lowTypesWarnsOnlyForUnlockedRoutesBelowTheThreshold()
	{
		int[] stored = {0, 5, 0, 2, 0};
		boolean[] unlocked = {true, true, true, true, false};
		// normal (0) and willow (0) are unlocked and below 1; oak (5) and yew (2) are covered;
		// magic (0) is low but the route is locked, so it is noise rather than a warning.
		assertEquals(java.util.List.of("normal", "willow"),
			BalloonLogStorage.lowTypes(stored, unlocked, 1));
		// Threshold 3 pulls yew (2) in; threshold 0 disables warnings entirely.
		assertEquals(java.util.List.of("normal", "willow", "yew"),
			BalloonLogStorage.lowTypes(stored, unlocked, 3));
		assertTrue(BalloonLogStorage.lowTypes(stored, unlocked, 0).isEmpty());
	}

	/** Plan step L34: the chat tracking itself, out of the plugin class. */
	@Test
	public void chatLinesUpdateTheCountsOnlyOnTheGameChannelsWithSmartModeOn()
	{
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		ConfigManager configManager = mock(ConfigManager.class);
		when(config.balloonSmartMode()).thenReturn(true);
		String stored = "You put the Willow logs in the crate. You now have 7 stored.";

		BalloonLogStorage.track(ChatMessageType.PUBLICCHAT, stored, config, configManager, "gps");
		verifyNoInteractions(configManager);

		BalloonLogStorage.track(ChatMessageType.SPAM, stored, config, configManager, "gps");
		verify(configManager).setConfiguration("gps", "balloonStoredWillowLogs", 7);
		verify(configManager).setConfiguration("gps", "balloonStorageSynced", true);

		when(config.balloonStorageSynced()).thenReturn(true);
		BalloonLogStorage.track(ChatMessageType.MESBOX, "You used the last of your Yew logs.", config, configManager, "gps");
		verify(configManager).setConfiguration("gps", "balloonStoredYewLogs", 0);
		verify(configManager, times(1)).setConfiguration("gps", "balloonStorageSynced", true);

		when(config.balloonSmartMode()).thenReturn(false);
		BalloonLogStorage.track(ChatMessageType.SPAM, stored, config, configManager, "gps");
		verifyNoMoreInteractions(configManager);
	}
}

package gps;

import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.TransportType;

/**
 * A generated balloon route must carry its flight as a route METHOD (so the route card lists it and
 * it can be excluded), and the method must name the vehicle — the data label is just the
 * destination ("Crafting Guild"), which read as a place, not a travel method, on the card and in
 * the "Use Crafting Guild" direction step.
 */
@RunWith(MockitoJUnitRunner.class)
public class BalloonRouteLabelTest
{
	private static final int TAVERLEY_BASKET = WorldPointUtil.packWorldPoint(2938, 3424, 0);
	private static final int CRAFTING_GUILD_LANDING = WorldPointUtil.packWorldPoint(2924, 3301, 0);

	private AlternativeRoutesService service;

	@Before
	public void before()
	{
		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.useHotAirBalloons()).thenReturn(true);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(ct, config);
	}

	@After
	public void after()
	{
		service.shutdown();
	}

	@Test
	public void balloonFlightIsARecordedMethodNamingTheVehicle() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(TAVERLEY_BASKET, Set.of(CRAFTING_GUILD_LANDING), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);

		TeleportMethod flight = null;
		for (RouteOption route : routes)
		{
			for (TeleportMethod method : route.getMethods())
			{
				if (TransportType.HOT_AIR_BALLOON.equals(method.getType()))
				{
					flight = method;
					break;
				}
			}
		}
		assertNotNull("standing at the Taverley basket, a route must use the balloon flight", flight);
		org.junit.Assert.assertEquals("the route label must name the vehicle, not just the place",
			"Balloon to Crafting Guild", flight.routeLabel());
		org.junit.Assert.assertEquals("the catalog label stays the bare destination (it sits under"
			+ " its category header)", "Crafting Guild", flight.label());
	}
}

package gps;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The search index's bank pins (destinations.tsv, category bank) and the engine's bank tiles
 * (destinations/game_features/bank.tsv) describe the same banks, so a surface bank pin must stand
 * near an engine tile. The cache dump behind the index once accepted any object named "Bank
 * table", which put a "West Ardougne Bank" in the Mourner HQ (a decorative table, object 591,
 * field report 2026-10-03): "nearest bank" then walked players to a table in a city with no bank.
 */
public class BankDestinationSanityTest
{
	/** Banks the engine deliberately leaves out but the index keeps: the Group Ironman bank. */
	private static final Set<String> ENGINE_EXCLUDES = Set.of("Lumbridge Swamp Bank");
	private static final int NEAR = 12;

	@Test
	public void everySurfaceBankPinStandsAtAnEngineBank() throws IOException
	{
		List<int[]> engine = new ArrayList<>();
		for (String line : lines("/destinations/game_features/bank.tsv"))
		{
			String[] c = line.split("\t")[0].trim().split(" ");
			engine.add(new int[]{Integer.parseInt(c[0]), Integer.parseInt(c[1]), Integer.parseInt(c[2])});
		}
		assertTrue("the engine's bank list is gone", engine.size() > 200);

		List<String> strays = new ArrayList<>();
		for (String line : lines("/destinations.tsv"))
		{
			String[] f = line.split("\t");
			if (!"bank".equals(f[0]) || f[1].startsWith("category"))
			{
				continue;
			}
			int x = Integer.parseInt(f[2]);
			int y = Integer.parseInt(f[3]);
			int plane = Integer.parseInt(f[4]);
			// Only the surface: upper floors and the instance and underground bands have their own
			// rules (template scenery is remapped, dungeon banks sit far from any surface tile).
			if (plane != 0 || y >= 4000 || ENGINE_EXCLUDES.contains(f[1]))
			{
				continue;
			}
			int nearest = Integer.MAX_VALUE;
			for (int[] e : engine)
			{
				if (e[2] == 0)
				{
					nearest = Math.min(nearest, Math.max(Math.abs(e[0] - x), Math.abs(e[1] - y)));
				}
			}
			if (nearest > NEAR)
			{
				strays.add(f[1] + " at " + x + "," + y + " (" + nearest + " tiles from the nearest engine bank)");
			}
		}
		assertTrue("bank pins with no engine bank nearby, a decorative Bank table in the cache dump: " + strays,
			strays.isEmpty());
	}

	private static List<String> lines(String resource) throws IOException
	{
		List<String> rows = new ArrayList<>();
		try (InputStream in = BankDestinationSanityTest.class.getResourceAsStream(resource))
		{
			assertNotNull(resource + " is missing", in);
			Scanner scanner = new Scanner(in, "UTF-8");
			while (scanner.hasNextLine())
			{
				String line = scanner.nextLine();
				if (!line.isEmpty() && !line.startsWith("#") && Character.isLetterOrDigit(line.charAt(0)))
				{
					rows.add(line);
				}
			}
		}
		return rows;
	}
}

package gps;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The destination a nearest-bank trip replaced (a player suggestion): resumed once the bank trip
 * completes, only when the bank click replaced an active destination, and forgotten by any other
 * change of destination, so a resume never surprises.
 */
public class BankDetourTest
{
	private static final Set<Integer> VARROCK = Set.of(WorldPointUtil.packWorldPoint(3213, 3424, 0));
	private static final Set<Integer> BANKS = Set.of(
		WorldPointUtil.packWorldPoint(3185, 3436, 0), WorldPointUtil.packWorldPoint(3253, 3420, 0));

	@Test
	public void aBankTripResumesTheDestinationItReplaced()
	{
		BankDetour detour = new BankDetour();
		detour.begin(detour.replacing(BankDetour.Route.of(VARROCK, "map pin", false, WorldPointUtil.UNDEFINED)));
		assertTrue(detour.isActive());

		BankDetour.Route resumed = detour.complete();
		assertNotNull(resumed);
		assertEquals(VARROCK, resumed.targets);
		assertEquals("map pin", resumed.source);
		assertFalse(detour.isActive());
		assertNull("a completed trip resumes once", detour.complete());
	}

	@Test
	public void aBankTripWithNothingActiveResumesNothing()
	{
		assertNull("no destination, no route", BankDetour.Route.of(Set.of(), null, false, WorldPointUtil.UNDEFINED));
		BankDetour detour = new BankDetour();
		detour.begin(detour.replacing(null));
		assertTrue(detour.isActive());
		assertNull(detour.complete());
	}

	@Test
	public void anyOtherDestinationChangeForgetsTheRoute()
	{
		BankDetour detour = new BankDetour();
		detour.begin(detour.replacing(BankDetour.Route.of(VARROCK, "search", false, WorldPointUtil.UNDEFINED)));
		// A new pin, a clear, another plugin's target: the trip was replaced, not completed.
		detour.cancel();
		assertFalse(detour.isActive());
		assertNull(detour.complete());
	}

	@Test
	public void aSecondBankClickKeepsTheOriginalRoute()
	{
		BankDetour detour = new BankDetour();
		detour.begin(detour.replacing(BankDetour.Route.of(VARROCK, "map pin", false, WorldPointUtil.UNDEFINED)));

		// "And back" pressed during the one-way trip: what it replaces is the bank trip itself,
		// so the route kept is still the original. The plugin's target setter forgets the trip
		// between the two calls, exactly as here.
		BankDetour.Route kept = detour.replacing(BankDetour.Route.of(BANKS, "nearest bank", false, WorldPointUtil.UNDEFINED));
		detour.cancel();
		detour.begin(kept);
		assertEquals(VARROCK, detour.complete().targets);
	}

	@Test
	public void aRouteCopiesItsTargetsAndKeepsItsShape()
	{
		Set<Integer> live = new HashSet<>(VARROCK);
		int pin = WorldPointUtil.packWorldPoint(3212, 3423, 0);
		BankDetour.Route route = BankDetour.Route.of(live, "search", true, pin);
		live.clear();
		assertEquals(VARROCK, route.targets);
		assertTrue(route.roundTrip);
		assertEquals(pin, route.marker);
	}

	@Test
	public void pendingIsTheRouteThatWillResume()
	{
		BankDetour detour = new BankDetour();
		assertNull(detour.pending());
		detour.begin(detour.replacing(BankDetour.Route.of(VARROCK, "map pin", false, WorldPointUtil.UNDEFINED)));
		assertEquals(VARROCK, detour.pending().targets);
		detour.cancel();
		assertNull(detour.pending());
		detour.begin(detour.replacing(null));
		assertNull("a trip with nothing to resume is not a detour", detour.pending());
	}

	@Test
	public void theHeaderLineSaysWhatResumesDuringATrip()
	{
		BankDetour.Route pin = BankDetour.Route.of(VARROCK, "map pin", false, WorldPointUtil.UNDEFINED);
		assertEquals("Destination set by map pin", BankDetour.headerLine("map pin", null, false));
		assertEquals("Bank stop, then the route set by map pin", BankDetour.headerLine("nearest bank", pin, false));
		assertEquals("Bank and back, then the route set by map pin",
			BankDetour.headerLine("nearest bank (and back)", pin, true));
		assertEquals("Bank stop, then your route",
			BankDetour.headerLine("nearest bank", BankDetour.Route.of(VARROCK, null, false, WorldPointUtil.UNDEFINED), false));
		assertEquals("a trip that resumes nothing reads as an ordinary destination",
			"Destination set by nearest bank", BankDetour.headerLine("nearest bank", null, false));
		assertNull(BankDetour.headerLine(null, null, false));
	}

	@Test
	public void aBankClickAddsAStopWhenARouteWouldResume()
	{
		BankDetour detour = new BankDetour();
		assertFalse("nothing set: a plain trip to the bank", detour.wouldResume(false));
		assertTrue("a route under way resumes after the bank", detour.wouldResume(true));
		detour.begin(detour.replacing(BankDetour.Route.of(VARROCK, "map pin", false, WorldPointUtil.UNDEFINED)));
		assertTrue("during a trip that saved a route, another bank click still adds a stop", detour.wouldResume(true));
		detour.cancel();
		detour.begin(detour.replacing(null));
		assertFalse("a trip that replaced nothing: the bank trip itself is the destination", detour.wouldResume(true));
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.when;

/**
 * Plan step N7: the "+ Bank" mode was excluded from the unreachable-target escape menu on the
 * theory that the distance field floods the inventory-only availability, so a target reachable
 * only through a banked item would look unreachable. The field floods BOTH bank states (reverse
 * transport index, teleport landings, blocked-landing patch), so a complete field that never
 * reaches the start is the same proof in every mode. Without the verdict, bank mode ran the full
 * chain against a sealed target: each iteration a blind flood of ~1.4M nodes.
 */
@RunWith(MockitoJUnitRunner.class)
public class BankModeUnreachableVerdictTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;
	@Mock
	ClientThread clientThread;

	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	/** The Broken Raft deck: a walkable tile on a sealed islet (field-verified not standable). */
	private static final int RAFT_DECK = WorldPointUtil.packWorldPoint(3253, 3180, 0);

	@Test
	public void bankModeGetsTheEscapeMenuForAProvablyUnreachableTarget() throws Exception
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);
		List<AlternativeRoutesService.SearchRecord> records;
		List<RouteOption> routes;
		try
		{
			CountDownLatch latch = new CountDownLatch(1);
			AtomicReference<List<RouteOption>> out = new AtomicReference<>();
			service.generate(LUMBRIDGE, Set.of(RAFT_DECK), Set.of(), AlternativeRoutesMode.OWNED_WITH_BANK, 10, 3, false,
				(r, catalog, unavailable, done) ->
				{
					if (done)
					{
						out.set(r);
						latch.countDown();
					}
				});
			assertTrue("generation must finish", latch.await(180, TimeUnit.SECONDS));
			routes = out.get();
			records = service.getLastSearchRecords();
		}
		finally
		{
			service.shutdown();
		}
		long nodes = 0;
		for (AlternativeRoutesService.SearchRecord record : records)
		{
			nodes += Math.max(0, record.nodesChecked);
		}
		System.out.println("BANKVERDICT searches=" + records.size() + " nodes=" + nodes + " routes=" + routes.size());
		// With nothing in the inventory the closest approach is walk-only, so the escape menu is
		// one route; the verdict's value is skipping the walk, seed and tail passes (each a
		// ~2M-node flood against a sealed target). Without it bank mode ran the walk pass too.
		assertTrue("an escape menu, not an empty page", routes != null && !routes.isEmpty());
		StringBuilder passes = new StringBuilder();
		for (AlternativeRoutesService.SearchRecord record : records)
		{
			if (!record.label.startsWith("chain#"))
			{
				passes.append(' ').append(record.label);
			}
		}
		assertTrue("bank mode must skip the walk, seed and tail passes for a provably unreachable target, ran:"
			+ passes, passes.length() == 0);
		assertTrue("bank mode must short-circuit a provably unreachable target: " + records.size() + " searches",
			records.size() <= AlternativeRoutesService.UNREACHABLE_ESCAPE_ROUTES);
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.BankPickupRequirements;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The bank pickup names what the rest of the route needs from the bank, and now also says which
 * bank slots hold it, for the bank highlight: the ids of the items actually in the bank, so a
 * Games necklace(7) lights up even though the phrase names the canonical necklace(8).
 */
public class BankPickupItemIdsTest
{
	private static final int CAMULET_LANDING = WorldPointUtil.packWorldPoint(3106, 9315, 2);
	private static final int BURTHORPE = WorldPointUtil.packWorldPoint(2899, 3553, 0);

	@Test
	public void thePickupListsTheBankSlotsOfEveryItemTheRouteStillNeeds()
	{
		Client client = client();
		ShortestPathConfig config = Mockito.mock(ShortestPathConfig.class, invocation ->
		{
			String name = invocation.getMethod().getName();
			Class<?> type = invocation.getMethod().getReturnType();
			if (type == boolean.class)
			{
				return !"avoidWilderness".equals(name);
			}
			if (type == int.class)
			{
				return "calculationCutoff".equals(name) ? 120 : 0;
			}
			if (type == TeleportationItem.class)
			{
				return TeleportationItem.INVENTORY_AND_BANK;
			}
			return HybridPageFillTest.defaultValue(type);
		});
		PathfinderConfig owned = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		Item[] bank = {new Item(ItemID.CAMULET, 1), new Item(ItemID.NECKLACE_OF_MINIGAMES_7, 1)};
		owned.setBankSnapshot(bank);
		owned.refresh();

		Set<Integer> banks = owned.getDestinations("bank");
		int bankTile = banks.iterator().next();
		List<PathStep> path = List.of(
			new PathStep(bankTile, false, 0),
			new PathStep(CAMULET_LANDING, true, 4),
			new PathStep(BURTHORPE, true, 8));

		BankPickupRequirements.Pickup pickup = BankPickupRequirements.compute(client, bank, owned, banks, path, 0);

		assertEquals("one phrase per item step", 2, pickup.phrases.size());
		assertEquals("the phrase names the canonical necklace", List.of("1 Item " + ItemID.CAMULET, "1 Item " + ItemID.NECKLACE_OF_MINIGAMES_8),
			pickup.phrases);
		assertEquals("the slots to light: the Camulet and the necklace the bank actually holds",
			Set.of(ItemID.CAMULET, ItemID.NECKLACE_OF_MINIGAMES_7), pickup.itemIds);
		assertFalse("the canonical necklace is a name, not a slot", pickup.itemIds.contains(ItemID.NECKLACE_OF_MINIGAMES_8));
	}

	@Test
	public void offTheBankTileThereIsNothingToPickUp()
	{
		Client client = client();
		PathfinderConfig owned = new TestPathfinderConfig(client, Mockito.mock(ShortestPathConfig.class));
		Item[] bank = {new Item(ItemID.CAMULET, 1)};
		List<PathStep> path = List.of(new PathStep(CAMULET_LANDING, true, 0), new PathStep(BURTHORPE, true, 4));
		BankPickupRequirements.Pickup pickup = BankPickupRequirements.compute(client, bank, owned, Set.of(), path, 0);
		assertTrue(pickup.phrases.isEmpty());
		assertTrue(pickup.itemIds.isEmpty());
	}

	/** A logged-in client with nothing on the player; item names read "Item <id>". */
	private static Client client()
	{
		final Thread clientThread = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					case "getItemDefinition":
						ItemComposition item = Mockito.mock(ItemComposition.class);
						Mockito.when(item.getName()).thenReturn("Item " + args[0]);
						return item;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}
}

package gps;

import net.runelite.api.Item;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The cross-session bank snapshot (Travel options → Bank) is persisted as {@code id:quantity}
 * pairs in RSProfile-scoped config. These tests pin the format: a round trip preserves every
 * real item, slots that carry no information (empty slots, withdrawn placeholders) are dropped,
 * and malformed stored data decodes to null (treated as "nothing saved") instead of throwing.
 */
public class BankSnapshotPersistenceTest
{
	@Test
	public void roundTripPreservesItemsAndQuantities()
	{
		Item[] items = {
			new Item(995, 1234567), // coins
			new Item(2434, 12),     // prayer potion(4)
			new Item(19675, 1),     // arclight
		};

		Item[] decoded = BankSnapshotService.decode(BankSnapshotService.encode(items));

		assertArrayEquals(items, decoded);
	}

	@Test
	public void emptySlotsAndPlaceholdersAreDropped()
	{
		Item[] items = {
			new Item(-1, 0),     // empty slot
			new Item(995, 100),
			new Item(2434, 0),   // placeholder: item withdrawn, slot kept
			new Item(-1, 5),     // nonsense id
		};

		Item[] decoded = BankSnapshotService.decode(BankSnapshotService.encode(items));

		assertEquals(1, decoded.length);
		assertEquals(new Item(995, 100), decoded[0]);
	}

	@Test
	public void nothingWorthSavingEncodesToNull()
	{
		assertNull(BankSnapshotService.encode(null));
		assertNull(BankSnapshotService.encode(new Item[0]));
		assertNull(BankSnapshotService.encode(new Item[]{new Item(-1, 0), new Item(4151, 0)}));
	}

	@Test
	public void missingOrMalformedStoredDataDecodesToNull()
	{
		assertNull(BankSnapshotService.decode(null));
		assertNull(BankSnapshotService.decode(""));
		assertNull(BankSnapshotService.decode("garbage"));
		assertNull(BankSnapshotService.decode("995:100,2434")); // pair missing quantity
		assertNull(BankSnapshotService.decode("995:abc"));      // non-numeric quantity
		assertNull(BankSnapshotService.decode(":5"));           // pair missing id
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Plan step L16: the bank knowledge and its cross-session snapshot, out of the plugin class.
 * The first sight of the live bank is reported once; a save is staged with the profile key of
 * the moment and written once (bank close, logout, shutdown), an empty bank dropping the stored
 * snapshot instead; a restore fills in only when nothing was seen live and the setting is on;
 * logout forgets; turning the setting off drops the stored snapshot and, when this session's
 * knowledge came from it, the knowledge too.
 */
@RunWith(MockitoJUnitRunner.class)
public class BankSnapshotServiceTest
{
	private static final String GROUP = "gps";
	private static final String PROFILE = "rsprofile.abc";

	@Mock
	ConfigManager configManager;
	@Mock
	PathfinderConfig pathfinderConfig;
	@Mock
	ItemContainer bank;

	private boolean rememberBank = true;

	private BankSnapshotService service()
	{
		return new BankSnapshotService(configManager, GROUP, () -> rememberBank, pathfinderConfig);
	}

	private static final Item[] ITEMS = {new Item(995, 100), new Item(2434, 3)};

	@Test
	public void theFirstSightIsReportedOnceAndTheStagedSaveWritesOnce()
	{
		when(bank.getItems()).thenReturn(ITEMS);
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
		when(pathfinderConfig.getBankSnapshot()).thenReturn(ITEMS);
		BankSnapshotService service = service();

		assertTrue(service.bankOpened(bank));
		assertTrue(service.isKnown());
		assertFalse(service.isRestored());
		verify(pathfinderConfig).setBankSnapshot(ITEMS);
		assertFalse("a deposit is not a first sight", service.bankOpened(bank));

		service.persist();
		verify(configManager).setConfiguration(GROUP, PROFILE, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT, "995:100,2434:3");
		service.persist();
		verify(configManager).setConfiguration(eq(GROUP), eq(PROFILE), eq(BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT), anyString());
	}

	@Test
	public void anEmptyBankDropsTheStoredSnapshot()
	{
		when(bank.getItems()).thenReturn(new Item[]{new Item(-1, 0)});
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
		when(pathfinderConfig.getBankSnapshot()).thenReturn(new Item[]{new Item(-1, 0)});
		BankSnapshotService service = service();
		service.bankOpened(bank);
		service.persist();
		verify(configManager).unsetConfiguration(GROUP, PROFILE, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT);
	}

	@Test
	public void nothingIsStagedWhenTheSettingIsOff()
	{
		rememberBank = false;
		when(bank.getItems()).thenReturn(ITEMS);
		BankSnapshotService service = service();
		service.bankOpened(bank);
		service.persist();
		verify(configManager, never()).setConfiguration(anyString(), anyString(), anyString(), any());
		verify(configManager, never()).getRSProfileKey();
	}

	@Test
	public void restoreFillsInOnlyBeforeTheLiveBankAndTheLiveBankSupersedesIt()
	{
		when(configManager.getRSProfileConfiguration(GROUP, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT)).thenReturn("995:100");
		BankSnapshotService service = service();
		service.restore();
		assertTrue(service.isKnown());
		assertTrue(service.isRestored());
		verify(pathfinderConfig).setBankSnapshot(new Item[]{new Item(995, 100)});

		when(bank.getItems()).thenReturn(ITEMS);
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
		assertFalse("restored knowledge counts as known: not a first sight", service.bankOpened(bank));
		assertFalse(service.isRestored());

		service.restore();
		verify(configManager).getRSProfileConfiguration(GROUP, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT);
	}

	@Test
	public void restoreIsSkippedWhenTheSettingIsOff()
	{
		rememberBank = false;
		BankSnapshotService service = service();
		service.restore();
		assertFalse(service.isKnown());
		verify(configManager, never()).getRSProfileConfiguration(anyString(), anyString());
	}

	@Test
	public void logoutPersistsThenForgets()
	{
		when(bank.getItems()).thenReturn(ITEMS);
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
		when(pathfinderConfig.getBankSnapshot()).thenReturn(ITEMS);
		BankSnapshotService service = service();
		service.bankOpened(bank);
		service.forget();
		verify(configManager).setConfiguration(GROUP, PROFILE, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT, "995:100,2434:3");
		verify(pathfinderConfig).clearBank();
		assertFalse(service.isKnown());
		assertFalse(service.isRestored());
	}

	@Test
	public void turningTheSettingOffDropsTheStoredSnapshotAndRestoredKnowledge()
	{
		when(configManager.getRSProfileConfiguration(GROUP, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT)).thenReturn("995:100");
		BankSnapshotService service = service();
		service.restore();
		assertTrue("the knowledge came from the snapshot: dropped with it", service.forgetStored());
		verify(configManager).unsetRSProfileConfiguration(GROUP, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT);
		verify(pathfinderConfig).clearBank();
		assertFalse(service.isKnown());

		when(bank.getItems()).thenReturn(ITEMS);
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
		service.bankOpened(bank);
		assertFalse("live knowledge stays", service.forgetStored());
		assertTrue(service.isKnown());
	}

	@Test
	public void turningTheSettingOnSavesALiveBankAtOnce()
	{
		when(bank.getItems()).thenReturn(ITEMS);
		when(configManager.getRSProfileKey()).thenReturn(PROFILE);
		when(pathfinderConfig.getBankSnapshot()).thenReturn(ITEMS);
		rememberBank = false;
		BankSnapshotService service = service();
		service.bankOpened(bank);
		rememberBank = true;
		service.rememberNow(true);
		verify(configManager).setConfiguration(GROUP, PROFILE, BankSnapshotService.CONFIG_KEY_BANK_SNAPSHOT, "995:100,2434:3");
	}
}

package gps;

