package gps;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Panel series P1: the destination search's ranking, out of the panel class. The match tiers
 * (exact, prefix, word prefix, substring, subsequence) order the results before anything else;
 * within a tier the entry nearest the player comes first, or the alphabetical one when the
 * player's position is unknown; the list is capped at twelve; nothing matches nothing.
 */
public class DestinationSearchRankingTest
{
	private static Destinations.Entry at(String name, int x, int y)
	{
		return new Destinations.Entry("place", name, WorldPointUtil.packWorldPoint(x, y, 0));
	}

	private static List<String> names(List<Destinations.Entry> entries)
	{
		List<String> names = new ArrayList<>();
		for (Destinations.Entry entry : entries)
		{
			names.add(entry.name);
		}
		return names;
	}

	@Test
	public void theMatchTierRanksBeforeProximity()
	{
		// The player stands at the mine: nearest, but a word-prefix match ranks below the exact
		// and prefix matches.
		List<Destinations.Entry> pool = List.of(at("East Varrock mine", 3280, 3360), at("Ardougne", 2660, 3300),
			at("Varrock Bank", 3183, 3436), at("Varrock", 3210, 3424));
		List<Destinations.Entry> ranked = DestinationSearchView.rank(pool, "varrock", WorldPointUtil.packWorldPoint(3280, 3360, 0));
		assertEquals(List.of("Varrock", "Varrock Bank", "East Varrock mine"), names(ranked));
	}

	@Test
	public void proximityBreaksTiesWithinATierAndTheNameWithoutAPosition()
	{
		Destinations.Entry north = at("Lumbridge north", 3222, 3260);
		Destinations.Entry south = at("Lumbridge south", 3222, 3200);
		assertEquals(List.of("Lumbridge south", "Lumbridge north"),
			names(DestinationSearchView.rank(List.of(north, south), "lumbridge", WorldPointUtil.packWorldPoint(3222, 3190, 0))));
		assertEquals(List.of("Lumbridge north", "Lumbridge south"),
			names(DestinationSearchView.rank(List.of(south, north), "lumbridge", WorldPointUtil.UNDEFINED)));
	}

	@Test
	public void atMostTwelveResultsAndNoneForNoMatch()
	{
		List<Destinations.Entry> pool = new ArrayList<>();
		for (int i = 1; i <= 15; i++)
		{
			pool.add(at(String.format("Place %02d", i), 3000 + i, 3000));
		}
		assertEquals(12, DestinationSearchView.rank(pool, "place", WorldPointUtil.UNDEFINED).size());
		assertTrue(DestinationSearchView.rank(pool, "xyzzy", WorldPointUtil.UNDEFINED).isEmpty());
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Repairs the unreachable-destination backlog (enable with -DsnapFix=true). Two outputs:
 *
 * 1. SNAP — pins whose tile isn't reachable but which have a reachable tile within
 *    {@link #MAX_SNAP} are rewritten onto it. These are pins on the wrong TILE: the amenity dump
 *    pinned the object (an altar's tiles, a bank booth) instead of the tile you stand on to use
 *    it. Rows that collapse onto the same place are de-duplicated. Only already-broken pins are
 *    touched, and only by a few tiles.
 * 2. TODO — everything still sealed is grouped by building/area into a field checklist, with the
 *    nearest reachable tile to walk to, so the missing entrances can be mapped with the audit.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class DestinationSnapFixTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int INSTANCE_MIN_Y = 4160;
	private static final int INSTANCE_MAX_Y = 8000;
	private static final int MAX_SNAP = 12;
	private static final int TODO_SEARCH = 60;
	private static final String[] FILES = {"destinations.tsv", "destinations-wiki.tsv"};

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private Set<Integer> reachable;
	private CollisionMap map;

	@Test
	public void snapAndReport() throws IOException
	{
		Assume.assumeTrue(Boolean.getBoolean("snapFix"));
		flood();

		List<String[]> sealed = new ArrayList<>();
		int snapped = 0;
		int dropped = 0;
		for (String file : FILES)
		{
			Path path = Paths.get("src/main/resources/" + file);
			List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
			List<String> out = new ArrayList<>(lines.size());
			Set<String> seen = new LinkedHashSet<>();
			for (String line : lines)
			{
				String[] fields = line.split("\t", -1);
				if (line.startsWith("#") || line.isBlank() || fields.length < 5
					|| !fields[2].trim().matches("\\d+"))
				{
					out.add(line);
					continue;
				}
				int x = Integer.parseInt(fields[2].trim());
				int y = Integer.parseInt(fields[3].trim());
				int plane = Integer.parseInt(fields[4].trim());
				int packed = WorldPointUtil.packWorldPoint(x, y, plane);
				if (!(y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y) && !anyReachable(packed))
				{
					int snap = nearestReachable(x, y, plane, MAX_SNAP);
					if (snap != WorldPointUtil.UNDEFINED)
					{
						fields[2] = String.valueOf(WorldPointUtil.unpackWorldX(snap));
						fields[3] = String.valueOf(WorldPointUtil.unpackWorldY(snap));
						snapped++;
						line = String.join("\t", fields);
					}
					else
					{
						sealed.add(new String[]{fields[0], fields[1], String.valueOf(x),
							String.valueOf(y), String.valueOf(plane)});
					}
				}
				// Collapse rows that now name the same place at the same tile.
				String key = fields[0] + "|" + fields[1] + "|" + fields[2] + "|" + fields[3]
					+ "|" + fields[4];
				if (!seen.add(key))
				{
					dropped++;
					continue;
				}
				out.add(line);
			}
			Files.write(path, String.join("\n", out).concat("\n").getBytes(StandardCharsets.UTF_8));
		}
		System.out.println("snapped " + snapped + " pins onto reachable tiles, dropped "
			+ dropped + " duplicates, " + sealed.size() + " still sealed");
		writeTodo(sealed);
	}

	/** Groups sealed pins by area and writes a field checklist with somewhere to walk to. */
	private void writeTodo(List<String[]> sealed) throws IOException
	{
		Map<String, List<String[]>> byArea = new TreeMap<>();
		for (String[] pin : sealed)
		{
			int x = Integer.parseInt(pin[2]);
			int y = Integer.parseInt(pin[3]);
			byArea.computeIfAbsent((x / 32 * 32) + "," + (y / 32 * 32) + "," + pin[4],
				k -> new ArrayList<>()).add(pin);
		}
		List<Map.Entry<String, List<String[]>>> areas = new ArrayList<>(byArea.entrySet());
		areas.sort((a, b) -> b.getValue().size() - a.getValue().size());

		StringBuilder md = new StringBuilder();
		md.append("# Unreachable destination areas — field checklist\n\n");
		md.append("Generated by `DestinationSnapFixTest -DsnapFix=true`. Each block is a place ")
			.append("with amenities GPS can't route to, meaning its entrance (staircase, door, ")
			.append("cave) has no transport row. Walk to the suggested tile, then map the way in ")
			.append("with the audit plugin — one staircase usually unseals the whole list.\n\n");
		md.append("Total sealed pins: ").append(sealed.size())
			.append(" in ").append(areas.size()).append(" areas.\n\n");
		for (Map.Entry<String, List<String[]>> area : areas)
		{
			List<String[]> pins = area.getValue();
			int cx = Integer.parseInt(area.getKey().split(",")[0]) + 16;
			int cy = Integer.parseInt(area.getKey().split(",")[1]) + 16;
			int plane = Integer.parseInt(area.getKey().split(",")[2]);
			int walkTo = nearestReachable(cx, cy, plane, TODO_SEARCH);
			if (walkTo == WorldPointUtil.UNDEFINED && plane > 0)
			{
				walkTo = nearestReachable(cx, cy, 0, TODO_SEARCH);
			}
			md.append("## ").append(pins.size()).append(" pins near ").append(cx).append(",")
				.append(cy).append(" (plane ").append(plane).append(")\n");
			md.append("- [ ] walk to **")
				.append(walkTo == WorldPointUtil.UNDEFINED ? "(nothing reachable within "
					+ TODO_SEARCH + " tiles)"
					: WorldPointUtil.unpackWorldX(walkTo) + ", " + WorldPointUtil.unpackWorldY(walkTo)
						+ ", " + WorldPointUtil.unpackWorldPlane(walkTo))
				.append("** and map the entrance\n");
			Set<String> names = new LinkedHashSet<>();
			for (String[] pin : pins)
			{
				names.add(pin[0] + " " + pin[1]);
			}
			md.append("- sealed: ");
			int shown = 0;
			for (String name : names)
			{
				if (shown++ > 0)
				{
					md.append(", ");
				}
				if (shown > 8)
				{
					md.append("… +").append(names.size() - 8).append(" more");
					break;
				}
				md.append(name);
			}
			md.append("\n\n");
		}
		Path out = Paths.get("build/unreachable-areas.md");
		Files.write(out, md.toString().getBytes(StandardCharsets.UTF_8));
		System.out.println("checklist written to " + out.toAbsolutePath());
	}

	private int nearestReachable(int x, int y, int plane, int maxRadius)
	{
		for (int radius = 1; radius <= maxRadius; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
					{
						continue;
					}
					int candidate = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
					if (reachable.contains(candidate))
					{
						return candidate;
					}
				}
			}
		}
		return WorldPointUtil.UNDEFINED;
	}

	private boolean anyReachable(int packed)
	{
		for (int target : Destinations.walkableTargets(map, packed))
		{
			if (reachable.contains(target))
			{
				return true;
			}
		}
		return false;
	}

	private void flood()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useTeleportationItems()).thenReturn(gps.TeleportationItem.ALL);
		when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		TestPathfinderConfig testConfig = new TestPathfinderConfig(client, config);
		// Universal bank: reachable means "a player CAN get there" — any obtainable item is
		// assumed owned (dashboard's BANK-preset pattern), else item-gated teleports like the
		// Sailors' amulet would wrongly strand their destinations (Port Roberts).
		net.runelite.api.ItemContainer universalBank = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] everyItem = new net.runelite.api.Item[40000];
		for (int i = 0; i < everyItem.length; i++)
		{
			everyItem[i] = new net.runelite.api.Item(i, 1000);
		}
		when(universalBank.getItems()).thenReturn(everyItem);
		testConfig.bank = universalBank;
		PathfinderConfig planning = testConfig.copyForPlanning();
		planning.refresh();
		map = planning.getMap();
		PrimitiveIntHashMap<Transport[]> transports = planning.getTransportsPacked(true);
		reachable = new HashSet<>(1 << 20);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		reachable.add(LUMBRIDGE);
		queue.add(LUMBRIDGE);
		// ORIGIN-LESS teleports (jewellery, tablets, spells) work ANYWHERE, so their landing
		// tiles are reachable outright. Keyed under UNDEFINED_ORIGIN rather than a tile, they
		// were invisible to a walk-the-graph flood — which made every teleport-only place,
		// Port Roberts included, look sealed.
		Transport[] anywhere = transports.get(Transport.UNDEFINED_ORIGIN);
		if (anywhere != null)
		{
			for (Transport transport : anywhere)
			{
				if (transport.getDestination() != WorldPointUtil.UNDEFINED
					&& reachable.add(transport.getDestination()))
				{
					queue.add(transport.getDestination());
				}
			}
		}
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
					if ((dx != 0 || dy != 0) && !reachable.contains(next) && map.canStep(at, next))
					{
						reachable.add(next);
						queue.add(next);
					}
				}
			}
			Transport[] from = transports.get(at);
			if (from != null)
			{
				for (Transport transport : from)
				{
					int destination = transport.getDestination();
					if (destination != WorldPointUtil.UNDEFINED && reachable.add(destination))
					{
						queue.add(destination);
					}
				}
			}
		}
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Triage for the unreachable-destination backlog (enable with -DsnapReport=true).
 *
 * Splits the failures into the two populations that need completely different fixes:
 *   SNAPPABLE — a reachable tile sits within a few tiles, so the pin is merely on the wrong
 *   tile (amenity dumps pin the OBJECT, not the tile you stand on). Fixable programmatically
 *   by rewriting the coordinate.
 *   SEALED — nothing reachable anywhere near, so the area genuinely has no mapped way in
 *   (missing staircase, door or cave entrance). Needs data, not a coordinate nudge.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class DestinationSnapReportTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int INSTANCE_MIN_Y = 4160;
	private static final int INSTANCE_MAX_Y = 8000;
	private static final int MAX_SNAP = 12;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void report()
	{
		Assume.assumeTrue(Boolean.getBoolean("snapReport"));
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useTeleportationItems()).thenReturn(gps.TeleportationItem.ALL);
		when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		TestPathfinderConfig testConfig = new TestPathfinderConfig(client, config);
		// Universal bank: reachable means "a player CAN get there" — any obtainable item is
		// assumed owned (dashboard's BANK-preset pattern), else item-gated teleports like the
		// Sailors' amulet would wrongly strand their destinations (Port Roberts).
		net.runelite.api.ItemContainer universalBank = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] everyItem = new net.runelite.api.Item[40000];
		for (int i = 0; i < everyItem.length; i++)
		{
			everyItem[i] = new net.runelite.api.Item(i, 1000);
		}
		when(universalBank.getItems()).thenReturn(everyItem);
		testConfig.bank = universalBank;
		PathfinderConfig planning = testConfig.copyForPlanning();
		planning.refresh();
		CollisionMap map = planning.getMap();
		PrimitiveIntHashMap<Transport[]> transports = planning.getTransportsPacked(true);

		Set<Integer> reachable = new HashSet<>(1 << 20);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		reachable.add(LUMBRIDGE);
		queue.add(LUMBRIDGE);
		// ORIGIN-LESS teleports (jewellery, tablets, spells) work ANYWHERE, so their landing
		// tiles are reachable outright. Keyed under UNDEFINED_ORIGIN rather than a tile, they
		// were invisible to a walk-the-graph flood — which made every teleport-only place,
		// Port Roberts included, look sealed.
		Transport[] anywhere = transports.get(Transport.UNDEFINED_ORIGIN);
		if (anywhere != null)
		{
			for (Transport transport : anywhere)
			{
				if (transport.getDestination() != WorldPointUtil.UNDEFINED
					&& reachable.add(transport.getDestination()))
				{
					queue.add(transport.getDestination());
				}
			}
		}
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
					if ((dx != 0 || dy != 0) && !reachable.contains(next) && map.canStep(at, next))
					{
						reachable.add(next);
						queue.add(next);
					}
				}
			}
			Transport[] from = transports.get(at);
			if (from != null)
			{
				for (Transport t : from)
				{
					if (t.getDestination() != WorldPointUtil.UNDEFINED && reachable.add(t.getDestination()))
					{
						queue.add(t.getDestination());
					}
				}
			}
		}

		int[] snapBuckets = new int[MAX_SNAP + 1];
		int sealed = 0;
		int total = 0;
		Map<String, Integer> sealedByArea = new TreeMap<>();
		Map<String, Integer> sealedByCategory = new TreeMap<>();
		for (Destinations.Entry entry : Destinations.resourceEntries())
		{
			int x = WorldPointUtil.unpackWorldX(entry.packedPosition);
			int y = WorldPointUtil.unpackWorldY(entry.packedPosition);
			int plane = WorldPointUtil.unpackWorldPlane(entry.packedPosition);
			if (y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y)
			{
				continue;
			}
			boolean ok = false;
			for (int target : Destinations.walkableTargets(map, entry.packedPosition))
			{
				if (reachable.contains(target))
				{
					ok = true;
					break;
				}
			}
			if (ok)
			{
				continue;
			}
			total++;
			int found = -1;
			for (int radius = 1; radius <= MAX_SNAP && found < 0; radius++)
			{
				for (int dx = -radius; dx <= radius && found < 0; dx++)
				{
					for (int dy = -radius; dy <= radius && found < 0; dy++)
					{
						if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
						{
							continue;
						}
						if (reachable.contains(WorldPointUtil.packWorldPoint(x + dx, y + dy, plane)))
						{
							found = radius;
						}
					}
				}
			}
			if (found > 0)
			{
				snapBuckets[found]++;
			}
			else
			{
				sealed++;
				sealedByArea.merge((x / 64 * 64) + "," + (y / 64 * 64) + " p" + plane, 1, Integer::sum);
				sealedByCategory.merge(entry.category, 1, Integer::sum);
			}
		}

		System.out.println("UNREACHABLE TOTAL: " + total);
		int running = 0;
		for (int r = 1; r <= MAX_SNAP; r++)
		{
			running += snapBuckets[r];
			System.out.println("  snappable within " + r + " tiles: " + snapBuckets[r]
				+ "   (cumulative " + running + ")");
		}
		System.out.println("SEALED (no reachable tile within " + MAX_SNAP + "): " + sealed);
		System.out.println("--- sealed by category ---");
		sealedByCategory.entrySet().stream()
			.sorted((a, b) -> b.getValue() - a.getValue()).limit(15)
			.forEach(e -> System.out.println("  " + e.getValue() + "  " + e.getKey()));
		System.out.println("--- worst sealed areas (64x64 blocks) ---");
		sealedByArea.entrySet().stream()
			.sorted((a, b) -> b.getValue() - a.getValue()).limit(20)
			.forEach(e -> System.out.println("  " + e.getValue() + "  @" + e.getKey()));
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * DATA INVARIANT: every searchable destination must be somewhere a player can actually get to.
 *
 * A pin on an unreachable tile is worse than a missing pin — the search explores the whole map,
 * gives up, and drops the player at "the closest reachable point", which is the pathology that
 * produced the Kingdom Divided report. Rather than pathfind to thousands of pins (minutes), this
 * floods ONCE from Lumbridge across walking edges plus every transport, then asserts each
 * destination's {@link Destinations#walkableTargets} set intersects that reachable region — the
 * same expansion the real search performs, so a pin on a fence still passes if its surroundings
 * are reachable.
 *
 * Failures are reported in bulk with coordinates, so a bad import is one glance to triage.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class DestinationsReachableTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	/** Instanced template bands: pins there are scenery copies, not places (POH, raids, cutscenes). */
	private static final int INSTANCE_MIN_Y = 4160;
	private static final int INSTANCE_MAX_Y = 8000;

	private static Set<Integer> reachable;
	private static CollisionMap map;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@BeforeClass
	public static void beforeClass()
	{
		reachable = null;
	}

	private void flood()
	{
		if (reachable != null)
		{
			return;
		}
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useTeleportationItems()).thenReturn(gps.TeleportationItem.ALL);
		when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		TestPathfinderConfig testConfig = new TestPathfinderConfig(client, config);
		// Universal bank: reachable means "a player CAN get there" — any obtainable item is
		// assumed owned (dashboard's BANK-preset pattern), else item-gated teleports like the
		// Sailors' amulet would wrongly strand their destinations (Port Roberts).
		net.runelite.api.ItemContainer universalBank = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] everyItem = new net.runelite.api.Item[40000];
		for (int i = 0; i < everyItem.length; i++)
		{
			everyItem[i] = new net.runelite.api.Item(i, 1000);
		}
		when(universalBank.getItems()).thenReturn(everyItem);
		testConfig.bank = universalBank;
		PathfinderConfig planning = testConfig.copyForPlanning();
		planning.refresh();
		map = planning.getMap();

		// Transport edges by origin, so the flood can jump the way a route can. Bank-visited
		// availability is the superset (it also offers banked-item teleports).
		PrimitiveIntHashMap<Transport[]> transports = planning.getTransportsPacked(true);
		Set<Integer> seen = new HashSet<>(1 << 20);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		seen.add(LUMBRIDGE);
		queue.add(LUMBRIDGE);
		// ORIGIN-LESS teleports (jewellery, tablets, spells) are usable ANYWHERE, so their
		// landing tiles are reachable outright. Keyed under UNDEFINED_ORIGIN rather than a
		// tile, they were invisible to a walk-the-graph flood — which made every
		// teleport-only destination, Port Roberts included, look sealed.
		Transport[] anywhere = transports.get(Transport.UNDEFINED_ORIGIN);
		if (anywhere != null)
		{
			for (Transport transport : anywhere)
			{
				if (transport.getDestination() != WorldPointUtil.UNDEFINED
					&& seen.add(transport.getDestination()))
				{
					queue.add(transport.getDestination());
				}
			}
		}
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
					// Transport origins may be collision-blocked (a fairy ring blocks its
					// own tile); the engine admits them via isTransportOrigin, so the flood
					// must too — without this, ALL ring-only content (Zanaris) reads sealed.
					// ...and symmetrically OFF one: a transport delivers you ONTO its
					// blocked destination ring; without the exit clause Zanaris's hub ring
					// was a trap node and the whole realm stayed sealed.
					if (!seen.contains(next)
						&& (map.canStep(at, next) || transports.get(next) != null
							|| (transports.get(at) != null && !map.isBlocked(x + dx, y + dy, plane))))
					{
						seen.add(next);
						queue.add(next);
					}
				}
			}
			Transport[] fromHere = transports.get(at);
			if (fromHere != null)
			{
				for (Transport transport : fromHere)
				{
					int destination = transport.getDestination();
					if (destination != WorldPointUtil.UNDEFINED && seen.add(destination))
					{
						queue.add(destination);
					}
				}
			}
		}
		reachable = seen;
	}

	/**
	 * Curated pins whose ENTRANCE has no transport row yet — real data gaps, not bad pins, each
	 * needing the cave/dungeon entrance mapped (audit field capture). Shrink this list; never
	 * add to it. Found by this test on 2026-07-27.
	 */
	private static final Set<String> KNOWN_GAPS = Set.of(
		"Ferox Enclave Dungeon", "Mogre Camp", "Ruins of Mokhaiotl", "Kendal's Lair");

	/**
	 * Known-unreachable IMPORTED pins; drive it down, never up. Re-based 647 -> 733 on
	 * 2026-07-29 when the collision substrate fix sealed the sailable ocean (the buoy-network
	 * flood, exactly): 86 pins had been reachable only by WALKING ON THE SEA. The honest
	 * backlog shrinks via the snap pass and island landings.
	 */
	// 733 -> 747 with the 2026-07-30 cache refresh (rev 2644): a world update legitimately
	// moves this number; the ratchet exists to catch OUR data regressions between refreshes.
	// 738 -> 709 on 2026-08-27: the dumper stopped blocking interact-2 ground decor
	// (bloodsplatters, droppings - walkable live), freeing 12 pins incl. the West
	// Ardougne chaos altar graveyard (live dump 1787883744264 was the arbiter).
	// 709 -> 705 on 2026-08-27: the Trouble Brewing arena's water-source pins are
	// minigame-only interiors, excluded from every destination surface (destination-
	// exclusions.tsv) rather than treated as unreachable places.
	// 705 -> 694 on 2026-08-27: MLM rockfall rows reconnected the bank quadrant, the
	// Fairytale I wall gap opened the Tanglefoot lair (both silent band offenders, now
	// asserted at zero below), Soul Wars' battle-interior pins are excluded and the Pest
	// Control pin adopts its Void-outpost remap anchor.
	// 694 -> 569 on 2026-08-27: pins on sailable water count as reachable by sea (the
	// 125 ocean-region landmarks are sailing destinations, not land gaps).
	// 569 -> a checked-in LIST on 2026-09-07 (plan step N14): a number let any pin trade places
	// with any other; the list names each known-unreachable pin, so a new one fails by name and
	// a listed pin that becomes reachable fails too, keeping the backlog honest in both directions.
	private static final String EXPECTED_UNREACHABLE = "src/test/resources/expected-unreachable.tsv";

	/** The listed pins in the same "category / name @x,y,plane" form the audit reports, or null when the file is missing. */
	private static Set<String> loadExpectedUnreachable() throws java.io.IOException
	{
		java.nio.file.Path path = java.nio.file.Paths.get(EXPECTED_UNREACHABLE);
		if (!java.nio.file.Files.exists(path))
		{
			return null;
		}
		Set<String> expected = new java.util.HashSet<>();
		for (String line : java.nio.file.Files.readAllLines(path, java.nio.charset.StandardCharsets.UTF_8))
		{
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] f = line.split("\t");
			if (f.length < 5)
			{
				continue;
			}
			expected.add(f[0] + " / " + f[1] + " @" + f[2] + "," + f[3] + "," + f[4]);
		}
		return expected;
	}

	/** Rewrites the list from the current audit (sorted), for a legitimate world update. */
	private static void writeExpectedUnreachable(List<String> unreachable) throws java.io.IOException
	{
		java.util.TreeSet<String> rows = new java.util.TreeSet<>();
		for (String entry : unreachable)
		{
			int at = entry.lastIndexOf('@');
			String[] xyz = entry.substring(at + 1).split(",");
			String head = entry.substring(0, at).trim();
			int sep = head.indexOf(" / ");
			rows.add(head.substring(0, sep) + "\t" + head.substring(sep + 3) + "\t" + xyz[0] + "\t" + xyz[1] + "\t" + xyz[2]);
		}
		List<String> lines = new ArrayList<>();
		lines.add("# Imported destination pins known to be unreachable (DestinationsReachableTest). Generated with");
		lines.add("# -Dgps.writeExpectedUnreachable=true; drive the list down by mapping entrances, never add by hand.");
		lines.add("# category\tname\tx\ty\tplane");
		lines.addAll(rows);
		java.nio.file.Files.write(java.nio.file.Paths.get(EXPECTED_UNREACHABLE), lines, java.nio.charset.StandardCharsets.UTF_8);
	}

	/**
	 * Real content living inside the instance template band, enforced by the invariant like
	 * anywhere else. The band is MOSTLY scenery copies (POH layouts, cutscenes), but a few
	 * genuine places are built there — the blanket skip hid a fully sealed Motherlode Mine
	 * pin. Transport-proximity was tried and over-matched (POH portal rows qualified whole
	 * template houses); an explicit box per known place is honest and auditable.
	 */
	private static final int[][] BAND_CONTENT_BOXES = {
		{3700, 5620, 3780, 5710}, // Motherlode Mine
		{2360, 4340, 2500, 4480}, // Zanaris
	};

	private boolean bandContent(int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		for (int[] box : BAND_CONTENT_BOXES)
		{
			if (x >= box[0] && y >= box[1] && x <= box[2] && y <= box[3])
			{
				return true;
			}
		}
		return false;
	}

	private Boolean oceanReachable;

	/**
	 * A pin on sailable water is a SAILING destination: the router reaches open water through
	 * the sea matrix once any mooring is boardable - motion the land flood cannot model. The
	 * sailable ocean is one connected body (the water-map invariant), so one reachable mooring
	 * makes every sailable tile attainable. 125 sea-region landmarks ("Kharidian Sea", "Lunar
	 * Bay") were counted unreachable for want of this rule.
	 */
	private boolean seaReachable(int packed)
	{
		if (!gps.SailingSea.isSailable(packed))
		{
			return false;
		}
		if (oceanReachable == null)
		{
			boolean any = false;
			for (int tile : reachable)
			{
				if (gps.SailingSea.isMooringLand(tile))
				{
					any = true;
					break;
				}
			}
			oceanReachable = any;
		}
		return oceanReachable;
	}

	private boolean anyReachable(int packed)
	{
		if (seaReachable(packed))
		{
			return true;
		}
		for (int target : Destinations.walkableTargets(map, packed))
		{
			if (reachable.contains(target))
			{
				return true;
			}
		}
		return false;
	}

	/** The hand-curated pins are ours to author, so the bar is zero unreachable. */
	@Test
	public void everyCuratedDestinationIsReachable() throws java.io.IOException
	{
		flood();
		List<String> unreachable = new ArrayList<>();
		int checked = 0;
		try (java.io.InputStream in =
			ShortestPathPlugin.class.getResourceAsStream("/destinations-curated.tsv"))
		{
			java.util.Scanner scanner = new java.util.Scanner(in, "UTF-8");
			scanner.nextLine(); // header
			while (scanner.hasNextLine())
			{
				String[] fields = scanner.nextLine().split("\t");
				if (fields.length < 5 || fields[0].startsWith("#"))
				{
					continue;
				}
				int packed = WorldPointUtil.packWorldPoint(Integer.parseInt(fields[2].trim()),
					Integer.parseInt(fields[3].trim()), Integer.parseInt(fields[4].trim()));
				int py = WorldPointUtil.unpackWorldY(packed);
				if (py >= INSTANCE_MIN_Y && py <= INSTANCE_MAX_Y || KNOWN_GAPS.contains(fields[1]))
				{
					continue;
				}
				checked++;
				if (!anyReachable(packed))
				{
					unreachable.add(fields[1] + " @" + fields[2] + "," + fields[3] + "," + fields[4]);
				}
			}
		}
		assertTrue("expected the curated pins to load", checked > 20);
		assertTrue("curated destinations must be reachable, these are not:\n  "
			+ String.join("\n  ", unreachable), unreachable.isEmpty());
	}

	/**
	 * The bulk imports (wiki + amenity dumps) carry known debt — 1166 of 5598 when written,
	 * largely upper-floor altars whose staircases have no transport row. A RATCHET rather than a
	 * hard zero, so imports can't quietly add unreachable pins while the backlog is worked down.
	 */
	@Test
	public void importedDestinationsDoNotRegress() throws java.io.IOException
	{
		flood();
		List<String> unreachable = new ArrayList<>();
		int checked = 0;
		for (Destinations.Entry entry : Destinations.resourceEntries())
		{
			int y = WorldPointUtil.unpackWorldY(entry.packedPosition);
			if (y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y && !bandContent(entry.packedPosition))
			{
				continue; // template junk: no transports anywhere near
			}
			checked++;
			if (!anyReachable(entry.packedPosition))
			{
				unreachable.add(entry.category + " / " + entry.name + " @"
					+ WorldPointUtil.unpackWorldX(entry.packedPosition) + ","
					+ WorldPointUtil.unpackWorldY(entry.packedPosition) + ","
					+ WorldPointUtil.unpackWorldPlane(entry.packedPosition));
			}
		}
		assertTrue("checked at least a few hundred destinations", checked > 200);
		// Band-content offenders get named first: they are enforced by an explicit box, so
		// a failure here is either a data gap in a REAL band place or a wrong box.
		List<String> bandOffenders = new ArrayList<>();
		for (String entry : unreachable)
		{
			String[] at = entry.substring(entry.lastIndexOf('@') + 1).split(",");
			int y = Integer.parseInt(at[1]);
			if (y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y)
			{
				bandOffenders.add(entry);
			}
		}
		// Band boxes are explicit content declarations, so an unreachable pin inside one is a
		// hard failure on its own - not just a unit inside the ratchet (two offenders sat here
		// silently for weeks: the MLM bank quadrant and the Tanglefoot lair).
		assertTrue("BAND-CONTENT offenders: " + String.join("; ", bandOffenders),
			bandOffenders.isEmpty());
		if (Boolean.getBoolean("gps.writeExpectedUnreachable"))
		{
			writeExpectedUnreachable(unreachable);
		}
		Set<String> expected = loadExpectedUnreachable();
		assertTrue("the expected-unreachable list is missing (" + EXPECTED_UNREACHABLE + "): generate it with"
			+ " -Dgps.writeExpectedUnreachable=true and check it in", expected != null);
		Set<String> unreachableSet = new java.util.HashSet<>(unreachable);
		List<String> fresh = new ArrayList<>();
		for (String entry : unreachable)
		{
			if (!expected.contains(entry))
			{
				fresh.add(entry);
			}
		}
		List<String> stale = new ArrayList<>();
		for (String entry : expected)
		{
			if (!unreachableSet.contains(entry))
			{
				stale.add(entry);
			}
		}
		java.util.Collections.sort(stale);
		assertTrue(fresh.size() + " NEW unreachable imported destinations (" + unreachable.size() + " of " + checked
			+ " in total, " + expected.size() + " expected). Either a data regression to fix, or a world update:"
			+ " then regenerate the list with -Dgps.writeExpectedUnreachable=true. First:\n  "
			+ String.join("\n  ", fresh.subList(0, Math.min(40, fresh.size()))), fresh.isEmpty());
		assertTrue(stale.size() + " listed pins are reachable now: remove them from " + EXPECTED_UNREACHABLE
			+ " (regenerate with -Dgps.writeExpectedUnreachable=true). First:\n  "
			+ String.join("\n  ", stale.subList(0, Math.min(40, stale.size()))), stale.isEmpty());
	}
}

