package gps;

import org.junit.Test;

public class DirectSeaLegTest
{
	@Test
	public void closeWaterPinGetsADirectLeg()
	{
		int start = WorldPointUtil.packWorldPoint(2744, 2989, 0);
		int pin = WorldPointUtil.packWorldPoint(2692, 2941, 0);
		System.out.println("start sailable: " + SailingSea.isSailable(start)
			+ " pin sailable: " + SailingSea.isSailable(pin));
		System.out.println("seaDistanceBetween: " + SailingSea.seaDistanceBetween(start, pin));
		java.util.List<gps.transport.Transport> legs =
			SailingSea.aboardLegTransports(start, java.util.Set.of(pin));
		// Field capture 232906: the route detoured disembark+re-embark through Cairn Isle
		// because the direct leg was missing live (own-wake obstacle poisoning). Headless,
		// the direct leg must exist and be dramatically cheaper than the port chain.
		int distance = SailingSea.seaDistanceBetween(start, pin);
		org.junit.Assert.assertTrue("direct sea distance sane: " + distance,
			distance > 4000 && distance < 12000);
		boolean direct = false;
		for (gps.transport.Transport leg : legs)
		{
			direct |= "Sail to the destination".equals(leg.getDisplayInfo())
				&& leg.getDestination() == pin && leg.getDuration() < 60;
		}
		org.junit.Assert.assertTrue("direct leg to the pin must be synthesized", direct);
	}

	/**
	 * Task 16 (findings 6-7): the aboard legs must cover EVERY sea-connected port, matrix-
	 * composed past the wet flood's ~12-endpoint settle horizon — one continuous
	 * "Disembark at Grimstone" from the Pandemonium instead of unreachable-or-chain. Whether
	 * the ROUTER prefers it is the service layer's cost call (teleport+short-hop chains
	 * legitimately win for Grimstone via Weiss); the leg's existence is what this pins.
	 */
	@Test
	public void aboardLegsReachEveryPortViaTheMatrix()
	{
		int pandemonium = WorldPointUtil.packWorldPoint(3093, 2981, 0);
		java.util.List<gps.transport.Transport> legs =
			SailingSea.aboardLegTransports(pandemonium, java.util.Set.of());
		int disembarks = 0;
		gps.transport.Transport grimstone = null;
		int nearest = Integer.MAX_VALUE;
		for (gps.transport.Transport leg : legs)
		{
			String info = leg.getDisplayInfo();
			if (info != null && info.startsWith("Disembark at "))
			{
				disembarks++;
				nearest = Math.min(nearest, leg.getDuration());
				if (info.equals("Disembark at Grimstone"))
				{
					grimstone = leg;
				}
			}
		}
		org.junit.Assert.assertTrue("aboard legs must cover nearly every port, got " + disembarks,
			disembarks >= 50);
		org.junit.Assert.assertTrue("the far-north Grimstone berth must get a composed leg",
			grimstone != null);
		org.junit.Assert.assertTrue("composed duration must be sane (ticks): " + grimstone.getDuration(),
			grimstone.getDuration() > nearest && grimstone.getDuration() < 3000);
	}
}

package gps;

import gps.transport.Transport;
import gps.transport.TransportLoader;
import gps.transport.TransportType;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * An "Open ..." transport is a doorway only when it crosses between two neighbouring tiles on
 * one plane: doors and gates, which need no cue once open. "Open Trapdoor" is the transport
 * itself and keeps its ground label (capture gps-capture-20261003-163557: the Mourner HQ trapdoor
 * step was in the directions but its label never showed, because the overlay treated every
 * "Open" edge as a door and only labels doors while the closed object stands on the edge).
 */
public class DoorwayStepTest
{
	private static Transport first(String row)
	{
		Map<Integer, java.util.Set<Transport>> transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports,
			"# Origin\tDestination\tmenuOption menuTarget objectID\n" + row + "\n", TransportType.TRANSPORT, 0);
		return transports.values().iterator().next().iterator().next();
	}

	@Test
	public void aDoorBetweenNeighbouringTilesIsADoorway()
	{
		assertTrue(RouteDirections.isDoorway(first("3207 3214 0\t3207 3215 0\tOpen Door 1535")));
		assertTrue("a two-wide gate", RouteDirections.isDoorway(first("1918 4639 0\t1916 4639 0\tOpen Gate 10")));
	}

	@Test
	public void aTrapdoorOrLadderIsNot()
	{
		assertFalse("the Mourner HQ trapdoor leads to the tunnels",
			RouteDirections.isDoorway(first("2543 3327 0\t2044 4649 0\tOpen Trapdoor 8783")));
		assertFalse("a plane change is never a doorway",
			RouteDirections.isDoorway(first("3207 3214 0\t3207 3215 1\tOpen Trapdoor 1")));
		assertFalse("not an Open edge at all",
			RouteDirections.isDoorway(first("1905 4638 0\t1901 4638 1\tClimb-up Staircase 10015")));
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Plan step L23: the transports a rendered path edge rides, out of the plugin class. Local
 * transports from the current tile and anywhere-teleports landing on the next tile are the
 * candidates; a teleport sharing destinations with a local type on the edge is dropped, and so
 * is one within its shared type's radius (the path is walking to the landing); a same-plane
 * adjacent step hints no teleport at all.
 */
public class EdgeTransportsTest
{
	private static final int QUETZAL_STAND = WorldPointUtil.packWorldPoint(3200, 3200, 0);
	private static final int LANDING = WorldPointUtil.packWorldPoint(3400, 3400, 0);

	private static Transport transport(TransportType type, int origin, int destination)
	{
		Transport transport = mock(Transport.class);
		when(transport.getType()).thenReturn(type);
		when(transport.getOrigin()).thenReturn(origin);
		when(transport.getDestination()).thenReturn(destination);
		return transport;
	}

	private static PathStep at(int packed)
	{
		return new PathStep(packed, false);
	}

	private final Transport quetzal = transport(TransportType.QUETZAL, QUETZAL_STAND, LANDING);
	private final Transport whistle = transport(TransportType.QUETZAL_WHISTLE, Transport.UNDEFINED_ORIGIN, LANDING);
	private final Transport tablet = transport(TransportType.TELEPORTATION_ITEM, Transport.UNDEFINED_ORIGIN, LANDING);

	private PathfinderConfig config()
	{
		PrimitiveIntHashMap<Transport[]> byOrigin = new PrimitiveIntHashMap<>(16);
		byOrigin.put(QUETZAL_STAND, new Transport[]{quetzal});
		PathfinderConfig config = mock(PathfinderConfig.class);
		when(config.getTransportsPacked(anyBoolean())).thenReturn(byOrigin);
		when(config.getUsableTeleports(anyBoolean())).thenReturn(new Transport[]{whistle, tablet});
		return config;
	}

	@Test
	public void aLocalTransportSuppressesTheTeleportThatSharesItsDestinations()
	{
		assertEquals(Set.of(quetzal, tablet), EdgeTransports.forEdge(config(), at(QUETZAL_STAND), at(LANDING)));
	}

	@Test
	public void aFarJumpWithoutTheLocalTypeKeepsBothTeleports()
	{
		PathStep elsewhere = at(WorldPointUtil.packWorldPoint(3000, 3000, 0));
		assertEquals(Set.of(whistle, tablet), EdgeTransports.forEdge(config(), elsewhere, at(LANDING)));
	}

	@Test
	public void walkingToTheLandingWithinTheRadiusDropsTheSharedTeleport()
	{
		PathStep nearby = at(WorldPointUtil.packWorldPoint(3397, 3400, 0)); // 3 tiles: inside the quetzal radius of 5
		assertEquals(Set.of(tablet), EdgeTransports.forEdge(config(), nearby, at(LANDING)));
	}

	@Test
	public void anAdjacentStepHintsNoTeleport()
	{
		PathStep adjacent = at(WorldPointUtil.packWorldPoint(3399, 3400, 0));
		assertEquals(Set.of(), EdgeTransports.forEdge(config(), adjacent, at(LANDING)));
		assertEquals(Set.of(), EdgeTransports.forEdge(config(), null, at(LANDING)));
	}

	@Test
	public void theNextStep()
	{
		List<PathStep> path = List.of(at(QUETZAL_STAND), at(LANDING));
		assertSame(path.get(1), EdgeTransports.nextStep(path, 0));
		assertNull(EdgeTransports.nextStep(path, 1));
		assertNull(EdgeTransports.nextStep(path, -1));
		assertNull(EdgeTransports.nextStep(null, 0));
	}
}

