package gps;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import net.runelite.api.Client;
import org.junit.Test;
import org.mockito.Mockito;

/**
 * Scratch harness: renders the directions HUD's "Finding the best route" panel headlessly to a
 * PNG (GPS_HUD_DUMP=path) so its layout can be inspected without a client. Not a regression test.
 */
public class HudRenderDumpTest
{
	@Test
	public void dumpFindingPanel() throws Exception
	{
		if (System.getenv("GPS_HUD_DUMP") == null)
		{
			return;
		}
		ShortestPathPlugin plugin = Mockito.mock(ShortestPathPlugin.class, Mockito.withSettings().lenient());
		Mockito.when(plugin.isFindingRoute()).thenReturn(true);
		Mockito.when(plugin.getDisplayedRoute()).thenReturn(null);
		// The overlay reads its settings through the plugin's snapshot: the shipped defaults.
		Mockito.when(plugin.display()).thenReturn(OverlaySettings.from(new TestShortestPathConfig()));

		RouteDirectionsOverlay overlay = new RouteDirectionsOverlay(Mockito.mock(Client.class), plugin);
		// Plain, an ordinary destination line, and a bank trip that will resume a route.
		String[][] cases = {{"plain", null}, {"source", "Destination set by Slayer gear advisor"},
			{"detour", BankDetour.headerLine("nearest bank",
				BankDetour.Route.of(java.util.Set.of(1), "map pin", false, WorldPointUtil.UNDEFINED), false)}};
		for (String[] variant : cases)
		{
			Mockito.when(plugin.getDestinationLine()).thenReturn(variant[1]);
			Mockito.when(plugin.isBankDetour()).thenReturn("detour".equals(variant[0]));
			BufferedImage image = new BufferedImage(420, 160, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = image.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			// A game-like backdrop so the translucent panel reads as it does in the client.
			g.setColor(new Color(0x4A, 0x6B, 0x3A));
			g.fillRect(0, 0, image.getWidth(), image.getHeight());
			g.setFont(net.runelite.client.ui.FontManager.getRunescapeFont());
			g.translate(10, 10);
			// The panel component sizes itself from the previous frame: render twice, keep the second.
			overlay.render(g);
			g.setColor(new Color(0x4A, 0x6B, 0x3A));
			g.fillRect(-10, -10, image.getWidth(), image.getHeight());
			Dimension size = overlay.render(g);
			g.dispose();
			File out = new File(System.getenv("GPS_HUD_DUMP") + "-" + variant[0] + ".png");
			ImageIO.write(image, "png", out);
			System.out.println("wrote " + out.getAbsolutePath() + " panel=" + size
				+ " children=" + overlay.getPanelComponent().getChildren().size());
		}
	}
}

package gps;

import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;

/**
 * The hybrid band edge: in-band routes are always shown, and past the band the page keeps filling
 * while the next route's cost stays within a modest gap of the acceptance region — so a first page
 * never cuts a dense cost cluster in half (the 105-shown/107-hidden capture that motivated this),
 * while a genuine cost cliff still ends the page.
 */
@RunWith(MockitoJUnitRunner.class)
public class HybridPageFillTest
{
	@Test
	public void ceilingFollowsAClusterAcrossTheBandEdge()
	{
		// The user capture: best 27, band 105, next cluster starts at 107 — 2 past the band edge.
		assertTrue("107 must be accepted (cluster straddles the band edge)",
			107 <= RouteAcceptance.pageFillCeiling(27, 105, 3));
		// The Barrows shape: best 32, band 105, costliest accepted 86, next cluster at 106 — the gap
		// from the last route is 20, but from the band edge it is 1.
		assertTrue("106 must be accepted (cluster starts just past the band)",
			106 <= RouteAcceptance.pageFillCeiling(32, 86, 3));
		// A genuine cliff is still a stop.
		assertTrue("a far outlier must not be dragged onto the page",
			400 > RouteAcceptance.pageFillCeiling(27, 112, 3));
		// The ceiling ratchets with accepted fill routes, following a dense cluster.
		assertTrue("the ceiling must ratchet as fill routes are accepted",
			RouteAcceptance.pageFillCeiling(27, 134, 3)
				> RouteAcceptance.pageFillCeiling(27, 107, 3));
	}

	// --- End-to-end on the real map -----------------------------------------------------------

	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);

	private AlternativeRoutesService service;

	public static Object defaultValue(Class<?> t)
	{
		if (t == int.class || t == short.class || t == byte.class)
		{
			return 0;
		}
		if (t == long.class)
		{
			return 0L;
		}
		if (t == boolean.class)
		{
			return false;
		}
		if (t == double.class)
		{
			return 0.0;
		}
		if (t == float.class)
		{
			return 0f;
		}
		if (t == char.class)
		{
			return (char) 0;
		}
		return null;
	}

	@Before
	public void before()
	{
		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(ct, config);
	}

	@org.junit.After
	public void after()
	{
		service.shutdown();
	}

	/**
	 * Keldagrim station -> Giants' Foundry (user capture): the minigame teleport (46) is far cheaper
	 * than every alternative (157+), so the band/cliff gates alone produced a ONE-route page. The
	 * minimum page size must surface alternatives anyway, and none of them may ride the Keldagrim
	 * train to White Wolf Mountain and back as a "free" shortcut (the rides had no duration, so the
	 * search priced them at zero).
	 */
	@Test
	public void minimumPageSurvivesACheapBestRoute() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2927, 10165, 0),
			Set.of(WorldPointUtil.packWorldPoint(3361, 3149, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("a cheap best route must not collapse the page to one entry (got "
			+ routes.size() + ")", routes.size() >= 4);
		for (RouteOption route : routes)
		{
			long trainRides = route.getMethods().stream()
				.filter(m -> gps.transport.TransportType.MINECART.equals(m.getType())
					&& m.label().contains("White Wolf Mountain"))
				.count();
			assertTrue("no route may detour via the White Wolf Mountain train from Keldagrim",
				trainRides == 0);
		}
	}

	/**
	 * Locked in a sealed quest cell (user capture: start 3054,9841 is a ~76-tile pocket with no
	 * transports out) targeting a through-the-bars tile in the Port Sarim jail (3014,3194 — also
	 * sealed). The goal-rooted field floods only the target's pocket, so every finite-capped
	 * chain/seed search used to gate-prune its own start (h effectively infinite) and the page
	 * collapsed to ONE escape route. The degenerate-heuristic fallback must keep the chain alive:
	 * several closest-point routes with distinct escape methods, none of them "reached".
	 */
	@Test
	public void sealedTargetStillEnumeratesEscapeAlternatives() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(3054, 9841, 0),
			Set.of(WorldPointUtil.packWorldPoint(3014, 3194, 0),
				WorldPointUtil.packWorldPoint(3014, 3195, 0),
				WorldPointUtil.packWorldPoint(3015, 3195, 0)),
			Set.of(), AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("a sealed target must still get a menu of escape routes (got "
			+ routes.size() + ")", routes.size() >= 2);
		java.util.Set<String> firstMethods = new java.util.HashSet<>();
		for (RouteOption route : routes)
		{
			assertTrue("no route can actually reach a sealed target", !route.isReached());
			if (!route.getMethods().isEmpty())
			{
				firstMethods.add(route.getMethods().get(0).label());
			}
		}
		assertTrue("the escape routes must use distinct methods (got " + firstMethods + ")",
			firstMethods.size() >= 2);
	}

	/**
	 * Lumbridge -> Barrows in everything mode: four routes sit under the bare 105 band (32/32/86/86)
	 * and a straggler cluster sits just past its edge (118, 122) before a genuine cliff (the next
	 * route costs 176). The bare band cut mid-cluster and showed 4; the hybrid must show the whole
	 * cluster (6) and still stop at the cliff rather than dragging the 176+ outliers onto the page.
	 */
	@Test
	public void barrowsFirstPageCrossesTheBandEdgeAndStopsAtTheCliff() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(LUMBRIDGE, Set.of(BARROWS), Set.of(), AlternativeRoutesMode.ALL_EVERYTHING,
			10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("the page must fill past the bare band's 4 routes, got " + routes.size(),
			routes.size() > 4);
		int best = routes.get(0).getTotalCost();
		long band = 3L * Math.max(best, 35);
		int costliest = 0;
		for (RouteOption route : routes)
		{
			costliest = Math.max(costliest, route.getTotalCost());
			assertTrue("route cost " + route.getTotalCost() + " must stay under the sanity ceiling",
				route.getTotalCost() <= 2 * band);
		}
		assertTrue("fill must actually cross the band edge (costliest " + costliest + " vs band " + band + ")",
			costliest > band);
		assertTrue("the page must stop at the cliff: nothing at or past the next cluster (176+)",
			costliest < 176);
	}
}

package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.Assume;
import org.junit.Test;
import org.mockito.Mockito;

/** Issue probes (-Dgps.issueProbe=true): #21 Kharazi walkability, #15 Brittle Isle generation time. */
public class IssueProbesTest
{
	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	@Test
	public void kharaziWalkOnly()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(60);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		Pathfinder pathfinder = new Pathfinder(config,
			WorldPointUtil.packWorldPoint(2825, 2997, 0),
			Set.of(WorldPointUtil.packWorldPoint(2950, 2902, 0)));
		pathfinder.run();
		List<gps.pathfinder.PathStep> path = pathfinder.getPath();
		int transports = 0;
		for (int i = 1; i < path.size(); i++)
		{
			if (WorldPointUtil.distanceBetween(path.get(i - 1).getPackedPosition(),
				path.get(i).getPackedPosition()) > 1)
			{
				transports++;
			}
		}
		System.out.println("PROBE #21 kharazi reached=" + pathfinder.getResult().isReached()
			+ " steps=" + path.size() + " jumps(transports)=" + transports);
	}

	@Test
	public void kharaziInteriorWalkOnly()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(60);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		// Issue 21's second snapshot: 2925,2944 -> 2950,2902 came back as a 95-cost WALK with no methods.
		Pathfinder pathfinder = new Pathfinder(config,
			WorldPointUtil.packWorldPoint(2925, 2944, 0),
			Set.of(WorldPointUtil.packWorldPoint(2950, 2902, 0)));
		pathfinder.run();
		List<gps.pathfinder.PathStep> path = pathfinder.getPath();
		int jumps = 0;
		StringBuilder jumpAt = new StringBuilder();
		for (int i = 1; i < path.size(); i++)
		{
			int a = path.get(i - 1).getPackedPosition();
			int b = path.get(i).getPackedPosition();
			if (WorldPointUtil.distanceBetween(a, b) > 1)
			{
				jumps++;
				jumpAt.append(' ').append(WorldPointUtil.unpackWorldX(a)).append(',').append(WorldPointUtil.unpackWorldY(a));
			}
		}
		System.out.println("PROBE #21b interior reached=" + pathfinder.getResult().isReached()
			+ " steps=" + path.size() + " jumps=" + jumps + jumpAt);
	}

	/** Collision-only BFS (no transports at all): can the interior be WALKED? */
	@Test
	public void kharaziInteriorCollisionOnly()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(60);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		gps.pathfinder.CollisionMap map = config.getMap();
		int start = WorldPointUtil.packWorldPoint(2925, 2944, 0);
		int goal = WorldPointUtil.packWorldPoint(2950, 2902, 0);
		java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
		java.util.HashSet<Integer> seen = new java.util.HashSet<>();
		queue.add(start);
		seen.add(start);
		boolean reached = false;
		while (!queue.isEmpty() && seen.size() < 200000)
		{
			int at = queue.poll();
			if (at == goal)
			{
				reached = true;
				break;
			}
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, 0);
					if ((dx != 0 || dy != 0) && map.canStep(at, next) && seen.add(next))
					{
						queue.add(next);
					}
				}
			}
		}
		System.out.println("PROBE #21c collision-only walk reached=" + reached + " flooded=" + seen.size());
	}

	@Test
	public void brittleIsleGenerationTime() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.useSailing()).thenReturn(true);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, config);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		long start = System.nanoTime();
		service.generate(WorldPointUtil.packWorldPoint(2936, 3281, 0),
			Set.of(WorldPointUtil.packWorldPoint(1947, 4067, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		boolean finished = latch.await(180, TimeUnit.SECONDS);
		long ms = (System.nanoTime() - start) / 1_000_000;
		System.out.println("PROBE #15 brittle isle finished=" + finished + " in " + ms + " ms, routes="
			+ (out.get() == null ? -1 : out.get().size())
			+ (out.get() != null && !out.get().isEmpty() ? " best=" + out.get().get(0).getTotalCost() + " " + out.get().get(0).getMethods() : ""));
		service.shutdown();
	}
}

package gps;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
