package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.PathStep;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The Mysterious pipe (88 Agility, id 34655) shortcuts the Karuulm Slayer Dungeon's hydra
 * chamber straight to the Alchemical Hydra corridor. The Agility plugin knew it; GPS data
 * didn't. Standing/landing tiles are cache-derived (~geometry): the pipe object tiles
 * (1316,10214) and (1346,10231) are blocked, so the rows use their open-side neighbours.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class KaruulmPipeTest
{
	private static final int NEAR_HYDRA = WorldPointUtil.packWorldPoint(1346, 10232, 0);
	private static final int NEAR_HALL = WorldPointUtil.packWorldPoint(1315, 10214, 0);

	@Mock
	Client client;
	private final TestShortestPathConfig config = new TestShortestPathConfig();

	/**
	 * The LIVE config (not copyForPlanning) — planning mode bypasses per-player unlock gates,
	 * skill levels included, which would defeat the 88 Agility assertions.
	 */
	private PathfinderConfig liveAt(int agilityLevel)
	{
		config.setCalculationCutoffValue(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(agilityLevel);
		PathfinderConfig live = new TestPathfinderConfig(client, config);
		live.refresh();
		return live;
	}

	private static boolean usesPipe(List<PathStep> steps, int from, int to)
	{
		for (int i = 0; i + 1 < steps.size(); i++)
		{
			if (steps.get(i).getPackedPosition() == from
				&& steps.get(i + 1).getPackedPosition() == to)
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void with88AgilityThePipeCarriesBothDirections()
	{
		PathfinderConfig planning = liveAt(99);
		Pathfinder toHall = new Pathfinder(planning, NEAR_HYDRA, Set.of(NEAR_HALL));
		toHall.run();
		assertTrue(toHall.getResult().isReached());
		assertTrue("hydra-side to hall must squeeze through the pipe",
			usesPipe(toHall.getResult().getPathSteps(), NEAR_HYDRA, NEAR_HALL));

		Pathfinder toHydra = new Pathfinder(planning, NEAR_HALL, Set.of(NEAR_HYDRA));
		toHydra.run();
		assertTrue(toHydra.getResult().isReached());
		assertTrue("hall to hydra-side must squeeze through the pipe",
			usesPipe(toHydra.getResult().getPathSteps(), NEAR_HALL, NEAR_HYDRA));
	}

	@Test
	public void below88AgilityThePipeIsClosed()
	{
		PathfinderConfig planning = liveAt(87);
		Pathfinder toHall = new Pathfinder(planning, NEAR_HYDRA, Set.of(NEAR_HALL));
		toHall.run();
		assertFalse("at 87 Agility the pipe edge must not be taken",
			usesPipe(toHall.getResult().getPathSteps(), NEAR_HYDRA, NEAR_HALL));
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.when;

/**
 * Dev probe (-DkebosMineProbe=true) for gps-capture-20260724-180802: route from the Kebos
 * Lowlands shore (1235,3656) to the mine cave (1211,3648) walked 66 tiles through the south
 * instead of cutting west. Prints the pathfinder's path, an edge-aware BFS distance (fences
 * are EDGE flags, invisible to tile-walkability grids), and where the direct corridor is
 * actually severed.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class KebosMineProbeTest
{
	private static final int START = WorldPointUtil.packWorldPoint(1235, 3656, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(1211, 3648, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void probe()
	{
		Assume.assumeTrue(Boolean.getBoolean("kebosMineProbe"));
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		CollisionMap map = planning.getMap();

		Pathfinder pathfinder = new Pathfinder(planning, START, Set.of(TARGET));
		pathfinder.run();
		System.out.println("pathfinder cost=" + pathfinder.getResult().getTotalCost()
			+ " steps=" + pathfinder.getResult().getPathSteps().size());

		// Edge-aware BFS over the local box: the true walk distance with fences honoured.
		Map<Integer, Integer> dist = new HashMap<>();
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		dist.put(START, 0);
		queue.add(START);
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int nx = x + dx;
					int ny = y + dy;
					if (nx < 1195 || nx > 1245 || ny < 3620 || ny > 3665)
					{
						continue;
					}
					int next = WorldPointUtil.packWorldPoint(nx, ny, 0);
					if (dist.containsKey(next) || !map.canStep(at, next))
					{
						continue;
					}
					dist.put(next, dist.get(at) + 1);
					queue.add(next);
				}
			}
		}
		System.out.println("edge-aware BFS distance to target: " + dist.getOrDefault(TARGET, -1));

		// The BFS wavefront as a grid: distance mod 10 per tile ('#' unreachable-or-blocked).
		// The frontier between low numbers (near start) and high/blank shows the barrier shape.
		System.out.println("     " + "0123456789".repeat(5).substring(0, 1245 - 1198 + 1));
		for (int y = 3660; y >= 3628; y--)
		{
			StringBuilder line = new StringBuilder(y + " ");
			for (int x = 1198; x <= 1245; x++)
			{
				Integer distance = dist.get(WorldPointUtil.packWorldPoint(x, y, 0));
				line.append(distance == null ? '#' : (char) ('0' + distance % 10));
			}
			System.out.println(line);
		}
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N10. KeepSailingTest failed intermittently: at the helm the pure-sail route is the
 * walk search's own result, appended last as the baseline, and the seed pass filled the page in
 * COMPLETION order. When ten cheaper port-then-teleport routes had already been accepted, the
 * append loop evicted the costliest unprotected route, which was the sail baseline itself (every
 * route is port-first, so the sole-port-first protection never applied). Completion order varies
 * with JIT and load, so the page sometimes filled before the baseline landed. The baseline just
 * appended is never the one evicted, and seed results are accepted in a deterministic order.
 */
@RunWith(MockitoJUnitRunner.class)
public class KeepSailingBaselineTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;
	@Mock
	ClientThread clientThread;

	private static final int HELM = WorldPointUtil.packWorldPoint(2746, 3216, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(2638, 3009, 0);

	@Test
	public void theSailBaselineSurvivesAFullPageAndThePageIsDeterministic() throws Exception
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		lenient().when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		lenient().when(client.getVarbitValue(VarbitID.SAILING_BOARDED_BOAT)).thenReturn(1);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		assertTrue("the harness must be at the helm", planning.isOnSailingBoat());
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);
		List<String> pages = new ArrayList<>();
		try
		{
			// A limit of nine: more than nine cheaper port-then-teleport routes exist, so the
			// page is full before the sail baseline is appended, every time.
			for (int run = 1; run <= 3; run++)
			{
				List<RouteOption> routes = generate(service, 9);
				assertTrue("run " + run + ": a pure-sail route must survive a full page at the helm:" + describe(routes),
					routes.stream().anyMatch(r -> r.isPureSail() && r.isReached()));
				assertTrue("run " + run + ": the limit holds", routes.size() <= 9);
				pages.add(describe(routes));
			}
		}
		finally
		{
			service.shutdown();
		}
		assertEquals("the same query must produce the same page every time", pages.get(0), pages.get(1));
		assertEquals("the same query must produce the same page every time", pages.get(0), pages.get(2));
	}

	private static List<RouteOption> generate(AlternativeRoutesService service, int limit) throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(HELM, Set.of(TARGET), Set.of(), AlternativeRoutesMode.ALL_EVERYTHING, limit, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		assertTrue("routes expected", out.get() != null && !out.get().isEmpty());
		return out.get();
	}

	private static String describe(List<RouteOption> routes)
	{
		StringBuilder sb = new StringBuilder();
		for (RouteOption r : routes)
		{
			sb.append("\n  cost ").append(r.getTotalCost()).append(' ').append(r.getMethods());
		}
		return sb.toString();
	}
}

