/**
 * Plan step L22: the map menu, out of the plugin class. A world-map icon's menu target becomes
 * the destination key the transport data uses: colour tags stripped, lower case, letters and
 * spaces only, words joined by single underscores. The directions overlay gets its own entry on a
 * plain right-click: "Clear Path" while a route is up, "Dismiss Arrival" while the "Arrived!"
 * panel lingers, nothing when the mouse is off the panel or the panel is hidden.
 */
public class MapMenuTest
{
	@Test
	public void iconTargetsBecomeDestinationKeys()
	{
		assertEquals("grand_exchange", MapMenu.simplify("<col=ff9040>Grand Exchange</col>"));
		assertEquals("slayer_master_konar", MapMenu.simplify("Slayer Master (Konar)"));
		assertEquals("fairy_ring", MapMenu.simplify("Fairy ring"));
	}

	/** A client whose right-click menu is empty and whose mouse sits at (10, 10), with a fresh entry to fill. */
	private static Client clientWithMenu(MenuEntry created)
	{
		Client client = mock(Client.class);
		Menu menu = mock(Menu.class);
		when(client.getMenu()).thenReturn(menu);
		when(client.getMouseCanvasPosition()).thenReturn(new Point(10, 10));
		when(menu.getMenuEntries()).thenReturn(new MenuEntry[0]);
		when(menu.createMenuEntry(Mockito.anyInt())).thenReturn(created);
		return client;
	}

	private static MenuEntry fluentEntry()
	{
		return mock(MenuEntry.class, Mockito.RETURNS_SELF);
	}

	/** The directions overlay as drawn at (0, 0) with the given size, arrived or not. */
	private static ShortestPathPlugin pluginShowing(int width, int height, boolean arrived, boolean hasTargets)
	{
		ShortestPathPlugin plugin = mock(ShortestPathPlugin.class);
		RouteDirectionsOverlay overlay = mock(RouteDirectionsOverlay.class);
		when(overlay.getBounds()).thenReturn(new Rectangle(0, 0, width, height));
		when(overlay.isArrivalShowing()).thenReturn(arrived);
		when(plugin.routeDirectionsOverlay()).thenReturn(overlay);
		when(plugin.hasPathTargets()).thenReturn(hasTargets);
		return plugin;
	}

	@Test
	public void aRightClickOnTheDirectionsOverlayOffersClearPath()
	{
		MenuEntry created = fluentEntry();
		MapMenu menu = new MapMenu(clientWithMenu(created), null, null, pluginShowing(200, 100, false, true));
		menu.addDirectionsEntry(mock(MenuEntryAdded.class));
		verify(created).setOption(MapMenu.CLEAR);
		verify(created).setTarget(MapMenu.PATH);
		verify(created).setType(MenuAction.RUNELITE);
	}

	@Test
	public void aRightClickOnTheArrivedPanelOffersDismiss()
	{
		MenuEntry created = fluentEntry();
		MapMenu menu = new MapMenu(clientWithMenu(created), null, null, pluginShowing(200, 100, true, false));
		menu.addDirectionsEntry(mock(MenuEntryAdded.class));
		verify(created).setOption(MapMenu.DISMISS);
		verify(created).setTarget(MapMenu.ARRIVAL);
	}

	@Test
	public void noEntryOffThePanelOrWhenNothingIsShown()
	{
		MenuEntry created = fluentEntry();
		Client client = clientWithMenu(created);
		// The mouse at (10, 10) is outside a panel drawn 5 pixels wide.
		new MapMenu(client, null, null, pluginShowing(5, 5, false, true)).addDirectionsEntry(mock(MenuEntryAdded.class));
		// No route and no arrival: nothing to clear or dismiss.
		new MapMenu(client, null, null, pluginShowing(200, 100, false, false)).addDirectionsEntry(mock(MenuEntryAdded.class));
		verify(client.getMenu(), never()).createMenuEntry(Mockito.anyInt());
	}
}

package gps;

import gps.transport.TransportType;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Panel series P3: the method catalog's rules, out of the panel class. Teleport items group by
 * charge model and every other method by its category; a banked item is usable only in the
 * Inventory + bank mode; the funnel filter keeps excluded methods or one unavailability kind,
 * and the text filter matches the category or the label, case-insensitively.
 */
public class MethodCatalogViewTest
{
	private static final TeleportMethod TABLET = new TeleportMethod(TransportType.TELEPORTATION_ITEM,
		"Varrock tablet", WorldPointUtil.packWorldPoint(3212, 3424, 0));
	private static final TeleportMethod RING = new TeleportMethod(TransportType.FAIRY_RING,
		"BKR", WorldPointUtil.packWorldPoint(3469, 3431, 0));

	@Test
	public void teleportItemsGroupByChargeModelAndTheRestByCategory()
	{
		assertEquals(RING.category(), MethodCatalogView.groupKey(RING));
		String key = MethodCatalogView.groupKey(TABLET);
		assertEquals(TABLET.isConsumable() ? "Items (charged)" : "Items (permanent)", key);
	}

	@Test
	public void aBankedItemIsUsableOnlyInTheBankMode()
	{
		assertTrue(MethodCatalogView.usable(null, AlternativeRoutesMode.OWNED_INVENTORY));
		assertTrue(MethodCatalogView.usable(MethodAvailability.IN_BANK, AlternativeRoutesMode.OWNED_WITH_BANK));
		assertFalse(MethodCatalogView.usable(MethodAvailability.IN_BANK, AlternativeRoutesMode.OWNED_INVENTORY));
		assertFalse(MethodCatalogView.usable(MethodAvailability.MISSING_LEVEL, AlternativeRoutesMode.OWNED_WITH_BANK));
	}

	@Test
	public void theFunnelAndTextFiltersNarrowTheRows()
	{
		Set<TeleportMethod> excluded = Set.of(RING);
		Map<TeleportMethod, MethodAvailability> unavailable = Map.of(TABLET, MethodAvailability.IN_BANK);

		assertTrue(MethodCatalogView.matches(TABLET, MethodCatalogView.Filter.ALL, "", excluded, unavailable));
		assertTrue("the disabled filter keeps excluded methods",
			MethodCatalogView.matches(RING, MethodCatalogView.Filter.DISABLED, "", excluded, unavailable));
		assertFalse(MethodCatalogView.matches(TABLET, MethodCatalogView.Filter.DISABLED, "", excluded, unavailable));
		assertTrue("an availability filter keeps that kind",
			MethodCatalogView.matches(TABLET, MethodCatalogView.Filter.IN_BANK, "", excluded, unavailable));
		assertFalse(MethodCatalogView.matches(RING, MethodCatalogView.Filter.IN_BANK, "", excluded, unavailable));

		assertTrue("the text matches the label, case-insensitively",
			MethodCatalogView.matches(TABLET, MethodCatalogView.Filter.ALL, "VARROCK", excluded, unavailable));
		assertTrue("or the category",
			MethodCatalogView.matches(RING, MethodCatalogView.Filter.ALL, RING.category().toLowerCase(), excluded, unavailable));
		assertFalse(MethodCatalogView.matches(RING, MethodCatalogView.Filter.ALL, "varrock", excluded, unavailable));
	}

	@Test
	public void everyUnavailabilityKindHasAReason()
	{
		for (MethodAvailability status : MethodAvailability.values())
		{
			assertFalse(status.name(), PanelWidgets.statusReason(status).isEmpty());
		}
	}
}

package gps;

import com.google.gson.Gson;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * Plan step L26: the excluded methods, out of the plugin class. Every real change persists once
 * and notifies once; a no-op change (excluding an excluded method, clearing an empty set) does
 * neither; the route list is stale after a change until a generation marks the set as used.
 */
@RunWith(MockitoJUnitRunner.class)
public class MethodExclusionsTest
{
	@Mock
	ConfigManager configManager;

	private final AtomicInteger changes = new AtomicInteger();
	private final TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Varrock tablet", 1);
	private final TeleportMethod fairy = new TeleportMethod(TransportType.FAIRY_RING, "BKR", 2);

	private MethodExclusions exclusions()
	{
		return new MethodExclusions(new ChoiceStore(() -> configManager, Gson::new, "gps"), changes::incrementAndGet);
	}

	private void verifySaves(int count)
	{
		verify(configManager, times(count)).setConfiguration(eq("gps"), eq(ChoiceStore.CONFIG_KEY_EXCLUSIONS), anyString());
	}

	@Test
	public void changesPersistAndNotifyOnceEach()
	{
		MethodExclusions exclusions = exclusions();
		exclusions.exclude(tab);
		exclusions.exclude(tab);
		assertTrue(exclusions.contains(tab));
		assertEquals(1, changes.get());
		verifySaves(1);

		exclusions.excludeAll(List.of(tab, fairy));
		assertEquals(Set.of(tab, fairy), exclusions.copy());
		assertEquals(2, changes.get());

		exclusions.includeAll(List.of(fairy));
		exclusions.include(fairy);
		assertEquals(Set.of(tab), exclusions.copy());
		assertEquals(3, changes.get());

		exclusions.clear();
		exclusions.clear();
		assertTrue(exclusions.isEmpty());
		assertEquals(4, changes.get());
		verifySaves(4);
	}

	@Test
	public void theListIsStaleAfterAChangeUntilAGenerationUsesTheSet()
	{
		MethodExclusions exclusions = exclusions();
		assertFalse("nothing excluded, nothing generated: fresh", exclusions.isStale());
		exclusions.exclude(tab);
		assertTrue(exclusions.isStale());
		exclusions.markGenerated();
		assertFalse(exclusions.isStale());
		exclusions.include(tab);
		assertTrue(exclusions.isStale());
	}
}

