 * (prepended), so the points run down the left side and back up the right, offset to where the
 * minimap widget sits on screen.
 */
public class MinimapClipTest
{
	@Test
	public void maskRowsBecomeAClosedOutline()
	{
		// A 4x4 mask with the outside colour at the corner and an opaque 2x2 block in the middle.
		BufferedImage mask = new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
		for (int y = 1; y <= 2; y++)
		{
			for (int x = 1; x <= 2; x++)
			{
				mask.setRGB(x, y, 0xFFFFFFFF);
			}
		}
		Polygon outline = MinimapClip.polygonOf(mask, 10, 20);
		assertEquals(4, outline.npoints);
		assertArrayEquals(new int[]{13, 13, 11, 11}, java.util.Arrays.copyOf(outline.xpoints, 4));
		assertArrayEquals(new int[]{22, 21, 21, 22}, java.util.Arrays.copyOf(outline.ypoints, 4));
		assertTrue(outline.contains(12, 21.5));
		assertFalse(outline.contains(10.5, 21.5));
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N1. A "nearest bank" query hands the generator a target set spanning the whole
 * map; DistanceField.buildIfCompact refused to build a field for anything wider than 256 tiles,
 * so every search of the generation ran blind: the cost cap degenerates to a plain g-ball and
 * each search floods everything inside it (the review measured ~1M nodes and ~400 ms per blind
 * search against ~1 ms guided). The field is built once per generation and bounds its own flood,
 * so a wide target set must get one too.
 */
@RunWith(MockitoJUnitRunner.class)
public class MultiTargetFieldTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;
	@Mock
	ClientThread clientThread;

	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);

	private static final int FELDIP_HILLS = WorldPointUtil.packWorldPoint(2500, 2960, 0);

	@Test
	public void nearestBankGenerationRunsGuided() throws Exception
	{
		runNearestBank(LUMBRIDGE, TeleportationItem.ALL, AlternativeRoutesMode.ALL_EVERYTHING);
	}

	/** The expensive shape: the nearest bank is far, and every blind search floods to the cap. */
	@Test
	public void farNearestBankRunsGuidedToo() throws Exception
	{
		runNearestBank(FELDIP_HILLS, TeleportationItem.NONE, AlternativeRoutesMode.OWNED_INVENTORY);
	}

	private void runNearestBank(int start, TeleportationItem items, AlternativeRoutesMode mode) throws Exception
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(items);
		lenient().when(config.useSpiritTrees()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		Set<Integer> banks = planning.getDestinations("bank");
		assertTrue("premise: the bank set spans the map", banks.size() > 100);

		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(start, banks, Set.of(), mode, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(180, TimeUnit.SECONDS));
		List<AlternativeRoutesService.SearchRecord> records = service.getLastSearchRecords();
		service.shutdown();

		assertTrue("routes expected", out.get() != null && !out.get().isEmpty());
		assertTrue("searches expected", !records.isEmpty());
		int guided = 0;
		int worstNodes = 0;
		long totalNodes = 0;
		StringBuilder blind = new StringBuilder();
		for (AlternativeRoutesService.SearchRecord record : records)
		{
			if (record.astar)
			{
				guided++;
			}
			else
			{
				blind.append("\n  ").append(record.label).append(" nodes=").append(record.nodesChecked);
			}
			worstNodes = Math.max(worstNodes, record.nodesChecked);
			totalNodes += record.nodesChecked;
		}
		assertTrue("at least 90% of a nearest-bank generation's searches must be field-guided, blind ones:"
			+ blind, guided * 10 >= records.size() * 9);
		assertTrue("no single search may flood the map (worst " + worstNodes + " nodes)", worstNodes < 500_000);
		assertTrue("the whole generation must stay under 2M nodes (was ~1M per search): " + totalNodes,
			totalNodes < 2_000_000);
		System.out.println("MULTITARGET " + WorldPointUtil.unpackWorldPoint(start) + " searches=" + records.size()
			+ " guided=" + guided + " worstNodes=" + worstNodes + " totalNodes=" + totalNodes);
	}
}

package gps;

import java.awt.event.KeyEvent;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.JPanel;
import net.runelite.client.config.Keybind;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Keybinds for the panel's "nearest bank" and "nearest bank and back" quick buttons (a player
 * suggestion), unset by default; a bound key runs the same action as its button.
 */
public class NearestBankHotkeysTest
{
	/**
	 * A key press as the toolkit delivers it: Keybind matches on the EXTENDED key code, which the
	 * native layer fills in and a hand-built event leaves at zero, so it is mirrored from the code.
	 */
	private static KeyEvent press(int keyCode, int modifiers)
	{
		return new KeyEvent(new JPanel(), KeyEvent.KEY_PRESSED, 0L, modifiers, keyCode, KeyEvent.CHAR_UNDEFINED)
		{
			@Override
			public int getExtendedKeyCode()
			{
				return getKeyCode();
			}
		};
	}

	@Test
	public void bothDefaultToNotSet()
	{
		TestShortestPathConfig config = new TestShortestPathConfig();
		assertEquals(Keybind.NOT_SET, config.nearestBankHotkey());
		assertEquals(Keybind.NOT_SET, config.nearestBankAndBackHotkey());
	}

	@Test
	public void eachHotkeyFiresOnItsOwnBindingOnly()
	{
		AtomicInteger oneWay = new AtomicInteger();
		AtomicInteger andBack = new AtomicInteger();
		NearestBankHotkeys hotkeys = new NearestBankHotkeys(
			() -> new Keybind(KeyEvent.VK_B, KeyEvent.CTRL_DOWN_MASK), oneWay::incrementAndGet,
			() -> new Keybind(KeyEvent.VK_B, KeyEvent.CTRL_DOWN_MASK | KeyEvent.SHIFT_DOWN_MASK), andBack::incrementAndGet);

		hotkeys.bank().keyPressed(press(KeyEvent.VK_B, KeyEvent.CTRL_DOWN_MASK));
		hotkeys.bank().keyPressed(press(KeyEvent.VK_B, 0));
		hotkeys.bankAndBack().keyPressed(press(KeyEvent.VK_B, KeyEvent.CTRL_DOWN_MASK));
		hotkeys.bankAndBack().keyPressed(press(KeyEvent.VK_B, KeyEvent.CTRL_DOWN_MASK | KeyEvent.SHIFT_DOWN_MASK));
		assertEquals(1, oneWay.get());
		assertEquals("only the shifted press matches", 1, andBack.get());
	}

	@Test
	public void unboundKeysNeverFire()
	{
		AtomicInteger fired = new AtomicInteger();
		TestShortestPathConfig config = new TestShortestPathConfig();
		NearestBankHotkeys hotkeys = new NearestBankHotkeys(
			config::nearestBankHotkey, fired::incrementAndGet, config::nearestBankAndBackHotkey, fired::incrementAndGet);

		for (int key : new int[]{KeyEvent.VK_B, KeyEvent.VK_ENTER, KeyEvent.VK_UNDEFINED})
		{
			hotkeys.bank().keyPressed(press(key, 0));
			hotkeys.bankAndBack().keyPressed(press(key, KeyEvent.CTRL_DOWN_MASK));
		}
		assertEquals(0, fired.get());
	}
}

package gps;

import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.client.callback.ClientThread;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;

/**
 * Reproduces the benchmark's "Nearest anvil from Varrock" scenario and prints the per-search
 * profile records — the diagnostic view for WHERE a multi-target generation's time goes (the
 * aggregate timing can't tell a few expensive searches from many cheap ones). Also guards the
 * records plumbing itself: every search of a generation must produce a record.
 */
@RunWith(MockitoJUnitRunner.class)
public class NearestSearchProfileTest
{
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3428, 0);

	@Mock
	Client client;
	@Mock
	ClientThread clientThread;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(invocation -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));
	}

	@Test
	public void nearestAnvilGenerationProfilesEverySearch() throws Exception
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		Set<Integer> anvils = Destinations.tilesForCategory("anvil", null);
		assertFalse("Anvil destinations must load from the bundled resource", anvils.isEmpty());

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		long wallStart = System.nanoTime();
		service.generate(VARROCK, anvils, Set.of(), AlternativeRoutesMode.ALL_EVERYTHING, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		long wallMs = (System.nanoTime() - wallStart) / 1_000_000;
		service.shutdown();

		List<AlternativeRoutesService.SearchRecord> records = service.getLastSearchRecords();
		long[] timing = service.getLastTimingSummary();
		System.out.println("=== Nearest anvil from Varrock: " + finalRoutes.get().size() + " routes, wall "
			+ wallMs + "ms, searchCpu " + timing[3] + "ms, " + timing[4] + " searches ===");
		System.out.printf("%-52s %7s %6s %8s %9s %11s %7s%n",
			"search", "cpuMs", "cost", "reached", "nodes", "transports", "capped");
		for (AlternativeRoutesService.SearchRecord r : records)
		{
			System.out.printf("%-52s %7d %6d %8s %9d %11d %7s  %s%n",
				r.label.length() > 52 ? r.label.substring(0, 52) : r.label,
				r.cpuMs, r.resultCost, r.reached, r.nodesChecked, r.transportsChecked, r.capped, r.termination);
		}

		assertFalse("Every search must produce a profile record", records.isEmpty());
		assertTrue("Record count must match the search count (" + records.size() + " vs " + timing[4] + ")",
			records.size() == timing[4]);

		// Regression guards for the perimeter-target fix: amenity destinations are object tiles that
		// aren't walkable — targeting only them meant NO search ever "reached", every search flooded
		// the entire map (~1.3M nodes), and the walk-cost cap never engaged. With the walkable
		// perimeter in the target set the searches must reach and stay bounded.
		assertTrue("The best route must actually reach a target",
			finalRoutes.get().stream().anyMatch(RouteOption::isReached));
		assertTrue("The walk search must reach the nearest anvil (it defines the cost cap)",
			records.stream().filter(r -> "walk".equals(r.label)).allMatch(r -> r.reached));
		assertTrue("Seed searches must run under the walk-cost cap",
			records.stream().filter(r -> r.label.startsWith("seed:")).allMatch(r -> r.capped));
		for (AlternativeRoutesService.SearchRecord r : records)
		{
			assertTrue("Search '" + r.label + "' explored " + r.nodesChecked
					+ " nodes — full-map flooding is back (fix regressed)",
				r.nodesChecked < 500_000);
		}
	}
}

package gps;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
