package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N5: the planning refresh runs on the client thread once per generation. A sampling
 * probe (RefreshProfileProbeTest) showed 63% of it re-reading the per-type travel toggles through
 * the live config interface for every one of the ~14,000 rows (a ConfigManager lookup each in the
 * client), and a direct varbit read on the classification's fairy ring branch. The toggles are
 * read once per refresh, the varbit through the per-pass memo, and item names through a cache that
 * survives refreshes (names never change), so the pass reads the config a bounded number of times.
 */
@RunWith(MockitoJUnitRunner.class)
public class PlanningRefreshCostTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	/** Config reads one planning refresh may make: every key once, with a margin for overrides. */
	static final int CONFIG_READS_BUDGET = 120;
	/** Client reads one planning refresh may make: quests, varbits, skills, containers, item names. */
	static final int CLIENT_READS_BUDGET = 1200;

	@Test
	public void planningRefreshReadsTheConfigOncePerKey()
	{
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		lenient().when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		lenient().when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		planning.refresh();

		int configBefore = Mockito.mockingDetails(config).getInvocations().size();
		int clientBefore = Mockito.mockingDetails(client).getInvocations().size();
		long[] samples = new long[8];
		for (int i = 0; i < samples.length; i++)
		{
			long start = System.nanoTime();
			planning.refresh();
			samples[i] = (System.nanoTime() - start) / 1_000_000;
		}
		int configReads = (Mockito.mockingDetails(config).getInvocations().size() - configBefore) / samples.length;
		int clientReads = (Mockito.mockingDetails(client).getInvocations().size() - clientBefore) / samples.length;
		Arrays.sort(samples);
		System.out.println("PLANNINGREFRESH config reads per refresh: " + configReads + ", client reads: " + clientReads
			+ ", ms: " + Arrays.toString(samples));

		assertTrue("a planning refresh read the config " + configReads + " times (budget " + CONFIG_READS_BUDGET + ")",
			configReads <= CONFIG_READS_BUDGET);
		assertTrue("a planning refresh read the client " + clientReads + " times (budget " + CLIENT_READS_BUDGET + ")",
			clientReads <= CLIENT_READS_BUDGET);
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import java.util.function.BiFunction;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Plan step L18: the house exit label, out of the plugin class. For a destination inside the
 * house, the transport on the first inside-to-outside edge after the current index names the
 * exit by what it is; a destination outside, a path that walks out, or an edge without a
 * transport yields nothing.
 */
public class PlayerOwnedHouseTest
{
	private static final PathStep IN_A = new PathStep(WorldPointUtil.packWorldPoint(1900, 5700, 0), false);
	private static final PathStep IN_B = new PathStep(WorldPointUtil.packWorldPoint(1901, 5700, 0), false);
	private static final PathStep OUT = new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), false);
	private static final List<PathStep> PATH = List.of(IN_A, IN_B, OUT);

	private static Transport transport(TransportType type, String displayInfo, String objectInfo)
	{
		Transport transport = mock(Transport.class);
		when(transport.getType()).thenReturn(type);
		when(transport.getDisplayInfo()).thenReturn(displayInfo);
		when(transport.getObjectInfo()).thenReturn(objectInfo);
		return transport;
	}

	private static BiFunction<PathStep, PathStep, Set<Transport>> exitEdge(Transport transport)
	{
		return (from, to) -> from == IN_B && to == OUT ? Set.of(transport) : Set.of();
	}

	@Test
	public void theExitIsNamedByWhatItIs()
	{
		int destination = IN_A.getPackedPosition();
		assertEquals("Fairy Ring BKR", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.FAIRY_RING, "BKR", null))));
		assertEquals("Mounted Glory: Edgeville", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.TELEPORTATION_BOX, "Edgeville", "Rub Amulet of Glory 12345"))));
		assertEquals("Jewelry Box: Duel Arena", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.TELEPORTATION_BOX, "Duel Arena", "Teleport Jewellery Box 1"))));
		assertEquals("Nexus: Varrock", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.TELEPORTATION_PORTAL_POH, "Varrock", null))));
		assertEquals("Spirit Tree: Tree Gnome Village", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.SPIRIT_TREE, "Tree Gnome Village", null))));
		assertEquals("Obelisk: Level 13", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.WILDERNESS_OBELISK, "Level 13", null))));
		assertEquals("a plain transport keeps its own label", "Portal", PlayerOwnedHouse.exitInfo(destination, PATH, 0,
			exitEdge(transport(TransportType.TRANSPORT, "Portal", null))));
	}

	@Test
	public void nothingOutsideOrWithoutATransport()
	{
		Transport fairy = transport(TransportType.FAIRY_RING, "BKR", null);
		assertNull("destination outside the house", PlayerOwnedHouse.exitInfo(OUT.getPackedPosition(), PATH, 0, exitEdge(fairy)));
		assertNull("no transport on the exit edge", PlayerOwnedHouse.exitInfo(IN_A.getPackedPosition(), PATH, 0, (a, b) -> Set.of()));
		assertNull("already past the exit", PlayerOwnedHouse.exitInfo(IN_A.getPackedPosition(), PATH, 1, exitEdge(fairy)));
		assertNull(PlayerOwnedHouse.exitInfo(IN_A.getPackedPosition(), null, 0, exitEdge(fairy)));
	}
}

package gps;

import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.JPanel;
import net.runelite.client.config.Keybind;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Plan step L32: the input listeners, out of the plugin class. Each hotkey fires on its own
 * binding only (modifiers included), and the arrival click is consumed only when it dismissed
 * the panel, so an ordinary click still reaches the game.
 */
public class PluginHotkeysTest
{
	/**
	 * A key press as the toolkit delivers it: Keybind matches on the EXTENDED key code, which the
	 * native layer fills in and a hand-built event leaves at zero, so it is mirrored from the code.
	 */
	private static KeyEvent press(int keyCode, int modifiers)
	{
		return new KeyEvent(new JPanel(), KeyEvent.KEY_PRESSED, 0L, modifiers, keyCode, KeyEvent.CHAR_UNDEFINED)
		{
			@Override
			public int getExtendedKeyCode()
			{
				return getKeyCode();
			}
		};
	}

	private static MouseEvent click()
	{
		return new MouseEvent(new JPanel(), MouseEvent.MOUSE_PRESSED, 0L, 0, 5, 5, 1, false);
	}

	@Test
	public void eachHotkeyFiresOnItsOwnBindingOnly()
	{
		AtomicInteger cleared = new AtomicInteger();
		AtomicInteger focused = new AtomicInteger();
		PluginHotkeys hotkeys = new PluginHotkeys(
			() -> new Keybind(KeyEvent.VK_F, 0), cleared::incrementAndGet,
			() -> new Keybind(KeyEvent.VK_G, KeyEvent.CTRL_DOWN_MASK), focused::incrementAndGet,
			point -> false);

		hotkeys.clearPath().keyPressed(press(KeyEvent.VK_F, 0));
		hotkeys.clearPath().keyPressed(press(KeyEvent.VK_G, 0));
		hotkeys.focusSearch().keyPressed(press(KeyEvent.VK_G, 0));
		hotkeys.focusSearch().keyPressed(press(KeyEvent.VK_G, KeyEvent.CTRL_DOWN_MASK));
		assertEquals(1, cleared.get());
		assertEquals("only the modified press matches", 1, focused.get());
	}

	@Test
	public void theArrivalClickIsConsumedOnlyWhenItDismissedThePanel()
	{
		PluginHotkeys dismissing = new PluginHotkeys(() -> Keybind.NOT_SET, PluginHotkeysTest::noop, () -> Keybind.NOT_SET, PluginHotkeysTest::noop,
			point -> point.x == 5);
		MouseEvent hit = click();
		dismissing.dismissArrival().mousePressed(hit);
		assertTrue(hit.isConsumed());

		PluginHotkeys idle = new PluginHotkeys(() -> Keybind.NOT_SET, PluginHotkeysTest::noop, () -> Keybind.NOT_SET, PluginHotkeysTest::noop,
			point -> false);
		MouseEvent miss = click();
		idle.dismissArrival().mousePressed(miss);
		assertFalse("an ordinary click still reaches the game", miss.isConsumed());
	}

	/** A no-op callback (checkstyle wants a block's braces on their own lines, so no inline lambda). */
	private static void noop()
	{
	}
}

package gps;

import gps.pathfinder.PathStep;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

/**
 * Plan step L31: the plugin-message flow, out of the plugin class. A foreign namespace is
 * ignored; a new target arms the journey and expands the tile; an empty target keeps the current
 * destination and the running journey; without a start the player's position stands in, or the
 * request is dropped when there is none; overrides apply before the request and a clear drops
 * both; the displayed route's transports go out on both namespaces, only when enabled and routed.
 */
@RunWith(MockitoJUnitRunner.class)
public class PluginMessageBridgeTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3200, 3200, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(3210, 3205, 0);

	@Mock
	ShortestPathPlugin plugin;
	@Mock
	EventBus eventBus;
	@Mock
	ShortestPathConfig config;

	private PluginMessageBridge bridge;

	@Before
	public void setUp()
	{
		bridge = new PluginMessageBridge(plugin, () -> eventBus);
	}

	private static PluginMessage path(Map<String, Object> data)
	{
		return new PluginMessage(PluginMessageCodec.NAMESPACE_LEGACY, PluginMessageCodec.ACTION_PATH, data);
	}

	@Test
	public void foreignNamespacesAreIgnored()
	{
		bridge.receive(new PluginMessage("other", PluginMessageCodec.ACTION_PATH,
			Map.of(PluginMessageCodec.KEY_TARGET, new WorldPoint(3210, 3205, 0))));
		verifyNoInteractions(plugin, eventBus);
	}

	@Test
	@SuppressWarnings("unchecked")
	public void aNewTargetArmsTheJourneyAndExpandsTheTile()
	{
		Map<String, Object> data = new HashMap<>();
		data.put(PluginMessageCodec.KEY_START, new WorldPoint(3200, 3200, 0));
		data.put(PluginMessageCodec.KEY_TARGET, new WorldPoint(3210, 3205, 0));
		data.put(PluginMessageCodec.KEY_SOURCE, "Quest Helper");
		bridge.receive(path(data));

		verify(plugin).setTargetSource("Quest Helper");
		verify(plugin).armJourney();
		ArgumentCaptor<Set<Integer>> ends = ArgumentCaptor.forClass(Set.class);
		verify(plugin).setDestination(eq(START), ends.capture(), eq(false));
		assertTrue("the target tile is among the ends", ends.getValue().contains(TARGET));
		verify(plugin, never()).applyConfigOverrides(any());
	}

	@Test
	public void anEmptyTargetKeepsTheCurrentDestinationAndTheRunningJourney()
	{
		when(plugin.hasPathTargets()).thenReturn(true);
		when(plugin.getPathTargets()).thenReturn(Set.of(TARGET));
		bridge.receive(path(Map.of(PluginMessageCodec.KEY_START, new WorldPoint(3200, 3200, 0))));

		verify(plugin, never()).armJourney();
		verify(plugin).setDestination(START, Set.of(TARGET), true);
	}

	@Test
	public void withoutAStartThePlayerStandsInOrTheRequestIsDropped()
	{
		Map<String, Object> data = Map.of(PluginMessageCodec.KEY_TARGET, new WorldPoint(3210, 3205, 0));
		when(plugin.getPlayerLocation()).thenReturn(WorldPointUtil.UNDEFINED);
		bridge.receive(path(data));
		verify(plugin, never()).setDestination(anyInt(), any(), anyBoolean());

		when(plugin.getPlayerLocation()).thenReturn(START);
		bridge.receive(path(data));
		verify(plugin).setDestination(eq(START), any(), eq(false));
	}

	@Test
	public void overridesApplyBeforeTheRequestAndAClearDropsBoth()
	{
		Map<String, Object> data = new HashMap<>();
		data.put(PluginMessageCodec.KEY_START, new WorldPoint(3200, 3200, 0));
		data.put(PluginMessageCodec.KEY_TARGET, new WorldPoint(3210, 3205, 0));
		data.put(PluginMessageCodec.KEY_CONFIG_OVERRIDE, Map.of("avoidWilderness", true));
		bridge.receive(path(data));
		verify(plugin).applyConfigOverrides(Map.of("avoidWilderness", true));
		verify(plugin).setDestination(eq(START), any(), eq(false));

		bridge.receive(new PluginMessage(PluginMessageCodec.NAMESPACE, PluginMessageCodec.ACTION_CLEAR, Map.of()));
		verify(plugin).clearConfigOverrides();
		verify(plugin).clearPinnedTarget();
	}

	@Test
	public void transportsGoOutOnBothNamespacesOnlyWhenEnabledAndRouted()
	{
		when(plugin.hasPathTargets()).thenReturn(true);
		when(plugin.getGpsConfig()).thenReturn(config);
		when(config.postTransports()).thenReturn(false);
		bridge.postTransports();
		verifyNoInteractions(eventBus);

		when(config.postTransports()).thenReturn(true);
		when(plugin.getDisplayPath()).thenReturn(List.of());
		bridge.postTransports();
		verifyNoInteractions(eventBus);

		when(plugin.getDisplayPath()).thenReturn(List.of(new PathStep(START, false), new PathStep(TARGET, false)));
		when(plugin.transportsForEdge(any(), any())).thenReturn(Set.of());
		bridge.postTransports();
		ArgumentCaptor<PluginMessage> posted = ArgumentCaptor.forClass(PluginMessage.class);
		verify(eventBus, times(2)).post(posted.capture());
		List<String> namespaces = new ArrayList<>();
		for (PluginMessage message : posted.getAllValues())
		{
			assertEquals(PluginMessageCodec.ACTION_TRANSPORTS, message.getName());
			namespaces.add(message.getNamespace());
		}
		assertEquals(List.of(PluginMessageCodec.NAMESPACE, PluginMessageCodec.NAMESPACE_LEGACY), namespaces);
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Plan step L8: the plugin-message wire format, out of the plugin class. A "path" request may
 * carry its start and target as packed integers or world points (targets also as a set of
 * either), an optional config override and an optional source; a malformed target drops the
 * whole request rather than half of it, and an override-only message is not a path request.
 * The published transports keep the parallel-list shape older consumers read.
 */
public class PluginMessageCodecTest
{
	private static final WorldPoint LUMBRIDGE = new WorldPoint(3222, 3218, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3212, 3422, 0);

	@Test
	public void bothNamespacesAreOurs()
	{
		assertTrue(PluginMessageCodec.isOurs("gps"));
		assertTrue("the pre-fork namespace keeps older integrations working", PluginMessageCodec.isOurs("shortestpath"));
		assertFalse(PluginMessageCodec.isOurs("questhelper"));
	}

	@Test
	public void startAndTargetInEitherShape()
	{
		Map<String, Object> data = new HashMap<>();
		data.put("start", LUMBRIDGE);
		data.put("target", VARROCK);
		PluginMessageCodec.PathRequest request = PluginMessageCodec.parsePath(data);
		assertEquals(WorldPointUtil.packWorldPoint(LUMBRIDGE), request.start);
		assertEquals(Set.of(VARROCK), request.targets);
		assertEquals("no source given", PluginMessageCodec.DEFAULT_SOURCE, request.source);

		data.put("start", null);
		data.put("target", new WorldPoint(3212, 3422, 0));
		data.put("source", "Quest Helper");
		request = PluginMessageCodec.parsePath(data);
		assertEquals("no start: the player stands in for it", WorldPointUtil.UNDEFINED, request.start);
		assertEquals(Set.of(VARROCK), request.targets);
		assertEquals("Quest Helper", request.source);
	}

	@Test
	public void aSetOfTargetsMixesShapesAndDropsTheRequestOnABadMember()
	{
		Map<String, Object> data = new HashMap<>();
		data.put("target", Set.of(VARROCK, new WorldPoint(3222, 3218, 0)));
		PluginMessageCodec.PathRequest request = PluginMessageCodec.parsePath(data);
		assertEquals(Set.of(VARROCK, WorldPointUtil.packWorldPoint(LUMBRIDGE)), request.targets);

		data.put("target", Set.of(VARROCK, WorldPointUtil.UNDEFINED));
		assertNull("an undefined member drops the whole request", PluginMessageCodec.parsePath(data));
		data.put("target", WorldPointUtil.UNDEFINED);
		assertNull(PluginMessageCodec.parsePath(data));
	}

	@Test
	public void overrideOnlyIsNotAPathRequestAndAnUnknownTargetTypeKeepsTheDestination()
	{
		Map<String, Object> data = new HashMap<>();
		data.put("config", Map.of("avoidWilderness", true));
		assertNull("neither start nor target", PluginMessageCodec.parsePath(data));
		assertEquals(Map.of("avoidWilderness", true), PluginMessageCodec.configOverrideOf(data));

		data.put("config", "not a map");
		assertTrue(PluginMessageCodec.configOverrideOf(data).isEmpty());

		data.put("start", LUMBRIDGE);
		data.put("target", "somewhere");
		PluginMessageCodec.PathRequest request = PluginMessageCodec.parsePath(data);
		assertTrue("an unknown target type means keep the current destination", request.targets.isEmpty());
	}

	@Test
	public void publishedTransportsKeepTheParallelListShape()
	{
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3201, 3200, 0);
		int c = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		List<PathStep> path = List.of(new PathStep(a, false), new PathStep(b, false), new PathStep(c, false));
		Transport ride = new Transport.TransportBuilder().origin(b).destination(c)
			.type(TransportType.GNOME_GLIDER).displayInfo("Gandius").objectInfo("Glider").build();
		Map<String, Object> data = PluginMessageCodec.encodeTransports(path,
			(from, to) -> from.getPackedPosition() == b ? List.of(ride) : List.of());
		assertEquals(List.of(WorldPointUtil.unpackWorldPoint(b)), data.get("origin"));
		assertEquals(List.of(WorldPointUtil.unpackWorldPoint(c)), data.get("destination"));
		assertEquals(List.of("Glider"), data.get("objectInfo"));
		assertEquals(List.of("Gandius"), data.get("displayInfo"));
	}
}

