package gps;

import java.awt.Color;
import java.awt.Rectangle;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

@PluginDescriptor(name = "Shortest Path Test", description = "Test the Shortest Path Plugin Message events")
public class PluginMessageTestPlugin extends Plugin
{
	private static final String PLUGIN_MESSAGE_NAME = "shortestpath";
	private static final String PLUGIN_MESSAGE_PATH = "path";
	private static final String PLUGIN_MESSAGE_CLEAR = "clear";
	private static final String PLUGIN_MESSAGE_START = "start";
	private static final String PLUGIN_MESSAGE_TARGET = "target";
	private static final String PLUGIN_MESSAGE_CONFIG_OVERRIDE = "config";
	private static final String CLEAR = "Clear";
	private static final String PATH = ColorUtil.wrapWithColorTag("Path (PluginMessage)", JagexColors.MENU_TARGET);
	private static final String SET = "Set";
	private static final String START_INT = ColorUtil.wrapWithColorTag("Start Integer (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String START_WP = ColorUtil.wrapWithColorTag("Start WorldPoint (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String TARGET_INT = ColorUtil.wrapWithColorTag("Target Integer(s) (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String TARGET_WP = ColorUtil.wrapWithColorTag("Target WorldPoint(s) (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String CONFIG_COLOUR_PATH = ColorUtil.wrapWithColorTag("Yellow path colour (PluginMessage)",
		JagexColors.MENU_TARGET);

	private final Set<WorldPoint> targets = new HashSet<>(10);
	private Point lastMenuOpenedPoint;

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	private static int packWorldPoint(WorldPoint wp)
	{
		if (wp == null)
		{
			return -1;
		}
		return (wp.getX() & 0x7FFF) | ((wp.getY() & 0x7FFF) << 15) | ((wp.getPlane() & 0x3) << 30);
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		lastMenuOpenedPoint = client.getMouseCanvasPosition();

		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		for (MenuEntry menuEntry : event.getMenuEntries())
		{
			if (MenuAction.WALK.equals(menuEntry.getType()))
			{
				addMenuEntry(SET, TARGET_INT, 1);
				addMenuEntry(SET, TARGET_WP, 1);
				addMenuEntry(SET, CONFIG_COLOUR_PATH, 1);
				if (!targets.isEmpty())
				{
					addMenuEntry(SET, START_INT, 1);
					addMenuEntry(SET, START_WP, 1);
				}
				addMenuEntry(CLEAR, PATH, 1);
				break;
			}
		}

		final Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);

		if (map != null
			&& map.getBounds().contains(
			client.getMouseCanvasPosition().getX(),
			client.getMouseCanvasPosition().getY()))
		{
			addMenuEntry(SET, TARGET_INT, 0);
			addMenuEntry(SET, TARGET_WP, 0);
			addMenuEntry(SET, CONFIG_COLOUR_PATH, 0);
			if (!targets.isEmpty())
			{
				addMenuEntry(SET, START_INT, 0);
				addMenuEntry(SET, START_WP, 0);
				addMenuEntry(CLEAR, PATH, 0);
			}
		}
	}

	private void addMenuEntry(String option, String target, int position)
	{
		client.getMenu().createMenuEntry(position)
			.setOption(option)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(this::onMenuOptionClicked);
	}

	private void onMenuOptionClicked(MenuEntry entry)
	{
		boolean isMessageInt = false;
		boolean overrideColourPath = false;
		WorldPoint start = null;
		WorldPoint target = null;

		if (entry.getOption().equals(SET) && entry.getTarget().equals(TARGET_INT))
		{
			isMessageInt = true;
			target = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(TARGET_WP))
		{
			target = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(START_INT))
		{
			isMessageInt = true;
			start = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(START_WP))
		{
			start = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(CONFIG_COLOUR_PATH))
		{
			overrideColourPath = true;
		}
		else if (entry.getOption().equals(CLEAR) && entry.getTarget().equals(PATH))
		{
			targets.clear();
			eventBus.post(new PluginMessage(PLUGIN_MESSAGE_NAME, PLUGIN_MESSAGE_CLEAR));
			return;
		}

		if (target != null)
		{
			targets.add(target);
		}

		Set<Integer> convertedTargets = new HashSet<>();
		if (isMessageInt)
		{
			for (WorldPoint t : targets)
			{
				convertedTargets.add(packWorldPoint(t));
			}
		}

		Map<String, Object> data = new HashMap<>();

		if (start != null)
		{
			data.put(PLUGIN_MESSAGE_START, isMessageInt ? packWorldPoint(start) : start);
		}

		if (!targets.isEmpty())
		{
			data.put(PLUGIN_MESSAGE_TARGET,
				targets.size() != 1 ? (isMessageInt ? convertedTargets : targets)
					: (isMessageInt ? convertedTargets.iterator().next() : targets.iterator().next()));
		}

		if (overrideColourPath)
		{
			Map<String, Object> configOverride = new HashMap<>();
			configOverride.put("colourPath", new Color(255, 255, 0));
			data.put(PLUGIN_MESSAGE_CONFIG_OVERRIDE, configOverride);
		}

		eventBus.post(new PluginMessage(PLUGIN_MESSAGE_NAME, PLUGIN_MESSAGE_PATH, data));
	}

	private WorldPoint getSelectedWorldPoint()
	{
		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			if (client.getTopLevelWorldView().getSelectedSceneTile() != null)
			{
				return WorldPoint.fromLocalInstance(client, client.getTopLevelWorldView().getSelectedSceneTile().getLocalLocation());
			}
		}
		else
		{
			return client.isMenuOpen()
				? calculateMapPoint(lastMenuOpenedPoint.getX(), lastMenuOpenedPoint.getY())
				: calculateMapPoint(client.getMouseCanvasPosition().getX(), client.getMouseCanvasPosition().getY());
		}
		return null;
	}

	private WorldPoint calculateMapPoint(int pointX, int pointY)
	{
		WorldMap worldMap = client.getWorldMap();
		float zoom = worldMap.getWorldMapZoom();
		WorldPoint mapPoint = new WorldPoint(worldMap.getWorldMapPosition().getX(), worldMap.getWorldMapPosition().getY(),
			0);
		int middleX = mapWorldPointToGraphicsPointX(mapPoint);
		int middleY = mapWorldPointToGraphicsPointY(mapPoint);

		if (pointX == Integer.MIN_VALUE || pointY == Integer.MIN_VALUE ||
			middleX == Integer.MIN_VALUE || middleY == Integer.MIN_VALUE)
		{
			return null;
		}

		final int dx = (int) ((pointX - middleX) / zoom);
		final int dy = (int) ((-(pointY - middleY)) / zoom);

		return mapPoint.dx(dx).dy(dy);
	}

	public int mapWorldPointToGraphicsPointX(WorldPoint worldPoint)
	{
		WorldMap worldMap = client.getWorldMap();

		float pixelsPerTile = worldMap.getWorldMapZoom();

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map != null)
		{
			Rectangle worldMapRect = map.getBounds();

			int widthInTiles = (int) Math.ceil(worldMapRect.getWidth() / pixelsPerTile);

			Point worldMapPosition = worldMap.getWorldMapPosition();

			int xTileOffset = worldPoint.getX() + widthInTiles / 2 - worldMapPosition.getX();

			int xGraphDiff = ((int) (xTileOffset * pixelsPerTile));
			xGraphDiff += (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
			xGraphDiff += (int) worldMapRect.getX();

			return xGraphDiff;
		}
		return Integer.MIN_VALUE;
	}

	public int mapWorldPointToGraphicsPointY(WorldPoint worldPoint)
	{
		WorldMap worldMap = client.getWorldMap();

		float pixelsPerTile = worldMap.getWorldMapZoom();

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map != null)
		{
			Rectangle worldMapRect = map.getBounds();

			int heightInTiles = (int) Math.ceil(worldMapRect.getHeight() / pixelsPerTile);

			Point worldMapPosition = worldMap.getWorldMapPosition();

			int yTileMax = worldMapPosition.getY() - heightInTiles / 2;
			int yTileOffset = (yTileMax - worldPoint.getY() - 1) * -1;

			int yGraphDiff = (int) (yTileOffset * pixelsPerTile);
			yGraphDiff -= (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
			yGraphDiff = worldMapRect.height - yGraphDiff;
			yGraphDiff += (int) worldMapRect.getY();

			return yGraphDiff;
		}
		return Integer.MIN_VALUE;
	}
}

package gps;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Plan step L11: house-furniture detection, out of the plugin class. Inside-the-house evidence
 * comes from the template regions or from spawned furniture; a scan repeats per tick until it
 * finds something, capped at six attempts for a bare house; leaving the house or leaving
 * building mode re-arms it; declarations are only ever raised; the result persists once per
 * change and restores when nothing was scanned this session.
 */
@RunWith(MockitoJUnitRunner.class)
public class PohDetectionServiceTest
{
	@Mock
	ConfigManager configManager;

	private static final String GROUP = "gps";

	/** A scene the test controls: whether it is a house, and which object ids it holds. */
	private static final class FakeScene implements PohDetectionService.Scene
	{
		boolean house;
		final Set<Integer> ids = new HashSet<>();
		int walks;

		@Override
		public boolean isHouse()
		{
			return house;
		}

		@Override
		public boolean isInstance()
		{
			return house;
		}

		@Override
		public String describeChunks()
		{
			return "chunks";
		}

		@Override
		public Set<Integer> objectIds()
		{
			walks++;
			return ids;
		}
	}

	/** Declarations that record every raise; a raise takes effect, as the real config does. */
	private static final class FakeDeclarations implements PohDetectionService.Declarations
	{
		boolean fairyRing;
		boolean spiritTree;
		boolean obelisk;
		JewelleryBoxTier tier = JewelleryBoxTier.NONE;
		final List<String> raised = new ArrayList<>();

		@Override
		public boolean fairyRing()
		{
			return fairyRing;
		}

		@Override
		public boolean spiritTree()
		{
			return spiritTree;
		}

		@Override
		public boolean obelisk()
		{
			return obelisk;
		}

		@Override
		public JewelleryBoxTier jewelleryBoxTier()
		{
			return tier;
		}

		/** Records the raise and applies it, as the real config does for the next scan. */
		@Override
		public void raise(String key, Object value)
		{
			raised.add(key + "=" + value);
			switch (key)
			{
				case "usePohFairyRing":
					fairyRing = true;
					break;
				case "usePohSpiritTree":
					spiritTree = true;
					break;
				case "usePohObelisk":
					obelisk = true;
					break;
				case "pohJewelleryBoxTier":
					tier = (JewelleryBoxTier) value;
					break;
				default:
					throw new IllegalArgumentException(key);
			}
		}
	}

	private final FakeScene scene = new FakeScene();
	private final FakeDeclarations declarations = new FakeDeclarations();
	private boolean building;
	private boolean smartDetect = true;
	private final AtomicInteger changes = new AtomicInteger();

	private PohDetectionService service()
	{
		return new PohDetectionService(() -> scene, () -> building, () -> smartDetect, declarations,
			configManager, GROUP, changes::incrementAndGet);
	}

	@Test
	public void outsideAHouseNothingIsScanned()
	{
		PohDetectionService service = service();
		scene.ids.add(ObjectID.POH_FAIRY_RING);
		service.onTick();
		service.onTick();
		assertFalse(service.isScanned());
		assertEquals(0, scene.walks);
		verify(configManager, never()).setRSProfileConfiguration(GROUP, PohDetectionService.CONFIG_KEY_POH_FURNITURE, "x");
	}

	@Test
	public void insideAHouseTheFirstFindRaisesDeclarationsPersistsAndStopsRescanning()
	{
		PohDetectionService service = service();
		scene.house = true;
		scene.ids.add(ObjectID.POH_FAIRY_RING);
		scene.ids.add(ObjectID.POH_JEWELLERY_BOX_2);
		declarations.tier = JewelleryBoxTier.BASIC;

		service.onTick();
		assertTrue(service.isScanned());
		assertEquals(List.of("Fancy jewellery box", "Fairy ring"), service.detectedNames());
		assertEquals("only what was off or lower is raised", List.of("usePohFairyRing=true", "pohJewelleryBoxTier=Fancy"),
			declarations.raised);
		verify(configManager).setRSProfileConfiguration(GROUP, PohDetectionService.CONFIG_KEY_POH_FURNITURE, "FANCY,fairyRing");
		assertEquals(1, changes.get());

		service.onTick();
		service.onTick();
		assertEquals("found this visit: no rescans", 1, scene.walks);
	}

	@Test
	public void aBareHouseIsScannedSixTimesThenLeftAlone()
	{
		PohDetectionService service = service();
		scene.house = true;
		for (int i = 0; i < 10; i++)
		{
			service.onTick();
		}
		assertEquals(PohDetectionService.MAX_ATTEMPTS, scene.walks);
		assertTrue("scanned, with nothing", service.isScanned());
		assertTrue(service.detectedNames().isEmpty());
		assertEquals("persisted once (the empty result), then unchanged", 1, changes.get());
	}

	@Test
	public void spawnedFurnitureIsInsideEvidenceAndJoinsTheScan()
	{
		PohDetectionService service = service();
		service.furnitureSpawned(ObjectID.POH_SPIRIT_TREE);
		service.furnitureSpawned(4151); // not furniture
		service.onTick();
		assertTrue("the scene was not judged a house, the spawn was proof enough", service.isScanned());
		assertEquals(List.of("Spirit tree"), service.detectedNames());
		assertEquals(List.of("usePohSpiritTree=true"), declarations.raised);
	}

	@Test
	public void leavingBuildingModeReArmsTheScanAndOnlyChangesPersist()
	{
		PohDetectionService service = service();
		scene.house = true;
		scene.ids.add(ObjectID.POH_FAIRY_RING);
		service.onTick();
		assertEquals(1, scene.walks);

		// Building: the furniture is unchanged, and the scan does not re-run by itself.
		building = true;
		service.onTick();
		assertEquals(1, scene.walks);
		// Built a spirit tree, left building mode: one more scan, the new piece raised.
		scene.ids.add(ObjectID.POH_SPIRIT_TREE);
		building = false;
		service.onTick();
		assertEquals(2, scene.walks);
		assertEquals(List.of("usePohFairyRing=true", "usePohSpiritTree=true"), declarations.raised);
		verify(configManager, times(2)).setRSProfileConfiguration(org.mockito.ArgumentMatchers.eq(GROUP),
			org.mockito.ArgumentMatchers.eq(PohDetectionService.CONFIG_KEY_POH_FURNITURE), org.mockito.ArgumentMatchers.anyString());

		// Out of the house and back in: a fresh visit scans again; nothing changed, so no persist.
		scene.house = false;
		service.onTick();
		scene.house = true;
		service.onTick();
		assertEquals(3, scene.walks);
		verify(configManager, times(2)).setRSProfileConfiguration(org.mockito.ArgumentMatchers.eq(GROUP),
			org.mockito.ArgumentMatchers.eq(PohDetectionService.CONFIG_KEY_POH_FURNITURE), org.mockito.ArgumentMatchers.anyString());
	}

	@Test
	public void smartDetectOffMeansNoScan()
	{
		PohDetectionService service = service();
		scene.house = true;
		scene.ids.add(ObjectID.POH_FAIRY_RING);
		smartDetect = false;
		service.onTick();
		assertFalse(service.isScanned());
		assertEquals(0, scene.walks);
	}

	@Test
	public void restoreReadsTheSnapshotOnlyWhenNothingWasScannedAndResetForgets()
	{
		when(configManager.getRSProfileConfiguration(GROUP, PohDetectionService.CONFIG_KEY_POH_FURNITURE))
			.thenReturn("ORNATE,obelisk");
		PohDetectionService service = service();
		service.restore();
		assertTrue(service.isScanned());
		assertEquals(List.of("Ornate jewellery box", "Obelisk"), service.detectedNames());

		service.reset();
		assertFalse(service.isScanned());
		assertTrue(service.detectedNames().isEmpty());
	}
}

package gps;

import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;

public class PohHeuristicRegressionTest
{
	private AlternativeRoutesService service;
	private PathfinderConfig planningConfig;

	@Before
	public void before()
	{
		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.usePoh()).thenReturn(true);
		Mockito.when(cfg.useTeleportationPortalsPoh()).thenReturn(true);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		planningConfig = config;
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(ct, config);
	}

	@org.junit.After
	public void after()
	{
		service.shutdown();
	}

	/**
	 * User capture pair (20260713-232224/232231): from Keldagrim, the four "enter the POH, take the
	 * Lassar Portal" routes (cost 29) only appeared AFTER "+", jumping above the first page's 67+
	 * routes. The distance field's reverse transport index credited POH portals to their interior
	 * origin instead of the remapped landing key, leaving the landing unflooded — the heuristic then
	 * overestimated inside the house (inadmissible), so house-mediated routes settled late. The
	 * first page must now carry them.
	 */
	@Test
	public void houseMediatedRoutesAreOnTheFirstPage() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2907, 10172, 0),
			Set.of(WorldPointUtil.packWorldPoint(3009, 3487, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue(latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		int pohPortalRoutesAtBestTier = 0;
		for (RouteOption route : routes)
		{
			boolean viaPohPortal = route.getMethods().stream()
				.anyMatch(m -> gps.transport.TransportType.TELEPORTATION_PORTAL_POH.equals(m.getType()));
			if (viaPohPortal && route.getTotalCost() <= routes.get(0).getTotalCost() + 2)
			{
				pohPortalRoutesAtBestTier++;
			}
		}
		assertTrue("the first page must include the house->Lassar Portal routes at the best cost tier"
			+ " (found " + pohPortalRoutesAtBestTier + ")", pohPortalRoutesAtBestTier >= 3);
	}

	/**
	 * Route 0 itself was vulnerable, not just the lower ranks: for a player without the direct
	 * Lassar teleports, the TRUE optimum is the house route (29) — pre-fix, the inadmissible
	 * heuristic made the first search return Mind Altar (67) as the top route instead. Excluding
	 * the direct teleports simulates that player.
	 */
	@Test
	public void routeZeroIsTheHouseRouteWhenDirectTeleportsAreMissing() throws Exception
	{
		Set<TeleportMethod> exclusions = new java.util.HashSet<>();
		for (TeleportMethod method : planningConfig.getMethodCatalog())
		{
			if (method.label().equals("Lassar tablet") || method.label().equals("Lassar Teleport"))
			{
				exclusions.add(method);
			}
		}
		assertTrue("both direct Lassar methods must exist in the catalog", exclusions.size() == 2);

		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2907, 10172, 0),
			Set.of(WorldPointUtil.packWorldPoint(3009, 3487, 0)), exclusions,
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue(latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("routes must be found", !routes.isEmpty());
		RouteOption best = routes.get(0);
		boolean viaPohPortal = best.getMethods().stream()
			.anyMatch(m -> gps.transport.TransportType.TELEPORTATION_PORTAL_POH.equals(m.getType()));
		assertTrue("route 0 must be the house-mediated optimum (cost " + best.getTotalCost()
			+ ", methods " + best.getMethods() + ")", viaPohPortal && best.getTotalCost() <= 30);
	}
}

package gps;

import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import net.runelite.api.gameval.ObjectID;

public class PohScannerTest
{
	@Test
	public void emptyHouseDetectsNothing()
	{
		PohScanner.Detected d = PohScanner.detect(Set.of(1, 2, 3));
		assertFalse(d.any());
		assertEquals(JewelleryBoxTier.NONE, d.jewelleryBox);
	}

	@Test
	public void recognisesEachCleanFeature()
	{
		PohScanner.Detected d = PohScanner.detect(Set.of(
			ObjectID.POH_FAIRY_RING, ObjectID.POH_SPIRIT_TREE, ObjectID.POH_WILDERNESS_OBELISK,
			ObjectID.POH_JEWELLERY_BOX_2));
		assertTrue(d.fairyRing);
		assertTrue(d.spiritTree);
		assertTrue(d.obelisk);
		assertEquals(JewelleryBoxTier.FANCY, d.jewelleryBox);
		assertTrue(d.any());
	}

	@Test
	public void spawnRelevanceMatchesWhatDetectRecognises()
	{
		// Every id detect() reacts to must be flagged, so the spawn-event fast path never misses
		// furniture the tile scan would have found.
		for (int id : new int[]{
			ObjectID.POH_FAIRY_RING, ObjectID.POH_FAIRY_HOUSE, ObjectID.POH_FAIRY_HOUSE_OPEN,
			ObjectID.POH_SPIRIT_TREE, ObjectID.POH_WILDERNESS_OBELISK,
			ObjectID.POH_JEWELLERY_BOX_1, ObjectID.POH_JEWELLERY_BOX_2, ObjectID.POH_JEWELLERY_BOX_3})
		{
			assertTrue(String.valueOf(id), PohScanner.isRecognised(id));
			assertTrue(PohScanner.detect(Set.of(id)).any());
		}
		assertFalse(PohScanner.isRecognised(1));
	}

	@Test
	public void encodeDecodeRoundTripsEveryCombination()
	{
		for (JewelleryBoxTier tier : JewelleryBoxTier.values())
		{
			for (int flags = 0; flags < 8; flags++)
			{
				PohScanner.Detected original = new PohScanner.Detected(
					(flags & 1) != 0, (flags & 2) != 0, (flags & 4) != 0, tier);
				PohScanner.Detected decoded = PohScanner.decode(PohScanner.encode(original));
				assertTrue(tier + "/" + flags, original.sameAs(decoded));
			}
		}
	}

	@Test
	public void missingOrMalformedStoredDataDecodesToNull()
	{
		assertEquals(null, PohScanner.decode(null));
		assertEquals(null, PohScanner.decode(""));
		assertEquals(null, PohScanner.decode("garbage,fairyRing"));
		assertEquals(null, PohScanner.encode(null));
		// Duplicate flags are tolerated, not fatal.
		assertTrue(PohScanner.decode("NONE,fairyRing,fairyRing").fairyRing);
	}

	@Test
	public void jewelleryBoxTakesTheHighestTierPresent()
	{
		// A house upgraded to ornate may still show the lower box ids; the highest wins.
		assertEquals(JewelleryBoxTier.ORNATE, PohScanner.detect(Set.of(
			ObjectID.POH_JEWELLERY_BOX_1, ObjectID.POH_JEWELLERY_BOX_3)).jewelleryBox);
		assertEquals(JewelleryBoxTier.BASIC, PohScanner.detect(Set.of(
			ObjectID.POH_JEWELLERY_BOX_1)).jewelleryBox);
	}

	@Test
	public void openFairyHouseAlsoCounts()
	{
		assertTrue(PohScanner.detect(Set.of(ObjectID.POH_FAIRY_HOUSE_OPEN)).fairyRing);
	}
}

package gps;

import net.runelite.api.WorldView;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Pins the "is this scene a player-owned house" check: an instance whose map regions (the
 * template regions the scene is assembled from) include one of the POH template regions
 * (rx 29-32, ry 110-111 — regions 7534-8303). Confirmed against a real house's chunk dump, a
 * game-cache scan, and other plugins' POH region lists (2026-07-17); the transport data's POH
 * model band (y 5696) is NOT what live houses are built from, and checking it was why house
 * detection failed in the field.
 */
public class PohSceneDetectionTest
{
	private static WorldView instanceWithRegions(int... regions)
	{
		WorldView worldView = Mockito.mock(WorldView.class);
		Mockito.when(worldView.isInstance()).thenReturn(true);
		Mockito.when(worldView.getMapRegions()).thenReturn(regions);
		return worldView;
	}

	@Test
	public void everyPohTemplateRegionIsDetected()
	{
		for (int region : new int[]{7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303})
		{
			assertTrue(String.valueOf(region),
				PlayerOwnedHouse.isHouseScene(instanceWithRegions(region)));
		}
	}

	@Test
	public void realHouseRegionSetIsDetected()
	{
		// The house whose chunk dump identified the band mapped entirely into region 7534.
		assertTrue(PlayerOwnedHouse.isHouseScene(instanceWithRegions(7534)));
	}

	@Test
	public void nonHouseInstancesAreNotDetected()
	{
		// A raid or cutscene instance is assembled from other regions.
		assertFalse(PlayerOwnedHouse.isHouseScene(instanceWithRegions(12889, 13136)));
		// The transport data's POH model band (region 7513, y 5696) is not a live house.
		assertFalse(PlayerOwnedHouse.isHouseScene(instanceWithRegions(7513)));
		assertFalse(PlayerOwnedHouse.isHouseScene(instanceWithRegions()));
		assertFalse(PlayerOwnedHouse.isHouseScene(instanceWithRegions((int[]) null)));
	}

	@Test
	public void nonInstanceWorldsAreNeverAHouse()
	{
		assertFalse(PlayerOwnedHouse.isHouseScene(null));
		// Standing OUTSIDE a house portal the overworld is not an instance, whatever its regions.
		WorldView overworld = Mockito.mock(WorldView.class);
		Mockito.when(overworld.isInstance()).thenReturn(false);
		assertFalse(PlayerOwnedHouse.isHouseScene(overworld));
	}
}

package gps;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import org.junit.Assert;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;
import gps.transport.Transport;
import gps.transport.TransportLoader;

public class PrimitiveIntHashMapTests
{
	// Copy of the map's private hash to synthesize collisions in tests
	private static int testHash(int value)
	{
		return value ^ (value >>> 5) ^ (value >>> 25);
	}

	@Test(expected = IllegalArgumentException.class)
	public void checkNullValueProhibited()
	{
		PrimitiveIntHashMap<Boolean> map = new PrimitiveIntHashMap<>(8);
		map.put(0, null);
	}

	@Test
	public void tryInsertTransports()
	{
		HashMap<Integer, Set<Transport>> transports = TransportLoader.loadAllFromResources();
		PrimitiveIntHashMap<Set<Transport>> map = new PrimitiveIntHashMap<>(transports.size());

		for (Map.Entry<Integer, Set<Transport>> entry : transports.entrySet())
		{
			int packedPoint = entry.getKey();
			map.put(packedPoint, entry.getValue());
		}

		// Append empty set
		for (Map.Entry<Integer, Set<Transport>> entry : transports.entrySet())
		{
			int packedPoint = entry.getKey();
			map.put(packedPoint, entry.getValue());
			Assert.assertEquals("Appending empty should not overwrite", map.put(packedPoint, new HashSet<>()),
				map.get(packedPoint));
		}

		// Append non-empty set
		for (Map.Entry<Integer, Set<Transport>> entry : transports.entrySet())
		{
			int packedPoint = entry.getKey();
			map.put(packedPoint, entry.getValue());
			int sizeBefore = map.get(packedPoint).size();
			Set<Transport> nonEmpty = new HashSet<>();
			nonEmpty.add(null);
			map.put(packedPoint, nonEmpty);
			int sizeAfter = map.get(packedPoint).size();
			Assert.assertEquals("Appending non-empty should not overwrite", sizeBefore + 1, sizeAfter);
		}

		for (Map.Entry<Integer, Set<Transport>> entry : transports.entrySet())
		{
			int packedPoint = entry.getKey();
			Assert.assertEquals("World Point " + entry.getKey() + " did not map to the correct value", entry.getValue(),
				map.get(packedPoint));
		}
	}

	@Test
	public void tryGrowMap()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		for (int i = 0; i < 1024; ++i)
		{
			map.put(i, i);
		}

		Assert.assertEquals(1024, map.size());

		for (int i = 0; i < 1024; ++i)
		{
			Assert.assertEquals(i, map.get(i).intValue());
		}
	}

	@Test
	public void checkNonexistentEntries()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		Assert.assertNull(map.get(667215));
	}

	@Test
	public void tryOverwriteValues()
	{
		final int keyStart = 9875643; // Use keys that aren't 0 or all low bits

		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(2048);
		for (int i = 0; i < 1024; ++i)
		{
			map.put(i + keyStart, i);
		}

		// Overwrite values
		for (int i = 0; i < 1024; ++i)
		{
			map.put(i + keyStart, i + 1);
		}

		// Now check overwritten values stuck
		for (int i = 0; i < 1024; ++i)
		{
			Assert.assertEquals(i + 1, map.get(i + keyStart).intValue());
		}
	}

	@Test
	public void checkClearMap()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		for (int i = 0; i < 1024; ++i)
		{
			map.put(i, i);
		}

		Assert.assertEquals(1024, map.size());
		Assert.assertEquals(364, map.get(364).intValue());

		map.clear();
		Assert.assertEquals(0, map.size());
		Assert.assertNull(map.get(364));
	}

	@Test
	public void checkInsertOrderIrrelevant()
	{
		final int keyStart = 9875643; // Use keys that aren't 0 or all low bits
		PrimitiveIntHashMap<Integer> mapForward = new PrimitiveIntHashMap<>(8);
		PrimitiveIntHashMap<Integer> mapReversed = new PrimitiveIntHashMap<>(8);
		for (int i = 0; i < 1024; ++i)
		{
			mapForward.put(i + keyStart, i);
			mapReversed.put(1023 - i + keyStart, 1023 - i);
		}

		for (int i = 0; i < 1024; ++i)
		{
			Assert.assertEquals(mapForward.get(i + keyStart), mapReversed.get(i + keyStart));
		}
	}

	@Test
	public void sizeAndBasicPutGet()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);
		assertEquals(0, map.size());
		assertNull(map.get(42));

		assertNull(map.put(1, "a"));
		assertNull(map.put(2, "b"));
		assertEquals(2, map.size());
		assertEquals("a", map.get(1));
		assertEquals("b", map.get(2));

		// overwrite existing non-collection
		String prev = map.put(1, "a2");
		assertEquals("a", prev);
		assertEquals("a2", map.get(1));
		assertEquals(2, map.size()); // size unchanged on replace
	}

	@Test
	public void getOrDefaultWorks()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(4);
		assertEquals(Integer.valueOf(99), map.getOrDefault(123, 99));
		map.put(123, 7);
		assertEquals(Integer.valueOf(7), map.getOrDefault(123, 99));
	}

	@Test(expected = IllegalArgumentException.class)
	public void putNullDisallowed()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(4);
		map.put(5, null);
	}

	@Test
	public void negativeKeysSupported()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(4);
		map.put(-1, "neg1");
		map.put(Integer.MIN_VALUE, "min");
		assertEquals("neg1", map.get(-1));
		assertEquals("min", map.get(Integer.MIN_VALUE));
	}

	@Test
	public void clearResetsState()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(16);
		for (int i = 0; i < 10; i++)
		{
			map.put(i, "v" + i);
		}
		assertTrue(map.size() > 0);
		map.clear();
		assertEquals(0, map.size());
		for (int i = 0; i < 10; i++)
		{
			assertNull(map.get(i));
		}
	}

	@Test
	public void collectionValuesAppendOnDuplicateKey()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> a = new ArrayList<>(Arrays.asList(1, 2));
		List<Integer> b = new ArrayList<>(Arrays.asList(3, 4, 5));

		assertNull(map.put(7, a));
		List<Integer> prev = map.put(7, b);

		// Returned value is the previous instance and it has been mutated by addAll
		assertSame(a, prev);
		assertSame(a, map.get(7));
		assertEquals(Arrays.asList(1, 2, 3, 4, 5), map.get(7));
		assertEquals(1, map.size());
	}

	@Test
	public void rehashPreservesEntries()
	{
		// Use default load factor so rehashes will happen as size grows
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);

		int n = 10_000;
		for (int i = 0; i < n; i++)
		{
			map.put(i, "v" + i);
		}
		assertEquals(n, map.size());

		// verify random subset
		Random rnd = new Random(123);
		for (int i = 0; i < 2000; i++)
		{
			int k = rnd.nextInt(n);
			assertEquals("v" + k, map.get(k));
		}
	}

	@Test
	public void heavyCollisionsGrowBucketWithoutRehash()
	{
		// With loadFactor=1.0 and initial size < MINIMUM_SIZE, maxSize becomes 8 and
		// capacity is 8.
		// We'll place 6 entries into the SAME bucket so the internal bucket needs to
		// grow beyond DEFAULT_BUCKET_SIZE (4)
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(1, 1.0f);
		int mask = 8 - 1; // maxSize for initial map (given MINIMUM_SIZE=8)

		int targetBucket = 0; // any bucket works; pick 0
		List<Integer> collidingKeys = new ArrayList<>();
		for (int k = 0; collidingKeys.size() < 6 && k < 100_000; k++)
		{
			int bucket = (testHash(k) & 0x7FFFFFFF) & mask;
			if (bucket == targetBucket)
			{
				collidingKeys.add(k);
			}
		}
		assertEquals(6, collidingKeys.size());

		int i = 0;
		for (int key : collidingKeys)
		{
			assertNull(map.put(key, "v" + (i++)));
		}
		assertEquals(6, map.size());
		for (int idx = 0; idx < collidingKeys.size(); idx++)
		{
			int key = collidingKeys.get(idx);
			assertEquals("v" + idx, map.get(key));
		}
	}

	@Test
	public void calculateFullnessWithinBounds()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		double f0 = map.calculateFullness();
		assertTrue("empty map fullness should be NaN", Double.isNaN(f0));

		for (int i = 0; i < 100; i++)
		{
			map.put(i, i);
		}
		double f1 = map.calculateFullness();
		assertTrue("fullness in [0,100]", f1 >= 0.0 && f1 <= 100.0);
	}

	@Test
	public void constructorRejectsInvalidLoadFactor()
	{
		try
		{
			new PrimitiveIntHashMap<>(8, -0.1f);
			fail("Expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
		}

		try
		{
			new PrimitiveIntHashMap<>(8, 1.1f);
			fail("Expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
		}

		// Edge values allowed
		new PrimitiveIntHashMap<>(8, 0.0f);
		new PrimitiveIntHashMap<>(8, 1.0f);
	}

	@Test
	public void replacingDoesNotIncreaseSize()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);
		assertNull(map.put(10, "a"));
		int s1 = map.size();
		String prev = map.put(10, "b");
		assertEquals("a", prev);
		assertEquals(s1, map.size());
		assertEquals("b", map.get(10));
	}

	@Test
	public void manyRandomInsertionsAndLookups()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(32);
		Random rnd = new Random(42);
		Set<Integer> keys = new HashSet<>();

		for (int i = 0; i < 50_000; i++)
		{
			int k = rnd.nextInt();
			// avoid null values
			Integer prev = map.put(k, i);
			if (!keys.add(k))
			{
				// replacement path: previous value must be non-null
				assertNotNull(prev);
			}
			assertEquals(Integer.valueOf(i), map.get(k));
		}

		assertEquals(keys.size(), map.size());

		// sample lookups
		int checked = 0;
		for (int k : keys)
		{
			assertNotNull(map.get(k));
			if (++checked > 2000)
			{
				break;
			}
		}
	}

	@Test
	public void zeroLoadFactorCreatesMinimumCapacity()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(4, 0.0f);
		// With loadFactor 0.0, capacity should be 0, but map should still be usable
		assertNull(map.put(1, "test"));
		assertEquals("test", map.get(1));
		assertEquals(1, map.size());
	}

	@Test
	public void emptyCollectionAppending()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> originalList = new ArrayList<>(Arrays.asList(1, 2, 3));
		List<Integer> emptyList = new ArrayList<>();

		map.put(10, originalList);
		List<Integer> prev = map.put(10, emptyList);

		// Original list should be returned and remain unchanged since empty list adds
		// nothing
		assertSame(originalList, prev);
		assertSame(originalList, map.get(10));
		assertEquals(Arrays.asList(1, 2, 3), map.get(10));
	}

	@Test
	public void mixedCollectionAndNonCollectionReplace()
	{
		PrimitiveIntHashMap<Object> map = new PrimitiveIntHashMap<>(8);
		List<Integer> list = new ArrayList<>(Arrays.asList(1, 2));

		// Start with non-collection value
		map.put(5, "string");

		// Replace with collection - should replace, not append
		Object prev = map.put(5, list);
		assertEquals("string", prev);
		assertSame(list, map.get(5));

		// Replace collection with non-collection - should replace, not append
		prev = map.put(5, "another string");
		assertSame(list, prev);
		assertEquals("another string", map.get(5));
	}

	@Test
	public void calculateFullnessEdgeCases()
	{
		// Test with completely empty map
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		assertTrue("Empty map fullness should be NaN", Double.isNaN(map.calculateFullness()));

		// Test with single element
		map.put(1, 1);
		double fullness = map.calculateFullness();
		assertTrue("Single element fullness should be valid", fullness >= 0.0 && fullness <= 100.0);

		// Test with all buckets having exactly one element
		map.clear();
		// Fill exactly one slot in each bucket if possible
		for (int i = 0; i < 8; i++)
		{
			map.put(i * 1000, i); // Use keys that likely hash to different buckets
		}
		fullness = map.calculateFullness();
		assertTrue("Evenly distributed fullness should be valid", fullness >= 0.0 && fullness <= 100.0);
	}

	@Test
	public void integerOverflowKeys()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(16);

		// Test keys near integer overflow boundaries
		map.put(Integer.MAX_VALUE, "max");
		map.put(Integer.MAX_VALUE - 1, "max-1");
		map.put(Integer.MIN_VALUE, "min");
		map.put(Integer.MIN_VALUE + 1, "min+1");
		map.put(0, "zero");
		map.put(-1, "neg-one");

		assertEquals("max", map.get(Integer.MAX_VALUE));
		assertEquals("max-1", map.get(Integer.MAX_VALUE - 1));
		assertEquals("min", map.get(Integer.MIN_VALUE));
		assertEquals("min+1", map.get(Integer.MIN_VALUE + 1));
		assertEquals("zero", map.get(0));
		assertEquals("neg-one", map.get(-1));
		assertEquals(6, map.size());
	}

	@Test
	public void extremeCollisionScenario()
	{
		// Force many collisions by using a small initial size and load factor 1.0
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(2, 1.0f);

		// Add many items that will definitely cause collisions and bucket growth
		for (int i = 0; i < 100; i++)
		{
			map.put(i, "value" + i);
		}

		// Verify all values are still accessible
		for (int i = 0; i < 100; i++)
		{
			assertEquals("value" + i, map.get(i));
		}
		assertEquals(100, map.size());
	}

	@Test
	public void largeCollectionAppending()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> list1 = new ArrayList<>();
		for (int i = 0; i < 10000; i++)
		{
			list1.add(i);
		}

		List<Integer> list2 = new ArrayList<>();
		for (int i = 10000; i < 20000; i++)
		{
			list2.add(i);
		}

		map.put(1, list1);
		List<Integer> prev = map.put(1, list2);

		assertSame(list1, prev);
		assertSame(list1, map.get(1));
		assertEquals(20000, map.get(1).size());
		assertEquals(Integer.valueOf(0), map.get(1).get(0));
		assertEquals(Integer.valueOf(19999), map.get(1).get(19999));
	}

	@Test
	public void rehashDuringCollectionAppend()
	{
		// Create a map that will trigger rehash when a specific key is added
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(4, 0.75f);

		// Add items until we're close to the rehash threshold
		map.put(1, new ArrayList<>(List.of(1)));
		map.put(2, new ArrayList<>(List.of(2)));

		// This should trigger a rehash when the collection is appended
		List<Integer> appendList = new ArrayList<>(Arrays.asList(100, 200));
		List<Integer> prev = map.put(1, appendList);

		assertNotNull(prev);
		assertEquals(Arrays.asList(1, 100, 200), map.get(1));
		assertEquals(List.of(2), map.get(2));
		assertEquals(2, map.size());
	}

	@Test
	public void sameKeyDifferentHashBehavior()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);

		// Test that same key always returns same value regardless of hash collisions
		map.put(42, "first");
		assertEquals("first", map.get(42));

		String prev = map.put(42, "second");
		assertEquals("first", prev);
		assertEquals("second", map.get(42));
		assertEquals(1, map.size()); // Size should not change
	}

	@Test
	public void clearAfterComplexOperations()
	{
		PrimitiveIntHashMap<List<String>> map = new PrimitiveIntHashMap<>(4);

		// Perform complex operations that cause growth and collection appending
		for (int i = 0; i < 50; i++)
		{
			List<String> list = new ArrayList<>(List.of("item" + i));
			map.put(i % 10, list); // This will cause appending for repeated keys
		}

		assertTrue(map.size() > 0);
		double fullness = map.calculateFullness();
		assertFalse(Double.isNaN(fullness));

		// Clear should reset everything
		map.clear();
		assertEquals(0, map.size());
		assertTrue(Double.isNaN(map.calculateFullness()));

		// Should be able to use normally after clear
		map.put(1, new ArrayList<>(List.of("after clear")));
		assertEquals(1, map.size());
		assertEquals(List.of("after clear"), map.get(1));
	}

	@Test
	public void incompatibleCollectionTypes()
	{
		PrimitiveIntHashMap<Object> map = new PrimitiveIntHashMap<>(8);

		// Put a list of strings
		List<String> stringList = new ArrayList<>(Arrays.asList("hello", "world"));
		map.put(10, stringList);

		// Try to append a list of integers - this should handle the ClassCastException
		// gracefully
		List<Integer> intList = new ArrayList<>(Arrays.asList(1, 2, 3));
		try
		{
			Object prev = map.put(10, intList);
			// If we get here, the implementation should have handled the type mismatch
			assertSame(stringList, prev);
		}
		catch (ClassCastException e)
		{
			// This is also acceptable behavior - the implementation throws when types don't
			// match
			// In this case, verify the original value is still there
			assertSame(stringList, map.get(10));
		}
	}

	@Test
	public void bucketGrowthIntegerOverflow()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);

		// This test ensures that bucket growth doesn't cause integer overflow
		// We can't easily test the actual overflow case, but we can test large bucket
		// growth
		for (int i = 0; i < 1000; i++)
		{
			map.put(i, "value" + i);
		}

		// Verify all values are still accessible after many bucket growth operations
		for (int i = 0; i < 1000; i++)
		{
			assertEquals("value" + i, map.get(i));
		}
		assertEquals(1000, map.size());
	}

	@Test
	public void constructorHandlesNegativeInitialSize()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(-5);
		assertNull(map.get(1));
		map.put(1, "a");
		map.put(2, "b");
		assertEquals("a", map.get(1));
		assertEquals("b", map.get(2));
		assertEquals(2, map.size());
	}

	@Test
	public void appendToUnmodifiableCollectionReplaces()
	{
		PrimitiveIntHashMap<List<String>> map = new PrimitiveIntHashMap<>(8);
		List<String> fixed = Arrays.asList("x", "y"); // fixed-size list => addAll throws UnsupportedOperationException
		List<String> replacement = new ArrayList<>(Arrays.asList("a", "b", "c"));

		assertNull(map.put(42, fixed));
		List<String> prev = map.put(42, replacement);

		// Should have replaced rather than appended due to
		// UnsupportedOperationException
		assertSame(fixed, prev);
		assertSame(replacement, map.get(42));
		assertEquals(Arrays.asList("a", "b", "c"), map.get(42));
		assertEquals(1, map.size());
	}

	@Test
	public void getOrDefaultAllowsNullDefault()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		assertNull(map.getOrDefault(999, null));
		map.put(999, 123);
		assertEquals(Integer.valueOf(123), map.getOrDefault(999, null));
	}

	@Test
	public void selfCollectionAppendDuplicatesSafely()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> list = new ArrayList<>(Arrays.asList(1, 2));
		map.put(7, list);
		// Appending the same instance to itself should not crash and should duplicate
		// elements
		List<Integer> prev = map.put(7, list);
		assertSame(list, prev);
		assertSame(list, map.get(7));
		assertEquals(4, map.get(7).size());
		assertEquals(Arrays.asList(1, 2, 1, 2), map.get(7));
		assertEquals(1, map.size());
	}

	@Test
	public void zeroLoadFactorStress()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8, 0.0f);
		// Keep this small to avoid exponential rehash growth with loadFactor=0.0
		for (int i = 0; i < 16; i++)
		{
			map.put(i, i);
		}
		for (int i = 0; i < 16; i++)
		{
			assertEquals(Integer.valueOf(i), map.get(i));
		}
		assertEquals(16, map.size());
	}
}

package gps;

import org.junit.Assert;
import org.junit.Test;

public class PrimitiveIntListTests
{
	@Test
	public void tryAddAndGet()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		intList.add(11);
		Assert.assertEquals(2, intList.size());
		Assert.assertEquals(10, intList.get(0));
		Assert.assertEquals(11, intList.get(1));
	}

	@Test
	public void tryGrow()
	{
		PrimitiveIntList intList = new PrimitiveIntList(4);
		intList.add(10);
		intList.add(11);
		intList.add(12);
		intList.add(13);
		intList.add(14);
		Assert.assertEquals(5, intList.size());
		int sum = 0;
		for (int i = 0; i < intList.size(); i++)
		{
			sum += intList.get(i);
		}
		Assert.assertEquals(10 + 11 + 12 + 13 + 14, sum);
	}

	@Test
	public void tryInitialize()
	{
		PrimitiveIntList intList = new PrimitiveIntList(3, true);
		Assert.assertEquals(3, intList.size());
		Assert.assertEquals(0, intList.get(0));
		Assert.assertEquals(0, intList.get(1));
		Assert.assertEquals(0, intList.get(2));
		intList.set(0, 10);
		intList.set(1, 11);
		intList.set(2, 12);
		Assert.assertEquals(10, intList.get(0));
		Assert.assertEquals(11, intList.get(1));
		Assert.assertEquals(12, intList.get(2));
	}

	@Test
	public void tryIterate()
	{
		int sum = 0;
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		intList.add(11);
		for (int i = 0; i < intList.size(); i++)
		{
			sum += intList.get(i);
		}
		Assert.assertEquals(10 + 11, sum);
	}

	@Test
	public void tryRemove()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		intList.add(11);
		Assert.assertEquals(2, intList.size());
		Assert.assertEquals(10, intList.removeAt(0));
		Assert.assertTrue(intList.remove(11));
		Assert.assertTrue(intList.isEmpty());
	}

	@Test
	public void defaultConstructor()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
	}

	@Test
	public void capacityOnlyConstructor()
	{
		PrimitiveIntList intList = new PrimitiveIntList(5);
		// The list is not initialized so the size is 0
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
		intList.add(42);
		Assert.assertEquals(1, intList.size());
		Assert.assertEquals(42, intList.get(0));
	}

	@Test(expected = IllegalArgumentException.class)
	public void negativeCapacityConstructor()
	{
		new PrimitiveIntList(-1);
	}

	@Test
	public void zeroCapacityConstructor()
	{
		PrimitiveIntList intList = new PrimitiveIntList(0);
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
	}

	@Test
	public void addAtIndex()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.add(2);
		intList.add(1, 99); // insert in middle
		Assert.assertEquals(3, intList.size());
		Assert.assertEquals(1, intList.get(0));
		Assert.assertEquals(99, intList.get(1));
		Assert.assertEquals(2, intList.get(2));
		intList.add(3, 100); // insert at end (index == size before add)
		Assert.assertEquals(4, intList.size());
		Assert.assertEquals(100, intList.get(3));
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void addAtIndexOutOfBoundsHigh()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1, 5);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void addAtIndexOutOfBoundsNegative()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(-1, 5);
	}

	@Test
	public void setReturnsOldValue()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		int old = intList.set(0, 20);
		Assert.assertEquals(10, old);
		Assert.assertEquals(20, intList.get(0));
	}

	@Test
	public void containsAndIndexOf()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(5);
		intList.add(6);
		intList.add(7);
		Assert.assertTrue(intList.contains(6));
		Assert.assertEquals(1, intList.indexOf(6));
		Assert.assertFalse(intList.contains(8));
		Assert.assertEquals(-1, intList.indexOf(8));
	}

	@Test
	public void removeNotPresent()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		Assert.assertFalse(intList.remove(2));
		Assert.assertEquals(1, intList.size());
	}

	@Test
	public void clearEmptiesList()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.add(2);
		intList.clear();
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
		intList.add(3); // ensure list still usable
		Assert.assertEquals(1, intList.size());
		Assert.assertEquals(3, intList.get(0));
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void getOutOfBounds()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.get(1); // size == 1 so index 1 invalid
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void setOutOfBounds()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.set(1, 2);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void removeAtOutOfBounds()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.removeAt(1);
	}

	@Test
	public void ensureCapacityNoOpAndGrowth()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		// ensureCapacity(0) should be a no-op and size unchanged
		intList.ensureCapacity(0);
		Assert.assertEquals(0, intList.size());

		// Pre-grow to capacity for 500 elements
		intList.ensureCapacity(500);
		// Add 500 elements and assert size; this should work without errors
		for (int i = 0; i < 500; i++)
		{
			intList.add(i);
		}
		Assert.assertEquals(500, intList.size());
		// Spot check a few values
		Assert.assertEquals(0, intList.get(0));
		Assert.assertEquals(123, intList.get(123));
		Assert.assertEquals(499, intList.get(499));
	}

	@Test
	public void ensureCapacityIdempotentForSmaller()
	{
		PrimitiveIntList intList = new PrimitiveIntList(4);
		intList.add(1);
		intList.add(2);
		intList.ensureCapacity(2); // already at least 2; should not affect size
		Assert.assertEquals(2, intList.size());
		Assert.assertEquals(1, intList.get(0));
		Assert.assertEquals(2, intList.get(1));
	}
}

package gps;

import com.google.gson.Gson;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertTrue;

/**
 * The overlay's route across a REAL generation (real service, real threads), sampled at high
 * frequency from a render-like thread: for a fresh destination the overlay must show nothing
 * while the generation streams and then the settled best — one appearance, no flicker through
 * the re-sorted list.
 */
public class ProvisionalDisplayLiveTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3221, 3219, 0);
	private static final int GRAND_EXCHANGE = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	/** Capture 20260822-163446: Lumbridge -> Civitas illa Fortis, 10 chain routes + seeds + a 383 ms walk. */
	private static final int CIVITAS = WorldPointUtil.packWorldPoint(1687, 3141, 0);

	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}


	private static List<String> sampleGeneration(int start, int target, AlternativeRoutesMode mode) throws Exception
	{
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.currencyThreshold()).thenReturn(10000000);
		Mockito.when(cfg.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY);
		for (String name : new String[]{"useSpiritTrees", "useHotAirBalloons", "useSailing"})
		{
			Mockito.when((Boolean) ShortestPathConfig.class.getMethod(name).invoke(cfg)).thenReturn(true);
		}
		Mockito.when(cfg.defaultRouteCount()).thenReturn(10);
		PathfinderConfig planning = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		planning.refresh();
		// The service refreshes on "the client thread": the test thread here, via a direct-run mock.
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, planning);

		// The controller over a mocked plugin: the config, the destination and the identity order;
		// the saved mode comes through the choice store as at startup.
		Set<Integer> targets = Set.of(target);
		ShortestPathPlugin plugin = Mockito.mock(ShortestPathPlugin.class);
		Mockito.when(plugin.getGpsConfig()).thenReturn(cfg);
		Mockito.when(plugin.getPathTargets()).thenReturn(targets);
		Mockito.when(plugin.sortByEffectiveOrder(Mockito.any())).thenAnswer(i -> i.getArgument(0));
		ConfigManager configManager = Mockito.mock(ConfigManager.class);
		Mockito.when(configManager.getConfiguration("gps", ChoiceStore.CONFIG_KEY_MODE)).thenReturn(mode.name());
		ChoiceStore choices = new ChoiceStore(() -> configManager, Gson::new, "gps");
		RouteSession session = new RouteSession();
		RouteController routes = new RouteController(plugin, session, new MethodExclusions(choices, ProvisionalDisplayLiveTest::noop), choices,
			new PluginMessageBridge(plugin, () -> null));
		routes.start(service);

		// Sample what the overlay would draw, as fast as a render loop and then some.
		List<String> trace = new ArrayList<>();
		Thread sampler = new Thread(() ->
		{
			RouteOption last = null;
			boolean started = false;
			boolean sawFinding = false;
			long until = System.currentTimeMillis() + 30000;
			while (System.currentTimeMillis() < until)
			{
				try
				{
					boolean inFlight = session.inFlight();
					started |= inFlight;
					RouteOption now = session.displayed(targets);
					// The initial empty state is only "seen" once the generation is in flight.
					if (!sawFinding && now == null && session.isFinding(targets))
					{
						sawFinding = true;
						synchronized (trace)
						{
							trace.add("null [finding] [in-flight]");
						}
					}
					if (now != last)
					{
						synchronized (trace)
						{
							trace.add((now == null ? "null" : now.getTotalCost() + " " + now.getMethods())
								+ (session.isFinding(targets) ? " [finding]" : "")
								+ (inFlight ? " [in-flight]" : ""));
						}
						last = now;
					}
					if (started && !inFlight)
					{
						break;
					}
					Thread.sleep(0, 200_000);
				}
				catch (Exception e)
				{
					throw new RuntimeException(e);
				}
			}
		});
		sampler.start();

		routes.trigger(start, new HashSet<>(targets));
		sampler.join(40000);
		service.shutdown();
		synchronized (trace)
		{
			return new ArrayList<>(trace);
		}
	}

	private static void assertOneAppearance(List<String> trace)
	{
		int routeChanges = 0;
		for (String t : trace)
		{
			if (!t.startsWith("null"))
			{
				routeChanges++;
			}
		}
		assertTrue("the overlay must stay empty while finding and then show the settled route once; saw " + trace,
			routeChanges == 1);
		assertTrue("the finding state must be visible before the list settles; saw " + trace,
			trace.stream().anyMatch(t -> t.startsWith("null") && t.contains("[finding]")));
	}

	@Test
	public void lumbridgeToGrandExchange() throws Exception
	{
		assertOneAppearance(sampleGeneration(LUMBRIDGE, GRAND_EXCHANGE, AlternativeRoutesMode.OWNED_INVENTORY));
	}

	@Test
	public void lumbridgeToCivitasEverything() throws Exception
	{
		assertOneAppearance(sampleGeneration(LUMBRIDGE, CIVITAS, AlternativeRoutesMode.ALL_EVERYTHING));
	}

	/** A no-op callback (checkstyle wants a block's braces on their own lines, so no inline lambda). */
	private static void noop()
	{
	}
}

package gps;

import com.google.gson.Gson;
import gps.pathfinder.PathStep;
import gps.transport.TransportType;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The overlay's route while a generation streams: for a fresh destination NOTHING is shown, the
 * HUD is in its "Finding the best route" state, until the generation settles, when the best
 * route appears once. Front-runners streamed mid-generation never reach the overlay. A
 * same-destination regeneration keeps the committed route on screen throughout. Exercised
 * through the controller's real trigger and update over a mocked plugin (review of 2026-09-12:
 * previously by reflection on a bare plugin instance).
 */
@RunWith(MockitoJUnitRunner.class)
public class ProvisionalDisplayTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	private static final Set<Integer> TARGETS = Set.of(TARGET);
	private static final TeleportMethod TABLET =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Varrock tablet", TARGET);
	private static final TeleportMethod SPELL =
		new TeleportMethod(TransportType.TELEPORTATION_SPELL, "Varrock Teleport", TARGET);

	@Mock
	ShortestPathPlugin plugin;
	@Mock
	ShortestPathConfig config;
	@Mock
	ConfigManager configManager;
	@Mock
	AlternativeRoutesService service;

	private RouteSession session;
	private RouteController routes;

	@Before
	public void before()
	{
		when(plugin.getGpsConfig()).thenReturn(config);
		when(config.defaultRouteCount()).thenReturn(10);
		// The effective order is the identity here: the lists arrive already ordered.
		when(plugin.sortByEffectiveOrder(any())).thenAnswer(i -> i.getArgument(0));
		ChoiceStore choices = new ChoiceStore(() -> configManager, Gson::new, "gps");
		session = new RouteSession();
		routes = new RouteController(plugin, session, new MethodExclusions(choices, ProvisionalDisplayTest::noop), choices,
			new PluginMessageBridge(plugin, () -> null));
		routes.start(service);
	}

	private void trigger()
	{
		routes.trigger(START, new HashSet<>(TARGETS));
	}

	private void update(List<RouteOption> list, boolean done)
	{
		routes.onUpdate(list, List.of(), Map.of(), done);
	}

	/** What the overlay draws for the destination. */
	private RouteOption displayed()
	{
		return session.displayed(TARGETS);
	}

	/** Whether the HUD is in its finding state for the destination. */
	private boolean finding()
	{
		return session.isFinding(TARGETS);
	}

	private static RouteOption route(int cost, TeleportMethod method)
	{
		List<PathStep> path = List.of(new PathStep(START, false), new PathStep(TARGET, false));
		return new RouteOption(path, List.of(method), List.of(1), List.of(1), cost, cost, true,
			Set.of(), List.of(0), 0);
	}

	@Test
	public void freshDestinationStaysClearUntilTheListSettles()
	{
		RouteOption first = route(100, SPELL);
		RouteOption cheaper = route(50, TABLET);
		RouteOption middle = route(70, SPELL);

		trigger();
		assertTrue("a generation is in flight", session.inFlight());
		assertNull("nothing on the overlay before the routes settle", displayed());
		assertTrue("the HUD is in its finding state", finding());

		update(List.of(first), false);
		assertNull("the first route found is NOT shown: it may still change", displayed());
		assertTrue(finding());
		update(List.of(cheaper, first), false);
		update(List.of(cheaper, middle, first), false);
		assertNull("front-runners mid-stream never reach the overlay", displayed());
		assertTrue(finding());

		update(List.of(cheaper, middle, first), true);
		assertSame("settled: the final best appears, once", cheaper, displayed());
		assertFalse("finding state over", finding());
		assertFalse(session.inFlight());
	}

	@Test
	public void sameDestinationRegenerationKeepsTheCommittedRoute()
	{
		RouteOption settled = route(50, TABLET);
		RouteOption newer = route(40, SPELL);

		trigger();
		update(List.of(settled), false);
		update(List.of(settled), true);
		assertSame(settled, displayed());

		// Off-route recalc / method toggle: same targets, the overlay holds the committed route
		// steadily while the fresh list streams: no blank, no finding state.
		trigger();
		assertSame("committed route survives the regeneration start", settled, displayed());
		assertFalse("a held route is not a finding state", finding());
		update(List.of(newer), false);
		assertSame("streaming does not swap the held route", settled, displayed());
		update(List.of(newer), true);
		assertSame("settles to the new best once", newer, displayed());
	}

	/** A no-op callback (checkstyle wants a block's braces on their own lines, so no inline lambda). */
	private static void noop()
	{
	}
}

package gps;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * ARCHITECTURAL GUARD: live player position must flow through the boat-aware
 * {@code WorldPointUtil.fromLocalInstance(Client, Player)} overload. Aboard a boat the raw
 * player position lives in the boat's sub-WorldView (template-band coordinates), and the raw
 * idioms below regressed independently THREE times — the plugin's recalc start, the debug
 * snapshot, and the progress tracker — each one silently breaking the moment a player
 * boarded. A new use of these idioms in main sources is a test failure, not a field capture.
 */
public class RawPlayerPositionGuardTest
{
	private static final String[] FORBIDDEN = {
		".getLocalPlayer().getWorldLocation()",
		"fromLocalInstance(client, player.getLocalLocation())",
		"fromLocalInstance(client, local.getLocalLocation())",
	};

	@Test
	public void mainSourcesNeverReadRawPlayerPosition() throws IOException
	{
		List<String> offenders = new ArrayList<>();
		try (Stream<Path> files = Files.walk(Path.of("src/main/java/gps")))
		{
			for (Path file : (Iterable<Path>) files.filter(
				f -> f.toString().endsWith(".java"))::iterator)
			{
				// The overload itself legitimately reads the raw local as its ashore fallback.
				if (file.getFileName().toString().equals("WorldPointUtil.java"))
				{
					continue;
				}
				String source = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
				for (String idiom : FORBIDDEN)
				{
					if (source.contains(idiom))
					{
						offenders.add(file.getFileName() + ": " + idiom);
					}
				}
			}
		}
		assertTrue("Raw player-position idioms break aboard a boat; route through"
			+ " WorldPointUtil.fromLocalInstance(client, player):\n  "
			+ String.join("\n  ", offenders), offenders.isEmpty());
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.lang.management.ManagementFactory;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N3: the per-search availability rebuild must not allocate a method identity per
 * transport. Every chain iteration, seed, tail and walk search calls
 * rebuildAvailabilityWithExclusions, which built a fresh TeleportMethod for every transport in
 * both base lists just to test set membership (~12,000 throwaway objects per rebuild, ~19
 * rebuilds per generation), and TransportAvailability's builder allocated a key array per pass.
 */
@RunWith(MockitoJUnitRunner.class)
public class RebuildAllocationTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	/**
	 * Bytes one rebuild may allocate with exclusions present: the two origin maps of each
	 * availability are cloned (four clones of an int[] plus an Object[] at ~16K capacity) and the
	 * touched origins get a new array. Baseline before N3: 4,017,408 bytes.
	 */
	static final long BYTES_PER_REBUILD_BUDGET = 800_000;

	private static com.sun.management.ThreadMXBean threadBean()
	{
		java.lang.management.ThreadMXBean bean = ManagementFactory.getThreadMXBean();
		Assume.assumeTrue(bean instanceof com.sun.management.ThreadMXBean);
		com.sun.management.ThreadMXBean sun = (com.sun.management.ThreadMXBean) bean;
		Assume.assumeTrue(sun.isThreadAllocatedMemorySupported());
		sun.setThreadAllocatedMemoryEnabled(true);
		return sun;
	}

	@Test
	public void rebuildWithExclusionsDoesNotAllocateAMethodPerTransport()
	{
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		lenient().when(config.useSpiritTrees()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(true);
		planning.setBypassItemPossession(true);
		planning.refresh();
		List<TeleportMethod> catalog = new java.util.ArrayList<>(planning.getMethodCatalog());
		assertTrue("premise: a catalog to exclude from", catalog.size() > 50);
		// Four origin-less teleports and four origin-bound transports, so both the teleport array
		// and the copy-on-write origin maps are exercised.
		Set<TeleportMethod> excluded = new HashSet<>(catalog.subList(0, 4));
		List<Transport> originBound = new java.util.ArrayList<>();
		planning.getTransportsPacked(false).forEach((origin, transports) ->
		{
			if (originBound.size() < 4)
			{
				originBound.add(transports[0]);
			}
		});
		assertTrue("premise: origin-bound transports to exclude", originBound.size() == 4);
		for (Transport transport : originBound)
		{
			excluded.add(transport.method());
		}

		planning.rebuildAvailabilityWithExclusions(excluded);
		for (Transport transport : originBound)
		{
			Transport[] left = planning.getTransportsPacked(false).getOrDefault(transport.getOrigin(), new Transport[0]);
			for (Transport candidate : left)
			{
				assertTrue("an excluded transport must be gone from its origin", !excluded.contains(candidate.method()));
			}
		}
		planning.rebuildAvailabilityWithExclusions(Set.of());
		for (Transport transport : originBound)
		{
			Transport[] restored = planning.getTransportsPacked(false).get(transport.getOrigin());
			assertTrue("the base availability must be intact afterwards", java.util.Arrays.asList(restored).contains(transport));
		}

		com.sun.management.ThreadMXBean bean = threadBean();
		long thread = Thread.currentThread().getId();
		// Warm up, then measure the steady state of one rebuild each way.
		planning.rebuildAvailabilityWithExclusions(excluded);
		planning.rebuildAvailabilityWithExclusions(Set.of());
		long before = bean.getThreadAllocatedBytes(thread);
		planning.rebuildAvailabilityWithExclusions(excluded);
		long withExclusions = bean.getThreadAllocatedBytes(thread) - before;
		before = bean.getThreadAllocatedBytes(thread);
		planning.rebuildAvailabilityWithExclusions(Set.of());
		long without = bean.getThreadAllocatedBytes(thread) - before;
		System.out.println("REBUILDALLOC with 8 exclusions: " + withExclusions + " bytes; without: " + without + " bytes");

		assertTrue("a rebuild with exclusions allocated " + withExclusions + " bytes (budget "
			+ BYTES_PER_REBUILD_BUDGET + ")", withExclusions < BYTES_PER_REBUILD_BUDGET);
		assertTrue("with nothing excluded the base availability must be shared, not rebuilt: " + without + " bytes",
			without < 10_000);
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Captures 20260823-213943 and -215617: most routes were "Quetzal whistle to some site, quetzal
 * back to Civitas, charter to Port Tyras" — pointless variants of the direct "Whistle to Civitas,
 * charter" (the whistle already lands at any built site), one per whistle destination the
 * exclusion chain tried. The filter's baseline is captured before the chain's own exclusion
 * rebuilds: the chain removes the direct whistle right before generating its hop variants, so a
 * live-availability check found nothing (the second capture, on the first cut of this filter).
 */
public class RedundantTeleportHopTest
{
	private static final int CIVITAS_LANDING = WorldPointUtil.packWorldPoint(1697, 3140, 0);
	private static final int QUETZACALLI_LANDING = WorldPointUtil.packWorldPoint(1510, 3222, 0);
	private static final int PRIMIO_VARROCK_LANDING = WorldPointUtil.packWorldPoint(3280, 3412, 0);

	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	private static PathfinderConfig planning(ShortestPathConfig cfg)
	{
		PathfinderConfig planning = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static ShortestPathConfig config()
	{
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.currencyThreshold()).thenReturn(10000000);
		Mockito.when(cfg.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		return cfg;
	}

	@Test
	public void whistleThenQuetzalBackIsRedundantButPrimioIsNot()
	{
		PathfinderConfig planning = planning(config());
		List<Transport> baseline = AlternativeRoutesService.teleportHopBaseline(planning, Set.of());
		assertTrue("the baseline must hold the whistle teleports", !baseline.isEmpty());
		TeleportMethod whistleToQuetzacalli = new TeleportMethod(
			TransportType.QUETZAL_WHISTLE, "Quetzal whistle: Quetzacalli Gorge", QUETZACALLI_LANDING);
		TeleportMethod whistleToCivitas = new TeleportMethod(
			TransportType.QUETZAL_WHISTLE, "Quetzal whistle: Civitas illa Fortis", CIVITAS_LANDING);
		TeleportMethod quetzalToCivitas = new TeleportMethod(
			TransportType.QUETZAL, "Civitas illa Fortis", CIVITAS_LANDING);
		TeleportMethod primioToVarrock = new TeleportMethod(
			TransportType.QUETZAL, "Primio: Varrock", PRIMIO_VARROCK_LANDING);
		TeleportMethod charter = new TeleportMethod(
			TransportType.CHARTER_SHIP, "Port Tyras", WorldPointUtil.packWorldPoint(2142, 3122, 0));

		assertTrue("whistle -> quetzal back to a whistle-reachable site is the hop to drop",
			RouteAcceptance.hasRedundantTeleportHop(baseline,
				List.of(whistleToQuetzacalli, quetzalToCivitas, charter)));
		assertFalse("Varrock has no whistle landing: the Primio flight is a REAL leg",
			RouteAcceptance.hasRedundantTeleportHop(baseline,
				List.of(whistleToQuetzacalli, primioToVarrock)));
		assertFalse("unrelated method pairs are untouched",
			RouteAcceptance.hasRedundantTeleportHop(baseline,
				List.of(quetzalToCivitas, charter)));

		// A USER exclusion of the direct whistle makes its hop variants legitimate alternatives.
		List<Transport> withoutCivitas =
			AlternativeRoutesService.teleportHopBaseline(planning, Set.of(whistleToCivitas));
		assertFalse("with the direct whistle excluded by the user, the hop is a real route",
			RouteAcceptance.hasRedundantTeleportHop(withoutCivitas,
				List.of(whistleToQuetzacalli, quetzalToCivitas, charter)));
	}

	/**
	 * Capture 20260823-215617's exact query (Grand Exchange -> Zul-Andra): from the GE the whistle
	 * is the cheapest entry to Varlamore, so the chain excludes it and, before the baseline fix,
	 * emitted one whistle-hop variant per landing site. No emitted route may carry the hop.
	 */
	@Test
	public void capturedQueryNoLongerEmitsWhistleHopVariants() throws Exception
	{
		PathfinderConfig planning = planning(config());
		List<Transport> baseline = AlternativeRoutesService.teleportHopBaseline(planning, Set.of());
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, planning);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(3162, 3486, 0),
			Set.of(WorldPointUtil.packWorldPoint(2207, 3159, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		service.shutdown();
		List<RouteOption> routes = out.get();
		assertTrue("routes expected", routes != null && !routes.isEmpty());
		boolean reached = false;
		for (RouteOption route : routes)
		{
			assertFalse("no route may keep a redundant whistle hop: " + route.getMethods(),
				RouteAcceptance.hasRedundantTeleportHop(baseline, route.getMethods()));
			reached |= route.isReached();
		}
		assertTrue("the target stays reachable with the junk variants filtered", reached);
	}
}

