		if (t == float.class)
		{
			return 0f;
		}
		if (t == char.class)
		{
			return (char) 0;
		}
		return null;
	}

	@Before
	public void before()
	{
		final Thread ct = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return ct;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		clientThread = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(clientThread, config);
	}

	@After
	public void after()
	{
		service.shutdown();
	}

	private List<RouteOption> generate(AlternativeRoutesService svc, int limit, int multiple,
		List<List<Integer>> streamedCosts) throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		svc.generate(LUMBRIDGE, Set.of(BARROWS), Set.of(), AlternativeRoutesMode.ALL_EVERYTHING,
			limit, multiple, false,
			(routes, catalog, unavailable, done) ->
			{
				if (streamedCosts != null)
				{
					List<Integer> costs = new ArrayList<>();
					for (RouteOption r : routes)
					{
						costs.add(r.getTotalCost());
					}
					streamedCosts.add(costs);
				}
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		return out.get();
	}

	private static List<Integer> costs(List<RouteOption> routes)
	{
		List<Integer> costs = new ArrayList<>();
		for (RouteOption r : routes)
		{
			costs.add(r.getTotalCost());
		}
		return costs;
	}

	@Test
	public void wideningResumesAndNeverBlanksThePage() throws Exception
	{
		List<RouteOption> first = generate(service, 10, 3, null);
		assertNotNull(first);
		assertFalse("the narrow run must find routes", first.isEmpty());
		List<Integer> firstCosts = costs(first);

		// Widen ("+"): same start/targets/mode/exclusions, bigger limit and multiple.
		List<List<Integer>> streamed = new CopyOnWriteArrayList<>();
		List<RouteOption> widened = generate(service, 20, 6, streamed);
		assertNotNull(widened);

		// Continuity: every update (including the first) carries at least the narrow run's routes,
		// unchanged and in order — the page never blanks and never loses what it showed.
		assertFalse("the widened run must stream updates", streamed.isEmpty());
		for (List<Integer> update : streamed)
		{
			assertTrue("an update lost routes (page blanked): " + update,
				update.size() >= firstCosts.size());
			assertEquals("the previously shown routes must stay, unchanged and in order",
				firstCosts, update.subList(0, firstCosts.size()));
		}
		assertTrue("widening must add routes past the narrow page (got "
			+ widened.size() + " vs " + first.size() + ")", widened.size() > first.size());

		// Parity: a from-scratch service at the wide settings finds the same number of routes, and
		// the resumed run is never worse slot-for-slot. (Exact multiset equality is too strict: the
		// parallel seed pass fills the marginal last slots in completion order, so the two runs can
		// legitimately differ there — the resumed run keeping a cheaper marginal route is fine, and with the
		// tail-saturation cap a couple of ticks either way on a marginal slot is completion-order
		// noise, not a regression.)
		AlternativeRoutesService fresh = new AlternativeRoutesService(clientThread, config);
		try
		{
			List<RouteOption> scratch = generate(fresh, 20, 6, null);
			List<Integer> a = costs(widened);
			List<Integer> b = costs(scratch);
			a.sort(Integer::compareTo);
			b.sort(Integer::compareTo);
			assertEquals("resumed and from-scratch runs must find the same number of routes",
				b.size(), a.size());
			for (int i = 0; i < a.size(); i++)
			{
				assertTrue("resumed run must never be meaningfully worse than from-scratch at slot " + i
					+ " (" + a.get(i) + " vs " + b.get(i) + ")", a.get(i) <= b.get(i) + 4);
			}
		}
		finally
		{
			fresh.shutdown();
		}
	}

	/**
	 * Resuming from a TINY prior generation must not silently drop routes. A panel-hidden generation
	 * computes only the primary route (limit 1), and its seed pass records signatures for routes it
	 * can't fit; the full generation that follows (panel opens / Quest Helper sets a target) resumes
	 * from it. If those burned signatures carried over, the wide run rejected cheap routes it found
	 * — the user capture where a Quest-Helper target showed 6 routes (missing the 2nd-cheapest) while
	 * a plain refresh showed 10. It must match a from-scratch wide run.
	 */
	@Test
	public void resumingFromATinyGenerationLosesNoRoutes() throws Exception
	{
		List<RouteOption> tiny = generate(service, 1, 3, null);
		assertNotNull(tiny);
		assertEquals("the panel-hidden run shows only the primary route", 1, tiny.size());

		List<RouteOption> resumed = generate(service, 10, 3, null);
		assertNotNull(resumed);

		AlternativeRoutesService fresh = new AlternativeRoutesService(clientThread, config);
		try
		{
			List<RouteOption> scratch = generate(fresh, 10, 3, null);
			List<Integer> a = costs(resumed);
			List<Integer> b = costs(scratch);
			a.sort(Integer::compareTo);
			b.sort(Integer::compareTo);
			assertEquals("resuming from a limit-1 generation must find as many routes as from scratch"
				+ " (resumed " + a + " vs scratch " + b + ")", b.size(), a.size());
			for (int i = 0; i < a.size(); i++)
			{
				assertTrue("resumed run must never be meaningfully worse than from-scratch at slot " + i
					+ " (" + a.get(i) + " vs " + b.get(i) + ")", a.get(i) <= b.get(i) + 4);
			}
		}
		finally
		{
			fresh.shutdown();
		}
	}
}

package gps;

import gps.transport.TransportType;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Plan step L1: the page acceptance rule (closeness, the hybrid cost band with its page-fill
 * ceiling, and eviction when the page is full) was copied three times inside the generator (the
 * exclusion chain, the seed pass, the tail-diversity pass) with small drifts between the copies.
 * It is one set of pure functions now, pinned here; the generator's own tests keep the wiring.
 */
public class RouteAcceptanceTest
{
	private static final TeleportMethod TELEPORT = new TeleportMethod(TransportType.TELEPORTATION_SPELL, "Varrock Teleport", 1);
	private static final TeleportMethod PORT = new TeleportMethod(TransportType.SAILING, "Disembark at Port Khazard", 2);
	private static final TeleportMethod SAIL = new TeleportMethod(TransportType.SAILING, "Sail to the pin", 3);

	private static RouteOption route(int cost, TeleportMethod... methods)
	{
		return new RouteOption(List.of(), List.of(methods), List.of(), List.of(), cost, cost, true, Set.of(), List.of(), 0);
	}

	private static List<RouteOption> page(int... costs)
	{
		List<RouteOption> routes = new ArrayList<>();
		for (int cost : costs)
		{
			routes.add(route(cost, TELEPORT));
		}
		return routes;
	}

	@Test
	public void theBandOnlyAppliesOnceThePageHasAMinimum()
	{
		// Three routes: no band yet, whatever the cost.
		assertFalse(RouteAcceptance.beyondBand(10_000, page(10, 20, 30), 3));
		// Four routes, best 10: the band prices off max(best, 35) * 3 = 105.
		assertFalse("inside the band", RouteAcceptance.beyondBand(105, page(10, 20, 30, 40), 3));
		assertFalse("just past the band but within the page-fill gap of the band",
			RouteAcceptance.beyondBand(115, page(10, 20, 30, 40), 3));
		assertTrue("a cliff past the band", RouteAcceptance.beyondBand(200, page(10, 20, 30, 40), 3));
		assertFalse("no multiple, no band", RouteAcceptance.beyondBand(200, page(10, 20, 30, 40), 0));
	}

	@Test
	public void thePageFillCeilingRatchetsWithTheCostliestAcceptedRoute()
	{
		// Band 105, costliest accepted 150: the ceiling follows the cluster (150 + max(10, 150/8)).
		List<RouteOption> routes = page(10, 100, 120, 150);
		assertFalse(RouteAcceptance.beyondBand(165, routes, 3));
		assertTrue(RouteAcceptance.beyondBand(190, routes, 3));
		assertEquals(168L, RouteAcceptance.pageFillCeiling(10, 150, 3));
	}

	@Test
	public void theChainStopsAtTheLimitPastTheBandWhileSeedsMayEvict()
	{
		List<RouteOption> full = page(10, 20, 30, 40);
		// Past the band with the page at its limit: the chain has nothing to evict, so it stops.
		assertTrue(RouteAcceptance.beyondBand(110, full, 3, 4));
		// The seed form never stops on the limit: it can evict a costlier entry.
		assertFalse(RouteAcceptance.beyondBand(110, full, 3));
	}

	@Test
	public void closenessRules()
	{
		// The best route reached: an unreached result is a cap truncation, never a route.
		assertTrue(RouteAcceptance.tooFar(false, 3, 0));
		assertFalse(RouteAcceptance.tooFar(true, 0, 0));
		// No best yet: anything goes, the caller records it as the best.
		assertFalse(RouteAcceptance.tooFar(false, 500, -1));
		// An unreachable target: routes must end about as close as the best approach.
		assertFalse(RouteAcceptance.tooFar(false, 25, 20));
		assertTrue(RouteAcceptance.tooFar(false, 31, 20));
	}

	@Test
	public void evictionPicksTheCostliestEvictableRouteAndNeverTheSolePortFirstOne()
	{
		List<RouteOption> routes = new ArrayList<>();
		routes.add(route(20, TELEPORT));
		routes.add(route(400, PORT, TELEPORT));
		routes.add(route(300, TELEPORT));
		routes.add(route(50));
		// Any cost: the costliest evictable is index 2 (400 is the sole port-first route, 50 is walk-only).
		assertEquals(2, RouteAcceptance.evictionIndex(routes, -1, r -> !r.isWalkOnly()));
		// Only routes strictly costlier than the candidate qualify.
		assertEquals(-1, RouteAcceptance.evictionIndex(routes, 300, r -> !r.isWalkOnly()));
		assertEquals(2, RouteAcceptance.evictionIndex(routes, 299, r -> !r.isWalkOnly()));
		// With two port-first routes neither is protected.
		routes.add(route(450, PORT, SAIL));
		assertEquals(4, RouteAcceptance.evictionIndex(routes, -1, r -> !r.isWalkOnly()));
		// The predicate can protect anything else (the pure-sail baseline, a family).
		assertEquals(1, RouteAcceptance.evictionIndex(routes, -1, r -> !r.isWalkOnly() && !r.isPureSail()));
	}

	@Test
	public void portFirstHelpers()
	{
		List<RouteOption> routes = new ArrayList<>();
		routes.add(route(20, TELEPORT));
		assertFalse(RouteAcceptance.hasPortFirstRoute(routes));
		assertEquals(-1, RouteAcceptance.solePortFirstIndex(routes));
		routes.add(route(40, PORT));
		assertTrue(RouteAcceptance.hasPortFirstRoute(routes));
		assertEquals(1, RouteAcceptance.solePortFirstIndex(routes));
	}
}

package gps;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Review 2026-09-06: the pohMount*, sailingAssumeSummon and sailingTeleportAbandon toggles did
 * nothing when flipped because the plugin's "route-affecting keys" list was a hand-maintained
 * regex that never learned them. This test derives the set the routing engine actually reads
 * from its sources and fails the moment a key is missing from the list.
 */
public class RouteAffectingKeysTest
{
	private static final Pattern OVERRIDE_READ = Pattern.compile("override\\(\"(\\w+)\"");
	private static final Pattern DIRECT_READ = Pattern.compile("\\bconfig\\.(\\w+)\\(\\)");

	/** Config reads inside the engine that do NOT change what routing computes. */
	private static final Set<String> NOT_ROUTING = Set.of(
		"rememberBank" // persistence only: whether the bank snapshot is stored across sessions
	);

	@Test
	public void everyKeyTheEngineReadsRegeneratesRoutes() throws IOException
	{
		Set<String> keys = new TreeSet<>();
		for (String source : List.of(
			"src/main/java/gps/pathfinder/PathfinderConfig.java",
			"src/main/java/gps/transport/TransportTypeConfig.java"))
		{
			String text = Files.readString(Paths.get(source), StandardCharsets.UTF_8);
			for (Pattern pattern : List.of(OVERRIDE_READ, DIRECT_READ))
			{
				Matcher m = pattern.matcher(text);
				while (m.find())
				{
					keys.add(m.group(1));
				}
			}
		}
		assertTrue("the scan must find the engine's config reads", keys.size() > 20);

		Set<String> missing = new TreeSet<>();
		for (String key : keys)
		{
			if (!NOT_ROUTING.contains(key) && !ConfigOverrides.affectsRouting(key))
			{
				missing.add(key);
			}
		}
		assertTrue("routing reads these keys but a change to them never recomputes: " + missing, missing.isEmpty());
	}

	@Test
	public void theFieldToggles()
	{
		for (String key : List.of("pohMountGlory", "pohMountXerics", "pohMountDigsite", "pohMountMythical",
			"sailingAssumeSummon", "sailingTeleportAbandon", "useCharterShips", "costSailing", "avoidWilderness"))
		{
			assertTrue(key + " must regenerate routes", ConfigOverrides.affectsRouting(key));
		}
		// Display order only: handled by a re-sort, not a regeneration.
		assertFalse(ConfigOverrides.affectsRouting("sailingKeepSailing"));
		assertFalse(ConfigOverrides.affectsRouting("colourPath"));
		assertFalse(ConfigOverrides.affectsRouting(null));
	}

	@Test
	public void pluginMessageOverridesOnlyAcceptDeclaredKeys()
	{
		TestConfigKeys.declare();
		Set<String> known = ConfigOverrides.knownKeys();
		assertTrue(known.contains("avoidWilderness"));
		assertTrue(known.contains("useTeleportationItems"));
		assertFalse("a typo must be rejected, not stored forever", known.contains("avoidWildernes"));
		assertTrue("the declared surface is large", known.size() > 100);
	}

	/** Guard for the source scan: the files exist where the test expects them. */
	@Test
	public void engineSourcesExist()
	{
		Path p = Paths.get("src/main/java/gps/pathfinder/PathfinderConfig.java");
		assertTrue(Files.exists(p));
	}
}

package gps;

import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Plan step L35: the generation controller, out of the plugin class. A mode change saves the
 * mode and regenerates once with the last inputs (the same mode again does nothing); opening the
 * panel re-checks the auto-compute decision, which fires once per target set and never before the
 * generator exists; show more widens both the route budget and the cost band before regenerating.
 */
@RunWith(MockitoJUnitRunner.class)
public class RouteControllerTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3200, 3200, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(3210, 3205, 0);

	@Mock
	ShortestPathPlugin plugin;
	@Mock
	ClientThread clientThread;
	@Mock
	ShortestPathConfig config;
	@Mock
	ConfigManager configManager;
	@Mock
	AlternativeRoutesService service;

	private RouteSession session;
	private RouteController controller;

	@Before
	public void setUp()
	{
		// The client thread runs inline: the controller hops to it from the panel's entry points.
		lenient().doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));
		lenient().doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));
		when(plugin.getClientThread()).thenReturn(clientThread);
		when(plugin.getGpsConfig()).thenReturn(config);
		when(config.defaultRouteCount()).thenReturn(10);

		ChoiceStore choices = new ChoiceStore(() -> configManager, Gson::new, "gps");
		MethodExclusions exclusions = new MethodExclusions(choices, RouteControllerTest::noop);
		session = new RouteSession();
		controller = new RouteController(plugin, session, exclusions, choices,
			new PluginMessageBridge(plugin, () -> null));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void aModeChangeSavesAndRegeneratesOnceWithTheLastInputs()
	{
		controller.start(service);
		controller.trigger(START, Set.of(TARGET));
		controller.setMode(AlternativeRoutesMode.ALL_EVERYTHING);
		controller.setMode(AlternativeRoutesMode.ALL_EVERYTHING);
		controller.setMode(null);

		verify(configManager).setConfiguration("gps", ChoiceStore.CONFIG_KEY_MODE, "ALL_EVERYTHING");
		ArgumentCaptor<Set<Integer>> targets = ArgumentCaptor.forClass(Set.class);
		ArgumentCaptor<AlternativeRoutesMode> modes = ArgumentCaptor.forClass(AlternativeRoutesMode.class);
		verify(service, times(2)).generate(eq(START), targets.capture(), any(), modes.capture(), anyInt(), anyInt(),
			anyBoolean(), any());
		assertEquals(List.of(AlternativeRoutesMode.OWNED_INVENTORY, AlternativeRoutesMode.ALL_EVERYTHING), modes.getAllValues());
		assertEquals("the same destination, regenerated under the new mode", Set.of(TARGET), targets.getAllValues().get(1));
		assertEquals(AlternativeRoutesMode.ALL_EVERYTHING, controller.mode());
	}

	@Test
	public void aRecomputeWithoutATargetOnlyDirtiesTheCatalog()
	{
		// Every bank close asks for a recompute; with no destination there is nothing to route, so
		// the catalog is marked for its debounced re-classification instead of a full generation.
		controller.start(service);
		when(plugin.getPathTargets()).thenReturn(Set.of());
		controller.recompute();
		verify(service, never()).generate(anyInt(), any(), any(), any(), anyInt(), anyInt(), anyBoolean(), any());
		assertTrue(controller.isCatalogDirty());
	}

	@Test
	public void openingThePanelRechecksTheAutoComputeDecisionOncePerTargetSet()
	{
		when(plugin.getPathTargets()).thenReturn(Set.of(TARGET));
		controller.maybeAutoCompute();
		verify(service, never()).generate(anyInt(), any(), any(), any(), anyInt(), anyInt(), anyBoolean(), any());

		when(plugin.altStart()).thenReturn(START);
		controller.start(service);
		controller.setPanelVisible(true);
		controller.setPanelVisible(true);
		controller.maybeAutoCompute();
		verify(service, times(1)).generate(eq(START), eq(Set.of(TARGET)), any(), any(), eq(10), anyInt(),
			anyBoolean(), any());
	}

	@Test
	public void showMoreWidensTheBudgetAndTheBandThenRegenerates()
	{
		controller.start(service);
		controller.trigger(START, Set.of(TARGET));
		// More routes are likely only once a non-empty page settled under a budget below the cap.
		when(service.wasMoreLikely()).thenReturn(true);
		when(plugin.sortByEffectiveOrder(any())).thenAnswer(i -> i.getArgument(0));
		RouteOption route = new RouteOption(List.of(), List.of(), List.of(), List.of(), 10, 10, true, Set.of(), List.of(), 0);
		controller.onUpdate(List.of(route), List.of(), Map.of(), true);
		assertTrue(controller.canLoadMore());
		controller.loadMore();

		ArgumentCaptor<Integer> limits = ArgumentCaptor.forClass(Integer.class);
		ArgumentCaptor<Integer> multiples = ArgumentCaptor.forClass(Integer.class);
		verify(service, times(2)).generate(eq(START), eq(Set.of(TARGET)), any(), any(), limits.capture(),
			multiples.capture(), anyBoolean(), any());
		assertTrue("the route budget grew", limits.getAllValues().get(1) > limits.getAllValues().get(0));
		assertTrue("the cost band grew", multiples.getAllValues().get(1) > multiples.getAllValues().get(0));
	}

	/** A no-op callback (checkstyle wants a block's braces on their own lines, so no inline lambda). */
	private static void noop()
	{
	}
}

