package gps;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The ETA/priority separation: the card's ETA is the route's FULL configured cost (travel time,
 * bank detour, and the implicit cost modifiers — charged items, transport type, currency), while
 * explicit priorities stay outside as the green/red chip. List order is always ETA + chip; no
 * hidden component may reorder cards (the Combat-bracelet capture: a 13s-looking route ranked
 * last because its charged-item surcharge was invisible).
 */
public class RouteEtaTest
{
	private static RouteOption route(int totalCost, int rawCost, boolean viaBank)
	{
		TeleportMethod method = new TeleportMethod(
			gps.transport.TransportType.TELEPORTATION_ITEM, "Test", 1);
		return new RouteOption(java.util.List.of(), java.util.List.of(method), java.util.List.of(),
			java.util.List.of(), totalCost, rawCost, true,
			viaBank ? java.util.Set.of(method) : java.util.Set.of(), java.util.List.of(), 0);
	}

	@Test
	public void etaIsTheFullConfiguredCostIncludingModifiers()
	{
		// rawCost 84 with a +30 surcharge (bank pickup or charged-item modifier): the ETA shows
		// the full 114 — the surcharge is never hidden from the number the user compares.
		assertEquals(114, RouteListView.routeEtaUnits(route(114, 84, true)));
		// No modifiers: ETA == raw travel cost.
		assertEquals(104, RouteListView.routeEtaUnits(route(104, 104, false)));
	}

	/**
	 * The directions overlay's bank-withdraw step must count the same bank time the search put
	 * into totalCost: {@code bankWithdrawTicks} in cost units tracks {@code max(0, pickup)}
	 * within one-tick granularity, and a negative modifier (a ranking preference) is no time.
	 */
	@Test
	public void directionsBankTicksMatchTheChargedPickup()
	{
		for (int cost : new int[]{0, 15, 16, 30, 100})
		{
			int chargedUnits = Math.max(0, cost);
			int overlayUnits = RouteDirections.bankWithdrawTicks(cost)
				* gps.pathfinder.CostUnits.UNITS_PER_TICK;
			assertTrue("bank time must agree for costBankPickup=" + cost
				+ " (charged " + chargedUnits + " vs overlay " + overlayUnits + ")",
				Math.abs(chargedUnits - overlayUnits) <= 1);
		}
		assertEquals(0, RouteDirections.bankWithdrawTicks(-50));
	}

}

package gps;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import javax.swing.ImageIcon;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The panel's icons are PNG resources under /icons (0.14.0 moved them out of Java2D code, which
 * the hub's review bot counted). route-icons.sha256 records every icon's pixels as they were
 * drawn, so the files must stay what the code produced, pixel for pixel. To accept a deliberate
 * change to an icon, re-record with -Dgps.recordIcons=true (the test then rewrites the file).
 */
public class RouteIconsTest
{
	private static final String HASHES = "src/test/resources/route-icons.sha256";

	@Test
	public void everyIconHasItsRecordedPixels() throws Exception
	{
		Map<String, BufferedImage> icons = allIcons();
		if (System.getProperty("gps.recordIcons") != null)
		{
			List<String> lines = new ArrayList<>();
			for (Map.Entry<String, BufferedImage> e : icons.entrySet())
			{
				lines.add(e.getKey() + "\t" + pixelHash(e.getValue()));
			}
			Files.write(Paths.get(HASHES), lines, StandardCharsets.UTF_8);
			return;
		}
		Map<String, String> expected = recorded();
		assertFalse("no recorded icons", expected.isEmpty());
		for (Map.Entry<String, String> e : expected.entrySet())
		{
			BufferedImage icon = icons.get(e.getKey());
			assertNotNull("recorded icon " + e.getKey() + " no longer exists", icon);
			assertEquals(e.getKey() + " changed pixels (re-record with -Dgps.recordIcons=true if intended)",
				e.getValue(), pixelHash(icon));
		}
		for (String name : icons.keySet())
		{
			assertTrue(name + " is not recorded: run with -Dgps.recordIcons=true", expected.containsKey(name));
		}
	}

	@Test
	public void iconsAreSixteenPixelSquares() throws Exception
	{
		for (Map.Entry<String, BufferedImage> e : allIcons().entrySet())
		{
			assertEquals(e.getKey() + " width", 16, e.getValue().getWidth());
			assertEquals(e.getKey() + " height", 16, e.getValue().getHeight());
		}
	}

	/**
	 * Every icon the class exposes, by field name (array entries as NAME_1, NAME_2, ...), plus the
	 * sidebar pin. Private destination icons are included: they reach the panel via
	 * {@link RouteIcons#destinationIcon}.
	 */
	static Map<String, BufferedImage> allIcons() throws Exception
	{
		Map<String, BufferedImage> icons = new LinkedHashMap<>();
		for (Field field : RouteIcons.class.getDeclaredFields())
		{
			if (!Modifier.isStatic(field.getModifiers()))
			{
				continue;
			}
			field.setAccessible(true);
			Object value = field.get(null);
			if (value instanceof ImageIcon)
			{
				icons.put(field.getName(), toBuffered((ImageIcon) value));
			}
			else if (value instanceof ImageIcon[])
			{
				ImageIcon[] array = (ImageIcon[]) value;
				for (int i = 0; i < array.length; i++)
				{
					icons.put(field.getName() + "_" + (i + 1), toBuffered(array[i]));
				}
			}
		}
		icons.put("gpsPin", RouteIcons.gpsPin());
		return icons;
	}

	private static BufferedImage toBuffered(ImageIcon icon)
	{
		return (BufferedImage) icon.getImage();
	}

	/** SHA-256 of the ARGB pixels in row-major order, as hex. */
	static String pixelHash(BufferedImage image) throws Exception
	{
		MessageDigest digest = MessageDigest.getInstance("SHA-256");
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int argb = image.getRGB(x, y);
				digest.update(new byte[]{(byte) (argb >>> 24), (byte) (argb >>> 16), (byte) (argb >>> 8), (byte) argb});
			}
		}
		StringBuilder hex = new StringBuilder();
		for (byte b : digest.digest())
		{
			hex.append(String.format("%02x", b));
		}
		return hex.toString();
	}

	private static Map<String, String> recorded() throws IOException
	{
		Map<String, String> expected = new LinkedHashMap<>();
		try (InputStream in = RouteIconsTest.class.getResourceAsStream("/route-icons.sha256"))
		{
			assertNotNull("route-icons.sha256 is missing from the test resources", in);
			Scanner scanner = new Scanner(in, "UTF-8");
			while (scanner.hasNextLine())
			{
				String[] fields = scanner.nextLine().split("\t");
				if (fields.length == 2)
				{
					expected.put(fields[0], fields[1]);
				}
			}
		}
		return expected;
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportLoader;
import gps.transport.TransportType;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The widget highlight follows the route's NEXT item step only: the first method edge the player
 * has not reached, when its transport is an item teleport. "Worn-only" is read from the item's
 * inventory options: an item with no option that uses it where it lies (the Camulet: Wear, Check)
 * teleports from the worn slot, so the bag copy gets an "Equip" tag.
 */
public class RouteItemCueTest
{
	private static final int CAMULET = 6707;

	private static Transport camulet()
	{
		Map<Integer, Set<Transport>> transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports,
			"# Destination\tmenuOption menuTarget objectID\tSkills\tItems\tQuests\tDuration\tDisplay info\tConsumable\tWilderness level\n"
				+ "3106 9315 2\t\t\t" + CAMULET + "=1\t\t4\tCamulet: Inside Enakhra's Temple\tF\t20\n",
			TransportType.TELEPORTATION_ITEM, 0);
		return transports.values().iterator().next().iterator().next();
	}

	private static Transport ring()
	{
		Map<Integer, Set<Transport>> transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports,
			"# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tQuests\tVarbits\tDuration\tDisplay info\n"
				+ "3106 9316 2\t3106 9317 2\tConfigure Fairy ring 29560\t\t\t\t5\tAKQ\n",
			TransportType.FAIRY_RING, 0);
		return transports.values().iterator().next().iterator().next();
	}

	private static Set<Integer> staves()
	{
		Set<Integer> staves = new java.util.HashSet<>();
		for (int id : ItemVariations.DRAMEN_STAFF.getIds())
		{
			staves.add(id);
		}
		return staves;
	}

	/** A four-step path with one method per listed edge (the Camulet's name for all of them). */
	private static RouteOption route(List<Integer> methodEdges)
	{
		List<PathStep> path = List.of(
			new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), false, 0),
			new PathStep(WorldPointUtil.packWorldPoint(3106, 9315, 2), false, 4),
			new PathStep(WorldPointUtil.packWorldPoint(3106, 9316, 2), false, 5),
			new PathStep(WorldPointUtil.packWorldPoint(3106, 9317, 2), false, 6));
		List<TeleportMethod> methods = new java.util.ArrayList<>();
		List<Integer> durations = new java.util.ArrayList<>();
		List<Integer> walkBefore = new java.util.ArrayList<>();
		for (int edge : methodEdges)
		{
			methods.add(new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Camulet: Inside Enakhra's Temple", path.get(edge).getPackedPosition()));
			durations.add(4);
			walkBefore.add(0);
		}
		return new RouteOption(path, methods, methodEdges, durations, 6, 6, true, Set.of(), walkBefore, 2);
	}

	@Test
	public void theNextItemStepNamesItsItemsUntilItIsPassed()
	{
		Transport camulet = camulet();
		RouteOption route = route(List.of(1));
		RouteItemCue cue = RouteItemCue.next(route, 0, (a, b) -> Set.of(camulet), true, Map.of());
		assertEquals(Set.of(CAMULET), cue.itemIds);
		assertTrue("the Camulet is operated, worn or not", cue.wornDone.isEmpty());
		assertNull("teleported: the step is behind the player", RouteItemCue.next(route, 1, (a, b) -> Set.of(camulet), true, Map.of()));
		assertNull("a route without methods has no item step", RouteItemCue.next(route(List.of()), 0, (a, b) -> Set.of(camulet), true, Map.of()));
		assertNull("no route", RouteItemCue.next(null, 0, (a, b) -> Set.of(camulet), true, Map.of()));
	}

	@Test
	public void aSpellStepNamesTheSpellAndNoItems()
	{
		Map<Integer, Set<Transport>> transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports,
			"# Destination\tmenuOption menuTarget objectID\tSkills\tItems\tQuests\tDuration\tDisplay info\tConsumable\tWilderness level\n"
				+ "3106 9315 2\t\t\tLAW_RUNE=1\t\t4\tVarrock Teleport: GE\tT\t20\n",
			TransportType.TELEPORTATION_SPELL, 0);
		Transport spell = transports.values().iterator().next().iterator().next();
		RouteItemCue cue = RouteItemCue.next(route(List.of(1)), 0, (a, b) -> Set.of(spell), true, Map.of());
		assertEquals("the spellbook is clicked, not the runes", Set.of(), cue.itemIds);
		assertEquals("Varrock Teleport: GE", cue.spell);
		assertNull("an item step names no spell", RouteItemCue.next(route(List.of(1)), 0, (a, b) -> Set.of(camulet()), true, Map.of()).spell);
	}

	@Test
	public void aStaffOrTomeStandingInForRunesMustBeWielded()
	{
		Map<Integer, Set<Transport>> transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports,
			"# Destination\tItems\tSkills\tQuests\tDuration\tDisplay info\tWilderness level\n"
				+ "3213 3424 0\tAIR_RUNE=3&&FIRE_RUNE=1&&LAW_RUNE=1\t25 Magic\t\t4\tVarrock Teleport\t20\n",
			TransportType.TELEPORTATION_SPELL, 0);
		Transport varrock = transports.values().iterator().next().iterator().next();
		RouteOption route = route(List.of(1));

		// Law runes and a Mystic air staff in the bag, a Tome of fire worn: both stand in for runes.
		Map<Integer, Integer> carried = Map.of(ItemID.LAWRUNE, 1, ItemID.MYSTIC_AIR_STAFF, 1, ItemID.TOME_OF_FIRE, 1);
		RouteItemCue cue = RouteItemCue.next(route, 0, (a, b) -> Set.of(varrock), true, carried);
		assertEquals("Varrock Teleport", cue.spell);
		assertEquals("the staff and the tome, which do nothing in the bag", Set.of(ItemID.MYSTIC_AIR_STAFF, ItemID.TOME_OF_FIRE), cue.itemIds);
		assertEquals("worn, they are done", cue.itemIds, cue.wornDone);

		// The runes themselves in the bag: no staff to point at, whatever else is carried.
		Map<Integer, Integer> runes = Map.of(ItemID.LAWRUNE, 1, ItemID.AIRRUNE, 3, ItemID.FIRERUNE, 1, ItemID.MYSTIC_AIR_STAFF, 1);
		assertEquals(Set.of(), RouteItemCue.next(route, 0, (a, b) -> Set.of(varrock), true, runes).itemIds);
		// Two air runes only: short, so the staff is still the way.
		Map<Integer, Integer> short2 = Map.of(ItemID.LAWRUNE, 1, ItemID.AIRRUNE, 2, ItemID.FIRERUNE, 1, ItemID.MYSTIC_AIR_STAFF, 1);
		assertEquals(Set.of(ItemID.MYSTIC_AIR_STAFF), RouteItemCue.next(route, 0, (a, b) -> Set.of(varrock), true, short2).itemIds);
	}

	@Test
	public void aFairyRingStepAsksForTheStaffUnlessTheDiaryWaivesIt()
	{
		Transport ring = ring();
		RouteItemCue cue = RouteItemCue.next(route(List.of(3)), 1, (a, b) -> Set.of(ring), true, Map.of());
		assertEquals("a Dramen or Lunar staff, any of them", staves(), cue.itemIds);
		assertEquals("the staff works worn: nothing to do once it is", staves(), cue.wornDone);
		assertNull("Lumbridge Elite done: the ring needs nothing", RouteItemCue.next(route(List.of(3)), 1, (a, b) -> Set.of(ring), false, Map.of()));
	}

	@Test
	public void theStaffIsAskedForOneMethodAhead()
	{
		// Camulet at edge 1, fairy ring at edge 3: while the Camulet is the next step, the staff is
		// already cued so it can be wielded before the ring, and the Camulet keeps its own rules.
		Transport camulet = camulet();
		Transport ring = ring();
		RouteOption route = route(List.of(1, 3));
		RouteItemCue cue = RouteItemCue.next(route, 0, (a, b) -> b.getPackedPosition() == route.getPath().get(1).getPackedPosition()
			? Set.of(camulet) : Set.of(ring), true, Map.of());
		Set<Integer> expected = new java.util.HashSet<>(staves());
		expected.add(CAMULET);
		assertEquals(expected, cue.itemIds);
		assertEquals("only the staff is done once worn", staves(), cue.wornDone);
		assertNull(cue.spell);
		assertEquals("the diary waives the staff ahead too", Set.of(CAMULET),
			RouteItemCue.next(route, 0, (a, b) -> b.getPackedPosition() == route.getPath().get(1).getPackedPosition()
				? Set.of(camulet) : Set.of(ring), false, Map.of()).itemIds);
	}

	@Test
	public void theBankStepIsWhereThePathTurnsBankedOnARouteViaTheBank()
	{
		List<PathStep> path = List.of(
			new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), false, 0),
			new PathStep(WorldPointUtil.packWorldPoint(3201, 3200, 0), false, 1),
			new PathStep(WorldPointUtil.packWorldPoint(3202, 3200, 0), true, 2),
			new PathStep(WorldPointUtil.packWorldPoint(3106, 9315, 2), true, 6));
		TeleportMethod camulet = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Camulet: Inside Enakhra's Temple", path.get(3).getPackedPosition());
		RouteOption viaBank = new RouteOption(path, List.of(camulet), List.of(3), List.of(4), 6, 6, true, Set.of(camulet), List.of(2), 0);
		assertEquals(2, RouteItemCue.bankStep(viaBank));
		RouteOption owned = new RouteOption(path, List.of(camulet), List.of(3), List.of(4), 6, 6, true, Set.of(), List.of(2), 0);
		assertEquals("a route that only passes a bank withdraws nothing", -1, RouteItemCue.bankStep(owned));
		assertEquals(-1, RouteItemCue.bankStep(null));
	}

	@Test
	public void anItemWithNoOptionThatUsesItFromTheBagIsWornOnly()
	{
		assertTrue("the Camulet: its teleports are worn options", RouteItemCue.wornOnly(new String[]{"Wear", "Check", null, null, null}));
		assertTrue(RouteItemCue.wornOnly(null));
		assertFalse("jewellery rubs from the bag", RouteItemCue.wornOnly(new String[]{"Rub", "Wear", null, null, null}));
		assertFalse("tablets break", RouteItemCue.wornOnly(new String[]{"Break", null, null, null, null}));
		assertFalse("capes teleport, whatever the destination word", RouteItemCue.wornOnly(new String[]{"Wear", "Monastery Teleport", null, null, null}));
	}
}

package gps;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Quest Helper draws its item ring from an always-on-top overlay, after the inventory's own draw
 * hook where this plugin's mark lands, and the two rings have the same shape: on an item both
 * plugins want, Quest Helper's covers ours. The mark is therefore the item's outline thickened by
 * one pixel outward, so a ring in this plugin's colour stays visible around Quest Helper's.
 */
public class RouteItemMarkTest
{
	private static final int GOLD = new Color(0xF2, 0xC1, 0x4E).getRGB();
	private static final int CYAN = Color.CYAN.getRGB();

	@Test
	public void theOutlineGrowsOneRingOutward()
	{
		// A one-pixel sprite at (2,2) and the client's ring around it: its eight neighbours.
		BufferedImage sprite = new BufferedImage(5, 5, BufferedImage.TYPE_INT_ARGB);
		sprite.setRGB(2, 2, Color.WHITE.getRGB());
		BufferedImage ring = new BufferedImage(5, 5, BufferedImage.TYPE_INT_ARGB);
		for (int x = 1; x <= 3; x++)
			for (int y = 1; y <= 3; y++)
				if (x != 2 || y != 2)
					ring.setRGB(x, y, CYAN);

		BufferedImage mark = RouteItemMark.thickened(sprite, ring, GOLD);

		assertEquals("one pixel of margin on each side", 7, mark.getWidth());
		assertEquals(7, mark.getHeight());
		Set<String> inner = new HashSet<>();
		Set<String> outer = new HashSet<>();
		Set<String> clear = new HashSet<>();
		for (int x = 0; x < 7; x++)
		{
			for (int y = 0; y < 7; y++)
			{
				int rgb = mark.getRGB(x, y);
				if (rgb == CYAN)
					inner.add(x + "," + y);
				else if (rgb == GOLD)
					outer.add(x + "," + y);
				else if ((rgb >>> 24) == 0)
					clear.add(x + "," + y);
				else
					throw new AssertionError("unexpected colour at " + x + "," + y);
			}
		}
		Set<String> expectedInner = new HashSet<>();
		Set<String> expectedOuter = new HashSet<>();
		for (int x = 1; x <= 5; x++)
		{
			for (int y = 1; y <= 5; y++)
			{
				boolean ring1 = x >= 2 && x <= 4 && y >= 2 && y <= 4 && !(x == 3 && y == 3);
				if (ring1)
					expectedInner.add(x + "," + y);
				else if (!(x == 3 && y == 3))
					expectedOuter.add(x + "," + y);
			}
		}
		assertEquals("the client's ring, shifted by the margin, keeps its colour", expectedInner, inner);
		assertEquals("every pixel touching the ring from outside joins it, in the plugin's colour", expectedOuter, outer);
		assertEquals("the sprite itself and the far margin stay clear", 49 - 8 - 16, clear.size());
	}

	@Test
	public void aRingAtTheSpriteEdgeStillGetsItsOuterPixels()
	{
		// A sprite pixel in the corner: the client's ring is clipped to the image, the thickening is not.
		BufferedImage sprite = new BufferedImage(3, 3, BufferedImage.TYPE_INT_ARGB);
		sprite.setRGB(0, 0, Color.WHITE.getRGB());
		BufferedImage ring = new BufferedImage(3, 3, BufferedImage.TYPE_INT_ARGB);
		ring.setRGB(1, 0, CYAN);
		ring.setRGB(0, 1, CYAN);
		ring.setRGB(1, 1, CYAN);

		BufferedImage mark = RouteItemMark.thickened(sprite, ring, GOLD);

		assertEquals(GOLD, mark.getRGB(3, 0));
		assertEquals(GOLD, mark.getRGB(0, 3));
		assertEquals(GOLD, mark.getRGB(3, 3));
		assertEquals("the sprite pixel stays clear", 0, mark.getRGB(1, 1) >>> 24);
	}
}

package gps;

import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Panel series P4: the route list's text rules, out of the panel class. A duration reads as
 * seconds under a minute and minutes plus seconds above; the busy note switches to "longer
 * routes" once the found routes span more than three times the cheapest (so the good ones are
 * in); an empty list is never in that state.
 */
public class RouteListViewTest
{
	private static RouteOption costing(int cost)
	{
		return new RouteOption(List.of(), List.of(), List.of(), List.of(), cost, cost, true, Set.of(), List.of(), 0);
	}

	@Test
	public void durationsReadAsSecondsThenMinutes()
	{
		assertEquals("0s", RouteListView.formatDuration(0));
		assertEquals("59s", RouteListView.formatDuration(59));
		assertEquals("1m 0s", RouteListView.formatDuration(60));
		assertEquals("2m 5s", RouteListView.formatDuration(125));
	}

	@Test
	public void theBusyNoteSaysLongerRoutesOnceTheSpreadPassesTheMultiple()
	{
		assertFalse(RouteListView.searchingLongerRoutes(List.of()));
		assertFalse(RouteListView.searchingLongerRoutes(List.of(costing(100))));
		assertFalse("three times exactly is not past the multiple",
			RouteListView.searchingLongerRoutes(List.of(costing(100), costing(300))));
		assertTrue(RouteListView.searchingLongerRoutes(List.of(costing(100), costing(200), costing(301))));
	}
}

