package gps;

import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The nested-route filter (AlternativeRoutesService.nestsAKeptRoute): a candidate that detours
 * and then runs an already-kept route anyway ("dueling ring + glory + carts" next to
 * "glory + carts") is noise and must be dropped — a field capture showed seven such wrappers
 * around one Keldagrim route. Walking never dominates, and bank-fetch candidates are spared.
 */
public class RouteNestingTest
{
	private static final TeleportMethod GLORY =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Amulet of glory: Edgeville", 1);
	private static final TeleportMethod CARTS =
		new TeleportMethod(TransportType.MINECART, "Keldagrim", 2);
	private static final TeleportMethod DUELING =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Ring of dueling: Castle Wars", 3);
	private static final TeleportMethod VARROCK =
		new TeleportMethod(TransportType.TELEPORTATION_SPELL, "Varrock Teleport", 4);

	private static RouteOption route(List<TeleportMethod> methods, Set<TeleportMethod> bankMethods)
	{
		return new RouteOption(List.of(), methods, List.of(), List.of(), 100, 100, true,
			bankMethods, List.of(), 0);
	}

	@Test
	public void detourPlusKeptRouteIsNested()
	{
		List<RouteOption> kept = List.of(route(List.of(GLORY, CARTS), Set.of()));
		assertTrue(RouteAcceptance.nestsAKeptRoute(
			List.of(DUELING, GLORY, CARTS), false, kept));
		assertTrue("double-teleport prefix still nests", RouteAcceptance.nestsAKeptRoute(
			List.of(VARROCK, DUELING, GLORY, CARTS), false, kept));
	}

	@Test
	public void genuinelyDifferentEndingsSurvive()
	{
		List<RouteOption> kept = List.of(route(List.of(GLORY, CARTS), Set.of()));
		// Varrock -> carts: same carts, different opening — carts alone is not the kept SEQUENCE.
		assertFalse(RouteAcceptance.nestsAKeptRoute(
			List.of(VARROCK, CARTS), false, kept));
		// Same length = same signature territory, not nesting.
		assertFalse(RouteAcceptance.nestsAKeptRoute(
			List.of(DUELING, CARTS), false, kept));
	}

	@Test
	public void walkOnlyNeverDominatesAndBankFetchIsSpared()
	{
		// A walk-only kept route has an empty sequence — matching "every suffix" would kill all.
		List<RouteOption> keptWalk = List.of(route(List.of(), Set.of()));
		assertFalse(RouteAcceptance.nestsAKeptRoute(
			List.of(GLORY, CARTS), false, keptWalk));
		// Bank-fetching candidate vs a non-bank kept route: the detour withdraws the item — real.
		List<RouteOption> kept = List.of(route(List.of(GLORY, CARTS), Set.of()));
		assertFalse(RouteAcceptance.nestsAKeptRoute(
			List.of(DUELING, GLORY, CARTS), true, kept));
		// But bank candidate vs bank kept route: nested is nested.
		List<RouteOption> keptBank = List.of(route(List.of(GLORY, CARTS), Set.of(GLORY)));
		assertTrue(RouteAcceptance.nestsAKeptRoute(
			List.of(DUELING, GLORY, CARTS), true, keptBank));
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Pins the methodEdgeIndexes convention END TO END: scanMethods records a transport edge by
 * its ARRIVAL step, and sailingJumpDepartures converts to the DEPARTURE index the overlays
 * key jumps by. The off-by-one this guards against left every sea leg permanently dashed
 * while all the track machinery tested green (capture 20260730-203634).
 */
public class RouteOptionTest
{
	@Test
	public void sailingJumpDeparturesConvertArrivalToDeparture()
	{
		// Path: walk 0->1->2, sail 2->3 (edge recorded by ARRIVAL index 3), walk 3->4.
		List<PathStep> path = List.of(
			step(3000, 3000), step(3001, 3000), step(3002, 3000),
			step(3200, 3200), step(3201, 3200));
		Transport sail = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3002, 3000, 0))
			.destination(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.type(TransportType.SAILING)
			.duration(50)
			.displayInfo("Sailing: test")
			.build();
		TeleportMethod method = TeleportMethod.fromTransport(sail);
		RouteOption route = new RouteOption(path, List.of(method), List.of(3), List.of(50),
			100, 100, true, Set.of(), List.of(2), 0);
		assertEquals("departure index = arrival index - 1",
			Set.of(2), route.sailingJumpDepartures());
	}

	private static PathStep step(int x, int y)
	{
		return new PathStep(WorldPointUtil.packWorldPoint(x, y, 0), false);
	}
}

package gps;

import com.google.gson.Gson;
import gps.transport.TransportType;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Plan step L14: the ranking preferences, out of the plugin class. Tiers shift a route's
 * EFFECTIVE rank (cost plus seconds-based adjustments) without touching the search; the walk
 * preference gives the plain walking route slack; the bank bias shifts via-bank routes; reached
 * routes always outrank unreached ones; at the helm pure-sail routes lead; excluded methods read
 * back as the EXCLUDED tier, a mask over the stored tier; tiers and biases persist and reload.
 */
@RunWith(MockitoJUnitRunner.class)
public class RoutePreferencesTest
{
	private static final String GROUP = "gps";

	@Mock
	ConfigManager configManager;

	private final Set<TeleportMethod> exclusions = new HashSet<>();
	private boolean keepSailing;

	private static RouteOption route(int cost, TeleportMethod... methods)
	{
		return new RouteOption(List.of(), List.of(methods), List.of(), List.of(),
			cost, cost, true, Set.of(), List.of(), 0);
	}

	private RoutePreferences preferences(Map<TeleportMethod, MethodPriority> priorities, int walkPreferenceSeconds)
	{
		RoutePreferences preferences = new RoutePreferences(exclusions, () -> keepSailing,
			() -> configManager, Gson::new, GROUP);
		priorities.forEach(preferences::setTier);
		preferences.setWalkPreferenceSeconds(walkPreferenceSeconds);
		return preferences;
	}

	@Test
	public void preferredMethodOutranksARawFasterRoute()
	{
		TeleportMethod cloak = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Ardougne cloak", 1);
		TeleportMethod minigame = new TeleportMethod(TransportType.TELEPORTATION_MINIGAME, "Rat Pits", 2);
		RoutePreferences preferences = preferences(Map.of(cloak, MethodPriority.PREFER_2), 0);

		RouteOption cloakRoute = route(300, cloak);      // effective 300 - 33 = 267
		RouteOption minigameRoute = route(280, minigame); // effective 280
		List<RouteOption> sorted = preferences.sorted(List.of(minigameRoute, cloakRoute));

		assertEquals(cloakRoute, sorted.get(0));
		assertEquals(-10, preferences.adjustmentSeconds(cloakRoute));
		assertEquals(0, preferences.adjustmentSeconds(minigameRoute));
	}

	@Test
	public void avoidedMethodSinksBelowASlowerRoute()
	{
		TeleportMethod fairy = new TeleportMethod(TransportType.FAIRY_RING, "C L S", 3);
		TeleportMethod tree = new TeleportMethod(TransportType.SPIRIT_TREE, "Tree", 4);
		RoutePreferences preferences = preferences(Map.of(fairy, MethodPriority.AVOID_3), 0);

		RouteOption fairyRoute = route(250, fairy); // effective 250 + 67 = 317
		RouteOption treeRoute = route(300, tree);   // effective 300
		List<RouteOption> sorted = preferences.sorted(List.of(fairyRoute, treeRoute));

		assertEquals(treeRoute, sorted.get(0));
		assertEquals(20, preferences.adjustmentSeconds(fairyRoute));
	}

	@Test
	public void walkPreferenceGivesThePureWalkRouteSlack()
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 5);
		RoutePreferences preferences = preferences(Map.of(), 15);

		RouteOption walk = route(320);          // effective 320 - 50 = 270
		RouteOption teleport = route(280, tab); // effective 280
		List<RouteOption> sorted = preferences.sorted(List.of(teleport, walk));

		assertEquals("walking wins: the method is not 15s better", walk, sorted.get(0));
		assertEquals(-15, preferences.adjustmentSeconds(walk));

		RouteOption fastTeleport = route(240, tab); // effective 240 beats 270
		assertEquals(fastTeleport, preferences.sorted(List.of(walk, fastTeleport)).get(0));
	}

	@Test
	public void bankBiasShiftsViaBankRoutes()
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 10);
		RoutePreferences preferences = preferences(Map.of(), 0);
		preferences.setBankPreferenceSeconds(10); // prefer bank routes by 10s

		RouteOption viaBank = new RouteOption(List.of(), List.of(tab), List.of(), List.of(),
			300, 300, true, Set.of(tab), List.of(), 0);
		RouteOption direct = route(280, tab);
		assertEquals(-10, preferences.adjustmentSeconds(viaBank));
		assertEquals("bank route effective 267 beats direct 280",
			viaBank, preferences.sorted(List.of(direct, viaBank)).get(0));

		preferences.setBankPreferenceSeconds(-10); // avoid bank routes
		assertEquals(10, preferences.adjustmentSeconds(viaBank));
		assertEquals(direct, preferences.sorted(List.of(viaBank, direct)).get(0));
	}

	@Test
	public void adjustmentsNeverPromoteAnUnreachedRoute()
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 6);
		RoutePreferences preferences = preferences(Map.of(tab, MethodPriority.PREFER_3), 0);

		RouteOption unreachedPreferred = new RouteOption(List.of(), List.of(tab), List.of(),
			List.of(), 100, 100, false, Set.of(), List.of(), 0);
		RouteOption reachedPlain = route(500);
		assertEquals(reachedPlain, preferences.sorted(List.of(unreachedPreferred, reachedPlain)).get(0));
	}

	@Test
	public void atTheHelmPureSailRanksFirstDespiteCost()
	{
		TeleportMethod sail = new TeleportMethod(TransportType.SAILING,
			"Disembark at Corsair Cove", WorldPointUtil.packWorldPoint(2589, 2851, 0));
		TeleportMethod glory = new TeleportMethod(TransportType.TELEPORTATION_ITEM,
			"Amulet of glory: Al Kharid", WorldPointUtil.packWorldPoint(3087, 3496, 0));
		RouteOption sailRoute = sailingRoute(666, sail);
		RouteOption chain = sailingRoute(182, sail, glory);
		RoutePreferences preferences = preferences(Map.of(), 0);

		keepSailing = true;
		assertSame("at the helm the pure-sail route leads even at 3x the cost",
			sailRoute, preferences.sorted(List.of(chain, sailRoute)).get(0));
		keepSailing = false;
		assertSame("ashore the cheaper chain leads", chain, preferences.sorted(List.of(sailRoute, chain)).get(0));
	}

	private static RouteOption sailingRoute(int cost, TeleportMethod... methods)
	{
		List<TeleportMethod> list = List.of(methods);
		List<Integer> edges = new java.util.ArrayList<>();
		List<Integer> durations = new java.util.ArrayList<>();
		for (int i = 0; i < list.size(); i++)
		{
			edges.add(i + 1);
			durations.add(1);
		}
		List<gps.pathfinder.PathStep> path = List.of(
			new gps.pathfinder.PathStep(WorldPointUtil.packWorldPoint(2746, 3216, 0), false),
			new gps.pathfinder.PathStep(WorldPointUtil.packWorldPoint(2638, 3009, 0), false));
		return new RouteOption(path, list, edges, durations, cost, cost, true, Set.of(), List.of(0), 0);
	}

	@Test
	public void excludedMethodsReadBackAsTheExcludedTier()
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 7);
		exclusions.add(tab);
		RoutePreferences preferences = preferences(Map.of(), 0);
		assertEquals(MethodPriority.EXCLUDED, preferences.priorityOf(tab));
		assertEquals(MethodPriority.NORMAL, preferences.priorityOf(
			new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Other", 8)));
	}

	@Test
	public void exclusionMasksButDoesNotEraseTheTier()
	{
		// Set a tier, then exclude (as the category toggle or the menu would): the tier is
		// shadowed while excluded and restored the moment the exclusion lifts.
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 9);
		RoutePreferences preferences = preferences(Map.of(tab, MethodPriority.PREFER_2), 0);
		assertEquals(MethodPriority.PREFER_2, preferences.priorityOf(tab));

		exclusions.add(tab);
		assertEquals(MethodPriority.EXCLUDED, preferences.priorityOf(tab));

		exclusions.remove(tab);
		assertEquals("re-inclusion must restore the stored tier", MethodPriority.PREFER_2, preferences.priorityOf(tab));
	}

	@Test
	public void tiersAndBiasesPersistAndReload()
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 11);
		TeleportMethod fairy = new TeleportMethod(TransportType.FAIRY_RING, "C L S", 12);
		RoutePreferences saved = preferences(Map.of(tab, MethodPriority.PREFER_1, fairy, MethodPriority.AVOID_2), 15);
		saved.setBankPreferenceSeconds(-5);
		// NORMAL is the absence of a tier: setting it removes the entry.
		saved.setTier(fairy, MethodPriority.NORMAL);

		ArgumentCaptor<String> json = ArgumentCaptor.forClass(String.class);
		verify(configManager, atLeastOnce()).setConfiguration(eq(GROUP), eq(RoutePreferences.CONFIG_KEY_PRIORITIES), json.capture());
		verify(configManager).setConfiguration(GROUP, RoutePreferences.CONFIG_KEY_WALK_PREFERENCE, 15);
		verify(configManager).setConfiguration(GROUP, RoutePreferences.CONFIG_KEY_BANK_PREFERENCE, -5);

		when(configManager.getConfiguration(GROUP, RoutePreferences.CONFIG_KEY_PRIORITIES)).thenReturn(json.getValue());
		when(configManager.getConfiguration(GROUP, RoutePreferences.CONFIG_KEY_WALK_PREFERENCE, Integer.class)).thenReturn(15);
		when(configManager.getConfiguration(GROUP, RoutePreferences.CONFIG_KEY_BANK_PREFERENCE, Integer.class)).thenReturn(-5);
		RoutePreferences loaded = new RoutePreferences(exclusions, () -> keepSailing, () -> configManager, Gson::new, GROUP);
		loaded.load();
		assertEquals(MethodPriority.PREFER_1, loaded.priorityOf(tab));
		assertEquals("the removed tier did not persist", MethodPriority.NORMAL, loaded.priorityOf(fairy));
		assertEquals(15, loaded.walkPreferenceSeconds());
		assertEquals(-5, loaded.bankPreferenceSeconds());
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.SplitFlagMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Sanity budget for the progress tracker's walk-distance flood on the REAL collision map: it
 * runs once per player-tile change (memoized in the overlay), so it must be comfortably
 * sub-millisecond. Fails only if it regresses catastrophically; prints the measured average.
 */
public class RouteProgressBenchTest
{
	@Test
	public void walkDistanceFloodIsSubMillisecond()
	{
		CollisionMap map = new CollisionMap(SplitFlagMap.fromResources());
		// Anchors near open ground; the scan below snaps each to a genuinely unblocked tile
		// (hand-picked tiles kept landing inside GE fences and castle walls).
		int[][] anchors = {{3164, 3487, 0}, {2465, 9650, 0}, {3222, 3218, 0}};
		int[] spots = new int[anchors.length];
		for (int a = 0; a < anchors.length; a++)
		{
			outer:
			for (int dx = 0; dx < 6; dx++)
			{
				for (int dy = 0; dy < 6; dy++)
				{
					if (!map.isBlocked(anchors[a][0] + dx, anchors[a][1] + dy, anchors[a][2]))
					{
						spots[a] = WorldPointUtil.packWorldPoint(
							anchors[a][0] + dx, anchors[a][1] + dy, anchors[a][2]);
						break outer;
					}
				}
			}
			assertTrue("no open tile near anchor " + a, spots[a] != 0);
		}
		// Warm-up (JIT + page-in).
		for (int i = 0; i < 200; i++)
		{
			RouteProgress.walkDistances(map, spots[i % spots.length], RouteProgress.REACH_RADIUS);
		}
		int iterations = 600;
		long start = System.nanoTime();
		int sink = 0;
		for (int i = 0; i < iterations; i++)
		{
			Map<Integer, Integer> walk =
				RouteProgress.walkDistances(map, spots[i % spots.length], RouteProgress.REACH_RADIUS);
			sink += walk.size();
		}
		long nanos = System.nanoTime() - start;
		double microsPerFlood = nanos / 1000.0 / iterations;
		System.out.println("walkDistances avg: " + String.format("%.1f", microsPerFlood)
			+ " us/flood (tiles per flood avg " + (sink / iterations) + ")");
		// Budget: one flood per tile moved. 2 ms would already be absurd; typical should be far less.
		assertTrue("walk flood too slow: " + microsPerFlood + " us", microsPerFlood < 2000);
	}
}

package gps;

import gps.pathfinder.PathStep;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The route progress tracker's maze rules: straight-line proximity is wall-blind, so eligibility
 * is based on walking distance. A path tile one tile away across a wall, or a corridor doubling
 * back a few tiles over, must not capture progress — the exact bugs seen in the field ("it thinks
 * I'm at a point in the route that is unreachable from where I stand").
 */
public class RouteProgressTest
{
	private static final int NO_GATE = Integer.MAX_VALUE;

	private static int tile(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	/** A straight east-west path at y=3200: indexes 0..length-1 map to x=3200+i. */
	private static List<PathStep> corridor(int length)
	{
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < length; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		return path;
	}

	/** Walking distances where every listed tile is openly reachable (walk == straight line). */
	private static Map<Integer, Integer> openField(int playerPacked, int radius)
	{
		Map<Integer, Integer> walk = new HashMap<>();
		int px = WorldPointUtil.unpackWorldX(playerPacked);
		int py = WorldPointUtil.unpackWorldY(playerPacked);
		for (int dx = -radius; dx <= radius; dx++)
		{
			for (int dy = -radius; dy <= radius; dy++)
			{
				walk.put(tile(px + dx, py + dy), Math.max(Math.abs(dx), Math.abs(dy)));
			}
		}
		return walk;
	}

	@Test
	public void adjacentTileAcrossAWallDoesNotCount()
	{
		// Player at (3205,3201): one tile north of path index 5 — but a wall is between (the
		// BFS never reached any path tile). Legacy straight-line rules would have snapped here.
		List<PathStep> path = corridor(20);
		int player = tile(3205, 3201);
		Map<Integer, Integer> walk = new HashMap<>();
		walk.put(player, 0); // only the player's own tile is reachable
		assertNull("wall-adjacent tile must not capture progress",
			RouteProgress.select(path, 3, NO_GATE, NO_GATE, player, walk));
	}

	@Test
	public void mazeDoubleBackDoesNotTeleportProgress()
	{
		// A U-shaped corridor: outbound leg y=3200 (indexes 0..9), return leg y=3202
		// (indexes 30..39) — 2 tiles apart straight-line, but the wall between means the real
		// walk goes around (14+ steps). The player stands on index 4; index ~34 is 2 tiles away.
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		for (int i = 10; i < 30; i++)
		{
			path.add(new PathStep(tile(3215, 3200 + (i - 10) / 10), false)); // filler far away
		}
		for (int i = 30; i < 40; i++)
		{
			path.add(new PathStep(tile(3209 - (i - 30), 3202), false));
		}
		int player = tile(3204, 3200);
		Map<Integer, Integer> walk = new HashMap<>();
		// Reachable along the outbound corridor only; the return leg is walled off (absent).
		for (int i = 0; i < 10; i++)
		{
			walk.put(tile(3200 + i, 3200), Math.abs(3200 + i - 3204));
		}
		RouteProgress.Result result = RouteProgress.select(path, 4, NO_GATE, NO_GATE, player, walk);
		assertNotNull(result);
		assertEquals("progress stays on the outbound leg, not across the wall", 4, result.index);
	}

	@Test
	public void doubleBackWithinReachStillPrefersTheNearWalk()
	{
		// Same shape but the wall has a gap: the return tile IS walkable — in 14 steps. Straight
		// line says 2; walking says 14 > 2 + slack, so the near-line match is rejected as
		// through-a-wall even though the tile is technically reachable.
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		for (int i = 10; i < 12; i++)
		{
			path.add(new PathStep(tile(3204 - (i - 10), 3202), false));
		}
		int player = tile(3204, 3200);
		Map<Integer, Integer> walk = new HashMap<>();
		for (int i = 0; i < 10; i++)
		{
			walk.put(tile(3200 + i, 3200), Math.abs(3200 + i - 3204));
		}
		walk.put(tile(3204, 3202), 11); // reachable, but only the long way round
		walk.put(tile(3203, 3202), 12);
		RouteProgress.Result result = RouteProgress.select(path, 4, NO_GATE, NO_GATE, player, walk);
		assertNotNull(result);
		assertEquals(4, result.index);
	}

	@Test
	public void honestWalkingAdvancesAlongTheCorridor()
	{
		List<PathStep> path = corridor(20);
		int player = tile(3207, 3200); // standing exactly on index 7
		RouteProgress.Result result = RouteProgress.select(
			path, 4, NO_GATE, NO_GATE, player, openField(player, RouteProgress.REACH_RADIUS));
		assertNotNull(result);
		assertEquals(7, result.index);
		assertEquals(0, result.distance);
	}

	@Test
	public void teleportLandingOnThePathJumpsAnyIndexDistance()
	{
		// Landing exactly on index 18 from reachedIndex 2: far outside STEP_WINDOW, but standing
		// ON the path counts anywhere (transport landings).
		List<PathStep> path = corridor(20);
		int player = tile(3218, 3200);
		RouteProgress.Result result = RouteProgress.select(
			path, 2, NO_GATE, NO_GATE, player, openField(player, RouteProgress.REACH_RADIUS));
		assertNotNull(result);
		assertEquals(18, result.index);
	}

	@Test
	public void beyondAnUncrossedDoorOnlyExactPresenceCounts()
	{
		List<PathStep> path = corridor(20);
		int doorGate = 10;
		// One tile from index 12 (beyond the door), openly walkable — still not enough.
		RouteProgress.Result near = RouteProgress.select(
			path, 9, doorGate, NO_GATE, tile(3212, 3201), openField(tile(3212, 3201), RouteProgress.REACH_RADIUS));
		assertEquals("only pre-door tiles are eligible near the door", 9, near.index);
		// Standing exactly on index 12: the door was evidently crossed.
		RouteProgress.Result exact = RouteProgress.select(
			path, 9, doorGate, NO_GATE, tile(3212, 3200), openField(tile(3212, 3200), RouteProgress.REACH_RADIUS));
		assertEquals(12, exact.index);
	}

	@Test
	public void returnLegIsIneligibleUntilTheTurnaround()
	{
		// Round trip retracing the same street: outbound 0..9, return 10..19 on the SAME tiles.
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3209 - i, 3200), false));
		}
		int player = tile(3204, 3200);
		RouteProgress.Result result = RouteProgress.select(
			path, 4, NO_GATE, 9, player, openField(player, RouteProgress.REACH_RADIUS));
		assertNotNull(result);
		assertEquals("walking out must not read as coming back", 4, result.index);
	}

	@Test
	public void legacyStraightLineRulesApplyWithoutACollisionMap()
	{
		// No walk map (collision not loaded): the old behaviour — including its wall-blindness —
		// keeps the tracker functional rather than frozen.
		List<PathStep> path = corridor(20);
		RouteProgress.Result result = RouteProgress.select(
			path, 3, NO_GATE, NO_GATE, tile(3205, 3201), null);
		assertNotNull(result);
		// Indexes 4 and 5 are both straight-line distance 1; ties break toward the previous
		// position — and crucially, the wall-adjacent snap IS allowed in legacy mode.
		assertEquals(4, result.index);
	}

	@Test
	public void offRouteDetourHoldsTheEstimate()
	{
		List<PathStep> path = corridor(20);
		int player = tile(3240, 3240); // nowhere near
		assertNull(RouteProgress.select(
			path, 4, NO_GATE, NO_GATE, player, openField(player, RouteProgress.REACH_RADIUS)));
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Selection stickiness across recalculations: the picked route survives re-ranking, survives the
 * player's own progress along it (methods already behind are consumed from the match), and only
 * falls back to the new best when no equivalent continuation exists. Exercised through the
 * session's settle, which is what the generation's done-branch calls (review of 2026-09-12:
 * previously through the plugin's private update handler by reflection).
 */
public class RouteRematchTest
{
	private static final TeleportMethod CLOAK =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Ardougne cloak", WorldPointUtil.packWorldPoint(2606, 3230, 0));
	private static final TeleportMethod MINECART =
		new TeleportMethod(TransportType.MINECART, "Keldagrim minecart", WorldPointUtil.packWorldPoint(2908, 10170, 0));
	private static final TeleportMethod SPIRIT_TREE =
		new TeleportMethod(TransportType.SPIRIT_TREE, "Tree Gnome Village", WorldPointUtil.packWorldPoint(2542, 3170, 0));
	private static final Set<Integer> TARGETS = Set.of(WorldPointUtil.packWorldPoint(2542, 3170, 0));

	private RouteSession session;
	// What the directions tracker reports for the picked route.
	private int progress;

	@Before
	public void before()
	{
		session = new RouteSession();
		session.begin(WorldPointUtil.packWorldPoint(3222, 3218, 0), TARGETS);
	}

	private static RouteOption route(boolean viaBank, List<Integer> methodEdges, TeleportMethod... methods)
	{
		List<TeleportMethod> methodList = List.of(methods);
		Set<TeleportMethod> bankMethods = viaBank && methods.length > 0 ? Set.of(methods[0]) : Set.of();
		List<Integer> durations = methodList.stream().map(m -> 1).collect(java.util.stream.Collectors.toList());
		return new RouteOption(List.<PathStep>of(), methodList, methodEdges, durations,
			100, 100, true, bankMethods, List.of(), 0);
	}

	private static RouteOption route(TeleportMethod... methods)
	{
		List<Integer> edges = new java.util.ArrayList<>();
		for (int i = 0; i < methods.length; i++)
		{
			edges.add(10 * (i + 1)); // method edges at path indexes 10, 20, ...
		}
		return route(false, edges, methods);
	}

	/** Settles the fresh list as the generation's done-branch does, or streams it mid-generation. */
	private void update(List<RouteOption> routes, boolean done)
	{
		if (done)
		{
			session.settle(routes, false, AlternativeRoutesService.MAX_ROUTES_CAP, () -> progress);
		}
		else
		{
			session.stream(routes);
		}
	}

	/** The player picked {@code route}; the tracker says they are at path index {@code trackerProgress}. */
	private void select(RouteOption route, int trackerProgress)
	{
		session.stream(List.of(route));
		session.select(0);
		progress = trackerProgress;
	}

	/** The overlay's route after a settle: the pick, else the settled best. */
	private RouteOption committed()
	{
		return session.displayed(TARGETS);
	}

	@Test
	public void pickedRouteStaysSelectedWhenItsRankMoves()
	{
		RouteOption picked = route(CLOAK);
		select(picked, 0);
		RouteOption newBest = route(SPIRIT_TREE);
		RouteOption equivalent = route(CLOAK); // same methods, different object, now ranked #2
		update(List.of(newBest, equivalent), true);
		assertSame("equivalent route keeps the selection despite the rank change", equivalent, session.selected());
		assertSame(equivalent, committed());
	}

	@Test
	public void vanishedRouteFallsBackToTheNewBest()
	{
		select(route(CLOAK), 0);
		RouteOption newBest = route(SPIRIT_TREE);
		update(List.of(newBest), true);
		assertNull("no equivalent -> selection cleared", session.selected());
		assertSame(newBest, committed());
	}

	@Test
	public void bankDetourVariantIsNotTheSameRouteBeforeDeparture()
	{
		select(route(false, List.of(10), CLOAK), 0);
		RouteOption bankVariant = route(true, List.of(10), CLOAK);
		update(List.of(bankVariant), true);
		assertNull("direct route must not silently become the bank-detour variant", session.selected());
	}

	@Test
	public void methodsAlreadyBehindAreConsumedFromTheMatch()
	{
		// Picked minecart -> spirit tree; the tracker says the player is past the minecart edge
		// (index 10) but before the spirit tree (index 20).
		RouteOption picked = route(MINECART, SPIRIT_TREE);
		select(picked, 14);
		RouteOption continuation = route(SPIRIT_TREE); // fresh list re-plans only the remainder
		RouteOption other = route(CLOAK);
		update(List.of(other, continuation), true);
		assertSame("the continuation (remaining methods) keeps the selection", continuation, session.selected());
	}

	@Test
	public void bankNessIsIgnoredMidJourney()
	{
		// Withdrew and departed: the picked route was via the bank, the continuation is direct.
		RouteOption picked = route(true, List.of(10, 20), MINECART, SPIRIT_TREE);
		select(picked, 14);
		RouteOption continuation = route(false, List.of(10), SPIRIT_TREE);
		update(List.of(continuation), true);
		assertSame(continuation, session.selected());
	}

	@Test
	public void walkRemainderMatchesOnlyWhenEveryMethodIsBehind()
	{
		RouteOption picked = route(MINECART);
		RouteOption walk = route(); // no methods
		// Before the minecart: the walk route must NOT steal the selection.
		select(picked, 0);
		update(List.of(walk), true);
		assertNull("untouched selection must not match the plain-walk route", session.selected());
		// After the minecart (edge 10 crossed): the walk route IS the honest continuation.
		select(picked, 12);
		update(List.of(walk), true);
		assertSame(walk, session.selected());
	}

	@Test
	public void midStreamUpdatesDoNotDisturbTheSelection()
	{
		RouteOption picked = route(CLOAK);
		select(picked, 0);
		// Streaming update (done=false) with no equivalent present yet: selection must survive
		// so the overlay keeps drawing the picked route until the generation settles.
		update(List.of(route(SPIRIT_TREE)), false);
		assertSame(picked, session.selected());
		// The equivalent arrives by the time the generation settles: selection transfers to it.
		RouteOption equivalent = route(CLOAK);
		update(List.of(route(SPIRIT_TREE), equivalent), true);
		assertSame(equivalent, session.selected());
	}

	@Test
	public void emptyFinalListClearsEverything()
	{
		select(route(CLOAK), 0);
		update(List.of(), true);
		assertNull(session.selected());
		assertNull(committed());
		assertFalse(session.canLoadMore());
	}
}

package gps;

import gps.transport.TransportType;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Plan step L9: the alternative-routes session, out of the plugin class. The page, the pick, the
 * committed display route, the in-flight flag, the last generation's start, targets and limit,
 * and the "more" budget, with the decisions that used to be spread over eleven plugin fields:
 * a fresh destination shows nothing until its routes settle, a same-destination regeneration
 * keeps the current route on screen, a pick survives a regeneration when an equivalent route
 * exists (matching what is LEFT of the plan) unless it was never started and something far
 * better appeared, a stale page for another destination is never shown, and "more" widens the
 * band and the count up to the cap.
 */
public class RouteSessionTest
{
	private static final TeleportMethod SPELL = new TeleportMethod(TransportType.TELEPORTATION_SPELL, "Varrock Teleport", 1);
	private static final TeleportMethod RING = new TeleportMethod(TransportType.FAIRY_RING, "A K S", 2);
	private static final TeleportMethod CART = new TeleportMethod(TransportType.MINECART, "Keldagrim", 3);
	private static final Set<Integer> T1 = Set.of(WorldPointUtil.packWorldPoint(3212, 3422, 0));
	private static final Set<Integer> T2 = Set.of(WorldPointUtil.packWorldPoint(2965, 3380, 0));

	private static RouteOption route(int cost, List<TeleportMethod> methods, List<Integer> edges)
	{
		return new RouteOption(List.of(), methods, edges, List.of(), cost, cost, true, Set.of(), List.of(), 0);
	}

	private static RouteOption route(int cost, TeleportMethod... methods)
	{
		return route(cost, List.of(methods), List.of());
	}

	@Test
	public void aFreshDestinationShowsNothingUntilItsRoutesSettle()
	{
		RouteSession session = new RouteSession();
		session.setLimit(10);
		session.begin(1, T1);
		assertTrue(session.inFlight());
		assertNull(session.displayed(T1));

		RouteOption a = route(100, SPELL);
		session.stream(List.of(a));
		assertNull("a streaming front-runner is never drawn", session.displayed(T1));

		RouteOption b = route(150, RING);
		session.settle(List.of(a, b), true, 250, () -> 0);
		assertFalse(session.inFlight());
		assertSame("settled: the best route", a, session.displayed(T1));
		assertTrue("routes were left unshown and the budget is below the cap", session.canLoadMore());
	}

	@Test
	public void selectionTogglesAndFallsBackToTheBest()
	{
		RouteSession session = new RouteSession();
		session.begin(1, T1);
		RouteOption a = route(100, SPELL);
		RouteOption b = route(150, RING);
		session.settle(List.of(a, b), false, 250, () -> 0);
		assertTrue(session.select(1));
		assertSame(b, session.displayed(T1));
		assertTrue("clicking the shown route hides it", session.select(1));
		assertSame("the best route is the fallback", a, session.displayed(T1));
		assertFalse("out of range", session.select(9));
		assertFalse("nothing was left unshown", session.canLoadMore());
	}

	@Test
	public void aSameDestinationRegenerationKeepsTheDisplayAndRematchesThePick()
	{
		RouteSession session = new RouteSession();
		session.begin(1, T1);
		RouteOption a = route(100, SPELL);
		RouteOption b = route(150, RING);
		session.settle(List.of(a, b), false, 250, () -> 0);
		session.select(1);

		session.begin(2, T1);
		assertTrue(session.inFlight());
		assertSame("the picked route stays on screen while the fresh page computes", b, session.displayed(T1));

		RouteOption a2 = route(90, SPELL);
		RouteOption b2 = route(160, RING);
		session.settle(List.of(a2, b2), false, 250, () -> 0);
		assertSame("the equivalent route stays selected, even at another cost", b2, session.selected());
		assertSame(b2, session.displayed(T1));
	}

	@Test
	public void aNeverStartedPickYieldsToSomethingFarBetter()
	{
		RouteSession session = new RouteSession();
		session.begin(1, T1);
		RouteOption a = route(100, SPELL);
		RouteOption b = route(300, RING);
		session.settle(List.of(a, b), false, 250, () -> 0);
		session.select(1);

		session.begin(1, T1);
		RouteOption a2 = route(100, SPELL);
		RouteOption b2 = route(300, RING);
		session.settle(List.of(a2, b2), false, 250, () -> 0);
		assertNull("300 against a best of 100, standing at the start: not stability", session.selected());
		assertSame(a2, session.displayed(T1));

		// The same page, but the pick was under way (progress past the start): it is kept.
		session.select(1);
		session.begin(1, T1);
		session.settle(List.of(a2, b2), false, 250, () -> 7);
		assertSame(b2, session.selected());
	}

	@Test
	public void rematchMatchesWhatIsLeftOfThePlan()
	{
		RouteOption previous = route(200, List.of(SPELL, CART), List.of(3, 8));
		RouteOption remainder = route(120, CART);
		RouteOption whole = route(200, SPELL, CART);
		assertSame("nothing consumed: the full sequence", whole, RouteSession.rematch(previous, List.of(remainder, whole), 0));
		assertSame("the spell's edge is behind the player: the remainder", remainder,
			RouteSession.rematch(previous, List.of(remainder, whole), 5));
		assertNull(RouteSession.rematch(previous, List.of(route(50, RING)), 0));
	}

	@Test
	public void aNewDestinationClearsTheDisplayAndAStalePageIsNeverShown()
	{
		RouteSession session = new RouteSession();
		session.begin(1, T1);
		RouteOption a = route(100, SPELL);
		session.settle(List.of(a), false, 250, () -> 0);
		assertSame(a, session.displayed(T1));
		assertNull("the page was generated for T1", session.displayed(T2));
		assertNull(session.displayed(Set.of()));

		session.begin(1, T2);
		assertNull("a new destination draws nothing until it settles", session.displayed(T2));
	}

	@Test
	public void moreWidensTheBandAndTheCountUpToTheCap()
	{
		RouteSession session = new RouteSession();
		session.setLimit(10);
		assertFalse("no destination yet", session.widen(10, 250));
		session.begin(1, T1);
		session.settle(List.of(route(100, SPELL)), true, 250, () -> 0);
		assertTrue(session.widen(10, 250));
		assertEquals(6, session.costMultiple());
		assertEquals(20, session.limit());
		assertEquals("the budget the generation ran with, for the auto-compute check", 10, session.lastLimit());

		session.setLimit(250);
		session.begin(1, T1);
		session.settle(List.of(route(100, SPELL)), true, 250, () -> 0);
		assertFalse("at the cap nothing more can be asked for", session.canLoadMore());

		session.resetBudget(10);
		assertEquals(RouteSession.DEFAULT_COST_MULTIPLE, session.costMultiple());
		assertEquals(10, session.limit());
	}

	@Test
	public void resortAndAutoCompute()
	{
		RouteSession session = new RouteSession();
		session.begin(1, T1);
		RouteOption a = route(100, SPELL);
		RouteOption b = route(150, RING);
		session.settle(List.of(a, b), false, 250, () -> 0);
		session.resort(Comparator.comparingInt(RouteOption::getTotalCost).reversed());
		assertSame(b, session.routes().get(0));

		assertTrue(RouteSession.shouldAutoCompute(T1, Set.of(), 0, 10));
		assertTrue("the last run was allowed fewer routes than wanted now", RouteSession.shouldAutoCompute(T1, T1, 1, 10));
		assertFalse(RouteSession.shouldAutoCompute(T1, T1, 10, 10));
		assertFalse("no target", RouteSession.shouldAutoCompute(Set.of(), T1, 0, 10));
	}
}

package gps;

import gps.pathfinder.PathStep;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Plan step L28: the route verdicts, out of the plugin class. A reached route is never too far
 * and always reaches; a route that stopped short counts by how far its endpoint is from the
 * nearest target against the tolerance; without a path or targets, "too far" is false and
 * "reaches" is true (not enough information to declare it unreachable); a null route reaches
 * nothing.
 */
public class RouteVerdictsTest
{
	private static final int TARGET = WorldPointUtil.packWorldPoint(3200, 3200, 0);

	private static RouteOption endingAt(int x, int y, boolean reached)
	{
		List<PathStep> path = List.of(new PathStep(WorldPointUtil.packWorldPoint(3100, 3100, 0), false),
			new PathStep(WorldPointUtil.packWorldPoint(x, y, 0), false));
		return new RouteOption(path, List.of(), List.of(), List.of(), 10, 10, reached, Set.of(), List.of(), 0);
	}

	@Test
	public void aRouteThatStoppedShortIsJudgedByItsEndpoint()
	{
		RouteOption beside = endingAt(3202, 3201, false); // 2 tiles: an object destination
		RouteOption far = endingAt(3230, 3200, false);    // 30 tiles: the target is cut off
		assertFalse(RouteVerdicts.endTooFar(beside, Set.of(TARGET), 5));
		assertTrue(RouteVerdicts.reachesTarget(beside, Set.of(TARGET), 5));
		assertTrue(RouteVerdicts.endTooFar(far, Set.of(TARGET), 5));
		assertFalse(RouteVerdicts.reachesTarget(far, Set.of(TARGET), 5));
		assertFalse("a wider tolerance forgives it", RouteVerdicts.endTooFar(far, Set.of(TARGET), 30));
	}

	@Test
	public void aReachedRouteAndMissingInformation()
	{
		RouteOption reached = endingAt(3230, 3200, true);
		assertFalse(RouteVerdicts.endTooFar(reached, Set.of(TARGET), 5));
		assertTrue(RouteVerdicts.reachesTarget(reached, Set.of(TARGET), 5));

		RouteOption far = endingAt(3230, 3200, false);
		assertFalse("no targets: not too far", RouteVerdicts.endTooFar(far, Set.of(), 5));
		assertTrue("no targets: cannot be declared unreachable", RouteVerdicts.reachesTarget(far, Set.of(), 5));
		assertFalse(RouteVerdicts.reachesTarget(null, Set.of(TARGET), 5));
	}
}

package gps;

import com.google.gson.Gson;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The item-dependency gate (issues #23/#24 follow-up): inventory changes only mark the teleport
 * catalog dirty when they touch an item some transport requirement can actually read. Bulk
 * skilling traffic - logs, ore, food, loot - never schedules a refresh at all.
 */
@RunWith(MockitoJUnitRunner.class)
public class RoutingItemDependenciesTest
{
	private static RoutingItemDependencies deps;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@BeforeClass
	public static void buildIndex()
	{
		Client client = mock(Client.class);
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		deps = new TestPathfinderConfig(client, config).getRoutingItemDependencies();
	}

	private static ItemContainer container(Item... items)
	{
		ItemContainer container = mock(ItemContainer.class);
		when(container.getItems()).thenReturn(items);
		return container;
	}

	@Test
	public void bulkSkillingItemsAreIrrelevantTransportItemsAreNot()
	{
		assertTrue("the index must not be empty", deps.size() > 100);
		// Logs are NOT in this list: hot-air balloon flights burn them, and the index knows.
		assertTrue("logs gate balloon flights", deps.isRelevant(ItemID.LOGS));
		assertFalse("raw shrimps gate no transport", deps.isRelevant(ItemID.RAW_SHRIMP));
		assertFalse("iron ore gates no transport", deps.isRelevant(ItemID.IRON_ORE));
		assertTrue("dramen staff gates fairy rings", deps.isRelevant(ItemID.DRAMEN_STAFF));
		assertTrue("coins gate charters and fares", deps.isRelevant(ItemID.COINS));
		assertTrue("a rune pouch unlocks its runes for spell requirements",
			deps.isRelevant(ItemID.BH_RUNE_POUCH));
	}

	@Test
	public void fingerprintIgnoresIrrelevantTraffic()
	{
		ItemContainer worn = container();
		long before = deps.fingerprint(
			container(new Item(ItemID.RING_OF_DUELING_8, 1), new Item(ItemID.LOGS, 5)), worn);
		long after = deps.fingerprint(
			container(new Item(ItemID.RING_OF_DUELING_8, 1), new Item(ItemID.LOGS, 500),
				new Item(ItemID.RAW_SHRIMP, 20)), worn);
		assertEquals("chopping 495 more logs changes nothing a transport reads", before, after);
	}

	@Test
	public void fingerprintTracksRelevantChanges()
	{
		ItemContainer worn = container();
		long ringOnly = deps.fingerprint(container(new Item(ItemID.RING_OF_DUELING_8, 1)), worn);
		long ringAndNecklace = deps.fingerprint(
			container(new Item(ItemID.RING_OF_DUELING_8, 1), new Item(ItemID.NECKLACE_OF_MINIGAMES_8, 1)), worn);
		long bare = deps.fingerprint(container(), worn);
		assertNotEquals("gaining a games necklace matters", ringOnly, ringAndNecklace);
		assertNotEquals("losing the dueling ring matters", ringOnly, bare);
	}

	@Test
	public void wieldedVersusCarriedStaffDiffers()
	{
		long carried = deps.fingerprint(container(new Item(ItemID.DRAMEN_STAFF, 1)), container());
		long wielded = deps.fingerprint(container(), container(new Item(ItemID.DRAMEN_STAFF, 1)));
		assertNotEquals("possession checks credit wielded and carried differently", carried, wielded);
	}

	@Test
	public void currencyOnlyMattersAtFareThresholds()
	{
		ItemContainer worn = container();
		long none = deps.fingerprint(container(), worn);
		long some = deps.fingerprint(container(new Item(ItemID.COINS, 100)), worn);
		assertNotEquals("first coins cross the presence threshold", none, some);

		long rich = deps.fingerprint(container(new Item(ItemID.COINS, 1_000_000)), worn);
		long richer = deps.fingerprint(container(new Item(ItemID.COINS, 1_000_001)), worn);
		assertEquals("a coin pickup above every fare crosses no threshold", rich, richer);
	}

	/** End to end through the controller's item hook: only relevant changes arm the dirty flag. */
	@Test
	public void inventoryEventsWithoutRelevantChangesStayClean()
	{
		PathfinderConfig pathConfig = new TestPathfinderConfig(client, config);
		ShortestPathPlugin plugin = mock(ShortestPathPlugin.class);
		ConfigManager configManager = mock(ConfigManager.class);
		ChoiceStore choices = new ChoiceStore(() -> configManager, Gson::new, "gps");
		RouteController routes = new RouteController(plugin, new RouteSession(), new MethodExclusions(choices, RoutingItemDependenciesTest::noop),
			choices, new PluginMessageBridge(plugin, () -> null));

		ItemContainer worn = container();
		ItemContainer inv = container(new Item(ItemID.RING_OF_DUELING_8, 1),
			new Item(ItemID.RAW_SHRIMP, 3), new Item(ItemID.LOGS, 5));
		// First event baselines the fingerprint (dirty once, panel-gated downstream anyway).
		assertTrue(routes.itemsChanged(pathConfig, inv, worn));
		assertTrue(routes.isCatalogDirty());

		// Fishing shrimp: the routing-relevant slice is unchanged, no refresh is ever scheduled.
		ItemContainer moreShrimp = container(new Item(ItemID.RING_OF_DUELING_8, 1),
			new Item(ItemID.RAW_SHRIMP, 22), new Item(ItemID.LOGS, 5));
		assertFalse("bulk skilling traffic must not dirty the catalog", routes.itemsChanged(pathConfig, moreShrimp, worn));

		// Equipping the dueling ring: relevant slice changed, the flag arms.
		ItemContainer invAfterEquip = container(new Item(ItemID.RAW_SHRIMP, 22), new Item(ItemID.LOGS, 5));
		ItemContainer wornAfterEquip = container(new Item(ItemID.RING_OF_DUELING_8, 1));
		assertTrue("a teleport item moving matters", routes.itemsChanged(pathConfig, invAfterEquip, wornAfterEquip));
		assertTrue("without a dependency index yet, every change counts", routes.itemsChanged(null, inv, worn));
	}

	/** A no-op callback (checkstyle wants a block's braces on their own lines, so no inline lambda). */
	private static void noop()
	{
	}
}

