import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;

/**
 * SERVICE-level sailing generation: the layer every August field finding lived in while the
 * unit tests stayed green. Seeds, chains, display caps and dedupe compose here — so these
 * tests assert ROUTE-SET PROPERTIES for aboard starts, not single-search reachability:
 * the closest-port option surviving the display cap (finding 4), multi-port + post-landing
 * teleport diversity with abandonment forbidden (finding 5), and the direct sail beating the
 * disembark/re-embark farce for a close water pin (the Cairn Isle capture).
 */
@RunWith(MockitoJUnitRunner.class)
public class SailingGenerationTest
{
	private static final int PANDEMONIUM_WATER = WorldPointUtil.packWorldPoint(3093, 2981, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3212, 3433, 0);
	private static final int NEAR_CAIRN_WATER = WorldPointUtil.packWorldPoint(2744, 2989, 0);
	private static final int CAIRN_PIN = WorldPointUtil.packWorldPoint(2692, 2941, 0);
	/** Land on a sailing-only island: every route must sail, so boarding rules are visible. */
	private static final int DOGNOSE_PIN = WorldPointUtil.packWorldPoint(3048, 2648, 0);
	/** Grimstone's mooring land tile — the far north-east ocean, sailing-only and far beyond
	 * the wet flood's settle horizon: only matrix-composed aboard legs reach it directly. */
	private static final int GRIMSTONE_PIN = WorldPointUtil.packWorldPoint(2927, 4055, 0);
	private static final int PORT_ID_PANDEMONIUM = 1;
	/** Port Sarim (id 0) — a MAINLAND berth: walkable from Varrock, so OWNED-mode
	 * scenarios can actually reach the boat with an empty mocked inventory. */
	private static final int PORT_ID_PORT_SARIM = 0;
	private static final int PORT_ID_WINTUMBER = 46;

	private AlternativeRoutesService service;

	private List<RouteOption> generate(int start, int target, boolean abandon) throws Exception
	{
		return generate(start, target, abandon, true, -1, true);
	}

	/**
	 * @param summon   the "Assume Summon Boat spell" toggle
	 * @param boatPort SAILING_BOAT_1's port id (boat owned and moored there), or -1 for no
	 *                 boat seen — the pre-detection world every earlier test lives in
	 * @param aboard   whether the start is aboard the boat (SAILING_BOARDED_BOAT)
	 */
	private List<RouteOption> generate(int start, int target, boolean abandon, boolean summon,
		int boatPort, boolean aboard) throws Exception
	{
		return generate(start, target, abandon, summon, boatPort, aboard,
			AlternativeRoutesMode.ALL_EVERYTHING);
	}

	/** The refreshed planning-copy config all these tests search with. */
	private PathfinderConfig buildConfig(boolean summon, int boatPort, boolean aboard)
		throws Exception
	{
		return buildConfig(true, summon, boatPort, aboard);
	}

	private PathfinderConfig buildConfig(boolean abandon, boolean summon, int boatPort,
		boolean aboard) throws Exception
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						// Whatever thread asks IS the client thread: the mocked ClientThread
						// runs invokeLater inline on the service worker, and the per-mode
						// refreshTransports must not no-op behind its thread guard there.
						return Thread.currentThread();
					case "getBoostedSkillLevel":
						return 99;
					case "getVarbitValue":
						int id = (int) args[0];
						if (id == VarbitID.SAILING_BOARDED_BOAT)
						{
							return aboard ? 1 : 0;
						}
						if (id == VarbitID.SAILING_BOAT_1_OWNED)
						{
							return boatPort >= 0 ? 1 : 0;
						}
						if (id == VarbitID.SAILING_BOAT_1_PORT)
						{
							return Math.max(boatPort, 0);
						}
						return 0;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class,
			Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.useSailing()).thenReturn(true);
		Mockito.when(cfg.sailingTeleportAbandon()).thenReturn(abandon);
		Mockito.when(cfg.sailingAssumeSummon()).thenReturn(summon);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		return config;
	}

	private List<RouteOption> generate(int start, int target, boolean abandon, boolean summon,
		int boatPort, boolean aboard, AlternativeRoutesMode mode) throws Exception
	{
		PathfinderConfig config = buildConfig(abandon, summon, boatPort, aboard);
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(ct, config);
		return runGeneration(start, target, mode);
	}

	/** One generation on the CURRENT service — lets a test run several against one service. */
	private List<RouteOption> runGeneration(int start, int target, AlternativeRoutesMode mode)
		throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(start, Set.of(target), Set.of(),
			mode, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertRouteShapes(routes);
		return routes;
	}

	private static ClientThread inlineClientThread()
	{
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		return ct;
	}

	/**
	 * Capture 211433: flip Summon Boat off, refresh — the Khazard water pin routed to
	 * "closest point" Brimhaven; a second refresh fixed it. The sea legs were synthesized
	 * from the PREVIOUS generation's snapshot, so the first post-flip generation had
	 * neither near-mooring legs (gated off) nor the berth must-include (not yet visible).
	 * One service, two generations, the toggle flipped between: the first post-flip
	 * generation must already reach.
	 */
	@Test
	public void summonFlipTakesEffectOnTheNextGeneration() throws Exception
	{
		final boolean[] summon = {true};
		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					case "getVarbitValue":
						int id = (int) args[0];
						if (id == VarbitID.SAILING_BOAT_1_OWNED)
						{
							return 1;
						}
						if (id == VarbitID.SAILING_BOAT_1_PORT)
						{
							return PORT_ID_PANDEMONIUM;
						}
						return 0;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class,
			Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.useSailing()).thenReturn(true);
		// Lenient: a LAND start never consults the abandon toggle.
		Mockito.lenient().when(cfg.sailingTeleportAbandon()).thenReturn(true);
		Mockito.when(cfg.sailingAssumeSummon()).thenAnswer(i -> summon[0]);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		service = new AlternativeRoutesService(inlineClientThread(), config);

		int ardougne = WorldPointUtil.packWorldPoint(2610, 3222, 0);
		int khazardWater = WorldPointUtil.packWorldPoint(2693, 3152, 0);
		assertTrue("summon-on generation must reach the water pin",
			anyReaches(runGeneration(ardougne, khazardWater, AlternativeRoutesMode.OWNED_INVENTORY)));
		summon[0] = false;
		assertTrue("the FIRST generation after flipping summon off must already reach"
				+ " (capture 211433: it took a second refresh)",
			anyReaches(runGeneration(ardougne, khazardWater, AlternativeRoutesMode.OWNED_INVENTORY)));
	}

	private static boolean anyReaches(List<RouteOption> routes)
	{
		for (RouteOption route : routes)
		{
			if (route.isReached())
			{
				return true;
			}
		}
		return false;
	}

	@After
	public void after()
	{
		if (service != null)
		{
			service.shutdown();
		}
	}

	/** Finding 7's lint: no route may disembark at a port and re-board at the same port.
	 * Plus capture 233931's: parking variants (disembark somewhere, then summon the boat
	 * away to a later embark) must be collapsed — one route per distinct continuation. */
	private static void assertRouteShapes(List<RouteOption> routes)
	{
		java.util.Set<String> parkingTails = new java.util.HashSet<>();
		for (RouteOption route : routes)
		{
			List<TeleportMethod> methods = route.getMethods();
			if (methods.size() < 2 || !isSailing(methods.get(0))
				|| methods.get(0).getDisplayInfo() == null
				|| !methods.get(0).getDisplayInfo().startsWith("Disembark at "))
			{
				continue;
			}
			boolean laterEmbark = false;
			StringBuilder tail = new StringBuilder();
			for (int i = 1; i < methods.size(); i++)
			{
				laterEmbark |= isSailing(methods.get(i)) && methods.get(i).getDisplayInfo() != null
					&& methods.get(i).getDisplayInfo().startsWith("Embark at ");
				tail.append(methods.get(i)).append('|');
			}
			if (laterEmbark)
			{
				assertTrue("parking variants must collapse (capture 233931): " + methods,
					parkingTails.add(tail.toString()));
			}
		}
		for (RouteOption route : routes)
		{
			List<TeleportMethod> methods = route.getMethods();
			for (int i = 0; i + 1 < methods.size(); i++)
			{
				String a = methods.get(i).getDisplayInfo();
				String b = methods.get(i + 1).getDisplayInfo();
				if (a != null && b != null && a.startsWith("Disembark at "))
				{
					String port = a.substring("Disembark at ".length());
					assertTrue("route disembarks and re-embarks at " + port + ": " + methods,
						!b.startsWith("Sailing: " + port + " →"));
				}
			}
		}
	}

	private static boolean isSailing(TeleportMethod method)
	{
		return TransportType.SAILING.equals(method.getType());
	}

	@Test
	public void abandonOnKeepsTheClosestPortOnTheCard() throws Exception
	{
		List<RouteOption> routes = generate(PANDEMONIUM_WATER, VARROCK, true);
		assertTrue("aboard generations must produce several routes, got " + routes.size(),
			routes.size() >= 3);
		boolean teleportFirst = false;
		boolean portFirst = false;
		for (RouteOption route : routes)
		{
			TeleportMethod first = route.getMethods().isEmpty() ? null : route.getMethods().get(0);
			if (first == null)
			{
				continue;
			}
			teleportFirst |= !isSailing(first);
			portFirst |= isSailing(first) && first.getDisplayInfo() != null
				&& first.getDisplayInfo().startsWith("Disembark");
		}
		assertTrue("with abandonment allowed, teleport-first routes must exist", teleportFirst);
		assertTrue("the closest-port disembark must survive the display cost cap (finding 4)",
			portFirst);
	}

	@Test
	public void abandonOffDiversifiesPortsAndContinuations() throws Exception
	{
		List<RouteOption> routes = generate(PANDEMONIUM_WATER, VARROCK, false);
		assertTrue("port-seeded generation must produce several routes, got " + routes.size(),
			routes.size() >= 3);
		Set<String> firstPorts = new java.util.HashSet<>();
		boolean teleportAfterLanding = false;
		for (RouteOption route : routes)
		{
			List<TeleportMethod> methods = route.getMethods();
			if (methods.isEmpty())
			{
				continue;
			}
			TeleportMethod first = methods.get(0);
			assertTrue("abandonment forbidden: no teleport-first routes, got " + methods,
				isSailing(first));
			firstPorts.add(first.getDisplayInfo());
			for (int i = 1; i < methods.size(); i++)
			{
				teleportAfterLanding |= methods.get(i).getType().isTeleport();
			}
		}
		assertTrue("distinct disembark ports must compete (finding 5), got " + firstPorts,
			firstPorts.size() >= 2);
		assertTrue("teleports must fire AFTER landing (position-scoped gate)",
			teleportAfterLanding);
		// Capture 001352: four ports, four times the same continuation. Teleport seeds
		// stay in the pool (position-gated off the helm), so the card must show at least
		// two DIFFERENT post-landing teleports across the routes.
		Set<String> continuations = new java.util.HashSet<>();
		for (RouteOption route : routes)
		{
			for (int i = 1; i < route.getMethods().size(); i++)
			{
				TeleportMethod method = route.getMethods().get(i);
				if (method.getType().isTeleport())
				{
					continuations.add(method.getDisplayInfo());
					break;
				}
			}
		}
		// KNOWN GAP (capture 001352, task #19): the chain excludes only each route's
		// PRIMARY — aboard that is the disembark, so continuations repeat. Wiring the
		// seed phase in needs family-scoped exclusions + ranking/eviction rework.
		assertTrue("post-landing continuations exist, got " + continuations,
			!continuations.isEmpty());
	}

	/**
	 * Boat-location awareness in an OWNED mode (the gate is a possession, so the "All"
	 * family legitimately bypasses it): with the boat moored at the Pandemonium and Summon
	 * Boat NOT assumed, no route may board anywhere else.
	 */
	@Test
	public void summonOffBoardsOnlyWhereTheBoatIs() throws Exception
	{
		List<RouteOption> routes = generate(VARROCK, DOGNOSE_PIN, true, false,
			PORT_ID_PORT_SARIM, false, AlternativeRoutesMode.OWNED_INVENTORY);
		assertTrue("routes must exist", !routes.isEmpty());
		boolean sailed = false;
		for (RouteOption route : routes)
		{
			for (TeleportMethod method : route.getMethods())
			{
				String info = method.getDisplayInfo();
				if (info != null && info.startsWith("Sailing: "))
				{
					sailed = true;
					assertTrue("with the boat at the Bay of Sarim and no summon, a route boards"
							+ " elsewhere: " + info,
						info.startsWith("Sailing: Bay of Sarim"));
				}
			}
		}
		assertTrue("a sailing route via the boat's berth must exist", sailed);
	}

	/**
	 * Sailing on by default must not sell boatless accounts a boarding step: boat varbits
	 * read (logged in), NO boat owned, no summon — an OWNED-mode generation to a
	 * sailing-only island produces no sailing methods at all.
	 */
	@Test
	public void boatlessAccountsGetNoBoardingLegs() throws Exception
	{
		List<RouteOption> routes = generate(VARROCK, DOGNOSE_PIN, true, false,
			-1, false, AlternativeRoutesMode.OWNED_INVENTORY);
		for (RouteOption route : routes)
		{
			for (TeleportMethod method : route.getMethods())
			{
				assertTrue("boatless account was offered sailing: " + method.getDisplayInfo(),
					!isSailing(method));
			}
		}
	}

	/**
	 * Teleport to Boat at the availability level: the generated spell rows exist for every
	 * port, and ONLY the live berth's row survives the structural gate — asserted directly
	 * on the planning copy's usable teleports so route-card competition can't hide it.
	 */
	@Test
	public void teleportToBoatTargetsTheLiveBerth() throws Exception
	{
		PathfinderConfig config = buildConfig(false, PORT_ID_PANDEMONIUM, false);
		boolean berthRow = false;
		for (gps.transport.Transport teleport : config.getUsableTeleports(false))
		{
			String info = teleport.getDisplayInfo();
			if (info != null && info.startsWith("Teleport to Boat"))
			{
				assertTrue("only the live berth's teleport row may survive, got " + info,
					info.equals("Teleport to Boat — The Pandemonium"));
				berthRow = true;
			}
		}
		assertTrue("the berth's Teleport to Boat row must be usable", berthRow);
	}

	/**
	 * The toggle really disables the gate: the boat rots at far-north Wintumber, Summon Boat
	 * IS assumed, and a sailing-only pin still gets boarded at sensible nearby ports.
	 */
	@Test
	public void summonOnFreesEveryMooring() throws Exception
	{
		List<RouteOption> routes =
			generate(VARROCK, DOGNOSE_PIN, true, true, PORT_ID_WINTUMBER, false);
		assertTrue("routes must exist", !routes.isEmpty());
		boolean otherPort = false;
		for (RouteOption route : routes)
		{
			for (TeleportMethod method : route.getMethods())
			{
				String info = method.getDisplayInfo();
				otherPort |= info != null && info.startsWith("Sailing: ")
					&& !info.startsWith("Sailing: Wintumber Island");
			}
		}
		assertTrue("assuming Summon Boat, boardings must not be pinned to the boat's berth",
			otherPort);
	}

	/**
	 * Findings 6-7 at the service level: a far sailing-only pin generates cleanly — routes
	 * exist, and any disembark→re-board chain uses DIFFERENT ports (the same-port farce
	 * stays dead; assertRouteShapes lints every generation). The far continuous sail itself
	 * is pinned as a unit property in {@link DirectSeaLegTest} — for Grimstone the router
	 * rightly prefers the Weiss teleport + 30-tile hop over a 1,000-tile ocean crossing.
	 */
	@Test
	public void farSailingOnlyPinGeneratesCleanly() throws Exception
	{
		List<RouteOption> routes = generate(PANDEMONIUM_WATER, GRIMSTONE_PIN, true);
		assertTrue("routes must exist", !routes.isEmpty());
		boolean sailsToGrimstone = false;
		for (RouteOption route : routes)
		{
			for (TeleportMethod method : route.getMethods())
			{
				sailsToGrimstone |= isSailing(method) && method.getDisplayInfo() != null
					&& method.getDisplayInfo().contains("Grimstone");
			}
		}
		assertTrue("every path to the sailing-only rock ends under sail", sailsToGrimstone);
	}

	@Test
	public void closeWaterPinTakesTheDirectSail() throws Exception
	{
		List<RouteOption> routes = generate(NEAR_CAIRN_WATER, CAIRN_PIN, true);
		assertTrue("routes must exist", !routes.isEmpty());
		RouteOption best = routes.get(0);
		assertTrue("the direct sail must win for a 70-tile water pin (Cairn capture: a 182-cost"
				+ " disembark/re-embark detour displayed instead), got cost " + best.getTotalCost()
				+ " methods " + best.getMethods(),
			best.getTotalCost() < 80 && best.getMethods().size() == 1
				&& isSailing(best.getMethods().get(0)));
	}
}

package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

/**
 * A pin on the open ocean must be a real destination: the synthesized sea legs (board at a
 * nearby mooring, sail straight out) make it reachable — and the sailing master toggle
 * removes them entirely, water pin included.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class SailingSeaTargetTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	/** The reported unreachable pin: open sea south-west of Karamja. */
	private static final int SEA_PIN = WorldPointUtil.packWorldPoint(2894, 2637, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private PathfinderConfig planning(boolean sailingOn)
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useSailing()).thenReturn(sailingOn);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		planning.setExtraTransports(SailingSea.seaLegTransports(SEA_PIN, 6));
		planning.rebuildAvailabilityWithExclusions(Set.of());
		return planning;
	}

	@Test
	public void seaTileIsRecognisedAsSailable()
	{
		assertTrue("the reported pin is on the shipped ocean", SailingSea.isSailable(SEA_PIN));
		assertFalse("land is not ocean", SailingSea.isSailable(LUMBRIDGE));
		List<Transport> legs = SailingSea.seaLegTransports(SEA_PIN, 6);
		// Six nearest plus the walk-reachable guarantee: near new islands the nearest moorings
		// can all be walk-unreachable unlocks, and legs only from those give the heuristic
		// field no mainland anchors — every search of the generation then runs blind.
		assertTrue("at least the six nearest moorings serve the pin", legs.size() >= 6);
		assertTrue("the guarantee never adds more than three ports", legs.size() <= 9);
	}

	@Test
	public void wetFloodRespectsCoastlines()
	{
		// Exact sea distances are never shorter than the straight line, and the flood must be
		// fast enough to run per generation (the water-pin performance report).
		long start = System.nanoTime();
		int[] distances = SailingSea.seaDistances(SEA_PIN);
		long coldMs = (System.nanoTime() - start) / 1_000_000;
		int settled = 0;
		for (int d : distances)
		{
			if (d != Integer.MAX_VALUE)
			{
				settled++;
			}
		}
		assertTrue("the flood settles enough moorings to build legs (got " + settled + ")",
			settled >= 6);
		assertTrue("cold wet-endpoint flood must stay interactive (took " + coldMs + "ms)",
			coldMs < 500);
	}

	@Test
	public void abandonForbiddenGatesTeleportsByPosition()
	{
		// Abandonment forbidden: no casting from the helm (water nodes), but after
		// disembarking (land nodes) teleports are legal — the config-wide kill made every
		// post-landing continuation walk-only.
		when(client.getVarbitValue(net.runelite.api.gameval.VarbitID.SAILING_BOARDED_BOAT))
			.thenReturn(1);
		when(config.sailingTeleportAbandon()).thenReturn(false);
		PathfinderConfig planning = planning(true);
		int helm = WorldPointUtil.packWorldPoint(3091, 2955, 0);
		int lumbridge = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		assertTrue("no teleports from the helm", planning.teleportsBlockedAt(helm));
		assertTrue("teleports fine on land", !planning.teleportsBlockedAt(lumbridge));
		when(config.sailingTeleportAbandon()).thenReturn(true);
		assertTrue("abandon allowed: helm teleports fine", !planning.teleportsBlockedAt(helm));
	}

	@Test
	public void aboardStartRoutesToWaterAndLand()
	{
		// Player aboard mid-ocean: without start-side legs the search dies on its sealed
		// start tile (field report: pin on water from a boat said unreachable).
		int aboard = WorldPointUtil.packWorldPoint(3091, 2955, 0);
		assertTrue("test start must be sailable water", SailingSea.isSailable(aboard));
		PathfinderConfig planning = planning(true);
		java.util.List<gps.transport.Transport> extras = new java.util.ArrayList<>();
		extras.addAll(SailingSea.seaLegTransports(SEA_PIN, 6));
		extras.addAll(SailingSea.aboardLegTransports(aboard, java.util.Set.of(SEA_PIN)));
		planning.setExtraTransports(extras);
		planning.rebuildAvailabilityWithExclusions(java.util.Set.of());
		Pathfinder toWater = new Pathfinder(planning, aboard, java.util.Set.of(SEA_PIN));
		toWater.run();
		assertTrue("aboard -> water pin must reach (direct sail leg)",
			toWater.getResult().isReached());
		int lumbridge = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		Pathfinder toLand = new Pathfinder(planning, aboard, java.util.Set.of(lumbridge));
		toLand.run();
		assertTrue("aboard -> land must reach (disembark at a port, then walk/teleport)",
			toLand.getResult().isReached());
	}

	@Test
	public void learnedObstaclesBendTracks()
	{
		// The runtime learner: live-blocked sailable tiles (a moored galleon) must bend the
		// cached track around them, and new knowledge must invalidate the old cache.
		int from = WorldPointUtil.packWorldPoint(3080, 2990, 0);
		int to = WorldPointUtil.packWorldPoint(3080, 3010, 0);
		try
		{
			int[] before = SailingSea.seaPathBlocking(from, to);
			assertTrue("baseline track exists", before != null);
			// Wall the straight line: three tiles across the corridor at y 3000.
			java.util.List<Integer> wall = new java.util.ArrayList<>();
			for (int x = 3070; x <= 3090; x++)
			{
				wall.add(WorldPointUtil.packWorldPoint(x, 3000, 0));
			}
			SailingSea.learnObstacles(wall);
			int[] after = SailingSea.seaPathBlocking(from, to);
			assertTrue("track must still exist after learning", after != null);
			for (int waypoint : after)
			{
				int wx = WorldPointUtil.unpackWorldX(waypoint);
				int wy = WorldPointUtil.unpackWorldY(waypoint);
				assertTrue("track must avoid learned obstacles (hit " + wx + "," + wy + ")",
					!SailingSea.obstacleAt(wx, wy));
			}
		}
		finally
		{
			SailingSea.clearLiveObstacles();
		}
	}

	@Test
	public void seaTrackFollowsWater()
	{
		// The rendering track for a sailing leg: every waypoint must be genuinely sailable
		// water, and both ends must sit by the leg's endpoints (mooring land / ocean pin).
		int mooringLand = WorldPointUtil.packWorldPoint(3069, 2986, 0);
		// The field-reported leg: this mooring's land sits >6 tiles from its water (pier), the
		// exact case that returned null and left the route dashed (capture 20260729-211852).
		int pierMooring = WorldPointUtil.packWorldPoint(2965, 2608, 0);
		assertTrue("pier moorings with distant water must still produce a track",
			SailingSea.seaPathBlocking(pierMooring, SEA_PIN) != null);
		int[] track = SailingSea.seaPathBlocking(mooringLand, SEA_PIN);
		assertTrue("a track must exist between a port and the ocean pin", track != null);
		assertTrue("a real track has many waypoints, not a straight hop", track.length > 10);
		int bearingChanges = 0;
		for (int w = 0; w + 2 < track.length; w++)
		{
			long b1 = bearing(track[w], track[w + 1]);
			long b2 = bearing(track[w + 1], track[w + 2]);
			if (b1 != b2)
			{
				bearingChanges++;
			}
		}
		for (int waypoint : track)
		{
			assertTrue("every waypoint is sailable water", SailingSea.isSailable(waypoint));
		}
		// LOS smoothing: a mostly-open-water leg must be a few long straight runs, not a
		// staircase — the field complaint was scattered bearing changes hugging the coast.
		assertTrue("track should be long straight legs, got " + bearingChanges
			+ " bearing changes over " + track.length + " points",
			bearingChanges <= track.length / 3);
		// Standoff: interior waypoints keep 2 tiles of clearance from land (endpoints and
		// their approaches excepted) — capture 212843 showed smoothed chords re-hugging
		// the headlands the Dijkstra penalty had paid to avoid.
		for (int w = 3; w < track.length - 3; w++)
		{
			int wx = WorldPointUtil.unpackWorldX(track[w]);
			int wy = WorldPointUtil.unpackWorldY(track[w]);
			for (int dx = -2; dx <= 2; dx++)
			{
				for (int dy = -2; dy <= 2; dy++)
				{
					assertTrue("waypoint " + wx + "," + wy + " hugs land",
						SailingSea.isSailable(WorldPointUtil.packWorldPoint(wx + dx, wy + dy, 0)));
				}
			}
		}
	}

	@Test
	public void oceanPinReachableWithSailingOn()
	{
		Pathfinder pathfinder = new Pathfinder(planning(true), LUMBRIDGE, Set.of(SEA_PIN));
		pathfinder.run();
		assertTrue("the ocean pin must be reached via a synthesized sea leg",
			pathfinder.getResult().isReached());
	}

	@Test
	public void khazardPinBoardsLocally()
	{
		// Field report gps-capture-20260729-213352: a pin beside Port Khazard detoured through
		// Port Roberts (~1480 cost) because the Khazard mooring boarding tile was not
		// walk-connected. Boarding locally (teleport + short walk + 13-tile hop) costs a few
		// hundred at most; anything near the detour cost means boarding broke again.
		int start = WorldPointUtil.packWorldPoint(2729, 3491, 3);
		int pin = WorldPointUtil.packWorldPoint(2687, 3152, 0);
		PathfinderConfig planning = planning(true);
		planning.setExtraTransports(SailingSea.seaLegTransports(pin, 6));
		planning.rebuildAvailabilityWithExclusions(Set.of());
		Pathfinder pathfinder = new Pathfinder(planning, start, Set.of(pin));
		pathfinder.run();
		assertTrue("the Khazard pin must be reached", pathfinder.getResult().isReached());
		assertTrue("must board at Khazard, not detour the western ocean (cost "
			+ pathfinder.getResult().getTotalCost() + ")",
			pathfinder.getResult().getTotalCost() < 500);
	}

	@Test
	public void oceanPinUnreachableWithSailingOff()
	{
		Pathfinder pathfinder = new Pathfinder(planning(false), LUMBRIDGE, Set.of(SEA_PIN));
		pathfinder.run();
		assertFalse("with the master toggle off the sea legs must not exist",
			pathfinder.getResult().isReached());
	}

	private static long bearing(int fromPacked, int toPacked)
	{
		int dx = Integer.compare(WorldPointUtil.unpackWorldX(toPacked)
			- WorldPointUtil.unpackWorldX(fromPacked), 0);
		int dy = Integer.compare(WorldPointUtil.unpackWorldY(toPacked)
			- WorldPointUtil.unpackWorldY(fromPacked), 0);
		return dx * 10L + dy;
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.BeforeClass;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Which destination tiles get sea legs. A water pin is one place and always does; a category
 * spread over the map ("nearest bank") does only for a player already aboard. Four bank tiles
 * stand on sailable water (the Bank Boat, the Fossil Island shipwreck's chest), and treating them
 * as water pins cost every on-foot "nearest bank" click four ocean floods, about 700 ms.
 */
public class SailingSeaWaterPinsTest
{
	private static final int PANDEMONIUM_WATER = WorldPointUtil.packWorldPoint(3093, 2981, 0);
	private static final int BANK_BOAT = WorldPointUtil.packWorldPoint(2280, 2544, 0);
	private static final Set<Integer> FOSSIL_ISLAND_BANK = Set.of(
		WorldPointUtil.packWorldPoint(3767, 3900, 0), WorldPointUtil.packWorldPoint(3767, 3898, 0));

	private static CollisionMap map;
	private static Set<Integer> nearestBank;

	@BeforeClass
	public static void load()
	{
		Client client = Mockito.mock(Client.class, Mockito.withSettings().lenient());
		Mockito.when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		PathfinderConfig config = new TestPathfinderConfig(client, new TestShortestPathConfig()).copyForPlanning();
		map = config.getMap();
		// The panel's "nearest bank": the amenity dump's bank tiles and the engine's own.
		nearestBank = new HashSet<>(Destinations.tilesForCategory("bank", null));
		nearestBank.addAll(config.getDestinations("bank"));
	}

	@Test
	public void aPinnedWaterTileIsAWaterPin()
	{
		assertEquals(Set.of(PANDEMONIUM_WATER), SailingSea.waterPins(map, Set.of(PANDEMONIUM_WATER), false));
		assertEquals(Set.of(PANDEMONIUM_WATER), SailingSea.waterPins(map, Set.of(PANDEMONIUM_WATER), true));
	}

	@Test
	public void aCategoryOnFootGetsNoSeaLegs()
	{
		assertTrue("the category really does hold the Bank Boat", nearestBank.contains(BANK_BOAT));
		assertEquals(Set.of(), SailingSea.waterPins(map, nearestBank, false));
	}

	@Test
	public void aCategoryAboardKeepsItsWaterTiles()
	{
		Set<Integer> aboard = SailingSea.waterPins(map, nearestBank, true);
		assertTrue("a sailor can still be routed to the Bank Boat by sea", aboard.contains(BANK_BOAT));
	}

	@Test
	public void aNamedPlaceIsCompactAndKeepsItsWaterTiles()
	{
		assertEquals(FOSSIL_ISLAND_BANK, SailingSea.waterPins(map, FOSSIL_ISLAND_BANK, false));
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Capture 20260827-191635: south of Ardougne with the fare only in the bank, all ten routes were
 * "teleport to some bank, Ardougne Teleport back, Brimhaven ship" - prefix twins of one tail -
 * while walking to the adjacent south bank sat at rank 11. A saturated tail (TAIL_DOMINANCE kept
 * routes) now rejects further prefix twins, so the walk-to-bank continuation makes the page.
 */
@RunWith(MockitoJUnitRunner.class)
public class SameTailPrefixCapTest
{
	private static final int START = WorldPointUtil.packWorldPoint(2664, 3286, 0);
	private static final int MOSS_GIANT_ISLAND = WorldPointUtil.packWorldPoint(2705, 3205, 0);

	@Mock
	Client client;
	@Mock
	ItemContainer inventory;
	@Mock
	ItemContainer bank;
	@Mock
	ShortestPathConfig config;
	@Mock
	ClientThread clientThread;

	@Test
	public void saturatedTailLeavesRoomForTheWalkToBankRoute() throws Exception
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.currencyThreshold()).thenReturn(10000000);
		lenient().when(config.costBankPickup()).thenReturn(15);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY_NON_CONSUMABLE);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		// Runes for every standard teleport: plenty of bank-adjacent prefixes to spawn twins.
		doReturn(new Item[]{
			new Item(ItemID.AIRRUNE, 1000), new Item(ItemID.WATERRUNE, 1000),
			new Item(ItemID.EARTHRUNE, 1000), new Item(ItemID.FIRERUNE, 1000),
			new Item(ItemID.LAWRUNE, 1000)}).when(inventory).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		Item[] bankItems = {new Item(ItemID.COINS, 10000)};
		doReturn(bankItems).when(bank).getItems();
		TestPathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		base.setBankSnapshot(bankItems);
		PathfinderConfig planning = base.copyForPlanning();
		planning.refresh();
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(START, Set.of(MOSS_GIANT_ISLAND), Set.of(),
			AlternativeRoutesMode.OWNED_WITH_BANK, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		service.shutdown();
		List<RouteOption> routes = out.get();
		assertTrue("routes expected", routes != null && !routes.isEmpty());

		Map<String, Integer> tails = new HashMap<>();
		boolean walkToBankShip = false;
		StringBuilder dump = new StringBuilder();
		for (RouteOption route : routes)
		{
			List<TeleportMethod> methods = route.getMethods();
			dump.append("\n  cost ").append(route.getTotalCost()).append(' ').append(methods);
			if (methods.size() >= 2)
			{
				String tail = methods.subList(1, methods.size()).toString();
				tails.merge(tail, 1, Integer::sum);
			}
			// The adjacent-bank continuation: no teleport prefix, just the ship (via the bank).
			walkToBankShip |= route.isViaBank() && methods.size() == 1
				&& methods.get(0).getType() == gps.transport.TransportType.SHIP;
		}
		for (Map.Entry<String, Integer> entry : tails.entrySet())
		{
			assertTrue("a saturated tail must stop collecting prefix twins: "
				+ entry.getKey() + " x" + entry.getValue() + dump, entry.getValue() <= 3);
		}
		assertTrue("the walk-to-the-adjacent-bank ship route must make the page:" + dump, walkToBankShip);
	}
}

package gps;

import java.util.Scanner;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/** Every shipped sailing leg must produce a drawable sea track (else the overlay dashes). */
public class SeaTrackCoverageTest
{
	@Test
	public void everyPortPairHasATrack()
	{
		// Full sweep incl. full-grid legs takes minutes: audit tool, not a suite tax.
		org.junit.Assume.assumeTrue(Boolean.getBoolean("gps.trackCoverage"));
		int total = 0;
		java.util.List<String> missing = new java.util.ArrayList<>();
		try (Scanner scanner = new Scanner(
			SailingSea.class.getResourceAsStream("/transports/sailing.tsv"), "UTF-8"))
		{
			while (scanner.hasNextLine())
			{
				String line = scanner.nextLine();
				if (line.startsWith("#") || line.isBlank())
				{
					continue;
				}
				String[] f = line.split("	");
				String[] o = f[0].split(" ");
				String[] d = f[1].split(" ");
				int origin = WorldPointUtil.packWorldPoint(
					Integer.parseInt(o[0]), Integer.parseInt(o[1]), 0);
				int destination = WorldPointUtil.packWorldPoint(
					Integer.parseInt(d[0]), Integer.parseInt(d[1]), 0);
				total++;
				if (SailingSea.seaPathBlocking(origin, destination) == null)
				{
					if (missing.size() < 12)
					{
						missing.add(f[0] + " -> " + f[1] + " (" + f[7] + ")");
					}
				}
			}
		}
		assertTrue("checked rows", total > 2000);
		assertTrue(missing.size() + " of " + total + " sailing legs have NO drawable track:\n  "
			+ String.join("\n  ", missing), missing.isEmpty());
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Track QUALITY as numbers, not eyeballs: for the field capture 212843 leg (the Pandemonium's
 * ship berth to open water at 2882,2872), report how many straight legs the helm must steer
 * and the closest the track ever comes to a blocked tile — then hold both to the bounds the
 * standoff/smoothing machinery promises. The second test re-runs the leg with hull obstacles
 * planted on the course (the moored ships of screenshot report 2026-08-14): the dogleg
 * snapping must keep the 16-bearing grid around hulls, where the old two-leg-or-chord
 * fallback wiggled. Run with -i to see the reports in the test log.
 */
public class SeaTrackQualityTest
{
	private static final int PANDEMONIUM_BERTH_LAND = WorldPointUtil.packWorldPoint(3069, 2986, 0);
	private static final int CAPTURE_PIN = WorldPointUtil.packWorldPoint(2882, 2872, 0);
	/** Endpoint approaches may legally close in (port water); the open-sea body may not. */
	private static final int ENDPOINT_SLACK_POINTS = 3;

	@Test
	public void captureLegIsFewStraightLegsWithClearance()
	{
		int[] track = SailingSea.seaPathBlocking(PANDEMONIUM_BERTH_LAND, CAPTURE_PIN);
		assertTrue("track must exist", track != null && track.length > 2);

		// Real helm changes via the windowed corner detector — per-point bearings count the
		// integer stair-stepping of densified straight chords as phantom turns.
		int straightLegs = SailingSea.trackCorners(track).size() - 1;

		int minClearance = Integer.MAX_VALUE;
		int clearanceAtX = -1;
		int clearanceAtY = -1;
		for (int w = ENDPOINT_SLACK_POINTS; w < track.length - ENDPOINT_SLACK_POINTS; w++)
		{
			int x = WorldPointUtil.unpackWorldX(track[w]);
			int y = WorldPointUtil.unpackWorldY(track[w]);
			int clearance = clearanceAt(x, y);
			if (clearance < minClearance)
			{
				minClearance = clearance;
				clearanceAtX = x;
				clearanceAtY = y;
			}
		}

		System.out.println("TRACK QUALITY " + 3069 + "," + 2986 + " -> 2882,2872: "
			+ straightLegs + " straight leg(s) over " + track.length + " points; minimum "
			+ minClearance + " tile(s) of clearance (tightest at " + clearanceAtX + ","
			+ clearanceAtY + ")");

		assertTrue("a mostly open-water leg should need few helm changes, got " + straightLegs,
			straightLegs <= 10);
		assertTrue("the open-sea body of the track must keep the standoff, got "
				+ minClearance + " tile(s) at " + clearanceAtX + "," + clearanceAtY,
			minClearance >= 2);

		String offenders = bearingOffenders(track);
		assertTrue("legs must steer the 16 boat bearings, off-grid:" + offenders,
			offenders.isEmpty());
	}

	/**
	 * The screenshot condition (2026-08-14): moored hulls on the course force the track to
	 * dodge — every leg must STILL steer the 16 bearings. Before the dogleg snapping,
	 * obstacle-blocked cones fell back to raw off-grid chords, and the field track wiggled
	 * exactly where the green hull boxes sat. Hulls are planted ON the clean track's own
	 * mid-course points (learner-style, +1 dilation applied by learnObstacles), so the
	 * dodge is guaranteed and the fixture survives any future course change.
	 */
	@Test
	public void hullObstaclesKeepTheBearingGrid()
	{
		int[] clean = SailingSea.seaPathBlocking(PANDEMONIUM_BERTH_LAND, CAPTURE_PIN);
		assertTrue("clean track must exist", clean != null && clean.length > 8);

		List<Integer> hulls = new ArrayList<>();
		for (int at : new int[]{clean.length / 4, clean.length / 2})
		{
			int cx = WorldPointUtil.unpackWorldX(clean[at]);
			int cy = WorldPointUtil.unpackWorldY(clean[at]);
			for (int dx = -2; dx <= 2; dx++)
			{
				for (int dy = -2; dy <= 2; dy++)
				{
					hulls.add(WorldPointUtil.packWorldPoint(cx + dx, cy + dy, 0));
				}
			}
		}

		try
		{
			SailingSea.learnObstacles(hulls);
			int[] track = SailingSea.seaPathBlocking(PANDEMONIUM_BERTH_LAND, CAPTURE_PIN);
			assertTrue("track must exist with hulls loaded", track != null && track.length > 2);
			for (int point : track)
			{
				assertTrue("track must dodge the hulls, hit "
						+ WorldPointUtil.unpackWorldX(point) + "," + WorldPointUtil.unpackWorldY(point),
					!SailingSea.obstacleAt(
						WorldPointUtil.unpackWorldX(point), WorldPointUtil.unpackWorldY(point)));
			}
			int straightLegs = SailingSea.trackCorners(track).size() - 1;
			String offenders = bearingOffenders(track, true);
			System.out.println("TRACK QUALITY (hulls on course): " + straightLegs
				+ " straight leg(s) over " + track.length + " points;"
				+ (offenders.isEmpty() ? " all on the bearing grid" : " off-grid:" + offenders));
			StringBuilder geometry = new StringBuilder("TRACK GEOMETRY corners:");
			for (int c : SailingSea.trackCorners(track))
			{
				geometry.append(' ').append(c).append('@')
					.append(WorldPointUtil.unpackWorldX(track[c])).append(',')
					.append(WorldPointUtil.unpackWorldY(track[c]));
			}
			System.out.println(geometry);
			assertTrue("hull-dodging legs must steer the 16 boat bearings, off-grid:" + offenders,
				offenders.isEmpty());
		}
		finally
		{
			SailingSea.clearLiveObstacles();
		}
	}

	/**
	 * Every leg must lie on one of the 16 bearings the boat can steer (22.5-degree grid);
	 * port-approach legs (both corners within 25 tiles of an endpoint) may fall back to raw
	 * chords in tight corridors, and one SHORT connector (<= 16 tiles, <= 8 degrees off)
	 * may absorb the integer residue of the fractional bearing decomposition. Returns the
	 * offender list — empty means the grid holds.
	 */
	private static String bearingOffenders(int[] track)
	{
		return bearingOffenders(track, false);
	}

	/**
	 * {@code hullDodges} widens the one-connector tolerance to 25 tiles / 12 degrees:
	 * a corner butted against a learned hull box has no on-bearing exit at all (every
	 * candidate clips the box; only the diagonal chord threads it) — fixing that needs
	 * bearing-aware corner PLACEMENT, tracked as follow-up work, not a better snapper.
	 */
	private static String bearingOffenders(int[] track, boolean hullDodges)
	{
		List<Integer> corners = SailingSea.trackCorners(track);
		StringBuilder offenders = new StringBuilder();
		for (int c = 0; c + 1 < corners.size(); c++)
		{
			// Sample the leg INTERIOR: the windowed detector places corners up to two dense
			// points (~8 tiles) off the true geometric corner, smearing edge angles.
			int from = corners.get(c);
			int to = corners.get(c + 1);
			if (to - from >= 6)
			{
				from += 2;
				to -= 2;
			}
			int a1 = track[from];
			int b1 = track[to];
			double dx = WorldPointUtil.unpackWorldX(b1) - WorldPointUtil.unpackWorldX(a1);
			double dy = WorldPointUtil.unpackWorldY(b1) - WorldPointUtil.unpackWorldY(a1);
			double angle = Math.toDegrees(Math.atan2(dy, dx));
			double offGrid = Math.abs(angle % 22.5);
			offGrid = Math.min(offGrid, 22.5 - offGrid);
			boolean approach =
				(WorldPointUtil.distanceBetween(a1, track[0]) <= 25
					&& WorldPointUtil.distanceBetween(b1, track[0]) <= 25)
				|| (WorldPointUtil.distanceBetween(a1, track[track.length - 1]) <= 25
					&& WorldPointUtil.distanceBetween(b1, track[track.length - 1]) <= 25);
			boolean shortConnector = hullDodges
				? Math.hypot(dx, dy) <= 25 && offGrid <= 12.0
				: Math.hypot(dx, dy) <= 16 && offGrid <= 8.0;
			if (offGrid > 4.0 && !approach && !shortConnector)
			{
				offenders.append(' ').append(WorldPointUtil.unpackWorldX(a1)).append(',')
					.append(WorldPointUtil.unpackWorldY(a1)).append("->")
					.append(WorldPointUtil.unpackWorldX(b1)).append(',')
					.append(WorldPointUtil.unpackWorldY(b1))
					.append(String.format("(%.1f deg off)", offGrid));
			}
		}
		return offenders.toString();
	}

	/** Chebyshev distance from (x, y) to the nearest non-sailable tile, capped at 6. */
	private static int clearanceAt(int x, int y)
	{
		for (int radius = 1; radius <= 6; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) == radius
						&& !SailingSea.isSailable(WorldPointUtil.packWorldPoint(x + dx, y + dy, 0)))
					{
						return radius;
					}
				}
			}
		}
		return 6;
	}

}

package gps;

import org.junit.Test;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertFalse;

/**
 * Capture 20260827-223426: the direct-sail leg's track computed fine offline yet never rendered
 * in the client - a failed early computation had poisoned the track cache permanently (nulls
 * were cached forever). Failures now cool down and retry; successes cache as before.
 */
public class SeaTrackTest
{
	@Test
	public void goodTracksCacheAndFailuresStayRetryable()
	{
		int from = WorldPointUtil.packWorldPoint(2873, 3221, 0);
		int to = WorldPointUtil.packWorldPoint(2897, 3335, 0);
		int[] track = SailingSea.seaPathBlocking(from, to);
		assertTrue("the capture's direct-sail track must compute", track != null && track.length > 1);
		assertTrue("a good track is cached", SailingSea.trackPermanentlyCached(from, to));

		// A land-to-land pair can never produce a track: the failure must NOT poison the cache.
		int landA = WorldPointUtil.packWorldPoint(3222, 3218, 0);
		int landB = WorldPointUtil.packWorldPoint(3165, 3487, 0);
		SailingSea.seaPathBlocking(landA, landB);
		assertFalse("an uncomputable pair must stay retryable, not cached as a permanent null",
			SailingSea.trackPermanentlyCached(landA, landB));
	}
}

package gps;

import gps.pathfinder.DistanceField;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderResult;
import gps.pathfinder.SearchHeuristic;
import gps.pathfinder.TestPathfinderConfig;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Baseline numbers for the search engine on this machine: startup (data load), refresh, the
 * target-directed heuristic build, and representative searches with and without the heuristic,
 * including the worst case - an unreachable target that floods the whole reachable world.
 * -Dgps.searchBench=true. Numbers are printed as BENCH lines; nothing is asserted.
 */
@RunWith(MockitoJUnitRunner.class)
public class SearchBenchmarkProbeTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int GRAND_EXCHANGE = WorldPointUtil.packWorldPoint(3165, 3487, 0);
	private static final int ARDOUGNE = WorldPointUtil.packWorldPoint(2662, 3305, 0);
	private static final int PRIFDDINAS = WorldPointUtil.packWorldPoint(3257, 6094, 0);
	/** The Broken Raft deck: open tiles ringed by the river - never reachable on foot. */
	private static final int LUM_RAFT = WorldPointUtil.packWorldPoint(3253, 3180, 0);

	@Test
	public void bench()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.searchBench"));
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		lenient().when(config.useSpiritTrees()).thenReturn(true);
		lenient().when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);

		long t0 = System.nanoTime();
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		PathfinderConfig walkConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		long load = ms(t0);
		t0 = System.nanoTime();
		walkConfig.refresh();
		System.out.println("BENCH startup: data load " + load + " ms, main-config refresh " + ms(t0) + " ms");

		when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		PathfinderConfig allConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		allConfig.refresh();
		PathfinderConfig planning = allConfig.copyForPlanning();
		t0 = System.nanoTime();
		planning.refresh();
		System.out.println("BENCH planning-copy refresh " + ms(t0) + " ms");

		// Warm the JIT once on a mid-size search before timing.
		search("warmup", walkConfig, LUMBRIDGE, GRAND_EXCHANGE, false);

		search("walk Lumbridge->GE, no heuristic", walkConfig, LUMBRIDGE, GRAND_EXCHANGE, false);
		search("walk Lumbridge->GE, heuristic", walkConfig, LUMBRIDGE, GRAND_EXCHANGE, true);
		search("walk Lumbridge->Ardougne, no heuristic", walkConfig, LUMBRIDGE, ARDOUGNE, false);
		search("walk Lumbridge->Ardougne, heuristic", walkConfig, LUMBRIDGE, ARDOUGNE, true);
		search("ALL teleports Lumbridge->Ardougne, no heuristic", allConfig, LUMBRIDGE, ARDOUGNE, false);
		search("ALL teleports Lumbridge->Ardougne, heuristic", allConfig, LUMBRIDGE, ARDOUGNE, true);
		search("ALL teleports Lumbridge->Prifddinas, heuristic", allConfig, LUMBRIDGE, PRIFDDINAS, true);
		search("UNREACHABLE raft, walk, no heuristic (full flood)", walkConfig, LUMBRIDGE, LUM_RAFT, false);
		search("UNREACHABLE raft, ALL teleports, heuristic (full flood)", allConfig, LUMBRIDGE, LUM_RAFT, true);
	}

	private static void search(String label, PathfinderConfig config, int start, int target, boolean heuristic)
	{
		long t0 = System.nanoTime();
		SearchHeuristic h = null;
		long fieldMs = 0;
		if (heuristic)
		{
			DistanceField field = DistanceField.build(config, Set.of(target));
			fieldMs = ms(t0);
			h = SearchHeuristic.buildWithField(config, field, start);
			t0 = System.nanoTime();
		}
		Pathfinder pathfinder = new Pathfinder(config, start, Set.of(target), Integer.MAX_VALUE, h);
		pathfinder.run();
		long searchMs = ms(t0);
		PathfinderResult r = pathfinder.getResult();
		System.out.println("BENCH " + label + ": " + searchMs + " ms"
			+ (heuristic ? " (+field " + fieldMs + " ms)" : "")
			+ " nodes=" + r.getNodesChecked() + " transports=" + r.getTransportsChecked()
			+ " reached=" + r.isReached() + " cost=" + r.getTotalCost()
			+ " term=" + r.getTerminationReason()
			+ " ns/node=" + (r.getNodesChecked() > 0 ? (searchMs * 1_000_000L / r.getNodesChecked()) : 0));
	}

	private static long ms(long since)
	{
		return (System.nanoTime() - since) / 1_000_000;
	}
}

package gps;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The destination search's fuzzy matcher and persisted history: tier ordering (exact &gt; prefix
 * &gt; word prefixes &gt; substring &gt; subsequence), the abbreviation cases the fuzziness exists
 * for, and the history's dedupe/cap/round-trip behaviour.
 */
public class SearchMatcherTest
{
	@Test
	public void tiersRankTighterMatchesHigher()
	{
		int exact = SearchMatcher.score("Varrock", "varrock");
		int prefix = SearchMatcher.score("Varrock Palace", "varrock");
		int wordPrefix = SearchMatcher.score("East Varrock Mine", "var mine");
		int substring = SearchMatcher.score("East Varrock", "arrock");
		int subsequence = SearchMatcher.score("Varrock", "vrck");
		assertTrue("exact > prefix", exact > prefix);
		assertTrue("prefix > word prefix", prefix > wordPrefix);
		assertTrue("word prefix > substring", wordPrefix > substring);
		assertTrue("substring > subsequence", substring > subsequence);
		assertTrue("subsequence still matches", subsequence > 0);
	}

	@Test
	public void wordPrefixesMatchInOrder()
	{
		assertTrue(SearchMatcher.score("Varrock Palace", "var pal") > 0);
		assertTrue(SearchMatcher.score("Seers' Village Rooftop Course", "seers roof") > 0);
		assertEquals("tokens out of order must not match as word prefixes or better",
			0, SearchMatcher.score("Varrock Palace", "pal var"));
	}

	@Test
	public void subsequenceToleratesDroppedLetters()
	{
		assertTrue(SearchMatcher.score("Brimhaven Agility Arena", "brmhvn") > 0);
		assertTrue(SearchMatcher.score("Gemstone crabs (Tal Teklan)", "gmstn crb") > 0);
		assertEquals("letters out of order never match", 0, SearchMatcher.score("Brimhaven", "nvhmrb"));
		assertEquals("too-short queries don't subsequence-match", 0, SearchMatcher.score("Brimhaven", "bn"));
	}

	@Test
	public void shorterNamesWinWithinATier()
	{
		assertTrue(SearchMatcher.score("Varrock", "var") > SearchMatcher.score("Varrock Palace", "var"));
	}

	@Test
	public void historyPushDedupesAndCaps()
	{
		List<Destinations.Entry> history = List.of();
		for (int i = 0; i < 15; i++)
		{
			history = SearchHistory.push(history, new Destinations.Entry("place", "Place " + i, i));
		}
		assertEquals(SearchHistory.LIMIT, history.size());
		assertEquals("Place 14", history.get(0).name);

		// Re-selecting an existing entry moves it to the front without duplicating it.
		history = SearchHistory.push(history, new Destinations.Entry("place", "Place 12", 12));
		assertEquals(SearchHistory.LIMIT, history.size());
		assertEquals("Place 12", history.get(0).name);
		assertEquals(1, history.stream().filter(e -> e.name.equals("Place 12")).count());
	}

	@Test
	public void historySurvivesARoundTrip()
	{
		List<Destinations.Entry> history = List.of(
			new Destinations.Entry("training", "Brimhaven Agility Arena", 12345),
			new Destinations.Entry("place", "Seers' Village", -99));
		List<Destinations.Entry> back = SearchHistory.deserialize(SearchHistory.serialize(history));
		assertEquals(2, back.size());
		assertEquals("Brimhaven Agility Arena", back.get(0).name);
		assertEquals("training", back.get(0).category);
		assertEquals(12345, back.get(0).packedPosition);
		assertEquals(-99, back.get(1).packedPosition);
	}

	@Test
	public void deserializeToleratesJunk()
	{
		assertTrue(SearchHistory.deserialize(null).isEmpty());
		assertTrue(SearchHistory.deserialize("").isEmpty());
		assertEquals(1, SearchHistory.deserialize("place\tValid\t5\ngarbage line\nplace\tNaN\tx").size());
	}
}

package gps;

import com.google.gson.Gson;
import java.util.List;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * Plan step L27: the search memory, out of the plugin class. A favourite with the same label
 * replaces the old one, the list is capped, removal matches label and position, a selection
 * goes to the front of the history, and every change persists.
 */
@RunWith(MockitoJUnitRunner.class)
public class SearchMemoryTest
{
	@Mock
	ConfigManager configManager;

	private SearchMemory memory()
	{
		return new SearchMemory(new ChoiceStore(() -> configManager, Gson::new, "gps"));
	}

	@Test
	public void favouritesReplaceByLabelAndRemoveByLabelAndPosition()
	{
		SearchMemory memory = memory();
		memory.addFavorite("Home", 100);
		memory.addFavorite("Bank", 200);
		memory.addFavorite("Home", 300);
		assertEquals(List.of("Bank", "Home"), names(memory.favorites()));
		assertEquals(300, memory.favorites().get(1).packedPosition);

		memory.removeFavorite(new Destinations.Entry("favorite", "Home", 100));
		assertEquals("a different position is a different favourite", 2, memory.favorites().size());
		memory.removeFavorite(new Destinations.Entry("favorite", "Home", 300));
		assertEquals(List.of("Bank"), names(memory.favorites()));
		verify(configManager, times(5)).setConfiguration(eq("gps"), eq(ChoiceStore.CONFIG_KEY_FAVORITES), anyString());
	}

	@Test
	public void theFavouriteListIsCapped()
	{
		SearchMemory memory = memory();
		for (int i = 0; i < ChoiceStore.FAVORITES_LIMIT + 5; i++)
		{
			memory.addFavorite("Spot " + i, i);
		}
		assertEquals(ChoiceStore.FAVORITES_LIMIT, memory.favorites().size());
		assertTrue("the extras were not added", names(memory.favorites()).contains("Spot 0"));
	}

	@Test
	public void selectionsGoToTheFrontOfTheHistory()
	{
		SearchMemory memory = memory();
		memory.recordSelection(new Destinations.Entry("bank", "Varrock west bank", 1));
		memory.recordSelection(new Destinations.Entry("city", "Falador", 2));
		memory.recordSelection(new Destinations.Entry("bank", "Varrock west bank", 1));
		assertEquals(List.of("Varrock west bank", "Falador"), names(memory.history()));
		verify(configManager, times(3)).setConfiguration(eq("gps"), eq(ChoiceStore.CONFIG_KEY_SEARCH_HISTORY), anyString());
	}

	private static List<String> names(List<Destinations.Entry> entries)
	{
		List<String> names = new java.util.ArrayList<>();
		for (Destinations.Entry entry : entries)
		{
			names.add(entry.name);
		}
		return names;
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * Covers the seed-teleport candidate selection ({@link AlternativeRoutesService#rankSeedCandidates}):
 * candidates are ranked by estimated arrival cost (teleport duration + straight-line landing
 * distance), far-landing candidates are kept rather than dropped (an obstacle between start and
 * target makes straight-line comparisons lie), cross-plane landings rank last instead of
 * overflowing to first, duplicate landings keep the best-ranked candidate, user exclusions are
 * honoured, and the attempt cap bounds the list.
 */
public class SeedCandidateRankingTest
{
	private static final int TARGET = WorldPointUtil.packWorldPoint(3200, 3200, 0);

	private static Transport teleport(String name, int x, int y, int plane, int duration)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_SPELL)
			.destination(WorldPointUtil.packWorldPoint(x, y, plane))
			.duration(duration)
			.displayInfo(name)
			.build();
	}

	@Test
	public void farLandingCandidateIsKeptAndRankedByEstimate()
	{
		// The old drop rule discarded any candidate landing straight-line-farther than the start —
		// wrong when an obstacle separates start and target (start looks close but the walk is long).
		// A far-landing candidate must now be kept, ranked after closer ones.
		Transport near = teleport("near", 3205, 3200, 0, 0);   // 5 tiles from target
		Transport far = teleport("far", 3230, 3200, 0, 0);     // 30 tiles from target

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(far, near)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Both candidates must be kept (no distance-based drop)", 2, attempts.size());
		assertEquals("Closer landing must rank first", "near", attempts.get(0).getDisplayInfo());
		assertEquals("Farther landing must still be attempted", "far", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void teleportDurationIsChargedIntoTheRankingAtTwoUnitsPerTick()
	{
		// The rank is the engine's time-normalized cost: duration ticks convert at 2 run-tiles per
		// tick. Chosen so the normalization decides the order: a 10-tick cast landing 15 tiles out
		// (2*10 + 15 = 35) must LOSE to an instant teleport landing 30 tiles out (30) — with the
		// old 1-unit-per-tick blend (10 + 15 = 25) it would have won.
		Transport slowCast = teleport("slow-cast", 3215, 3200, 0, 10);
		Transport instantFar = teleport("instant-far", 3230, 3200, 0, 0);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(slowCast, instantFar)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Duration must be charged at 2 units per tick", "instant-far", attempts.get(0).getDisplayInfo());
		assertEquals("slow-cast", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void crossPlaneLandingRanksLastNotFirst()
	{
		// A landing on another plane has straight-line distance Integer.MAX_VALUE; with int
		// arithmetic adding the duration would overflow negative and rank it FIRST. It must rank
		// last — but still be kept (the old drop rule discarded every seed for cross-plane targets).
		Transport samePlane = teleport("surface", 3300, 3300, 0, 10);
		Transport crossPlane = teleport("dungeon", 3201, 3200, 1, 10);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(crossPlane, samePlane)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Cross-plane candidates must be kept", 2, attempts.size());
		assertEquals("Same-plane landing must rank first", "surface", attempts.get(0).getDisplayInfo());
		assertEquals("Cross-plane landing must rank last (no overflow)", "dungeon", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void duplicateLandingsKeepTheBestRankedCandidate()
	{
		// Tab and spell to the same tile: only one attempt is spent, on the better-estimated one.
		Transport slow = teleport("slow-duplicate", 3210, 3200, 0, 30);
		Transport fast = teleport("fast-duplicate", 3210, 3200, 0, 4);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(slow, fast)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Duplicate landings collapse to one attempt", 1, attempts.size());
		assertEquals("The better-ranked duplicate wins", "fast-duplicate", attempts.get(0).getDisplayInfo());
	}

	@Test
	public void userExcludedCandidatesAreDropped()
	{
		Transport kept = teleport("kept", 3210, 3200, 0, 0);
		Transport excluded = teleport("excluded", 3205, 3200, 0, 0);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(kept, excluded)), Set.of(TARGET),
			Set.of(TeleportMethod.fromTransport(excluded)), 10);

		assertEquals("Excluded method must not get an attempt", 1, attempts.size());
		assertEquals("kept", attempts.get(0).getDisplayInfo());
	}

	@Test
	public void multiTargetRankingMeasuresEachLandingAgainstItsNearestTarget()
	{
		// "Nearest bank" style query: two targets far apart. A teleport landing beside the DISTANT
		// target must outrank one landing moderately close to the near target — ranked against only
		// the near target (the old single-representative behavior) it would have come last.
		int nearTarget = TARGET;                                             // (3200, 3200)
		int farTarget = WorldPointUtil.packWorldPoint(2400, 2800, 0);        // far away
		Transport besideFarTarget = teleport("beside-far-target", 2402, 2800, 0, 0);  // 2 from far target
		Transport nearishNearTarget = teleport("nearish-near-target", 3220, 3200, 0, 0); // 20 from near target

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(nearishNearTarget, besideFarTarget)),
			Set.of(nearTarget, farTarget), Set.of(), 10);

		assertEquals("A landing beside ANY target must rank by its nearest target",
			"beside-far-target", attempts.get(0).getDisplayInfo());
		assertEquals("nearish-near-target", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void attemptCapKeepsTheBestRankedCandidates()
	{
		List<Transport> candidates = new ArrayList<>();
		for (int i = 1; i <= 5; i++)
		{
			candidates.add(teleport("t" + i, 3200 + 5 * i, 3200, 0, 0)); // 5, 10, ... 25 tiles out
		}

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(candidates, Set.of(TARGET), Set.of(), 3);

		assertEquals("Cap must bound the attempts", 3, attempts.size());
		for (int i = 0; i < attempts.size(); i++)
		{
			assertEquals("The cap must keep the best-ranked candidates in order",
				"t" + (i + 1), attempts.get(i).getDisplayInfo());
		}
		assertTrue("Zero cap yields no attempts",
			AlternativeRoutesService.rankSeedCandidates(candidates, Set.of(TARGET), Set.of(), 0).isEmpty());
	}
}

