/**
 * Dev tool, not a test: builds destinations-wiki.tsv for the GPS search from the OSRS wiki —
 * every article using {@code {{Infobox Location}}} (places, landmarks, dungeons) or
 * {@code {{Infobox Activity}}} (minigames) whose infobox carries a {@code {{Map|x=..|y=..}}} pin.
 * This fills the gap the cache dump leaves: locations without an in-game world-map label
 * (e.g. Giants' Foundry) become searchable without hand-curating each one.
 * <p>
 * Names already present in destinations.tsv / destinations-curated.tsv are skipped (the cache dump
 * and hand curation stay authoritative), and pins with no walkable tile nearby (instanced/unmapped
 * zones) are dropped against the plugin's own collision map.
 * <p>
 * Run with: {@code ./gradlew test --tests gps.WikiLocationDumperTest -DwikiLocations.dump=true}
 * (the plugin build forwards {@code wikiLocations.*} system properties to the test JVM); the
 * output default is src/main/resources/destinations-wiki.tsv — review the diff and commit.
 */
public class WikiLocationDumperTest
{
	private static final String API = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT =
		"RuneLite GPS plugin location dump (github.com/PauloAguiar/runelite-gps-plugin)";
	private static final int BATCH = 50;
	private static final long THROTTLE_MILLIS = 300;

	// The infobox map pin: {{Map|x=3360|y=3151|plane=0|...}} (named params, any order).
	private static final Pattern MAP_TEMPLATE = Pattern.compile("\\{\\{Map\\|([^{}]*)}}", Pattern.CASE_INSENSITIVE);
	private static final Pattern INFOBOX_TYPE = Pattern.compile("\\|\\s*type\\s*=\\s*([^|\\n]*)", Pattern.CASE_INSENSITIVE);

	private final HttpClient http = HttpClient.newHttpClient();

	@Test
	public void dump() throws Exception
	{
		Assume.assumeTrue("Enable with -DwikiLocations.dump=true", Boolean.getBoolean("wikiLocations.dump"));
		Path resources = Paths.get(System.getProperty("wikiLocations.resources", "src/main/resources"));
		Path output = Paths.get(System.getProperty("wikiLocations.output",
			resources.resolve("destinations-wiki.tsv").toString()));

		Set<String> existingNames = new HashSet<>();
		for (String file : new String[]{"destinations.tsv", "destinations-curated.tsv"})
		{
			Path path = resources.resolve(file);
			if (Files.exists(path))
			{
				for (String line : Files.readAllLines(path, StandardCharsets.UTF_8))
				{
					String[] cols = line.split("\t");
					if (cols.length >= 2 && !"category".equals(cols[0]))
					{
						existingNames.add(normalize(cols[1]));
					}
				}
			}
		}
		System.out.println("existing names to dedupe against: " + existingNames.size());

		// category|name -> row; TreeMap for a stable, reviewable file order.
		Map<String, String> rows = new TreeMap<>();
		Set<String> emitted = new HashSet<>(existingNames);
		int[] scanned = new int[1];
		String today = LocalDate.now().toString();
		// Wiki pins in instanced/unmapped zones (cutscene areas, Memory instances) have no walkable
		// tile nearby in the plugin's collision map and would produce nonsense routes.
		CollisionMap collisionMap = new CollisionMap(SplitFlagMap.fromResources());

		Map<String, List<int[]>> candidates = new TreeMap<>();
		harvest("Template:Infobox Location", false, emitted, candidates, scanned);
		harvest("Template:Infobox Activity", true, emitted, candidates, scanned);
		resolvePins(rows, candidates, collisionMap, today);

		Files.createDirectories(output.getParent());
		try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8))
		{
			writer.write("category\tname\tx\ty\tplane\tverified_source\tverified_date\n");
			for (String row : rows.values())
			{
				writer.write(row);
				writer.write('\n');
			}
		}
		System.out.println("pages scanned: " + scanned[0] + ", entries written: " + rows.size());
		System.out.println("output: " + output.toAbsolutePath());
	}

	private void harvest(String template, boolean activity, Set<String> emitted, Map<String, List<int[]>> candidates,
		int[] scanned) throws Exception
	{
		List<String> titles = transcludingTitles(template);
		System.out.println(template + ": " + titles.size() + " pages");
		for (int i = 0; i < titles.size(); i += BATCH)
		{
			for (Map.Entry<String, String> page : wikitexts(titles.subList(i, Math.min(i + BATCH, titles.size()))).entrySet())
			{
				scanned[0]++;
				String title = page.getKey();
				if (title.contains("/") || title.contains("(historical)") || title.contains("Leagues"))
				{
					continue;
				}
				String category = categorize(page.getValue(), activity);
				if (category == null)
				{
					continue;
				}
				List<int[]> pins = mapPins(page.getValue());
				if (pins.isEmpty() || !emitted.add(normalize(title)))
				{
					continue;
				}
				candidates.put(category + "|" + title, pins);
			}
		}
	}

	/**
	 * Resolves each candidate to its first REACHABLE pin, or drops it: instanced and cutscene zones
	 * are walkable in the collision map but disconnected from the world graph, so a search from
	 * Lumbridge with every transport enabled (everything-mode planning config) is the oracle. Pages
	 * often pin an interior first and the entrance later (dungeons, altars), so every pin gets a
	 * chance. Slow (minutes — unreachable pins each flood the map) but this only runs when
	 * regenerating the data.
	 */
	private static void resolvePins(Map<String, String> rows, Map<String, List<int[]>> candidates,
		CollisionMap collisionMap, String today)
	{
		final Thread clientThread = Thread.currentThread();
		net.runelite.api.Client client = (net.runelite.api.Client) java.lang.reflect.Proxy.newProxyInstance(
			net.runelite.api.Client.class.getClassLoader(), new Class<?>[]{net.runelite.api.Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return net.runelite.api.GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		// Everything on: booleans true (minus the restricting toggles), items ALL, best jewellery box.
		ShortestPathConfig config = org.mockito.Mockito.mock(ShortestPathConfig.class, invocation ->
		{
			String name = invocation.getMethod().getName();
			Class<?> type = invocation.getMethod().getReturnType();
			if (type == boolean.class)
			{
				return !"avoidWilderness".equals(name) && !"enableSeasonalTransports".equals(name);
			}
			if (type == int.class)
			{
				return "calculationCutoff".equals(name) ? 120 : 0;
			}
			if (type == TeleportationItem.class)
			{
				return TeleportationItem.ALL;
			}
			if (type == JewelleryBoxTier.class)
			{
				return JewelleryBoxTier.ORNATE;
			}
			return HybridPageFillTest.defaultValue(type);
		});
		gps.pathfinder.PathfinderConfig planning =
			new gps.pathfinder.TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();

		final int lumbridge = WorldPointUtil.packWorldPoint(3221, 3218, 0);
		List<String> dropped = new ArrayList<>();
		List<String> review = new ArrayList<>();
		int salvagedByLaterPin = 0;
		for (Map.Entry<String, List<int[]>> candidate : candidates.entrySet())
		{
			// Evaluate EVERY pin, not just up to the first reachable one: when several distinct
			// sites are reachable, the first-pin choice is a guess that a human should review.
			List<int[]> pins = candidate.getValue();
			List<int[]> reachable = new ArrayList<>();
			for (int[] pin : pins)
			{
				Set<Integer> ring = Destinations.walkableTargets(collisionMap,
					WorldPointUtil.packWorldPoint(pin[0], pin[1], pin[2]));
				if (ring.isEmpty())
				{
					continue;
				}
				gps.pathfinder.Pathfinder pathfinder = new gps.pathfinder.Pathfinder(planning, lumbridge, ring);
				pathfinder.run();
				if (pathfinder.getResult().isReached())
				{
					reachable.add(pin);
				}
			}
			if (reachable.isEmpty())
			{
				dropped.add(candidate.getKey());
				continue;
			}
			int[] chosen = reachable.get(0);
			if (!java.util.Arrays.equals(chosen, pins.get(0)))
			{
				salvagedByLaterPin++;
			}
			// Ambiguous pick: more than one reachable pin, meaningfully apart — flag for a human.
			// A wrong pick is overridden by adding a curated row with the same name (the dedupe
			// then drops the wiki entry on the next run).
			for (int i = 1; i < reachable.size(); i++)
			{
				int[] other = reachable.get(i);
				if (other[2] != chosen[2]
					|| Math.abs(other[0] - chosen[0]) + Math.abs(other[1] - chosen[1]) > 40)
				{
					review.add(candidate.getKey() + "\tchose (" + chosen[0] + ", " + chosen[1] + ", " + chosen[2]
						+ ")\talternatives " + reachable.stream()
							.map(p -> "(" + p[0] + ", " + p[1] + ", " + p[2] + ")")
							.reduce((a, b) -> a + " " + b).orElse(""));
					break;
				}
			}
			String key = candidate.getKey();
			String category = key.substring(0, key.indexOf('|'));
			String title = key.substring(key.indexOf('|') + 1);
			rows.put(key, category + "\t" + title + "\t" + chosen[0] + "\t" + chosen[1] + "\t" + chosen[2]
				+ "\tosrs-wiki-infobox-map\t" + today);
		}
		System.out.println("salvaged by a later pin: " + salvagedByLaterPin);
		System.out.println("unreachable entries dropped: " + dropped.size() + " " + dropped);
		System.out.println("AMBIGUOUS picks needing review: " + review.size());
		for (String line : review)
		{
			System.out.println("  REVIEW " + line);
		}
	}

	/**
	 * The search category for a page, from its infobox type: activities count when they are
	 * minigames or raids ("minigame") or fixed-location bosses/activities like Barrows and the
	 * Blast mine ("landmark") — but not random events, forestry events, or roaming distractions.
	 * Locations map city/town/village/island to "place", dungeons and caves to "dungeon",
	 * everything else (mountains, ruins, guilds, buildings, ...) to "landmark". Null skips the page.
	 */
	private static String categorize(String wikitext, boolean activity)
	{
		Matcher typeMatcher = INFOBOX_TYPE.matcher(wikitext);
		String type = typeMatcher.find()
			? typeMatcher.group(1).replaceAll("\\[\\[|]]", "").trim().toLowerCase(Locale.ROOT) : "";
		if (activity)
		{
			if (type.contains("minigame") || type.contains("raid"))
			{
				return "minigame";
			}
			return type.equals("boss") || type.equals("activity") ? "landmark" : null;
		}
		if (type.contains("city") || type.contains("town") || type.contains("village") || type.contains("island"))
		{
			return "place";
		}
		if (type.contains("dungeon") || type.contains("cave"))
		{
			return "dungeon";
		}
		return "landmark";
	}

	/**
	 * Every plausible in-world {@code {{Map}}} pin on the page, in order: [x, y, plane] each. Many
	 * pages pin an interior first and the entrance later, so the reachability pass tries them all.
	 * Handles both named ({@code x=..|y=..}) and positional ({@code {{Map|2984,3291|...}}}) pins.
	 */
	private static List<int[]> mapPins(String wikitext)
	{
		List<int[]> pins = new ArrayList<>();
		Matcher matcher = MAP_TEMPLATE.matcher(wikitext);
		while (matcher.find())
		{
			Integer x = null;
			Integer y = null;
			int plane = 0;
			for (String param : matcher.group(1).split("\\|"))
			{
				String[] pair = param.split("=", 2);
				if (pair.length != 2)
				{
					// Positional coordinate pair: {{Map|2984,3291|mtype=pin}}.
					Matcher pos = Pattern.compile("^\\s*(\\d{4}),\\s*(\\d{4,5})\\s*$").matcher(param);
					if (pos.matches())
					{
						x = Integer.parseInt(pos.group(1));
						y = Integer.parseInt(pos.group(2));
					}
					continue;
				}
				String key = pair[0].trim().toLowerCase(Locale.ROOT);
				try
				{
					if ("x".equals(key))
					{
						x = Integer.parseInt(pair[1].trim());
					}
					else if ("y".equals(key))
					{
						y = Integer.parseInt(pair[1].trim());
					}
					else if ("plane".equals(key))
					{
						plane = Integer.parseInt(pair[1].trim());
					}
				}
				catch (NumberFormatException e)
				{
					// A templated/expression param — not a plain pin; keep scanning.
				}
			}
			if (x != null && y != null && x >= 1000 && x <= 4600 && y >= 2000 && y <= 13000 && plane >= 0 && plane <= 3)
			{
				pins.add(new int[]{x, y, plane});
			}
		}
		return pins;
	}

	/** Every mainspace title transcluding the template, via the paginated embeddedin API. */
	private List<String> transcludingTitles(String template) throws IOException, InterruptedException
	{
		List<String> titles = new ArrayList<>();
		String cont = null;
		do
		{
			String url = API + "?action=query&list=embeddedin&eititle=" + encode(template)
				+ "&einamespace=0&eilimit=500&format=json"
				+ (cont != null ? "&eicontinue=" + encode(cont) : "");
			JsonObject json = get(url);
			for (JsonElement e : json.getAsJsonObject("query").getAsJsonArray("embeddedin"))
			{
				titles.add(e.getAsJsonObject().get("title").getAsString());
			}
			cont = json.has("continue") ? json.getAsJsonObject("continue").get("eicontinue").getAsString() : null;
		}
		while (cont != null);
		return titles;
	}

	/** Raw wikitext per title for one batch (the API caps titles at 50 per request). */
	private Map<String, String> wikitexts(List<String> titles) throws IOException, InterruptedException
	{
		String url = API + "?action=query&prop=revisions&rvprop=content&rvslots=main&format=json"
			+ "&titles=" + encode(String.join("|", titles));
		JsonObject json = get(url);
		Map<String, String> out = new TreeMap<>();
		for (Map.Entry<String, JsonElement> entry : json.getAsJsonObject("query").getAsJsonObject("pages").entrySet())
		{
			JsonObject page = entry.getValue().getAsJsonObject();
			if (!page.has("revisions"))
			{
				continue;
			}
			JsonObject slot = page.getAsJsonArray("revisions").get(0).getAsJsonObject()
				.getAsJsonObject("slots").getAsJsonObject("main");
			out.put(page.get("title").getAsString(), slot.get("*").getAsString());
		}
		return out;
	}

	private JsonObject get(String url) throws IOException, InterruptedException
	{
		Thread.sleep(THROTTLE_MILLIS);
		HttpRequest request = HttpRequest.newBuilder(URI.create(url)).header("User-Agent", USER_AGENT).GET().build();
		HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
		if (response.statusCode() != 200)
		{
			throw new IOException("wiki API " + response.statusCode() + " for " + url);
		}
		return JsonParser.parseString(response.body()).getAsJsonObject();
	}

	private static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	private static String encode(String value)
	{
		try
		{
			return URLEncoder.encode(value, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package gps;

import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import gps.pathfinder.WildernessChecker;

@RunWith(MockitoJUnitRunner.class)
public class WildernessCheckerTest
{

	private static final int WILDERNESS_GREEN_DRAGONS = WorldPointUtil.packWorldPoint(3339, 3696, 0);
	private static final int WILDERNESS_EDGEVILLE_DUNGEON = WorldPointUtil.packWorldPoint(3089, 9957, 0);
	private static final int WILDERNESS_LAVA_MAZE_DUNGEON = WorldPointUtil.packWorldPoint(3039, 10260, 0);
	private static final int WILDERNESS_DARK_WARRIORS_FORTRESS = WorldPointUtil.packWorldPoint(3023, 3626, 1);
	private static final int WILDERNESS_REVENANT_CAVES = WorldPointUtil.packWorldPoint(3198, 10074, 0);
	private static final int WILDERNESS_SLAYER_CAVE = WorldPointUtil.packWorldPoint(3406, 10144, 0);
	private static final int WILDERNESS_SLAYER_CAVE_SOUTH = WorldPointUtil.packWorldPoint(3385, 10054, 0);
	private static final int WILDERNESS_GOD_WARS_DUNGEON = WorldPointUtil.packWorldPoint(3044, 10134, 0);
	private static final int WILDERNESS_GOD_WARS_DUNGEON_UPSTAIRS = WorldPointUtil.packWorldPoint(3065, 10155, 3);

	private static final int WILDERNESS_FEROX_ENCLAVE = WorldPointUtil.packWorldPoint(3134, 3629, 0);
	private static final int NON_WILDERNESS_PENINSULA = WorldPointUtil.packWorldPoint(3009, 3531, 0);

	private static final int WILDERNESS_BANDIT_CAMP = WorldPointUtil.packWorldPoint(3037, 3700, 0);

	@Test
	public void testIsInWilderness()
	{
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GREEN_DRAGONS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_EDGEVILLE_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_LAVA_MAZE_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_DARK_WARRIORS_FORTRESS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_REVENANT_CAVES));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_SLAYER_CAVE));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GOD_WARS_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GOD_WARS_DUNGEON_UPSTAIRS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_SLAYER_CAVE_SOUTH));

		assertFalse(WildernessChecker.isInWilderness(NON_WILDERNESS_PENINSULA));
		assertFalse(WildernessChecker.isInWilderness(WILDERNESS_FEROX_ENCLAVE));
	}

	@Test
	public void testisInWildernessSet()
	{
		Set<Integer> packedPoints = new HashSet<>();

		// All wilderness areas
		packedPoints.add(WILDERNESS_DARK_WARRIORS_FORTRESS);
		packedPoints.add(WILDERNESS_EDGEVILLE_DUNGEON);
		assertTrue(WildernessChecker.isInWilderness(packedPoints));
		packedPoints.clear();

		// All non-wilderness areas
		packedPoints.add(WILDERNESS_FEROX_ENCLAVE);
		packedPoints.add(NON_WILDERNESS_PENINSULA);
		assertFalse(WildernessChecker.isInWilderness(packedPoints));
		packedPoints.clear();

		// Mixed areas
		packedPoints.add(WILDERNESS_GREEN_DRAGONS);
		packedPoints.add(NON_WILDERNESS_PENINSULA);
		assertTrue(WildernessChecker.isInWilderness(packedPoints));
	}

	@Test
	public void testInLevel20Wilderness()
	{
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_BANDIT_CAMP));
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_GOD_WARS_DUNGEON));
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_SLAYER_CAVE)); // Northern entrance at level 29
		// wilderness
		assertFalse(WildernessChecker.isInLevel20Wilderness(WILDERNESS_SLAYER_CAVE_SOUTH));
	}

	@Test
	public void testInLevel30Wilderness()
	{
		assertTrue(WildernessChecker.isInLevel30Wilderness(WILDERNESS_LAVA_MAZE_DUNGEON));
	}
}

package gps;

import java.util.Set;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * Plan step L33: the world-map pin, out of the plugin class. A single target is pinned, a
 * multi-target set is not, unless the one-shot override names the tile the set was expanded
 * from, and that override is consumed by the placement it applies to.
 */
@RunWith(MockitoJUnitRunner.class)
public class WorldMapMarkerTest
{
	private static final int BOOTH = WorldPointUtil.packWorldPoint(3185, 3436, 0);
	private static final int WEST = WorldPointUtil.packWorldPoint(3184, 3436, 0);
	private static final int EAST = WorldPointUtil.packWorldPoint(3186, 3436, 0);

	@Mock
	WorldMapPointManager manager;

	@Test
	public void aSingleTargetIsPinnedAndAMultiTargetSetIsNot()
	{
		WorldMapMarker marker = new WorldMapMarker(() -> manager);
		marker.place(Set.of(BOOTH));
		assertEquals(BOOTH, marker.pinnedTile());
		verify(manager, times(1)).add(any());

		marker.place(Set.of(WEST, EAST));
		assertEquals("a category of targets has no single place to pin", WorldPointUtil.UNDEFINED, marker.pinnedTile());
		verify(manager, times(1)).add(any());
		verify(manager, times(2)).removeIf(any());
	}

	@Test
	public void theOverridePinsTheExpandedTileOnceThenTheRuleReturns()
	{
		WorldMapMarker marker = new WorldMapMarker(() -> manager);
		marker.pinNextAt(BOOTH);
		marker.place(Set.of(WEST, EAST));
		assertEquals("the searched booth, not its walkable surround", BOOTH, marker.pinnedTile());

		marker.place(Set.of(WEST, EAST));
		assertEquals("consumed: the next multi-target set pins nothing", WorldPointUtil.UNDEFINED, marker.pinnedTile());
	}

	@Test
	public void clearRemovesThePin()
	{
		WorldMapMarker marker = new WorldMapMarker(() -> manager);
		marker.clear();
		verify(manager, never()).add(any());
		marker.place(Set.of(BOOTH));
		marker.clear();
		assertEquals(WorldPointUtil.UNDEFINED, marker.pinnedTile());
	}
}

package gps;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step L13: the world-map projection, out of the plugin class. A world point projects to
 * the map widget's pixels from the map's zoom, centre and bounds; a pixel projects back to the
 * world point (the shift-click "Set GPS Target" on the world map); no map widget means no
 * projection (the sentinel the overlays test for).
 */
@RunWith(MockitoJUnitRunner.class)
public class WorldMapProjectionTest
{
	@Mock
	Client client;
	@Mock
	WorldMap worldMap;
	@Mock
	Widget mapWidget;

	@Test
	public void projectsThereAndBack()
	{
		when(client.getWorldMap()).thenReturn(worldMap);
		when(worldMap.getWorldMapZoom()).thenReturn(4f);
		when(worldMap.getWorldMapPosition()).thenReturn(new Point(3200, 3200));
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(mapWidget);
		when(mapWidget.getBounds()).thenReturn(new Rectangle(100, 50, 800, 600));
		WorldMapProjection projection = new WorldMapProjection(client);

		int point = WorldPointUtil.packWorldPoint(3210, 3210, 0);
		assertEquals(542, projection.toGraphicsX(point));
		assertEquals(308, projection.toGraphicsY(point));
		assertEquals("a pixel maps back to the tile it shows", point, projection.worldPointAt(542, 308));
	}

	@Test
	public void noMapWidgetMeansNoProjection()
	{
		when(client.getWorldMap()).thenReturn(worldMap);
		lenient().when(worldMap.getWorldMapZoom()).thenReturn(4f);
		lenient().when(worldMap.getWorldMapPosition()).thenReturn(new Point(3200, 3200));
		when(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).thenReturn(null);
		WorldMapProjection projection = new WorldMapProjection(client);

		int point = WorldPointUtil.packWorldPoint(3210, 3210, 0);
		assertEquals(WorldMapProjection.NONE, projection.toGraphicsX(point));
		assertEquals(WorldMapProjection.NONE, projection.toGraphicsY(point));
		assertEquals(WorldPointUtil.UNDEFINED, projection.worldPointAt(542, 308));
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Perspective.LOCAL_COORD_BITS;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import org.mockito.Mockito;

/**
 * Unit tests for {@link WorldPointUtil}.
 */
public class WorldPointUtilTest
{

	private static final WorldArea WILDERNESS_ABOVE_GROUND = new WorldArea(2944, 3523, 448, 448, 0);

	@Test
	public void packAndUnpackRoundTrip()
	{
		WorldPoint p = new WorldPoint(1234, 5678, 2);
		int packed = WorldPointUtil.packWorldPoint(p);
		assertEquals(1234, WorldPointUtil.unpackWorldX(packed));
		assertEquals(5678, WorldPointUtil.unpackWorldY(packed));
		assertEquals(2, WorldPointUtil.unpackWorldPlane(packed));

		WorldPoint unpacked = WorldPointUtil.unpackWorldPoint(packed);
		assertEquals(p, unpacked);
	}

	@Test
	public void packMasksHighBits()
	{
		int x = 40000; // exceeds 15 bits
		int y = 50000; // exceeds 15 bits
		int plane = 7; // exceeds 2 bits
		int packed = WorldPointUtil.packWorldPoint(x, y, plane);
		assertEquals(x & 0x7FFF, WorldPointUtil.unpackWorldX(packed));
		assertEquals(y & 0x7FFF, WorldPointUtil.unpackWorldY(packed));
		assertEquals(plane & 0x3, WorldPointUtil.unpackWorldPlane(packed));
	}

	@Test
	public void dxdyOffsetsCorrectly()
	{
		int base = WorldPointUtil.packWorldPoint(3200, 3200, 1);
		int moved = WorldPointUtil.dxdy(base, 5, -7);
		assertEquals(3200 + 5, WorldPointUtil.unpackWorldX(moved));
		assertEquals(3200 - 7, WorldPointUtil.unpackWorldY(moved));
		assertEquals(1, WorldPointUtil.unpackWorldPlane(moved));
	}

	@Test
	public void distanceChebyshevAndManhattan()
	{
		int a = WorldPointUtil.packWorldPoint(10, 10, 0);
		int b = WorldPointUtil.packWorldPoint(15, 13, 0); // dx=5 dy=3
		assertEquals(5, WorldPointUtil.distanceBetween(a, b)); // Chebyshev
		assertEquals(5, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.CHEBYSHEV_DISTANCE_METRIC)); // Chebyshev
		assertEquals(5, WorldPointUtil.distanceBetween2D(a, b)); // Chebyshev 2D
		assertEquals(5 + 3, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.MANHATTAN_DISTANCE_METRIC)); // Manhattan
		assertEquals(5 * 5 + 3 * 3, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC)); // Euclidean
		// squared
		assertEquals(5 * 5 + 3 * 3, WorldPointUtil.distanceBetween(a, b, 99));
	}

	@Test
	public void distanceDifferentPlanesReturnsMax()
	{
		int a = WorldPointUtil.packWorldPoint(10, 10, 0);
		int b = WorldPointUtil.packWorldPoint(11, 11, 1);
		assertEquals(Integer.MAX_VALUE, WorldPointUtil.distanceBetween(a, b));
	}

	@Test
	public void distanceWorldPointOverloads()
	{
		WorldPoint a = new WorldPoint(100, 150, 0);
		WorldPoint b = new WorldPoint(103, 160, 0); // dx=3 dy=10
		assertEquals(10, WorldPointUtil.distanceBetween(a, b)); // Chebyshev
		assertEquals(10 + 3, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.MANHATTAN_DISTANCE_METRIC)); // Manhattan
		assertEquals(10 * 10 + 3 * 3,
			WorldPointUtil.distanceBetween(a, b, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC)); // Euclidean squared
	}

	@Test
	public void distanceToAreaInsideAndOutside()
	{
		WorldArea area = new WorldArea(3000, 4000, 5, 4, 0); // x:[3000..3004], y:[4000..4003]
		int inside = WorldPointUtil.packWorldPoint(3002, 4001, 0);
		int leftOutside = WorldPointUtil.packWorldPoint(2995, 4002, 0);
		int diagOutside = WorldPointUtil.packWorldPoint(2990, 3990, 0);
		int otherPlane = WorldPointUtil.packWorldPoint(3002, 4001, 1);

		assertEquals(0, WorldPointUtil.distanceToArea(inside, area));
		assertEquals(0, WorldPointUtil.distanceToArea2D(inside, area));
		// leftOutside: dx = 3000-2995=5, dy=0 => Chebyshev 5
		assertEquals(5, WorldPointUtil.distanceToArea(leftOutside, area));
		assertEquals(5, WorldPointUtil.distanceToArea2D(leftOutside, area));
		// diagOutside: dx=3000-2990=10, dy=4000-3990=10 => Chebyshev 10
		assertEquals(10, WorldPointUtil.distanceToArea(diagOutside, area));
		assertEquals(10, WorldPointUtil.distanceToArea2D(diagOutside, area));
		// plane mismatch
		assertEquals(Integer.MAX_VALUE, WorldPointUtil.distanceToArea(otherPlane, area));
	}

	@Test
	public void toLocalPointWithinScene()
	{
		Client client = Mockito.mock(Client.class);
		WorldView worldView = Mockito.mock(WorldView.class);
		Mockito.when(client.getTopLevelWorldView()).thenReturn(worldView);
		Mockito.when(worldView.getPlane()).thenReturn(0);
		Mockito.when(worldView.getBaseX()).thenReturn(3200);
		Mockito.when(worldView.getBaseY()).thenReturn(3200);
		Mockito.when(worldView.getSizeX()).thenReturn(104); // typical scene size
		Mockito.when(worldView.getSizeY()).thenReturn(104);
		Mockito.when(worldView.getId()).thenReturn(0);

		int packed = WorldPointUtil.packWorldPoint(3210, 3220, 0);
		LocalPoint lp = WorldPointUtil.toLocalPoint(client, packed);
		assertNotNull(lp);
		int expectedLocalX = ((3210 - 3200) << LOCAL_COORD_BITS) + (1 << (LOCAL_COORD_BITS - 1));
		int expectedLocalY = ((3220 - 3200) << LOCAL_COORD_BITS) + (1 << (LOCAL_COORD_BITS - 1));
		assertEquals(expectedLocalX, lp.getX());
		assertEquals(expectedLocalY, lp.getY());
	}

	@Test
	public void toLocalPointOutOfSceneOrPlane()
	{
		Client client = Mockito.mock(Client.class);
