	/**
	 * Packs an instance template chunk entry the way the client does: rotation in bits 1-2,
	 * template chunk Y (world y / 8) in bits 3-13, template chunk X (world x / 8) in bits 14-23,
	 * template plane in bits 24-25.
	 */
	private static int templateChunk(int worldX, int worldY, int plane, int rotation)
	{
		return (rotation << 1) | ((worldY / CHUNK_SIZE) << 3) | ((worldX / CHUNK_SIZE) << 14) | (plane << 24);
	}

	private static WorldView instanceOf(int... chunkData)
	{
		WorldView worldView = Mockito.mock(WorldView.class);
		Mockito.when(worldView.isInstance()).thenReturn(true);
		int[][][] chunks = new int[1][1][chunkData.length];
		chunks[0][0] = chunkData;
		Mockito.when(worldView.getInstanceTemplateChunks()).thenReturn(chunks);
		return worldView;
	}

	@Test
	public void describeInstanceChunksDecodesTemplateOrigins()
	{
		// The debug chunk dump is the diagnostic that identified the live POH template band —
		// pin its decoding (empty slots skipped, distinct origins listed with plane).
		String described = WorldPointUtil.describeInstanceChunks(instanceOf(
			-1, templateChunk(1864, 7040, 0, 0), templateChunk(1856, 7096, 1, 2)));
		assertTrue(described, described.contains("(1864,7040,p0)"));
		assertTrue(described, described.contains("(1856,7096,p1)"));
		assertEquals("not an instance", WorldPointUtil.describeInstanceChunks(null));
	}
}

package gps.dev;

import gps.WorldPointUtil;
import java.util.List;
import java.util.function.IntPredicate;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Captures across multi-tile objects (a 4-wide lava gap, 2-wide climbing rocks) only record
 * the lane actually traversed — {@link TransportAuditPlugin#expandCaptureLanes} translates
 * the capture to the sibling lanes of the footprint. Real cases from the Mount Karuulm
 * field session that motivated it.
 */
public class ExpandCaptureLanesTest
{
	private static final IntPredicate OPEN = p -> false;

	private static int tile(int x, int y, int plane)
	{
		return WorldPointUtil.packWorldPoint(x, y, plane);
	}

	@Test
	public void twoLaneRocksDeriveTheOtherLane()
	{
		// Rocks 34548 (2x1 at x 1351-1352): southbound was only captured on the x=1351 lane.
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1351, 10252, 0), tile(1351, 10250, 0), 1351, 1352, OPEN);
		assertEquals(1, lanes.size());
		assertArrayEquals(new int[]{tile(1352, 10252, 0), tile(1352, 10250, 0)}, lanes.get(0));
	}

	@Test
	public void fourLaneGapDerivesThreeSiblings()
	{
		// Lava gap 34515 (4 lanes, x 1269-1272), jumped north on the x=1269 lane.
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1269, 10170, 0), tile(1269, 10175, 0), 1269, 1272, OPEN);
		assertEquals(3, lanes.size());
		assertArrayEquals(new int[]{tile(1270, 10170, 0), tile(1270, 10175, 0)}, lanes.get(0));
		assertArrayEquals(new int[]{tile(1271, 10170, 0), tile(1271, 10175, 0)}, lanes.get(1));
		assertArrayEquals(new int[]{tile(1272, 10170, 0), tile(1272, 10175, 0)}, lanes.get(2));
	}

	@Test
	public void blockedLanesAreDropped()
	{
		IntPredicate blocked = p -> WorldPointUtil.unpackWorldX(p) == 1271;
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1269, 10170, 0), tile(1269, 10175, 0), 1269, 1272, blocked);
		assertEquals(2, lanes.size());
	}

	@Test
	public void crossPlaneStepsKeepEachEndpointsPlane()
	{
		// Steps 34530: up from plane 0 to plane 1, two lanes (y 10205-10206).
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1329, 10205, 0), tile(1334, 10205, 1), 10205, 10206, OPEN);
		assertEquals(1, lanes.size());
		assertArrayEquals(new int[]{tile(1329, 10206, 0), tile(1334, 10206, 1)}, lanes.get(0));
	}

	@Test
	public void diagonalTravelIsNotExpanded()
	{
		assertTrue(TransportAuditPlugin.expandCaptureLanes(
			tile(1270, 10176, 0), tile(1272, 10174, 0), 1269, 1272, OPEN).isEmpty());
	}

	@Test
	public void angledWalkInApproachIsNotExpanded()
	{
		// Origin lane coordinate outside the footprint span (the Karuulm steps were clicked
		// from 2-3 tiles out, so the recorded origin never lined up with a lane).
		assertTrue(TransportAuditPlugin.expandCaptureLanes(
			tile(1313, 10191, 1), tile(1318, 10189, 2), 10188, 10189, OPEN).isEmpty());
	}
}

package gps.dev;

import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

/**
 * Every machine-derived (~geometry) transport row in the Mount Karuulm dungeon must have
 * WALKABLE endpoints — a translated lane whose origin or landing is collision-blocked is a
 * dead edge at best and a wrong route at worst. Guards the capture lane expansion's output
 * and the retro-filled lanes alike.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class KaruulmDerivedRowsTest
{
	private static final int MIN_X = 1250;
	private static final int MAX_X = 1420;
	private static final int MIN_Y = 10150;
	private static final int MAX_Y = 10300;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void derivedKaruulmRowsHaveWalkableEndpoints()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		CollisionMap map = planning.getMap();

		List<MetaEdges.Entry> derived = MetaEdges.load().stream()
			.filter(e -> e.tags.contains("~geometry"))
			.filter(e -> inKaruulm(e.origin) || inKaruulm(e.destination))
			.collect(Collectors.toList());
		assertFalse("expected Karuulm ~geometry rows (lane fills + pipe)", derived.isEmpty());

		StringBuilder problems = new StringBuilder();
		for (MetaEdges.Entry entry : derived)
		{
			checkWalkable(map, entry.origin, "origin", entry, problems);
			checkWalkable(map, entry.destination, "destination", entry, problems);
		}
		assertTrue("blocked endpoints on derived rows:\n" + problems, problems.length() == 0);
	}

	private static boolean inKaruulm(int packed)
	{
		if (packed == WorldPointUtil.UNDEFINED)
		{
			return false;
		}
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		return x >= MIN_X && x <= MAX_X && y >= MIN_Y && y <= MAX_Y;
	}

	private static void checkWalkable(CollisionMap map, int packed, String which,
		MetaEdges.Entry entry, StringBuilder problems)
	{
		if (packed == WorldPointUtil.UNDEFINED)
		{
			return;
		}
		if (map.isBlocked(WorldPointUtil.unpackWorldX(packed), WorldPointUtil.unpackWorldY(packed),
			WorldPointUtil.unpackWorldPlane(packed)))
		{
			problems.append(entry.menu).append(' ').append(which).append(' ')
				.append(WorldPointUtil.unpackWorldX(packed)).append(',')
				.append(WorldPointUtil.unpackWorldY(packed)).append(',')
				.append(WorldPointUtil.unpackWorldPlane(packed)).append('\n');
		}
	}
}

package gps.dev;

import gps.WorldPointUtil;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Loader for the transport files' Meta column (dev audit only — the plugin runtime ignores it).
 * Compact vocabulary, absence = trusted: {@code ~field} means the value is machine-estimated
 * (cache geometry, family-calibrated ticks) and {@code ?field} means it awaits confirmation
 * (e.g. an unverified varbit gate). The audit shows these in-game so field sessions can confirm
 * them; once confirmed, the tag is removed from the row and the entry disappears here.
 */
final class MetaEdges
{
	/** One tagged row: where to go, what to do, and which tags are outstanding. */
	static final class Entry
	{
		final int origin;      // UNDEFINED for origin-less teleports (confirmable only by use)
		final int destination; // UNDEFINED when the row has no destination column value
		final String menu;
		final String duration;
		final String tags;
		final String file;

		Entry(int origin, int destination, String menu, String duration, String tags, String file)
		{
			this.origin = origin;
			this.destination = destination;
			this.menu = menu;
			this.duration = duration;
			this.tags = tags;
			this.file = file;
		}

		String describe()
		{
			String where = origin != WorldPointUtil.UNDEFINED
				? WorldPointUtil.unpackWorldX(origin) + "," + WorldPointUtil.unpackWorldY(origin)
				+ "," + WorldPointUtil.unpackWorldPlane(origin)
				: "(no origin)";
			return (menu.isEmpty() ? file : menu) + " @" + where + " [" + tags + "]";
		}
	}

	private MetaEdges()
	{
	}

	private static final String[] FILES = {
		"transports.tsv", "agility_shortcuts.tsv", "boats.tsv", "canoes.tsv", "charter_ships.tsv",
		"fairy_rings.tsv", "gnome_gliders.tsv", "hot_air_balloons.tsv", "magic_carpets.tsv",
		"magic_mushtrees.tsv", "minecarts.tsv", "mountain_guides.tsv", "quetzal_whistle.tsv",
		"quetzals.tsv", "ships.tsv", "spirit_trees.tsv", "teleportation_boxes.tsv",
		"teleportation_items.tsv", "teleportation_levers.tsv", "teleportation_minigames.tsv",
		"teleportation_portals.tsv", "teleportation_portals_poh.tsv", "teleportation_spells.tsv",
		"wilderness_obelisks.tsv",
	};

	/** Every row across the transport files whose Meta column is non-empty. */
	static List<Entry> load()
	{
		List<Entry> entries = new ArrayList<>();
		for (String file : FILES)
		{
			try (InputStream in = MetaEdges.class.getResourceAsStream("/transports/" + file))
			{
				if (in == null)
				{
					continue;
				}
				try (Scanner scanner = new Scanner(in, "UTF-8"))
				{
					String[] headers = null;
					int metaIndex = -1;
					while (scanner.hasNextLine())
					{
						String line = scanner.nextLine();
						if (headers == null)
						{
							headers = (line.startsWith("# ") ? line.substring(2) : line).split("\t");
							for (int i = 0; i < headers.length; i++)
							{
								if ("Meta".equals(headers[i].trim()))
								{
									metaIndex = i;
								}
							}
							if (metaIndex < 0)
							{
								break; // no Meta column in this file
							}
							continue;
						}
						if (line.startsWith("#") || line.isBlank())
						{
							continue;
						}
						String[] fields = line.split("\t", -1);
						if (metaIndex >= fields.length || fields[metaIndex].trim().isEmpty())
						{
							continue;
						}
						entries.add(new Entry(
							parseTile(column(headers, fields, "Origin")),
							parseTile(column(headers, fields, "Destination")),
							column(headers, fields, "menuOption menuTarget objectID").trim(),
							column(headers, fields, "Duration").trim(),
							fields[metaIndex].trim(),
							file));
					}
				}
			}
			catch (Exception e)
			{
				// dev tooling: skip unreadable files rather than break the client
			}
		}
		return entries;
	}

	private static String column(String[] headers, String[] fields, String name)
	{
		for (int i = 0; i < headers.length && i < fields.length; i++)
		{
			if (name.equals(headers[i].trim()))
			{
				return fields[i];
			}
		}
		return "";
	}

	static int parseTile(String text)
	{
		String[] parts = text.trim().split(" ");
		if (parts.length < 3)
		{
			return WorldPointUtil.UNDEFINED;
		}
		try
		{
			return WorldPointUtil.packWorldPoint(Integer.parseInt(parts[0]),
				Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
		}
		catch (NumberFormatException e)
		{
			return WorldPointUtil.UNDEFINED;
		}
	}
}

package gps.dev;

import gps.WorldPointUtil;
import gps.transport.Transport;
import gps.transport.TransportLoader;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The single-file metadata model: Meta-tagged rows are loadable for the dev audit's
 * needs-confirmation view, while the runtime loader keeps parsing tagged rows exactly like
 * untagged ones (the Meta column is invisible to routing).
 */
public class MetaEdgesTest
{
	@Test
	public void tagsAreLoadableAndPlentiful()
	{
		List<MetaEdges.Entry> entries = MetaEdges.load();
		assertTrue("expected hundreds of tagged rows, got " + entries.size(), entries.size() > 500);
		assertTrue("the Honour varbit gate must be tagged ?varbits",
			entries.stream().anyMatch(e -> e.tags.contains("?varbits")));
		assertTrue("derived rows must be tagged ~geometry",
			entries.stream().filter(e -> e.tags.contains("~geometry")).count() > 500);
	}

	@Test
	public void runtimeLoaderIsUnaffectedByTags()
	{
		// A calibrated derived row (ladder-up, family mode 4 ticks) parses with its real values.
		int origin = WorldPointUtil.packWorldPoint(1204, 3119, 0);
		int dest = WorldPointUtil.packWorldPoint(1203, 3118, 1);
		Set<Transport> transports = TransportLoader.loadAllFromResources()
			.getOrDefault(origin, Set.of());
		Transport ladder = transports.stream()
			.filter(t -> t.getDestination() == dest)
			.findFirst().orElseThrow(() -> new AssertionError("tagged ladder row not loaded"));
		assertEquals("calibrated duration must survive the Meta column", 4, ladder.getDuration());
	}
}

package gps.dev;

import gps.WorldPointUtil;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * The one-way/two-way pairing rules, pinned with the exact field data that exposed two bugs:
 * live captures read as ONE-WAY until restart (pairing was never recomputed on capture — fixed
 * at the completeCapture call site, exercised here by recomputing after each add the way that
 * site now does), and same-plane short hops (rockslides) paired with THEMSELVES through the
 * 5-tile tolerance, showing two-way after a single direction.
 */
public class TransportAuditPairingTest
{
	private static int tile(int x, int y, int p)
	{
		return WorldPointUtil.packWorldPoint(x, y, p);
	}

	private static TransportAuditPlugin plugin()
	{
		return new TransportAuditPlugin();
	}

	@Test
	public void varlamoreStairsPairAcrossTheTwoObjects()
	{
		// The user's captures, verbatim: descent via 27856 and ascent via 27854.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(1610, 3796, 1), tile(1617, 3796, 0), 27856});
		plugin.recomputeEdgePairs();
		assertEquals("only one direction captured yet",
			TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY,
			plugin.capturedState(27856, tile(1613, 3797, 1), true));

		plugin.capturedEdges.add(new int[]{tile(1617, 3796, 0), tile(1610, 3796, 1), 27854});
		plugin.recomputeEdgePairs();
		assertEquals("both directions captured — must read as complete, LIVE, without a restart",
			TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(27856, tile(1613, 3797, 1), true));
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(27854, tile(1615, 3797, 0), true));
	}

	@Test
	public void samePlaneShortHopDoesNotPairWithItself()
	{
		// An Underground Pass rockslide: origin and dest 2 tiles apart on the same plane — well
		// inside the 5-tile pairing tolerance, so without the identity/direction checks it
		// paired with itself and showed two-way after a single crossing.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2485, 9722, 0), 3309});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}

	@Test
	public void samePlaneShortHopPairsWithItsRealReverse()
	{
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2485, 9722, 0), 3309});
		plugin.capturedEdges.add(new int[]{tile(2485, 9722, 0), tile(2485, 9720, 0), 3309});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}

	@Test
	public void sameDirectionJitterDuplicateIsNotAReverse()
	{
		// Two captures of the SAME crossing with 1-tile landing jitter: same direction, so they
		// must not satisfy each other's reverse check.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2485, 9722, 0), 3309});
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2486, 9722, 0), 3309});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}

	@Test
	public void crossPlanePairsViaSeparateObjects()
	{
		// Cave entrance/exit style: each object one-directional; together a round trip.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2435, 3314, 0), tile(2495, 9716, 0), 3213});
		plugin.capturedEdges.add(new int[]{tile(2496, 9713, 0), tile(2436, 3315, 0), 3214});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3213, tile(2434, 3315, 0), true));
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3214, tile(2498, 9716, 0), true));
	}

	@Test
	public void operatorOneWayMarkerCompletesTheEdge()
	{
		TransportAuditPlugin plugin = plugin();
		int[] edge = {tile(2485, 9720, 0), tile(2485, 9722, 0), 3309};
		plugin.capturedEdges.add(edge);
		plugin.noReverseKeys.add("2485 9720 0|2485 9722 0|3309");
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}
}

