		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		RouteOption bankedRoute = finalRoutes.get().stream()
			.filter(RouteOption::isViaBank)
			.findFirst().orElse(null);
		assertTrue("A route via the bank should exist", bankedRoute != null);
		return bankedRoute.getTotalCost();
	}

	@Test
	public void routesAreOrderedByEtaWhenUnweighted() throws Exception
	{
		// With no configured weights (the mock returns 0 for every cost item), the blended cost must
		// equal the raw time-normalized cost, so the list order IS the ETA order — the bug this
		// guards against was ticks and tiles blending 1:1, letting a slower route sort first. Each
		// route's raw cost must also decompose exactly into its walked units plus its transport
		// travel times at 2 units per tick.
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(false);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(FAR_START, Set.of(TARGET), Set.of(), AlternativeRoutesMode.OWNED_INVENTORY, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		service.shutdown();

		List<RouteOption> routes = finalRoutes.get();
		assertTrue("Expected at least a teleport route and the walk option", routes.size() >= 2);
		int previousRaw = Integer.MIN_VALUE;
		for (RouteOption route : routes)
		{
			assertTrue("Unweighted: blended cost must equal the raw (ETA) cost, got "
					+ route.getTotalCost() + " vs " + route.getRawCost(),
				route.getTotalCost() == route.getRawCost());
			assertTrue("Routes must be ordered by ETA (raw cost), got " + route.getRawCost()
					+ " after " + previousRaw,
				route.getRawCost() >= previousRaw);
			previousRaw = route.getRawCost();

			int walked = route.getTrailingWalkSteps();
			int transportUnits = 0;
			for (int m = 0; m < route.getMethods().size(); m++)
			{
				walked += route.walkBefore(m);
			}
			for (int duration : route.getMethodDurations())
			{
				transportUnits += CostUnits.fromTicks(duration);
			}
			assertTrue("Raw cost must decompose into walk units + 2×duration ticks ("
					+ route.getRawCost() + " != " + walked + " + " + transportUnits + ")",
				route.getRawCost() == walked + transportUnits);
		}
	}

	@Test
	public void roundTripRoutesGoOutAndComeBack() throws Exception
	{
		// "Bank (and back)": every produced route must end where it started, be flagged as a round
		// trip, and the list must be ranked by the combined out-and-back cost.
		int varrockCentre = WorldPointUtil.packWorldPoint(3213, 3424, 0);
		Set<Integer> bankTiles = gps.Destinations.tilesForCategory("bank_round_trip", null);
		assertTrue("Round-trip category must resolve to the bank tiles",
			bankTiles.equals(gps.Destinations.tilesForCategory("bank", null)) && !bankTiles.isEmpty());

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(false);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(varrockCentre, bankTiles, Set.of(), AlternativeRoutesMode.OWNED_INVENTORY, 5, 0, true,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		service.shutdown();

		List<RouteOption> routes = finalRoutes.get();
		assertTrue("Round-trip routes should be found", !routes.isEmpty());
		int previousCost = -1;
		for (RouteOption route : routes)
		{
			assertTrue("Every route must be flagged as a round trip", route.isRoundTrip());
			assertTrue("Every route must reach", route.isReached());
			int first = route.getPath().get(0).getPackedPosition();
			int last = route.getPath().get(route.getPath().size() - 1).getPackedPosition();
			assertTrue("The route must start at the player", first == varrockCentre);
			assertTrue("The route must END back at the player (round trip), ended "
					+ WorldPointUtil.distanceBetween(last, varrockCentre) + " tiles away",
				last == varrockCentre);
			// The turnaround (where the outbound leg ends — the bank) must be a real interior
			// index away from the start: progress/arrival gate the return leg behind it.
			int turnaround = route.getTurnaroundIndex();
			assertTrue("Turnaround must be an interior path index, got " + turnaround,
				turnaround > 0 && turnaround < route.getPath().size() - 1);
			assertTrue("The turnaround tile must not be the start tile",
				route.getPath().get(turnaround).getPackedPosition() != varrockCentre);
			assertTrue("Routes must be ranked by combined cost", route.getTotalCost() >= previousCost);
			previousCost = route.getTotalCost();
		}
	}

