package gps.pathfinder;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.WorldPointUtil;
import gps.transport.TransportType;

/**
 * Captain Barnaby's ships (Ardougne / Brimhaven / Rimmington) drop you on the boat DECK, from which
 * you cross a gangplank to disembark — so the ship transports must land on the deck tile, not the
 * post-gangplank land tile. Landing on land skipped the gangplank: the route couldn't be tracked
 * (and the overlay froze on "Use ...") until the player had already crossed it by hand.
 */
@RunWith(MockitoJUnitRunner.class)
public class BarnabyShipTest
{
	private static final int ARDOUGNE_DOCK = WorldPointUtil.packWorldPoint(2683, 3271, 0);
	private static final int BRIMHAVEN_DECK = WorldPointUtil.packWorldPoint(2775, 3234, 1);
	private static final int BRIMHAVEN_LAND = WorldPointUtil.packWorldPoint(2772, 3234, 0);
	private static final int ARDOUGNE_DECK = WorldPointUtil.packWorldPoint(2683, 3268, 1);
	private static final int ARDOUGNE_LAND = WorldPointUtil.packWorldPoint(2683, 3271, 0);
	private static final int RIMMINGTON_DECK = WorldPointUtil.packWorldPoint(2915, 3222, 1);
	private static final int RIMMINGTON_LAND = WorldPointUtil.packWorldPoint(2915, 3225, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	@Test
	public void ardougneToBrimhavenLandsOnTheDeckAndCrossesTheGangplank()
	{
		// Ships only: every method-type but SHIP is excluded (gangplanks are plain walking connectors,
		// not methods, so they stay). Brimhaven is an island, so the Barnaby ship is the only route.
		PathfinderConfig config = everythingConfig();
		Set<TeleportMethod> excludeNonShips = new HashSet<>();
		for (TeleportMethod method : config.getMethodCatalog())
		{
			if (method.getType() != TransportType.SHIP)
			{
				excludeNonShips.add(method);
			}
		}
		config.rebuildAvailabilityWithExclusions(excludeNonShips);

		Pathfinder pathfinder = new Pathfinder(config, ARDOUGNE_DOCK, Set.of(BRIMHAVEN_LAND));
		pathfinder.run();

		assertTrue("Ardougne -> Brimhaven must be reachable by the Barnaby ship",
			pathfinder.getResult().isReached());
		List<PathStep> path = pathfinder.getResult().getPathSteps();
		assertTrue("the route must land on the Brimhaven boat deck, then cross the gangplank — "
				+ "landing straight on land would skip the gangplank the player must actually cross",
			path.stream().anyMatch(s -> s.getPackedPosition() == BRIMHAVEN_DECK));
	}

	@Test
	public void everyBarnabyDeckCanDisembark()
	{
		// Each tile the ships now land on must have a way off (guards against a dead-end landing).
		assertDisembark(BRIMHAVEN_DECK, BRIMHAVEN_LAND);
		assertDisembark(ARDOUGNE_DECK, ARDOUGNE_LAND);
		assertDisembark(RIMMINGTON_DECK, RIMMINGTON_LAND);
	}

	private void assertDisembark(int deck, int land)
	{
		Pathfinder pathfinder = new Pathfinder(everythingConfig(), deck, Set.of(land));
		pathfinder.run();
		assertTrue("boat deck " + WorldPointUtil.unpackWorldPoint(deck) + " must disembark to land",
			pathfinder.getResult().isReached());
	}
}

package gps.pathfinder;

import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N7: the Moss Giant Island rope swing lands on a BLOCKED tile (2704,3209). The reverse
 * flood never steps onto blocked tiles unless they host a transport origin, so the landing was
 * only valued by the post-flood patch, after the loop that would have followed its reverse edge
 * into the rope's origin (2709,3209) had ended. Everything behind the rope read as unreachable:
 * the field declared a reachable island target provably unreachable (the escape menu then
 * replaced the real page), and for any target behind a blocked jetty or platform the heuristic
 * sent the far side to its floor, overestimating and burying routes through it.
 */
@RunWith(MockitoJUnitRunner.class)
public class BlockedLandingReverseEdgeTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private static final int ISLAND = WorldPointUtil.packWorldPoint(2705, 3205, 0);
	private static final int ROPE_ORIGIN = WorldPointUtil.packWorldPoint(2709, 3209, 0);
	private static final int ROPE_LANDING = WorldPointUtil.packWorldPoint(2704, 3209, 0);
	private static final int BRIMHAVEN_DOCK = WorldPointUtil.packWorldPoint(2772, 3225, 0);

	@Test
	public void reverseEdgesOutOfABlockedLandingAreFollowed()
	{
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		PathfinderConfig pathConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		pathConfig.refresh();
		assertTrue("premise: the rope lands on a blocked tile", pathConfig.getMap().isBlocked(2704, 3209, 0));

		DistanceField field = DistanceField.build(pathConfig, Set.of(ISLAND));
		int landing = field.distance(ROPE_LANDING);
		int origin = field.distance(ROPE_ORIGIN);
		int dock = field.distance(BRIMHAVEN_DOCK);
		System.out.println("BLOCKEDLANDING landing=" + landing + " origin=" + origin + " dock=" + dock);
		assertTrue("the landing itself is valued", landing != DistanceField.UNREACHED);
		assertTrue("the rope's origin must be reached through the landing's reverse edge", origin != DistanceField.UNREACHED);
		assertTrue("the mainland behind the rope must be flooded", dock != DistanceField.UNREACHED);

		// Admissibility: the field is a lower bound on the forward cost from the dock.
		Pathfinder pathfinder = new Pathfinder(pathConfig, BRIMHAVEN_DOCK, Set.of(ISLAND), Integer.MAX_VALUE, null);
		pathfinder.run();
		assertTrue("premise: the island is reachable on foot from the dock", pathfinder.getResult().isReached());
		int forward = pathfinder.getResult().getTotalCost();
		System.out.println("BLOCKEDLANDING forward from dock=" + forward);
		assertTrue("field " + dock + " must not exceed the forward cost " + forward, dock <= forward);
	}
}

package gps.pathfinder;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * The bounded (floor-limited) distance-field flood must be invisible to every search result: the
 * horizon only weakens the heuristic beyond the returnable cost band, never changes a cost. Each
 * scenario runs A* with the bounded field against {@link ReferenceDijkstra} — including with the
 * best method excluded (a chain#1-style search, whose floor rises above the build-time floor) —
 * and samples heuristic consistency across the flood frontier, where truncation could break the
 * triangle inequality if the unflooded fallback were wrong.
 */
@RunWith(MockitoJUnitRunner.class)
public class BoundedDistanceFieldTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);
	private static final int GRAND_EXCHANGE = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	private static final int SHILO_VILLAGE = WorldPointUtil.packWorldPoint(2852, 2954, 0);
	private static final int COST_MULTIPLE = 3;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		Pathfinder.validateSettleOrder = true;
	}

	@After
	public void after()
	{
		Pathfinder.validateSettleOrder = false;
	}

	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static void assertBoundedMatchesOracle(PathfinderConfig cfg, int start, Set<Integer> targets)
	{
		DistanceField bounded = DistanceField.build(cfg, targets, COST_MULTIPLE);
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(cfg, bounded);
		assertNotNull(heuristic);

		ReferenceDijkstra.Result oracle = ReferenceDijkstra.search(cfg, start, targets);
		Pathfinder astar = new Pathfinder(cfg, start, targets, Integer.MAX_VALUE, heuristic);
		astar.run();

		assertEquals("bounded-field A* reached must match the oracle",
			oracle.reached, astar.getResult().isReached());
		if (oracle.reached)
		{
			assertEquals("bounded-field A* must return the oracle's minimal cost",
				oracle.cost, astar.getResult().getTotalCost());
		}
	}

	@Test
	public void boundedFieldSearchesMatchTheOracle()
	{
		PathfinderConfig cfg = everythingConfig();
		assertBoundedMatchesOracle(cfg, LUMBRIDGE, Set.of(BARROWS));
		assertBoundedMatchesOracle(cfg, GRAND_EXCHANGE, Set.of(SHILO_VILLAGE));
	}

	/**
	 * A chain-style search whose exclusions RAISE the per-search floor past the build-time floor the
	 * horizon was sized from — the exact regime where an unflooded tile's fallback must stay
	 * min(horizon, floor) and not the (now larger) floor alone. Excludes every method whose teleport
	 * lands inside the flooded zone (the floor-setters), the harshest version of the regime.
	 */
	@Test
	public void boundedFieldStaysOptimalWhenExclusionsRaiseTheFloor()
	{
		PathfinderConfig cfg = everythingConfig();
		Set<Integer> targets = Set.of(BARROWS);
		DistanceField bounded = DistanceField.build(cfg, targets, COST_MULTIPLE);
		assertTrue("the flood must actually be bounded", bounded.horizon() != Integer.MAX_VALUE);

		Set<TeleportMethod> excluded = new HashSet<>();
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (Transport teleport : cfg.getUsableTeleports(bankVisited))
			{
				if (teleport.getDestination() != WorldPointUtil.UNDEFINED
					&& bounded.distance(teleport.getDestination()) != DistanceField.UNREACHED
					&& TeleportMethod.isMethodType(teleport.getType()))
				{
					excluded.add(TeleportMethod.fromTransport(teleport));
				}
			}
		}
		assertTrue("some floor-setting teleports must exist to exclude", !excluded.isEmpty());
		cfg.rebuildAvailabilityWithExclusions(excluded);

		SearchHeuristic excludedHeuristic = SearchHeuristic.buildWithField(cfg, bounded);
		ReferenceDijkstra.Result oracle = ReferenceDijkstra.search(cfg, LUMBRIDGE, targets);
		Pathfinder astar = new Pathfinder(cfg, LUMBRIDGE, targets, Integer.MAX_VALUE, excludedHeuristic);
		astar.run();
		assertEquals(oracle.reached, astar.getResult().isReached());
		if (oracle.reached)
		{
			assertEquals("excluded-method search on the bounded field must stay optimal",
				oracle.cost, astar.getResult().getTotalCost());
		}
	}

	/**
	 * Consistency across the flood frontier: h(a) <= 1 + h(b) for walkable neighbours in a band
	 * spanning flooded and unflooded tiles. A wrong unflooded fallback (e.g. the raw floor) breaks
	 * the inequality exactly here.
	 */
	@Test
	public void heuristicStaysConsistentAcrossTheFrontier()
	{
		PathfinderConfig cfg = everythingConfig();
		DistanceField bounded = DistanceField.build(cfg, Set.of(BARROWS), COST_MULTIPLE);
		assertTrue("the flood must actually be bounded for this test to mean anything",
			bounded.horizon() != Integer.MAX_VALUE);
		SearchHeuristic h = SearchHeuristic.buildWithField(cfg, bounded);
		CollisionMap map = cfg.getMap();

		final int bx = 3566;
		final int by = 3291;
		// Wide box around the target: comfortably covers the horizon ring on all sides.
		final int radius = bounded.horizon() + 80;
		int violations = 0;
		int frontierPairs = 0;
		for (int x = bx - radius; x <= bx + radius; x++)
		{
			for (int y = by - radius; y <= by + radius; y++)
			{
				if (map.isBlocked(x, y, 0))
				{
					continue;
				}
				final int ha = h.of(WorldPointUtil.packWorldPoint(x, y, 0));
				final int[][] steps = {{x - 1, y}, {x + 1, y}, {x, y - 1}, {x, y + 1}};
				final boolean[] open = {map.w(x, y, 0), map.e(x, y, 0), map.s(x, y, 0), map.n(x, y, 0)};
				for (int i = 0; i < steps.length; i++)
				{
					if (!open[i])
					{
						continue;
					}
					final int b = WorldPointUtil.packWorldPoint(steps[i][0], steps[i][1], 0);
					final int hb = h.of(b);
					final boolean aFlooded = bounded.distance(WorldPointUtil.packWorldPoint(x, y, 0)) != DistanceField.UNREACHED;
					final boolean bFlooded = bounded.distance(b) != DistanceField.UNREACHED;
					if (aFlooded != bFlooded)
					{
						frontierPairs++;
					}
					if (ha > 1 + hb)
					{
						violations++;
					}
				}
			}
		}
		assertTrue("the sample must actually cross the frontier", frontierPairs > 0);
		assertEquals("consistency violations across the frontier", 0, violations);
	}
}

package gps.pathfinder;

import gps.JewelleryBoxTier;
import gps.MethodAvailability;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.TeleportationItem;
import gps.TypeOverrides;
import gps.transport.TransportType;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The rule: a method row never leaves the catalog for a structural reason — house off, a
 * jewellery-box tier not built, mounts off — it stays listed with a lock and a reason. The one
 * exception is seasonal content, which only exists on seasonal worlds.
 */
@RunWith(MockitoJUnitRunner.class)
public class CatalogNeverShrinksTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@After
	public void clearTypeOverrides()
	{
		TypeOverrides.clear();
	}

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(config.usePoh()).thenReturn(true);
		when(config.usePohMountedItems()).thenReturn(true);
		when(config.pohMountGlory()).thenReturn(true);
		when(config.pohMountXerics()).thenReturn(true);
		when(config.pohMountDigsite()).thenReturn(true);
		when(config.pohMountMythical()).thenReturn(true);
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.ORNATE);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig planning()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static TeleportMethod first(Map<TeleportMethod, MethodAvailability> availability, TransportType type,
		String labelPrefix)
	{
		for (TeleportMethod method : availability.keySet())
		{
			if (method.getType() == type && (labelPrefix == null || method.label().startsWith(labelPrefix)))
			{
				return method;
			}
		}
		return null;
	}

	@Test
	public void houseOffLocksItsMethodsInsteadOfRemovingThem()
	{
		int withHouse = planning().getMethodCatalog().size();
		when(config.usePoh()).thenReturn(false);
		PathfinderConfig off = planning();
		assertEquals("the catalog must not shrink when the house is switched off",
			withHouse, off.getMethodCatalog().size());
		Map<TeleportMethod, MethodAvailability> availability = off.getMethodAvailability();
		TeleportMethod box = first(availability, TransportType.TELEPORTATION_BOX, null);
		assertTrue("a house method is still listed", box != null);
		assertEquals(MethodAvailability.LOCKED, availability.get(box));
		assertEquals("House is off (House section)", off.getMethodAvailabilityDetail().get(box));
	}

	@Test
	public void boxTierLocksHigherTierDestinations()
	{
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.NONE);
		PathfinderConfig none = planning();
		Map<TeleportMethod, MethodAvailability> availability = none.getMethodAvailability();
		boolean lockedBox = false;
		for (Map.Entry<TeleportMethod, MethodAvailability> entry : availability.entrySet())
		{
			String label = entry.getKey().label();
			boolean mount = label.startsWith("Xeric's talisman:") || label.startsWith("Amulet of glory:")
				|| label.startsWith("Digsite pendant:") || label.startsWith("Mythical cape:");
			if (entry.getKey().getType() == TransportType.TELEPORTATION_BOX && !mount
				&& entry.getValue() == MethodAvailability.LOCKED)
			{
				lockedBox = true;
				assertEquals("Not built at your jewellery box tier (House section)",
					none.getMethodAvailabilityDetail().get(entry.getKey()));
			}
		}
		assertTrue("with no box built its destinations stay listed, locked", lockedBox);
	}

	@Test
	public void travelOptionOffLocksItsMethodsInsteadOfRemovingThem()
	{
		TypeOverrides.off(TransportType.CHARTER_SHIP);
		// The charter network switched off by override: listed, locked, named.
		PathfinderConfig off = planning();
		TeleportMethod charter = first(off.getMethodAvailability(), TransportType.CHARTER_SHIP, null);
		assertTrue("a charter method is still listed", charter != null);
		assertEquals(MethodAvailability.LOCKED, off.getMethodAvailability().get(charter));
		assertEquals("Charter ships are off (Travel options)",
			off.getMethodAvailabilityDetail().get(charter));
		int total = off.getMethodCatalog().size();

		TypeOverrides.clear();
		PathfinderConfig on = planning();
		assertEquals("the catalog is the same size either way", total, on.getMethodCatalog().size());
		assertTrue("with the toggle on the charter is no longer locked",
			on.getMethodAvailability().get(charter) != MethodAvailability.LOCKED);
	}

	@Test
	public void seasonalContentIsTheOneException()
	{
		when(config.useSeasonalTransports()).thenReturn(false);
		assertFalse("seasonal rows must NOT be listed off a seasonal world",
			planning().getMethodCatalog().stream().anyMatch(m -> m.getType() == TransportType.SEASONAL_TRANSPORTS));
	}
}

package gps.pathfinder;

import gps.WorldPointUtil;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import org.junit.Assume;
import org.junit.Test;

/**
 * Dev probe (-DcollisionDiff.run=true): quantifies what a collision-map change did to
 * PLAYER-REACHABLE space, not just raw edges. Loads two zips (-DcollisionDiff.oldZip /
 * -DcollisionDiff.newZip), measures load time and retained heap, then flood-fills each with
 * the real 8-direction canStep from Lumbridge plus every transport endpoint, and diffs the
 * reachable sets both ways: newly reachable tiles (possible void leaks) and newly
 * UNREACHABLE tiles (broken paths), grouped by region.
 */
public class CollisionDiffProbeTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);

	@Test
	public void diff() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("collisionDiff.run"));
		Path oldZip = Paths.get(System.getProperty("collisionDiff.oldZip"));
		Path newZip = Paths.get(System.getProperty("collisionDiff.newZip"));

		List<Integer> seeds = transportSeeds();
		seeds.add(LUMBRIDGE);
		System.out.println("seeds: " + seeds.size() + " (transport endpoints + Lumbridge)");

		Result oldResult = measure("old", oldZip, seeds);
		Result newResult = measure("new", newZip, seeds);

		BitSet gained = (BitSet) newResult.reachable.clone();
		gained.andNot(oldResult.reachable);
		BitSet lost = (BitSet) oldResult.reachable.clone();
		lost.andNot(newResult.reachable);

		StringBuilder report = new StringBuilder();
		report.append(String.format("old: load %dms, retained %.1f MB, flood %dms, reachable %,d%n",
			oldResult.loadMs, oldResult.retainedMb, oldResult.floodMs, oldResult.reachable.cardinality()));
		report.append(String.format("new: load %dms, retained %.1f MB, flood %dms, reachable %,d%n",
			newResult.loadMs, newResult.retainedMb, newResult.floodMs, newResult.reachable.cardinality()));
		report.append(String.format("newly reachable: %,d   newly UNREACHABLE: %,d%n%n",
			gained.cardinality(), lost.cardinality()));
		bandTotals(report, "gained", gained);
		summarize(report, "NEWLY REACHABLE (leak candidates)", gained);
		summarize(report, "NEWLY UNREACHABLE (broken paths)", lost);
		report.append("exact newly-unreachable tiles:\n");
		for (int i = lost.nextSetBit(0); i >= 0; i = lost.nextSetBit(i + 1))
		{
			report.append("  ").append(i & 0x3FFF).append(',')
				.append((i >> 14) & 0x3FFF).append(',').append(i >>> 28).append('\n');
		}

		Files.write(Paths.get("build/collision-diff-report.txt"),
			report.toString().getBytes(StandardCharsets.UTF_8));
		System.out.println(report);
	}

	private static final class Result
	{
		long loadMs;
		double retainedMb;
		long floodMs;
		BitSet reachable;
	}

	private Result measure(String label, Path zip, List<Integer> seeds) throws Exception
	{
		Result result = new Result();
		System.gc();
		Thread.sleep(200);
		long before = used();
		long t0 = System.nanoTime();
		CollisionMap map = loadMap(zip);
		result.loadMs = (System.nanoTime() - t0) / 1_000_000;
		System.gc();
		Thread.sleep(200);
		result.retainedMb = (used() - before) / 1048576.0;

		t0 = System.nanoTime();
		result.reachable = flood(map, seeds);
		result.floodMs = (System.nanoTime() - t0) / 1_000_000;
		System.out.println(label + " done: " + result.reachable.cardinality() + " reachable");
		return result;
	}

	private static long used()
	{
		Runtime r = Runtime.getRuntime();
		return r.totalMemory() - r.freeMemory();
	}

	/** Mirrors SplitFlagMap.fromResources but reads an arbitrary zip (extents set reflectively). */
	private static CollisionMap loadMap(Path zip) throws Exception
	{
		Map<Integer, byte[]> compressed = new HashMap<>();
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = 0;
		int maxY = 0;
		try (ZipInputStream in = new ZipInputStream(new FileInputStream(zip.toFile())))
		{
			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				int x = Integer.parseInt(n[0]);
				int y = Integer.parseInt(n[1]);
				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);
				compressed.put(SplitFlagMap.packPosition(x, y), gps.Util.readAllBytes(in));
			}
		}
		Constructor<?> extentCtor = SplitFlagMap.RegionExtent.class.getDeclaredConstructors()[0];
		extentCtor.setAccessible(true);
		Object extent = extentCtor.newInstance(minX, minY, maxX, maxY);
		Field field = SplitFlagMap.class.getDeclaredField("regionExtents");
		field.setAccessible(true);
		field.set(null, extent);
		return new CollisionMap(new SplitFlagMap(compressed));
	}

	private static BitSet flood(CollisionMap map, List<Integer> seeds)
	{
		BitSet visited = new BitSet(1 << 30);
		int[] queue = new int[1 << 22];
		int head = 0;
		int tail = 0;
		for (int seed : seeds)
		{
			int x = WorldPointUtil.unpackWorldX(seed);
			int y = WorldPointUtil.unpackWorldY(seed);
			int plane = WorldPointUtil.unpackWorldPlane(seed);
			if (map.isBlocked(x, y, plane))
			{
				continue;
			}
			int index = index(x, y, plane);
			if (!visited.get(index))
			{
				visited.set(index);
				queue[tail++] = seed;
			}
		}
		while (head != tail)
		{
			int at = queue[head++];
			if (head == queue.length)
			{
				head = 0;
			}
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int nx = x + dx;
					int ny = y + dy;
					if (nx < 1024 || nx > 4200 || ny < 2400 || ny > 12800)
					{
						continue;
					}
					int neighborIndex = index(nx, ny, plane);
					if (visited.get(neighborIndex))
					{
						continue;
					}
					int neighbor = WorldPointUtil.packWorldPoint(nx, ny, plane);
					if (!map.canStep(at, neighbor))
					{
						continue;
					}
					visited.set(neighborIndex);
					queue[tail++] = neighbor;
					if (tail == queue.length)
					{
						tail = 0;
					}
					if (tail == head)
					{
						throw new IllegalStateException("flood queue overflow");
					}
				}
			}
		}
		return visited;
	}

	private static int index(int x, int y, int plane)
	{
		return (plane << 28) | (y << 14) | x;
	}

	private static void bandTotals(StringBuilder report, String label, BitSet tiles)
	{
		int surface = 0;
		int under = 0;
		int instance = 0;
		for (int i = tiles.nextSetBit(0); i >= 0; i = tiles.nextSetBit(i + 1))
		{
			int y = (i >> 14) & 0x3FFF;
			if (y <= 4160)
			{
				surface++;
			}
			else if (y >= 8900)
			{
				under++;
			}
			else
			{
				instance++;
			}
		}
		report.append(label).append(" by band: surface=").append(surface)
			.append(" underground=").append(under).append(" instance-band=").append(instance)
			.append('\n');
	}

	private static void summarize(StringBuilder report, String title, BitSet tiles)
	{
		Map<Long, Integer> byRegion = new HashMap<>();
		for (int i = tiles.nextSetBit(0); i >= 0; i = tiles.nextSetBit(i + 1))
		{
			int x = i & 0x3FFF;
			int y = (i >> 14) & 0x3FFF;
			byRegion.merge(((long) (x / 64) << 20) | (y / 64), 1, Integer::sum);
		}
		List<Map.Entry<Long, Integer>> top = new ArrayList<>(byRegion.entrySet());
		top.sort((a, b) -> b.getValue() - a.getValue());
		report.append("=== ").append(title).append(": ").append(tiles.cardinality())
			.append(" tiles in ").append(byRegion.size()).append(" regions ===\n");
		for (int i = 0; i < Math.min(25, top.size()); i++)
		{
			int rx = (int) (top.get(i).getKey() >> 20);
			int ry = (int) (top.get(i).getKey() & 0xFFFFF);
			report.append(String.format("  %6d tiles  region %d_%d  world (%d,%d)%s%n",
				top.get(i).getValue(), rx, ry, rx * 64, ry * 64,
				ry * 64 >= 8900 ? "  [underground]" : (ry * 64 > 4160 ? "  [instance band]" : "")));
		}
	}

	private static List<Integer> transportSeeds() throws IOException
	{
		List<Integer> seeds = new ArrayList<>();
		File dir = new File("src/main/resources/transports");
		File[] files = dir.listFiles((d, name) -> name.endsWith(".tsv"));
		if (files == null)
		{
			return seeds;
		}
		for (File file : files)
		{
			for (String line : Files.readAllLines(file.toPath(), StandardCharsets.UTF_8))
			{
				if (line.startsWith("#") || line.isEmpty())
				{
					continue;
				}
				String[] cols = line.split("\t");
				for (int c = 0; c < Math.min(2, cols.length); c++)
				{
					String[] parts = cols[c].trim().split(" ");
					if (parts.length == 3)
					{
						try
						{
							seeds.add(WorldPointUtil.packWorldPoint(Integer.parseInt(parts[0]),
								Integer.parseInt(parts[1]), Integer.parseInt(parts[2])));
						}
						catch (NumberFormatException ignored)
						{
							// header or malformed row — not a tile
						}
					}
				}
			}
		}
		return seeds;
	}
}

package gps.pathfinder;

import static org.junit.Assert.assertEquals;
import org.junit.Test;
import gps.WorldPointUtil;

/**
 * Covers the time-normalized cost model: one cost unit = one run-tile = half a game tick (0.3s),
 * transport travel time converts at 2 units per tick, and every edge is clamped at free so a
 * negative configured weight can make a method free but never pay the route back (Dijkstra needs
 * non-negative edges).
 */
public class CostModelTest
{
	private static final int A = WorldPointUtil.packWorldPoint(3200, 3200, 0);
	private static final int B = WorldPointUtil.packWorldPoint(3201, 3200, 0);
	private static final int C = WorldPointUtil.packWorldPoint(3250, 3250, 0);

	@Test
	public void transportTravelTimeConvertsAtTwoUnitsPerTick()
	{
		assertEquals("A game tick covers 2 run-tiles", 2, CostUnits.UNITS_PER_TICK);
		assertEquals(10, CostUnits.fromTicks(5));
		assertEquals(0, CostUnits.fromTicks(0));
		// The unit really is real time: units * seconds-per-unit == ticks * 0.6s.
		assertEquals(5 * 0.6, CostUnits.fromTicks(5) * CostUnits.SECONDS_PER_UNIT, 1e-9);
	}

	@Test
	public void walkingEdgeCostsItsTileDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int step = graph.createTile(B, start, false, 0);
		assertEquals("One walked tile = one unit", 1, graph.cost(step));
	}

	@Test
	public void transportEdgeChargesTravelTimePlusWeight()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int viaTransport = graph.createTransport(C, start, CostUnits.fromTicks(5), 7, false);
		assertEquals("5 ticks of travel (10 units) + weight 7", 17, graph.cost(viaTransport));
	}

	@Test
	public void negativeWeightClampsTheTransportEdgeAtFree()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int walked = graph.createTile(B, start, false, 0); // cost 1
		// Travel 3 ticks (6 units) with a -20 favor weight: the edge is free, not -14 — the route
		// must never get cheaper by using a favored method (no negative edges).
		int viaTransport = graph.createTransport(C, walked, CostUnits.fromTicks(3), -20, false);
		assertEquals("The favored transport is free but never pays back", 1, graph.cost(viaTransport));
	}

	@Test
	public void negativeExtraCostClampsWalkAndAbstractEdgesAtFree()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int walked = graph.createTile(B, start, false, -5);
		assertEquals("A negative surcharge can't make walking pay back", 0, graph.cost(walked));
		int abstractNode = graph.createAbstract(AbstractNodeKind.fromWildernessLevel(0), walked, false, -7);
		assertEquals("A negative surcharge can't make the abstract hop pay back", 0, graph.cost(abstractNode));
	}
}

