package gps.pathfinder;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.PrimitiveIntHashMap;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * Invariants of the target-rooted distance field: targets are zero, values lower-bound real
 * search costs (admissibility — the property the A* heuristic's exactness rests on), and
 * reverse-unreachable places stay unreached.
 */
@RunWith(MockitoJUnitRunner.class)
public class DistanceFieldTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int ENTRANA = WorldPointUtil.packWorldPoint(2830, 3335, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig walkOnlyConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		planning.rebuildAvailabilityWithExclusions(planning.getMethodCatalog());
		return planning;
	}

	@Test
	public void fieldLowerBoundsTheRealWalkCostAndIsZeroAtTargets()
	{
		PathfinderConfig config = walkOnlyConfig();
		DistanceField field = DistanceField.build(config, Set.of(VARROCK));

		assertEquals("A target tile must be at distance zero", 0, field.distance(VARROCK));

		Pathfinder walk = new Pathfinder(config, LUMBRIDGE, Set.of(VARROCK), Integer.MAX_VALUE, null);
		walk.run();
		int walkCost = walk.getResult().getTotalCost();
		int fieldAtStart = field.distance(LUMBRIDGE);
		assertTrue("Field must be reached at the start tile", fieldAtStart != DistanceField.UNREACHED);
		assertTrue("Field must lower-bound the real walk cost (" + fieldAtStart + " vs " + walkCost + ")",
			fieldAtStart <= walkCost);
		assertTrue("Field must be a meaningful distance, not zero", fieldAtStart > 100);

		// Admissibility along the actual route: at every step, the field may never exceed the
		// cost still ahead of that step (this is exactly the property A* exactness rests on).
		List<PathStep> path = walk.getResult().getPathSteps();
		for (int i = 0; i < path.size(); i++)
		{
			int remaining = walkCost - (i == 0 ? 0 : pathCostUpTo(path, i));
			int h = field.distance(path.get(i).getPackedPosition());
			assertTrue("Field overestimates at step " + i + " (" + h + " > " + remaining + ")",
				h == DistanceField.UNREACHED || h <= remaining);
		}
	}

	/** Walking cost accumulated up to step index (walk-only paths move 1 tile per step). */
	private static int pathCostUpTo(List<PathStep> path, int index)
	{
		int cost = 0;
		for (int i = 1; i <= index; i++)
		{
			cost += Math.max(1, WorldPointUtil.distanceBetween(
				path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition()));
		}
		return cost;
	}

	@Test
	public void reverseUnreachableIslandStaysUnreached()
	{
		// Entrana is boat-only; with every method excluded nothing walks there, so the island must
		// not be flooded from a mainland target — its heuristic falls back to the floor.
		DistanceField field = DistanceField.build(walkOnlyConfig(), Set.of(VARROCK));
		assertEquals("The island must be reverse-unreachable",
			DistanceField.UNREACHED, field.distance(ENTRANA));
	}

	/**
	 * The reverse index must fold every (destination, origin) pair to a single min-cost entry — a
	 * transport not gated on banking is present in both bank-state availability maps, and distinct
	 * methods can share an origin and landing, so the raw data holds duplicate/redundant edges the
	 * index is expected to collapse. Verified by independently reducing the raw availability the same
	 * way and asserting the index matches exactly.
	 */
	@Test
	public void reverseIndexKeepsOneMinCostEntryPerOrigin()
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		Map<Integer, Map<Integer, Integer>> expected = new HashMap<>();
		for (boolean bankVisited : new boolean[]{false, true})
		{
			PrimitiveIntHashMap<Transport[]> transports = cfg.getTransportsPacked(bankVisited);
			for (int origin : transports.keys())
			{
				Transport[] set = transports.get(origin);
				if (set == null)
				{
					continue;
				}
				for (Transport t : set)
				{
					if (t.getDestination() == WorldPointUtil.UNDEFINED
						|| t.getOrigin() == WorldPointUtil.UNDEFINED)
					{
						continue;
					}
					int cost = Math.max(0, CostUnits.fromTicks(t.getDuration())
						+ cfg.getAdditionalTransportCost(t));
					expected.computeIfAbsent(t.getDestination(), k -> new HashMap<>())
						.merge(t.getOrigin(), cost, Math::min);
				}
			}
		}

		PrimitiveIntHashMap<Map<Integer, Integer>> index = DistanceField.buildReverseTransportIndex(cfg);
		assertFalse("The transport data must produce some reverse edges for this test to mean anything",
			index.size() == 0);
		int[] landings = index.keys();
		assertEquals("Every landing (and only those) must be indexed", expected.size(), landings.length);
		for (int landing : landings)
		{
			// A Map<origin, cost> can't hold a duplicate origin, and each value must be the minimum
			// cost across both bank states — exactly the reduction computed above.
			assertEquals("One min-cost entry per origin at landing " + landing,
				expected.get(landing), index.get(landing));
		}
	}

	@Test
	public void multiSourceFieldTakesTheNearestTarget()
	{
		PathfinderConfig config = walkOnlyConfig();
		DistanceField single = DistanceField.build(config, Set.of(VARROCK));
		DistanceField multi = DistanceField.build(config, Set.of(VARROCK, LUMBRIDGE));
		assertEquals("A tile that IS a target must be zero in the multi-source field",
			0, multi.distance(LUMBRIDGE));
		assertTrue("Multi-source distances can only shrink",
			multi.distance(WorldPointUtil.packWorldPoint(3250, 3300, 0))
				<= single.distance(WorldPointUtil.packWorldPoint(3250, 3300, 0)));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Multi-floor stairs with Top-/Bottom-floor menu options jump past the intermediate floors in one
 * click. The data prices a jump at floors-1 ticks (the upstream Lighthouse convention), so the
 * router must strictly prefer it over chaining the per-floor climbs — one step in the directions
 * instead of three.
 */
@RunWith(MockitoJUnitRunner.class)
public class FloorJumpTest
{
	// The Grand Tree ladder column at (2466, 3494): planes 0..3, glider level on top.
	private static final int GRAND_TREE_BASE = WorldPointUtil.packWorldPoint(2466, 3494, 0);
	private static final int GRAND_TREE_TOP = WorldPointUtil.packWorldPoint(2466, 3494, 3);
	// Lumbridge Castle north staircase: ground floor to the bank level.
	private static final int LUMBRIDGE_BASE = WorldPointUtil.packWorldPoint(3205, 3228, 0);
	private static final int LUMBRIDGE_TOP = WorldPointUtil.packWorldPoint(3206, 3229, 2);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	@Test
	public void grandTreeTopFloorJumpBeatsChainedClimbs()
	{
		Pathfinder pathfinder = new Pathfinder(everythingConfig(), GRAND_TREE_BASE, Set.of(GRAND_TREE_TOP));
		pathfinder.run();
		assertTrue("route should reach the glider level", pathfinder.getResult().isReached());
		// Jump: 2 ticks = 4 cost units. The chained climbs cost at least 3 ticks (3 x 1-tick floor).
		assertEquals("Top-Floor jump (2 ticks) should be the optimal route",
			gps.pathfinder.CostUnits.fromTicks(2), pathfinder.getResult().getTotalCost());
		// One edge: base -> top, no intermediate-floor tiles on the path.
		assertEquals(2, pathfinder.getResult().getPathSteps().size());
	}

	@Test
	public void grandTreeBottomFloorJumpFromTheGliderLevel()
	{
		Pathfinder pathfinder = new Pathfinder(everythingConfig(), GRAND_TREE_TOP, Set.of(GRAND_TREE_BASE));
		pathfinder.run();
		assertTrue(pathfinder.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(2), pathfinder.getResult().getTotalCost());
		assertEquals(2, pathfinder.getResult().getPathSteps().size());
	}

	@Test
	public void lumbridgeCastleTopFloorReachesTheBankLevelInOneStep()
	{
		Pathfinder pathfinder = new Pathfinder(everythingConfig(), LUMBRIDGE_BASE, Set.of(LUMBRIDGE_TOP));
		pathfinder.run();
		assertTrue(pathfinder.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(1), pathfinder.getResult().getTotalCost());
		assertEquals(2, pathfinder.getResult().getPathSteps().size());
	}

	@Test
	public void fairytaleHideoutTowerJumpsAndMidFloorBothWork()
	{
		// Cache-derived rows (the Lighthouse's identical twin staircase): ground -> top in one
		// 1-tick step, and the middle floor stays reachable via the per-floor rows.
		int base = WorldPointUtil.packWorldPoint(2444, 4600, 0);
		int top = WorldPointUtil.packWorldPoint(2441, 4601, 2);
		int mid = WorldPointUtil.packWorldPoint(2441, 4601, 1);
		Pathfinder jump = new Pathfinder(everythingConfig(), base, Set.of(top));
		jump.run();
		assertTrue(jump.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(1), jump.getResult().getTotalCost());
		assertEquals(2, jump.getResult().getPathSteps().size());
		Pathfinder toMid = new Pathfinder(everythingConfig(), base, Set.of(mid));
		toMid.run();
		assertTrue("middle floor must stay reachable via per-floor rows", toMid.getResult().isReached());
	}

	@Test
	public void stampedVarlamoreStairsRouteAtUnvisitedBuildings()
	{
		// The first building has since been field-captured (origin one diagonal from the old
		// stamped guess, which the derived-row dedupe removed): the captured row carries the
		// climb, plus one walked tile to its standing spot.
		Pathfinder up = new Pathfinder(everythingConfig(),
			WorldPointUtil.packWorldPoint(1681, 3771, 0),
			Set.of(WorldPointUtil.packWorldPoint(1688, 3771, 1)));
		up.run();
		assertTrue(up.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(2) + 1, up.getResult().getTotalCost());
		// The second building is still STAMP-ONLY (scripts/stamp_stairs.py from a field-captured
		// exemplar; never visited) — the pure (id, orientation) stamp must carry the whole climb.
		Pathfinder stamped = new Pathfinder(everythingConfig(),
			WorldPointUtil.packWorldPoint(1695, 3795, 0),
			Set.of(WorldPointUtil.packWorldPoint(1688, 3794, 1)));
		stamped.run();
		assertTrue(stamped.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(2), stamped.getResult().getTotalCost());
	}

	@Test
	public void aldarinTowerJumpsAndMidFloorBothWork()
	{
		int base = WorldPointUtil.packWorldPoint(1649, 3091, 0);
		int top = WorldPointUtil.packWorldPoint(1649, 3091, 2);
		int mid = WorldPointUtil.packWorldPoint(1649, 3091, 1);
		Pathfinder jump = new Pathfinder(everythingConfig(), base, Set.of(top));
		jump.run();
		assertTrue(jump.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(1), jump.getResult().getTotalCost());
		assertEquals(2, jump.getResult().getPathSteps().size());
		Pathfinder down = new Pathfinder(everythingConfig(), top, Set.of(base));
		down.run();
		assertTrue(down.getResult().isReached());
		assertEquals(gps.pathfinder.CostUnits.fromTicks(1), down.getResult().getTotalCost());
		Pathfinder toMid = new Pathfinder(everythingConfig(), base, Set.of(mid));
		toMid.run();
		assertTrue(toMid.getResult().isReached());
	}
}

package gps.pathfinder;

import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.MethodAvailability;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.TeleportationItem;
import gps.WorldPointUtil;
import gps.transport.TransportType;

/**
 * Covers the teleport-method catalog and its per-method availability classification
 * ({@link PathfinderConfig#getMethodAvailability()}): the catalog must be the same full set in every
 * mode, and each method must carry the reason the player can(not) use it right now — independent of
 * the mode's possession/unlock bypasses.
 */
@RunWith(MockitoJUnitRunner.class)
public class MethodAvailabilityCatalogTest
{
	private static final int COWBELL_DESTINATION = WorldPointUtil.packWorldPoint(3259, 3277, 0);
	private static final int COWBELL_AMULET = 33104;

	@Mock
	Client client;
	@Mock
	ItemContainer inventory;
	@Mock
	ItemContainer bank;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		// Classification must be independent of the (hidden) teleportation-item setting.
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		// The classifier now locks switched-off travel options first; these tests exercise
		// the per-transport gates, so the types they touch are ON.
	}

	/**
	 * An Owned/Inventory planning copy, refreshed so the catalog is built.
	 */
	private PathfinderConfig refreshedPlanningCopy(PathfinderConfig base)
	{
		PathfinderConfig planning = base.copyForPlanning();
		planning.setPlanningMode(false);
		planning.setBypassItemPossession(false);
		planning.setConsiderBank(false);
		planning.refresh();
		return planning;
	}

	private static TeleportMethod cowbellMethod(Map<TeleportMethod, MethodAvailability> catalog)
	{
		return catalog.keySet().stream()
			.filter(m -> m.getType() == TransportType.TELEPORTATION_ITEM && m.getDestination() == COWBELL_DESTINATION)
			.findFirst()
			.orElseThrow(() -> new AssertionError("Cowbell amulet method missing from the catalog"));
	}

	@Test
	public void itemInInventoryClassifiesAvailable()
	{
		doReturn(new Item[]{new Item(COWBELL_AMULET, 1)}).when(inventory).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);

		Map<TeleportMethod, MethodAvailability> catalog =
			refreshedPlanningCopy(new TestPathfinderConfig(client, config)).getMethodAvailability();

		assertEquals(MethodAvailability.AVAILABLE, catalog.get(cowbellMethod(catalog)));
	}

	@Test
	public void itemOnlyInBankClassifiesInBank()
	{
		// Bank contents known only via the snapshot captured while the bank was open — the classifier
		// must consult it in EVERY mode (here Owned/Inventory), not just the bank mode.
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.setBankSnapshot(new Item[]{new Item(COWBELL_AMULET, 1)});

		Map<TeleportMethod, MethodAvailability> catalog =
			refreshedPlanningCopy(base).getMethodAvailability();

		assertEquals(MethodAvailability.IN_BANK, catalog.get(cowbellMethod(catalog)));
	}

	@Test
	public void itemNowhereClassifiesMissingItem()
	{
		Map<TeleportMethod, MethodAvailability> catalog =
			refreshedPlanningCopy(new TestPathfinderConfig(client, config)).getMethodAvailability();

		assertEquals(MethodAvailability.MISSING_ITEM, catalog.get(cowbellMethod(catalog)));
	}

	@Test
	public void lowSkillLevelClassifiesMissingLevel()
	{
		// Magic level 3: Varrock Teleport (25 Magic) is level-gated before any item check.
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(3);

		Map<TeleportMethod, MethodAvailability> catalog =
			refreshedPlanningCopy(new TestPathfinderConfig(client, config)).getMethodAvailability();

		TeleportMethod varrockTeleport = catalog.keySet().stream()
			.filter(m -> m.getType() == TransportType.TELEPORTATION_SPELL
				&& m.getDisplayInfo() != null && m.getDisplayInfo().startsWith("Varrock Teleport"))
			.findFirst()
			.orElseThrow(() -> new AssertionError("Varrock Teleport method missing from the catalog"));
		assertEquals(MethodAvailability.MISSING_LEVEL, catalog.get(varrockTeleport));
	}

	@Test
	public void fairyRingsClassifyMissingQuestWithoutQuestProgress()
	{
		// The fairy-ring network is gated on Fairytale II progress (varbit, unstubbed = 0). The type-level
		// classifier must report MISSING_QUEST for every fairy-ring method. The house ring (D I Q)
		// is also a structural question — house and its fairy ring on — else it locks first.
		when(config.usePoh()).thenReturn(true);
		when(config.usePohFairyRing()).thenReturn(true);
		Map<TeleportMethod, MethodAvailability> catalog =
			refreshedPlanningCopy(new TestPathfinderConfig(client, config)).getMethodAvailability();

		boolean sawFairyRing = false;
		for (Map.Entry<TeleportMethod, MethodAvailability> entry : catalog.entrySet())
		{
			if (entry.getKey().getType() == TransportType.FAIRY_RING)
			{
				sawFairyRing = true;
				assertEquals("Fairy ring " + entry.getKey().label(),
					MethodAvailability.MISSING_QUEST, entry.getValue());
			}
		}
		assertTrue("Catalog should contain fairy-ring methods", sawFairyRing);
	}

	@Test
	public void catalogKeySetIsIdenticalAcrossModes()
	{
		// The catalog is the full method universe in every mode; only the availability markers differ.
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(false);
		planning.setBypassItemPossession(false);
		planning.setConsiderBank(false);
		planning.refresh();
		Set<TeleportMethod> ownedCatalog = planning.getMethodCatalog();

		planning.setPlanningMode(true);
		planning.setBypassItemPossession(true);
		planning.refresh();
		Set<TeleportMethod> everythingCatalog = planning.getMethodCatalog();

		assertFalse("Catalog should not be empty", ownedCatalog.isEmpty());
		assertEquals("Owned and Everything modes must expose the same catalog",
			everythingCatalog, ownedCatalog);
	}

	@Test
	public void bestPrefersMoreAvailableStatus()
	{
		assertEquals(MethodAvailability.AVAILABLE, MethodAvailability.AVAILABLE.best(MethodAvailability.IN_BANK));
		assertEquals(MethodAvailability.AVAILABLE, MethodAvailability.MISSING_QUEST.best(MethodAvailability.AVAILABLE));
		assertEquals(MethodAvailability.IN_BANK, MethodAvailability.IN_BANK.best(MethodAvailability.MISSING_ITEM));
		assertEquals(MethodAvailability.LOCKED, MethodAvailability.LOCKED.best(null));
	}

	@Test
	public void seasonalTransportsHiddenUnlessEnabled()
	{
		// Seasonal (Leagues) methods are gated by the "Enable seasonal transports" toggle
		// (useSeasonalTransports). Off by default (the mock returns false), they must be absent
		// from the catalog entirely — not merely flagged; on, they appear like any other type.
		PathfinderConfig off = new TestPathfinderConfig(client, config).copyForPlanning();
		off.refresh();
		assertFalse("Catalog should not be empty", off.getMethodCatalog().isEmpty());
		assertFalse("Seasonal methods must be hidden while the toggle is off",
			off.getMethodCatalog().stream().anyMatch(m -> m.getType() == TransportType.SEASONAL_TRANSPORTS));

		when(config.useSeasonalTransports()).thenReturn(true);
		PathfinderConfig on = new TestPathfinderConfig(client, config).copyForPlanning();
		on.refresh();
		assertTrue("Seasonal methods must appear when the toggle is on",
			on.getMethodCatalog().stream().anyMatch(m -> m.getType() == TransportType.SEASONAL_TRANSPORTS));
	}
}

package gps.pathfinder;

import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;
import gps.MethodAvailability;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.transport.TransportType;

/**
 * The catalog's availability classification also records WHAT is missing, so the panel's lock
 * tooltip can say "Requires 40 Firemaking" or "Missing item: Willow logs" instead of a generic
 * category. The Varrock balloon flight is the probe: it carries a Firemaking level and a willow-log
 * requirement, and its unlock varbits are bypassed by the test config.
 */
public class MethodAvailabilityDetailTest
{
	private static final int WILLOW_LOGS = 1519;

	private PathfinderConfig planningConfig(int boostedLevel, boolean stubWillowName)
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(boostedLevel);
		if (stubWillowName)
		{
			ItemComposition willow = mock(ItemComposition.class);
			when(willow.getName()).thenReturn("Willow logs");
			when(client.getItemDefinition(WILLOW_LOGS)).thenReturn(willow);
		}
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		when(config.calculationCutoff()).thenReturn(30);
		// The classifier now locks switched-off travel options first; balloons are the subject here.
		lenient().when(config.useHotAirBalloons()).thenReturn(true);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static TeleportMethod varrockFlight(PathfinderConfig config)
	{
		for (TeleportMethod method : config.getMethodAvailability().keySet())
		{
			if (TransportType.HOT_AIR_BALLOON.equals(method.getType())
				&& "Varrock".equals(method.getDisplayInfo()))
			{
				return method;
			}
		}
		return null;
	}

	@Test
	public void missingLevelNamesTheSkillAndLevel()
	{
		PathfinderConfig config = planningConfig(1, false);
		TeleportMethod flight = varrockFlight(config);
		assertNotNull("the Varrock balloon flight must be in the catalog", flight);
		assertEquals(MethodAvailability.MISSING_LEVEL, config.getMethodAvailability().get(flight));
		assertEquals("Requires 40 Firemaking", config.getMethodAvailabilityDetail().get(flight));
	}

	@Test
	public void missingItemNamesTheItem()
	{
		PathfinderConfig config = planningConfig(99, true);
		TeleportMethod flight = varrockFlight(config);
		assertNotNull("the Varrock balloon flight must be in the catalog", flight);
		assertEquals(MethodAvailability.MISSING_ITEM, config.getMethodAvailability().get(flight));
		assertEquals("Missing item: Willow logs", config.getMethodAvailabilityDetail().get(flight));
	}

	@Test
	public void unnameableDetailsFallBackToNoEntry()
	{
		// Without an item definition source (the common test/mocked case), the status is still
		// classified but the detail map simply has no entry — the panel falls back to its generic
		// per-status wording.
		PathfinderConfig config = planningConfig(99, false);
		TeleportMethod flight = varrockFlight(config);
		assertNotNull(flight);
		assertEquals(MethodAvailability.MISSING_ITEM, config.getMethodAvailability().get(flight));
		Map<TeleportMethod, String> details = config.getMethodAvailabilityDetail();
		assertEquals(null, details.get(flight));
	}
}

package gps.pathfinder;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * The Auburn Valley Mountain Guide (npc 14529, Quetzacalli Gorge <-> Auburn Valley) must be
 * traversable: both endpoints walkable, the transport registered at each origin, and a route from
 * beside the gorge guide to Auburn Valley taking the guide edge. Guards the gate/data regressions
 * that hid it (an unverifiable exact-equality varbit requirement).
 */
@RunWith(MockitoJUnitRunner.class)
public class MountainGuideTest
{
	private static final int GORGE_GUIDE = WorldPointUtil.packWorldPoint(1486, 3232, 0);
	private static final int AUBURN_GUIDE = WorldPointUtil.packWorldPoint(1361, 3309, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	@Test
	public void guideRouteIsTraversableAndTaken()
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		assertEquals("guide transport must be registered at the gorge origin", 1,
			cfg.getTransportsPacked(false).getOrDefault(GORGE_GUIDE, TransportAvailability.EMPTY_TRANSPORTS).length);
		assertEquals("guide transport must be registered at the Auburn origin", 1,
			cfg.getTransportsPacked(false).getOrDefault(AUBURN_GUIDE, TransportAvailability.EMPTY_TRANSPORTS).length);

		Pathfinder pathfinder = new Pathfinder(cfg, WorldPointUtil.packWorldPoint(1490, 3230, 0), Set.of(AUBURN_GUIDE));
		pathfinder.run();
		assertTrue("route beside the gorge guide must reach Auburn Valley", pathfinder.getResult().isReached());
		List<PathStep> path = pathfinder.getResult().getPathSteps();
		boolean usedGuide = false;
		for (int i = 1; i < path.size(); i++)
		{
			if (path.get(i - 1).getPackedPosition() == GORGE_GUIDE && path.get(i).getPackedPosition() == AUBURN_GUIDE)
			{
				usedGuide = true;
			}
		}
		assertTrue("the route must take the mountain guide edge", usedGuide);
	}
}

package gps.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import gps.WorldPointUtil;

/**
 * Pins down the cost formulas and flag bookkeeping of the structure-of-arrays node store so a
 * regression in any of the three distinct cost rules (tile walk, transport, abstract) fails fast.
 * The expected values mirror the maths of the old {@code Node}/{@code TransportNode} classes.
 */
public class NodeGraphTest
{
	@Test
	public void startNodeHasZeroCostAndNoPrevious()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));

		assertEquals(0, graph.cost(start));
		assertEquals(NodeGraph.NO_NODE, graph.previous(start));
		assertTrue(graph.isTile(start));
		assertFalse(graph.isAbstract(start));
		assertFalse(graph.isTransport(start));
		assertFalse(graph.bankVisited(start));
	}

	@Test
	public void tileFromTileAddsWalkingDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3205, 3203, 0);
		int start = graph.createStart(a);
		int tile = graph.createTile(b, start, false, 0);

		assertEquals(WorldPointUtil.distanceBetween(a, b), graph.cost(tile));
		assertEquals(start, graph.previous(tile));
		assertTrue(graph.isTile(tile));
		// With no heuristic the queue-ordering key is EXACTLY the accumulated cost.
		assertEquals(graph.cost(tile), graph.orderCost(tile));
	}

	@Test
	public void tileFromAbstractAddsNoWalkingDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		int start = graph.createStart(a);
		int tileBeforeAbstract = graph.createTile(WorldPointUtil.packWorldPoint(3201, 3200, 0), start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tileBeforeAbstract, true, 0);
		int tileFromAbstract = graph.createTile(b, abstractNode, true, 0);

		// Reaching a tile from an abstract node adds no travel cost: it inherits the abstract cost.
		assertEquals(graph.cost(abstractNode), graph.cost(tileFromAbstract));
		assertTrue(graph.bankVisited(tileFromAbstract));
	}

	@Test
	public void tileEdgeAddsExtraCost()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3205, 3203, 0);
		int start = graph.createStart(a);
		// The bank-pickup surcharge is charged on the edge that first enters the banked state.
		int tile = graph.createTile(b, start, true, 50);

		assertEquals(WorldPointUtil.distanceBetween(a, b) + 50, graph.cost(tile));
		assertTrue(graph.bankVisited(tile));
	}

	@Test
	public void abstractNodeAddsExtraCost()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int tile = graph.createTile(WorldPointUtil.packWorldPoint(3210, 3200, 0), start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tile, true, 50);

		// A global teleport reached via a bank inherits the bank-pickup surcharge from the abstract node.
		assertEquals(graph.cost(tile) + 50, graph.cost(abstractNode));
		assertTrue(graph.bankVisited(abstractNode));
	}

	@Test
	public void abstractInheritsPreviousCostAndCarriesKind()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int tile = graph.createTile(WorldPointUtil.packWorldPoint(3210, 3200, 0), start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30, tile, false, 0);

		assertEquals(graph.cost(tile), graph.cost(abstractNode));
		assertTrue(graph.isAbstract(abstractNode));
		assertFalse(graph.isTile(abstractNode));
		assertEquals(AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30, graph.abstractKind(abstractNode));
		assertEquals(WorldPointUtil.UNDEFINED, graph.packedPosition(abstractNode));
	}

	@Test
	public void transportCostIsPreviousPlusTravelAndAdditionalWithNoDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int destination = WorldPointUtil.packWorldPoint(2800, 3400, 0);
		int start = graph.createStart(origin);
		int prev = graph.createTile(WorldPointUtil.packWorldPoint(3201, 3200, 0), start, false, 0);

		int travelTime = 6;
		int additionalCost = 50;
		int transport = graph.createTransport(destination, prev, travelTime, additionalCost, false);

		// No walking-distance term for transports, unlike a walked tile.
		assertEquals(graph.cost(prev) + travelTime + additionalCost, graph.cost(transport));
		// The queue-ordering key is the cost and nothing else (no heuristic attached here): an
		// ordering-only term would break the first-settle-is-optimal invariant.
		assertEquals(graph.cost(transport), graph.orderCost(transport));
		assertTrue(graph.isTransport(transport));
		assertTrue(graph.isTile(transport)); // transports are concrete tile destinations
	}

	@Test
	public void bankVisitedTransportKeepsTheFlagAndPureCostKey()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int transport = graph.createTransport(WorldPointUtil.packWorldPoint(2800, 3400, 0), start, 6, 0, true);

		assertTrue(graph.isTransport(transport));
		assertEquals(graph.cost(transport), graph.orderCost(transport));
		assertTrue(graph.bankVisited(transport));
	}

	@Test
	public void pathStepsSkipAbstractNodesInOrder()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3201, 3200, 0);
		int c = WorldPointUtil.packWorldPoint(2800, 3400, 0);
		int start = graph.createStart(a);
		int tile = graph.createTile(b, start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tile, false, 0);
		int teleportDest = graph.createTransport(c, abstractNode, 6, 0, false);

		var steps = graph.getPathSteps(teleportDest);
		assertEquals(3, steps.size()); // start, tile, teleportDest (abstract is skipped)
		assertEquals(a, steps.get(0).getPackedPosition());
		assertEquals(b, steps.get(1).getPackedPosition());
		assertEquals(c, steps.get(2).getPackedPosition());

		assertEquals(c, graph.getClosestTilePosition(teleportDest));
		assertEquals(b, graph.getClosestTilePosition(abstractNode));
	}

	@Test
	public void releaseMakesChainWalksReturnEmpty()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		graph.release();

		assertTrue(graph.getPathSteps(start).isEmpty());
		assertEquals(WorldPointUtil.UNDEFINED, graph.getClosestTilePosition(start));
	}
}

package gps.pathfinder;

import gps.Destinations;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * A blocked target on a mapped object's FOOTPRINT snaps to the object's transport origin —
 * the interactable side — not to whichever adjacent tile is walkable. Captured at the Troll
 * Stronghold south cave (gps-capture-20260725-183521): Quest Helper targeted the cave tiles,
 * the route ended one tile BEHIND the mouth, and the game walked the long way around.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class ObjectTargetSnapTest
{
	// A footprint tile of Cave Entrance 3759 (3x2 at 2892,3672; mapped origins at y 3671).
	private static final int CAVE_FOOTPRINT = WorldPointUtil.packWorldPoint(2893, 3673, 0);
	private static final int BEHIND_THE_CAVE = WorldPointUtil.packWorldPoint(2892, 3674, 0);
	private static final int CAVE_FRONT = WorldPointUtil.packWorldPoint(2893, 3671, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void footprintTargetSnapsToTheMappedEntranceSide()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();

		assertTrue("premise: the cave footprint tile is blocked",
			planning.getMap().isBlocked(2893, 3673, 0));
		assertTrue("premise: the cave's data rows make 2893,3671 a transport origin",
			planning.isTransportOrigin(CAVE_FRONT));

		Set<Integer> targets = Destinations.walkableTargets(
			planning.getMap(), CAVE_FOOTPRINT, planning::isTransportOrigin);
		assertTrue("the mapped entrance side must be targeted", targets.contains(CAVE_FRONT));
		assertFalse("the tile behind the mouth must not be", targets.contains(BEHIND_THE_CAVE));

		// Without origin data the old nearest-ring behaviour stands (no regression for
		// unmapped objects).
		Set<Integer> plain = Destinations.walkableTargets(planning.getMap(), CAVE_FOOTPRINT);
		assertTrue(plain.contains(BEHIND_THE_CAVE) || plain.contains(CAVE_FOOTPRINT));
	}
}

package gps.pathfinder;

import gps.ShortestPathConfig;
import gps.TeleportationItem;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
