import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N8: a parallel-search sibling (seed workers, the walk search) must see exactly the
 * refresh-derived state the chain's config sees, or the same query returns different routes
 * depending on which worker ran it ("consistent over fast"). The review found the hand-written
 * copy method missed fields as they were added. This audit compares every declared field of the
 * planning config against its sibling by content, and every field that is legitimately per-copy
 * must be listed here with its reason, so a new field fails the build until someone decides.
 */
@RunWith(MockitoJUnitRunner.class)
public class ParallelCopyFidelityTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	/** Fields that are per-copy by design, each with the reason it need not match the source. */
	private static final Set<String> PER_COPY = Set.of(
		// Identity and wiring.
		"client", "config", "planningSource",
		// Filled lazily by the copy's own refresh pass; the copy never refreshes.
		"questStates", "varbitValues", "varPlayerValues", "itemSnapshots", "refreshPassActive", "itemNames",
		// Per-thread collision map (the paged graph mutates it during a search).
		"map",
		// Copied by value in the copy constructor; its content is compared below.
		"transportTypeConfig"
	);

	@Test
	public void everyFieldIsCopiedOrDeclaredPerCopy() throws Exception
	{
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		lenient().when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		lenient().when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(true);
		planning.setBypassItemPossession(true);
		planning.refresh();
		PathfinderConfig sibling = planning.copyForParallelSearch();

		List<String> mismatches = new ArrayList<>();
		for (Field field : PathfinderConfig.class.getDeclaredFields())
		{
			if (Modifier.isStatic(field.getModifiers()) || PER_COPY.contains(field.getName()))
			{
				continue;
			}
			field.setAccessible(true);
			Object source = field.get(planning);
			Object copy = field.get(sibling);
			if (source != copy && !Objects.deepEquals(source, copy))
			{
				mismatches.add(field.getName() + " (source=" + brief(source) + ", copy=" + brief(copy) + ")");
			}
		}
		Field typeConfigField = PathfinderConfig.class.getDeclaredField("transportTypeConfig");
		typeConfigField.setAccessible(true);
		gps.transport.TransportTypeConfig sourceTypes = (gps.transport.TransportTypeConfig) typeConfigField.get(planning);
		gps.transport.TransportTypeConfig copyTypes = (gps.transport.TransportTypeConfig) typeConfigField.get(sibling);
		if (sourceTypes.getTeleportationItemSetting() != copyTypes.getTeleportationItemSetting())
		{
			mismatches.add("transportTypeConfig.teleportationItemSetting");
		}
		for (gps.transport.TransportType type : gps.transport.TransportType.values())
		{
			if (sourceTypes.isEnabled(type) != copyTypes.isEnabled(type)
				|| sourceTypes.isEnabledInConfig(type) != copyTypes.isEnabledInConfig(type)
				|| sourceTypes.getCost(type) != copyTypes.getCost(type))
			{
				mismatches.add("transportTypeConfig state for " + type);
			}
		}
		assertTrue("fields a parallel-search sibling does not share with its source; copy them in"
			+ " copyForParallelSearch or list them as per-copy with a reason:\n  " + String.join("\n  ", mismatches),
			mismatches.isEmpty());
	}

	private static String brief(Object value)
	{
		if (value == null)
		{
			return "null";
		}
		String text = value.toString();
		return text.length() > 60 ? text.substring(0, 57) + "..." : text;
	}
}

package gps.pathfinder;

import java.util.EnumSet;
import net.runelite.api.Client;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.leagues.LeagueModeState;
import gps.leagues.LeagueRegion;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class PathfinderConfigSeasonalTest
{
	private static final int VARROCK_WEST = WorldPointUtil.packWorldPoint(3186, 3438, 0);
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3225, 3220, 0);
	private static final int CIVITAS = WorldPointUtil.packWorldPoint(1781, 3100, 0);
	private static final int FORTIS_CIVITAS_WEST = WorldPointUtil.packWorldPoint(1646, 3112, 0);

	@Mock
	private Client client;
	@Mock
	private ShortestPathConfig config;

	private PathfinderConfig pathfinderConfig;

	@Before
	public void before()
	{
		pathfinderConfig = new TestPathfinderConfig(client, config);
	}

	@Test
	public void avoidBlockedRegionIsNoOpOffSeasonalWorlds()
	{
		LeagueModeState state = pathfinderConfig.getLeagueModeState();
		state.setForTest(false, EnumSet.noneOf(LeagueRegion.class));

		// Walking from Civitas towards Varrock would normally cross from Varlamore into Misthalin.
		// Off-seasonal we expect zero league filtering.
		assertFalse(pathfinderConfig.avoidBlockedRegion(CIVITAS, VARROCK_WEST, false));
		assertFalse(pathfinderConfig.avoidBlockedRegion(VARROCK_WEST, LUMBRIDGE, false));
	}

	@Test
	public void avoidBlockedRegionBlocksMisthalinEntryOnSeasonal()
	{
		LeagueModeState state = pathfinderConfig.getLeagueModeState();
		state.setForTest(true, EnumSet.of(LeagueRegion.KANDARIN));

		// Crossing FROM neutral/varlamore INTO Misthalin must be blocked.
		assertTrue(pathfinderConfig.avoidBlockedRegion(CIVITAS, VARROCK_WEST, false));
	}

	@Test
	public void avoidBlockedRegionPermitsMovementInsideMisthalin()
	{
		LeagueModeState state = pathfinderConfig.getLeagueModeState();
		state.setForTest(true, EnumSet.of(LeagueRegion.KANDARIN));

		// Both endpoints inside Misthalin must NOT be blocked, otherwise a player who
		// somehow lands inside the blocked region could not walk out.
		assertFalse(pathfinderConfig.avoidBlockedRegion(VARROCK_WEST, LUMBRIDGE, true));
	}

	@Test
	public void avoidBlockedRegionDoesNotInterfereWithVarlamoreInternalMoves()
	{
		LeagueModeState state = pathfinderConfig.getLeagueModeState();
		state.setForTest(true, EnumSet.noneOf(LeagueRegion.class));

		assertFalse(pathfinderConfig.avoidBlockedRegion(CIVITAS, FORTIS_CIVITAS_WEST, false));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import gps.TeleportationItem;
import gps.TestShortestPathConfig;
import gps.WorldPointUtil;

public class PathfinderResultTest
{
	private static PathfinderConfig configWithCutoff(int cutoffTicks)
	{
		Client client = mock(Client.class);
		TestShortestPathConfig config = new TestShortestPathConfig();
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getTotalLevel()).thenReturn(2277);
		config.setCalculationCutoffValue(cutoffTicks);
		config.setUseTeleportationItemsValue(TeleportationItem.ALL);

		PathfinderConfig pathfinderConfig = new TestPathfinderConfig(client, config);
		pathfinderConfig.refresh();
		return pathfinderConfig;
	}

	private static int point(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	@Test
	public void reachedTargetProducesReachedResult()
	{
		Pathfinder pathfinder = new Pathfinder(configWithCutoff(100), point(3200, 3200), Set.of(point(3201, 3200)));

		pathfinder.run();
		PathfinderResult result = pathfinder.getResult();

		assertTrue(result.isReached());
		assertEquals(PathTerminationReason.TARGET_REACHED, result.getTerminationReason());
	}

	@Test
	public void zeroCutoffProducesCutoffResult()
	{
		Pathfinder pathfinder = new Pathfinder(configWithCutoff(0), point(3200, 3200), Set.of(point(3300, 3300)));

		pathfinder.run();
		PathfinderResult result = pathfinder.getResult();

		assertEquals(PathTerminationReason.CUTOFF_REACHED, result.getTerminationReason());
	}
}

