/**
 * The house's mounted items are individual assumptions (they can't be scene-detected): each
 * mount has its own toggle under "Mounted items". An unticked mount stays IN the catalog —
 * nothing vanishes — but classifies LOCKED with a "not built" reason and drops out of routing,
 * exactly like any other unlock the player lacks.
 */
@RunWith(MockitoJUnitRunner.class)
public class PohMountSelectionTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(config.usePoh()).thenReturn(true);
		when(config.usePohMountedItems()).thenReturn(true);
		// Below Ornate, so the mounted glory is not folded into the box.
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.BASIC);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig planning(boolean glory, boolean xerics, boolean digsite, boolean mythical)
	{
		when(config.pohMountGlory()).thenReturn(glory);
		when(config.pohMountXerics()).thenReturn(xerics);
		when(config.pohMountDigsite()).thenReturn(digsite);
		when(config.pohMountMythical()).thenReturn(mythical);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static TeleportMethod mount(Map<TeleportMethod, MethodAvailability> availability, String mount)
	{
		for (TeleportMethod method : availability.keySet())
		{
			if (method.getType() == TransportType.TELEPORTATION_BOX && method.label().startsWith(mount + ":"))
			{
				return method;
			}
		}
		return null;
	}

	@Test
	public void untickedMountStaysListedButLocked()
	{
		PathfinderConfig all = planning(true, true, true, true);
		Map<TeleportMethod, MethodAvailability> availability = all.getMethodAvailability();
		for (String name : new String[]{"Amulet of glory", "Xeric's talisman", "Digsite pendant", "Mythical cape"})
		{
			TeleportMethod method = mount(availability, name);
			assertTrue(name + " mount in the catalog", method != null);
			assertEquals(name + " usable when ticked", MethodAvailability.AVAILABLE, availability.get(method));
		}

		PathfinderConfig noXerics = planning(true, false, true, true);
		availability = noXerics.getMethodAvailability();
		TeleportMethod xerics = mount(availability, "Xeric's talisman");
		assertTrue("unticked Xeric's must STAY in the catalog", xerics != null);
		assertEquals("…but locked", MethodAvailability.LOCKED, availability.get(xerics));
		assertEquals("…with the reason the lock tooltip shows",
			"Not built in your house (House section)", noXerics.getMethodAvailabilityDetail().get(xerics));
		assertEquals("the other mounts stay usable", MethodAvailability.AVAILABLE,
			availability.get(mount(availability, "Amulet of glory")));
	}

	@Test
	public void untickedMountDropsOutOfOwnedRouting()
	{
		PathfinderConfig noXerics = planning(true, false, true, true);
		noXerics.setPlanningMode(false);
		noXerics.setBypassItemPossession(false);
		noXerics.refresh();
		boolean xericsEdge = false;
		boolean gloryEdge = false;
		// The mounts sit on two house tiles (glory/cape at 1960,5750; Xeric's/digsite at
		// 1886,5760) — scan every origin rather than hard-code either.
		gps.PrimitiveIntHashMap<gps.transport.Transport[]> byOrigin = noXerics.getTransportsPacked(false);
		for (int origin : byOrigin.keys())
		{
			gps.transport.Transport[] transports = byOrigin.get(origin);
			for (gps.transport.Transport transport : transports == null ? new gps.transport.Transport[0] : transports)
			{
				String info = transport.getObjectInfo();
				if (info != null && transport.getType() == TransportType.TELEPORTATION_BOX)
				{
					xericsEdge |= info.contains("Xeric's Talisman");
					gloryEdge |= info.contains("Amulet of Glory");
				}
			}
		}
		assertFalse("an unbuilt mount must not be a routable edge", xericsEdge);
		assertTrue("a built mount still is", gloryEdge);
	}
}

package gps.pathfinder;

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Set;
import gps.PrimitiveIntList;
import gps.WorldPointUtil;
import gps.leagues.LeagueModeState;

/**
 * Textbook Dijkstra over the exact same edge expansion as {@link Pathfinder} — the optimality
 * ORACLE. Every node (tile, transport, abstract) goes through one min-heap keyed by pure
 * accumulated cost g; a state settles at its first dequeue and is never revisited; a target
 * counts only when POPPED (which, with non-negative edges, is the proof its cost is minimal).
 * No FIFO fast-path, no ordering-only cost terms, no heuristic — nothing that could trade
 * exactness for speed.
 * <p>
 * Used by the optimality tests and the benchmark's audit pass to catch any production search
 * returning a non-minimal cost. Deliberately simple and boxed — never run in the client hot path.
 */
public final class ReferenceDijkstra
{
	/** Safety valve: a bugged scenario must fail the audit, not hang it. */
	private static final long MAX_SETTLES = 20_000_000L;

	private ReferenceDijkstra()
	{
	}

	/** The oracle's verdict: whether a target was reached, the minimal cost, and its path. */
	public static final class Result
	{
		public final boolean reached;
		public final int cost;
		public final java.util.List<PathStep> path;

		Result(boolean reached, int cost, java.util.List<PathStep> path)
		{
			this.reached = reached;
			this.cost = cost;
			this.path = path;
		}
	}

	/**
	 * Runs the reference search on the config's CURRENT availability (callers refresh/rebuild
	 * exclusions first, exactly as they would for a production search).
	 */
	public static Result search(PathfinderConfig config, int start, Set<Integer> targets)
	{
		final CollisionMap map = config.getMap();
		final NodeGraph graph = new NodeGraph(1 << 14, null);
		final VisitedTiles settled = new VisitedTiles(map);
		// Ordering key: graph.cost only (node costs are write-once, so the comparator is stable).
		final PriorityQueue<Integer> heap = new PriorityQueue<>(Comparator.comparingInt(graph::cost));
		final boolean targetInWilderness = WildernessChecker.isInWilderness(targets);
		final boolean targetInBlockedRegion = anyInBlockedRegion(config.getLeagueModeState(), targets);
		int wildernessLevel = 31;

		heap.add(graph.createStart(start));
		long budget = MAX_SETTLES;
		while (!heap.isEmpty() && budget-- > 0)
		{
			final int node = heap.poll();
			// Settle-time dedup for EVERY node kind: duplicates stay in the heap (lazy deletion)
			// and are discarded here; the first dequeue of a state is its cheapest arrival.
			if (settled.get(node, graph))
			{
				continue;
			}
			settled.set(node, graph);

			final boolean nodeIsTile = graph.isTile(node);
			final int nodePacked = nodeIsTile ? graph.packedPosition(node) : WorldPointUtil.UNDEFINED;
			if (nodeIsTile)
			{
				wildernessLevel = updateWildernessLevel(wildernessLevel, nodePacked);
				if (targets.contains(nodePacked))
				{
					return new Result(true, graph.cost(node), graph.getPathSteps(node));
				}
			}

			final PrimitiveIntList neighbors =
				map.getNeighbors(node, settled, config, wildernessLevel, targetInWilderness, graph);
			final int count = neighbors.size();
			for (int i = 0; i < count; i++)
			{
				final int neighbor = neighbors.get(i);
				// Mirror Pathfinder.addNeighbors' tile-edge filters exactly.
				if (nodeIsTile && graph.isTile(neighbor))
				{
					final int neighborPacked = graph.packedPosition(neighbor);
					if (config.avoidWilderness(nodePacked, neighborPacked, targetInWilderness))
					{
						continue;
					}
					if (config.avoidBlockedRegion(nodePacked, neighborPacked, targetInBlockedRegion))
					{
						continue;
					}
				}
				heap.add(neighbor);
			}
		}
		return new Result(false, -1, java.util.List.of());
	}

	/** Mirrors {@link Pathfinder}'s wilderness-level narrowing on settled tiles. */
	private static int updateWildernessLevel(int wildernessLevel, int packedPosition)
	{
		if (wildernessLevel > 30 && !WildernessChecker.isInLevel30Wilderness(packedPosition))
		{
			wildernessLevel = 30;
		}
		if (wildernessLevel > 20 && !WildernessChecker.isInLevel20Wilderness(packedPosition))
		{
			wildernessLevel = 20;
		}
		if (wildernessLevel > 0 && !WildernessChecker.isInWilderness(packedPosition))
		{
			wildernessLevel = 0;
		}
		return wildernessLevel;
	}

	private static boolean anyInBlockedRegion(LeagueModeState league, Set<Integer> packed)
	{
		if (league == null || !league.isSeasonal() || packed == null || packed.isEmpty())
		{
			return false;
		}
		for (Integer point : packed)
		{
			if (league.isInBlockedRegion(point))
			{
				return true;
			}
		}
		return false;
	}
}

package gps.pathfinder;

import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;
import java.lang.management.ManagementFactory;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N2: the search hot loop must not allocate per node. The review found an Integer
 * boxed per settled tile (targets.contains), one per expanded tile for the door mask and one
 * for the bank-tile check, a clock read per node, an O(nodes x targets) post-pass, and a node
 * graph that copies itself a dozen times while growing to a couple of million nodes and is then
 * thrown away - hundreds of megabytes of garbage per generation, the likeliest source of GC
 * hitches on the client. This measures bytes allocated on the search thread per settled node.
 */
@RunWith(MockitoJUnitRunner.class)
public class SearchAllocationTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int ARDOUGNE = WorldPointUtil.packWorldPoint(2662, 3305, 0);
	/** Bytes per settled node the loop is allowed after the cleanup. */
	static final int BYTES_PER_NODE_BUDGET = 64;

	private PathfinderConfig walkConfig()
	{
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		PathfinderConfig pathConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		pathConfig.refresh();
		return pathConfig;
	}

	private static com.sun.management.ThreadMXBean threadBean()
	{
		java.lang.management.ThreadMXBean bean = ManagementFactory.getThreadMXBean();
		Assume.assumeTrue("needs the HotSpot thread allocation counter", bean instanceof com.sun.management.ThreadMXBean);
		com.sun.management.ThreadMXBean sun = (com.sun.management.ThreadMXBean) bean;
		Assume.assumeTrue(sun.isThreadAllocatedMemorySupported());
		sun.setThreadAllocatedMemoryEnabled(true);
		return sun;
	}

	private static long[] measure(PathfinderConfig pathConfig, int start, Set<Integer> targets)
	{
		com.sun.management.ThreadMXBean bean = threadBean();
		long thread = Thread.currentThread().getId();
		// Warm the JIT and the lazily loaded map regions on a first run, then measure a second.
		new Pathfinder(pathConfig, start, targets, Integer.MAX_VALUE, null).run();
		long before = bean.getThreadAllocatedBytes(thread);
		Pathfinder pathfinder = new Pathfinder(pathConfig, start, targets, Integer.MAX_VALUE, null);
		pathfinder.run();
		long bytes = bean.getThreadAllocatedBytes(thread) - before;
		int nodes = pathfinder.getResult().getNodesChecked();
		assertTrue("the search must settle enough nodes to measure: " + nodes + " (reached="
			+ pathfinder.getResult().isReached() + ", " + pathfinder.getResult().getTerminationReason()
			+ ", closest=" + WorldPointUtil.unpackWorldPoint(pathfinder.getResult().getClosestReachedPoint())
			+ ", astar=" + pathfinder.isAstar() + ", target=" + WorldPointUtil.unpackWorldPoint(pathfinder.getResult().getTarget())
			+ ", pathEnd=" + (pathfinder.getPath().isEmpty() ? "none" : WorldPointUtil.unpackWorldPoint(
				pathfinder.getPath().get(pathfinder.getPath().size() - 1).getPackedPosition()))
			+ ", steps=" + pathfinder.getPath().size() + ")", nodes > 100_000);
		return new long[]{bytes, nodes};
	}

	@Test
	public void blindWalkSearchAllocatesLittlePerNode()
	{
		long[] m = measure(walkConfig(), LUMBRIDGE, Set.of(ARDOUGNE));
		long perNode = m[0] / m[1];
		System.out.println("SEARCHALLOC single target: " + m[1] + " nodes, " + m[0] + " bytes, " + perNode + " B/node");
		assertTrue("a blind search allocated " + perNode + " bytes per settled node (budget "
			+ BYTES_PER_NODE_BUDGET + ")", perNode < BYTES_PER_NODE_BUDGET);
	}

	/** Many targets: the per-node target check and the closest-tile post-pass must not scale with them. */
	@Test
	public void manyTargetsDoNotMultiplyTheCost()
	{
		PathfinderConfig pathConfig = walkConfig();
		// Every target unreachable (tiles in unmapped ocean far west of the world), so the search
		// floods its whole component while the per-node target check and the closest-tile
		// post-pass run over 120 targets. A single reachable bank would end the search at
		// Lumbridge castle's after ~1,800 nodes; plane-3 copies of the banks still hit a roof.
		Set<Integer> banks = new HashSet<>();
		for (int i = 0; i < 120; i++)
		{
			banks.add(WorldPointUtil.packWorldPoint(1000 + i, 2000 + i, 0));
		}
		Set<Integer> farOnly = new HashSet<>();
		farOnly.add(WorldPointUtil.packWorldPoint(3253, 3180, 0)); // the Broken Raft deck: unreachable
		long[] one = measure(pathConfig, LUMBRIDGE, farOnly);
		long[] many = measure(pathConfig, LUMBRIDGE, banks);
		System.out.println("SEARCHALLOC unreachable, 1 target: " + one[1] + " nodes " + one[0] / one[1] + " B/node; "
			+ banks.size() + " targets: " + many[1] + " nodes " + many[0] / many[1] + " B/node");
		assertTrue("per-node allocation must not grow with the target count",
			many[0] / many[1] < BYTES_PER_NODE_BUDGET);
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * The search optimality contract, checked against {@link ReferenceDijkstra} (textbook Dijkstra
 * over the same edge expansion — the oracle): every production search, informed or not, must
 * return EXACTLY the oracle's minimal cost. This is what guarantees the panel's route 0 is the
 * true optimum regardless of the route count.
 * <p>
 * Battery notes: the Varlamore scenario reproduces a user capture where the primary search
 * returned a 177-cost route while a 101-cost route existed (surfaced only by the seed pass at a
 * higher route limit). The shared-destination scenario forces the quetzal whistle's differential
 * cost into play — with the differential in the ordering key only, the cheaper arrival loses the
 * settle race to a costlier competitor and is permanently discarded.
 */
@RunWith(MockitoJUnitRunner.class)
public class SearchOptimalityTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);
	private static final int GRAND_EXCHANGE = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	private static final int SHILO_VILLAGE = WorldPointUtil.packWorldPoint(2852, 2954, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3380, 0);
	private static final int DRAYNOR = WorldPointUtil.packWorldPoint(3093, 3245, 0);

	// The user capture (gps-capture-20260709-162344): Lumbridge courtyard to the Hunter Guild
	// entrance tiles in Varlamore.
	private static final int CAPTURE_START = WorldPointUtil.packWorldPoint(3219, 3219, 0);
	private static final Set<Integer> CAPTURE_TARGETS = Set.of(
		WorldPointUtil.packWorldPoint(1556, 3046, 0),
		WorldPointUtil.packWorldPoint(1555, 3045, 0),
		WorldPointUtil.packWorldPoint(1555, 3046, 0),
		WorldPointUtil.packWorldPoint(1554, 3046, 0));

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		// Every production search in this suite also self-checks its settle order (a decrease
		// means an inadmissible heuristic or a polluted ordering key).
		Pathfinder.validateSettleOrder = true;
	}

	@org.junit.After
	public void after()
	{
		Pathfinder.validateSettleOrder = false;
	}

	/** An Everything-mode planning copy (possession and unlocks bypassed), refreshed. */
	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	/**
	 * Runs the oracle plus both production searches (uninformed, and A* with the distance-field
	 * heuristic) and asserts every one returns the oracle's minimal cost.
	 */
	private static void assertOptimal(PathfinderConfig config, int start, Set<Integer> targets)
	{
		ReferenceDijkstra.Result oracle = ReferenceDijkstra.search(config, start, targets);

		Pathfinder uninformed = new Pathfinder(config, start, targets, Integer.MAX_VALUE, null);
		uninformed.run();

		DistanceField field = DistanceField.build(config, targets);
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(config, field);
		assertNotNull("field heuristic must build", heuristic);
		Pathfinder astar = new Pathfinder(config, start, targets, Integer.MAX_VALUE, heuristic);
		astar.run();

		assertEquals("uninformed reached must match the oracle",
			oracle.reached, uninformed.getResult().isReached());
		assertEquals("A* reached must match the oracle",
			oracle.reached, astar.getResult().isReached());
		if (oracle.reached)
		{
			assertEquals("uninformed search must return the minimal cost",
				oracle.cost, uninformed.getResult().getTotalCost());
			assertEquals("A* search must return the minimal cost",
				oracle.cost, astar.getResult().getTotalCost());
		}
	}

	@Test
	public void captureQueryLumbridgeToHunterGuildIsOptimal()
	{
		assertOptimal(everythingConfig(), CAPTURE_START, CAPTURE_TARGETS);
	}

	@Test
	public void lumbridgeToBarrowsIsOptimal()
	{
		assertOptimal(everythingConfig(), LUMBRIDGE, Set.of(BARROWS));
	}

	@Test
	public void grandExchangeToShiloIsOptimal()
	{
		assertOptimal(everythingConfig(), GRAND_EXCHANGE, Set.of(SHILO_VILLAGE));
	}

	@Test
	public void multiTargetIsOptimal()
	{
		assertOptimal(everythingConfig(), LUMBRIDGE, Set.of(VARROCK, FALADOR, DRAYNOR));
	}

	/**
	 * Shared-destination competition under a non-zero whistle differential: the quetzal whistle
	 * teleport and a quetzal flight land on the SAME tile. Starting at the flight's origin makes
	 * the flight arrival cheap-and-early while the differential inflates the whistle's queue
	 * position — the exact configuration where an ordering-only cost term lets a costlier arrival
	 * settle the destination first and the cheaper one be discarded.
	 */
	@Test
	public void whistleDifferentialSharedDestinationIsOptimal()
	{
		when(config.costQuetzalWhistle()).thenReturn(100);
		PathfinderConfig cfg = everythingConfig();

		// Derive a concrete flight from the loaded data instead of hardcoding coordinates.
		Transport flight = null;
		for (int origin : cfg.getTransportsPacked(false).keys())
		{
			for (Transport transport : cfg.getTransportsPacked(false).get(origin))
			{
				if (TransportType.QUETZAL.equals(transport.getType())
					&& transport.getOrigin() != WorldPointUtil.UNDEFINED
					&& transport.getDestination() != WorldPointUtil.UNDEFINED)
				{
					flight = transport;
					break;
				}
			}
			if (flight != null)
			{
				break;
			}
		}
		assertNotNull("a quetzal flight must exist in the transport data", flight);
		assertTrue("the whistle must be usable so the shared-destination race exists",
			hasWhistle(cfg));

		assertOptimal(cfg, flight.getOrigin(), Set.of(flight.getDestination()));
	}

	private static boolean hasWhistle(PathfinderConfig cfg)
	{
		for (Transport teleport : cfg.getUsableTeleports(false))
		{
			if (TransportType.QUETZAL_WHISTLE.equals(teleport.getType()))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Heuristic consistency sampler: h(a) &le; c(a,b) + h(b) over every edge kind the search can
	 * take from an occupiable tile — cardinal/diagonal walking in a box around the targets,
	 * origin-bound transports, and the global-teleport hub (whose h is the floor). Consistency is
	 * what makes the first settle optimal; a single violated edge is a route-burying bug.
	 */
	@Test
	public void heuristicIsConsistentAroundTheCaptureTargets()
	{
		PathfinderConfig cfg = everythingConfig();
		DistanceField field = DistanceField.build(cfg, CAPTURE_TARGETS);
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(cfg, field);
		assertNotNull(heuristic);
		CollisionMap map = cfg.getMap();

		// Walking edges in a box around the capture targets (the region the heuristic steers).
		int violations = 0;
		for (int x = 1555 - 220; x <= 1555 + 220; x++)
		{
			for (int y = 3046 - 220; y <= 3046 + 220; y++)
			{
				if (map.isBlocked(x, y, 0))
				{
					// Non-landing blocked tiles are never occupied by the search; landings are
					// covered by the transport and hub checks below.
					continue;
				}
				final int a = WorldPointUtil.packWorldPoint(x, y, 0);
				final int ha = heuristic.of(a);
				// Cardinals; diagonals are compositions of them with equal edge cost 1, so the
				// cardinal triangle inequalities imply the diagonal ones within 1 either way —
				// check them directly anyway via the packed diagonal neighbours.
				final int[][] steps = {
					{x - 1, y}, {x + 1, y}, {x, y - 1}, {x, y + 1},
					{x - 1, y - 1}, {x + 1, y - 1}, {x - 1, y + 1}, {x + 1, y + 1}};
				final boolean[] open = {
					map.w(x, y, 0), map.e(x, y, 0), map.s(x, y, 0), map.n(x, y, 0),
					map.s(x, y, 0) && map.w(x, y - 1, 0) && map.w(x, y, 0) && map.s(x - 1, y, 0),
					map.s(x, y, 0) && map.e(x, y - 1, 0) && map.e(x, y, 0) && map.s(x + 1, y, 0),
					map.n(x, y, 0) && map.w(x, y + 1, 0) && map.w(x, y, 0) && map.n(x - 1, y, 0),
					map.n(x, y, 0) && map.e(x, y + 1, 0) && map.e(x, y, 0) && map.n(x + 1, y, 0)};
				for (int i = 0; i < steps.length; i++)
				{
					if (!open[i])
					{
						continue;
					}
					final int hb = heuristic.of(WorldPointUtil.packWorldPoint(steps[i][0], steps[i][1], 0));
					if (ha > 1 + hb)
					{
						violations++;
					}
				}
			}
		}
		assertEquals("walking-edge consistency violations", 0, violations);

		assertTransportEdgesConsistent(cfg, heuristic);
	}

	/**
	 * Transport-edge and teleport-hub consistency: h never overestimates across a ride or a cast.
	 * The origin is the availability MAP KEY — the tile the search actually uses the transport
	 * from — not transport.getOrigin(): the POH remap re-homes interior transports onto the
	 * landing by key only, and checking the stale interior origin is exactly how this sampler
	 * missed the inadmissible-heuristic-at-the-landing bug (capture pair 20260713-232224/232231).
	 */
	private static void assertTransportEdgesConsistent(PathfinderConfig cfg, SearchHeuristic heuristic)
	{
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (int origin : cfg.getTransportsPacked(bankVisited).keys())
			{
				for (Transport transport : cfg.getTransportsPacked(bankVisited).get(origin))
				{
					if (transport.getDestination() == WorldPointUtil.UNDEFINED)
					{
						continue;
					}
					final int edge = Math.max(0, CostUnits.fromTicks(transport.getDuration())
						+ cfg.getAdditionalTransportCost(transport));
					final int ha = heuristic.of(origin);
					final int hb = heuristic.of(transport.getDestination());
					assertTrue("transport edge " + transport + ": h(origin)=" + ha
						+ " > " + edge + " + h(dest)=" + hb, ha <= edge + hb);
				}
			}
			// The hub (h = floor) to every usable teleport landing.
			for (Transport teleport : cfg.getUsableTeleports(bankVisited))
			{
				if (teleport.getDestination() == WorldPointUtil.UNDEFINED)
				{
					continue;
				}
				final int edge = Math.max(0, CostUnits.fromTicks(teleport.getDuration())
					+ cfg.getAdditionalTransportCost(teleport));
				final int hb = heuristic.of(teleport.getDestination());
				assertTrue("hub -> " + teleport + ": floor=" + heuristic.floor()
					+ " > " + edge + " + h(landing)=" + hb, heuristic.floor() <= edge + hb);
			}
		}
	}

	// Keldagrim train station to the Ice Mountain -area target (capture pair
	// 20260713-232224/232231): the scenario whose optimum crosses the POH once the direct
	// teleports are excluded.
	private static final int KELDAGRIM_STATION = WorldPointUtil.packWorldPoint(2907, 10172, 0);
	private static final int ICE_MOUNTAIN_TARGET = WorldPointUtil.packWorldPoint(3009, 3487, 0);

	/** With the POH enabled, the heuristic must stay consistent across the remapped landing hub. */
	@Test
	public void heuristicIsConsistentWithThePohEnabled()
	{
		when(config.usePoh()).thenReturn(true);
		when(config.useTeleportationPortalsPoh()).thenReturn(true);
		PathfinderConfig cfg = everythingConfig();
		DistanceField field = DistanceField.build(cfg, Set.of(ICE_MOUNTAIN_TARGET));
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(cfg, field);
		assertNotNull(heuristic);
		assertTransportEdgesConsistent(cfg, heuristic);
	}

	/**
	 * The optimum must survive crossing the POH: with the direct Lassar teleports excluded, the
	 * cheapest route enters the house and takes the Lassar Portal — the oracle and both production
	 * searches must agree. Pre-fix, A* returned the 67-cost Mind Altar route here.
	 */
	@Test
	public void pohMediatedOptimumIsOptimal()
	{
		when(config.usePoh()).thenReturn(true);
		when(config.useTeleportationPortalsPoh()).thenReturn(true);
		PathfinderConfig cfg = everythingConfig();
		Set<gps.TeleportMethod> excluded = new java.util.HashSet<>();
		for (gps.TeleportMethod method : cfg.getMethodCatalog())
		{
			if (method.label().equals("Lassar tablet") || method.label().equals("Lassar Teleport"))
			{
				excluded.add(method);
			}
		}
		assertTrue("the direct Lassar methods must exist in the catalog", excluded.size() == 2);
		cfg.setExcludedMethods(excluded);
		cfg.rebuildAvailabilityWithExclusions(excluded);
		assertOptimal(cfg, KELDAGRIM_STATION, Set.of(ICE_MOUNTAIN_TARGET));
	}
}

package gps.pathfinder;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * Farmable spirit trees (Port Sarim, Etceteria, Brimhaven, Hosidius, Farming Guild). Smart off:
 * all are assumed available (catalog is the only gate). Smart on: only the trees the travel menu
 * confirmed are planted route, and until the menu is seen none do. The confirmed set lives on the
 * main config; planning copies (the search engine) must read it through their source, or planted
 * trees would never route at all (the bug this feature also fixed).
 */
@RunWith(MockitoJUnitRunner.class)
public class SpiritTreeSmartModeTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.useSpiritTrees()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private static boolean isPortSarimTile(int packed)
	{
		return "Port Sarim".equals(PathfinderConfig.getPlantedSpiritTreeName(
			WorldPointUtil.unpackWorldX(packed), WorldPointUtil.unpackWorldY(packed)));
	}

	/** Whether any spirit-tree transport touching the Port Sarim patch is usable in the engine. */
	private static boolean portSarimTreeRoutes(PathfinderConfig cfg)
	{
		for (int origin : cfg.getTransportsPacked(false).keys())
		{
			for (Transport transport : cfg.getTransportsPacked(false).get(origin))
			{
				if (TransportType.SPIRIT_TREE.equals(transport.getType())
					&& (isPortSarimTile(origin) || isPortSarimTile(transport.getDestination())))
				{
					return true;
				}
			}
		}
		return false;
	}

	private PathfinderConfig search(boolean smart, Set<String> availableOnSource)
	{
		when(config.spiritTreeSmartMode()).thenReturn(smart);
		TestPathfinderConfig main = new TestPathfinderConfig(client, config);
		main.availableSpiritTrees = availableOnSource;
		PathfinderConfig planning = main.copyForPlanning();
		planning.refresh();
		return planning;
	}

	@Test
	public void smartOffAssumesAllFarmableTrees()
	{
		// Off = assume every farmable tree is grown; routing doesn't depend on the detected set.
		assertTrue("with smart tracking off, farmable trees are assumed available",
			portSarimTreeRoutes(search(false, null)));
	}

	@Test
	public void smartOnButUnsyncedIsConservative()
	{
		assertFalse("before the travel menu is seen, farmable trees must not be assumed",
			portSarimTreeRoutes(search(true, null)));
	}

	@Test
	public void smartOnAndPlantedRoutesThroughTheSource()
	{
		// The planted set is on the MAIN config; the planning copy must see it via its source.
		assertTrue("a planted, detected tree must route in the search engine",
			portSarimTreeRoutes(search(true, new HashSet<>(Set.of("Port Sarim")))));
	}

	@Test
	public void smartOnButNotPlantedStaysBlocked()
	{
		assertFalse("a farmable location the player has NOT planted must not route",
			portSarimTreeRoutes(search(true, new HashSet<>(Set.of("Etceteria")))));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * The Stronghold of Security exit portal (leave-to-surface) and its surface entrance both land on
 * the same tile, so with a zero cost the search used "exit → surface → re-enter" as a FREE hop
 * between two adjacent inside tiles — routing the player needlessly out of the dungeon (user
 * capture 20260716-200841). Giving the exit transports a real duration restores the direct walk.
 */
@RunWith(MockitoJUnitRunner.class)
public class StrongholdExitTest
{
	// Adjacent, directly-walkable inside tiles either side of the exit portal.
	private static final int INSIDE_A = WorldPointUtil.packWorldPoint(2837, 10089, 2);
	private static final int INSIDE_B = WorldPointUtil.packWorldPoint(2837, 10090, 2);

	@Mock Client client;
	@Mock ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	@Test
	public void doesNotLeaveTheStrongholdToCrossOneTile()
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		Pathfinder pf = new Pathfinder(cfg, INSIDE_A, Set.of(INSIDE_B));
		pf.run();

		assertTrue(pf.getResult().isReached());
		assertEquals("the two tiles are adjacent — the route must be a single walking step", 1,
			pf.getResult().getTotalCost());
		for (PathStep step : pf.getPath())
		{
			assertTrue("the route must not dip out to the surface: " + step.getPackedPosition(),
				WorldPointUtil.unpackWorldPlane(step.getPackedPosition()) != 0);
		}
	}
}

package gps.pathfinder;

import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import java.util.Map;
import java.util.Set;
import gps.Destination;
import gps.DestinationRequirements;
import gps.ShortestPathConfig;
import gps.transport.Transport;
import gps.transport.TransportLoader;

// This subclass is used to provide mocked implementations of methods from the normal
// PathfinderConfig. CRUCIAL: Not implemented via Mockito as these methods are called
// many times in the inner pathfinding loop.
//
// In particular, at the moment you can provide default values for:
//  * getQuestState: Whether all quests are completed or not started.
//  * varbitChecks: Ignore any varbitChecks.
//  * varPlayerChecks: Ignore any varPlayerChecks.
// Other methods are delegated to a normal PathfinderConfig.
public class TestPathfinderConfig extends PathfinderConfig
{
	/**
	 * Initialization-on-Demand Holder: loads the five resource-heavy fields exactly once
	 * per JVM, so every TestPathfinderConfig instance shares the same pre-parsed data.
	 */
	private static final class ResourceHolder
	{
		static final SplitFlagMap MAP_DATA;
		static final Map<Integer, Set<Transport>> ALL_TRANSPORTS;
		static final Map<String, Set<Integer>> ALL_DESTINATIONS;
		static final Map<String, Set<Integer>> FILTERED_DESTINATIONS;
		static final Map<Integer, DestinationRequirements> BANK_REQUIREMENTS;

		static
		{
			MAP_DATA = SplitFlagMap.fromResources();
			ALL_TRANSPORTS = TransportLoader.loadAllFromResources();
			PathfinderConfig.remapPohDestinations(ALL_TRANSPORTS);
			ALL_DESTINATIONS = Destination.loadAllFromResources();
			FILTERED_DESTINATIONS = PathfinderConfig.filterDestinations(ALL_DESTINATIONS);
			BANK_REQUIREMENTS = Destination.loadBankRequirementsFromResources();
		}
	}

	private final QuestState questState;
	private final boolean bypassVarbitChecks;
	private final boolean bypassVarPlayerChecks;

	public TestPathfinderConfig(Client client, ShortestPathConfig config)
	{
		this(client, config, QuestState.FINISHED, true, true);
	}

	public TestPathfinderConfig(Client client, ShortestPathConfig config, QuestState questState,
		boolean bypassVarbitChecks, boolean bypassVarPlayerChecks)
	{
		super(client, config,
			ResourceHolder.MAP_DATA,
			ResourceHolder.ALL_TRANSPORTS,
			ResourceHolder.ALL_DESTINATIONS,
			ResourceHolder.FILTERED_DESTINATIONS,
			ResourceHolder.BANK_REQUIREMENTS);
		this.questState = questState;
		this.bypassVarbitChecks = bypassVarbitChecks;
		this.bypassVarPlayerChecks = bypassVarPlayerChecks;
	}

	protected TestPathfinderConfig(TestPathfinderConfig source)
	{
		super(source);
		this.questState = source.questState;
		this.bypassVarbitChecks = source.bypassVarbitChecks;
		this.bypassVarPlayerChecks = source.bypassVarPlayerChecks;
	}

	@Override
	protected PathfinderConfig newPlanningCopy()
	{
		return new TestPathfinderConfig(this);
	}

	@Override
	public QuestState getQuestState(Quest quest)
	{
		return questState;
	}

	@Override
	public boolean varbitChecks(Transport transport)
	{
		return !bypassVarbitChecks && super.varbitChecks(transport);
	}

	@Override
	public boolean varPlayerChecks(Transport transport)
	{
		return !bypassVarPlayerChecks && super.varPlayerChecks(transport);
	}
}

package gps.pathfinder;

import gps.TeleportMethod;
import gps.WorldPointUtil;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Plan step N3: a per-search rebuild is a filtered copy of the base availability - only the
 * origins that hold an excluded transport get a new array, every other origin keeps sharing the
 * base array, extras are appended, and with nothing to exclude the base objects are reused.
 */
public class TransportAvailabilityFilteredTest
{
	private static final int A = WorldPointUtil.packWorldPoint(3200, 3200, 0);
	private static final int B = WorldPointUtil.packWorldPoint(3210, 3210, 0);
	private static final int LANDING = WorldPointUtil.packWorldPoint(3220, 3220, 0);

	private static Transport row(int origin, int destination, TransportType type, String info)
	{
		return new Transport.TransportBuilder()
			.origin(origin)
			.destination(destination)
			.type(type)
			.displayInfo(info)
			.build();
	}

	private static TransportAvailability base(Transport... rows)
	{
		TransportAvailability.Builder builder = new TransportAvailability.Builder(rows.length);
		for (Transport row : rows)
		{
			builder.add(row);
		}
		return builder.build();
	}

	@Test
	public void nothingExcludedReusesTheBaseArrays()
	{
		Transport a1 = row(A, LANDING, TransportType.TRANSPORT, "a1");
		Transport teleport = row(Transport.UNDEFINED_ORIGIN, LANDING, TransportType.TELEPORTATION_SPELL, "Tele");
		TransportAvailability base = base(a1, teleport);

		TransportAvailability filtered = base.filtered(Set.of(), List.of());
		assertSame("the base arrays are shared when nothing changes", base.getTransportsPacked().get(A), filtered.getTransportsPacked().get(A));
		assertEquals(1, filtered.getUsableTeleports().length);
	}

	@Test
	public void onlyTheTouchedOriginGetsANewArray()
	{
		Transport a1 = row(A, LANDING, TransportType.TRANSPORT, "a1");
		Transport a2 = row(A, B, TransportType.TRANSPORT, "a2");
		Transport b1 = row(B, LANDING, TransportType.TRANSPORT, "b1");
		Transport teleport = row(Transport.UNDEFINED_ORIGIN, LANDING, TransportType.TELEPORTATION_SPELL, "Tele");
		Transport teleport2 = row(Transport.UNDEFINED_ORIGIN, B, TransportType.TELEPORTATION_SPELL, "Tele2");
		TransportAvailability base = base(a1, a2, b1, teleport, teleport2);

		TransportAvailability filtered = base.filtered(Set.of(a2.method(), teleport.method()), List.of());
		Transport[] atA = filtered.getTransportsPacked().get(A);
		assertNotNull(atA);
		assertEquals("a2 removed", 1, atA.length);
		assertSame(a1, atA[0]);
		assertSame("an untouched origin keeps sharing its array", base.getTransportsPacked().get(B), filtered.getTransportsPacked().get(B));
		assertEquals("the excluded teleport is gone", 1, filtered.getUsableTeleports().length);
		assertSame(teleport2, filtered.getUsableTeleports()[0]);
		assertSame("the display view follows", atA, filtered.getDisplayTransports().get(A));
		// The base is untouched.
		assertEquals(2, base.getTransportsPacked().get(A).length);
		assertEquals(2, base.getUsableTeleports().length);
	}

	@Test
	public void extrasAreAppendedToTheirOrigin()
	{
		Transport a1 = row(A, LANDING, TransportType.TRANSPORT, "a1");
		TransportAvailability base = base(a1);
		Transport extraAtA = row(A, B, TransportType.SAILING, "Sail");
		Transport extraAtB = row(B, LANDING, TransportType.SAILING, "Sail 2");

		TransportAvailability filtered = base.filtered(Set.of(), List.of(extraAtA, extraAtB));
		assertEquals(2, filtered.getTransportsPacked().get(A).length);
		assertEquals(1, filtered.getTransportsPacked().get(B).length);
		assertSame(extraAtB, filtered.getTransportsPacked().get(B)[0]);
		assertTrue("the base is untouched", base.getTransportsPacked().get(B) == null);
	}

	@Test
	public void methodIdentityIsCachedAndFollowsARemappedDestination()
	{
		Transport a1 = row(A, LANDING, TransportType.TRANSPORT, "a1");
		TeleportMethod first = a1.method();
		assertSame("one identity per row", first, a1.method());
		a1.setDestination(B);
		assertEquals("a remapped destination changes the identity", B, a1.method().getDestination());
	}
}

