/**
 * Balloon flights are destination-keyed (wiki: the log type and Firemaking level belong to the
 * DESTINATION, and each route needs its first-flight unlock varbit): the permutation pair-combiner
 * merges the destination-role row's requirements into every generated edge, so a flight from any
 * station to Varrock must require 40 Firemaking, a willow log, and the Varrock unlock (2872=1) —
 * verified against live varbit values (a player with 2872=1 can fly there; 2869=0 cannot fly to
 * Castle Wars). The log can be paid from the inventory or from the balloon storage crates
 * (chat-parsed counts; see {@link gps.BalloonLogStorage}).
 */
public class BalloonRouteTest
{
	private static final int WILLOW_LOGS = 1519;
	private static final int VARROCK_LANDING = WorldPointUtil.packWorldPoint(3299, 3482, 0);
	private static final int ENTRANA_LANDING = WorldPointUtil.packWorldPoint(2808, 3354, 0);

	@Test
	public void flightsCarryTheDestinationsRequirements()
	{
		HashMap<Integer, Set<Transport>> all = TransportLoader.loadAllFromResources();
		// A Castle Wars basket tile; the edge to Varrock's landing (3299,3482).
		Transport flight = null;
		for (Set<Transport> transports : all.values())
		{
			for (Transport transport : transports)
			{
				if (TransportType.HOT_AIR_BALLOON.equals(transport.getType())
					&& transport.getDestination() == VARROCK_LANDING)
				{
					flight = transport;
					break;
				}
			}
			if (flight != null)
			{
				break;
			}
		}
		assertNotNull("a balloon flight to Varrock must exist", flight);

		// Firemaking 40 (destination-keyed).
		boolean firemaking40 = false;
		int[] skills = flight.getSkillLevels();
		// Skill array indexing follows Skill.ordinal(); scan for a 40 requirement.
		for (int level : skills)
		{
			if (level == 40)
			{
				firemaking40 = true;
				break;
			}
		}
		assertTrue("the Varrock flight must require level 40 (Firemaking)", firemaking40);

		// One willow log.
		boolean willow = false;
		if (flight.getItemRequirements() != null)
		{
			for (ItemRequirement req : flight.getItemRequirements().getRequirements())
			{
				if (req.getItemIds() != null)
				{
					for (int id : req.getItemIds())
					{
						if (id == WILLOW_LOGS)
						{
							willow = true;
							break;
						}
					}
				}
			}
		}
		assertTrue("the Varrock flight must require a willow log", willow);

		// The Varrock route unlock varbit (2872=1), verified against live player values.
		boolean unlockVarbit = false;
		for (VarRequirement var : flight.getVarbits())
		{
			if (var.getId() == 2872)
			{
				unlockVarbit = true;
				break;
			}
		}
		assertTrue("the Varrock flight must be gated on its route unlock varbit (2872)", unlockVarbit);

		// And the quest gate from the origin-role row survives the merge.
		Map<Integer, Integer> questState = new HashMap<>();
		questState.put(2867, 2);
		questState.put(2872, 1);
		boolean allPass = true;
		for (VarRequirement var : flight.getVarbits())
		{
			if (!var.check(questState))
			{
				allPass = false;
				break;
			}
		}
		assertTrue("an unlocked player (2867=2, 2872=1) must pass every varbit gate", allPass);
	}

	/**
	 * The possession check must BIND in owned modes: a player whose inventory holds only a willow
	 * log can fly to Varrock (its log) but not to Entrana (needs a normal log). Uses a
	 * possession-checked config (not a planning copy) with the balloon type enabled and varbit
	 * checks bypassed, so the log requirement is the only difference between the two flights.
	 */
	@Test
	public void logPossessionGatesFlightsInOwnedModes()
	{
		Client client = loggedInClient();
		ItemContainer inventory = mock(ItemContainer.class);
		doReturn(new Item[]{new Item(WILLOW_LOGS, 1)}).when(inventory).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);

		boolean[] usable = flightUsability(client, balloonConfig());
		assertTrue("holding a willow log, the Varrock flight must be usable", usable[0]);
		assertFalse("without a normal log, the Entrana flight must not be usable", usable[1]);
	}

	/**
	 * In smart mode the balloon log storage pays for flights without carrying logs: an empty
	 * inventory plus a chat-parsed stored willow count makes the Varrock flight usable, while
	 * Entrana (normal logs; that type's storage is empty) stays gated.
	 */
	@Test
	public void storedLogsCoverFlightsWithoutCarrying()
	{
		ShortestPathConfig config = balloonConfig();
		when(config.balloonSmartMode()).thenReturn(true);
		when(config.balloonStoredWillowLogs()).thenReturn(5);

		boolean[] usable = flightUsability(loggedInClient(), config);
		assertTrue("with willow logs in storage, the Varrock flight must be usable", usable[0]);
		assertFalse("with no normal log stored or carried, the Entrana flight must not be usable", usable[1]);
	}

	/** With smart mode off the storage is not tracked, so stored counts must not pay for flights. */
	@Test
	public void smartModeOffIgnoresTheStoredCounts()
	{
		ShortestPathConfig config = balloonConfig();
		when(config.balloonStoredWillowLogs()).thenReturn(5);

		boolean[] usable = flightUsability(loggedInClient(), config);
		assertFalse("without smart mode, stored counts must not make the Varrock flight usable", usable[0]);
	}

	private static ShortestPathConfig balloonConfig()
	{
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		when(config.calculationCutoff()).thenReturn(30);
		when(config.useHotAirBalloons()).thenReturn(true);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		return config;
	}

	private static Client loggedInClient()
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		return client;
	}

	/** Whether the Varrock ([0]) and Entrana ([1]) flights are usable under the given mocks. */
	private static boolean[] flightUsability(Client client, ShortestPathConfig config)
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config);
		cfg.refresh();

		boolean varrock = false;
		boolean entrana = false;
		for (int origin : cfg.getTransportsPacked(false).keys())
		{
			for (Transport transport : cfg.getTransportsPacked(false).get(origin))
			{
				if (!TransportType.HOT_AIR_BALLOON.equals(transport.getType()))
				{
					continue;
				}
				varrock |= transport.getDestination() == VARROCK_LANDING;
				entrana |= transport.getDestination() == ENTRANA_LANDING;
			}
		}
		return new boolean[]{varrock, entrana};
	}
}

package gps.transport;

import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Capture 20260907-114507: the crew charged half the row's fare. Cabin Fever halves every
 * charter fare and the Ring of charos (a) halves again (a quarter with both); the rows carry base
 * fares and PathfinderConfig scales both the possession check and the displayed fare.
 */
@RunWith(MockitoJUnitRunner.class)
public class CharterFareDiscountTest
{
	private static final int PORT_SARIM_CREW = WorldPointUtil.packWorldPoint(3038, 3192, 0);
	private static final int PORT_TYRAS_DECK = WorldPointUtil.packWorldPoint(2142, 3125, 1);
	private static final int BASE_FARE = 3200;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;
	@Mock
	ItemContainer inventory;
	@Mock
	ItemContainer equipment;

	@Before
	public void stubs()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		lenient().when(client.getItemContainer(InventoryID.WORN)).thenReturn(equipment);
		lenient().when(equipment.getItems()).thenReturn(new Item[0]);
	}

	private Transport portSarimToTyras(PathfinderConfig pathConfig)
	{
		Transport[] fromCrew = pathConfig.getTransportsPacked(false).get(PORT_SARIM_CREW);
		if (fromCrew != null)
		{
			for (Transport transport : fromCrew)
			{
				if (transport.getDestination() == PORT_TYRAS_DECK && TransportType.CHARTER_SHIP.equals(transport.getType()))
				{
					return transport;
				}
			}
		}
		return null;
	}

	@Test
	public void cabinFeverHalvesTheFare()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, BASE_FARE / 2)});
		PathfinderConfig done = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		done.refresh();
		Transport charter = portSarimToTyras(done);
		assertTrue("half the base fare boards after Cabin Fever", charter != null);
		assertEquals(50, done.getCharterFarePercent());
		assertEquals("the label shows what the crew charges", BASE_FARE / 2, done.effectiveCoinFare(charter));
	}

	@Test
	public void withoutCabinFeverTheBaseFareApplies()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, BASE_FARE / 2)});
		PathfinderConfig notDone = new TestPathfinderConfig(client, config, QuestState.NOT_STARTED, true, true);
		notDone.refresh();
		assertEquals(100, notDone.getCharterFarePercent());
		assertFalse("half the base fare does not board without the discount", portSarimToTyras(notDone) != null);
	}

	@Test
	public void ringOfCharosStacksToAQuarter()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, BASE_FARE / 4)});
		when(equipment.getItems()).thenReturn(new Item[]{new Item(ItemID.RING_OF_CHAROS_UNLOCKED, 1)});
		when(equipment.contains(ItemID.RING_OF_CHAROS_UNLOCKED)).thenReturn(true);
		PathfinderConfig done = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		done.refresh();
		assertEquals(25, done.getCharterFarePercent());
		assertTrue("a quarter of the base fare boards with both discounts", portSarimToTyras(done) != null);
	}
}

package gps.transport;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.TeleportMethod;
import gps.WorldPointUtil;

/**
 * Every method-type transport must carry display info: the panel's method rows and the direction
 * steps label methods by it, and the fallback is a bare coordinate pair ("Portals (2440, 3089)") —
 * meaningless to a player. Permutation networks inherit the destination row's info, so this
 * effectively requires every direct row and every destination-role row to be named.
 */
public class MethodDisplayInfoTest
{
	@Test
	public void everyMethodTransportIsNamed()
	{
		List<String> unnamed = new ArrayList<>();
		for (Set<Transport> transports : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : transports)
			{
				if (!TeleportMethod.isMethodType(transport.getType()))
				{
					continue;
				}
				String info = transport.getDisplayInfo();
				if (info == null || info.isEmpty())
				{
					int d = transport.getDestination();
					unnamed.add(transport.getType() + " -> (" + WorldPointUtil.unpackWorldX(d)
						+ ", " + WorldPointUtil.unpackWorldY(d) + ", " + WorldPointUtil.unpackWorldPlane(d) + ")");
				}
			}
		}
		assertTrue("method transports without display info (would label as coordinates): " + unnamed,
			unnamed.isEmpty());
	}

	/**
	 * Every network RIDE must cost at least a tick: a missing Duration cell prices the ride at
	 * zero, and the search then uses it as a free shortcut (the Keldagrim train rode to White Wolf
	 * Mountain and back to cross 18 tiles — user capture 20260713-233919).
	 */
	@Test
	public void everyNetworkRideHasADuration()
	{
		Set<TransportType> rides = java.util.EnumSet.of(
			TransportType.BOAT, TransportType.CANOE, TransportType.CHARTER_SHIP, TransportType.SHIP,
			TransportType.GNOME_GLIDER, TransportType.HOT_AIR_BALLOON, TransportType.MAGIC_CARPET,
			TransportType.MAGIC_MUSHTREE, TransportType.MINECART, TransportType.MOUNTAIN_GUIDE,
			TransportType.QUETZAL, TransportType.SPIRIT_TREE, TransportType.WILDERNESS_OBELISK);
		List<String> free = new ArrayList<>();
		for (Set<Transport> transports : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : transports)
			{
				if (rides.contains(transport.getType()) && transport.getDuration() < 1)
				{
					free.add(transport.getType() + " -> " + transport.getDisplayInfo());
				}
			}
		}
		assertTrue("rides with no duration (searched as free shortcuts): " + free, free.isEmpty());
	}
}

package gps.transport;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.TeleportMethod;
import gps.WorldPointUtil;

/**
 * Mountain-guide rows must carry their DESTINATION as display info — the data used to repeat the
 * menu text ("Travel Mountain Guide") on every row, so route cards and direction steps could not
 * say where the guide goes, and identical labels collapsed the catalog entries' meaning.
 */
public class MountainGuideLabelTest
{
	@Test
	public void everyGuideRouteNamesItsDestination()
	{
		Map<Integer, String> expected = new HashMap<>();
		expected.put(WorldPointUtil.packWorldPoint(1275, 3559, 0), "Mount Quidamortem");
		expected.put(WorldPointUtil.packWorldPoint(1272, 3475, 0), "South of Quidamortem");
		expected.put(WorldPointUtil.packWorldPoint(1401, 3536, 0), "Shayzien Outpost");
		expected.put(WorldPointUtil.packWorldPoint(1361, 3309, 0), "Auburnvale");
		expected.put(WorldPointUtil.packWorldPoint(1486, 3232, 0), "Quetzacalli Gorge");

		int guides = 0;
		for (Set<Transport> transports : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : transports)
			{
				if (!TransportType.MOUNTAIN_GUIDE.equals(transport.getType()))
				{
					continue;
				}
				guides++;
				String info = transport.getDisplayInfo();
				assertFalse("display info must not be the menu text: " + info,
					info == null || info.contains("Mountain Guide"));
				assertEquals("display info must name the destination",
					expected.get(transport.getDestination()), info);
				assertEquals("the route label must name the vehicle",
					"Mountain guide to " + info, TeleportMethod.fromTransport(transport).routeLabel());
			}
		}
		assertTrue("the mountain-guide network must load (got " + guides + " routes)", guides >= 8);
	}
}

package gps.transport;

import gps.WorldPointUtil;
import gps.transport.parser.ParseErrors;
import gps.transport.parser.QuestParser;
import gps.transport.parser.WorldPointParser;
import java.util.List;
import java.util.Set;
import net.runelite.api.Quest;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Review 2026-09-06: three transport rows shipped UNGATED because their quest name matched no
 * Quest enum entry and the parser dropped the gate silently; one row lost its destination to a
 * leading space and fell out of the graph. Both parsers now record parse errors, which the data
 * lint drains, so the next typo is a red build instead of a silent behaviour change.
 */
public class QuestAndCoordinateParserTest
{
	@Before
	public void drain()
	{
		ParseErrors.drain();
	}

	@Test
	public void knownQuestsParseCleanly()
	{
		Set<Quest> quests = new QuestParser().parse("Shadow of the Storm;Recipe for Disaster - King Awowogei");
		assertTrue(quests.contains(Quest.SHADOW_OF_THE_STORM));
		assertTrue(quests.contains(Quest.RECIPE_FOR_DISASTER__KING_AWOWOGEI));
		assertTrue("no errors for valid names", ParseErrors.drain().isEmpty());
	}

	@Test
	public void unknownQuestNameIsRecordedNotDropped()
	{
		Set<Quest> quests = new QuestParser().parse("Shadows of the Storm");
		assertTrue(quests.isEmpty());
		List<String> errors = ParseErrors.drain();
		assertEquals("exactly one recorded error", 1, errors.size());
		assertTrue(errors.get(0), errors.get(0).contains("Shadows of the Storm"));
	}

	@Test
	public void paddedCoordinateStillParses()
	{
		WorldPointParser parser = new WorldPointParser();
		assertEquals((Integer) WorldPointUtil.packWorldPoint(3035, 4852, 0), parser.parse(" 3035 4852 0"));
		assertEquals((Integer) WorldPointUtil.packWorldPoint(3019, 9741, 0), parser.parse("3019 9741 0 "));
		assertTrue("padding is tolerated silently", ParseErrors.drain().isEmpty());
	}

	@Test
	public void malformedCoordinateIsRecorded()
	{
		WorldPointParser parser = new WorldPointParser();
		assertEquals((Integer) Transport.LOCATION_PERMUTATION, parser.parse("3035 4852"));
		assertEquals("a two-part cell is a malformed coordinate", 1, ParseErrors.drain().size());
		assertEquals("empty stays a permutation without an error", (Integer) Transport.LOCATION_PERMUTATION, parser.parse(""));
		assertTrue(ParseErrors.drain().isEmpty());
	}
}

