package gps.transport;

import net.runelite.api.Quest;

import gps.transport.parser.ParseErrors;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;
import gps.WorldPointUtil;

/**
 * Unit tests for validating transport data integrity.
 * These tests validate the consistency and correctness of transport data files.
 */
public class TransportDataLintTest
{

	@Test
	public void testNoDuplicateOriginDestinationPairs()
	{
		// Load all transport data from resources
		HashMap<Integer, Set<Transport>> transports = TransportLoader.loadAllFromResources();

		// Track all origin-destination-type combinations to check for exact duplicates
		Set<String> transportSignatures = new HashSet<>();
		Map<String, String> duplicateInfo = new HashMap<>();
		List<String> duplicatesFound = new ArrayList<>();

		for (Map.Entry<Integer, Set<Transport>> entry : transports.entrySet())
		{
			int origin = entry.getKey();
			Set<Transport> transportSet = entry.getValue();

			for (Transport transport : transportSet)
			{
				int destination = transport.getDestination();

				// Create a comprehensive signature that includes all transport properties
				// This helps distinguish between legitimate different transport variants vs
				// true duplicates
				// ObjectInfo is critical for distinguishing fairy rings with different item
				// requirements
				// (e.g., dramen staff vs lunar staff are represented by different objectIDs in
				// objectInfo)
				// The display info is there of the one edge case in the fairy ring system.
				// There are two options to go to Zanaris, one is with the code `B K S` and the
				// other is with the `zanaris` option.
				// only the display info is different between those two options so we need to
				// include it in the signature.
				String signature = String.format(
					"%s -> %s [%s] '%s' Consumable:%s Items:%s Quests:%s Varbits:%s VarPlayers:%s ObjectInfo:%s",
					WorldPointUtil.unpackWorldX(origin) + " " + WorldPointUtil.unpackWorldY(origin) + " "
						+ WorldPointUtil.unpackWorldPlane(origin),
					WorldPointUtil.unpackWorldX(destination) + " " + WorldPointUtil.unpackWorldY(destination) + " "
						+ WorldPointUtil.unpackWorldPlane(destination),
					transport.getType(),
					transport.getDisplayInfo() != null ? transport.getDisplayInfo() : "",
					transport.isConsumable(),
					transport.getItemRequirements() != null ? transport.getItemRequirements().toString() : "none",
					transport.getQuests().toString(),
					transport.getVarbits().toString(),
					transport.getVarPlayers().toString(),
					transport.getObjectInfo() != null ? transport.getObjectInfo() : "none");

				// Check if this exact transport signature already exists
				if (transportSignatures.contains(signature))
				{
					String existingInfo = duplicateInfo.get(signature);
					String newInfo = String.format("MaxWilderness: %d, Skills: %s",
						transport.getMaxWildernessLevel(),
						Arrays.toString(transport.getSkillLevels()));

					duplicatesFound.add(String.format("Exact duplicate transport: %s\n" +
							"First occurrence: %s\n" +
							"Duplicate occurrence: %s\n",
						signature, existingInfo, newInfo));
				}
				else
				{
					// Add this signature to our tracking set
					transportSignatures.add(signature);

					// Store information about this transport for error reporting
					String info = String.format("MaxWilderness: %d, Skills: %s",
						transport.getMaxWildernessLevel(),
						Arrays.toString(transport.getSkillLevels()));
					duplicateInfo.put(signature, info);
				}
			}
		}

		// Report results
		if (!duplicatesFound.isEmpty())
		{
			StringBuilder message = new StringBuilder();
			message.append(String.format("Found %d duplicate transport entries in the data files:\n\n",
				duplicatesFound.size()));
			for (String duplicate : duplicatesFound)
			{
				message.append(duplicate).append("\n");
			}
			Assert.fail(message.toString());
		}

		// If we get here, no exact duplicates were found
		System.out.printf("Successfully validated %d unique transport signatures across all transport data files.\n",
			transportSignatures.size());
	}
	/**
	 * The data must parse CLEANLY: a requirement the parser cannot read is dropped, and the
	 * transport becomes usable without its gate. For weeks that was log noise only — an
	 * Underground Pass dig spelled "Spade" (free without one), the Motherlode ladders put their
	 * duration in the varbit column. Now it fails the build.
	 */
	@Test
	public void everyRequirementParses()
	{
		ParseErrors.drain();
		HashMap<Integer, Set<Transport>> all = TransportLoader.loadAllFromResources();
		Assert.assertTrue("transports must load", !all.isEmpty());
		List<String> errors = ParseErrors.drain();
		Assert.assertTrue("requirements that failed to parse (the gate is DROPPED for each):\n  "
			+ String.join("\n  ", errors), errors.isEmpty());
	}

	/**
	 * Issue #17: the house Respawn Portal's Prifddinas row had no gate at all — every other
	 * respawn row carries its unlock varbit. Song of the Elves is the Prifddinas unlock.
	 */
	@Test
	public void prifddinasRespawnPortalIsQuestGated()
	{
		boolean found = false;
		for (Set<Transport> set : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : set)
			{
				if ("Respawn Portal (Prifddinas)".equals(transport.getDisplayInfo()))
				{
					found = true;
					Assert.assertTrue("Prifddinas respawn must require Song of the Elves, got "
						+ transport.getQuests(), transport.getQuests().contains(Quest.SONG_OF_THE_ELVES));
				}
				if ("Respawn Portal (Lumbridge)".equals(transport.getDisplayInfo()))
				{
					Assert.assertTrue("the default respawn has no quest gate", transport.getQuests().isEmpty());
					// The *_SPAWN varbits are SELECTION flags (one per respawn point, field-verified
					// 2026-08-16: setting Falador flips FALADOR_SPAWN 0 -> 1); Lumbridge is the
					// default when none is set, so its row must require every known flag to be 0.
					Assert.assertEquals("Lumbridge must be gated on all six selection flags", 6,
						transport.getVarbits().size());
				}
			}
		}
		Assert.assertTrue("the Prifddinas respawn row must exist", found);
	}
	/**
	 * The Monkey Madness I chain to Ape Atoll (Daero -> Waydar's glider -> Lumdo's boat) was
	 * ungated and its two flights were plain rows, so anyone got routed through it and the legs
	 * showed as "Travel Waydar" / "Travel Lumdo" instead of a glider and a boat. Quest Helper's
	 * varbits gate it (MM_DAERO >= 7 after the hangar puzzle, MM_LUMDO >= 3 after Waydar's
	 * Crash Island briefing), and the flights/boat are method-typed so they have catalog entries
	 * and "Glider to Crash Island" / "Boat to Ape Atoll" wording.
	 */
	@Test
	public void monkeyMadnessChainIsGatedAndTyped()
	{
		Map<String, List<Transport>> byObject = new HashMap<>();
		for (Set<Transport> set : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : set)
			{
				String info = transport.getObjectInfo();
				if (info != null && (info.startsWith("Travel Daero") || info.startsWith("Travel Waydar")
					|| info.startsWith("Travel Lumdo")))
				{
					byObject.computeIfAbsent(info.substring(0, info.lastIndexOf(' ')), k -> new ArrayList<>()).add(transport);
				}
			}
		}
		Assert.assertEquals("Daero's ride", 1, byObject.getOrDefault("Travel Daero", List.of()).size());
		Assert.assertEquals("Waydar's two flights", 2, byObject.getOrDefault("Travel Waydar", List.of()).size());
		Assert.assertEquals("Lumdo's boat both ways", 2, byObject.getOrDefault("Travel Lumdo", List.of()).size());
		for (Transport t : byObject.get("Travel Daero"))
		{
			Assert.assertEquals(1, t.getVarbits().size());
		}
		for (Transport t : byObject.get("Travel Waydar"))
		{
			Assert.assertEquals("a glider flight, not a plain row", TransportType.GNOME_GLIDER, t.getType());
			Assert.assertTrue("named destination: " + t.getDisplayInfo(),
				"Crash Island".equals(t.getDisplayInfo()) || "Gnome Stronghold (Waydar)".equals(t.getDisplayInfo()));
			Assert.assertEquals(1, t.getVarbits().size());
		}
		for (Transport t : byObject.get("Travel Lumdo"))
		{
			Assert.assertEquals(TransportType.BOAT, t.getType());
			Assert.assertTrue("named destination: " + t.getDisplayInfo(),
				"Ape Atoll".equals(t.getDisplayInfo()) || "Crash Island".equals(t.getDisplayInfo()));
			Assert.assertEquals(1, t.getVarbits().size());
		}
	}
	/**
	 * Charter arrivals land ON THE DECK (plane 1): the game leaves you on the ship and the
	 * paired Cross Gangplank row is the step down to the dock. With dockside destinations the
	 * path skipped the gangplank entirely and drew nothing while the player stood on plane 1
	 * (field report 2026-08-24, Port Tyras). Land's End is the one port with no gangplank pair
	 * in the data yet, so it still lands dockside.
	 */
	@Test
	public void charterArrivalsLandOnTheDeck()
	{
		int deckArrivals = 0;
		for (Set<Transport> set : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : set)
			{
				if (!TransportType.CHARTER_SHIP.equals(transport.getType()))
				{
					continue;
				}
				int plane = WorldPointUtil.unpackWorldPlane(transport.getDestination());
				boolean landsEnd = WorldPointUtil.unpackWorldX(transport.getDestination()) == 1496
					&& WorldPointUtil.unpackWorldY(transport.getDestination()) == 3403;
				// The Pandemonium also lands dockside until its charter gangplank pair is field-verified
				// (two ships share the east dock; see charter_ships.tsv).
				boolean pandemonium = WorldPointUtil.unpackWorldX(transport.getDestination()) == 3063
					&& WorldPointUtil.unpackWorldY(transport.getDestination()) == 2999;
				Assert.assertTrue("charter to " + transport.getDisplayInfo()
					+ " must arrive on the ship's deck (plane 1)", plane == 1 || landsEnd || pandemonium);
				if (plane == 1)
				{
					deckArrivals++;
				}
			}
		}
		Assert.assertTrue("deck arrivals expected", deckArrivals > 100);
	}
	/**
	 * Sailors' amulet destinations unlock by inspecting their Sailors' Marker (gameval
	 * SAILORS_AMULET_*, field-verified via the varbit watch 2026-08-28): Port Roberts and
	 * Deepfin Point carry their unlock varbit; The Pandemonium is the amulet's home port and
	 * needs none.
	 */
	@Test
	public void sailorsAmuletDestinationsCarryTheirUnlockVarbits()
	{
		int roberts = 0, deepfin = 0, redRock = 0, pandemonium = 0;
		for (Set<Transport> set : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : set)
			{
				String info = transport.getDisplayInfo();
				if (info == null || !info.startsWith("Sailors' amulet:"))
				{
					continue;
				}
				if (info.endsWith("Port Roberts"))
				{
					roberts++;
					Assert.assertEquals("Port Roberts needs its marker varbit", 1, transport.getVarbits().size());
				}
				else if (info.endsWith("Deepfin Point"))
				{
					deepfin++;
					Assert.assertEquals("Deepfin needs its marker varbit", 1, transport.getVarbits().size());
				}
				else if (info.endsWith("Red Rock"))
				{
					redRock++;
					Assert.assertEquals("Red Rock needs its marker varbit", 1, transport.getVarbits().size());
				}
				else if (info.endsWith("The Pandemonium"))
				{
					pandemonium++;
					Assert.assertEquals("the home port has no unlock", 0, transport.getVarbits().size());
				}
			}
		}
		Assert.assertTrue("all four amulet rows must exist",
			roberts == 1 && deepfin == 1 && redRock == 1 && pandemonium == 1);
	}
}

package gps.transport;

import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;
import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Plan step N15 (data lint): every transport endpoint must be a tile the player can stand on.
 * An origin is standable when it is unblocked, or blocked with an unblocked cardinal neighbour
 * (the forward rule that lets a path step onto a fairy ring platform); a destination when it is
 * unblocked, or blocked with a step-off neighbour (any unblocked cardinal, or a diagonal with
 * both flanking cardinals open: the rule the distance field mirrors). An endpoint that fails
 * both is a row the search can never use: a typo, a stale object position, or a cache update
 * that moved a wall. Sea legs, boat tiles and the instance template band are out of scope here.
 */
@RunWith(MockitoJUnitRunner.class)
public class TransportEndpointLintTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private static final int INSTANCE_MIN_Y = 4160;
	private static final int INSTANCE_MAX_Y = 8000;

	/**
	 * The known offenders, one per line in the audit's own wording, so a NEW one fails by name
	 * and a listed one that is fixed must be removed (the list only shrinks honestly). Regenerate
	 * after a cache refresh with -Dgps.writeExpectedEndpoints=true.
	 */
	private static final String EXPECTED = "src/test/resources/expected-unstandable-endpoints.tsv";

	private static java.util.Set<String> loadExpected() throws java.io.IOException
	{
		java.nio.file.Path path = java.nio.file.Paths.get(EXPECTED);
		if (!java.nio.file.Files.exists(path))
		{
			return null;
		}
		java.util.Set<String> expected = new java.util.HashSet<>();
		for (String line : java.nio.file.Files.readAllLines(path, java.nio.charset.StandardCharsets.UTF_8))
		{
			if (!line.isEmpty() && !line.startsWith("#"))
			{
				expected.add(line);
			}
		}
		return expected;
	}

	private static void writeExpected(List<String> offenders) throws java.io.IOException
	{
		List<String> lines = new ArrayList<>();
		lines.add("# Transport endpoints known not to be standable (TransportEndpointLintTest): blocked tiles with no");
		lines.add("# step-off neighbour on the shipped collision map. Generated with -Dgps.writeExpectedEndpoints=true;");
		lines.add("# fix rows or the map to shrink it, never add by hand. One audit line per endpoint.");
		lines.addAll(new java.util.TreeSet<>(offenders));
		java.nio.file.Files.write(java.nio.file.Paths.get(EXPECTED), lines, java.nio.charset.StandardCharsets.UTF_8);
	}

	@Test
	public void everyTransportEndpointIsStandable() throws java.io.IOException
	{
		when(config.calculationCutoff()).thenReturn(120);
		lenient().when(config.currencyThreshold()).thenReturn(10000000);
		lenient().when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		PathfinderConfig pathConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		pathConfig.refresh();
		CollisionMap map = pathConfig.getMap();

		List<String> offenders = new ArrayList<>();
		int checked = 0;
		for (Transport transport : pathConfig.getAllTransports())
		{
			if (transport.getType() == TransportType.SAILING)
			{
				continue;
			}
			int origin = transport.getOrigin();
			int destination = transport.getDestination();
			if (origin != Transport.UNDEFINED_ORIGIN && !inBand(origin) && !gps.SailingSea.isSailable(origin))
			{
				checked++;
				if (!standableOrigin(map, origin))
				{
					offenders.add("origin " + describe(transport, origin));
				}
			}
			if (destination != WorldPointUtil.UNDEFINED && !inBand(destination) && !gps.SailingSea.isSailable(destination))
			{
				checked++;
				if (!standableLanding(map, destination))
				{
					offenders.add("destination " + describe(transport, destination));
				}
			}
		}
		System.out.println("ENDPOINTLINT checked=" + checked + " offenders=" + offenders.size());
		assertTrue("premise: thousands of endpoints", checked > 5000);
		if (Boolean.getBoolean("gps.writeExpectedEndpoints"))
		{
			writeExpected(offenders);
		}
		java.util.Set<String> expected = loadExpected();
		assertTrue("the expected-endpoints list is missing (" + EXPECTED + "): generate it with"
			+ " -Dgps.writeExpectedEndpoints=true and check it in", expected != null);
		java.util.Set<String> offenderSet = new java.util.HashSet<>(offenders);
		List<String> fresh = new ArrayList<>();
		for (String offender : offenders)
		{
			if (!expected.contains(offender))
			{
				fresh.add(offender);
			}
		}
		List<String> stale = new ArrayList<>();
		for (String entry : expected)
		{
			if (!offenderSet.contains(entry))
			{
				stale.add(entry);
			}
		}
		java.util.Collections.sort(stale);
		assertTrue(fresh.size() + " NEW transport endpoints are not standable (unblocked, or blocked with a step-off"
			+ " neighbour); " + offenders.size() + " in total, " + expected.size() + " expected. A data regression to fix,"
			+ " or a cache refresh: then regenerate with -Dgps.writeExpectedEndpoints=true. First:\n  "
			+ String.join("\n  ", fresh.subList(0, Math.min(60, fresh.size()))), fresh.isEmpty());
		assertTrue(stale.size() + " listed endpoints are standable now: remove them from " + EXPECTED
			+ " (regenerate with -Dgps.writeExpectedEndpoints=true). First:\n  "
			+ String.join("\n  ", stale.subList(0, Math.min(40, stale.size()))), stale.isEmpty());
	}

	private static boolean inBand(int packed)
	{
		int y = WorldPointUtil.unpackWorldY(packed);
		return y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y;
	}

	private static boolean standableOrigin(CollisionMap map, int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		if (!map.isBlocked(x, y, plane))
		{
			return true;
		}
		return !map.isBlocked(x - 1, y, plane) || !map.isBlocked(x + 1, y, plane)
			|| !map.isBlocked(x, y - 1, plane) || !map.isBlocked(x, y + 1, plane);
	}

	private static boolean standableLanding(CollisionMap map, int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		if (!map.isBlocked(x, y, plane))
		{
			return true;
		}
		boolean w = !map.isBlocked(x - 1, y, plane);
		boolean e = !map.isBlocked(x + 1, y, plane);
		boolean s = !map.isBlocked(x, y - 1, plane);
		boolean n = !map.isBlocked(x, y + 1, plane);
		return w || e || s || n
			|| (!map.isBlocked(x - 1, y - 1, plane) && w && s) || (!map.isBlocked(x + 1, y - 1, plane) && e && s)
			|| (!map.isBlocked(x - 1, y + 1, plane) && w && n) || (!map.isBlocked(x + 1, y + 1, plane) && e && n);
	}

	private static String describe(Transport transport, int packed)
	{
		return WorldPointUtil.unpackWorldX(packed) + "," + WorldPointUtil.unpackWorldY(packed) + ","
			+ WorldPointUtil.unpackWorldPlane(packed) + " " + transport.getType()
			+ (transport.getDisplayInfo() != null ? " " + transport.getDisplayInfo() : "")
			+ (transport.getObjectInfo() != null ? " [" + transport.getObjectInfo() + "]" : "");
	}
}

package gps.transport;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.transport.requirement.TransportItems;

public class TransportItemsTest
{

	@Test
	public void gettersAndToStringWork()
	{
		int[][] items = new int[][]{new int[]{1, 2}, new int[]{3}};
		int[][] staves = new int[][]{new int[]{10}, new int[]{20, 30}};
		int[][] offhands = new int[][]{new int[]{100}, new int[]{200}};
		int[] quantities = new int[]{5, 10};

		TransportItems ti = new TransportItems(items, staves, offhands, quantities);

		assertArrayEquals(items, ti.getItems());
		assertArrayEquals(staves, ti.getStaves());
		assertArrayEquals(offhands, ti.getOffhands());
		assertArrayEquals(quantities, ti.getQuantities());

		String s = ti.toString();
		assertTrue(s.contains("["));
		assertTrue(s.contains("]"));
		assertTrue("toString should include items", s.contains("[1, 2]"));
		assertTrue("toString should include staves", s.contains("[10]"));
		assertTrue("toString should include offhands", s.contains("[100]"));
		assertTrue("toString should include quantities", s.contains("[5, 10]"));
	}

	@Test
	public void equalsAndHashCodeByContents()
	{
		int[][] items1 = new int[][]{new int[]{1, 2}, new int[]{3}};
		int[][] staves1 = new int[][]{new int[]{10}, new int[]{20, 30}};
		int[][] offhands1 = new int[][]{new int[]{100}, new int[]{200}};
		int[] quantities1 = new int[]{5, 10};

		int[][] items2 = new int[][]{new int[]{1, 2}, new int[]{3}};
		int[][] staves2 = new int[][]{new int[]{10}, new int[]{20, 30}};
		int[][] offhands2 = new int[][]{new int[]{100}, new int[]{200}};
		int[] quantities2 = new int[]{5, 10};

		TransportItems a = new TransportItems(items1, staves1, offhands1, quantities1);
		TransportItems b = new TransportItems(items2, staves2, offhands2, quantities2);

		// Lombok @EqualsAndHashCode performs deep array equality; same contents should
		// be equal
		assertEquals(a, b);
		assertEquals(a.hashCode(), b.hashCode());

		// Changing any content should make them not equal
		int[] quantitiesDifferent = new int[]{5, 11};
		TransportItems d = new TransportItems(items2, staves2, offhands2, quantitiesDifferent);
		assertNotEquals(a, d);
	}
}

package gps.transport;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import gps.WorldPointUtil;
import gps.transport.parser.VarRequirement;
import gps.transport.requirement.TransportItems;

/**
 * Comprehensive unit tests for {@link Transport}
 * method.
 */
public class TransportLoaderTest
{

	private Map<Integer, Set<Transport>> transports;

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
	}

	// Helper method to get the first transport from a set
	private Transport getFirstTransport(Set<Transport> transportSet)
	{
		Assert.assertFalse("Transport set should not be empty", transportSet.isEmpty());
		return transportSet.iterator().next();
	}

	@Test
	public void testBasicTransportParsing()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"3200 3200 0\t3300 3300 0\t5\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int originPacked = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int destinationPacked = WorldPointUtil.packWorldPoint(3300, 3300, 0);

		Assert.assertTrue("Should contain origin", transports.containsKey(originPacked));
		Set<Transport> transportSet = transports.get(originPacked);
		Assert.assertEquals("Should have exactly one transport", 1, transportSet.size());

		Transport transport = getFirstTransport(transportSet);
		Assert.assertEquals("Origin should match", originPacked, transport.getOrigin());
		Assert.assertEquals("Destination should match", destinationPacked, transport.getDestination());
		Assert.assertEquals("Duration should match", 5, transport.getDuration());
		Assert.assertEquals("Type should match", TransportType.TRANSPORT, transport.getType());
	}

	@Test
	public void testEmptyAndCommentLines()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"# This is a comment\n" +
			"\n" +
			"3200 3200 0\t3300 3300 0\t5\n" +
			"\n" +
			"# Another comment\n" +
			"3400 3400 0\t3500 3500 0\t10\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		Assert.assertEquals("Should have exactly 2 origins", 2, transports.size());

		int origin1 = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3400, 3400, 0);

		Assert.assertTrue("Should contain first origin", transports.containsKey(origin1));
		Assert.assertTrue("Should contain second origin", transports.containsKey(origin2));

		// Check exact contents for each origin
		int dest1 = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		int dest2 = WorldPointUtil.packWorldPoint(3500, 3500, 0);
		Transport t1 = getFirstTransport(transports.get(origin1));
		Transport t2 = getFirstTransport(transports.get(origin2));
		Assert.assertEquals("Origin1 destination should match", dest1, t1.getDestination());
		Assert.assertEquals("Origin1 duration should match", 5, t1.getDuration());
		Assert.assertEquals("Origin2 destination should match", dest2, t2.getDestination());
		Assert.assertEquals("Origin2 duration should match", 10, t2.getDuration());
	}

	@Test
	public void testMultipleTransportsFromSameOrigin()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"3200 3200 0\t3300 3300 0\t5\n" +
			"3200 3200 0\t3400 3400 0\t10\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Assert.assertTrue("Should contain origin", transports.containsKey(origin));

		Set<Transport> transportSet = transports.get(origin);
		Assert.assertEquals("Should have exactly two transports", 2, transportSet.size());

		int destination1 = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		int destination2 = WorldPointUtil.packWorldPoint(3400, 3400, 0);
		boolean hasDestination1 = false, hasDestination2 = false;
		for (Transport t : transportSet)
		{
			if (t.getDestination() == destination1)
			{
				hasDestination1 = true;
				Assert.assertEquals("Duration for first should match", 5, t.getDuration());
			}
			else if (t.getDestination() == destination2)
			{
				hasDestination2 = true;
				Assert.assertEquals("Duration for second should match", 10, t.getDuration());
			}
		}
		Assert.assertTrue("Should contain destination 1", hasDestination1);
		Assert.assertTrue("Should contain destination 2", hasDestination2);
	}

	@Test
	public void testTeleportDurationAdjustment()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"\t3300 3300 0\t0\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TELEPORTATION_SPELL, 0);

		// Teleportation spells have undefined origin, so we need to check the transport
		// differently
		// Since origin is undefined, this should create a transport but not add it to
		// the map
		Assert.assertTrue("No transports should be added for undefined origin teleports", transports.isEmpty());
	}

	@Test
	public void testNonTeleportDurationNotAdjusted()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"3200 3200 0\t3300 3300 0\t0\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport transport = getFirstTransport(transports.get(origin));
		Assert.assertEquals("Duration should remain 0 for non-teleports", 0, transport.getDuration());
	}

	@Test
	public void testPermutationTransports()
	{
		// Simulating fairy ring transport where origins and destinations are
		// permutations
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tAIQ\n" +
			"3200 3200 0\t\tBJR\n" +
			"\t3300 3300 0\tAIQ\n" +
			"\t3400 3400 0\tBJR\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);

		// Should create permutations: AIQ->AIQ, AIQ->BJR, BJR->AIQ, BJR->BJR
		// AIQ->AIQ and BJR->BJR should be filtered out by distance check (same
		// coordinates)

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Assert.assertTrue("Should contain first origin", transports.containsKey(origin1));
		Assert.assertTrue("Should contain second origin", transports.containsKey(origin2));

		// Each origin should have two transports (to each of the two destinations)
		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		Assert.assertEquals("Origin 1 should have two transports", 2, transports1.size());
