		Assert.assertTrue("No transports should be added for undefined destination", transports.isEmpty());
	}

	@Test
	public void testRadiusThresholdFiltering()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"3200 3200 0\t\tLocation2\n" +
			"\t3102 3102 0\tLocation1\n" + // Distance 2.8 from first origin
			"\t3105 3105 0\tLocation1\n" + // Distance 7.1 from first origin
			"\t3400 3400 0\tLocation2\n";

		// Test with radius threshold of 5
		TransportLoader.addTransportsFromContents(transports, contents, TransportType.SPIRIT_TREE, 5);

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Assert.assertTrue("Should contain first origin", transports.containsKey(origin1));
		Assert.assertTrue("Should contain second origin", transports.containsKey(origin2));

		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		// Exact expectations given radius=5 and Chebyshev metric with strict '>'
		// Distance to 3102 is 2 (filtered), to 3105 is 5 (filtered), to 3400 is 300
		// (kept)
		Assert.assertEquals("Origin 1 should have one transport (3400)", 1, transports1.size());
		Assert.assertEquals("Origin 2 should have three transports (3102,3105,3400)", 3, transports2.size());

		int closeDestination = WorldPointUtil.packWorldPoint(3102, 3102, 0);
		int midDestination = WorldPointUtil.packWorldPoint(3105, 3105, 0);
		int farDestination = WorldPointUtil.packWorldPoint(3400, 3400, 0);

		boolean o1hasClose = false, o1hasMid = false, o1hasFar = false;
		for (Transport t : transports1)
		{
			if (t.getDestination() == closeDestination)
			{
				o1hasClose = true;
			}
			if (t.getDestination() == midDestination)
			{
				o1hasMid = true;
			}
			if (t.getDestination() == farDestination)
			{
				o1hasFar = true;
			}
		}
		Assert.assertFalse("Origin1 should not include very close destination", o1hasClose);
		Assert.assertFalse("Origin1 should not include mid destination at equal threshold", o1hasMid);
		Assert.assertTrue("Origin1 should include far destination", o1hasFar);

		boolean o2hasClose = false, o2hasMid = false, o2hasFar = false;
		for (Transport t : transports2)
		{
			if (t.getDestination() == closeDestination)
			{
				o2hasClose = true;
			}
			if (t.getDestination() == midDestination)
			{
				o2hasMid = true;
			}
			if (t.getDestination() == farDestination)
			{
				o2hasFar = true;
			}
		}
		Assert.assertTrue("Origin2 should include close destination (not close to origin2)", o2hasClose);
		Assert.assertTrue("Origin2 should include mid destination", o2hasMid);
		Assert.assertTrue("Origin2 should include far destination", o2hasFar);
	}

	@Test
	public void testZeroRadiusThreshold()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"3200 3200 0\t\tLocation2\n" +
			"\t3101 3101 0\tLocation1\n" + // Very close
			"\t3400 3400 0\tLocation2\n";

		// Test with radius threshold of 0 (no filtering)
		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		// With radius 0, only exact same coordinates should be filtered out
		// All different coordinates should be included
		Assert.assertEquals("Origin 1 should have 2 transports", 2, transports1.size());
		Assert.assertEquals("Origin 2 should have 2 transports", 2, transports2.size());

		int nearDest = WorldPointUtil.packWorldPoint(3101, 3101, 0);
		int farDest = WorldPointUtil.packWorldPoint(3400, 3400, 0);
		boolean o1near = false, o1far = false, o2near = false, o2far = false;
		for (Transport t : transports1)
		{
			if (t.getDestination() == nearDest)
			{
				o1near = true;
			}
			if (t.getDestination() == farDest)
			{
				o1far = true;
			}
		}
		for (Transport t : transports2)
		{
			if (t.getDestination() == nearDest)
			{
				o2near = true;
			}
			if (t.getDestination() == farDest)
			{
				o2far = true;
			}
		}
		Assert.assertTrue("Origin1 should include near destination", o1near);
		Assert.assertTrue("Origin1 should include far destination", o1far);
		Assert.assertTrue("Origin2 should include near destination", o2near);
		Assert.assertTrue("Origin2 should include far destination", o2far);
	}

	@Test
	public void testExactSameCoordinatesFiltered()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"\t3100 3100 0\tLocation1\n"; // Exact same coordinates

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);

		// Should not create transport from location to itself
		Assert.assertTrue("Should not create transport to same location", transports.isEmpty());
	}

	@Test
	public void testLargeRadiusThreshold()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"3200 3200 0\t\tLocation2\n" +
			"\t3150 3150 0\tLocation1\n" + // Distance ~70
			"\t3400 3400 0\tLocation2\n"; // Distance much larger

		// Test with large radius threshold
		TransportLoader.addTransportsFromContents(transports, contents, TransportType.SPIRIT_TREE, 100);

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		// With large radius, only very far destinations should remain
		Assert.assertEquals("Origin 1 should have 1 transport (close one filtered)", 1, transports1.size());
		Assert.assertEquals("Origin 2 should have 1 transport (close one filtered)", 1, transports2.size());

		// Verify the remaining transport goes to the far destination
		Transport transport1 = getFirstTransport(transports1);
		int farDestination = WorldPointUtil.packWorldPoint(3400, 3400, 0);
		Assert.assertEquals("Should transport to far destination", farDestination, transport1.getDestination());
	}

	@Test
	public void testPermutationOnlyRowsAreIgnored()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"\t\tOnlyLabel\n"; // both origin and destination missing -> permutation-only

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);
		Assert.assertTrue("No transports should be created for permutation-only row", transports.isEmpty());
	}
}

package gps.transport;

import gps.transport.parser.TransportRecord;
import gps.transport.parser.TsvParser;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The optional Note column: a free-text advisory shown on the route step ("fire arrow needed",
 * "can fail") that must never gate the transport — it carries no requirement semantics, so a
 * noted transport stays exactly as routable as an un-noted one.
 */
public class TransportNoteTest
{
	private static final String HEADER =
		"# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tQuests\tVarbits\tVarPlayers\tDuration\tDisplay info\tNote\n";

	@Test
	public void noteColumnIsParsedAndExposed()
	{
		List<TransportRecord> records = new TsvParser().parse(HEADER
			+ "2446 3316 0\t2495 9716 0\tEnter Cave entrance 3213\t\t\t\t\t\t3\t\tfire arrow needed for the bridge ahead\n");
		Transport transport = new Transport(records.get(0), TransportType.TRANSPORT);
		assertEquals("fire arrow needed for the bridge ahead", transport.getNote());
	}

	@Test
	public void missingOrEmptyNoteIsNull()
	{
		// Short row (file without the column) and empty trailing column both mean "no note".
		List<TransportRecord> records = new TsvParser().parse(HEADER
			+ "2446 3316 0\t2495 9716 0\tEnter Cave entrance 3213\t\t\t\t\t\t3\t\n"
			+ "2446 3317 0\t2495 9717 0\tEnter Cave entrance 3213\t\t\t\t\t\t3\t\t\n");
		assertNull(new Transport(records.get(0), TransportType.TRANSPORT).getNote());
		assertNull(new Transport(records.get(1), TransportType.TRANSPORT).getNote());
	}

	@Test
	public void notedTransportCarriesNoRequirements()
	{
		List<TransportRecord> records = new TsvParser().parse(HEADER
			+ "2446 3316 0\t2495 9716 0\tCross Bridge 3254\t\t\t\t\t\t3\t\tbring a fire arrow\n");
		Transport transport = new Transport(records.get(0), TransportType.TRANSPORT);
		// Advisory only: no quests, no items, no skill levels appear because of a note.
		assertTrue(transport.getQuests().isEmpty());
		assertNull(transport.getItemRequirements());
		for (int level : transport.getSkillLevels())
		{
			assertEquals(0, level);
		}
	}
}

package gps.transport;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import gps.ShortestPathPlugin;
import gps.Util;
import gps.WorldPointUtil;
import gps.leagues.LeagueRegion;

/**
 * Unit tests for the per-transport seasonal-league region override
 * (column {@code Region override} in seasonal_transports.tsv). The
 * override replaces the chunk-classifier result for the destination
 * endpoint in
 * {@code PathfinderConfig.isTransportRegionAllowed(Transport)}.
 */
public class TransportRegionOverrideTest
{
	private Map<Integer, Set<Transport>> transports;

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
	}

	private Transport firstTransport(int origin)
	{
		Set<Transport> set = transports.get(origin);
		Assert.assertNotNull("Expected transports for origin " + origin, set);
		Assert.assertFalse("Transport set for origin " + origin + " should not be empty", set.isEmpty());
		return set.iterator().next();
	}

	// ── Builder parsing ───────────────────────────────────────────────

	@Test
	public void testBuilderAcceptsValidEnum()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("ASGARNIA")
			.build();
		Assert.assertEquals(LeagueRegion.ASGARNIA, t.getRegionOverride());
	}

	@Test
	public void testBuilderAcceptsLowercaseAndWhitespace()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("  kandarin  ")
			.build();
		Assert.assertEquals(LeagueRegion.KANDARIN, t.getRegionOverride());
	}

	@Test
	public void testBuilderNullValueLeavesOverrideUnset()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride((String) null)
			.build();
		Assert.assertNull(t.getRegionOverride());
	}

	@Test
	public void testBuilderEmptyValueLeavesOverrideUnset()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("")
			.build();
		Assert.assertNull(t.getRegionOverride());
	}

	@Test
	public void testBuilderInvalidValueLeavesOverrideUnset()
	{
		// Unknown enum name is logged and silently ignored so a single
		// malformed row does not break the whole TSV load.
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("NOT_A_REGION")
			.build();
		Assert.assertNull(t.getRegionOverride());
	}

	// ── TSV round-trip ────────────────────────────────────────────────

	@Test
	public void testTsvRoundTripPopulatesOverride()
	{
		String contents = "# Origin\tDestination\tDuration\tRegion override\n" +
			"3200 3200 0\t3300 3300 0\t5\tVARLAMORE\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport t = firstTransport(origin);
		Assert.assertEquals(LeagueRegion.VARLAMORE, t.getRegionOverride());
	}

	@Test
	public void testTsvRoundTripWithoutOverrideLeavesNull()
	{
		String contents = "# Origin\tDestination\tDuration\tRegion override\n" +
			"3200 3200 0\t3300 3300 0\t5\t\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport t = firstTransport(origin);
		Assert.assertNull(t.getRegionOverride());
	}

	@Test
	public void testTsvRoundTripWithoutColumnLeavesNull()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"3200 3200 0\t3300 3300 0\t5\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport t = firstTransport(origin);
		Assert.assertNull(t.getRegionOverride());
	}

	// ── Real seasonal_transports.tsv resource ─────────────────────────

	/**
	 * Locks in the active set of per-row overrides shipped with the
	 * plugin. The bbox classifier in leagues_regions.tsv is the source
	 * of truth; any chunk that still disagrees with the wiki keeps an
	 * override here. Adjust the expected map when adding, removing, or
	 * relocating an override and document the reason in the TSV.
	 */
	@Test
	public void testSeasonalTransportsResourceCarriesDocumentedOverrides() throws IOException
	{
		Map<Integer, LeagueRegion> expected = new HashMap<>();
		// Banker's Briefcase: Aldarin — chunk cx=23 cy=53 is Kourend
		// (Land's End shoreline), wiki lists destination under Varlamore.
		expected.put(WorldPointUtil.packWorldPoint(1502, 3410, 0), LeagueRegion.VARLAMORE);
		// Map of Alacrity: Trollheim Wilderness climb — chunk cx=46
		// cy=57 is Wilderness, wiki lists destination under Asgarnia.
		expected.put(WorldPointUtil.packWorldPoint(2946, 3678, 0), LeagueRegion.ASGARNIA);
		// Fairy Mushroom: AIR (SE of Ardougne) — chunk cx=42 cy=50 is
		// Karamja (Brimhaven east), wiki lists destination under Kandarin.
		expected.put(WorldPointUtil.packWorldPoint(2700, 3247, 0), LeagueRegion.KANDARIN);
		// Map of Alacrity: Barbarian Outpost Basalt causeway — chunk
		// cx=39 cy=56 stays FREMENNIK because the Lighthouse dominates
		// the chunk; the Basalt causeway is listed under Kandarin on
		// the league wiki and so carries a per-row override.
		expected.put(WorldPointUtil.packWorldPoint(2522, 3595, 0), LeagueRegion.KANDARIN);
		// Map of Alacrity: Sinclair Mansion Log balance — chunk cx=42
		// cy=56 is FREMENNIK; the destination is listed under Kandarin
		// on the league wiki and so carries a per-row override.
		expected.put(WorldPointUtil.packWorldPoint(2722, 3592, 0), LeagueRegion.KANDARIN);
		// Fairy Mushroom: DLR (Poison Waste south of Isafdar) — chunk
		// cx=34 cy=48 is Tirannwn, wiki lists destination under Kandarin.
		expected.put(WorldPointUtil.packWorldPoint(2213, 3099, 0), LeagueRegion.KANDARIN);

		Map<Integer, LeagueRegion> seen = new HashMap<>();
		for (Set<Transport> set : loadSeasonalTransports().values())
		{
			for (Transport t : set)
			{
				if (t.getRegionOverride() != null)
				{
					seen.put(t.getDestination(), t.getRegionOverride());
				}
			}
		}

		Assert.assertEquals(
			"Active region overrides drifted from documented set — update both this test "
				+ "and the in-file comments when changing the override list.",
			expected, seen);
	}

	private Map<Integer, Set<Transport>> loadSeasonalTransports() throws IOException
	{
		Map<Integer, Set<Transport>> loaded = new HashMap<>();
		try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(
			"/transports/seasonal_transports.tsv"))
		{
			String contents = new String(
				Util.readAllBytes(Objects.requireNonNull(in)),
				StandardCharsets.UTF_8);
			TransportLoader.addTransportsFromContents(
				loaded, contents, TransportType.SEASONAL_TRANSPORTS, 0);
		}
		return loaded;
	}
}

package gps.transport;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportationItem;

/**
 * Tests for TransportTypeConfig.
 * These tests ensure that the functional getter mechanism works correctly and
 * that
 * all config getters defined in TransportType work with ShortestPathConfig.
 */
@RunWith(MockitoJUnitRunner.class)
public class TransportTypeConfigTest
{

	@Mock
	ShortestPathConfig config;

	/**
	 * Verifies that every enabledGetter defined in TransportType returns a boolean
	 * when applied to a config object.
	 */
	@Test
	public void testAllEnabledGettersReturnBoolean()
	{
		setupDefaultMocks();

		List<String> errors = new ArrayList<>();

		for (TransportType type : TransportType.values())
		{
			Function<ShortestPathConfig, Boolean> getter = type.getEnabledGetter();
			if (getter == null)
			{
				continue; // No enabled getter for this type, skip
			}

			try
			{
				Boolean result = getter.apply(config);
				assertNotNull("enabledGetter for " + type.name() + " should not return null", result);
			}
			catch (Exception e)
			{
				errors.add(String.format("%s: %s", type.name(), e.getMessage()));
			}
		}

		if (!errors.isEmpty())
		{
			fail("Errors invoking enabledGetters:\n  " + String.join("\n  ", errors));
		}
	}

	/**
	 * Verifies that every costGetter defined in TransportType returns an integer
	 * when applied to a config object.
	 */
	@Test
	public void testAllCostGettersReturnInteger()
	{
		setupDefaultMocks();

		List<String> errors = new ArrayList<>();

		for (TransportType type : TransportType.values())
		{
			Function<ShortestPathConfig, Integer> getter = type.getCostGetter();
			if (getter == null)
			{
				continue; // No cost getter for this type, skip
			}

			try
			{
				Integer result = getter.apply(config);
				assertNotNull("costGetter for " + type.name() + " should not return null", result);
			}
			catch (Exception e)
			{
				errors.add(String.format("%s: %s", type.name(), e.getMessage()));
			}
		}

		if (!errors.isEmpty())
		{
			fail("Errors invoking costGetters:\n  " + String.join("\n  ", errors));
		}
	}

	/**
	 * Verifies that TransportTypeConfig can be constructed and refreshed without
	 * exceptions.
	 */
	@Test
	public void testTransportTypeConfigConstruction()
	{
		// Setup default returns for all config methods
		setupDefaultMocks();

		// Should not throw
		TransportTypeConfig typeConfig = new TransportTypeConfig(config);
		assertNotNull(typeConfig);
	}

	/**
	 * Verifies that isEnabled returns the correct value based on mocked config.
	 */
	@Test
	public void testIsEnabledReturnsConfigValue()
	{
		// Setup default mocks first, then override specific values
		setupDefaultMocks();
		when(config.useSailing()).thenReturn(false);

		TransportTypeConfig typeConfig = new TransportTypeConfig(config);

		assertTrue("AGILITY_SHORTCUT has no toggle: always enabled",
			typeConfig.isEnabled(TransportType.AGILITY_SHORTCUT));
		assertFalse("SAILING should be disabled",
			typeConfig.isEnabled(TransportType.SAILING));
		assertTrue("BOAT should be enabled",
			typeConfig.isEnabled(TransportType.BOAT));
	}

	/**
	 * Verifies that types without configKey are enabled based on TeleportationItem
	 * setting.
	 * TELEPORTATION_ITEM and TELEPORTATION_BOX are controlled by
	 * useTeleportationItems config.
	 */
	@Test
	public void testTypesWithoutConfigKeyAreEnabled()
	{
		setupDefaultMocks();
		// When TeleportationItem is not NONE, teleport item types should be enabled
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);

		TransportTypeConfig typeConfig = new TransportTypeConfig(config);

		// TRANSPORT has no configKey, should always be enabled
		assertTrue("TRANSPORT (no configKey) should be enabled",
			typeConfig.isEnabled(TransportType.TRANSPORT));

		// TELEPORTATION_ITEM should be enabled when TeleportationItem != NONE
